INSERT INTO `food` VALUES (4,'妈妈牌健康午餐肉 好吃到没朋友','荤菜','蘑菇#\n鸡蛋#\n洋葱#\n瘦肉沫#\n胡萝卜#\n蛋清#\n米饭#\n玉米淀粉#','5克#\n1个#\n5克#\n100克#\n10克#\n1个#\n15克#\n8克#','1. 将蘑菇切丁，洋葱同样切丁#\n2. 放入剁好的肉末中，加入一个蛋清，玉米淀粉，搅拌上劲#\n3. 将搅拌上劲后的肉末倒入方形碗中，用手铺平后盖上保鲜膜#\n4. 放入蒸锅中，蒸15分钟#\n5. 将胡萝卜切丁，青菜切碎#\n6. 放入米饭中，打入一个鸡蛋，搅拌均匀#\n7. 取出做好的午餐肉，在上面倒入拌好的蛋液#\n8. 盖上保鲜膜，放入蒸锅中，再蒸8分钟，直至蛋液凝固#\n9. 切成一块一块，就大功告成啦！#\n10. 摆盘、完成#'),(5,'家常炸酱面','主食','五花肉 （去皮，切丁）#\n香菇（泡发，切丁）#\n一根葱#\n姜末#\n蒜末#\n新鲜小黄瓜 切丝#\n胡萝卜 切丝#\n干黄酱 （我用了Miso）#\n甜面酱#\n糖#','300 克#\n6-8朵#\n#\n1 小勺#\n1 小勺#\n1/4 根#\n1/2 根#\n1 大勺#\n1 大勺#\n1 小勺#','1. 把所有材料准备好。#\n2. 锅里下一小勺的油，把肉丁煸炒至变色，油开始溢出时#\n3. 加入葱蒜姜末，炒香。加入香菇丁，炒香。#\n4. 把干黄酱/Miso和甜面酱加水调匀，倒入锅里炒至酱香味溢出，加入糖调味。#\n5. 加两杯水没过肉丁，大火煮滚然后小火熬煮大约45分钟，间中搅拌几次，防止粘锅.熬至酱汁浓稠即可。#\n6. 熬制好的炸酱特别香！#\n7. 熬肉时把黄瓜和胡萝卜切丝，炸酱面的黄瓜丝一定要用切的，擦丝器擦出来的黄瓜口感没有切出来的清爽脆口。把新鲜面条煮熟，摆到碗里，加上菜码和炸酱，拌匀，开吃！#'),(6,'超简单省事咖喱饭','主食','土豆#\n胡萝卜#\n洋葱#\n牛肉#\n咖喱块#','1个#\n1个#\n1个#\n#\n#','1. 材料切块#\n2. 油热后，放入蒜花椒#\n3. 放入材料炒#\n4. 同时炖肉#\n5. 半熟时，连汤带肉一起倒到锅里#\n6. 放入咖喱块，根据自己的口味放 ，我一般放2块#\n7. 加盐（个人口味比较重）#\n8. 盖上锅盖，慢炖收汁#\n9. 盛米#\n10. 关火#\n11. 上盘#'),(7,'孜然香烤豆腐','素菜','北豆腐#\n生抽#\n孜然#\n辣椒粉#\n熟芝麻#\n椒盐#','500克#\n50克#\n适量#\n适量#\n10克#\n少许#','1. 准备好原材料。#\n2. 豆腐切成七八毫米厚的长方形块。#\n3. 碗里倒入生抽#\n4. 加入熟芝麻、孜然、辣椒粉、椒盐，调成调味汁。#\n5. 豆腐摆放到铺好油纸的烤盘上，表面刷上调味汁，稍微多刷一点，然后用叉子在豆腐上挨着插一些小孔，使豆腐入味。#\n6. 放入预热的烤箱中层，上下火，230度，15分钟左右。#\n7. 取出翻一面，再刷上薄薄一层调味汁，放入烤箱再烤十来分钟即可。#\n8. 成品图。#\n9. 成品图。#\n10. 成品图。#'),(8,'果蔬沙拉','素菜','生菜#\n苹果#\n梨#\n草莓#\n熟鸡蛋#\n红萝卜#\n黄瓜#\n坚果#\n黑芝麻#\n沙拉酱#','30g#\n1个#\n1个#\n50g#\n2个#\n50g#\n半根#\n适量#\n适量#\n适量#','1. 准备食材#\n2. 生菜撕小块#\n3. 草莓一切两半#\n4. 黄瓜切片#\n5. 红萝卜切片#\n6. 坚果一切两半#\n7. 苹果去皮切滚刀块。#\n8. 梨切小块#\n9. 鸡蛋切小块#\n10. 所有食材放入碗内，撒黑芝麻，拌入沙拉酱即可。#'),(9,'金牌BBQ烤鱿鱼筒','荤菜','冰冻鱿鱼#\n金牌BBQ烤肉料#\n花生油#\n柠檬片#\n薄荷叶#','394克#\n20克#\n1小勺#\n1片#\n1朵#','1. 鱿鱼解冻、清洗、弄干水分。#\n2. 加入20克BBQ烤肉料。#\n3. 戴一次性手套抓均匀，再加入花生油，腌制一会，同时预热烤箱，200度，上下火，热风循环。#\n4. 腌制好的鱿鱼放入垫锡纸的烤盘里。#\n5. 连烤盘一起送入烤箱，烤15分钟，烤完戴隔热手套趁热取出。#\n6. 用干净的夹肉夹子夹住、厨房剪刀剪成一圈圈，须则竖着剪成一条条，摆盘，浇上烤汁，柠檬片和薄荷叶伴碟。#\n7. 成品。#'),(11,'酸汤麻辣小面—迷迭香','主食','辣椒油#\n花椒油#\n辣椒碎#\n蒜泥#\n醋#\n生抽#\n白芝麻#\n盐#','1 勺#\n1勺#\n1勺#\n1 勺#\n1 勺#\n1 勺#\n1 勺#\n1 茶匙#','1. 面条、辣椒油、花椒油、醋、生抽等备料#\n2. 蒜切末、青菜掰青菜叶#\n3. 辣椒油、辣椒面、花椒油、醋、生抽、白芝麻拌匀#\n4. 热水下面条，中间加一点冷水后加入青菜煮沸#\n5.  煮好盛到调好汁儿的碗里，洒上蒜泥、红米椒，尽情享用吧。#'),(14,'凉拌菜豆笋（腐竹）','素菜','腐竹#\n辣椒油#\n蒜#\n葱#\n辣椒粉#','150g#\n#\n#\n#\n#','1. 冷水泡软（大概2个小时），夏天中途换一下水#\n2. 切段、水煮至熟透，捞出沥干水#\n3. 大蒜切末、准备辣椒粉（有辣椒油可以直接放辣椒油）、葱花#\n4. 放入蒜末、葱花、辣椒粉（若有油泼辣子直接放即可）#\n5. 热油#\n6. 热油淋上去#\n7. 放少许白糖、盐（放一点点就可以了）、生抽、酱油、醋、芝麻油（可以再放点蚝油、味精，不喜欢则不放）#\n8. 我没有油泼辣子放了点辣椒酱（颜色有点重）#\n9. 装盘#\n10. 最后散上点葱花点缀、味道还不错呢#'),(15,'饭合 | 橙味鸭胸','主食','鸭胸肉#\n小番茄#\n茴香头#\n橙子#\n盐#\n黑胡椒#\n橄榄油#\n意大利黑醋#\n五香粉#\n大蒜#\n姜片#','400g#\n100g#\n120g#\n1个#\n30g#\n少许#\n1勺#\n1勺#\n少许#\n5瓣#\n5片#','1. 在鸭皮上轻划出十字花纹#\n2. 将橙皮挤汁涂抹在鸭肉表面#\n3. 撒上盐、黑胡椒、五香粉。大蒜拍碎、姜切片放与花刀面，腌制30分钟#\n4. 将切好的小番茄、茴香头、橙肉放入碗中，并加入少许意大利黑醋、橄榄油、黑胡椒搅拌均匀#\n5. 平底锅不放油，将鸭皮煎出多余油脂并放入腌制辅料，烹饪10-15分钟#\n6. 鸭肉切好，与时蔬沙拉摆盘即可#'),(16,'红酒香煎龙利鱼','荤菜','龙利鱼#\n洋葱#\n香葱#\n柠檬#\n指天椒#\n红酒#\n黑胡椒#\n白糖#\n料酒#\n酱油#\n蚝油#\n姜水#\n淀粉#','250g#\n半个#\n1个#\n1个#\n2个#\n3勺#\n根据个人口味#\n半勺#\n1勺#\n1勺#\n半勺#\n1勺#\n能沾满龙利鱼的量即可#','1. 食材清洗干净，将除黑胡椒外所有调味料调和成酱汁#\n2. 葱切碎、指天椒切段、柠檬切成两半。龙利鱼切成两段，洋葱切碎，把酱汁倒入盘中，与洋葱龙利鱼均匀混合。#\n3. 美的电饼铛双面预热，龙利鱼从酱汁中取出，两面均匀沾满淀粉，电饼铛预热结束后放入龙利鱼#\n4. 调到烧烤模式，等待一分钟#\n5. 倒入盘中的汤汁跟洋葱，倒入半杯红酒，扣盖，等待一分钟#\n6. 出锅，撒上黑胡椒、香葱、指天椒即可，食用前记得淋上柠檬汁哦#'),(17,'?夏至粥?','主食','小米#\n荞麦#\n红豆#\n糯米#\n燕麦#\n薏米#\n大红豆#\n芸豆#\n糙米#\n绿豆#\n大米#\n白糖#\n小米#','150g#\n100g#\n100g#\n100g#\n100g#\n100g#\n100g#\n100g#\n100g#\n100g#\n100g#\n适量#\n100g#','1. 配料洗净后，硬的大的豆要隔夜煮一煮泡水里，其他可以不煮泡水里，早上电饭煲直接定时开始煮粥模式#\n2. 煮好后放入适量白糖，切记不要早放，不然豆不容易煮烂#\n3. 装碗就可以分给家人吃啦！#'),(19,'丝瓜鲜虾盅#元气挑战美一天#','荤菜','鲜虾#\n丝瓜#\n剁椒（不吃辣就不放）#\n生抽#\n蚝油#\n香油#\n白糖#\n料酒#\n盐#','8只#\n1根#\n一小勺#\n1小勺#\n半勺#\n几滴#\n适量#\n少许#\n少许#','1. 准备好需要的食材。鲜虾去皮去虾线，用少许盐和料酒抓匀。#\n2. 丝瓜去皮，切均匀的丝瓜段。#\n3. 用勺子把挖掉丝瓜的一部分瓤。#\n4. 用小刀在顶部的丝瓜，切斜刀划出小花边。#\n5. 卷起虾肉，塞进处理好的丝瓜盅里。#\n6. 依次都这样做好。#\n7. 放一点剁椒很好吃，如果不吃辣就不放。用糖、生抽、蚝油、香油做一碗调味汁。倒入丝瓜盅的盘子里。#\n8. 将盘子放入美的蒸汽炉，预热好后蒸5分钟即可。焖1分钟再出锅。#\n9. 取出即可食用。很清爽的口感哦。#'),(23,'葱油淋杏鲍菇','素菜','生姜#\n葱末#\n小米椒#\n生抽#\n蚝油#\n食用油#','40g#\n40g#\n6-7只#\n1勺#\n1.5勺#\n60g#','1. 杏鲍菇洗净，切片不要太薄，大约4毫米#\n2. 水开后倒入切好的杏鲍菇加1/3茶匙盐煮2分钟左右，变软就可以了#\n3. 浸泡在冷水里备用#\n4. 接下来做葱油淋酱。葱姜小米椒切碎，准备生抽和蚝油#\n5. 倒入碗中，取不粘锅，锅内热油#\n6. 将油淋在酱料上，油尽量浇均匀#\n7. 葱油淋酱就做好了，你喜欢吃的食材，大多都能用葱油淋酱来拌#\n8. 把杏鲍菇码成一圈#\n9. 淋上酱汁就可以吃啦#'),(24,'山药木耳炒肉丝','荤菜','山药#\n肉丝#\n木耳#\n葱姜#\n青红椒#\n生抽#\n老抽#\n料酒#','半斤#\n一两#\n适量#\n适量#\n各一个#\n一勺#\n一滴#\n半勺#','1. 木耳泡发好，青红椒切小片备用#\n2. 山药切片或者条状，夏天山药容易变色，用热水加盐泡着备用#\n3. 肉丝切好，葱花姜丝切好备用#\n4. 锅里油热下葱姜爆香下肉丝翻炒#\n5. 加一滴老抽上色，加料酒去肉丝腥味#\n6. 山药，木耳青红椒下锅和肉丝一块翻炒均匀，如果觉得太干可以加一小勺水，略煮至山药熟了，加生抽提味，加盐翻炒均匀就可以了。如果口味重觉得不鲜就加点鸡粉调味。我个人觉得还是少吃味精，鸡精好。#\n7. 翻炒均匀就可以装盘了#\n8. 看，是不是很有食欲呢#'),(25,'蚝油牛肉#美的微波炉菜谱#','荤菜','A牛肉#\nB洋葱#\nB青椒#\nB胡萝卜#\nB食用油#\nA姜#\nA生粉#\nA食用油（步骤3）#\nA盐#\nA料酒#\nA生抽#\nA蚝油#\nA姜末#\nA蒜瓣#','220g#\n50g#\n50g#\n35g#\n1勺#\n#\n1勺#\n2勺#\n1/3茶匙#\n1茶匙#\n1勺#\n3勺#\n少许#\n少许#','1. 牛肉与蔬菜切片#\n2. 牛肉与A部分辅料混合抓拌均匀#\n3. 盘底倒油2勺高火预热3分钟，放入拌好的牛肉，加盖高火p100烹调4分钟九成熟取出备用#\n4. 将蔬菜用1勺食用油拌匀，高火p100烹调3分钟取出#\n5. 与九成熟牛肉混合均匀高火p100烹调3分钟即可#'),(26,'番茄牛肉浓汤【九阳破壁豆浆机Q1】','荤菜','牛肉#\n西红柿#\n胡萝卜#\n洋葱#\n土豆#\n白胡椒#\n葱#\n姜#\n番茄酱#\n盐#\n橄榄油#\n香草#','500g#\n240g#\n80g#\n150g#\n160g#\n适量#\n1段#\n1片#\n30g#\n适量#\n适量#\n适量#','1. 所有材料。#\n2. 牛肉浸泡去血水后放锅中，放入葱姜，煮开后撇去沫子，煮到筷子能轻松扎透。#\n3. 所有材料都切碎备用，煮牛肉的汤也留着备用。#\n4. 将1杯胡萝卜、1杯洋葱、1杯土豆、2杯西红柿、放入九阳破壁豆浆机中，加入牛肉汤。#\n5. 插好电源，按冷饮区，选择精力汤功能。#\n6. 炒锅放入少量橄榄油，将剩余的蔬菜材料放入煸炒，加入番茄酱。#\n7. 打好的精力汤倒入锅中，放入炒好的菜和牛肉块，炖煮20分钟左右，调入盐、白胡椒和香草即可。#\n8. 成品。#'),(27,'糖醋排骨','荤菜','小排#\n冰糖#\n生抽#\n黄酒#\n葱#\n姜#\n八角#\n桂皮#\n细砂糖#\n康乐醋#\n白芝麻#','400g#\n20g#\n一勺#\n2勺#\n少许#\n少许#\n一粒#\n一块#\n两勺#\n3勺#\n少许#','1. 约15g水和冰糖放入锅中小火熬煮。#\n2. 熬煮到糖融化成金黄色（请原谅我的图拍糊了）加入少许开水搅匀盛出。#\n3. 熬制好的糖水备用。#\n4. 锅里放少许油烧热。#\n5. 放入洗干净的小排翻炒约五分钟。#\n6. 放入生抽，黄酒、葱、姜、八角翻炒约三分钟。#\n7. 倒入煮好的糖水，加入开水没过排骨。#\n8. 加入桂皮盖上锅盖小火慢炖40分钟。#\n9. 最后大火收汁，当汁快收好时加入两勺细砂糖，三勺康乐醋收汁出锅。摆盘后撒上芝麻会更好看哦！#'),(29,'干锅花菜｜美食台','素菜','有机花菜#\n五花肉#\n红尖椒#\n芹菜#\n花椒#\n干辣椒#\n姜#\n蒜#\n糖#\n生抽#\n老抽#','1棵#\n100克#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 将洗净的花菜拆成小朵；五花肉切薄片；姜、蒜切片，干辣椒切段，红尖椒、芹菜切段备用；#\n2. 然后用老抽、生抽、糖调一个汁，三种调料的比例为1︰4︰1；#\n3. 热锅冷油，姜片、蒜片取一半倒入锅中，然后放入五花肉片煸炒，待肉炒至变色，再倒入剩余的姜片、蒜片和花椒、干辣椒段煸香；#\n4. 等五花肉的油炒出来后，加入花菜，调大火炒匀，一直炒到花菜的水分出来，颜色变深；#\n5. 然后放入尖椒段、芹菜段，倒入调味汁烧片刻，收汁即可。#\n6. 装盘，完成！#'),(30,'冷面','主食','煎鸡蛋#\n胡萝卜#\n青瓜#\n火腿肠#\n腐竹#\n菇#\n葱丝#\n酱汁#\n生抽#\n香醋#\n辣椒面#\n香油#','一颗#\n10g#\n10g#\n一根#\n一条#\n10g#\n少许#\n#\n一勺#\n一小勺#\n一小勺#\n少许#','1. 腐竹浸泡水里让其变软，和菇一起放开水里捞一遍备用。把其他食材全部设成丝。#\n2. 水烧开，放入荞麦面，煮到熟捞起。#\n3. 放到冷开水里过两遍。#\n4. 碗里装半碗的鸡汤#\n5. 把做好的荞麦面放入碗里#\n6. 把所有切好的食材摆入荞麦面上。#\n7. 调点酱汁淋上就可以了(生抽，辣椒面，香油，香醋)#\n8. 稍微拌一拌就可以吃啦！好美味！#'),(31,'米饭绝配-私房香辣豆腐','素菜','大豆腐#\n干辣椒#\n大葱#\n姜#\n大蒜#\n盐#\n十三香#\n酱油#\n淀粉#\n水#','1块#\n3-4根#\n适量#\n2-3片#\n4-5粒#\n适量#\n大半调料勺#\n3羹匙#\n3羹匙#\n大半碗#','1. 选卤水豆腐一块。#\n2. 豆腐切块。#\n3. 平底锅冷锅冷油，摆好豆腐，开大火煎至两面金黄。#\n4. 煎豆腐时不加锅盖，且不宜煎过久。#\n5. 煎豆腐时准备葱姜蒜及水淀粉。#\n6. 另起锅，煸炒辣椒段后下葱姜蒜和酱油爆锅。#\n7. 倒入煎好的豆腐，加盐、十三香后翻炒。#\n8. 加入水淀粉翻炒收汁。#\n9. 加入葱丝翻炒。#\n10. 加入味精后出锅装盘。#'),(32,'炝炒土豆丝','素菜','土豆#\n红美人椒#\n青椒#','4个#\n3个#\n2个#','1. 土豆削皮，辣椒洗净备用#\n2. 土豆，辣椒切丝。不用切的那么细。家里吃的不需要那么麻烦，尽量粗细一样，受热均匀#\n3. 锅里油烧热，放入土豆丝大火爆炒，无需放水，锅里油稍微多点，不会沾锅。#\n4. 放入盐，糖调味。土豆丝变软了就可以出锅啦#\n5. 家常土豆丝就是这么简单任性#\n6. 最简单的食材，最原始的味道，就是念家的味道了吧#'),(33,'南瓜腊肠焖饭#美的初心电饭煲#','主食','大米#\n腊肠#\n南瓜#\n杏鲍菇#\n姜#\n盐#\n胡椒粉#\n生抽#','200克#\n400克#\n350克#\n300克#\n10克#\n2克#\n2克#\n20毫升#','1.  准备食材：川味腊肠份量挺多的，姜剁成姜茸#\n2. 大米洗净提前浸泡，浸泡1小时#\n3. 腊肠切丁#\n4.  杏鲍菇切丁#\n5. 南瓜削皮后切丁#\n6. 炒锅烧热油，爆香姜茸，放入腊肠翻炒#\n7. 放入杏鲍菇丁翻炒#\n8.  再放入南瓜丁，翻炒#\n9. 大米倒出浸泡水，加入炒锅里的所有食材，放盐、生抽和胡椒粉拌匀，加入没过食材的水量#\n10. 用电饭煲的煮饭功能煮饭#\n11. 电饭锅工作完毕，香喷喷的南瓜腊肠饭就做好了#\n12. 盛饭后可以撒些葱粒#'),(36,'饭合|豉汁排骨','主食','猪肋排#\n豆豉切碎#\n蒜头切碎#\n姜切碎#\n红辣椒切小段#\n上海青#\n盐#\n黑胡椒#\n酱油#\n绍兴酒#\n白酒#\n蚝油#\n砂糖#\n淀粉#\n油#','800g#\n1.5大匙#\n1瓣#\n2大匙#\n少许#\n5根#\n1/4小匙#\n少许#\n1.5大匙#\n2大匙#\n1/3杯#\n1/2大匙#\n1/2大匙#\n1小匙#\n1小匙#','1. 猪肋排汆烫洗净后吸除多余水分，加盐和黑胡椒静置10分钟。#\n2. 油倒入锅中，上海青过油略炒，加入盐和两大匙的水，并盖上锅盖蒸两分钟，取出菜叶并将水倒掉。#\n3. 将酱油、切碎的豆豉、绍兴酒、白酒、蚝油、砂糖、蒜、姜、红辣椒、淀粉调成汁倒入腌制后的猪肋排，搅拌均匀。中火，滚煮后盖上锅盖改小火煮20分钟后关火，焖放10-20分钟。#\n4. 大火收汁加入烫好的青菜，即可装盘。#'),(38,'鱼排','荤菜','白鱼#\n黑胡椒粉#\n盐#\n柠檬汁#\n蚝油#\n面包糠#\n油#\n蒜#','4条#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 鱼肉化冻，然后用刀轻轻在表面斜切出菱形纹路，方便腌制时入味#\n2. 在鱼上均匀抹上胡椒粉，盐，柠檬汁和蚝油腌制大约15分钟，注意盐不要加多了。在腌鱼的时候，我们剁蒜蓉，并将其和油一起混入面包糠#\n3. 腌好的鱼裹上面包糠，200度上下火烤20分钟#\n4. 对比一下，烤好的鱼小了好多啊！#'),(40,'迷迭香—油焖大虾','荤菜','葱#\n姜#\n蒜#\n番茄酱#\n料酒#\n生抽#\n盐#\n白糖#','1根#\n2片#\n3瓣#\n1勺#\n1勺#\n1勺#\n1茶匙#\n2茶匙#','1. 对虾、葱花、姜末、蒜末、番茄酱、生抽等备用#\n2. 对虾剪掉须和爪开背挑出虾线黑线，清洗干净控净水分备用#\n3. 锅中倒油，油热至六七成时倒入虾#\n4. 翻炒均匀，待虾颜色变红立即盛出备用#\n5. 留下锅中油烧热，倒入姜蒜末爆香#\n6. 倒入番茄酱，翻炒成汁儿#\n7. 接着倒入炒好的虾#\n8. 沿锅边依次倒入料酒、生抽、白糖#\n9. 炒匀后，倒入小半碗热水，烧开后盖盖儿小火焖2分钟#\n10. 再加入葱末和盐#\n11. 大火收汁儿#\n12. 终于可以开动喽#'),(42,'? 玫瑰腐乳肉 ?','荤菜','五花肉#\n玫瑰腐乳#\n啤酒#\n姜#\n生抽#\n冰糖#\n红曲粉#','500克#\n2块#\n1锅铲#\n1块#\n半锅铲#\n1块#\n少许#','1. 五花肉切方块。今天买的五花肉特别肥厚～用小勺将腐乳碾碎和腐乳汁搅拌成腐乳汁。#\n2. 起油锅，小火将五花肉炸出油份，肉表面变色即可。#\n3. 倒入啤酒。#\n4. 倒入腐乳汁和生抽翻炒均匀。#\n5. 加入热水没过五花肉。放入冰糖，红曲粉，煮开后转中火煮至汤汁浓稠。#\n6. 肥的流油，但是很香。#'),(43,'迷迭香美食| 番茄牛腩煲','荤菜','牛腩#\n西红柿#\n小葱#\n生抽#\n老抽#\n料酒#\n香叶#\n八角#\n姜#\n香菜#\n盐#','1斤#\n2个#\n4根#\n1勺#\n1勺#\n1勺#\n5片#\n6个#\n1块#\n1小把#\n少许#','1. 牛腩、西红柿、葱、姜、八角、香叶等备料#\n2. 开水汆烫一下西红柿，去皮#\n3. 西红柿切块#\n4. 牛腩冷水焯水#\n5. 姜切片#\n6. 给煲中倒入牛腩，加上水，水淹没牛腩即可#\n7. 加一勺料酒，一勺生抽，一勺老抽#\n8. 接着加入八角，香叶，姜片，小葱#\n9. 大火煮沸后调小火炖牛腩约1小时，倒入西红柿继续炖#\n10. 20分钟后再加入部分西红柿，并加入盐#\n11. 出锅时加一点点香菜，完成#'),(45,'超下饭肉末茄子','荤菜','茄子#\n肉末#\n猪油#\n盐，糖，味精，#\n葱姜蒜#\n小香葱#\n老抽，生抽，料酒#','半根#\n一小把#\n一小碗#\n适量#\n若干#\n一小把#\n适量#','1. 茄子切滚刀块，把一小碗猪油倒锅里小火把茄子煎微黄#\n2. 用锅铲试试茄子软了以后把葱姜蒜放锅里开大火煸炒，加入肉末，肉末炒变色后加入开水#\n3. 开水漫过茄子，一直大火，加入盐糖味精料酒调味，生抽少放点太咸，老抽调色，盖上锅盖大火一直烧个五分钟的样子把锅盖打开收汁，尝味道，缺什么加什么，我做的甜咸鲜口的，所以糖会多点#\n4. 收汁后盛出，把小香葱切碎撒上完事！盛一碗大米饭开吃吧#'),(46,'剁椒金针菇龙利鱼','荤菜','龙利鱼#\n金针菇#\n剁椒#\n姜丝#\n葱末#','300g#\n150g#\n#\n#\n#','1. 龙利鱼竖切一刀，横切成一厘米左右的宽条#\n2. 金针菇洗净#\n3. 在盘子底部铺上金针菇，然后依次铺上龙利鱼，姜丝、剁椒#\n4. 在盘子底部铺上金针菇，然后依次铺上龙利鱼，姜丝、剁椒#\n5. 水煮开后，将盘子放入蒸锅，大火蒸6-8分钟。#\n6. 水煮开后，将盘子放入蒸锅，大火蒸6-8分钟。#\n7. 将盘内多余水分沥出，保留约一半的汤汁即可#\n8. 加入生抽，撒上葱花#\n9. 锅内下油，待油温9成热时，淋在鱼上即可。#\n10. 鲜嫩的鱼肉，充分吸收了汤汁的金针菇，好好吃！#'),(47,'木耳肉末汤','汤','木耳#\n肉末#\n蒜蓉#\n葱段#\n盐和鸡精#','适量#\n适量#\n适量#\n适量#\n调味#','1. 木耳提前浸泡，蒜蓉，和葱花备好#\n2. 肉末提前用盐，蚝油，鸡精，胡椒粉，玉米淀粉腌盐#\n3. 锅里加适量植物油，加入蒜蓉，葱花炒香#\n4. 木耳翻炒上油#\n5. 已上油的木耳#\n6. 加入适量肉末#\n7. 加入适量的水#\n8. 盖上锅盖大火煮开转文火煮30分钟#\n9. 煮好的汤加入适量盐和鸡精调味#\n10. 简单美味的木耳汤#\n11. 多吃木耳身体好^_^#'),(48,'香煎杂蔬饼','素菜','土豆#\n胡萝卜#\n木耳#\n生菜#\n辣椒面#\n花椒#\n盐#\n生抽#','1小个#\n半根#\n五朵#\n三片#\n适量#\n六颗#\n适量#\n适量#','1. 土豆，胡萝卜，木耳，生菜切丝，切得细一点#\n2. 放入面粉，辣椒面，花椒，生抽，盐，适量的水，搅拌均匀#\n3. 成糊状#\n4. 倒入油，喜欢吃糊一点的，就开中火转小火，慢慢煎#\n5. 成盘#'),(49,'虾仁炒芹菜','荤菜','虾仁#\n芹菜#\n姜#\n料酒#\n盐#\n白糖#\n淀粉#\n白胡椒粉#','150g—200g#\n半根#\n适量#\n适量#\n少许#\n一小勺#\n一小勺#\n两小勺#','1. 虾仁去黑线洗净#\n2. 芹菜洗净切斜段#\n3. 将控净水的虾仁里加入白胡椒粉.料酒.淀粉姜丝，拌均腌制5—10分钟#\n4. 待水开加半小勺盐.几滴油，再放入切好的芹菜水开片刻捞出#\n5. 起油锅，热锅凉油，且不要多，油热后把腌好的虾仁放入后开大火快速翻炒，待虾仁卷起，变色后盛出#\n6. 将锅洗净，再起油锅，待油热后翻炒几下#\n7. 加入炒过的虾仁，依次放入盐.白糖，清爽的虾仁芹菜可以享用了#\n8. 上菜，好香哦#'),(50,'【九阳铁釜饭煲】粉蒸肉米饭套餐','主食','五花肉#\n大米#\n紫薯#\n玉米#\n圣女果#\n白玉菇#\n黄瓜#\n粉蒸肉调料#\n料酒#\n生抽#\n水#\n油#\n盐#','200g#\n120g#\n40g#\n100#\n20g#\n30g#\n20g#\n3勺#\n2勺#\n1勺#\n3勺#\n1勺#\n半勺#','1. 五花肉切成薄片，加入粉蒸肉调料。#\n2. 加入料酒、生抽，少 许水，将肉片抓匀，一片片夹开，码在碗中，腌制15分钟。#\n3. 将大米淘洗两遍后，放入电饭煲内，加入适量的水。#\n4. 第二层将电饭煲自带的蒸笼盖上，将粉蒸肉放入，再顺便蒸个紫薯和玉米。#\n5. 合上电饭煲盖子，选择精煮饭功能。#\n6. 圣女果切片，与白玉菇和切成条状的黄瓜，一起放入另一个容器内，加入盐和油拌匀。在程序剩下8分钟时，将粉蒸肉取出，将蔬菜放入，直到程序结束，再焖5分钟，食物就全部都熟了。#'),(55,'小排骨土豆汤#青春食堂#','汤','猪肋排#\n土豆#\n油#\n盐#\n葱#\n料酒#\n姜#','500g#\n2个#\n适量#\n2小勺#\n一把#\n5ml#\n3片#','1. 猪肋排切块洗净，放入锅中倒入凉水大火煮开，撇去后浮沫，捞出备用#\n2. 炒锅中放入一小勺油烧热，放入葱姜爆香#\n3. 将猪肋排倒入，烹入5ml料酒炒香#\n4. 将炒好的猪肋排连同汤汁一起倒入炖锅中，加入约2L-2.5L左右的水#\n5. 大火煮开后调小火焖煮2小时，剩余半小时时加入2小勺盐#\n6. 剩余10分钟时，加入切好条的土豆块，大火煮开后调小火，快好的时候剪入葱花即可#'),(57,'独家蒜香糖醋鲳鱼#美的微波炉菜谱#','荤菜','鲳鱼#\n小葱#\n姜#\n蒜#\n盐#\n生抽#\n料酒#\n醋#\n糖#','2条300克#\n1根#\n3片#\n3瓣#\n1小勺（2克）#\n30毫升#\n20毫升#\n20毫升#\n20克#','1. 配料#\n2. 鲳鱼2条洗净去腮肚，在背上划菱形刀，容易腌入味#\n3. 葱、姜、蒜均切末，葱分葱白和葱绿#\n4. 所有的调料混合均匀后加在鲳鱼上#\n5. 再加葱白和姜末和蒜末，腌制30分钟入味#\n6. 中间翻个面，两边都要腌到#\n7. 连盘子放入微波炉里加盖高火叮3分钟#\n8. 取出翻个面再加盖叮2分钟，洒上绿葱花就好了#'),(58,'腌笃鲜｜日食记','荤菜','五花肉#\n春笋#\n百叶结#','一块#\n适量#\n适量#','1. 咸肉用温水浸泡2小时。#\n2. 冷水锅中放葱姜、花雕酒，肉焯水变色后关火取出。#\n3. 焯水后的五花肉切片，金华火腿切5片，泡水后的咸肉整块，一起入滚水锅，小火“笃”半小时。#\n4. 继上一步，单将咸肉取出切块后，再放回肉汤锅里。撇去浮沫。#\n5. 春笋去皮切滚刀块，烧开一锅水放少许盐，放入春笋焯水后取出备用。#\n6. 将春笋和百叶结放入肉汤锅中大火煮沸，小火慢“笃”1小时出锅，可撒葱花。#\n7. 吃吧～#'),(59,'豉汁蒸鸡腿 #元气挑战每一天#','荤菜','姜#\n蒜#\n料酒#\n豆豉酱#\n蚝油#\n生抽#','2片#\n5瓣#\n1茶匙#\n1茶匙#\n1茶匙#\n1/2茶匙#','1. 备好所需食材；#\n2. 鸡腿洗净剁成小块儿，洋葱切小块儿，两者混合；#\n3. 蒜切末，放入其中，再放入姜片，料酒、蚝油、豆豉酱、生抽；#\n4. 抓匀，腌制40分钟；#\n5. 腌好的食材全部放入美的蒸宝宝中；#\n6. 抽出蒸宝宝下面的加水盒，注满纯净水，#\n7. 选择2排骨程序即可。#'),(62,'五花肉炒四季豆','荤菜','盐#\n干辣椒#\n蒜#\n酱油#\n蚝油#','适量#\n6只#\n1瓣#\n1汤匙#\n半汤匙#','1. 材料；#\n2. 五花肉切薄片；#\n3. 四季豆摘头尾，斜切段；#\n4. 干辣椒切段，蒜切片；#\n5. 五花肉入锅煎煸出油；盛出；#\n6. 锅中留适量油，加入干辣椒段和蒜片炒出香味；#\n7. 倒入四季豆炒1-2分钟；四季豆要多炒一会儿熟透~#\n8. 加入五花肉翻炒，调入盐、酱油、蚝油炒匀就可以了。#'),(64,'多谷坚果菠萝饭#美的初心电饭煲#','主食','菠萝#\n薏仁#\n大麦米#\n高粱米#\n小麦#\n糯米#\n糖#\n小米#\n荞麦#\n糙米#\n粳米#\n坚果#','半个#\n30克#\n15克#\n30克#\n15克#\n10克#\n30克#\n30克#\n10克#\n10克#\n30克#\n适量#','1. 准备食材#\n2. 薏仁用水泡3-4小时，其他粗粮不用泡发#\n3. 其他粗粮及泡发好的薏仁一起放入美的电饭煲，50分钟左右就做好了，粗粮：水=1:1#\n4. 蒸饭时，准备菠萝，菠萝从中间切开后，挖去内心#\n5. 这时，谷物饭也做好了，还有点温热时#\n6. 从美的电饭煲中取出一些，放入糖和坚果，充分搅拌均匀#\n7. 最后放入菠萝里，就可以和家人一起享用了。#\n8. 成品图，味道非常浓郁的菠萝饭。#'),(67,'清蒸龙利鱼#美极鲜味汁#','荤菜','姜#\n美人椒#\n盐#\n美极鲜味汁#\n料酒#\n白胡椒粉#\n糖#\n玉米油#','10g#\n1个#\n1g#\n1勺#\n适量#\n少许#\n1g#\n20g#','1. 龙利鱼柳解冻，用厨房纸巾吸干水份#\n2. 薄薄的撒上1克盐（两面共1克），少许白胡椒粉#\n3. 料酒适量#\n4. 放上姜片，腌制15分钟。香葱葱白切段，葱绿切细丝泡冷水，剩余的姜切丝；美人椒切细丝#\n5. 盘子底部铺上姜片和葱白#\n6. 放上龙利鱼柳，蒸锅上汽后，大火蒸3分钟，出水后倒出多余水份，再蒸5分钟，闷2分钟#\n7. 取出龙利鱼柳，#\n8. 放美极鲜味汁1勺，糖1g#\n9. 在鱼表面铺上姜丝，香葱丝，美人椒丝#\n10. 油锅烧热油，看到冒青烟#\n11. 热油浇到鱼柳上#\n12. 成品#'),(68,'紫薯绿豆甜汤','甜品','绿豆#\n紫薯#\n冰糖#\n清水#','200g#\n1个#\n50g#\n1000ml#','1. 将绿豆洗净，紫薯切皮切块放入锅中加入适量水和冰糖#\n2. 按煲汤键即可#\n3. 完成#\n4. 不错#'),(69,'手撕包菜','素菜','包菜#\n稻米油#\n鲜酱油#\n干红椒#\n蒜#\n葱花#\n花椒#\n鸡精#','200g#\n适量#\n适量#\n一个#\n2瓣#\n少许#\n少许#\n少许#','1. 包菜洗净，用手撕成块，较厚的叶柄用刀片薄，葱蒜、红椒备好；#\n2. 炒锅放入适量的稻米油；#\n3. 放入花椒，炸出香味，但不要炸糊啦；#\n4. 放入红椒、葱、蒜，炒出香味；#\n5. 放入包菜，快速翻炒，用大火；#\n6. 包菜都是嫩叶，很快变得软榻透明，倒入适量的鲜酱油，翻炒均匀；#\n7. 放入少许的盐、鸡精，翻炒均匀，关火，盛出即可。#\n8. 成品图#'),(71,'青椒肉丝','荤菜','大青椒#\n猪里脊肉#\n姜#\n干淀粉#\n老抽#\n生抽#\n水淀粉#\n清水#\n清水#\n盐#\n糖#\n料酒#\n蒜#','#\n#\n#\n5g#\n10g#\n5g#\n适量#\n清水#\n5g#\n盐#\n6g#\n5g#\n#','1. 大青椒横向剖开，去除里面的芯后，切成丝，#\n2. 里脊肉顺纹理切成丝，加少许淀粉和生抽腌制。#\n3. 炒锅里加少量油，油热后下青椒丝煸炒到微软时，出锅备用。再次烧热锅，倒入少量油，油热后下姜蒜片爆香，#\n4. 倒入肉丝快速炒散（要大火快炒，肉丝才嫩，火小了肉丝会老）。#\n5. 肉丝炒到约八成熟时，#\n6. 下炒过的青椒丝同炒匀。调入盐与糖（剩下的一半）炒匀后，再淋入水淀粉勾薄芡，炒匀即可出锅。#'),(72,'香辣藕丁','素菜','莲藕#\n郫县豆瓣酱#\n蒜#\n糖#\n生抽#\n青红朝天椒#\n白醋(米醋)#','去皮(320克)#\n两勺#\n两瓣#\n一小勺#\n两勺#\n各三只#\n一勺#','1. 盆里倒凉水，加入一勺米醋(白醋)#\n2. 莲藕去皮切丁，放到水盆里，泡大约10分钟，防止变色。蒜末，小辣椒切好备用#\n3. 锅里放油，小火煸香蒜末#\n4. 加入两勺豆瓣酱炒香，出红油#\n5. 炒出红油#\n6. 用漏勺捞出藕丁，沥干水份，放入锅里翻炒均匀，开大点火，#\n7. 加入两勺生抽#\n8. 一小勺糖，略炒#\n9. 加入约100毫升的热水，烧开，盖盖小火煮约两分钟#\n10. 开盖大火收汁(约一分钟)，放入辣椒圈，翻炒均匀出锅#'),(73,'蚝油生菜','素菜','生菜#\n蚝油#\n大蒜#\n葱白#\n淀粉#\n葱花#','1斤#\n1勺#\n适量#\n适量#\n1勺#\n适量#','1. 洗净#\n2. 蒜末，葱白，蚝油、生抽、淀粉各一勺调汁#\n3. 开水捞一下#\n4. 摆盘#\n5. 葱蒜末下油爆香，放调好的蚝油汁，烧至浓稠#\n6. 淋在生菜上#\n7. 拌拌就好了#'),(74,'蓑衣黄瓜#小妙招擂台#','素菜','黄瓜#\n盐#\n糖#\n醋#\n香油#\n酱油#\n小红椒（或辣椒油）#','2根#\n1勺#\n1.5勺#\n1勺#\n少许#\n半勺#\n适量#','1. 尽量选笔直的黄瓜，洗净后在黄瓜两边放两根筷子。#\n2. 90度直角把黄瓜切成薄片，有了筷子，您再也别担心黄瓜会切断了。#\n3. 切完后把黄瓜翻面，筷子继续放在两边。刀的角度改成45度，斜刀切片。#\n4. 这样一根蓑衣黄瓜就切好了。#\n5. 切好的黄瓜放在盘子里，撒适量的盐，腌制20分钟。#\n6. 根据您的喜好做一碗酸甜调味汁，喜好辣口的可以放些辣椒油。您着急的话，腌制半小时后就可以浇汁食用，不过蓑衣黄瓜要好吃，还是腌制时间长一点，入冰箱4-5小时，黄瓜片析出水分，充分吸收调味料，才特别好吃。#'),(75,'鸡肉披萨','荤菜','鸡脯肉#\n胡萝卜#\n洋葱#\n青椒#\n发好的披萨面团#','200g#\n50g#\n50g#\n50g#\n250g#','1. 发好的面团杆饼，刷披萨酱，撒上鸡肉陷#\n2. 180度入烤箱烤十分钟撒芝士，再烤6.7分钟即可#\n3. 挤上番茄酱切块#\n4. 午餐一起合个影#'),(76,'脆爽娃娃菜','素菜','娃娃菜#\n冰糖#\n白糖#\n辣椒#\n盐#\n鸡精#\n白醋#\n香油#','1颗#\n4块#\n1勺#\n5个#\n少许#\n适量#\n4~5勺#\n几滴#','1. 冰糖，白糖放入锅里加少许水加热化成冰糖水，娃娃菜洗净，辣椒洗净#\n2. 洗净的娃娃菜切成丝儿#\n3. 辣椒切圈#\n4. 锅里烧少许油，油热关火，放入辣椒圈炸出香味#\n5. 倒入盆里#\n6. 加入冰糖水，白醋，盐，鸡精，拌匀，如果不够味，再加一些白糖和白醋，鸡精的量也稍微多一些，搅匀#\n7. 倒入娃娃菜,滴几滴香油轻轻拌匀#\n8. 好啦#'),(77,'之孜然排骨#粉粉套装试用#','荤菜','排骨#\n孜然粉#\n青椒#\n盐#\n油#','500克#\n适量#\n适量#\n适量#\n适量#','1. 排骨切成段#\n2. 油锅烧热#\n3. 把排骨倒进去，#\n4. 翻炒至微微变色#\n5. 盖上锅盖，焖煮片刻#\n6. 倒入从排骨上切下的肉片一起翻炒#\n7. 炒至肉变色，放入青椒和盐#\n8. 翻炒至青椒变软#\n9. 撒入孜然粉即可起锅#'),(78,'西红柿炒散花菜','素菜','开花菜#\n西红柿#\n胡萝卜#\n油#\n盐#\n水#','1/4#\n1个#\n1/2#\n2勺#\n1茶匙#\n4勺#','1. 散花菜掰小朵洗净沥干水分#\n2. 胡萝卜去皮洗净，切菱形块#\n3. 锅中热油，油热放入葱花炒香，加入西红柿翻炒，待西红柿变软，淋入适量水#\n4. 炒至汤汁粘稠#\n5. 加入散花菜和胡萝卜翻炒片刻#\n6. 撒适量盐，（喜欢甜味的可以?少量糖）翻炒均匀，美味的西红柿散花菜菜，西红柿汁酸酸好开胃，散花菜甜甜好口感。酸酸甜甜特别美味。#'),(80,'【白灼虾】活虾最原味的做法','荤菜','活虾#\n料酒#\n姜片#\n陈醋#\n芥末#\n香葱#','500g#\n#\n#\n#\n#\n#','1. 新鲜的虾准备好#\n2. 锅内放入姜片、水、料酒烧开#\n3. 倒入活虾，火要保持大火状态#\n4. 烫到虾变成红色就可以马上捞起#\n5. 吃的时候加点沾酱就成#'),(81,'韩国芝士炒年糕','主食','韩国辣椒酱#\n香菇#\n五花肉#\n葱#\n马苏里拉芝士#\n鱼丸#','#\n#\n#\n#\n#\n#','1. 准备材料#\n2. 锅中放油，放入五花肉煸炒，倒入辣酱，两勺白糖、辣白菜、香菇翻炒，加水煮开倒入年糕，中火慢煮，加盐调味#\n3. 煮到汤汁粘稠加入芝士碎和葱叶，芝士融化即可#\n4. 酸酸甜甜带点辣的韩国芝士炒年糕出锅啦#'),(82,'茭白炒牛肉#黑人牙膏一招制胜#','荤菜','茭白#\n牛肉#\n酱油#\n料酒#\n淀粉#\n花椒粒#\n生姜#\n大蒜#\n植物油#\n盐#','两个（约400g）#\n300g#\n半勺#\n半勺#\n2g#\n1.5g#\n2g#\n两粒#\n35g#\n半勺#','1. 牛肉横纹切片之后用清水清洗，直到把血水洗净，放入酱油、料酒和淀粉搅拌均匀，腌制半个小时左右。#\n2. 把茭白切成条状，生姜和大蒜清洗之后拍散，花椒粒准备好。#\n3. 油热之后把大蒜、生姜和花椒粒放入锅中爆香。#\n4. 放入牛肉，中火翻炒，将牛肉炒至八成熟。#\n5. 一次性倒入茭白，继续翻炒。#\n6. 炒熟之后调入盐，翻炒均匀入味即可关火。#\n7. 腌制过的牛肉比较嫩滑，茭白脆爽，口味适中，适合全家食用。#'),(83,'3月不减肥，月月徒伤悲 清炒四季时蔬','素菜','紫甘蓝#\n藕片#\n芦笋#\n胡萝卜#\n木耳#\n葱花#\n食盐#\n食用油#','100g#\n50g#\n50g#\n30g#\n30g#\n5g#\n适量#\n适量#','1. 紫甘蓝切大块，莲藕切片，芦笋切段，胡萝卜切片，木耳洗干净掰一口大小的块#\n2. 炒锅烧热，加入食用油和葱花炝锅，然后下入胡萝卜和木耳，翻炒一下加入莲藕和芦笋，最后加入紫甘蓝，放盐搅拌均匀即可。#'),(85,'黄金猪排 | 九阳知食','荤菜','猪大排#\n鸡蛋#\n生粉#\n面包糠#\n食盐#\n黄酒#\n柠檬#\n食用油#\n姜片#','2片#\n2个#\n适量#\n适量#\n适量#\n4勺#\n半个#\n1勺#\n5片#','1. 准备食材#\n2. 首先将猪大排用刀背或肉锤，反复敲打，敲打至原来大排的翻倍大小即可。#\n3. 腌制：加入黑胡椒、食盐、黄酒、姜片、柠檬汁，腌制半小时以上。#\n4. 鸡蛋打散，把腌制好的猪排沾上蛋液，裹上生粉；重复以上操作一次。#\n5. 将3再次沾上蛋液，然后裹上面包糠，按压平整。#\n6. 猪排两面刷上一层食用油，放入空气炸锅中炸制（180度15分钟）#\n7. 完成#'),(86,'爆炒猪肝（味道超级嫩）','荤菜','猪肝#\n葱#\n姜#\n料酒#\n芝麻#\n胡椒粉#\n淀粉#\n生抽#','250g#\n少许#\n少许#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 葱姜切好备用#\n2. 切成薄片#\n3. 加入生姜，盐，生抽，白胡椒，油，地瓜粉，抓匀，至少两分钟。#\n4. 在锅中倒入油，放入姜和蒜，芝麻。#\n5. 翻炒，放入料酒。#\n6. 放入葱，继续煸炒#\n7. 出锅啦～#'),(89,'豉香土豆排骨#寻找最聪明的蒸菜达人#','荤菜','猪肋排#\n土豆#\n生抽#\n盐#\n料酒#\n生粉#\n小葱#\n生姜#\n豆豉#\n蚝油#','500克#\n180克#\n2汤匙#\n4克#\n30毫升#\n2汤匙#\n适量#\n适量#\n2汤匙#\n15毫升#','1. 猪肋排用清水泡清血水，中途水浑浊了要调换#\n2. 之后把排骨洗净沥干水分后加入盐，料酒，生抽，蚝油和生粉抓匀后腌制6小时以上#\n3. 土豆去皮洗净，准备葱和姜片#\n4. 把土豆切成滚刀块后加入2克盐拌匀#\n5. 准备豆豉#\n6. 先把土豆放入碗中再把排骨加入，再把豆豉，小葱和姜片加在上面#\n7. 放入微波炉专用蒸笼里后进微波炉#\n8. 选择蒸汽菜单蒸排骨，一共用了30分钟#\n9. 出锅后撒上葱花#\n10. 上桌#'),(90,'嫩滑鸡胸肉片','荤菜','鸡胸脯肉#\n水#\n玉米淀粉#\n油#\n盐#\n浓汤宝#\n葱粒#\n香菜#','300克#\n2大勺#\n1大勺#\n1小勺#\n1/4小勺#\n半小块#\n适量#\n适量#','1. 准备鸡大胸一块，洗净，去除边缘的脂肪块和表面的筋膜；切片，越薄越好。#\n2. 把调料都加进去；搅匀，腌制10分钟。#\n3. 准备好其他配料；锅里烧开水，把浓汤宝加进去。#\n4. 把肉片放进去，改为中火；重新沸腾后加入葱粒和香菜，再煮10秒即可。#\n5. 不是吹嘘，真的是很滑的~#\n6. 连着汤一起吃，还有香菜香葱的味道~#\n7. 真心推荐！！#'),(91,'蜜汁叉烧肉','荤菜','五花肉#\n蜂蜜#\n酱油#\n料酒#\n白砂糖#\n豆豉酱#\n盐#','150g#\n2勺#\n1勺#\n2g#\n1g#\n2g#\n1g#','1. 配料调汁，加入一半蜂蜜，腌制五花肉4小时。#\n2. 腌好的肉表面刷蜂蜜，挂到烤网上。220度烤20分钟。中间再刷一次蜜。#\n3. 待表面蜂蜜收干，就可以啦#'),(92,'红烧肉（冰糖）','荤菜','精选五花肉#\n小香葱#\n生姜#\n八角#\n花椒#\n桂皮#\n香叶#\n料酒#\n生抽#\n老抽#\n红方腐乳#\n冰糖#','300g#\n4-6颗#\n4块#\n1颗#\n10颗#\n2小块#\n2片#\n2勺#\n斟酌#\n1勺#\n2块#\n20颗左右#','1. 锅里少倒点油放花椒八角等大料炸油，起香倒入切好的五花肉（方块型），把肉煸到呈白色有香味用盘子装出来，然后热锅放入冰糖，再倒入生抽把冰糖完全烧化掉，然后倒入之前煸好的肉，翻炒到每块肉都被生抽冰糖汁包裹，放入葱和生姜，料酒，生抽，腐乳翻炒一分钟左右，加水漫过肉，大火烧开10分钟后中火10-25分钟转小火40分钟后，大火收汁，最后装盘。#'),(93,'咸烧白','荤菜','带皮五花肉#\n芽菜#\n老抽#\n红糖#\n植物油#\n花椒#\n葱（煮肉时用）#','500克#\n适量#\n15毫升#\n5克#\n20ml#\n适量#\n#','1. 五花肉煮15分钟，备用#\n2. 煮好后的肉，摸上老抽和化开的红糖！#\n3. 锅里放少量油烧开，把手上色后的肉放锅里按压肉皮面，使肉皮使之起泡。#\n4. 然后切之均匀厚度，厚度可根据个人喜好切至！#\n5. 肉皮向下摆放，然后把刚才上色的配料淋上。#\n6. 肉上压实芽菜，准备上锅大火蒸至一个半小时！#\n7. 蒸至烂熟后，翻盘。一盘色味型巨佳的咸烧白成功出膛！#'),(94,'胡萝卜炒鸡丝','荤菜','鸡胸#\n胡萝卜#\n食用油#\n葱#\n生姜#\n大蒜#\n生粉#\n盐#\n料酒#\n生抽#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 鸡胸脯肉清洗干净打成薄片后切成丝；#\n2. 鸡丝里放入一点盐，一小勺料酒和生粉；#\n3. 用手抓匀，放一小勺食用油再抓匀后盖保鲜膜入冰箱冷藏一小时；#\n4. 胡萝卜切断后打成薄片，再切成丝；#\n5. 热锅冷油加入生姜，葱和大蒜煸炒出香味；#\n6. 加入鸡丝翻炒到变色即可马上出锅备用；#\n7. 利用锅里的剩油，加入胡萝卜丝翻炒到变软；#\n8. 加入鸡丝，再翻炒几下；#\n9. 加一点盐和几滴生抽调味即可出锅。#'),(97,'蒜蓉茼蒿','素菜','茼蒿#\n大蒜#\n盐#\n鸡精#\n油#','500g#\n4瓣#\n少许#\n少许#\n适量#','1. 准备好食材。#\n2. 蒜蓉爆锅。#\n3. 煸香。#\n4. 放入茼蒿，翻炒。#\n5. 加入盐、鸡精，翻炒均匀。#\n6. 出锅入盘，好清香哇。(?￣? ?? ￣??)#'),(99,'酱烧胡萝卜','素菜','胡萝卜#\n葱#\n辣椒酱#\n蒜蓉辣酱#\n糖#\n水#','2根#\n一段#\n20克#\n20克#\n5克#\n适量#','1. 准备2根胡萝卜，洗净切滚刀块#\n2. 一大勺韩式辣椒酱、一大勺蒜蓉辣椒酱，一小勺白糖，用清水调成酱汁#\n3. 炒锅入油、放葱花炒出香味，放入胡萝卜翻炒#\n4. 胡萝卜在油中要多炒几分钟，放入调好的酱料，翻炒均匀#\n5. 加入清水与胡萝卜齐平，大火烧开，小火炖煮10分钟#\n6. 10分钟后，用锅铲铲一下胡萝卜，已软烂即可盛出；盐基本不用放，酱料里都含有盐分#\n7. 成品图#\n8. 成品图#\n9. 成品图#'),(100,'瘦肉炒菜心','荤菜','菜心#\n瘦肉#\n生姜#\n盐#\n酱油#\n油#\n生粉#\n料酒#','500克#\n200克#\n5克#\n5克#\n3克#\n5ml#\n1勺#\n2克#','1. 瘦肉洗干净，切片，放油、酱油、料酒、生粉、盐拌均腌制10分钟；#\n2. 菜心洗干净，去老叶，清水浸泡5分钟，捞出沥干水；#\n3. 清水煮沸，放入菜心，汆烫，捞出沥干水；#\n4. 热锅，倒油，放入腌制好的瘦肉、姜丝爆炒五成熟；#\n5. 加入汆烫过的菜心，盐盐，炒均即可；#'),(103,'土豆焖排骨','荤菜','蒜头#\n葱蒜段#\n料酒#\n酱油#\n姜片#\n豆豉#\n豆瓣辣酱#','6颗#\n适量#\n2茶匙#\n1.5茶匙#\n8片#\n5g#\n1茶匙#','1. 准备材料，排骨已用盐腌过，洗净沥水、土豆切块，葱蒜切段，姜片适量#\n2. 葱白、姜、蒜头下油锅爆香#\n3. 排骨下锅摊开煎香#\n4. 排骨翻面，放入豆豉翻炒#\n5. 加入土豆翻炒，干锅时酒入料酒翻炒，加入酱油翻炒#\n6. 加一勺辣酱#\n7. 加水末过排骨，盖盖，大火煮5分钟后转中火再煮10分钟#\n8. 加入葱蒜段，生粉水勾芡即可#\n9. 上碟#\n10. 开吃#'),(108,'小炒牛肉','荤菜','牛肉#\n蒜#\n姜片#\n青红椒#\n葱段#\n泡椒#\n胡椒#\n盐#\n淀粉#\n食用油#\n生抽#\n鸡粉#\n料酒#','250#\n#\n#\n#\n#\n#\n如:1勺#\n#\n#\n#\n#\n#\n#','1. 牛肉切片放料酒，胡椒粉，盐，淀粉，少许食用油抓匀腌制15分钟#\n2. 红椒切块，葱切段，泡椒切粒，姜蒜切末#\n3. 锅热油后将牛肉放入快速滑变色盛出#\n4. 锅放油爆香姜蒜，放泡椒和青红椒，调盐翻炒#\n5. 倒入牛肉翻炒，调生抽，鸡粉，葱段炒匀即可。#'),(109,'腐竹炒木耳','素菜','腐竹#\n胡萝卜#\n木耳#\n猪肉#\n蚝油#\n盐#\n火麻油#','100g#\n1根#\n两片#\n200g#\n30g#\n1茶匙#\n1勺#','1. 猪肉焯水，备用#\n2. 腐竹泡水切段备用；猪肉切片备用；木耳泡水切段备用；胡萝卜切片备用。#\n3. 半肥瘦的猪肉放锅里煎出油，煎出油后，放酱油炒香。#\n4. 倒入腐竹和木耳炒均匀。#\n5. 倒入蚝油炒匀#\n6. 放入胡萝卜一起炒匀，倒入三分之一碗水，盖锅焖10分钟左右，中途可以开盖翻炒一下，出锅前放盐和亦舒堂火麻油炒均匀即可出锅。#\n7. 特写#'),(111,'油淋藕片#金龙鱼外婆小榨菜籽油#','素菜','莲藕#\n花椒#\n干辣椒#\n白醋#\n盐#\n糖#\n金龙鱼外婆小榨菜籽油#','1段儿#\n10颗#\n2粒#\n1茶匙#\n1茶匙#\n1/4茶匙#\n2茶匙#','1. 藕去皮，切薄片，泡入水中，加入少许白醋或柠檬汁；#\n2. 锅里放入足量的水，待水开后，放入切好的藕片煮约1分钟左右，捞出，过凉水，装盘，表面放花椒和辣椒；#\n3. 另起锅，锅里倒入金龙鱼外婆小榨菜籽油，待油热后，淋在藕片上面花椒和辣椒上，拌入白醋、盐和糖即可。#'),(113,'茄子肉末｜组长教你做湘菜','荤菜','肉末#\n茄子#\n葱姜蒜#\n干辣椒#\n芝麻#\n豆瓣酱#\n生抽#\n辣椒面#\n孜然#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 因为是少油版，茄子先蒸熟，蒸10分钟左右，切段备用。#\n2. 油锅下肉末，加少许料酒去腥。小火煎至焦黄，微微变硬，且有焦香时，加入姜蒜，干辣椒，芝麻煸香。最后再加豆瓣酱，生抽炒成汁。#\n3. 炒好的汁如图，加辣椒面能提辣提色，不爱吃辣可以不放#\n4. 出锅前撒少许葱花提香，装饰。焦香扑鼻的肉末，加上香辣软糯的茄子。下饭的超级无敌搭配。#'),(114,'爆炒花蛤','荤菜','花蛤#\n大葱#\n姜蒜#\n干辣椒#\n豆瓣酱#\n料酒#\n生抽#\n蚝油#','750g#\n一根#\n适量#\n小半碗#\n一勺#\n两勺#\n两勺#\n一勺#','1. 买回来的花蛤在加盐的水中养半天，使其吐沙。然后烧热水煮一下，煮至刚开口就捞起来过凉水，再在流水下一个一个地将花蛤内外洗干净。#\n2. 大葱切段，姜蒜切粒，干辣椒剪段，准备生抽、蚝油、料酒、豆瓣酱。#\n3. 热锅油温后放入花椒炒出香味后将花椒捞出扔掉。#\n4. 下姜蒜、干辣椒、大葱的葱白、豆瓣酱炒香。#\n5. 放入处理好的花蛤翻炒。#\n6. 翻炒过程中烹入料酒、生抽、蚝油炒匀。#\n7. 加入绿色的葱叶部分，翻炒均匀后起锅。#\n8. 一口一个，开吃吧！#'),(116,'据说藕带这样做不仅健康吃了还能变瘦','素菜','白醋#\n蜂蜜#\n新鲜薄荷#\n小酸柑#\n盐#','10g#\n20g#\n10g#\n4个#\n适量#','1. 藕带切成5cm的段，热水下锅，焯水到变软，捞出放入冷水#\n2. 薄荷叶切碎，小酸柑对半切开#\n3. 藕带控干水分，加入泡椒，小酸柑，薄荷叶，蜂蜜、白醋和少量盐，混合均匀，放入冰箱腌制1小时#'),(117,'冬瓜排骨汤','汤','猪排骨#\n冬瓜#\n香菜#\n盐#\n香油#\n鸡精#\n葱#\n姜#\n大料#\n花椒#','7~8块#\n小半个#\n一小把#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 猪骨洗净，锅中放水烧开下猪排汆出血水，撇去浮沫捞出排骨备用。#\n2. 冬瓜去皮去瓤，洗净，切块。#\n3. 另起锅加入大料、葱段、姜片和花椒煮开，然后将煮好的排骨重新放到锅中大火烧开后转小火慢炖半个小时。#\n4. 然后加入冬瓜块，加适量的盐在煮15分钟，加入鸡精和香菜段，滴入几滴香油即可出锅。#'),(118,'【菁选酱油】“米饭杀手”--炝拌土豆丝','素菜','土豆（小）#\n香葱#\n蒜瓣#\n孜然#\n熟芝麻#\n花椒#\n菁选酱油#\n辣椒粉#\n白糖#\n食盐#\n香醋#\n芝麻油#\n橄榄油#\n老干妈（油）#','1个#\n1根#\n2个#\n1茶匙#\n1茶匙#\n1茶匙#\n1汤匙#\n1茶匙#\n1茶匙#\n1茶匙#\n1茶匙#\n1汤匙#\n2汤匙#\n1茶匙#','1. 快手食材；#\n2. 土豆洗净，去皮切丝（感谢我家老头拔刀相助）泡入冷水中去除多余的淀粉，蒜瓣、香葱切末；#\n3. 取一小碗，依次倒入菁选酱油、芝麻油、香醋、熟芝麻、孜然、蒜蓉、葱花、辣椒粉、白糖、食盐及老干妈（油），调成混合酱汁；#\n4. 汤锅入水烧开，倒入土豆丝，迅速飞水断生，捞出沥水；#\n5. 炒锅入橄榄油，放入花椒，炸香，去椒留油，改中小火，倒入土豆丝及酱汁，关火，趁油温拌匀，即可。别忘了准备一碗大大的米饭噢：）#'),(119,'广式虎皮凤爪','荤菜','鸡爪#\n洋葱#\n辣椒#\n姜#\n盐#\n生抽#\n料酒#\n老抽#\n酱油#\n醋#\n花生#\n豆豉#','600g#\n半个#\n3-4个#\n适量#\n适量#\n3勺#\n3勺#\n1勺#\n3勺#\n适量#\n一把#\n适量#','1. 鸡爪洗净剁开#\n2. 锅里放入水，加姜，料酒烧开#\n3. 放入鸡爪煮三分钟#\n4. 捞出过凉水滤干水份。#\n5. 把洋葱剁碎，辣椒切碎，姜剁碎。葱切成葱花。#\n6. 油烧至六成热放入鸡爪炸至金黄（要记得盖上盖子，很会溅油）#\n7. 捞出后放入冰水里泡，放置冰箱2个小时。这时看起来已经虎皮样了:)#\n8. 热锅冷油放入洋葱，姜，辣椒，豆豉炒香，再放入酱油，醋，料酒加热。#\n9. 把鸡爪捞出沥干水份，倒入酱汁拌匀放置15分钟入味。（花生米要提前泡好，忘拍照了）#\n10. 蒸30分钟，出锅。开始享受吧#'),(121,'勾人馋虫的美容大菜——【Q弹软糯魔法猪蹄】','荤菜','猪蹄#\n冰糖#\n姜#\n大葱#\n酱油#\n老抽#\n八角#\n大蒜#\n花椒#\n料酒#\n干辣椒#','700克#\n50克#\n20克#\n4段#\n1匙#\n1匙#\n2个#\n20克#\n8克#\n2匙#\n6个（不吃辣可以不放）#','1. 猪蹄洗净切块冷水入锅，煮8分钟，取出用凉水冲洗，再沥干水分。#\n2. 小火热油至三成热，放入冰糖，至溶化成焦糖色。倒入猪蹄转中火，快速翻炒让皮略呈金黄色。#\n3. 炒好后放入姜片、干辣椒、花椒、八角继续炒，再加入盐、酱油、老抽继续翻炒。#\n4. 炒完后倒入高压锅，加没过猪蹄的水，加入葱段。#\n5. 再加入料酒，高压25分钟左右，取出倒入汤锅，大火收汁即可。#'),(123,'凉拌苦菜','素菜','苦菜#\n盐#\n糖#\n生抽#\n醋#\n芝麻#\n鸡精#\n植物油#\n蒜茸#\n剁椒，辣椒粉#','300g#\n两小勺#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n根据口味#','1. 新摘的苦菜。#\n2. 清水洗干净。滚水内焯两分钟。过凉水。这样能保证焯后的菜颜色碧绿。凉水里加少许盐，浸泡一晚。#\n3. 捞出苦菜挤掉苦水，打散，加入盐，糖，生抽，陈醋，鸡精拌匀静置十分钟，让味道腌进去。#\n4. 为了漂亮，弄成了一个团状。#\n5. 撒上芝麻，大蒜切成蒜茸。铺在苦菜球上。植物油烧滚，浇上。#\n6. 喜欢吃辣的可加点剁椒。吃的时候再拌开。这样处理过后的苦菜，小朋友也爱吃。苦味减淡了许多。清爽香脆。#'),(125,'家常菜-油渣炒手撕包菜','荤菜','包菜#\n油渣#\n干辣椒#\n大蒜籽#\n花椒粒#\n生抽#\n白醋#\n盐#\n白糖#\n蚝油（按个人喜欢）#','半个#\n50g#\n5个#\n2个#\n16个#\n适量#\n少许#\n适量#\n少许#\n少许#','1. 包菜撕小片，大蒜籽切碎#\n2. 锅里放猪油，小火炒香花椒，去除花椒#\n3. 转大火，下大蒜籽爆香后放入油渣，翻炒片刻#\n4. 放入干辣椒爆片刻，下包菜，放盐、生抽、白醋（陈醋好吃些可颜色就没有这么漂亮了）调味，翻炒均匀，放一点白糖和蚝油（可不放），关火，利用锅内余温继续翻炒片刻直至熟。#\n5. 一盘爽口又有油香的手撕包菜就好了，加一点料就让普通的家常菜变身餐馆菜#'),(126,'肉末香菇豆腐泡','荤菜','豆腐泡#\n肉末#\n香菇#\n胡椒粉#\n淀粉#\n生抽#\n葱花#\n姜#\n大蒜#\n蚝油#','400g#\n50g#\n10朵#\n五分之一小勺#\n一小勺#\n一汤匙#\n一小把#\n一小块#\n两瓣#\n一汤匙#','1. 肉末调入盐，胡椒粉和淀粉抓匀待用。#\n2. 香菇提前泡发，切片。推荐用干香菇，比新鲜香菇味道更加浓郁。#\n3. 姜蒜切末。#\n4. 锅里适量底油，煸炒肉末至变色盛出。#\n5. 爆香姜蒜末。#\n6. 炒香香菇。#\n7. 放入豆腐泡略微翻炒。#\n8. 加入小半碗水，生抽和蚝油。#\n9. 重新倒入肉，小火慢慢收汁使其入味即可。#'),(127,'凉拌海带丝','素菜','海带#\n蒜末、姜末#\n剁椒酱#\n砂糖#\n镇江香醋#\n酱油#\n麻油#','适量#\n比例1：2#\n2小勺#\n2小勺#\n2勺#\n1勺#\n1勺#','1. 海带洗净、切丝（偷懒的办法是买袋装切好滴），用开水煮熟，我一般煮5-7分钟，看个人口味啦，喜欢更脆一点可以少煮一会儿#\n2. 老姜切末#\n3. 加入蒜末，姜蒜比例：3～4:1#\n4. 加香醋、酱油、麻油、砂糖，调匀后微波高火10秒，让砂糖融化#\n5. 加入剁椒酱，多少按口味来哈#\n6. 调料倒入沥干水的海带丝#\n7. 拌匀即可！#'),(128,'虾仁炒芦笋#十二道锋味复刻#','荤菜','鲜虾#\n芦笋#\n盐#\n蒜#\n鸡精#','10只#\n200克#\n3克#\n2瓣#\n2克#','1. 鲜虾去头去壳去尾取虾仁后洗净，加盐，料酒，少许淀粉腌制5分钟后入沸水锅煮至10秒钟变色后捞出备用#\n2. 芦笋洗净去老皮后切片，入沸水锅煮熟至变色捞出，过冷水后备用。#\n3. 锅入适量食用油，油温升高后爆香蒜末，然后加入虾仁，芦笋大火翻炒，加盐，鸡精调味后即可#'),(131,'蒜苗炒腊肉','荤菜','腊肉#\n蒜苗#\n姜#\n蒜#\n植物油#\n盐#\n花椒#\n生抽#','600g#\n350g#\n2片#\n2瓣#\n2勺#\n0.5勺#\n20粒#\n1勺#','1. 腊肉用淘米水洗净，再用清水冲洗干净； 图片上的腊肉，我只炒了 一半；#\n2. 煮锅里倒入清水，放入需要煮的腊味，适量花椒，将腊味煮熟；#\n3. 煮熟的腊肉稍凉后，改刀切成片；#\n4. 蒜苗洗净，蒜苗杆和蒜苗叶分别切段，再切点姜蒜丝；#\n5. 锅里倒入适量植物油，烧热后放入姜蒜丝炒香，再放入腊肉下锅炒出油分；#\n6. 放入蒜苗杆，调入适量生抽翻炒；#\n7. 锅里的食材炒至八分熟，放入蒜苗叶翻炒；#\n8. 调入适量盐，翻炒均匀；#\n9. 装盘，盛出。#'),(132,'懒人版萝卜烧牛肋排','荤菜','牛肋排#\n白萝卜#\n柱候酱#\n老姜#\n料酒（处理牛肋排用）#\n食用油#\n清水#','500克#\n1根#\n3汤匙#\n1块#\n1汤匙#\n适量#\n1升#','1. 将牛肋排洗净血水，放入电压力锅中倒入料酒和1升左右的水，压20分钟。待压好后，将牛肋排捞出备用，压牛肋排剩下的汤汁留着备用。#\n2. 白萝卜去皮切滚刀块。#\n3. 炒锅中放入食用油烧至6成热，放入老姜，柱候酱，牛肋排爆香。#\n4. 然后倒入压牛肋排的汤汁。放入白萝卜，盖上锅盖，大火烧开后，转中小火烧30分钟至萝卜入味。#\n5. 就好了！#'),(133,'爆炒腰花','荤菜','猪腰#\n青、红椒#\n洋葱#\n生抽、老抽#\n葱姜蒜、料酒、盐、味精、糖。#\n水淀粉#','1个#\n各一个#\n半个#\n适量#\n适量#\n少量#','1. 猪腰洗净，剖开。#\n2. 去除猪腰臊。#\n3. 打上十字花。#\n4. 切成小段。#\n5. 放葱姜蒜、料酒、适量生抽、盐、糖、胡椒粉、腌制20分钟。#\n6. 锅里放油，大火烧至八成热，倒入腰花。#\n7. 大火煸炒，烧至全部变色，盛起。#\n8. 青、红椒、洋葱，切成小块。#\n9. 锅里少量油，加一点老抽，少量生抽、盐、糖，煸炒几下。#\n10. 倒入腰花，加味精，二滴醋，少量水淀粉，大火煸炒几下。#\n11. 完成。#'),(134,'番茄牛肉豆腐煲','荤菜','牛肉#\n豆腐#\n番茄 （大，红）#\n小葱#\n尖椒#\n大蒜#\n姜#\n料酒#\n胡椒粉#\n食盐#','500g#\n一块#\n3个#\n2根#\n1个#\n2瓣#\n#\n#\n#\n#','1. 牛肉切块，去血水后，加入姜片，料酒，少许胡椒炖煮。水开后换中火炖20-30分钟至牛肉软烂。#\n2. 番茄切成小块#\n3. 豆腐切成方糖块大小#\n4. 炒锅入油，加入切好的蒜瓣和尖椒#\n5. 放入番茄翻炒，加入盐便于出水，然后加入一大碗水，锅加盖，大火转中火煮#\n6. 将多余的牛肉汤倒掉，留下一小碗的量。将番茄汤和豆腐加入牛肉中小火炖煮10分钟#\n7. 出锅前加入葱末即可#\n8. 成品。鲜辣暖胃。不吃辣的就把辣椒去掉，味道一样佳#'),(135,'三文鱼塔塔#宜家让家更有味#','荤菜','宜家三文鱼#\n培根#\n牛油果#\n柠檬汁#\n黑胡椒#\n油#\n盐#','125g#\n2片#\n2个#\n少许#\n少许#\n少许#\n少许#','1. 备好所有用料#\n2. 将宜家三文鱼及培根切粒，三文鱼撒上黑胡椒先腌制一会儿，牛油果压成泥。#\n3. 锅中倒油，倒入培根和三文鱼粒加少许盐炒香。#\n4. 盛盘装出#\n5. 将三文鱼培根和牛油果挤入少许柠檬汁相拌，撒上黑胡椒#\n6. 用慕斯模具装盆，上面撒上坚果蔓越莓粒。搭配自己榨的云南石榴汁，可以抗氧化。#'),(136,'一碗煮南瓜','素菜','南瓜#\n油#\n生抽#\n白糖#\n盐#\n水#\n小葱花#','600g#\n1汤匙#\n1汤匙#\n1汤匙#\n少许（2克左右）#\n150g#\n少许#','1. 挑老南瓜，去皮，洗净，切成3厘米左右厚的滚刀块。太厚不易烂，太薄不禁煮。#\n2. 锅烧热，放1汤匙油，倒入南瓜块，翻炒几下，倒入1汤匙生抽，继续翻炒几下。#\n3. 加入1汤匙白糖。#\n4. 视个人口味加入少许的盐，其实真的只需要一点点就好了。炒匀。#\n5. 倒入水，盖上盖，大火烧开后，用铲子轻轻翻一下，转小火煮4分钟左右即可。出锅撒葱花。#'),(138,'麻婆豆腐','素菜','食盐#\n生姜#\n大蒜#\n米酒#\n白糖#\n花椒#\n豆瓣酱#','#\n#\n#\n#\n#\n#\n#','1. 烧开一锅水，下一勺食盐，关火下豆腐块浸泡十分钟。#\n2. 热锅下油，下花椒炸香，捞出花椒。#\n3. 下豆瓣酱，姜片，蒜瓣，炒出红油。#\n4. 下牛肉末炒香，加入白糖、米酒调味，再倒入水，煮开。#\n5. 下豆腐块，再次煮开，出锅~#'),(139,'【咱家粮仓炮儿哥有说】大枣黄豆炖猪脚～颜值要爆表','荤菜','猪脚#\n黄豆#\n新疆灰枣#\n姜#\n盐#','500g#\n50g#\n10个#\n10g#\n适量#','1. 炮儿哥有说：老规矩，先来个全家福#\n2. 下豆子，先泡一泡哈#\n3. 经过焯水的猪脚#\n4. 我们的黄豆和姜片上场了。加入焯过水的猪脚大火，炖开锅。#\n5. 开火加入泡好的灰枣。小火30分钟。炮儿哥有说为什么是灰枣？就是因为他不会被炖老炖烂。关键是这种自然风干枣它不落地，不晾晒营养价值高。#\n6. 加入盐，其他的调味料我是不再加入了。??还是原味的好些。#\n7. 出锅了?????#'),(140,'番茄炖牛腩','荤菜','牛腩#\n番茄#\n食盐#\n生姜#\n番茄沙司#\n料酒#','600g#\n3只#\n适量#\n适量#\n适量#\n适量#','1. 牛腩切小块，下热水锅汆烫。捞出后，用水冲洗干净浮末。#\n2. 两只番茄切丁，一只番茄切滚刀块。生姜切片。#\n3. 将汆烫过的牛腩倒入锅，倒入料酒、花椒和适量热水，大火煮开，调中小火炖一个小时。#\n4. 炒锅中放入少量色拉油，依次放入葱段、姜片翻炒，将番茄丁放入翻炒，至番茄丁成为番茄酱。#\n5. 将炖煮过的牛肉捞出，倒入炒好的番茄酱中，加入番茄沙司和适量食盐，继续炖煮三十分钟，至汤汁浓稠，放入切成滚刀块的番茄块，略略翻炒，即可盛出。#\n6. 盛出#'),(141,'烧烤牙签羊肉','荤菜','羊排肉#\n孜然粉#\n辣椒粉#\n鸡粉#\n料酒#\n葱#\n芝麻#','100#\n20#\n适量#\n4#\n15#\n少许#\n少许#','1. 将羊排肉洗净，切均匀的小块，加入料酒、葱末、鸡粉拌匀，腌半小时#\n2. 腌好的肉穿在牙签上，均匀撒上孜然粉、辣椒粉、花椒粉、芝麻。各个面都要撒到#\n3. 入烤箱，中层上下火，170度，15分钟左右。烤制过程中注意翻面。具体时间要根据羊排肉块大小决定，变色后再单开上火烤几分钟更香#\n4. 羊排肉切得尽量大小一致，烤的时候成熟比较均匀#\n5. 牙签肉一般都是炸的，其实烤的话有烤羊肉串的感觉，孜然更香#\n6. 因为羊排是肥瘦相间的，肥肉部分烤的时候会出油，所以我就没刷植物油了#'),(143,'地方美食【杭椒牛柳】','荤菜','红椒#\n姜丝#\n洋葱丝#\n~腌肉材料：#\n蛋清#\n生粉#\n黑胡椒粉#\n蒜蓉#\n黄酒#\n蚝油#\n酱油#\n香油#\n小苏打#\n盐#','30g#\n10g#\n20g#\n#\n半个#\n2茶匙#\n2茶匙#\n1汤匙#\n1汤匙#\n1汤匙#\n2汤匙#\n1汤匙#\n1小撮#\n适量#','1. 杭椒洗净对剖切开。红椒、生姜、洋葱分别切丝。牛肉切8分厚片后拍松，改刀成5-6公分长的条。#\n2. 牛柳用鸡蛋清，生粉，黑胡椒，黄酒，蒜蓉，蚝油，酱油，香油一点点小苏打粉搅拌上劲后，放入冰箱2个小时以上。#\n3. 炒锅烧热，放入比平时炒菜多一些的油，烧至4成热时，放入牛柳滑炒至变色，捞起沥干油待用。#\n4. 锅中留3大匙油，放入姜丝、洋葱丝炒香。#\n5. 放入杭椒炒2分钟断生，再放入牛柳和红椒丝急火快炒，下盐后试一下咸淡翻匀出锅。#\n6. 装盘。老板，来碗米饭~#'),(145,'豆腐烧鱼块------利仁电火锅试用菜谱','荤菜','鲩鱼肉#\n豆腐#\n青红椒#\n姜葱#\n八角#\n桂皮#\n柠檬#','600克#\n2块#\n2根#\n20克#\n1个#\n少许#\n半个#','1. 鲩鱼肉洗净后，沥干水，切长块放入盆中。#\n2. 加入葱姜，柠檬片，盐，糖，生抽，料酒腌制30分钟。#\n3. 电火锅烧热后，放少许食用油润锅，接着把沾了生粉的腌渍鱼块放入锅内煎制。#\n4. 两面煎至金黄焦香后，盛出备用。#\n5. 锅内再放入少许食用油，接着把八角，桂皮，葱姜放入煸出香味。#\n6. 接着放入适量的开水，调入盐，糖，生抽，蚝油，然后把事先煎好的豆腐放入锅内烧制。#\n7. 再放入煎好的鱼块一起烧制入味。#\n8. 当锅内的水份收干大部分时，把青红椒粒放入锅内稍稍烧一下，就可以出锅啦。#'),(146,'腰果虾仁','荤菜','虾仁#\n西芹#\n红青椒#\n盐#\n料酒#\n蛋清#\n淀粉#\n鸡精#','250g#\n1条#\n1块#\n#\n#\n#\n#\n#','1. 虾仁挑完虾线后，在背部拉一刀以便之后入味#\n2. 西芹去皮，切成菱形块#\n3. 红椒切成菱形块#\n4. 虾仁加入一个蛋清，适量淀粉料酒腌制30分钟#\n5. 锅中加水至沸，加少量油。抄熟虾仁和西芹红椒，捞出#\n6. 调好汁，少许味精，盐，料酒，水淀粉。#\n7. 加少许油，炒虾仁和西芹红椒，加入调好的汁，之后加入炸过的腰果。煸炒一会，出锅#'),(148,'干锅有机花菜','素菜','花菜，黑木耳#\n辣椒粉，老干妈辣酱，盐，料酒#','适量#\n适量#','1. 花菜切下根部，花部沿梗的分支切开待用。#\n2. 锅里开水中放入盐，把花菜倒入焯水，不要烫得太开，水一滚就关火，用筷把花菜在开水里继续翻几下，出锅。#\n3. 烫好的花菜沥干水分待用。#\n4. 油锅里倒入辣椒粉烧到八成热，倒入花菜和黑木耳，一点点盐、料酒翻炒。#\n5. 翻炒一分钟左右，火力调到中大火，速度略快一些，然后加入老干妈辣酱继续翻炒到全体滚到辣酱，关火装盘。#\n6. 绝对下饭，松脆感让人绝对停不下筷来！#'),(149,'牙签肉','荤菜','猪瘦肉#\n牙签#\n鸡蛋#\n淀粉#\n辣椒面#','适量#\n适量#\n1个#\n适量#\n适量#','1. 猪瘦肉洗净，切片。#\n2. 猪瘦肉放碗里，放入蒜，姜，辣椒，辣椒面，胡椒粉，盐拌匀。#\n3. 打一个鸡蛋，放少许淀粉，抓匀，放一分钟。#\n4. 然后用牙签把肉串串，#\n5. 锅放油，油温6成热，放入牙签肉炸金黄捞出，#\n6. 放在菜叶上，周围放一些胡萝卜。#'),(150,'世界杯美食——椒盐虾头','荤菜','食用油#\n椒盐#\n小葱#\n蒜#','适量#\n适量#\n1根#\n1瓣#','1. 准备所需材料。#\n2. 虾头洗净，用剪刀把虾须剪掉。#\n3. 要剪得干净一点。#\n4. 后清洗干净，沥干水份。（一定要沥干水）#\n5. 锅内放入油烧至200度。#\n6. 倒入虾头快速炸1分钟。#\n7. 然后把虾头捞起。#\n8. 当油温降至160度时，再次放入虾头复炸2分钟。#\n9. 将炸好的虾头捞起。#\n10. 锅内放入少许油烧热，放蒜沫炒香。#\n11. 倒入虾头翻炒一下。#\n12. 再加入椒盐。#\n13. 撒上葱花。#\n14. 最后拌匀即可。#'),(152,'醋溜白菜','素菜','白菜#\n白糖#\n醋#\n酱油#\n盐#\n葱姜蒜末#\n美人椒/小米椒#\n淀粉#\n花椒#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n1个#\n适量#\n几粒#','1. 调料大集合。#\n2. 下油，爆香花椒粒然后捞出，再放入葱姜蒜末，美人椒末，然后放入白菜翻炒。#\n3. 翻炒的过程中加入适量盐，酱油，白糖，醋翻炒。#\n4. 最后再倒入一点醋，味精，然后淀粉出锅。#\n5. 成品了。#\n6. 这是第二次炒的，没有放酱油，加了些干红辣椒。#\n7. 来张近照哇。#'),(153,'清爽土豆泥','素菜','土豆#\n尖椒#\n洋葱#\n盐#\n番茄酱#','200g#\n适量#\n适量#\n适量#\n适量#','1. 土豆去皮，切大片放到蒸锅，蒸大约20分钟，蒸熟。#\n2. 尖椒和洋葱洗干净都切成小粒。（我用了一个尖椒和半个圆葱，圆葱的量大约是尖椒的一半）#\n3. 土豆蒸熟取出用勺碾成泥。#\n4. 放入洋葱和尖椒粒，同时放点盐，不要太多，有咸味就可以。#\n5. 拌匀。#\n6. 微温后将土豆泥团成乒乓球大小的球。#\n7. 每个土豆泥小球上挤点番茄酱即可。#'),(154,'芝心鸡肉丸','荤菜','鸡胸脯#\n马苏里拉芝士#\n面包糠#\n鸡蛋#\n淀粉#\n盐#\n料酒#\n蚝油#\n五香粉#','200g#\n适量#\n适量#\n一个#\n适量#\n适量#\n适量#\n少许#\n少许#','1. 鸡胸脯洗净，切去边上多余的脂肪和筋#\n2.  用刀背拍松后，剁成鸡肉泥（我用料理机打的）#\n3. 加入适量淀粉，料酒，盐，半个蛋清，五香粉和蚝油，搅拌均匀#\n4. 芝士切成小块#\n5. 取一团鸡肉泥按扁，放上一块芝士，包好成丸子状（怕沾手可以事先在手上抹油）#\n6. 剩余的鸡蛋打成蛋液，包好的鸡肉丸放到蛋液中蘸一下#\n7. 放到面包糠里滚一圈#\n8. 锅里放油烧到五成热，放入鸡肉丸#\n9.  炸至金黄捞出吸掉多余的油，趁热食用#'),(155,'合家欢','不属于任何一类','培根#\n荷兰豆#\n胡萝卜#\n水发黑木耳#\n植物油#\n葱花#\n盐#','3条#\n一把#\n半根#\n数朵#\n30克#\n少许#\n适量#','1. 黑木耳提前泡发后，焯水晾凉，胡萝卜切薄片，荷兰豆去掉边上的筋，洗净#\n2. 黑木耳、胡萝卜片、荷兰豆入开水中焯一分钟，捞出，冲凉水过凉#\n3. 用刀将培根切成宽条#\n4. 全部材料准备好，培根注意轻拿轻放，以防弄碎，荷兰豆可从中间斜切一刀成两半#\n5. 锅中放少许油，入葱花煸炒出香味#\n6. 入培根中火煸炒出油、出香味#\n7. 倒入蔬菜#\n8. 加盐调味，翻炒几下，即可出锅#\n9. 合家欢#\n10. 清爽下饭小菜#\n11. 培根的香气，杂蔬的清脆#\n12. 新年清爽下饭菜#'),(156,'豆皮炒肉末','荤菜','五花肉#\n豆皮#\n菜椒#\n姜蒜#\n酱油#\n醋#\n盐#\n糖#\n面酱#','50g#\n150g#\n45g#\n适量#\n2ml#\n3ml#\n2g#\n1g#\n5g#','1. 豆皮切丝焯水，菜椒切丝，五花肉切末备用；#\n2. 少油煸炒肉末变色放姜蒜末爆香，放面酱炒熟，蓄水适量放入豆皮；#\n3. 水开后调盐糖酱油煨豆皮入味，放菜椒收汁，烹醋，出锅盛盘。#'),(157,'香辣小土豆','素菜','小土豆#\n辣椒粉#\n花椒粉#\n五香粉#\n盐#\n香葱#','500g#\n一勺#\n半勺#\n少许#\n适量#\n适量#','1. 买这种小土豆，价格便宜味道也不差#\n2. 清洗干净不用剥皮，待会儿熟了压扁处理不会爆开#\n3. 蒸熟后像这样在菜板上用刀压扁，像一个圆饼干#\n4. 热锅冷油放锅里煎至两面焦黄，如果是不粘锅油不用太多#\n5. 两面已煎至金黄色后加入各种调料的混合料，再加入香葱即可起锅，调料可以事先混合方便均匀的撒入#\n6. 好了、完美的一盘香煎小土豆，孩子、女性特别爱吃！喜欢孜然味的还可加入孜然又是另一番味道！#'),(158,'山寨版沙县卤肉蛋','荤菜','五花肉#\n鸡蛋#\n老卤#\n葱姜#\n花椒#\n大料#\n桂皮#\n草果#\n香叶#\n老抽#\n盐#\n小茴香#\n红辣椒#','一大块#\n11个#\n半小碗#\n适量#\n少许#\n2个#\n1个#\n小的2个#\n2片#\n适量#\n适量#\n少许#\n2个#','1. 鸡蛋洗净，和五花肉一起凉水下锅，锅开后，撇去浮沫#\n2. 锅里加入葱姜、花椒、大料、桂皮、草果、香叶、红辣椒、小茴香、盐#\n3. 再倒入老卤一起再次烧开，再根据颜色的深浅加入适当老抽调色#\n4. 鸡蛋熟后捞出剥去外皮，和锅内的卤汤一起倒入电饭煲中，开启煲汤功能进行卤制（这一步也可以不用换锅，直接卤，我是为了省煤气）#\n5. 半小时后即可关掉电源，五花肉好熟。别开盖子焖一夜即可食用，经过一夜的泡制成品特别入味#\n6. 泡了一夜的卤肉、蛋#\n7. 成品图！#\n8. 成品图！#\n9. 成品图！#'),(160,'做法简单，口味儿超赞。啤酒鸭腿','荤菜','鸭腿#\n啤酒#\n大葱#\n姜#\n蒜#\n干辣椒#\n八角#\n生抽#\n老抽#\n糖#\n小葱#','4只#\n1罐#\n少许#\n少许#\n2-3瓣#\n适量，依个人口味添加#\n2-3颗#\n适量#\n适量#\n适量#\n适量#','1. 鸭腿洗净，切块备用#\n2. 冷水入锅，开大火。飞水。放入少许料酒，2片姜。去腥#\n3. 葱姜蒜干辣椒八角洗净切好备用。啤酒准备好#\n4. 锅中放入油，葱姜蒜爆香。#\n5. 干辣椒八角放入锅内继续爆香#\n6. 放入飞水过后的鸭肉。翻炒。时间稍长些。煸出鸭油。颜色金黄就可以啦。#\n7. 依次倒入1勺半生抽，少许老抽，适量糖，盐。稍微翻炒。#\n8. 倒入一罐啤酒。啤酒倒入没过鸭肉一点点就行。大火烧开转中小火焖25～30分钟后，打开锅盖大火收汁儿。#\n9. 出锅装盘，小葱花切碎撒上。即可#'),(161,'萝卜干黄豆咸菜','素菜','萝卜干#\n黄豆#\n盐#\n玉米油#\n花椒粉#\n老抽#','150克#\n100克#\n1小勺#\n1勺#\n3克#\n15克#','1. 清水泡好萝卜干#\n2. 提前泡好黄豆，我制作这款咸菜，只用了一把黄豆，喜欢吃黄豆的多放#\n3. 将萝卜干清洗干净，挤干水分，加黄豆#\n4. 加一勺玉米油，适量的老抽，少许盐，白糖和花椒粉#\n5. 拌好，放蒸锅上#\n6. 上汽后，25分钟左右，时间短黄豆不熟，自己灵活掌握时间#\n7. 成品#\n8. 成品#'),(163,'麻辣豆腐','素菜','豆腐#\n葱、姜、蒜#\n豆瓣酱#\n花椒粒#\n植物油#\n水淀粉#\n鸡精#\n盐#','250g#\n适量#\n适量#\n适量#\n适量#\n适量#\n一点点（不喜欢的可以不加）#\n一点点就好#','1. 准备好材料#\n2. 豆腐在锅中绰一下#\n3. 锅中放油，加豆瓣酱炒一下#\n4. 然后放花椒、葱姜蒜炒出香味#\n5. 放入豆腐炒匀，加少许水烧开后放少许的盐（我因为不太喜欢味精之类的调味料，所以就只放盐）最后放一点玉米淀粉#\n6. 装盘#'),(164,'凉拌就是少油烟【木耳黄瓜】','素菜','黑木耳#\n黄瓜#\n红尖椒#\n姜#\n蒜#\n生抽#\n香醋#\n盐#\n糖#\n鸡精#\n香油#\n橄榄油#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 黑木耳用冷水浸泡2个小时左右至其泡发#\n2. 然后用手撕成小块#\n3. 烧开水，将木耳放入焯烫至水再次烧开，#\n4. 盛出过凉开水沥干待用#\n5. 黄瓜表皮洗净削花刀皮（都去皮也可以的，我这样是为了养眼）然后切小块#\n6. 红尖椒切颗粒，姜和蒜剁成末#\n7. 、将所有材料放入碗中#\n8. 加入调料拌匀，入冰箱冷藏半个小时以上再食用味道最佳。#'),(168,'油爆河虾','荤菜','食用油#\n糖#\n生抽#\n老抽#\n白酒#','#\n#\n#\n#\n#','1. 河虾洗净，沥干水份。#\n2. 食用油大量，旺火烧至 200 度。下河虾，虾壳变红爆裂后迅速捞起。#\n3. 少量食用油，糖、生抽、老抽、白酒，翻炒调汁。将河虾再次倒入，翻炒勾汁，即可起锅。#'),(170,'秘制蒸带鱼','荤菜','带鱼#\n葱#\n姜#\n蒜#\n花椒#\n料酒#\n酱油#\n白糖#\n红糖#\n蚝油#\n米醋#\n盐#','两条#\n适量#\n适量#\n适量#\n适量#\n3勺#\n3勺#\n2勺#\n适量#\n2勺#\n5勺#\n适量#','1. 带鱼洗净，切段儿后放入料酒 花椒 葱 姜 盐 腌制1小时以上#\n2. 平底锅或者电饼铛上倒入适量油 ，油热后将带鱼煎成两面金黄盛出备用#\n3. 调料汁：酱油+料酒+白糖+蚝油+醋 备用#\n4. 炸金黄的带鱼放入盘中后倒入调料汁撒上红糖#\n5. 再放上葱姜蒜#\n6. 热水烧开后上锅蒸30-40分钟（进味儿）也可以蒸10分钟左右#'),(171,'黑椒嫩肩牛排','荤菜','牛排#\n胡萝卜#\n洋葱#\n薯圈#\n西兰花#\n黑椒牛排酱粉#\n水#\n黄油#\n盐#','150g#\n30g#\n50g#\n20g#\n50g#\n20g#\n60g#\n15g#\n2g#','1. 准备好所需材料，胡萝卜切片、西兰花切小朵、洋葱切丝#\n2. 嫩肩牛排解冻，用刀背敲打拍两面使牛排松弛#\n3. 薯圈放入油锅内炸制金黄#\n4. 洋葱放入油锅爆炒#\n5. 西兰花和胡萝卜中加入少量水翻炒#\n6. 将翻炒好的蔬菜混合加入盐继续翻炒下出锅备用#\n7. 锅内加入黄油#\n8. 放入牛排，两分钟后翻面继续煎下出锅装盘#\n9. 将黑椒牛排酱粉加入水调均匀#\n10. 将酱汁倒入锅中，边加热边搅拌至煮开，关火待温热淋在牛排上#\n11. 装盘趁热品藏#'),(173,'猪骨海带汤`','汤','猪骨#\n厚海带#\n姜片#\n料酒#\n盐#\n鸡精#','一根#\n少许#\n#\n#\n#\n#','1. 海带选用稍微厚点的，用清水洗干净，泡发。多清洗几次，以免有沙石。#\n2. 猪骨砍碎，放入锅中加入清水，料酒，焯出血水。#\n3. 把猪骨焯出血水，过冷水稍微洗一下。#\n4. 煲中加大半水，放入焯好血水的猪骨，放三四片姜片。#\n5. 大火烧开，加两勺盐，一勺鸡精，适量料酒，转小火煲一个小时左右。#\n6. 猪骨汤可以煲久点，味道更好，关火前十分钟左右放入海带，海带用剪刀剪成小段再放入，转中火煲一会撒上葱段即可！#\n7. ……#'),(174,'香菇炒鸡胸肉','荤菜','鸡胸肉#\n香菇#\n生抽#\n淀粉#\n料酒#\n姜#\n大蒜#\n葱花#','2条#\n100g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 香菇去根，撕成块，用热水烫一会，捞出沥干水分#\n2. 鸡胸肉切丝，放入料酒.生抽.淀粉，抓匀，腌制备用#\n3. 葱花，姜蒜切丝备用，#\n4. 冷锅放油，烧至六成热#\n5. 下入肉丝，煸炒至变色成出，备用#\n6. 倒入少量油，放入花椒，姜蒜爆香#\n7. 加入香菇翻炒，香菇一定要沥干，因为香菇容易出水，炒至变软#\n8. 加入炒好的肉丝，煸炒，加入酱油，醋，鸡粉，盐少许#\n9. 放入少许清水#\n10. 中火焖至3～5分钟#\n11. 转至大火收汤，加入葱花翻炒片刻，出锅#\n12. 完成品#'),(176,'鲜贝冬瓜汤','汤','冬瓜#\n鲜贝#\n葱#\n姜#\n香菜#\n油#\n盐#\n胡椒粉#\n白酒#','#\n#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 冬瓜洗净一切为二，用挖球器挖出一个个冬瓜球，#\n2. 贝丁加入几滴白酒、少许盐、半勺淀粉腌制#\n3. 锅里烧水，水中放半勺盐，水沸腾后，将冬瓜球放入，焯水2分钟，#\n4. 然后迅速捞出，放凉水中浸泡，然后捞出沥干水#\n5. 锅里放少许油，油热后将葱姜下锅爆香，然后将焯好的冬瓜球放入翻炒，#\n6. 加入半锅开水，依个人口味加少许盐或是不加#\n7. 等冬瓜炖至完全成熟呈半透明时，加入腌制好的贝丁，一分钟后即可关火，#\n8. 加入少许胡椒粉，撒入切段的香菜#'),(178,'鱿鱼须炒洋葱','荤菜','青椒#\n红椒#\n料酒#\n姜蒜#\n干辣椒#\n花椒#\n酱油#\n醋#\n糖#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 切丝备用#\n2. 鱿鱼切断用水焯一下#\n3. 油锅放干辣椒花椒姜蒜爆香#\n4. 放洋葱翻炒#\n5. 洋葱炒熟后再放入鱿鱼须加入酱油醋糖#\n6. 再倒入青红椒#\n7. 加少许耗油，一点盐即可#'),(179,'菠萝熘肉段','荤菜','猪腿肉#\n糖水菠萝#\n油#\n白糖#\n青豆#\n盐#\n生粉#\n料酒#','350g#\n200g#\n100毫升#\n1茶匙#\n30克#\n3克#\n3汤匙#\n1汤匙#','1. 准备食材#\n2. 按照猪肉形状切成片后加入3克盐，1汤匙料酒和2汤匙生粉抓匀，青豆解冻#\n3. 再把一汤匙生粉加入清水拌匀成水淀粉，准备酥香炸粉（可以用面粉或者红薯粉代替）#\n4. 腌制过的肉片沾上酥香炸粉后整成条状#\n5. 热锅倒油温油下入肉段煎炸至变色捞起#\n6. 等油温升高后再入锅炸成金黄色捞起控油#\n7. 另起锅倒入糖水菠萝和青豆大火煮开#\n8. 尝试味道后加入白糖调整酸甜味#\n9. 再把肉段入锅#\n10. 翻炒均匀后加入水淀粉勾芡后熄火出锅#'),(180,'鸡肉炒土豆','荤菜','鸡肉#\n土豆#','#\n#','1. 首先把鸡肉切好洗干净，然后用一点料酒跟姜片搅拌腌10分钟左右。土豆切块放一边#\n2. 接着油锅热好下一点蒜片跟姜一起翻炒，起味后将鸡肉倒入翻炒，鸡肉翻炒炒色时熟了加入酱油翻几遍加去土豆还有适当一点水差不多腌过鸡肉盖上锅盖大火焖煮。#\n3. 焖的同时记得翻下锅，等汁焖的差不多快完的时候下点盐跟红椒还有葱翻炒均匀就可以上桌啦。#'),(181,'冬日暖暖什锦牛肉砂锅','荤菜','干切牛肉#\n牛肉丸#\n大白菜#\n香菜#\n油豆腐#\n西红柿杮#\n香菇#\n金针菇#\n蘑菇#\n平菇#','若干#\n3个#\n适量#\n适量#\n适量#\n2个#\n2朵#\n1小把#\n4朵#\n4朵#','1. 先将西红柿切块，与干切牛肉和丸子在砂锅中煮20分钟，切两片姜，倒点料酒！这样，西红柿便可以软烂，使汤头更醇厚一些。#\n2. 在砂锅煮的过程中，我们将别的菜洗净改刀#\n3. 将油豆腐也切一刀，这样更入味儿#\n4. 当砂锅里西红柿煮烂时，下各种菇类，油豆腐。#\n5. 让菇类先煮一会儿，再下白菜，因为蔬菜类易熟。#\n6. 下各类菜的顺序是按照成熟易难来分别下入。#\n7. 最后所有的菜都熟后，调味儿，放盐，放食用油。最后起锅时撒上香菜茉，也或者葱花之类都行。#'),(184,'杭椒炒鸡蛋#金龙鱼外婆乡小榨菜籽油#','素菜','鸡蛋#\n杭椒#\n菜籽油#\n盐#\n葱花#\n白花椒粉#\n料酒#','3个#\n1根#\n适量#\n2g#\n3g#\n1g#\n10g#','1. 备好食材：菜籽油、鸡蛋和杭椒#\n2. 鸡蛋打入碗中#\n3. 杭椒洗净切小段#\n4. 将杭椒段、料酒、盐、葱花和白胡椒粉放入鸡蛋碗中#\n5. 将其打散备用#\n6. 锅中倒入适量菜籽油#\n7. 中火将油烧热，倒入蛋液先不要翻动，待底面煎好后，再翻面煎#\n8. 煎熟之后可用锅铲将其划成小块即可出锅#\n9. 盛出后趁热吃吧！#\n10. 成品#'),(185,'蜜汁酱烤鸡腿','荤菜','生抽#\n白糖#\n葱姜蒜#\n甜面酱#\n五香粉#\n蜂蜜#\n水#','50g#\n40g#\n适量#\n适量#\n适量#\n30g#\n30g#','1. 把鸡腿划几刀切口以入味，这两只鸡腿衣服自己脱掉了#\n2. 调汁，把除了蜂蜜和水其他的原料都倒在一起#\n3. 放入鸡腿，用手抓匀，放冰箱冷藏一个晚上，如果实在没时间最少腌制4个小时#\n4. 腌好的鸡腿，能看到已经吸收了不少的汤汁#\n5. 烤箱预热，烤架上铺上锡纸，先210度烤10分钟，涂点剩余的腌料，翻面，温度调到200度，烤20分钟即可#\n6. 烤制过程中做蜜汁，把蜂蜜和水倒在锅里加热，等汤汁变得浓稠即可关火，浇在考好的鸡腿上，一款蜜汁酱烤鸡腿完成，味道绝对杠杠滴。#'),(186,'腰果玉米粒','素菜','腰果#\n玉米#\n胡萝卜#\n毛豆#\n蒜蓉#\n花生油#\n盐#\n鸡精#\n五香粉#','80g#\n200g#\n50g#\n50g#\n适量#\n适量#\n适量#\n适量#\n少许#','1. 玉米粒、毛豆洗净，胡萝卜切丁。#\n2. 锅热放油，下腰果，小火不断翻炒至金黄色，撒盐，起锅。#\n3. 原锅放蒜蓉爆香。#\n4. 倒入玉米、胡萝卜和毛豆炒一下，放半碗水煮3、4分钟至玉米熟透，加盐、鸡精、五香粉调味。#\n5. 出锅装盘，拌入之前炒好的腰果。#\n6. 开吃！#'),(187,'洋葱炒牛肉','荤菜','牛肉#\n洋葱#\n胡萝卜、清椒#\n盐、料酒、孜然粉、生抽、水淀粉#','300g#\n半个#\n适量#\n适量#','1. 洋葱、清椒、胡萝卜洗净切丝#\n2. 牛肉洗净切丝，放料酒、盐、生抽、水淀粉，孜然粉搅拌均匀#\n3. 锅热放适量食用油，油温7分热倒入腌好的牛肉炒至变色，出锅装入碗中备用#\n4. 炒牛肉的油留锅中，放洋葱炒香，依次放胡萝卜、清椒丝炒至段生#\n5. 最后放入炒好的牛肉丝，快速翻炒，加些生抽，盐，鸡精调入味立即起锅#'),(188,'排骨莲藕汤','汤','排骨筒子骨#\n藕#\n红枣#\n花椒#\n生姜#\n葱#\n胡萝卜（可加可不加）#\n盐#\n味精#\n胡椒#','2条#\n一筒#\n五颗#\n适量#\n适量#\n适量#\n半只#\n适量#\n适量#\n适量#','1. 排骨 筒子骨 焯水后 放入花椒 生姜 翻炒#\n2. 翻炒两分钟后 加入水#\n3. 水煮开后 放入炖锅 加莲藕 胡萝卜 红枣 葱段#\n4. 两个半小时 完成 加入适量 盐 味精 胡椒#'),(191,'菁选酱油试用之红烧鸡块','荤菜','酱油#\n料酒#\n大蒜#\n生姜#\n食盐#','2汤匙#\n1汤匙#\n2粒#\n4片#\n0.5小匙#','1. 鸡肉切小块，加盐和姜片腌制10分钟。#\n2. 锅下油烧热，放姜蒜爆香。#\n3. 加入鸡块翻炒到肉色变白，转中小火慢慢把鸡皮的油脂煎出来，再加糖翻炒到糖融化，让鸡肉裹上焦糖上色。这个步骤有点像红烧肉里的炒糖色。#\n4. 鸡肉煎炸到变黄变香酥，加入米酒和酱油翻炒几下。#\n5. 加水，大火煮开，转小火焖煮。#\n6. 水快收干后，开大火快速收锅，汁烧干就能上色。#'),(192,'香辣糖醋藕片','素菜','藕#\n辣椒粉#\n陈醋#\n白砂糖#\n姜#\n葱#\n芝麻香油#\n盐#\n大蒜#\n鸡精#','1个#\n1汤勺#\n适量#\n1茶勺#\n适量#\n2根#\n适量#\n适量#\n1瓣#\n适量#','1. 藕去皮，切片，冲洗干净，然后浸泡在放有醋的冷水里，最少泡5分钟以上。#\n2. 姜切末，大蒜切末，葱切葱花，备用一旁。#\n3. 将侵泡好的藕片沥干水分（不要清洗）#\n4. 油下锅，将沥干水分的藕片倒入，放入适量的盐、鸡精、大火翻炒两分钟，捞出沥干油。#\n5. 捞出藕片之后，下姜末、大蒜末、辣椒粉，小火炒香。#\n6. 辣椒粉炒得微焦黄之后，放入葱白、翻炒三秒（小火炒噢）#\n7. 葱白炒三秒，倒入藕片，拌匀，放入白砂糖、陈醋、剩余的葱花，滴几滴芝麻香油拌匀，就可以起锅了。#\n8. 完成?#'),(193,'孜然鸡翅','荤菜','鸡翅#\n孜然粉#\n盐，生抽#\n姜#\n辣椒粉#\n花椒#','#\n#\n#\n#\n#\n#','1. 鸡翅洗净，加入盐，生抽，辣椒粉，姜片，花椒腌半小时#\n2. 油锅放点油烧热至九成，下鸡翅煎至金黄色#\n3. 出锅，摆盘，撒上孜然粉#'),(194,'凉拌豆腐皮','素菜','豆腐皮#\n黄瓜#\n老干妈#\n香菜#','两张#\n一根#\n三勺#\n适量#','1. 豆腐皮，黄瓜洗净，切丝。锅内放入一大碗水，放三勺盐烧开，然后放入豆皮煮开，沥干水。#\n2. 调汁。醋，老干妈，盐，（根据个人口味调整用量），放入豆皮，黄瓜，香菜拌匀，即可。#'),(195,'包菜炒粉丝','素菜','包菜#\n龙口粉丝#\n红辣椒#\n六月鲜酱油#\n糖#\n盐#','1/2棵#\n1团#\n3个#\n少许#\n少许#\n少许#','1. 包菜切丝。#\n2. 一锅水煮开沸腾时倒进切好的包菜丝就立即关火，大约浸泡半分钟就捞出沥水。#\n3. 热油锅里爆炒下辣椒。#\n4. 将包菜丝倒进去翻炒加入适量的糖。因为是干烧所以一定要大火不停的翻炒，以免焦掉。#\n5. 加入泡好沥干水的粉丝继续翻炒。#\n6. 加入生抽翻炒后加盐调味出锅。#'),(197,'春韭菜炒鸡蛋','素菜','春韭菜#\n鸡蛋#\n盐#\n玉米油#','250g#\n2个#\n5g#\n35g#','1. 韭菜择好，洗净，水中加盐浸泡30分钟#\n2. 韭菜切寸段，#\n3. 鸡蛋加盐，打散#\n4. 热锅，倒油，油温6成热时下韭菜#\n5. 倒入鸡蛋液，至鸡蛋液稍凝固，翻炒出锅#\n6. 装盘#\n7. 成品#'),(200,'炸萝卜丸子 松软','素菜','白萝卜#\n泡打粉。#\n面粉#\n鸡蛋#\n五香面#\n盐#\n食用油#\n还可以随意加一些椒盐粉，孜然粉。#','一根#\n#\n一碗#\n一个#\n#\n#\n#\n#','1. 一棵白萝卜擦成丝，加少许盐，用手抓匀腌一会儿。淹十分钟之后，挤出水分。#\n2. 倒入面粉，打入鸡蛋，放盐和五香面。 面粉得分几次倒入，以免一次性到倒多了。为了让丸子更松软，加入半勺泡打粉。#\n3. 搅和均匀。闻味道看咸淡是否合适。#\n4. 锅里倒油，六七分热但是不能冒烟。用勺子舀出一个个小丸子，放入锅里炸，刚放进去的时候先别拨动它。等两面都炸的棕黄色，出锅即可。#\n5. 看，还是不错吧#'),(201,'酸菜粉条','素菜','酸菜#\n粉条#\n肉#\n花椒#\n姜#\n葱蒜#','300g#\n300g#\n100g#\n适量#\n#\n#','1. 粉条用水焯一下，备用，八分熟就可以#\n2. 酸菜切丝用手攥干备用#\n3. 肉切小条备用#\n4. 葱姜切碎！#\n5. 油开，下花椒葱姜爆锅！放入肉条煸炒！然后放入少许海鲜酱油爆一下！放入酸菜，酸菜成团的话，边撕开边放！继续翻炒！#\n6. 放入粉条！盐，少许海鲜酱油调色！继续翻炒，假如很干的话，可以放入少许水，但不要太多！#\n7. 翻炒两分钟，放入味精！就好啦！#'),(203,'快炒辣椒茄子','素菜','茄子#\n辣椒#\n姜葱蒜#','三条#\n一根#\n适量#','1. 油量比平时煮菜稍多点，油烧热，油温高些，入茄条，煸炒。不要过多翻炒，让茄子单面在油中受热。可保持茄子漂亮的颜色。茄子白面微黄入蒜碎。入辣椒，盐，鸡粉，糖，酱油调味。继而翻炒辣椒熟。ok盛盘！两碗米饭#'),(205,'荷兰豆炒百合','素菜','荷兰豆#\n白合#\n干椒#\n盐#\n十三香#\n鸡精#','一盘#\n一小把#\n四个#\n一勺#\n一勺#\n一勺#','1. 食材准备，荷兰豆去两头丝洗干净#\n2. 白合倒入烧了开水的锅里煮十分钟，取出来备用#\n3. 荷兰豆到入开水锅里掉两分钟#\n4. 取出来备用#\n5. 锅里放入适量的油油热放入干椒爆香#\n6. 在倒入掉过热水的荷兰豆#\n7. 加入一勺盐一勺十三香一勺鸡精翻炒均匀#\n8. 最后在加入白合一起翻炒均匀即可出锅#\n9. 不吃辣的少加干椒#'),(207,'【拉歌蒂尼菜谱】酱香锅塌豆腐','荤菜','北豆腐#\n面粉#\n全蛋液#\n葱#\n姜#','#\n#\n#\n#\n#','1. 1、准备好调料。2、把葱姜切成小米粒。豆腐切成长约4厘米，宽约3厘米，宽约1厘米厚的片。3、放到容器中加入葱、姜、盐、料酒，小心用手弄匀。腌制5分钟。4、把豆腐沾上均匀地沾上面粉。#\n2. 5、然后放到蛋液中裹上蛋液。6、锅中入油，烧到六成热，中火豆腐炸约2分钟成金黄色捞出备用。7、油倒出后，锅中加入适量的水入辣面酱拌匀。8、加入豆腐微火慢煨到只留一点底汤，出锅前点入香油即可。#\n3.#'),(209,'青椒与香肠的邂逅～美味香肠炒青椒','荤菜','盐#\n糖#\n葱花#','少许#\n少许#\n少许#','1. 青椒洗净切条#\n2. 香肠～切丝～一定小心，我就切到手了#\n3. 锅烧干，使水蒸发#\n4. 锅中放少许油#\n5. 放入葱花和香肠煸炒#\n6. 加入青椒后翻炒，放糖盐和一点酱油#\n7. 之后盛盘#'),(210,'酸菜花甲鲩鱼煲','荤菜','酸菜150克，花甲300克，鲩鱼块320克，姜一块，水550克，鱼露，生粉少许#\n香菜两根#','#\n#','1. 酸菜用水提前泡上几个小时#\n2. 花甲用水泡吐沙#\n3. 鲩鱼切块用鱼露和生粉腌#\n4. 花甲洗刷干净，用水煮开捞起，水别倒掉，用碗装起#\n5. 酸菜切片用滚水焯一下#\n6. 用一个煲放炉灶上烧热爆姜和酸菜#\n7. 加入煮花甲的水，放鱼块进去煮#\n8. 鱼块八成熟时加入花甲煮开至刚熟关火#\n9. 撒上香菜段即可，不用放盐，鲜酸可口又开胃#'),(212,'红酒焖牛排','荤菜','牛排#\n蘑菇#\n胡萝卜#\n大料#\n大蒜#\n香叶#\n红酒#\n盐#\n鸡精#\n香菜#','500g#\n200g#\n250g#\n2个#\n2瓣#\n2片#\n适量#\n少许#\n少许#\n适量#','1. 大块牛排入冷水过中焯烫#\n2. 洗净待用#\n3. 蘑菇和胡萝卜切小块待用#\n4. 将焯水过的牛排放入瓷煲中，加入大料、香叶和少许蒜片#\n5. 倒入红酒（根据自己口味增减）#\n6. 最后放入蘑菇和胡萝卜以及少许的水（没到材料就好）#\n7. 选择煲汤3-4个小时左右，最后放入调料和香菜就成#'),(213,'五彩串烧法兰肠——久美惠法兰克福香肠试用','荤菜','法兰克福香肠#\n口蘑#\n西兰花#\n红椒#\n青椒#\n黄椒#\n洋葱#\n橄榄油#\n黑胡椒酱#\n盐#','一根#\n三朵#\n六朵#\n1/4个#\n1/4个#\n1/4个#\n小半个#\n适量#\n适量#\n少许#','1. 食材洗洗切切。#\n2. 西兰花焯水断生。#\n3. 串起来~#\n4. 电饼铛里铺锡纸，倒入橄榄油，把串串摆上去，再刷一层橄榄油上去煎。不断翻面使受热均匀。#\n5. 煎熟后撒上黑胡椒酱，研磨黑胡椒和少许盐即可。#'),(214,'苦瓜炒肉片','荤菜','五花肉#\n苦瓜#\n上等蚝油#\n生抽#\n油盐#','100g#\n1根#\n1茶匙#\n1茶匙#\n适量#','1. 苦瓜切开后去瓤，切成薄片，用盐腌制20分钟，再用清水洗净。五花肉切成薄片。#\n2. 锅中倒入少量油，烧至六成热，放入五花肉炒至微焦出油，放入生姜丝稍翻炒。#\n3.  接着放入苦瓜继续中火翻炒。#\n4.  等苦瓜八分熟时，加入上等蚝油、生抽和适量盐炒匀即可。#'),(217,'减脂增肌食谱-西兰花炒鸡胸肉','荤菜','姜#\n盐#\n料酒#\n生抽#','适量#\n适量#\n适量#\n适量#','1. 鸡胸肉切小块，放入生姜，料酒，生抽抓均腌制一会。#\n2. 西兰花切成差不多大小，锅中放水煮沸，放入西兰花焯水2-3分钟，取出用冷水冲一冲。#\n3. 锅烧热，放少许橄榄油（或许食用油也可以）放姜和鸡胸肉，炒至快变成白色，加入焯水后西兰花翻炒，加入少许盐即可出锅。觉得清淡，也可出锅前放入少许蚝油。#'),(220,'肉饼蒸鹌鹑蛋（小鸟巢）','荤菜','碎瘦肉#\n鹌鹑蛋#\n麻油#\n鸡精#\n盐#','200g#\n6个#\n适量#\n少许#\n少许#','1. 碎猪肉加盐鸡精麻油搅拌均匀，腌制10分钟。#\n2. 我做的是6个的量，所以等量分6份，用做蛋挞的模具造型，要按压哦，这样中间会有小窝窝的。#\n3. 然后打个鹌鹑蛋在上面。#\n4. 上蒸锅蒸15分钟就可以了。#\n5. 下面我白灼了点青菜垫底，肉饼脱模，里面的汤汁可以淋在青菜上，味道很鲜美的。加以点缀了下，这样更能哄小朋友哦。#'),(222,'快手菜也可以高大上~～～香菇酿肉','荤菜','五花肉#\n香菇#\n葱花适量#\n胡椒粉#\n耗油#\n老抽#\n淀粉#\n橄榄油#','100g#\n8个#\n#\n少量#\n适量#\n适量#\n适量#\n少量（可不加）#','1. 香菇去根，洗净控干，可以在正面用刀划上十字花；肉剁成泥，放入葱花、少量淀粉、胡椒粉、耗油一勺、盐（口味轻的就不要放了）#\n2. 把肉灌入香菇上，然后冷水上锅蒸，水开后我又继续烧了七分钟。#\n3. 出锅后，会有很多的汤汁，汤汁倒进碗里放入少量的淀粉，老抽，和耗油入锅熬至粘稠状，然后洒入香菜沫关火。蒸香菇的盘子已经不能入目了，所以我又重新摆盘了。#\n4. 最后一步，把熬好的汤汁浇上，OK！#'),(225,'豆皮肉卷','荤菜','肉馅儿#\n葱#\n姜#\n料酒#\n蚝油#\n盐#\n香油#\n生抽#\n十三香#','1斤#\n适量#\n适量#\n少许#\n少许#\n适量#\n少许#\n适量#\n少许#','1. 把所有的配料放入肉馅儿，搅拌均匀。#\n2. 把肉馅儿铺满豆皮#\n3. 卷到三分之一处，两边对折再接着卷起。#\n4. 卷好的肉卷#\n5. 放入蒸锅大火，开锅蒸15分钟。#\n6. 蒸好的肉卷#\n7. 切块就可以食用了。也可以放凉以后冷冻，做汤时随拿随吃。#'),(226,'杏鲍菇木耳黄瓜胡萝卜','素菜','杏鲍菇#\n黄瓜#\n胡萝卜#\n木耳#\n生抽#\n盐#\n蚝油#\n花生油#','1个#\n1个#\n1个#\n1把#\n适量#\n适量#\n1勺#\n适量#','1. 杏鲍菇切片，木耳泡发备用#\n2. 黄瓜，胡萝卜切片备用#\n3. 锅内倒花生油微热，倒入杏鲍菇木耳翻炒，倒入生抽?盐#\n4. ?胡萝卜翻炒#\n5. 最后?蚝油，黄瓜翻炒片刻，入盘#'),(227,'香烤新奥尔良味五花肉','荤菜','五花肉#\n奥尔良腌料#\n水#','500g#\n30g#\n适量#','1. 有人推荐这个极美滋奥尔良调味料，事实证明蛮棒哒～就是第一次做没有掌握好量，所以有点咸了，所以亲们请酌量#\n2. 调料加水稀释，将五花肉切片放进调料水里，注意将五花肉表面均匀抹上腌制，放到冰箱冷藏12小时#\n3. 烤箱预热220度，5分钟，预热后将五花肉放到烤网上共烤制20分钟。每烤五分钟后翻面，快好时勤翻（小贴士  将接渣盘铺上锡纸，接渣盘放到加热管上面，这样便于清理，用烤网可以去除五花肉多余的油脂）#\n4. 香喷喷的奥尔良五花肉烤好啦！很简单吧#\n5. 蒜头～生菜～都是五花肉完美伴侣哟！#'),(228,'孜然牛肉粒','荤菜','牛肉#\n蚝油#\n淀粉#\n酱油#\n盐#\n料酒#\n花椒#\n孜然粉和孜然粒#\n葱#\n姜#\n青红椒#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 青红椒洗净切小块。牛肉切丁，姜切丝，葱切片。#\n2. 牛肉丁中加入料酒、盐、酱油、孜然（粉末+颗粒两种）、淀粉、蚝油、植物油，混合均匀，腌制30分钟左右。#\n3. 锅中放入少许油加热，放入花椒炒至变成黑色时捞出，放葱和姜炒至微微焦黄色，放入腌制好的牛肉翻炒至变色。#\n4. 继续翻炒至牛肉表面变成金黄色时，放入青红椒和孜然粒、孜然粉和少许芝麻翻炒均匀即可。#'),(230,'土豆炖豆角','素菜','土豆#\n油豆角#\n盐#\n味精#\n海鲜酱油#\n生抽#\n大葱#','#\n#\n#\n#\n#\n#\n#','1. 土豆切成块#\n2. 放好油，油开后放入葱花，然后放入豆角#\n3. 豆角炒成翠绿色#\n4. 放入土豆，炒一炒#\n5. 炒好后放入盐，味精，白糖，生抽，十三香～#\n6. 翻炒后，放入水，莫过菜～盖上锅盖，炖到水没了为止～#\n7. 出锅～豆角和土豆都是烂烂的～味道非常好～#'),(231,'#格兰仕爵仕快播波炉之蒜香双色鱼头','荤菜','鱼头#\n油#\n盐#\n红椒#\n青椒#\n大蒜#\n胡椒粉#\n姜片#','一个#\n适量#\n适量#\n4个#\n6个#\n6瓣#\n适量#\n适量#','1. 所有食材准备好#\n2. 青红椒和大蒜剁碎#\n3. 鱼肉破开，背部相连，平铺在盘子里，下面放几片生姜，撒上适量胡椒粉，抹均匀#\n4. 油锅烧热，把一半蒜米和红辣椒一起炒出香味，稍微多放点盐。#\n5. 把炒好的蒜米红辣椒铺在一半的鱼头上。#\n6. 剩下的一半蒜米和青辣椒炒香后，放盐炒匀。#\n7. 铺在另一半鱼头上。#\n8. 把准备好的剁椒鱼头放入微波炉，选择蒸鱼键，微波6分钟即可。#'),(232,'一道朴素清淡素菜----素什锦','素菜','黄花菜#\n香菇#\n大白菜#\n油豆腐#\n盐#\n油#\n蚝油#\n糖#\n鸡精#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n少许#\n少许#','1. 黄花菜，香菇，事先用清泡发#\n2. 大白菜，洗干净切成大小合适寸段#\n3. 油豆腐洗干净#\n4. 腐竹事先用凉水泡软锅里煮开水，下点盐，油，把腐竹放入焯水一会#\n5. 把事先泡发的黄花菜，香菇,也一起放入焯一会#\n6. 热锅热油,下大白菜炒一下#\n7. 把焯过水的黄花菜，香菇,腐竹放入#\n8. 加入蚝油，少许糖,盐，鸡精翻炒均匀，就可以出锅了#'),(234,'虎皮鹌鹑蛋','荤菜','鹌鹑蛋#\n黑木耳#\n姜#\n蒜#\n盐#\n酱油#\n白糖#\n食用油#\n郫县豆瓣#','#\n少许#\n少许#\n少许#\n少许#\n少许#\n少许#\n适量#\n1勺#','1. 鹌鹑蛋入冷水锅煮熟后捞出去壳，晾干。#\n2. 热锅上油，油温5.6成热时，放入晾干水分的鹌鹑蛋。#\n3. .炸至金黄呈虎皮状。#\n4. 捞出控油备用。#\n5. 锅内留少许底油，下姜蒜末爆香。#\n6. 加1勺郫县豆瓣炒出红油，再加入黑木耳略炒。#\n7. 倒入鹌鹑蛋。#\n8. 调入盐，酱油，白糖翻匀小火煮4.5分钟，待鹌鹑蛋入味后大火收汁，撒上葱末翻匀即可。#'),(235,'猪肝菠菜汤','汤','菠菜#\n猪肝#\n生姜#\n清水#\n盐#','400克#\n150克#\n几片#\n4~5碗#\n#','1. 猪肝整块放在清水里泡1个小时，然后切薄片，放进姜片、盐、油、酒拌匀；#\n2. 锅里放水，煮开，放进菠菜灼烫至水开，捞出冲洗一下；#\n3. 锅里烧4~5碗清水，水开后，放进灼烫过的菠菜；大火煮开，用筷子压一下，让全部菠菜都浸在水里；#\n4. 水开后，倒进腌好的猪肝，打开锅盖煮至猪肝变色，夹起猪肝，翻面，再煮至变色后再煮3~5分钟，放盐调味即可。#'),(236,'【羊排萝卜汤】','汤','羊排#\n玉米#\n白萝卜#\n葱#\n姜#\n盐#\n胡椒粉#','600g#\n#\n#\n#\n#\n#\n#','1. 羊排入冷水锅中烧开，去浮沫，然后用冷水清洗干净#\n2. 玉米也切块，姜切片，葱打结#\n3. 萝卜去皮切滚刀状#\n4. 除萝卜外，将焯过的羊排和其他辅料放入砂锅#\n5. 加适量的水烧开，转中小火煲40分钟左右#\n6. 取出葱结，放入萝卜，再次煮20分钟左右，撒点盐、胡椒粉，一碗清爽适合孩子的营养汤就做成了。#'),(237,'凉拌樱桃萝卜','素菜','樱桃萝卜#\n醋#\n白糖#\n香油#\n炒熟的白芝麻#','看你吃多少#\n适量#\n适量#\n适量#\n点缀用 适量#','1. 拔掉。#\n2. 洗干净，就这么一丢丢TaT。#\n3. 萝卜苗也洗干净，切两段。#\n4. 萝卜切片，虽然很小，但是不想腌很久着急着吃，切片方便快速入味。#\n5. 萝卜萝滚水下锅焯一下就捞起来冲凉水。然后稍微挤干一些水分。#\n6. 芝麻炒香。#\n7. 萝卜苗，萝卜放入大碗加入醋、白糖、香油拌一下。摆盘，白芝点缀就可以吃了。#'),(238,'不一样的脆炒大白菜','素菜','大白菜#','300g#','1. 把大白菜横刀切成像这样的小长条。到入大盆中加2汤勺盐用手拌匀。腌制一个小时。也得根据你切白菜的厚度来，切的薄的可以不用那么长时间。#\n2. 腌制好后用清水冲洗滤干水分，锅中烧热油至10成热下白菜爆炒加鸡精起锅。（我腌制的时候放盐比较多，所以炒的时候没有加盐。亲也可以尝一下味道不够再加根据个人口味）#'),(239,'10分钟的小炒菜——肉炒三丁','荤菜','瘦肉#\n玉米粒#\n黄瓜#\n红萝卜#\n盐#\n生抽#\n花生油#','#\n#\n#\n#\n#\n#\n#','1. 肉加生抽，盐，生粉拌匀放着。（我提前弄好一个小时左右了。）红萝卜，黄瓜切丁玉米粒大小。#\n2. 热锅倒入油，下蒜糜，下肉。翻炒变色。加入一点料酒…#\n3. 肉是提前腌制的，所以不会炒老，我就没盛出来了。没腌制的可以盛出来。先下玉米和萝卜。翻炒，一分钟#\n4. 倒入适量的水，闷煮3分钟。#\n5. 倒入黄瓜，再翻炒1分钟#\n6. 加入生抽，盐。炒匀。出锅。#'),(240,'麻辣豆腐','荤菜','豆腐#\n猪肉#\n麻椒#\n青辣椒#\n干辣椒#\n大蒜#\n葱#\n鸡精#\n盐#\n十三香#\n料酒#\n老干妈#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 准备豆腐切片，辣椒切段，葱切末，肉切块。如图。#\n2. 青椒切末。#\n3. 老干妈和麻椒。#\n4. 锅内倒油，放麻椒，炸一会将麻椒捞出，放蒜和肉块翻炒，倒入酱油，翻炒，加入老干妈翻炒，添热水，下干辣椒。#\n5. 下豆腐，放适量盐，鸡精，十三香，料酒，盖盖子中火开始炖。#\n6. 感觉豆腐炖入味了，就放味素出锅装盘，撒青椒末和葱末！#'),(243,'凉拌黄瓜','素菜','黄瓜#\n醋#\n蒜#\n辣椒面#','1根#\n适量#\n1~3颗#\n适量#','1. 将黄瓜切成一颗一颗的。#\n2. 将蒜切成一颗一颗。#\n3. 将黄瓜放入盘子里，倒入醋，放入蒜。#\n4. 放入冰箱里10分钟以上。#\n5. 时间到后拿出撒上辣椒面，完成。#'),(244,'烤里脊肉','荤菜','糖#\n花椒面#','#\n#','1. 猪里脊肉用酱油，糖，花椒面腌制30分钟#\n2. 放入烤箱的架子上，下面用烤盘接好，为了好清理可以在烤盘上铺上烤肉纸#\n3. 烤箱190度只用上火烤15分钟，这样肉中的汁更容易滴下来#\n4. 再翻面烤15分钟#\n5. 直接吃或卷春饼都行#\n6. 欢迎加入交流#'),(245,'苦瓜酿肉','荤菜','小葱#\n酱油#\n色拉油#\n香油#\n盐#','少许#\n适量#\n适量#\n适量#\n适量#','1. 苦瓜洗净切5cm左右的小段；肉馅中加入切好的小葱段、盐、酱油、色拉油、香油，并搅拌均匀#\n2. 把肉馅装进苦瓜段里#\n3. 上锅大火蒸8分钟左右，盖盖子#\n4. 关火闷一会，开盖就是这样啦#\n5. 装进饭盒里，跟黄三三一人一个~#'),(246,'花蛤丝瓜汤','汤','花蛤#\n丝瓜#\n精盐#\n姜#\n葱#\n油#','200克#\n150克#\n适量#\n适量#\n适量#\n适量#','1. 食材。#\n2. 丝瓜去皮，切滚刀块。#\n3. 泡一泡，花蛤洗净。#\n4. 锅里烧开水，加入花蛤。#\n5. 花蛤都开嘴后，捞出来，把汤倒入干净盆里，沉淀一下。#\n6. 锅里入姜葱，炒香。#\n7. 倒入花蛤汤。#\n8. 加入丝瓜块。#\n9. 丝瓜煮熟，加入花蛤。#\n10. 加入盐调味即可，也可以再放点胡椒粉。#\n11. 装碗即可。#'),(247,'黄瓜虾仁','荤菜','虾仁#\n黄瓜#\n胡萝卜#\n葱姜#','300g#\n200g#\n200g#\n适量#','1. 虾仁摘洗干净，去掉沙线，用盐 蛋清 淀粉抓匀。#\n2. 黄瓜切丁#\n3. 胡萝卜切丁#\n4. 葱姜适量#\n5. 凉油，下虾仁滑开。#\n6. 盛出待用。#\n7. 锅放油，爆香葱姜，依次放入胡萝卜丁、黄瓜丁炒熟。#\n8. 成品#'),(248,'芋头蒸排骨','荤菜','豆豉#\n生姜#\n油#\n盐#\n酱油#\n料酒#\n豆豉蒸酱#\n葱#\n生粉#','10克#\n10克#\n5克#\n5克#\n3克#\n2克#\n3克#\n10克#\n5克#','1. 排骨洗干净，沥干水，放盐、酱油、油、料酒腌制15分钟；芋头去皮，洗干净，切小方块。PS：用开水烫一下，再沥干水更好。#\n2. 芋头块放下面，腌制好的排骨放上面，晒上豆豉、姜丝，再把拌均生粉糊淋再上面，再淋一勺豆豉蒸酱#\n3. 适量的清水煮沸，适量的清水煮沸；#\n4. 大火煮沸水，转为中火，蒸25分钟即可；PS：时间与火的大小有关，每个人灶火不同，略有不同。#\n5. 大火煮沸水，转为中火，蒸25分钟即可；PS：时间与火的大小有关，每个人灶火不同，略有不同。#'),(249,'潮州小吃之翻砂芋','素菜','油，糖，葱花#','#','1. 把芋头切条状，放油锅炸熟#\n2. 白糖加水煮稠，记住不需要油，之前的油锅洗干净#\n3. 再把炸熟的芋头放进糖里面，这时火要关小，放进葱花，开始翻啦…………#\n4. 翻啦……,关火，最好拿到有风的地方继续翻#\n5. 边翻边变成雪花#\n6. 呐呐呐，成功啦！味道相当美味！掌声响起#'),(250,'新疆椒麻鸡','荤菜','鸡腿#\n大葱#\n洋葱#\n青椒#\n姜#\n麻椒#\n花椒#\n白胡椒#\n小红椒#\n八角#\n香叶#\n白芷#\n草果#\n桂皮#\n花椒粉#\n太太乐鲜鸡汁#\n藤椒油#\n麻辣油#','2个#\n2个#\n1个#\n1个#\n1小块#\n10g#\n5g#\n5g#\n10g#\n1个#\n3片#\n3块#\n1个#\n1小块#\n5g#\n适量#\n适量#\n依个人口味添加#','1. 鸡腿两只用盐花椒粉涂抹腌制20分钟#\n2. 烧水加，花椒，麻椒，白芷，草果，香叶，桂皮，八角，胡椒，一半小红椒，葱段，姜片，水开加入腌制好的鸡腿，加盐适量大火烧开小火慢炖至九成熟，捞出自然冷却！#\n3. 另一半小红椒切碎炸红辣椒油备用#\n4. 切好洋葱，大葱，青椒备用#\n5. 把凉透了的鸡腿撕成条备用#\n6. 锅里加适量鸡汤加热关火加入切好的大葱，洋葱，青椒倒入撕好的鸡腿里#\n7. 然后加入太太乐鸡汁，藤椒油，麻辣油，自制辣椒油！麻辣鲜香的椒麻鸡就完成了！#\n8. 很美味的#'),(252,'红烧冬瓜#酱香鲜#','素菜','冬瓜#\n食用油#\n味事达酱香鲜酱油#','300g#\n适量#\n适量#','1. 冬瓜去皮掏籽，切成小方块备用#\n2. 锅烧热，倒油，油热，倒入切好的冬瓜翻炒数下，倒入味事达酱香鲜继续翻炒#\n3. 锅内加少许水，继续翻炒数下后盖盖儿，焖烧片刻，待冬瓜收汁完毕关火，起锅盛盘，一道色泽红亮，味道鲜美，赛过红烧肉的红烧冬瓜就呈现在各位眼前#'),(254,'蒜香炒花甲','荤菜','花甲#\n蚝油#\n蒜蓉辣椒酱#\n蒜蓉#\n葱#','随意#\n#\n#\n#\n#','1. 锅里放冷水盖过花甲，盖锅盖，烧水，直至花甲开口，一开口翻几下，一熟马上捞起，沥干水份备用。不问滚太久肉会变老#\n2. 就想这样子开口#\n3. 有空的朋友，也可以把另一半的壳掰掉#\n4. 锅里热油下蒜蓉炒7秒，紧接着下蚝油，辣椒酱，葱跟蒜蓉搅拌均匀后马上下花甲，翻炒均匀即可（这一步一定要快，花甲均匀的把汁裹上就可以关火起锅咯）#'),(255,'清炒莲藕','素菜','嫩莲藕#\n醋#\n蒜瓣#\n葱#','300克#\n一勺#\n1个#\n1跟#','1. 买回来的莲藕切片#\n2. 切好的莲藕沥干水份#\n3. 锅内放油，油热后，加入蒜爆香#\n4. 加入莲藕翻炒，加入盐和一勺醋.#\n5. 侄女已经迫不及待了..#'),(256,'白菜卷','素菜','胡萝卜#\n黑木耳#\n淀粉#\n生抽#\n蚝油#\n盐#\n白糖#\n鸡精#','#\n#\n#\n#\n#\n#\n#\n#','1. 1.白菜去掉白菜帮洗净，2.猪肉、黑木耳，胡萝卜和剩余的白菜帮一起切末，3.加入盐、生抽、蚝油、白糖、鸡精拌匀，4.白菜用热水焯软，5.在案板上铺一张焯好的白菜叶，放上拌好的肉馅，6.全部包好摆在盘中，水开后蒸15分钟，7.倒出蒸白菜的水，加入适量水淀粉，煮开后淋在白菜卷上即可！#'),(260,'红烧肉简单做','荤菜','冰糖#\n生抽#\n八角#\n生姜#\n大蒜#\n醋#','适量#\n3勺#\n一块#\n适量#\n适量#\n1勺#','1. 猪肉洗净，入沸水中焯一遍，洗去浮沫。2.锅内倒油，6成热时加冰糖开小火炒出糖色。3.将肉倒入锅中，翻炒均匀裹上糖色。4.生姜、大蒜切丝和八角一起倒入锅中继续翻炒片刻。5.加3勺生抽，1勺醋和水没过猪肉，大火煮开转小火焖煮40分钟。6.根据个人口味加适量盐，收汤汁后装盘#'),(261,'蒜蓉茄子','素菜','茄子#\n蒜蓉#\n蒸鱼豉油#\n耗油#\n葱花#\n海鲜辣椒#\n盐巴#\n粉丝#\n色拉油#','一个#\n整个大蒜#\n20g#\n一汤匙#\n少许#\n2个#\n点点#\n一把#\n少许#','1. 一个茄子分两半切好，我这里为了尽早蒸熟就用小刀轻轻花成这样了#\n2. 蒜蓉切好，用一点耗油和蒸鱼豉油腌制，把辣椒切好#\n3. 把切好的茄子装盘，上蒸锅蒸10分钟，此时把粉丝用热水泡软#\n4. 蒸得差不多了，就把粉丝剪成小段，平铺在茄子上，稍微放凉一下，此时用炒菜锅把蒜蓉炒一炒大概30秒就可以把蒜蓉捞起来，平铺在粉丝上，在铺好的茄子上淋上耗油和蒸鱼豉油混合的汁，上蒸锅蒸5分钟#\n5. 蒸好后，端出茄子，把炒菜锅里面的油在热一遍，最后淋在茄子上，，撒上葱花，ok！#\n6. 超级好吃！#'),(262,'西兰花炒火腿','素菜','西兰花#\n火腿肠#\n大蒜#\n花椒#','#\n#\n#\n#','1. 买来的西兰花掰成一朵朵，洗干净，然后在热水里把西兰花焯水。两分钟就行咯#\n2. 买来的普通双汇火腿肠切一下~（PS我是不是有点给双汇做广告的嫌疑~嘻嘻）#\n3. 把大蒜切成片…多吃大蒜好，杀菌~#\n4. 锅里放油，先放花椒，然后放火腿 再放大蒜，最后放进去焯好的西兰花翻炒，加盐 白糖 生抽。炒两分钟，OK出锅~（最好用生抽，如果用老抽颜色太深了就，把西兰花本省的绿都给淹没了）#'),(263,'家常麻婆豆腐','素菜','嫩豆腐#\n郫县豆瓣酱#\n葱花#\n肥腊肉#\n蒜瓣#\n生粉#\n生抽#','400g#\n2小勺#\n适量#\n适量#\n3颗#\n2小勺#\n2小勺#','1. 准备材料：葱末、蒜末、肥腊肉、豆瓣酱#\n2. 豆腐用温水泡一下，切成小方块#\n3. 肥肉下锅爆出油后，加入蒜末爆出香味#\n4. 加入豆瓣酱（小火）#\n5. 倒入豆腐，用锅铲轻轻推。切忌切拌！！#\n6. 加入适量清水，盖上锅盖。煮至豆腐里面热透（大概2分钟）#\n7. 勾芡汁：生粉两小勺、生抽2小勺、加入适量水拌均匀。#\n8. 豆腐加热好后，倒入勾芡汁用锅铲轻轻推，汤浓稠既可。#\n9. 出锅撒上葱花既可！不用多说，绝对开胃菜！#'),(265,'油焖大虾','荤菜','青虾#\n葱#\n姜#\n白糖#\n盐#\n生抽#\n花生油#\n白醋#\n料酒#','500g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 从市场买来的青虾一斤。#\n2. 用干净的剪刀剪去虾枪、虾须，去掉沙线，然后加少许料酒腌制一下去腥。#\n3. 葱姜切小段备用。#\n4. 锅热后放入比平时炒菜略多一点的花生油。#\n5. 油热后放入腌制好的虾。#\n6. 待虾的一面变红后放入葱姜丝，然后翻面。#\n7. 倒入由白糖、白醋、生抽、盐调制好的汁，焖2-3分钟左右。#\n8. 看汤汁收的差不多即可出锅开吃了。#'),(268,'红烧带鱼','荤菜','带鱼#\n葱#\n姜#\n料酒#\n酱油#\n糖#\n鸡精#\n醋#','#\n#\n#\n#\n#\n#\n#\n#','1. 带鱼洗净，擦干水份，两面拍上一层薄薄的粉（可以不拍）#\n2. 锅内热油，小火逐次放入带鱼，煸至两面金面取出沥油#\n3. 倒出余油，将带鱼全部放入，放料酒，酱油，糖，加开水没过鱼，放入葱姜，大火烧开后改中火烧至汤汁见干，加入少许醋，颠匀即可起锅。#'),(270,'芹菜肉丝','荤菜','芹菜#\n猪瘦肉#\n油#\n盐#\n生抽#\n姜#\n蒜#\n红椒#\n胡椒粉#\n料酒#','350克#\n250克#\n适量#\n适量#\n适量#\n适量#\n适量#\n1个#\n适量#\n适量#','1. 芹菜去叶留梗，切小段洗净沥干#\n2. 猪瘦肉切丝#\n3. 将切好的瘦肉丝用适量生抽，料酒，胡椒粉，盐腌制10分钟入味#\n4. 姜，蒜准备适量，红椒1个切丝#\n5. 锅内油热后下姜与蒜炒香#\n6. 随后即下肉丝滑散#\n7. 当肉丝变成白色后，将其拔到一边，下芹菜翻炒2分钟#\n8. 把芹菜与肉丝炒匀#\n9. 跟着加入红椒丝翻炒片刻#\n10. 加少许盐调味后即可起锅#'),(272,'香菇炒青菜','素菜','青菜#\n香菇#\n油#\n盐#\n鸡精#','450g#\n350g#\n适量#\n适量#\n适量#','1. 青菜（切去根部）和香菇用小苏打浸泡十分钟#\n2. 香菇洗净切片#\n3. 青菜洗净控水后切段#\n4. 起油锅，加入香菇翻炒至发软后盛出#\n5. 锅里加入适量油（炒青菜油多才好吃）#\n6. 加入青菜快速翻炒几分钟至断生#\n7. 加入适量盐调味#\n8. 加入香菇一起翻炒几分钟#\n9. 炒至青菜熟即可关火，加入适量鸡精翻炒均匀，即可出锅#\n10. 成品图#'),(273,'烤豆腐','素菜','综合烧烤料#\n盐#\n五香粉#\n食用油#','#\n适量#\n#\n#','1. 1.豆腐切片，中间划二刀，为了入味#\n2. 2.将所有配料混合均匀#\n3. 3.豆腐所有面刷油，静置15分钟#\n4. 4.烤盘铺上锡纸，摆上豆腐，烤箱上下200度烤20分钟，再次刷油再烤20分钟#'),(274,'冬笋炒腊肉[简单三部曲]','荤菜','冬笋#\n烟熏腊肉#\n小米椒#\n香芹#\n大蒜#\n姜片#\n油#\n鸡精#','两个#\n5两#\n2根#\n2根#\n3瓣#\n2片#\n1汤匙#\n一茶匙#','1. 冬笋去壳，去掉根部切片，腊肉切片都焯水；姜切丝，小米椒切圈，大蒜切片，香芹切段#\n2. 热油爆香姜丝后，加入小米椒、蒜片翻炒，加入腊肉翻炒出油#\n3. 加入冬笋和鸡精稍微翻炒，起锅前再加入香芹翻两翻，就可以关火啦。#'),(275,'洋葱炒牛肉','荤菜','牛肉#\n洋葱#\n姜#\n青椒#\n红辣子#\n大葱#','250g#\n1颗#\n2块#\n2颗#\n1颗#\n1断#','1. 准备食材牛肉切条控水放入生抽，酱油，盐，糖，料酒，蚝油，淀粉，姜丝腌制10-15分钟洋葱对半切片，青椒，红辣子，大葱切碎备用#\n2. 锅中加油，加热至8成热后，关火，将牛肉和洋葱一起过油撑出注：洋葱先过一遍油可以去除洋葱辛辣味将大葱爆香后加入过好油的牛肉和洋葱，青椒红辣子，生抽，盐，爆炒3分钟出锅#\n3. 洋葱炒牛肉#'),(278,'扣酥肉—捷赛年夜饭','荤菜','五花肉#\n盐#\n红腐乳汁#\n冰糖#\n姜#\n大料#\n葱#\n花椒#\n料酒#\n水量#','1000克#\n6克#\n80毫升#\n8克#\n6片#\n2个#\n8段#\n10粒#\n20毫升#\n1200毫升#','1. 五花肉凉水下锅，加少许料酒，烧开汆烫2分钟，捞出后洗净血沫；#\n2. 锅内放葱、姜等调料，再放入汆烫好的五花肉（皮朝下放入锅内）以及水；#\n3. 盖好锅盖，启动【焖酥肉】功能；#\n4. 烹饪结束，将锅内调料拣出、撇除浮油，肉放入冰箱内；#\n5. 食用时切片，上汽后蒸10分钟左右蒸透，最后淋上汤汁即可#'),(279,'韭菜香菇豆干','素菜','白豆干#\n香菇#\n韭菜#\n花椒#','4块#\n3块#\n适量#\n4颗#','1. 豆干、香菇切丝，韭菜切段#\n2. 将油锅烧热然后放入花椒爆香，放入香菇、豆干、韭菜大火快炒2分钟，放盐出锅#'),(281,'平菇扣西兰花','素菜','西兰花#\n平菇#\n生粉#\n生抽、沙茶粉、盐#\n蒜蓉#','250g#\n200g#\n10g#\n适量#\n2颗#','1. 食材洗干净、西兰花切小朵沥水备用#\n2. 蒜蓉下油锅爆香倒入下西兰花爆炒，加入一点点盐炒均，这样西兰花就有味道，（盐水西兰花）#\n3. 炒好西兰花起锅摆盘#\n4. 调勾芡调料，两勺生抽、生粉适量，蒜蓉炸香。加入小碗水一起调好备用（重口味的朋友可以自己加其它的调料）#\n5. 平菇倒入锅内加入勾芡调料开中火一直拌炒至平菇断生，再加一小勺干贝素炒均即可#\n6. 煮好的平菇勺入摆好的西兰花中间～OK好吃又好看又养生的菜式～#'),(282,'锅包肉','荤菜','猪里脊（若小黄瓜肉更佳）#\n姜#\n胡萝卜#\n盐#\n糖#\n鸡精#\n水淀粉#\n色拉油#\n香菜#\n白醋#','250g#\n一小块#\n半根#\n一茶匙#\n适量#\n适量#\n适量#\n适量#\n少许#\n2勺#','1. 把香菜、姜、胡萝卜洗净切成丝；将肉切片用糖、盐、鸡精腌制10分钟入味备用。#\n2. 用适量清水和色拉油将淀粉拌匀调制成糊状如图。#\n3. 将调好的淀粉糊均匀的裹在腌制好肉上。#\n4. 油锅烧热下入肉片炸至金黄色捞出。#\n5. 将炸好的肉片再次下锅重复快速的炸至一遍，使之口感更加酥嫩。炸至好的肉片。#\n6. 锅内留少许油，将备好的胡萝卜、香菜、姜丝爆香，下入炸好的肉片加入适量白醋和糖同时迅速翻炒收汁片刻。#\n7. 好了，一道美味可口的锅包肉就完成了，可以品尝啰。#'),(283,'低油炸蘑菇','素菜','平菇#\n面粉#\n鸡蛋#\n盐#','500g#\n100g#\n1个#\n10g#','1. 用水焯蘑菇，凉水下锅，煮至沸腾，煮出很多浮沫，单纯用开水烫，感脚里面的脏东西出不来嘿嘿#\n2. 水开后捞出清洗两边，放盐，主要是让蘑菇更好的入味，还能再杀出一部分水#\n3. 调制面糊，放鸡蛋能保证外酥里嫩，一个就够了，再放入适量凉白开搅匀，如果不想制作椒盐的话，面糊里可以放入适量的食盐#\n4. 蘑菇放入面糊中搅匀#\n5. 把蘑菇放入调好的面糊搅匀，油至8成热下锅炸至金黄，就可以了#'),(284,'孜然五香炸排骨','荤菜','肋排#\n葱姜蒜#\n五香粉#\n八角#\n孜然粉#\n料酒#\n味达美（味极鲜）#','250#\n#\n#\n#\n#\n#\n#','1. 肋排剁成小块，加盐、料酒、味达美（味极鲜）、葱姜腌制半小时以上。#\n2. 切好葱花、蒜片、姜片，准备好花椒、干辣椒、八角#\n3. 热锅凉油，将油烧热后，加入辅料爆锅出味儿#\n4. 中小火，加入排骨#\n5. 一面炸好之后，翻到另一面继续炸，基本熟透后，可以改中火稍微炸一分钟上焦色。#\n6. 炸好之后，将锅倾斜放置，把排骨放在一边控油。#\n7. 盛出排骨后，撒上孜然粉、五香粉等任何觉得能够为排骨增色的调料即可。#'),(285,'夏日养生清肠的好选择-鲍汁排骨玉米汤','汤','排骨#\n甜玉米#\n冬瓜#\n胡萝卜（大）#\n鲍鱼汁#\n盐#\n白糖#\n八角#\n葱#\n热水#','400g#\n1根#\n500g#\n1根#\n10ml#\n适量#\n2g#\n1颗#\n适量#\n#','1. 排骨洗净冷水下锅，快煮沸时捞去脏的漂浮物#\n2. 用热水冲洗后加热水和八角入锅中火慢炖，水量宜没过排骨为宜，想多喝些汤那就适当多放些水哈！#\n3. 玉米、胡萝卜削皮洗净切大段，葱切段备用#\n4. 冬瓜切段，我用的是锯齿状的菜刀为了美观些，其实也无所谓啦！#\n5. 排炖二十多分钟后放入冬瓜，玉米和胡萝卜慢炖十几分钟的样子放入白糖、盐和鲍汁即可#\n6. 起锅装盘放葱段装饰下就OK啦！汤汁鲜爆啦！：）多吃些哈！#'),(286,'乌鸡汤','汤','乌鸡#\n山药#\n红枣#\n枸杞#\n大葱段#\n姜片#\n醋#\n盐#','半只#\n250g#\n8颗#\n10颗#\n4段#\n4片#\n少许#\n少许#','1. 红枣8颗，枸杞10颗，泡水里洗洗#\n2. 葱段，姜片少许#\n3. 山药滚刀切块后，不用的话，先放水里以免发黑#\n4. 乌鸡切块#\n5. 乌鸡用热水焯5分钟后，将血沫取出#\n6. 将红枣，枸杞，姜，葱，倒入锅内，大火开后改文火炖90分钟，90分钟后加山药再炖30分钟，关火，加少许山西老陈醋和盐，ok了。#\n7. 成品，怎么样？超补的哦！#'),(288,'夏天来了，自家卤水鸭脚吃起来','荤菜','鸭脚#\n干辣椒#\n老抽#\n盐#\n姜片#\n花椒粒#\n生抽#\n冰糖#\n八角#\n桂皮#\n葱段#','一盒#\n适量#\n适量#\n适量#\n少许#\n适量#\n适量#\n适量#\n适量#\n适量#\n少许#','1. 鸭脚洗干净，稍微减一下指甲，排整齐放砂锅中。加水，刚好淹到鸭脚。#\n2. 大火一边煮，一边放姜片、葱段、花椒粒、干辣椒、盐。老抽调色、生抽调味，继续放几颗冰糖，少许八角和桂皮。#\n3. 水开后，盖上锅盖，小火慢煮30-40分钟。具体时间要看鸭脚的数量，煮到鸭脚上色漂亮，微烂即可。#\n4. 出锅摆盘，撒点芝麻，喜辣的朋友可以沾辣椒粉。#'),(289,'奥尔良烤鸡翅根','荤菜','鸡翅根#\n新奥尔良烤鸡翅料#\n水#','8个#\n35g#\n35g#','1. 1.鸡翅根洗净，沥干水分#\n2. 2. 35g烤肉料中加入等量的35g凉开水,搅拌均匀#\n3. 3.将搅匀的料汁倒入盛鸡翅根的容器中，放冰箱冷藏2小时以上，时间越长越入味#\n4. 4.腌制好的鸡翅从冰箱中取出，将鸡翅根摆到烤架上，把剩余的料汁再重新刷到鸡翅根上；#\n5. 5.烤箱200度预热5分钟，烤架放入中层，烤20分钟，取出再刷一层料汁；#\n6. 6.刷好料汁的鸡翅根翻个面摆放，再烤10分钟左右。#\n7. 成品#'),(291,'爆炒猪肝','荤菜','猪肝#\n辣椒#\n洋葱#\n姜#\n蒜#\n花雕酒#\n淀粉（我用的澄粉）#\n生抽#','200g#\n2个#\n半个#\n#\n#\n#\n#\n#','1. 猪肝泡水洗净，加醋泡10分钟，切薄片，冲水，放入花雕酒（一瓶盖）腌五分钟放入少许淀粉（半汤勺）抓匀，锅里热油，葱姜蒜辣椒爆香，加入十三香，生抽，猪肝爆炒两三分钟.ok鲜嫩爽口无腥味.#'),(292,'凉拌西瓜皮','素菜','西瓜皮#\n豆瓣海椒#\n大蒜#\n醋#\n酱油#\n食用盐#\n花椒油#\n鸡精#\n味精#\n香油#\n老干妈#\n麻油#\n白糖#','适量#\n适量#\n适量#\n少量#\n少量#\n适量#\n适量#\n适量#\n适量#\n适量#\n少量#\n适量#\n少量#','1. 1:将西瓜皮洗净，除去果肉和硬皮。#\n2. 2:把西瓜皮切成丝拌上食用盐等待10分钟把水汁倒掉，用清水冲洗，挤干水分。#\n3. 放入麻油，花椒油，醋，酱油，老干妈，鸡精，味精，白糖，大蒜拌匀。#\n4. 把锅烧热后倒入香油然后放入豆瓣海椒，等待油变成红色就倒入西瓜皮上拌匀。一盘美味的凉拌西瓜皮就大功告成了！#'),(293,'秋葵豆腐番茄色拉','素菜','豆腐#\n秋葵#\n番茄（中）#\n☆麻油#\n☆盐#\n☆芝麻粉#\n☆黑胡椒#\n☆柠檬汁#\n☆鸡精#\n☆鲜酱油#','一块(120g)#\n6根#\n一个#\n适量#\n适量#\n适量#\n适量#\n半个左右#\n适量#\n一小勺#','1. 秋葵盐水烫一分钟冷水冷却后切丁，豆腐，番茄同样切丁。（豆腐最好用老豆腐，不易碎）#\n2. 加入☆调味料，柠檬挤汁加入#\n3. 拌匀即可#\n4. 减肥效果很好哦#'),(295,'螃蟹豆腐煲','荤菜','梭子蟹#\n豆腐#\n葱姜蒜#','2到3只#\n一盒#\n适量#','1. 螃蟹去腮洗干净。#\n2. 葱姜蒜切好备用#\n3. 锅内下油，8分热时下姜和蒜煸出香味，下蟹，翻炒，加黄酒去腥，大概炒到蟹变红，然后加一碗热水，最后加入豆腐。#\n4. 调味加盐味精和一点点糖，最后撒葱花，鲜到眉毛都掉光啦！#'),(296,'蘑菇汤面','主食','平菇#\n鸡蛋#\n面条#\n葱花#','200g#\n2个#\n若干#\n若干#','1. 平菇洗净。放入冷锅热油，翻炒半熟，加入适当水，煮沸。#\n2. 放入适当面条，煮沸，再分别加两次冷水，再煮沸。#\n3. 鸡蛋打散，放入锅中，成蛋花。#\n4. 放入适量盐，鸡精，盛盘，撒上葱花，大功告成！#'),(297,'香辣姜葱爆炒花甲','荤菜','生姜#\n香葱#\n指天椒#\n大蒜#','一块#\n两条#\n四个#\n5瓣#','1. 花甲放入盐水中浸泡半个小时或以上，使其吐尽泥沙；吐完泥沙清洗两遍沥干。#\n2. 把姜、蒜切片，香葱切约一寸的小段，指天椒切碎备用。#\n3. 小饭碗准备好生粉水备用。#\n4. 热锅烧油放入姜蒜指天椒末爆香。#\n5. 跟着放入洗净的花甲大火翻炒，翻炒过程中加入一勺料酒，三勺生抽。#\n6. 最后撒上葱段翻炒，用备好滴生粉水勾芡，再翻炒几下出锅即可。#\n7. 鲜香热辣滴一盘花甲就诞生咯！嘴馋吗，自己动手吧！#'),(298,'M～非油炸版地三鲜','素菜','土豆#\n茄子#\n青椒#\n豆瓣酱，老抽，生抽，盐，白糖，葱花#','#\n#\n#\n#','1. 茄子洗干净期待滚刀块，稍微撒点盐腌一下#\n2. 土豆切块备用#\n3. 青椒切块备用#\n4. 土豆和茄子炸水焯到土豆略透明#\n5. 茄子用刀背稍微压压，把水压出来#\n6. 电饼铛刷油预热#\n7. 土豆和茄子放入煎到表面金黄#\n8. 油锅放一点点油，倒入煎好的土豆茄子，青椒也放进去翻炒#\n9. 加两勺豆瓣酱，半勺糖，一勺生抽，一勺老抽，翻炒均匀#\n10. 出锅#'),(299,'木须肉','荤菜','猪肉里脊#\n鸡蛋#\n木耳#\n黄瓜#\n冬笋#\n酱油#\n姜末#\n油#\n盐#','200g#\n2个#\n80g#\n40g#\n40g#\n2茶匙#\n4g#\n1汤匙#\n1茶匙#','1. 猪里脊肉洗净切成片，用生粉拌匀腌片刻。鸡蛋磕入碗里大赛，黄瓜洗净切片，冬笋剥壳洗净，切片后焯水沥干。#\n2. 锅中放油，烧至五成热时倒入蛋液，待其凝固时用锅铲搅碎，盛出待用。#\n3. 锅中留热油，爆香姜末后放入里脊肉片迅速翻炒至熟，再依次放入木耳、黄瓜、笋片炒2分钟，倒入酱油并加盐翻炒1分钟后方鸡蛋碎炒匀即可。#\n4. 完成了。#'),(300,'黄豆猪手汤','汤','猪手#\n黄豆#\n黄酒#\n姜#\n盐#','1只#\n100克#\n少许#\n少许#\n少许#','1. 所有食材#\n2. 猪手洗净过水，黄豆洗净浸泡#\n3. 锅中放水，放入猪手#\n4. 放入黄豆#\n5. 放入少许姜#\n6. 再放少许黄酒#\n7. 电饭煲按煮汤键至到呜叫保温#\n8. 最后放少许盐即可#'),(301,'剁椒金针菇','素菜','金针菇#\n辣椒#\n生姜#\n蒜#','100g#\n10g#\n1只#\n1只#','1. 金针菇洗净#\n2. 辣椒切小粒#\n3. 姜蒜切碎#\n4. 放入盘中，加盐，酱油，花椒，油，放入锅中#\n5. 蒸10分钟就可以了#'),(302,'炝拌爽口藕片','素菜','鲜藕#\n黄椒#\n莴笋#\n蒜#\n干红辣椒#\n花生#\n花椒#\n盐#\n油#\n白糖#\n生抽#\n醋#','1节#\n半个#\n1/3根#\n2瓣#\n3只#\n少量#\n少许#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备好所需材料，忘了蒜啦；我把花生放烤箱里烤了几分钟去皮香脆；#\n2. 藕削皮洗净切小一点的片，放入白醋水中浸泡以免变黑；#\n3. 黄椒切小片；莴笋去皮切小片；干辣椒切段；蒜切片；#\n4. 藕片入沸水焯1-2分钟捞出沥干；#\n5. 黄椒和莴笋片入沸水稍焯捞出备用；#\n6.  焯好的菜加盐、生抽、白糖、醋拌匀；#\n7. 小锅中倒入油，先爆香花椒出味后去掉，再入干辣椒和蒜片煸出香味；#\n8. 烧好的油浇在拌好的菜上，撒上花生粒即可。#'),(306,'蒜蓉扇贝','荤菜','橄榄油#\n料酒#\n盐#','适量#\n1小匙#\n适量#','1. 将蒜去皮后压成蒜蓉，锅里放少许橄榄油，倒入蒜末，小火煸香，加入盐和料酒炒均匀关火将扇贝清洗干净，放入盘子中，#\n2. 将炒好的蒜蓉均匀的倒入扇贝上，上锅蒸约10分钟左右。蒸好后撒少许葱花装饰即可。#\n3. 撰写制作步骤#'),(307,'扁豆炒肉','荤菜','扁豆#\n五花肉#\n葱#\n姜#\n蒜#\n花椒#\n干辣椒#\n生抽#\n蚝油#\n水或高汤#','200g#\n100g#\n适量#\n2片#\n2瓣#\n少许#\n3～4个#\n适量#\n少许#\n1小碗#','1. 先将五花肉切片 用生抽和蚝油腌制十五分钟#\n2. 扁豆切块#\n3. 葱姜蒜末花椒干辣椒倒入锅中煸炒出香味#\n4. 加入腌好的肉片翻炒 小火炒一到两分钟#\n5. 倒入扁豆翻炒几下#\n6. 加入一小碗高汤或者清水小火 加盖焖十分钟#\n7. 大火收汁出锅 完成#'),(308,'醋溜娃娃菜','素菜','娃娃菜#\n红辣椒#\n醋#\n糖#\n盐#','2棵#\n4个#\n适量#\n适量#\n适量#','1. 准备材料#\n2. 爆香葱#\n3. 煸辣椒#\n4. 炒制#'),(309,'红烧小黄鱼','荤菜','小黄鱼#\n大葱#\n姜#\n大蒜#\n盐#\n白糖#\n生抽#\n陈醋#\n淀粉#','10条#\n#\n#\n#\n#\n#\n#\n#\n#','1. 小黄鱼清理干净，然后加一点儿盐，料酒和大葱腌十分钟左右#\n2. 控干水，加玉米淀粉拌匀。#\n3. 或放油烧到八成热放鱼炸到金黄色捞出来。#\n4. 锅烧热放一点油,加一个大料瓣，葱姜蒜片，爆香。#\n5. 一勺料酒，食盐，白糖，醋，生抽酱油，加一大勺热水，小火炖一会儿，改大火收汁。#\n6. 收汁后装盘就可以享用了。#'),(310,'粉蒸肉#自己做更健康#','荤菜','五花肉#\n蒸肉米粉#\n盐#\n五香粉#\n生抽#\n姜#\n葱#\n料酒#\n土豆#\n鸡粉#','400克#\n100克#\n3克#\n1克#\n3汤匙#\n1块#\n1段#\n1汤匙#\n150克#\n1茶匙#','1. 五花肉里放入盐、料酒、生抽、姜末、鸡粉、五香粉。#\n2. 放入蒸肉米粉抓匀，让每一片肉都裹上米粉，腌30分钟。#\n3. 土豆去皮切粗条。#\n4. 盘底先码上土豆条，再放肉片。#\n5. 放入蒸锅，大火蒸1个小时。#\n6. 蒸好的肉撒葱末即可出锅。#\n7. 酥软咸香的粉蒸肉。#'),(311,'辣酱爆蛏子','荤菜','蛏子#\n小米椒#\n青椒#\n韩式蒜蓉辣酱#\n葱#\n生抽#\n料酒#\n糖#\n油#\n姜#','500克#\n10克#\n1个#\n2汤匙#\n#\n10克#\n#\n#\n#\n#','1. 提前将蛏子用淡盐水浸泡2小时，吐尽沙，捞出沥干。#\n2. 蛏子用料酒水焯一下捞出。#\n3. 青椒洗净斜切成段，蒜、姜切片、小米椒段。#\n4. 锅中倒油，放入葱、姜片炒香，加入青辣椒。#\n5. 把沥干水的蛏子倒进锅里，马上加入料酒，倒入调好的酱汁，大火快速翻炒。#\n6.  因为蛏子用水焯过，所以不用炒太长时间，出锅时放入小米椒。#'),(313,'初春必备酸辣过瘾的开胃菜【韩式泡菜肥牛卷】——菁选酱油试用','荤菜','肥牛卷#\n韩国泡菜#\n金针菇#\n菁选酱油#\n香葱#\n红尖椒#\n绿尖椒#\n高汤或清水#\n橄榄油#\n糖#\n蚝油#\n蕃茄酱#\n韩式辣酱#','300克#\n150克#\n150克#\n适量#\n10克#\n2只#\n2只#\n菁选酱油#\n菁选酱油#\n5克#\n1大勺#\n2大勺#\n1大勺#','1. 金针菇洗净、肥牛卷备好。#\n2. 泡菜切细条，用肥牛把金针菇卷成卷，用香葱捆起来。#\n3. 辣酱和番茄酱、蚝油、糖一起混合，同时把姜、大蒜、香葱切好备用。#\n4. 红绿辣椒切圈，锅里倒入橄榄油。#\n5. 爆香葱姜蒜，倒入混合酱。#\n6. 倒入泡菜翻炒，加入高汤煮开。#\n7. 放入卷好的肥牛卷，盖上锅煮3-5分钟撒上切好的尖辣椒即可。#'),(314,'火锅鱼','荤菜','鱼#\n土豆#\n杏鲍菇#\n香菜#\n葱姜蒜#\n花椒#\n干辣椒#\n火锅料#\n豆粉#\n料酒#\n盐#\n鸡蛋#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 片鱼肉#\n2. 鱼片加盐、料酒、豆粉、蛋清腌制#\n3. 油烧热加葱姜蒜、豆瓣爆香，加火锅料、干辣椒、花椒#\n4. 加水煮开#\n5. 加土豆、杏鲍菇#\n6. 菜煮得差不多时加入鱼肉，记得尝尝味道合适不#\n7. 煮熟后面上撒花椒面、辣椒面#\n8. 少许油烧热，淋在鱼上#\n9. 完成#'),(315,'红烧土豆','素菜','土豆#\n胡萝卜#','250g#\n100g#','1. 油放入锅中爆炒胡萝卜2分钟，然后放入土豆爆炒1分钟，加入酱油翻炒3分钟，，加入少许盐，再加入适量水焖5分钟，翻炒几下最后出锅#'),(317,'小白菜炒滑子菇','素菜','滑子菇#\n小白菜#\n胡萝卜#\n红椒#\n蒜#\n花生油#\n盐#\n酱油#','300g#\n200g#\n适量#\n适量#\n两瓣#\n适量#\n少许#\n适量#','1. 准备食材。#\n2. 热锅放油，放入蒜爆出香味。#\n3. 放入胡萝卜和红椒翻炒几下。#\n4. 放入滑子菇翻炒几下。#\n5. 放入酱油翻炒几下。#\n6. 放入小白菜翻炒几下。#\n7. 放入少许盐。#\n8. 翻炒均匀即可。#\n9. 色彩艳丽，营养丰富的家常菜。#\n10. 再来一张！#'),(318,'油焖笋','素菜','竹笋#\n酱油#\n盐#\n白糖#\n芝麻油#','#\n#\n#\n#\n#','1. 竹笋剥去壳，切去老根，#\n2. 用刀背拍松后切段；#\n3.  热锅入油，#\n4. 油温后倒入笋段煸炒，调入酱油、盐、白糖调味；#\n5.  加入适量清水，中火焖烧15分钟左右，至汤汁收干入味，淋少许芝麻油即可。#'),(320,'炸土豆丝','素菜','材料:#\n土豆#\n盐#\n淀粉#\n胡椒粉#\n植物油#\n鸡蛋#\n糖#','#\n1个#\n适量#\n适量#\n适量#\n适量#\n1个#\n适量#','1. 土豆去皮擦丝。#\n2. 凉水冲洗后，沥干水份。#\n3. 加入一个打散的鸡蛋拌匀。再加入淀粉，盐，糖，胡椒粉，拌匀。腌制10~15分钟。#\n4. 油热后，放入土豆丝，小火慢炸至金黄色捞出。(放入土豆丝后，用筷子打散，防止沾粘。一次不要炸太多，多炸几次)#\n5. 盛盘后根据自己口味加入盐或者糖。#\n6. 成品图。#'),(321,'可乐鸡翅（健康生活）','荤菜','鸡中翅#\n可乐#\n八角#\n葱段#\n料酒#\n姜#','6个#\n1听#\n2个#\n3个#\n1勺#\n4片#','1. 材料切好备用#\n2. 加姜煮沸捞出#\n3. 过凉水#\n4. 用油煎至两面金黄#\n5. 倒入可乐，八角，葱，姜，料酒，还有一勺酱油，大火煮开转小火，待汤汁浓稠即可#\n6. 边看电视边吃鸡翅，巴适#'),(322,'秋葵蒸蛋','荤菜','鸡蛋#\n秋葵#\n水#\n盐#\n生抽#','3个#\n3个#\n适量#\n适量#\n适量#','1. 食材准备，秋葵and鸡蛋。#\n2. 鸡蛋打散，秋葵切片儿。#\n3. 鸡蛋和水混合打匀（体积比1:1.5），加适量盐。#\n4. 用网去掉泡泡。#\n5. 秋葵撒在鸡蛋液中。#\n6. 上蒸锅，蒸15min，切记：不要盖锅盖！#\n7. 出锅啦。#\n8. 可以浇点生抽，下饭棒棒哒。#\n9. 宝宝的话，就吃原味儿哒。#'),(323,'厦门鼓浪屿甜品~花生汤，老少皆宜','甜品','花生#\n红枣#\n冰糖#','250g#\n4颗#\n适量#','1. 花生，加少许泡打粉，或者小苏打，再用开水浸泡至有些发胖，入冷水，一个个去皮#\n2. 加入水，冰糖，熬至花生绵软，加入红枣，再熬制10分钟就可以了，红枣不宜早放，至少影响口感和外相#'),(325,'独家山药排骨煨汤','汤','排骨#\n山药#\n葱蒜姜#\n盐#','#\n#\n#\n#','1. 排骨加水姜蒜少盐，用搪瓷碗提前煨了三四个小时，肉酥软到入口即化了。汤汁用来煮山药，汤烧开后焖煮山药五分钟，脆还是软，看个人喜好了。#\n2. 搪瓷碗的排骨加到山药汤一起煮开，撒葱花。加少许盐出锅。#\n3. 上层的猪油花暂时留着，保温。开吃的时候去掉上层油花。(排骨里有点肥肉)#'),(328,'三分钟做出冬日里的爽口小菜----温拌姜汁菠菜','素菜','生抽#\n陈醋#\n盐#\n白砂糖#\n香油#\n白芝麻#','15ml#\n15ml#\n3g#\n3g#\n2ml#\n3g#','1. 菠菜洗净切去根部，放入沸水中焯半分钟左右#\n2. 捞出后放在容器中沥干水分，静置几分钟#\n3. 期间来处理生姜，将生姜的外皮削掉#\n4. 用研磨器将生姜磨成姜蓉#\n5. 待菠菜不烫手后，挤掉菠菜多余的水分，用刀切成寸段#\n6.  最后将生抽、陈醋、盐、白砂糖、香油、熟芝麻和姜蓉与菠菜混合拌匀即可#'),(330,'千张卷京酱肉丝','荤菜','猪肉丝，蛋清，豆瓣酱，白砂糖，大葱，千张皮#','#','1. 准备原料#\n2. 将蛋清打去肉丝中#\n3. 将裹过蛋清的肉丝炒熟捞出#\n4. 调制豆瓣酱，加入2勺白砂糖炒至沸腾#\n5. 将肉丝再次倒入锅中与酱拌炒#\n6. 将千张皮切成小方片，葱切成丝摆放在盘两侧，将拌炒过酱的肉丝盛至盘中即可#'),(331,'蒸碗小酥肉','荤菜','猪肉#\n排骨汤#\n面粉#\n水淀粉#\n胡椒粉#\n五香粉#\n鸡蛋#\n葱#\n姜#\n八角#\n桂皮#\n香叶#\n生抽#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 猪肉切丝后 加料酒 生粉 胡椒粉腌制#\n2. 鸡蛋 面粉 水淀粉 胡椒粉 五香粉加水搅拌均匀#\n3. 把腌好的肉丝倒入面糊糊中#\n4. 锅里放油 放入裹好面糊的肉丝#\n5. 炸至金黄后捞出沥干#\n6. 倒入蒸碗后 加葱段 姜片 八角 香叶和桂皮 倒入生抽 加两勺排骨汤淹没酥肉#\n7. 上锅蒸15-20分钟就好啦#'),(332,'夏日凉拌菜','素菜','胡萝卜#\n黄瓜#\n千张#\n金针菇#\n莴笋#\n木耳#\n绿豆拉皮#\n大蒜#\n生抽，香醋#\n干辣椒#\n味精#','1根#\n1根#\n1張#\n适量#\n1根#\n少许#\n1张#\n3片#\n适量#\n少许#\n少许#','1. 全部食材#\n2. 所有食材切丝（刨丝），黃瓜丝，莴笋丝放点盐腌制片刻备用，大蒜拍碎成蒜蓉备用。#\n3. 金针菇焯水备用#\n4. 千張木耳焯水备用。#\n5. 胡萝卜焯水备用。#\n6. 摆盘，拉皮放在中间，上面放蒜蓉。#\n7. 调碗汁，碗里放生抽一大勺，醋一大勺，干辣椒几棵，糖适量，味精少许，把油烧热倒入碗中。#\n8. 把所调的碗汁浇在成品上即可。成品图，吃时拌匀。#'),(333,'酸爽腌萝卜','素菜','红皮萝卜#\n糖#\n白醋o#\n盐#','1个#\n若干#\n若干#\n若干#','1. 红皮萝卜不要去皮，切片，码一层撒一点白糖，码好后，加入白醋，大约三分之一，然后放入凉白开，可以先尝下汤味道，觉得味道不够可以加糖，醋，或者白开水稀释，汤汁莫过萝卜，最后撒一撮盐即可，大约一天就可以吃了，红皮萝卜会把萝卜都腌红，比白萝卜好看#'),(334,'香肠炖蛋','荤菜','鸡蛋#\n香肠#\n葱花#','2只#\n1条#\n少量#','1. 打鸡蛋，倒入温水。包上保鲜膜，隔水蒸煮。7分钟后，加入香肠切片继续蒸煮。7分钟，后加入葱花闷一分钟。#'),(335,'可乐鸡腿','荤菜','鸡腿#\n可乐#\n生姜#\n葱段#\n盐#\n八角#','6个#\n适量#\n3g#\n适量#\n适量#\n1个#','1. 准备好食材，都洗干净#\n2. 生姜切片鸡腿上用刀划几道#\n3. 烧一锅水，加入葱姜，盐、再下一个八角#\n4. 煮沸，关火捞出备用#\n5. 另起一锅，加入适量油，油热后下捞出的鸡腿，姜?#\n6. 小火煎到鸡腿发黄#\n7. 加入适量可乐，没过鸡腿就够了#\n8. 大火煮开，中火收汁到比较稠，关火！#\n9. 出锅就好了#\n10. 美腿的诱惑#'),(336,'东北溜肉段','荤菜','猪瘦肉#\n青椒#\n葱#\n姜#\n蒜#\n食盐#\n料酒#\n淀粉#\n鸡蛋#\n酱油#\n醋精#\n白糖#\n鸡粉#\n食用油#','一斤#\n一根#\n少许#\n少许#\n少许#\n少许#\n少许#\n少许#\n一个#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 把瘦肉切成两厘米的小块，也可以切成条状！#\n2. 把一个鸡蛋打散放入搅好的水淀粉，放入料酒，食盐，鸡粉，腌制二十分钟！#\n3. 把腌制好的肉块放入七八分热的油中小火慢炸，炸成金黄色捞出来备用！#\n4. 现在调料汁，调料多少自己掌握。可以尝试，放入水淀粉，白糖，醋精，酱油，料酒鸡粉，切好葱，姜，备用！#\n5. 把肉段在过下油，为了颜色和口感更好，外焦里嫩！#\n6. 锅里放入少许食用油放入姜，青椒快速翻炒，放入炸好的肉段，倒入调好的料汁翻炒，放入蒜末，在翻炒均匀就可以出锅了！#'),(339,'尖椒豆腐皮','素菜','五花肉#\n油豆皮#\n尖椒#\n盐#\n味极鲜酱油#\n味精#\n花椒#\n大料#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备食材，油豆皮切三角，尖椒切长条，肉切片#\n2. 放入油，大约10分热的时间抓紧放入大料花椒，用铲子试下油温#\n3. 放入肉，翻炒着，看着肉大约要变颜色的瞬间放入豆#\n4. 豆皮去锅，翻炒，让豆皮均匀受热，放入酱油，（把酱油倒入勺子不多不少）放入盐#\n5. 放入切好的尖椒，快炒，翻炒，闻到豆皮的香味倒入味精，出锅～#'),(340,'蒜苗酸辣鸡杂','荤菜','新鲜鸡胗#\n蒜苗#\n姜#\n蒜粒#\n朝天椒#\n老抽#\n盐#\n鸡精#','250g#\n5根#\n少量#\n4颗#\n5只#\n#\n#\n#','1. 新鲜的鸡胗清洗干净，切片，加入少许盐，老抽，稍微腌制#\n2. 蒜苗切段，姜，蒜切末#\n3. 事先制作的酸豆角，也可以直接从市面购买#\n4. 朝天椒切碎#\n5. 油锅烧热，将腌制好的鸡胗下锅快速翻炒，变色后盛出待用#\n6. 姜，蒜，辣椒，酸豆角倒入油锅快炒，随后加入鸡胗，翻炒融合以后加入蒜苗，炒至蒜苗断生，加鸡精出锅#\n7. 盛盘#'),(341,'青蒜豆腐','素菜','豆腐#\n蚝油#\n酱油#\n盐巴#\n白糖#\n淀粉#','6块#\n一勺#\n1勺#\n适量#\n适量#\n适量#','1. 备好材料，把酱料加点水调成汁#\n2. 热锅放油煎一下豆腐#\n3. 煎好的豆腐备用#\n4. 留底油下入青蒜翻炒一下#\n5. 倒入煎好的豆腐#\n6. 倒点料酒进去#\n7. 倒点料酒，然后放入调好的酱汁快速翻炒出锅#\n8. 装盘出锅，看着是不是很诱人呀#'),(342,'鲜汁豆腐蒸蛋#美极鲜味汁#','素菜','鸡蛋#\n内酯豆腐#\n盐#\n美极鲜味汁#\n猪油#','2个#\n半盒#\n1小勺#\n2小勺#\n1勺尖#','1. 准备材料，将内脂豆腐均匀铺在蒸碗底部。#\n2. 鸡蛋打散加入两倍于蛋液的温水，加入一勺尖猪油，加入盐调匀。#\n3. 将蛋液倒入铺好豆腐的蒸碗内。#\n4. 上开水锅蒸15分钟左右。#\n5. 出锅在表面再淋上两小勺美极鲜味汁即可。#\n6. 成品。#'),(344,'酸甜可口，百吃不厌——糖醋排骨','荤菜','排骨#\n料酒#\n葱、姜、芝麻#\n香醋#\n生抽#\n老抽#\n白糖#\n精盐#\n鸡精#','500g#\n1.5汤勺#\n少量#\n3汤勺#\n半汤勺#\n1汤勺#\n3汤勺#\n半茶勺#\n半茶勺#','1. 锅中放足量水，加入半汤勺料酒、小葱、姜片烧沸，下入排骨煮四十分钟左右捞出洗净……#\n2. 洗过的排骨沥干水分后、加入1勺料酒、2勺香醋、1勺生抽、半勺老抽调腌渍30分钟入味……#\n3. 炒锅放油，油热下入排骨，将排骨炸至金黄就可……#\n4. 锅内放入刚刚腌制排骨的汁，再加三汤勺白糖、半茶勺盐、一碗肉汤，大火烧开，放入排骨……#\n5. 小火焖十五分钟左右，大火收汁，最后收汁的时候再加一汤匙香醋……#\n6. 临出锅前放入半茶勺鸡精，撒上芝麻和葱花点缀……#'),(345,'番茄豆腐','素菜','盐#\n糖#\n醋#\n北豆腐，硬一点的那种#\n葱#\n水#\n番茄酱#\n油#','#\n#\n#\n#\n#\n#\n#\n#','1. 先把豆腐用水冲一下，然后放入锅中加一点油煎一下#\n2. 切一点葱，放入油锅，出香味就可以#\n3. 调一下番茄酱加点水，盐，糖，醋，喜欢吃辣的还可以加一点辣酱#\n4. 热一下你的酱，然后放入煎好的豆腐，开始入味啦#\n5. 最后盛出来就可以吃啦#'),(346,'茄汁排骨','荤菜','排骨#\n一个番茄可加一点番茄酱#\n糖#\n盐 鸡精#\n蒜丁#','适量#\n#\n两勺#\n适量#\n适量#','1. 煮熟的排骨和番茄糊（料理机打的）#\n2. 蒜丁和青蒜丁#\n3. 锅底倒油烧热煎制#\n4. 等两面金黄转小火 ，把油倒出，锅中有一点底油#\n5. 放蒜丁爆香倒入番茄糊番茄酱和糖，小火熬至浓稠翻匀，可稍放点水淀粉挂糊好看。（（也可以排骨倒出，锅中少放点油爆香蒜丁，倒入番茄糊番茄酱和糖熬成糊，再放一些水淀粉和盐搅匀，倒入排骨翻炒））#\n6. 因煮排骨时放了一点盐所有可以稍微放一点，放鸡精翻匀即可，放青蒜丁点缀#\n7. 是不是很有食欲#'),(347,'蜜汁叉烧','荤菜','猪肉#\n叉烧酱#\n蜂蜜#\n玫瑰露酒#\n生抽#','一块#\n适量#\n适量#\n适量#\n适量#','1. 猪肉洗净，用刀尖在肉上刺小孔，以便入味，再抹上酱汁，放入保鲜盒内冷藏腌制1天1夜取出，#\n2. 腌好的肉放地烤网上，下面用垫了锡纸的烤盘接油，#\n3. 180度60分钟，中途翻面刷酱汁取出继续用剩余的酱汁放保鲜盒再腌一夜，腌肉放垫了锡纸的烤盘上，#\n4. 200度30分钟，中途翻面涂酱汁#'),(348,'香酥炸鸡翅','荤菜','鸡中翅#\n香酥炸鸡配料#','#\n#','1. 鸡翅洗干净，沥干水，在翅膀上用刀戳几个口子，入味#\n2. 料拌入鸡翅膀，搅拌下，其他东西一概不放#\n3. 拿个大点的容器把炸鸡粉拌入，小的容器粉容易洒到外面，拌匀，让每个地方都裹上粉，腌制一会，20分钟左右吧#\n4. 开始炸，火不要太大，中大火，炸至金黄色#\n5. 美味#'),(349,'葱油干豆腐（饭店秘方）','素菜','干豆腐#\n大葱#\n朝天椒#\n东古一品香#','#\n#\n#\n#','1. 把干豆腐、葱切丝，用水焯下干豆腐，一分钟就行，时间久了太软，不好吃。#\n2. 在焯好的干豆腐切丝上放好葱丝儿，放适量的鸡精，少少的盐，因为酱油也有咸味儿。#\n3. 锅里放少一勺半的油，油越多越好吃，要是怕腻建议少放，油开之后，加入切好的朝天椒断儿，闻到香味儿就关火。我个人喜欢老干妈，所以又加了一点老干妈，是绿边的这种油辣椒。#\n4. 把炸好的辣椒油浇在干豆腐上，最后倒上酱油，这时候秘方出现了，其实很简单，就是东古一品鲜，一定是这种酱油，别的都不好吃。#'),(350,'油焖蚕豆','素菜','花椒，八角，姜，葱，#','#','1. 先将蚕豆焯水，然后捞起放凉备用，#\n2. 热锅冷油，将八角生姜葱放油里炒出香味，蚕豆倒入锅中继续炒，加鸡精，盐，糖适量！#\n3. 加入水小火煮开，开大火收汁盛出！#\n4. 锅里加油待油温8成熟放花椒炸出香味，弄出花椒将热油直接浇在蚕豆上！好了收工！！#'),(351,'青椒炒猪腰','荤菜','猪腰子#\n青椒#\n蒜苗#\n盐#\n料酒#\n蚝油#','一个#\n一个#\n适量#\n#\n#\n#','1. 买猪腰的时候叫老板把猪腰处理干净，回来打花刀切好。#\n2. 青椒和蒜苗切好。蒜苗是自家阳台出品，营养不良跟韭菜似的#\n3. 油锅爆香姜片，放入猪腰翻炒，淋入适量料酒，去腥。#\n4. 放入青椒，加盐和蚝油调味。#\n5. 放入蒜苗翻炒，起锅开吃。很下饭呀#\n6. 附上腰花切法：在腰花上切斜刀，注意不要切断。#\n7. 转过90度再切，前两刀不切断，第三刀切断，一片腰花就切好了。不一定要三刀这样的大小，看个人，中心思想就是打XXXX#'),(352,'东北乱炖大丰收','素菜','玉米#\n土豆#\n豆角#\n南瓜#\n排骨#\n油#\n盐#\n花椒粉#\n葱#\n大料#\n豆瓣酱#\n大蒜#\n姜#\n料酒#\n味精#','2个#\n2个#\n300g#\n200g#\n500g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 排骨洗净焯水#\n2. 土豆去皮洗净切块，南瓜去皮洗净切块，豆角洗净#\n3. 切好葱姜蒜，两颗大料#\n4. 热油锅，放入葱姜蒜和大料炒香#\n5. 放入豆角、土豆、南瓜翻炒#\n6. 放入花椒粉炒匀#\n7. 倒入适量酱油炒匀#\n8. 倒入适量料酒炒匀#\n9. 放入焯好的排骨和一大勺豆瓣酱炒匀#\n10. 倒入开水，没过食材即可#\n11. 鲜玉米切小段#\n12. 再放入玉米段，大火炖至食材熟烂#\n13. 汤汁收的差不多时放入适量盐调味#\n14. 最后放入味精即可#'),(354,'可乐琵琶腿（鸡腿）','荤菜','鸡腿#\n葱姜#\n料酒#\n白糖#\n盐#\n酱油#\n可乐#','十根#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 琵琶腿用料酒、葱姜腌制十五分钟#\n2. 热锅不放油放入琵琶腿煎出油脂，蓄水，加葱姜，烧开打浮沫；锅内加与水等量的可乐烧开，盖盖烧十分钟；#\n3. 调盐糖酱油，大火收汁，捡出葱姜即可出锅盛盘。#'),(356,'香芋焖五花肉','荤菜','香芋#\n五花肉#\n姜丝#\n蒜蓉#\n指天椒#\n葱花#','半个#\n适量#\n#\n#\n#\n#','1. 步骤：1  五花肉洗净切薄片，放入烧红油锅爆炒！#\n2. 步骤：2 放入姜丝蒜蓉翻炒！#\n3. 步骤：3  放入备用好的香芋块，加入少许蚝油翻炒均匀！#\n4. 步骤：4  加入凉开水适量关盖焖5分钟！加入指天椒葱花翻炒均匀，关火少许盐即可！#'),(357,'炸茄子','素菜','长茄子#\n面粉#\n淀粉#\n盐#\n黑胡椒粉#\n泡打粉#','一根#\n三勺#\n三勺#\n一平勺#\n适量#\n适量#','1. 长茄子斜刀切1厘米左右的片。（茄子放的时间略长，有些蔫了）#\n2. 3勺面粉，3勺淀粉，1平勺盐，适量黑胡椒粉，少量泡打粉。加水成糊。#\n3. 这个糊有点稀，可以少加点水，比这个再稠一些。#\n4. 锅内适量油，油热后下锅。注意小火，小心糊锅。#\n5. 炸成两面金黄色出锅。（ 盘内垫两张吸油纸 ）开吃?#'),(358,'超级简单酱香炒粉条','素菜','粉条#\n大葱#\n四川担担面酱#','一人份#\n半段#\n适量#','1. 材料准备好#\n2. 热锅，炒酱#\n3. 加粉条，加适量水没过粉条，煮五分钟左右#\n4. 大火收汁，盛出来就可以吃啦#'),(359,'烤箱版--培根金针菇卷','荤菜','培根#\n金针菇#\n椒盐#\n孜然#\n青椒末#\n油#','#\n#\n适量#\n适量#\n适量#\n适量#','1. 金针菇去头洗干净 沥干水，培根切成两半，取适量的金针菇卷起用牙签固定#\n2. 烤盘铺上锡箔纸 备用#\n3. 将卷卷排放整齐（方便刷油）#\n4. 将每个金针菇头尾刷一点点油#\n5. 在撒上孜然和椒盐#\n6. 最后在刷上一点生抽（为了上色）#\n7. 撤上青椒末完成了#\n8. 烤箱预热200°，将做好的培根卷入烤箱烤15分钟，中间翻1至2次（口味重的童鞋可以在翻面的时候在上一次料）#'),(360,'甜蜜素菜—胡萝卜炒洋葱','素菜','胡萝卜#\n洋葱#\n鸡蛋#\n盐#\n酱油#\n淀粉#','1根#\n1个#\n1个#\n#\n#\n#','1. 胡萝卜切片#\n2. 进而切丝#\n3. 洋葱先切一半再切丝，稍微冻一下会不呛眼睛。#\n4. 打鸡蛋放入适量盐，如喜欢也可加少许淀粉和水。#\n5. 锅中热油倒入鸡蛋后，不断顺一个方向滑动铲子形成鸡蛋花。#\n6. 锅中放油先后放入洋葱、胡萝卜、鸡蛋翻炒，调入适量盐出锅即可（如喜欢酱油味道也可放入适量生抽，但不要太多，影响颜色和事物本身香气）#'),(361,'麻辣秘制小龙虾','荤菜','小龙虾#\n啤酒#\n麻椒，干辣椒#\n葱，蒜，姜，郫县豆瓣酱#\n糖，盐，#','500g#\n一听#\n大量#\n适量#\n适量#','1. 买回来去除虾线，虾尾中间那个，用牙刷刷干净#\n2. 刷干净洗干净备用#\n3. yu锅内放油，放入郫县豆瓣酱，炒出红油，放入麻椒，干辣椒，香叶，放入洗干净小龙虾，翻炒几下，看龙虾变色，倒入啤酒，加入盐，#\n4. 大火炖至烫收干净，放入小米辣，加入糖，香葱，#\n5. 烫收干，出锅#'),(362,'粥的完美搭配～炸豆腐','素菜','豆腐#\n花椒，大料，盐，#','一斤#\n适量#','1. 豆腐切厚片#\n2. 准备花椒，大料，葱（可以选择不放）#\n3. 放入油锅炸到两面焦黄#\n4. 这是炸好的样子#\n5. 锅里放入准备好的花椒，大料，放入盐做开，煮两三分钟，#\n6. 关火，把炸好的豆腐放进去泡几个小时就好啦#\n7. 外焦里嫩，豆香四溢，配上一碗稀饭，好好吃，#'),(363,'土豆香菇黄焖鸡','荤菜','鸡肉 300克#\n土豆一个#\n香菇#\n姜#\n大蒜#\n大葱#','#\n#\n5个#\n5块#\n5颗#\n2颗#','1. 鸡肉洗干净之后滤水#\n2. 土豆切块，香菇用水泡十分钟发起之后滤水#\n3. 姜切片，蒜切开即可#\n4. 葱切段起锅时用#\n5. 锅放油，下蒜和姜爆香，然后加入鸡块，炒些许以后加入生抽，老抽上色，再炒至一到两分钟，然后加热水没过鸡肉，等水开了以后加入香菇至水翻滚再然后放入土豆，（如果想要汤汁多一点可以多加一点水），大火转小火以后焖锅20分钟，待土豆熟透即可放入盐，然后起锅！#'),(364,'鱼香肉丝。','荤菜','里脊肉#\n木耳#\n胡萝卜#\n青椒#\n葱#\n姜#\n蒜#\n淀粉#\n豆辨酱#\n盐#\n生抽#\n醋#\n料酒#\n糖#','400g#\n50g#\n50g#\n1个#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 肉丝加盐料酒，1勺淀粉，抓拌均匀。#\n2. 拌好的肉丝，再加一勺油，（锁住水分）葱姜蒜切末。胡萝卜木耳青椒切丝。#\n3. 准备好料汁。盐、生抽、醋、糖、淀粉、和2勺水#\n4. 锅内放油，烧至四成热放入腌好的肉丝，快速滑炒至发白，装盘备用。#\n5. 锅里的余油煸香葱姜蒜，加入一勺豆瓣酱煸香。#\n6. 放入三丝快速煸炒。#\n7. 放入肉丝和料汁翻炒均匀。#\n8. 味道还真可以，赶紧来碗米饭。#'),(365,'番茄酱鸡翅','荤菜','鸡翅#\n番茄酱#\n白糖#\n盐#\n蒜#\n姜#\n葱#\n桂皮#\n八角#\n花椒#','10个#\n一瓶#\n少许#\n少许#\n#\n#\n少许#\n少许#\n#\n#','1. 先将鸡翅洗净，在鸡翅上切花刀以便入味！！#\n2. 锅内水烧开后放入鸡翅，加香料桂皮，八角，花椒煮至九成熟捞出备用！！#\n3. 锅内油烧热，放入葱姜蒜炒香，倒入番茄酱翻炒，后加少许白糖炒匀即可！#\n4. 倒入鸡翅翻炒，然后倒入水熬炖至收汁即可！#\n5. 出锅！#'),(366,'【最佳鸡肉料理】葱香麻油鸡','荤菜','盐#\n胡椒粉#\n料酒#\n葱#\n黄油#','#\n#\n#\n#\n少许#','1. 鸡上腿用料酒 盐 糖 胡椒粉 一根葱 麻油腌制半小时#\n2. 用小板半块黄油煎至两面金黄 多次添加麻油#\n3. 撒上葱花 入微波炉中火10分钟 香味出来即可#'),(367,'豆鼓蒸鱼片','荤菜','龙利鱼#\n草鱼#\n红薯粉#\n姜片#\n葱#\n小米椒#\n干豆鼓#\n蒸鱼鼓油#\n黑胡椒#\n盐#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 1 把鱼片成鱼片 用红薯粉 少量盐 黑胡椒 少许料酒抓匀腌制十分钟2 生姜 葱 青椒 切丝 3 盘子内铺几片姜 把腌好的鱼铺上4 沸水里蒸7-8分钟5 把水倒掉加入蒸鱼鼓油 把配菜铺在鱼片上6一勺热油浇上 就完成了#'),(368,'孔雀开屏鱼','荤菜','武昌鱼#\n葱#\n姜#\n蒜#\n小红辣椒#\n蒸鱼豉油#\n黑胡椒粉#','1条#\n1截#\n1块#\n3瓣#\n4个#\n2大勺#\n少许#','1. 盘中首先铺入葱、姜丝；#\n2. 放入鱼，摆成孔雀开屏状，再摆入鱼头和鱼尾；#\n3. 点缀小红辣椒；#\n4. 均匀加入蒸鱼豉油；#\n5. 撒少许现磨黑胡椒粉；#\n6. 微波可用蒸锅底部加入1/3水，放入蒸笼，将盘子放入蒸笼内，送入微波炉，按下蒸鱼档即可（中高火，18分钟）。#'),(371,'快手炒羊肉（只需三种料无膻味）','荤菜','京葱#\n羊肉#\n郫县豆瓣酱#','1根#\n300g#\n1勺#','1. 京葱洗干净切好，只要葱白，这玩意切的我眼泪汪汪的～#\n2. 羊肉切片～要稍微厚一点3mm左右～不然易碎～（如果是生的羊肉卷的话，就入水抄一下）#\n3. 锅内倒油，挖一小勺豆瓣酱，炒下，倒入京葱翻炒。#\n4. 炒出香味后倒入羊肉，煸炒2分钟左右，出香味就好了～加点糖调味～出锅～好吃到飞起来啊～#'),(372,'养生芦菔（蚝油白萝卜）','素菜','白萝卜#\n热水#\n白糖#\n蚝油#\n酱油#\n香葱#\n盐#','1根#\n1cup#\n1茶匙#\n1汤匙#\n1/2汤匙#\n1根#\n少许#','1. 白萝卜一根，去皮（大约655g），切小条。#\n2. 泡凉水里20分钟，可去白萝卜的味道。#\n3. 沥干水分。#\n4. 中大火热锅倒油，下入白萝卜，翻炒。#\n5. 放入糖1茶匙，翻炒片刻。#\n6. 放入蚝油1汤匙，继续炒。#\n7. 炒至萝卜均匀上色，倒入一杯热水。#\n8. 盖盖小火20分钟。汤汁收的差不多的时候放入酱油，盐少许（可以尝尝看如果口淡的酱油倒完味道就行了；口重的再加入少许盐）。#\n9. 出锅前将切碎的香葱加入即可收汁乘盘。#'),(373,'栗子烧鸡','荤菜','鸡#\n栗子#\n葱#\n姜#\n盐#\n糖#\n鸡精#\n料酒#\n李锦记红烧汁#','半只#\n300g#\n适量#\n适量#\n少许#\n适量#\n适量#\n适量#\n适量#','1. 鸡洗净沥干水分切块备用，栗子去壳剥开备用。#\n2. 冷锅热油，带油热后倒入切好的鸡块翻炒。#\n3. 再倒入栗子翻炒。#\n4. 倒入葱段，姜片和水一起煮烂。#\n5. 加入适量的料酒和李锦记红烧汁，再加入适量的水一起煮，根据自己口味加入适量的盐，糖和鸡精调味，大约再煮半小时就可以了。#\n6. 收干汁水后出锅装盘。#\n7. 好吃的栗子烧鸡就做好了。#'),(374,'酥油蘑菇是绝配！酥油煎口蘑','素菜','口蘑#\n酥油（黄油）#\n盐#\n黑胡椒粉#','5个#\n3g#\n少许#\n少许#','1. 新鲜口蘑洗净，把蒂拔出来#\n2. 平底锅烧热放一块酥油#\n3. 先把口蘑背面煎出一圈金黄出来#\n4. 再翻过来煎正面。大概五分钟左右。#\n5. 口蘑里面会充满汤汁！撒点盐和黑胡椒粉在上面，就可以起锅装盘啦。#\n6. 真是无比鲜美啊！瞬间吃完！#\n7. 看看#\n8. 吃完后的碟子#'),(375,'咖喱牛肉','荤菜','牛里脊#\n胡萝卜#\n土豆#\n洋葱#\n大葱#\n咖喱#','250g#\n适量#\n一个#\n半个#\n半根#\n三块#','1. 准备好食材，洗净备用#\n2. 牛里脊过水#\n3. 大葱切段#\n4. 土豆、胡萝卜、洋葱切块儿#\n5. 过水后里脊肉切小块#\n6. 大葱入油锅#\n7. 牛肉放入，加料酒、盐翻炒#\n8. 加一大碗水、煮开后去浮物#\n9. 放入炖锅中，转至小火炖，水不够的话适量加#\n10. 再把其他食材过下油锅，翻炒均匀，出锅待用#\n11. 牛肉炖一个半小时后，把土豆等加入#\n12. 炖半个小时后加三块咖喱#\n13. 小火炖15分钟#\n14. 关火后即可食用#\n15. 天气冷的话，盖住保温#'),(377,'香煎豆腐','素菜','卤水豆腐#\n盐#\n酱油#\n耗油#\n鸡精#\n香油#\n小米椒#\n葱#\n油#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 豆腐放盐水中浸泡十分钟左右，沥干水，切片，不要太薄，易碎。#\n2. 锅中热油，放入豆腐先煎一面。#\n3. 翻过来煎另一面，直至金黄。#\n4. 盛出备用。#\n5. 辣椒、葱切末。（家里没有小米椒了用干辣椒代替）#\n6. 再热油锅，放入辣椒和葱末爆香。#\n7. 倒入煎好的豆腐，加酱油、耗油、盐和鸡精调味，炒匀即可，出锅前滴几滴香油拌匀。#\n8. 开吃！#'),(378,'闽南特色-醋肉#自己做更健康#','荤菜','姜#\n蒜#\n酱油#\n油#\n地瓜粉#\n盐，味精#','几片#\n两瓣#\n若干#\n适量#\n适量#\n少许#','1. 准备新鲜瘦肉#\n2. 肉切片加入酱油#\n3. 加入盐和白糖适量#\n4. 加入香醋#\n5. 抓匀后放30分钟，以便调料能入味#\n6. 加地瓜粉，记得要多些，这样才能完全包裹瘦肉#\n7. 慢慢抓匀，开始的时候会觉得有点干，慢慢抓一会就好了，如果会干，可加一点点水#\n8. 锅中热油，油7成热时，依次下入肉片。（肉片在抓的时候会裹成一团，下锅时要稍微打开）#\n9. 炸至肉片表面金黄时捞出，用吸油纸吸干油份#\n10. 装盘上桌了#'),(379,'#夏日素食#豆角香干','素菜','豆角#\n香干#\n独头蒜#\n食用油，盐，生抽，芝麻油#','200克#\n200克#\n2个#\n少许#','1. 豆角洗净切成3厘米长的段。锅中烧开水，加少许食用油和盐，倒入豆角，煮3分钟至熟。捞出豆角，盛入碗中。#\n2. 香干切成0.5厘米厚的片，放进开水锅里，煮2分钟至熟。捞出香干，放入碗中。#\n3. 把独头蒜用刀背拍成蒜泥，放入碗中，再加入适量的盐，生抽，芝麻油。用筷子拌匀装盘即可。#'),(380,'话梅排骨烧土豆','荤菜','肋排#\n土豆#\n话梅#\n蒜瓣#\n盐#\n油#\n酱油#\n老抽#\n鸡粉#\n白糖#','300克#\n1个#\n3个#\n4个#\n适量#\n适量#\n2汤匙#\n半汤匙#\n少许#\n少许#','1. 肋排洗净斩段，蒜瓣去皮、土豆去皮切块、取出话梅。#\n2. 热锅，放适量油，爆香蒜瓣。#\n3. 放入排骨煎制片刻。#\n4. 两面煎至焦黄色。#\n5. 倒入酱油。老抽。#\n6. 少许白糖，翻炒均匀。#\n7. 倒入土豆块，端起平底锅抛炒几下。#\n8. 加上话梅，继续翻炒。#\n9. 倒入1碗左右的清水，拌匀。#\n10. 遮上锅盖，大火煮开后调成中火焖煮20分钟左右。#\n11. 酱汁收干后调入盐，鸡粉、翻炒均匀即可。#\n12. 装盆~#'),(381,'黑木耳炒肉','荤菜','黑木耳#\n肉片#\n灯笼椒#\n姜丝#\n蒜片#\n葱末#','300g#\n300g#\n一个#\n#\n#\n#','1. 所有材料都切好#\n2. 热锅，用肥肉炸出油#\n3. 放姜丝蒜片#\n4. 放肉炒，放酱油，炒至七分熟盛出来#\n5. 放辣椒炒#\n6. 放入黑木耳，炒熟后放入肉#\n7. 出锅时放入盐鸡精即可#'),(382,'千丝万缕-秘制拌千张','素菜','千张#\n米酒#\n大蒜#\n干红椒#\n糖#\n盐#\n醋#\n生抽#\n食用油#','若干#\n两勺#\n若干#\n适量#\n适量#\n适量#\n五勺#\n适量#\n适量#','1. 千张切丝#\n2. 水里加盐把千张煮熟捞起晾开，晾干水份。（可以适当多加一些盐，好入味）#\n3. 油烧至八成热加干辣椒，蒜炒香，再次醋和生抽倒进热锅里煮一煮，把剩下的调料倒进去。#\n4. 关火后，等调料凉一会后把晾好的千张倒进拌一拌，起锅装盘，撒上葱花。#\n5. 吃一口。#'),(383,'清炒油菜','素菜','油菜#\n干红椒段#\n大葱#\n淀粉#','适量#\n适量#\n一根#\n一小勺#','1. 油菜洗净，葱斜刀切段，#\n2. 碗中放入一小勺淀粉，倒入两勺温水和一勺凉拌酱油，搅拌均匀，待用。#\n3. 锅中倒去少许食用油，待油烧至6成熟，放入干红椒段爆锅，5-6秒后放入油菜，大火快速翻炒。#\n4. 放入适量花椒粉，胡椒粉，翻炒1-2分钟均匀后倒去事先搅拌均匀的淀粉（注意在翻炒过程中不要将油菜炒断，同一方向翻炒即可），1-2分钟后即可出锅，出锅前放入少许鸡精体味，并大火收汁。#'),(385,'有机花菜炒肉片','荤菜','五花肉#\n有机花菜#\n豆瓣酱#\n料酒#\n酱油#\n盐#','200g#\n1颗#\n1勺#\n适量#\n适量#\n适量#','1. 五花肉切片。#\n2. 花菜折块，放在盐水中浸泡。#\n3. 锅中倒油，倒入五花肉片，煸炒至两面金黄盛出备用。#\n4. 锅中留油，倒入一勺豆瓣酱煸香。#\n5. 倒入花菜翻炒，淋少许水。#\n6. 倒入炒好的肉片一起翻炒。#\n7. 加少许酱油着色。#\n8. 最后放盐翻炒数下即可出锅。#'),(386,'香橙炖蛋','甜品','橙子，鸡蛋，白糖，牛奶#','#','1. 把橙子切开果肉挖出，鸡蛋打散，加入白糖，橙肉，牛奶搅拌均匀，#\n2. 把调好的蛋液放入微波炉中高火三分钟取出后放入之前的橙皮里就好了！#'),(387,'蚝油杏鲍菇','素菜','杏鲍菇#\n蚝油#\n盐#\n生抽#','3颗#\n2勺#\n少许#\n1勺#','1. 将杏鲍菇洗干净，一分为二，然后切片备用#\n2. 锅里热上油，待油热后，将杏鲍菇入锅煎炒，2分钟左右#\n3. 然后加入蚝油，生抽和盐继续翻炒，此时杏鲍菇会出汤，盖盖焖2分钟左右。待杏鲍菇熟了即可出锅#'),(388,'洋葱、午餐肉、土豆的给合','荤菜','洋葱#\n午餐肉#\n土豆#','两粒#\n半个#\n一个#','1. 土豆和午餐肉切成大拇指头大小的小粒状，洋葱一分为六的切成块状并撕开一块块。#\n2. 土豆和午餐肉煎成四面金黄，土豆要先煎，然后放在盘子里盖上盖子给它回软#\n3. 等土豆凉了回软后，锅内少许油先炒洋葱块至软。#\n4. 这样就可以了#\n5. 把午餐肉和土豆倒回锅炒匀，用手撒一点点水炝一下锅焖十来秒后开盖撒少许盐炒匀后出锅！#\n6. 撒少许水焖半分钟样子。#\n7. 放盐炒匀#\n8. 装盘，香！#'),(389,'#鲜动生活甘草羊#羊肉炖萝卜','荤菜','羊肉#\n白萝卜#\n料酒#\n盐#\n红枣#\n胡椒粉#\n葱#\n枸杞#','750克#\n300可#\n适量#\n适量#\n3颗#\n适量#\n适量#\n适量#','1. 羊肉洗净后在凉水中煮开，放料酒去腥，捞出冲洗干净#\n2. 放入锅中，再放料酒#\n3. 放几颗红枣，放没过羊肉的开水大火煮开后改小火#\n4. 白萝卜去皮切块#\n5. 等羊肉酥烂后放入白萝卜，煮开后放盐#\n6. 煮到萝卜透明后放入枸杞#\n7. 出锅前撒上胡椒粉、葱花即可#\n8. 鲜美#'),(390,'电饼铛孜然鸡肉串','荤菜','鸡腿#\n竹签#\n盐#\n料酒#\n蚝油#\n胡椒粉#\n黄豆酱#\n孜然粉#\n玉米淀粉#\n食用油#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1.  鸡腿和竹签。#\n2.   鸡腿去骨。#\n3.  竹签洗净，鸡腿肉切块用盐，料酒，胡椒粉，蚝油，少许食用油，玉米淀粉腌20分钟#\n4.  串好肉串。#\n5.  饼铛倒少许油，加热后放入肉串。#\n6.  煎肉串时要勤翻动。肉串煎至颜色金黄后刷点黄豆酱，因为没有甜面酱啦。#\n7.  撒孜然粉即可。#\n8. 电饼铛煎肉串，少油无烟，非常健康。#'),(391,'不上火的锅巴肉片！','荤菜','锅巴#\n红椒#\n肉丝#\n胡萝卜#\n调料#','#\n#\n#\n#\n#','1. 锅内爆香一些大料#\n2. 把裹上嫩肉粉 少量盐腌制十分钟后的猪肉丝倒入锅内#\n3. 锅内入少量生抽 蚝油 果醋 白胡椒粉#\n4. 炒一会之后入红椒哦啊哦胡萝卜 牛肉酱（肉丝一定要爆炒一期 才能鲜嫩）#\n5. 入锅巴快速 小动作翻炒入味（尽量不要弄散）#\n6. 把锅巴产出锅 放在盘子内，洗锅加少量水 盐 烧沸 放少量葱花#\n7. 再起锅烧热一点香油（可放花椒 然后捞出 留香）#\n8. 先将汤倒入盘中 再淋入热油，吱吱啦啦的飘香养胃的锅巴来咯！#'),(392,'茄子烧豆角','素菜','茄子#\n豆角#\n蚝油#\n生抽#\n大蒜#\n干辣椒#','两个#\n十根#\n两汤匙#\n一汤匙#\n两瓣#\n3个#','1. 茄子切长条，豆角切段，辣椒和大蒜都分别切小备用。#\n2. 锅里放油，煎茄子，可稍多一点，茄子比较吃油。#\n3. 煎到茄子全部变软。#\n4. 盛出备用。#\n5. 下入豆角煎制。#\n6. 煎到表面略有焦焦的，即可。#\n7. 锅里留少量油，爆香大蒜末。#\n8. 辣椒容易糊，晚一点放。#\n9. 闻到辣椒香味立即把茄子豆角重新倒入锅里。#\n10. 加小半碗水。#\n11. 放入蚝油，生抽，略煮收汁，即可出锅。#'),(393,'拔丝香蕉','甜品','香蕉#\n鸡蛋#\n面粉#\n白糖#','2根#\n1个#\n少许#\n适量#','1. 将准备的2根香蕉切成块。#\n2. 将鸡蛋和面粉放入香蕉里面，拌匀。#\n3. 在把油倒入锅里面，待油熟之后放入香蕉，待香蕉成为金黄色，捞出放入盘里。#\n4. 将炸好的香蕉，放入盘里，再倒入一点油到锅里，待油熟以后放入白糖，白糖熬成黄色以后，倒入炸好的香蕉就可以了。#\n5. 翻炒以后就会有丝出来，这道菜就完成了。#'),(394,'鱼香三丝','荤菜','黑木耳#\n豆鼓#\n白糖#\n醋#\n老抽#\n味极鲜#\n耗油#','一撮#\n一大勺#\n一勺#\n1勺#\n半勺#\n1勺#\n1勺#','1. 胡萝卜切丝，黑木耳泡发切丝，杏鲍菇切丝，有时间的话最好手撕成丝#\n2. 杏鲍菇丝下锅，小火干煸至变软，成出#\n3. 锅里放油，放豆鼓适量辣椒面炒香，里面的葱蒜末看个人喜好#\n4. 先放萝卜丝炒软#\n5. 加木耳继续炒#\n6. 放入杏鲍菇丝，和调好的汁（#'),(395,'自制虾滑','荤菜','南极虾#\n淀粉#\n黑胡椒#\n盐#\n食用油#','30个#\n适量#\n少量#\n少量#\n少许#','1. 将虾洗干净，剥壳，去虾线#\n2. 用冷水泡一下(补充去虾线的方法：虾剥皮后可以看到背部一般都有黑色的一条线，如果直接往外拉会拉断，残留在虾肉上总感觉不卫生，正确的做法是用小刀顺着背部到尾部轻轻划开，就可以轻松取出虾线了，全部取出后用冷水泡一泡冲一冲保证虾肉干净)#\n3. 剁碎准备好的虾肉，加入一勺油，少许盐和黑胡椒，最后加入一大勺淀粉，拌匀，盖上保鲜膜放入冰箱冷藏至少一小时，完成啦。#'),(396,'素炒藕片','素菜','藕#\n葱#\n姜#\n味达美#\n醋#\n盐#','#\n#\n#\n#\n#\n#','1. 藕洗净切成片，葱切葱花，姜切片；#\n2. 热锅凉油，油热放入葱花、姜片爆香，倒入藕片翻炒片刻；#\n3. 调入味达美、醋、盐，继续翻炒至入味，装盘即可。#'),(397,'鸡腿菇','素菜','鸡腿菇#\n姜#\n青椒#\n胡萝卜#\n大蒜#\n瘦肉#\n料酒#\n味精#\n淀粉#\n盐#','1个#\n3片#\n半个#\n0.5根#\n2个#\n随意#\n#\n#\n#\n#','1. 所有食材切片#\n2. 还是切片#\n3. 肉片加入淀粉，盐，味精，料酒拌匀#\n4. 将蒜，辣椒，姜放入锅里爆香（炒菜基础）#\n5. 放入切好的胡萝卜，鸡腿菇稍稍炒一下，加入开水，盐，味精，酱油，料酒盖锅焖1分钟。#\n6. 水煮沸了以后把肉下锅，再煮一分钟就好出锅了#'),(398,'香辣虾','荤菜','虾#\n盐#\n生抽#\n葱姜蒜#\n葱头#\n辣椒#','500g#\n#\n#\n#\n半个#\n3～5#','1. 买来的虾去处虾线用生抽腌制10～15分钟#\n2. 放入适量的油，，等油热后放入葱姜蒜爆香，，再放入麻椒#\n3. 把腌制好的虾放入爆炒，，，直至炒出虾油#\n4. 最后放入葱头爆炒，，，放适量的盐，，大功告成，，，装盘#\n5. 成品#'),(399,'莴苣肉丝','荤菜','莴苣#\n猪肉丝#\n食用油#\n淀粉#\n盐#\n柠檬汁#','适量#\n适量#\n适量#\n少许#\n适量#\n几滴足以#','1. 莴苣去叶去皮，切丝备用#\n2. 少量肉丝加少量淀粉抓一下#\n3. 锅内放油炒肉丝#\n4. 肉炒变色盛出备用，锅内继续倒入莴苣丝炒#\n5. 挤些柠檬汁进莴苣丝#\n6. 加盐#\n7. 出锅#\n8. 这是一道非常时候卷春饼吃的菜哦！清淡而不腻，所以大家要少放肉哦！#'),(400,'南瓜丝饼','主食','南瓜#\n鸡蛋#\n面粉#\n盐#\n胡椒粉#','200g#\n2个#\n适量#\n少许#\n少许#','1. 这里我是都备好了，其实很简单，南瓜去皮洗净切丝用少许盐拌匀，腌制一会软点，加鸡蛋和面粉拌匀，本身南瓜用盐腌了会出水，如果觉得干可以加少许水的，加胡椒粉拌匀。#\n2. 锅炉烧热，倒少许油倒入南瓜糊，像这个样子，不要弄得太厚，摊平煎至两面金黄。#\n3. 煎成这样，火#\n4. 好拉，第一锅煎好了，用铲子在锅里就切成块了，这样宝宝吃起来方便，一出锅就拿走了！开森啊！！！！！#'),(401,'包菜粉丝炒鸡蛋','荤菜','包菜半个#\n鸡蛋两个#\n粉丝一小把#\n葱姜蒜适量#','#\n#\n#\n#','1. 粉丝用水焯两三分钟 用冷水激一下 先炒好鸡蛋装盘备用 再放油煸炒葱姜蒜 加入切好的包菜 加入少许酱油 加入粉丝和鸡蛋 并倒些蚝油 最后少许盐 鸡精 装盘 成功啦#'),(403,'秋刀鱼（弟弟喜欢的做法）','荤菜','秋刀鱼#\n番茄#\n柠檬汁#\n葱白#\n姜蒜#\n淀粉#\n清水#','2条#\n一小个#\n几滴#\n适量#\n适量#\n适量#\n小半碗#','1. 秋刀鱼处理后切断，用盐，料酒，腌制一小时；拭干水分；准备一个干净的小碗，里面装入淀粉；锅里入油预热；秋刀鱼裹淀粉，入锅小火煎至两面黄#\n2. 煎好后捞出，备用。#\n3. 锅里余油，中火，依次放入姜蒜，葱白煸炒#\n4. 倒入西红柿，中火转小火煸炒至出汁。#\n5. 放入秋刀鱼，滴入柠檬汁，清水小半碗，盖锅盖中火转小火焖十分钟。#\n6. 揭锅盖，调入盐，鸡粉，转中火，翻炒收汁。#\n7. 出锅！#\n8. 成品！#\n9. 成品~#'),(404,'完爆香辣虾','荤菜','基围虾#\n细葱#\n辣椒#\n大蒜#\n花椒#\n芝麻#\n生姜#','1斤#\n2根#\n3个#\n2片#\n少许#\n少许#\n2片#','1. 基围虾洗干净、挑出黑筋。准备一系列调味料备用。#\n2. 平底锅里放少许油翻炒虾仁，取出备用。#\n3. 取出虾后国内留有少许热油，依次放下细葱、蒜瓣，生姜爆香。放入辣椒、花椒、翻炒几次加入小半碗水，加糖加盐。#\n4. 再次放入虾编炒直至汤收稠。#\n5. 出锅，撒上芝麻。大功告成。#'),(405,'红糖姜汁卧蛋（超简单）#姨妈期#','汤','生姜#\n红糖#\n鸡蛋#\n水#','30g#\n25g#\n1颗#\n300ml#','1. 姜切片，入锅，加水中大火煮开，转中小火继续炖煮（煮制时间越长越辣，自行试味控制）#\n2. 捞出姜片，卧颗蛋进去，待成型凝结（鸡蛋生熟程度按照喜好，不过不建议过生，煮老一些没关系，只是微微流黄的最好）#\n3. 加入红糖，待其熔化即可。热呼呼的喝掉，全身温暖^_^#'),(406,'火柴豆腐干','素菜','香干#\n肉丝#\n蒜苗#\n小米椒#\n老干妈#\n白酒蚝油白糖白醋#\n生抽盐鸡精#\n香油#','200g#\n50g#\n3条#\n10g#\n10g#\n少许#\n适量#\n1勺#','1. 铺料#\n2. 香干切火柴形状#\n3. 热锅放油加入肉丝蒜苗头和小米椒煸炒#\n4. 煸香后放入香干和一勺老干妈和生抽白酒蚝油白醋进行爆炒#\n5. 炒至变色后加一勺白糖和少许盐#\n6. 再放蒜苗叶炒熟出锅前加一勺香油装盘即可#\n7. 成品味道美美哒#'),(407,'鸡肉泥 宝宝辅食','荤菜','鸡胸肉#','#','1. 鸡胸肉 去皮去油 洗净 切成小块#\n2. 用搅拌机搅拌成泥#\n3. 放入蒸锅蒸熟即可 吃的时候挖一小块 压一下拌在米糊里#'),(408,'木须肉','荤菜','里脊肉#\n鸡蛋#\n木耳#\n黄瓜#\n冬笋#\n生抽#\n姜末#\n油#\n盐#\n生粉#','200g#\n2个#\n80g#\n40g#\n40g#\n2茶匙#\n4g#\n1汤匙#\n1茶匙#\n1茶匙#','1. 猪里脊肉洗净切成片，用生粉拌匀腌片刻。鸡蛋磕入碗里大赛，黄瓜洗净切片，冬笋剥壳洗净，切片后焯水沥干。#\n2. 锅中放油，烧至五成热时倒入蛋液，待其凝固时用锅铲搅碎，盛出待用。#\n3. 锅中留热油，爆香姜末后放入里脊肉片迅速翻炒至熟，再依次放入木耳、黄瓜、笋片炒2分钟，倒入生抽并加盐翻炒1分钟后方鸡蛋碎炒匀即可。#'),(409,'零食篇-无油鸡翅','荤菜','鸡翅中#\n吐司片#\n盐#\n葱姜蒜#\n白胡椒#\n料酒#','#\n#\n#\n#\n#\n#','1. 把吐司片放置微波炉中两分半烤干后放入绞碎机打碎，烤箱也可以#\n2. 鸡翅中打花刀以后放入葱姜蒜盐和料酒腌制，喜欢辣的可以放辣椒#\n3. 鸡翅腌制十到十五分钟以后拿出裹上自制的面包糠放置盘中记得用筷子架空留氧气#\n4. 放入微波炉中3分钟拿出，然后反面再微2分钟，盘子中可以放一下吸油纸#\n5. 最后出炉咯，无油鸡翅，健康零食，盘子中都是鸡翅自带的油不用担心，开动啦～（＾ω＾）#'),(411,'红烧芋头排骨','荤菜','排骨#\n芋头#\n八角#\n蒜头#\n姜#\n料酒#\n生抽#\n老抽#\n五香粉#\n豆瓣酱#\n油#','适量#\n一个#\n一个#\n几个#\n适量#\n适量#\n#\n#\n#\n#\n#','1. 排骨#\n2. 芋头#\n3. 八角，蒜头，姜#\n4. 锅里煮开水，加入料酒和姜，放入排骨过下水#\n5. 过好捞起来备用#\n6. 另起锅，倒入油，放入姜蒜进去爆香，放入排骨翻炒到有点金黄#\n7. 放入豆瓣酱，老抽，生抽，五香粉#\n8. 倒入切好的芋头#\n9. 倒入点料酒和加入热水没过芋头排骨，闷个30分钟左右#\n10. 收汁起锅！！#'),(412,'素食之— —萝卜干炒毛豆','素菜','萝卜干#\n毛豆#\n蒜瓣#\n辣椒#','几根#\n小半碗#\n5颗#\n3颗#','1. 萝卜干切丁，毛豆去壳～#\n2. 先干锅把萝卜干煸炒出水份～#\n3. 下油，爆蒜瓣和辣椒～#\n4. 然后是毛豆～#\n5. 炒呀炒，放点儿盐。如果萝卜干是那种咸味很重的就不需要加盐。我的是甜味萝卜干～#\n6. 加几滴生抽调色～#\n7. 小咸菜，配清粥正好～#'),(414,'椒盐小黄花鱼','荤菜','黄花鱼，椒盐#','#','1. 小黄鱼解冻#\n2. 收拾干净，加少许盐腌15分钟。#\n3. 鱼抹点生粉，放入热锅中（油可以稍微多一点。）#\n4. 煎金黄色再翻面#\n5. 两面煎好，撒上葱花，椒盐再煎一分钟。#'),(415,'东北锅包肉','荤菜','猪肉里脊#\n葱、姜、蒜、胡萝卜#\n香菜#\n蛋清#\n盐#\n料酒#\n淀粉#\n醋#\n白糖#\n老抽#','500g#\n都切成条#\n少量#\n1个#\n适量#\n适量#\n适量#\n适量#\n适量#\n少量#','1. 把里脊肉切成片#\n2. 用盐、蛋清、料酒抓匀、腌15-20分钟#\n3. 把腌好的肉，用干淀粉裹好#\n4. 调好淀粉糊，加少量食用油。我把剩下的蛋黄放里面啦，也可以不放。#\n5. 锅里油烧热。#\n6. 把裹好面糊的肉放里面炸。#\n7. 肉要炸两边。#\n8. 留油放入葱、姜、蒜、胡萝卜爆香。#\n9. 用盐、白醋、糖、老抽、料酒、水淀粉调成汁。把肉和料汁都放入锅中。#\n10. 装好成盘，把香菜放在上面，完成。#'),(416,'银鱼煎蛋','荤菜','银鱼#\n鸡蛋#\n葱#\n盐#\n胡椒粉#\n料酒#','适量#\n三个#\n两根#\n一小勺#\n一小勺#\n一小勺#','1. 银鱼洗干净在锅里下油加热方点葱头把银鱼加点料酒翻炒下#\n2. 然后银鱼放凉到掉多余水分，鸡蛋打散，倒入加盐巴，胡椒粉，葱叶，喜欢的可以加一点紫菜，(这道菜，我买了三块钱的银鱼用了三个鸡蛋)#\n3. 最好用不粘平底锅，把油加到七八成热，倒入调好的蛋液，这时候要注意火候，火不能太大， 煎到下面熟了然后翻过来，再煎整个过程的火候自己掌握一下#\n4. 出来后用刀切成小块，也可以用大碗平放整个。很好吃哦，我一个人全部吃光。#'),(417,'蚝油生菜','素菜','生菜#\n蚝油#\n淀粉#\n生抽#\n蒜粒#\n糖#\n水#','#\n#\n#\n#\n#\n#\n#','1. 生菜洗净#\n2. 蒜切粒#\n3. 生菜焯水断生 时间不要太久 避免影响口感 盛出备用#\n4. 碗里放入蚝油 生抽 淀粉 糖 用水搅匀备用#\n5. 锅内热油放蒜粒#\n6. 加入调好的汁 翻炒粘稠#\n7. 直接浇入焯好的生菜上 完成！#'),(418,'飘香酸菜鱼','荤菜','草鱼一斤，酸菜二包，野山椒，黄米椒各适量#','干辣椒，葱花，姜末，鸡粉胡椒粉，白醋味精各适量#','1. 1。把草鱼从鱼骨开片，鱼骨剁成块，鱼肉片成片，酸菜切段。2/把鱼片洗净控干水，加一丁点盐鸡粉水，再加蛋清和生粉。3。起锅加油加野山椒黄灯笼椒葱花，加水加味精鸡粉胡椒粉白醋，放入过了水的鱼骨和酸菜，过会捞出放盆4。腌好的鱼片依次放入锅中，大约几十秒连水带肉导入盆里，干辣椒花椒用油炸下导入即可#'),(419,'可乐鸡翅','荤菜','翅中#\n可乐#','8个#\n一罐#','1. 将鸡翅横着切开口，放如料酒，姜丝，蒜瓣，腌制20分钟，然后锅里直接倒入可乐一瓶，加一勺生抽和老抽调色，刚好淹没鸡翅就行！烧开后，打去可乐泡沫，转小火闷10分钟，吃得甜的朋友们可以加点蜂蜜！最后大火收汁！装盘撒点芝麻！和葱丝就OK！赶快动手给家人朋友做来试一试吧！#'),(420,'清蒸扁鱼','荤菜','扁鱼#\n红剁椒#\n香葱段+葱花#\n姜丝#\n蒸鱼鼓油#\n盐#\n料酒#\n花椒#\n色拉油#\n半个青椒#','一条#\n10g#\n30g+10g#\n30g#\n15g#\n#\n15g#\n6颗#\n30g#\n#','1. 扁鱼破肚去鳞去腮肠和黑衣冲洗干净，在肉多的地方打上花刀抹上少量盐和料酒腌制半小时。#\n2. 空盘码上一半姜丝和葱段垫底，将鱼码在葱姜上，鱼身上码放剩下的葱姜丝，半个青椒丝，一勺子剁椒，空锅放清水烧开后隔水蒸鱼加盖大火蒸8分钟后开盖淋上蒸鱼鼓油闷三五分钟端出。#\n3. 炒锅烧热放油放花椒扁香，这时将剩下的葱花放鱼身上，最后将花椒油淋在鱼身上的葱花上就可以了。#\n4. 香喷喷的清蒸鱼就做好了，是不是很简单呢，省时省力又能吃到美味的鲜鱼。#'),(421,'酱炒明虾','荤菜','明虾#\n葱姜蒜#','#\n#','1. 虾去虾线去头洗净备用#\n2. 锅烧热油，下姜蒜爆香，然后放入虾快炒，炒至变色，放盐糖鸡精，最后倒入酱油，装盆开吃。#\n3. 由于本人比较懒，所以不一一拍照了。还有由于我对虾不去虾线跟虾头过敏所以全部去掉。大家自己做可以省掉。#'),(422,'芹菜豆干','素菜','豆干#\n芹菜#\n干辣椒#\n花椒#','自己爱好#\n自己爱好#\n适量#\n#','1. 豆干切丝备用#\n2. 芹菜切段备用#\n3. 花椒辣椒备用#\n4. 蒜粒，辣椒，花椒炒香#\n5. 加入豆干翻炒#\n6. 加入芹菜翻炒调味鸡精，盐断生起锅#\n7. 装盘开吃#'),(423,'碎米芽菜炒肉沫','荤菜','郫县豆瓣酱#\n盐#\n姜末#\n酱油#\n花椒#\n清水#\n食用油#','1汤匙#\n一小撮#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 肉馅先加入少量盐，姜末，酱油，一汤匙清水。#\n2. 拌匀。#\n3. 锅烧热，加入适量食用油。待油温升高，倒入适量花椒煸香#\n4. 将花椒盛出，加入一勺郫县豆瓣酱炒出红油。#\n5. 倒入肉馅~炒至变色。#\n6. 倒入碎米芽菜。翻炒均匀。#\n7. 加入适量清水~盖上锅盖焖一会5,6分钟~#\n8. 大火收汁。#\n9. 盛出即可~#'),(424,'青椒木耳鸡腿菇炒肉片','荤菜','木耳#\n辣椒#','1把#\n2个#','1. 肉丝切片，鸡腿菇切片，辣椒切丝，木耳在热水里泡大后，清水洗干净。#\n2. 1.先把青椒炒过盘子装起来最用。2，倒油烧热姜爆香。3加入肉片爆炒至变白。#\n3. 1.加入酱油一小勺糖翻炒。2.加水和盐（以各人口味放）后木耳鸡腿菇一起入味。3，待鸡腿菇和木耳变软后（拿筷子尝）加入青椒，翻炒后装盘。#\n4. 完成#'),(425,'莲藕小炒肉','荤菜','瘦肉#\n莲藕#\n农家尖椒#','两人份#\n一节#\n三五根#','1. 精瘦肉切不规则小肉片，用少量酱油，鸡精，料酒，油，腌制几分钟。#\n2. 莲藕对半切开，切薄片；尖椒斜刀切。#\n3. 锅烧热下少量油，下瘦肉炒断生。#\n4. 下入藕片和尖椒大火快炒断生，加入鸡精炒均。（怪物老公广东出生广东长大，吃的不是一般的清淡，所以我家做菜基本用不上盐，此处口味重的可以加适量盐和酱油）#\n5. 装盘。怪物还说有点咸，我说没放盐噢。他说应该是腌肉时候放的酱油和起锅时放的鸡精咸。他还门儿清。#'),(426,'清蒸金鲳鱼','荤菜','金鲳鱼#','1条#','1. 清洗：选择富有弹性，眼睛有神的冰鲜鱼一条。去除内脏，洗净沥干，两面三刀#\n2. 腌制：用小葱，姜片，料酒，生抽，少量盐抹在鱼上，鱼肚里多塞些葱，去腥。弄好后，覆膜，入冰箱腌制半小时。#\n3. 蒸鱼：蒸锅水烧开。腌制好的鱼倒掉大部分腌制出的水等，抹点猪油或放两三片肥肉（不喜猪油的可以不放，出锅时临油），入锅蒸15分钟，关火后闷5分钟。#\n4. 成品：鱼出锅，挑去原葱，姜。洒上葱花，淋点蒸鱼豉油和陈醋（蒸鱼时没放猪油的起热火，少量油烧热后关火，葱花放入，一并交鱼身上。），ok。#'),(427,'烧冬瓜，素菜中的重口味福利','素菜','冬瓜#\n浓缩火锅底料#','500g#\n70g#','1. 冬瓜去皮去瓤，切成宽2cm左右的方块，小葱洗净切好备用。#\n2. 冬瓜去皮去瓤，切成宽2cm左右的方块，小葱洗净切好备用。#\n3. 倒入冬瓜块，翻炒约2分钟，让冬瓜吸油入味，注意火不要大了。#\n4. 倒入冬瓜块，翻炒约2分钟，让冬瓜吸油入味，注意火不要大了。#\n5. 倒入冬瓜块，翻炒约2分钟，让冬瓜吸油入味，注意火不要大了。#'),(429,'椒盐鸭下巴','荤菜','鸭下巴#\n蒜#\n耗油#\n豉油#\n盐#\n香菜#\n辣椒#\n回香#\n八角#\n桂皮#','5个#\n4粒#\n适量#\n少量#\n1匙#\n少量#\n#\n少量#\n#\n#','1. 将鸭下巴洗净，用盐腌十五分钟，然后开水过一下！#\n2. 桂皮，回香，八角，豉油，耗油，加水煮成卤水！#\n3. 蒜，辣椒，香菜，备用！#\n4. 没拍图片，然后把鸭下巴放进卤水，煮开以后小火，想更入味可煮久一点！我就小火煮了十来分钟！#\n5. 卤水出来放凉，然后进油锅炸一下下，本来就熟了，不需炸久，然后加香菜那些就好了！上桌前撒点椒盐#'),(430,'秘制烤鸡腿','荤菜','鸡腿#','#','1. 鸡腿划两刀方便入味，准备蜂蜜，生抽酱油，糖，料酒，蒜蓉鸡酱，姜，腌制一夜#\n2. 温度180、30分钟#\n3. 出锅前可以撒点孜然#'),(431,'清蒸鲈鱼','荤菜','鲈鱼#\n枸杞#\n油#\n盐#\n醋#\n酱油#\n葱姜#','1斤2两#\n几粒#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 我买的时候就让卖家拨好肚子和刮去鱼鳞了，到家只是又重新洗了洗#\n2. 去鱼尾，从腹部到背部均匀地切条，再把鱼头切下。#\n3. 在鱼的两侧抹适量盐，鱼肚子里面也抹点盐。#\n4. 葱、姜切丝，铺在盘子底部。鱼身依次摆入盘，摆成孔雀开屏状，鱼头放中间，再放上孔雀尾巴上面些葱片和枸杞装饰#\n5. 开水上锅蒸6分钟，关火后不要揭盖，再焖4分钟，俗称“虚蒸”。 出锅后，淋上醋和酱油调制的汁，撒上葱花，再浇一遍热油即可#'),(432,'可乐鸡翅（简单的）','荤菜','鸡翅，翅中#\n可乐#\n生姜#\n八角#\n酱油#','16个#\n没过鸡翅#\n适量#\n一个#\n适量#','1. 先把鸡翅洗净，然后用水焯一下，和水同时放入锅里，可以加一些料酒去腥，水开了捞出来就行#\n2. 两面煎，（卖相不太好）煎成大概这个颜色就行，一定要用不粘锅，要不然鸡翅会很惨。#\n3. 生姜和八角放到锅里爆炒，然后放入鸡翅，最后倒可乐，刚刚没过鸡翅为好，加酱油调色，所以适量就好。#\n4. 盖上锅盖，等待可乐汁变稠，大概这样的时候就差不多了#\n5. 最后摆盘，怎么摆就看自己咯嘿嘿#'),(433,'香煎青红椒鸡中翼','荤菜','鸡中翼#\n青红椒#\n葱白#\n小红椒#\n蚝油#\n生姜#\n盐#\n料酒#\n生抽#\n老抽#','十只#\n各4条#\n3g#\n3条#\n1勺#\n1块#\n1勺#\n1勺#\n2勺#\n1勺#','1. 先把鸡翼两面划花面，用蚝油生姜料酒腌半个小时#\n2. 青红椒切丝，葱白小红椒切圈，放在一边备用#\n3. 热煎锅放鸡翼、煎到两面金黄色，大概五分钟左右，煎好先盛出放在一旁#\n4. 热锅放油，放葱白小红椒爆香，再放青红椒丝炒香#\n5. 放煎好的鸡翼下锅，放生抽老抽盐，炒均匀，放点清水，中小火焖3-4分钟左右，用筷子戳一下鸡翼试一下有没有熟透。#\n6. 成品#'),(434,'红烧鲳鱼','荤菜','鲳鱼#\n老抽#\n上海老酒#\n泡椒#\n胡椒#\n茴香#\n洋葱#\n蒜#','#\n适量#\n适量#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 将鲳鱼从冻箱里取出自然解冻，去除腮和内脏，在表面划几刀#\n2. 将洋葱和蒜切碎#\n3. 锅内倒油后放入洋葱蒜和泡椒爆香#\n4. 爆香后加入老抽酱油和老酒#\n5. 汤汁烧至半开后放入鲳鱼#\n6. 加入茴香加盖大火煮#\n7. 中途轻轻翻一次鱼，加入食盐调味，煮至汤汁变浓#\n8. 出锅前撒入胡椒粉，装盘后再撒少许茴香#'),(435,'黑椒牛肉粒','荤菜','牛排一块#\n青红椒各一个#\n洋葱#','#\n#\n#','1. 将牛排切成粒状，用黑椒汁进行腌制#\n2. 将青红椒、洋葱洗净切块#\n3. 小火放入橄榄油，煎牛肉的同时将火调大下青红椒洋葱一起炒#'),(437,'番茄牛肉汤','汤','番茄#\n牛肉#\n金针菇#','#\n#\n#','1. 番茄金针菇切好，牛肉切薄片加生抽，生粉，油抓匀，放10分钟。生粉不能多。#\n2. 热锅下油把番茄炒软。#\n3. 加水，煮5分钟。#\n4. 放金针菇煮2分钟。#\n5. 再放牛肉，下少许盐和鸡精调味。牛肉一变色马上关火。#\n6. 还可以煮面吃，非常开胃。#'),(438,'凉拌皮蛋','素菜','皮蛋#\n指天椒#\n大蒜#\n葱#\n生抽#\n醋#','4个#\n6个，可根据自己的口味添加#\n#\n#\n#\n#','1. 将皮蛋拨壳，切成4片，放在碗里围成一圈，如果摆完一圈还有多余的，直接切小块，放中间#\n2. 准备指天椒，大蒜，葱，洗净后，切成末，分别放置#\n3. 锅烧热放油，烧至8成热，放指天椒爆炒，在放蒜末爆炒，放生抽、醋，在放葱#\n4. 将做好的酱汁，围着皮蛋淋一圈，剩下的全部淋在中间，一盘色香味具全的凉拌皮蛋就做好了。#'),(440,'火腿蒜台','荤菜','蒜台#\n火腿肠#\n白糖#\n酱油#\n食用醋#\n甜面酱#\n盐#','1把#\n5根#\n一汤匙#\n两汤匙#\n两汤匙#\n半汤匙#\n两勺#','1. 首先蒜台摘洗干净切成段，火腿肠切成片，如图哦。#\n2. 锅里热油（油要稍微多一点），待油热之后把火腿肠放进去炸一下，之后再把蒜台放进去一起翻炒。#\n3. 先炒三四分钟之后就可以陆续把酱油，醋，盐，白糖放进去，搅拌均匀之后再加一点甜面酱（也可以不加哦），继续翻炒五分钟左右。#\n4. 美味的火腿肠炒蒜台就出锅了，有食欲么。#'),(441,'土豆炖鸡肉','荤菜','土豆#\n鸡#\n大葱#\n姜#\n蒜#\n十三香#\n盐#\n味精适量#','2个#\n一只#\n适量#\n适量#\n适量#\n适量#\n适量#\n#','1. 土豆去皮，切块        鸡洗干净，切块，#\n2. 葱姜蒜切沫#\n3.  首先把锅烧热，放入切好的葱姜蒜，炒出蒜香，然后把鸡肉放入锅中翻炒，炒到表面熟，然后放点酱油，把土豆放里翻炒，添水，水不要放过多，不要沒肉，放入适量盐，炖到熟，等熟了，在放点蒜，放点味精就可以出锅了，#'),(442,'香滑鸡翅','荤菜','鸡翅#\n香菇#\n葱#\n姜#\n蒜#\n胡椒粉#\n料酒#\n柱候酱#\n海鲜酱#\n郫县豆瓣酱#\n老抽#','600g#\n#\n#\n#\n#\n#\n#\n10g#\n10g#\n5g#\n3g#','1. 鸡翅中清洗干净控水后切好花刀！#\n2. 葱姜切片，料酒，胡椒粉，少许盐加清水调成葱姜水！#\n3. 鸡翅加入葱姜水中腌制40分钟！#\n4. 鸡翅腌好后控水，加少许淀粉拌匀（淀粉放一小勺就可以）！不粘锅中放15g左右的油把鸡翅煎至两面金黄！#\n5. 香菇切块，用煎鸡翅的油煸炒至软！#\n6. 锅中留底油，放入葱姜煸炒出香味后加入豆瓣酱，海鲜酱，柱候酱炒匀加入清水，老抽调色！锅开后下入鸡翅和香菇盖盖闷15分钟！汤汁收浓后放盐，鸡精调味出锅时撒上蒜末即可装盘！#\n7. 成品#'),(443,'胡萝卜牛骨汤～附基础牛骨汤法子','汤','牛骨头#\n胡萝卜#\n洋葱#\n生姜#\n香菜#\n盐#','2条#\n1条#\n半只#\n2片#\n1棵#\n适量#','1. 骨头冷水下锅烧开，再拿出清洗一下，去掉浮沫子，换上一锅清水放下骨头，加2片生姜片，滴入2滴醋，大火烧开转小水熬上3小时。水要一次多加点，中途不加水。#\n2. 看到浓汤了吧，其实很简单。#\n3. 另外拿一汤锅取几勺骨汤，加入切小块胡萝卜、洋葱，煮上10分钟即可。剩下的汤可以装盒子冷冻，一次一份，下次就方便使用了。#\n4. 出锅前加点盐，撒上香菜，那个香味立马引你走不开。#\n5. 看看想喝吧。#'),(444,'尖椒炒猪肚','荤菜','酱猪肚#\n尖椒#\n油#\n盐#\n葱#','半个#\n4个#\n适量#\n少许#\n适量#','1. 准备好材料；#\n2. 猪肚切条；#\n3. 尖椒洗净切条；#\n4. 炒锅放适量的油，放入葱炒出香味；#\n5. 放入尖椒翻炒；#\n6. 炒一分钟，放入猪肚翻炒；#\n7. 翻炒至尖椒有些软榻，加少许的盐调味，猪肚本身有味道，翻炒均匀，起锅。#'),(445,'懒人菜系列-红酒炖香菇','素菜','香菇#\n香菜#\n蒜瓣#\n红酒#','250g#\n适量#\n2个#\n适量#','1. 香菇洗净、香菜切段、蒜末备好。#\n2. 香菇切花易入味，也可以不切。#\n3. 蒜炝锅，倒入香菇，适量生抽，少量鸡精、老抽主要为了增色提香。#\n4. 略翻炒均匀后倒入红酒#\n5. 炖5分钟#\n6. 淀粉水#\n7. 倒入芡汁搅拌至汤汁粘稠后关火。倒入切好的香菜拌匀即可出锅。#\n8. 简单美味的下饭素食出锅啦*\\(^o^)/*#'),(446,'红烧百叶包','荤菜','五花肉#\n千张#\n盐#\n料酒#\n生粉#\n白胡椒#\n五香粉#\n老抽#\n生抽#\n葱#\n姜#\n八角#\n桂皮#\n干红椒#\n棉绳#','300克#\n2张#\n#\n2勺#\n1勺#\n#\n#\n3勺#\n1勺#\n1个#\n#\n2个#\n1片#\n1个#\n#','1. 肉糜加料酒、白胡椒、生抽、生粉、精盐拌匀,待用。#\n2. 百叶（千张）冲洗后,浸入凉开水泡2-5分钟。#\n3. 百叶（千张）切10-12厘米正方形,包入肉馅。馅放在正方形任意角,如春卷的方发包卷起来,用棉绳系好。（棉绳用前用水浸湿）#\n4. 热锅热油煎百叶包,呈两面金黄。#\n5. 热锅加油,姜、葱爆香,放入煎好的百叶包,翻炒（要慢）。加水至百叶包高度,烧开。加生抽、老抽（上色）、糖、白胡椒、桂皮、八角、干红椒,烧15分钟,大火收汁出锅。（中间可用筷子将百叶包翻1-2次面）#'),(447,'蚝油手撕杏鲍菇','素菜','杏鲍菇#\n青椒#','3个#\n3个#','1. 杏鲍菇洗干净，用手撕成细丝，这样杏鲍菇更有嚼劲#\n2. 青椒洗净，切小块备用#\n3. 锅里放适量的油，待油热后放几粒花椒，然后把备好的杏鲍菇倒入锅中翻吵一分钟左右，然后把青椒倒入锅中直至成熟，倒入适量的蚝油和盐#\n4. 起锅装盘即可#'),(451,'香菇酿','荤菜','马蹄#','#','1. 虾去皮，马蹄去皮，切碎，放入蛋清，盐，酱油拌匀，香菇洗好去蒂#\n2. 把虾和马蹄的碎泥码放在香菇shang#\n3. 大火烧开后上锅蒸10到15分钟。时间根据香菇和馅料大小调整#\n4. 出锅前撒上葱花#\n5. 如果肉馅味道淡，可以勾芡一个酱油，蚝油，盐，生粉兑水，热油一点烧开，做汁淋上更好看美味#'),(452,'黑椒杏鲍菇','素菜','黑胡椒碎#\n大蒜#\n大葱#\n糖#\n盐#\n酱油#','7克#\n1瓣#\n适量#\n7克#\n5克#\n20ml#','1. 大蒜与大葱切成小末；#\n2. 杏鲍菇洗净后切成切成长约5cm左右的长条备用。#\n3. 锅内热好油，倒入大蒜与大葱炒出香味，倒入杏鲍菇翻炒2-3分钟。#\n4. 调入酱油、黑胡椒碎与糖继续翻炒，直到杏鲍菇与之充分融合，最后调入盐即可出锅。#\n5. 期待您添加我的微信公众号，让我们近距离交流起立吧：）#'),(453,'软炸里脊','荤菜','猪里脊#\n鸡蛋#\n面粉#\n黑胡椒粉#\n料酒#','#\n1个#\n#\n#\n#','1. 里脊肉切成条状～#\n2. 加黑胡椒粉，料酒腌制15分钟#\n3. 鸡蛋打散#\n4. 加入少许面粉#\n5. 搅打成面糊状#\n6. 将肉充分沾取面糊#\n7. 锅中加油，烧至锅底开始有小泡泡起来的时候就可以下入肉肉了～不要急于将肉肉翻起来～这样挂的面糊不脱落，自己好了就飘起来了#\n8. 炸至金黄出锅#\n9. 家里有吸油纸要铺在盘子上吸一下多余的油分，撒上椒盐就可以吃啦！#'),(454,'爆炒酱汁鱿鱼','荤菜','鱿鱼#\n洋葱#\n尖椒#\n姜#\n蒜#\n生抽#\n蚝油#\n糖#\n五香粉#','1条#\n半颗#\n一根#\n2片#\n2瓣#\n1汤匙#\n1汤匙#\n少许#\n少许#','1. 尖椒丶洋葱丶姜丶蒜分别切片切丝#\n2. 鱿鱼洗净去骨去眼睛#\n3. 鱿鱼身切成0·5厘米宽的细圈。头对半切开再切成条段#\n4. 先把蚝油丶糖丶老抽五香粉调成汁备用！锅下油烧热依次放入姜丶蒜丶尖椒丶洋葱爆香，加入鱿鱼炒至变色，然后加入调好的酱汁翻炒一会就能起锅了#'),(455,'香煎菠菜','素菜','菠菜#\n鸡蛋#','#\n#','1. 菠菜洗干净，焯水#\n2. 过凉。#\n3. 撒淀粉。#\n4. 鸡蛋打匀，蘸菠菜。#\n5. 两面煎金黄。#\n6. 这次试了没放任何调料，竟也很有味道。#\n7. 不爱吃菠菜的也能轻松接受。#'),(456,'让你的年龄永远是个迷！——黑木耳枸杞猪圈汤','汤','猪圈，#\n枸杞，#\n大枣，#\n黑木耳（冷水泡发更爽口）#','4个#\n20颗#\n10颗#\n10朵#','1. 先将猪圈用沸水焯去血水，放入冷水中清洗干净。#\n2. 将姜片，猪圈肉放入褒锅，加入一点醋（肉更酥软，钙溶出），米酒，黑木耳，煮到水开，（水开20分钟）#\n3. 加入大枣，枸杞，慢火炖两个小时（看到猪圈的皮和肉快分开时，可以关火）加盐调味即可。#'),(457,'鸡腿炖土豆','荤菜','鸡腿#\n土豆#\n红干椒#\n盐#\n花椒粉#\n姜粉#\n生抽#\n香菜#\n味素#','2个#\n2个#\n1个#\n少许#\n少许#\n少许#\n适量#\n|根#\n少许#','1. 鸡腿我用两个琵琶腿，也可用其它肉代替#\n2. 土豆去皮切成滚刀块，用水泡上，防止土豆变色#\n3. 鸡腿去骨切块#\n4. 鸡块焯水#\n5. 鸡腿焯水后捞出备用#\n6. 锅内放底油，稍后放入鸡块和干辣椒翻炒#\n7. 然后放入花椒粉.生姜粉和生抽继续翻炒#\n8. 炒匀后，锅内加入清水，大火烧开，转中火焖炖#\n9. 等汁收干后放盐和味精炒匀，出锅即可#\n10. 出锅点缀上香菜#'),(458,'低卡蔬菜沙拉','素菜','西蓝花#\n胡萝卜#\n紫甘蓝#\n玉米#','15g#\n10g#\n30g#\n80g#','1. 胡萝卜，西兰花，紫甘蓝，玉米，在锅里焯水，然后摆放盘子里，撒上葡萄干，挤上色拉酱#\n2. 然后摆放盘子里#\n3. 撒上葡萄干，挤上色拉酱。完成#'),(459,'炒意大利面','主食','意面#\n西红柿#\n红椒#\n青菜#\n葱姜蒜#\n盐#\n食用油#\n鸡蛋#','两人份#\n1个#\n1个#\n3-4株#\n少许#\n适量#\n适量#\n2个#','1. 水中放适量盐烧开，下入意大利面煮软捞出；用少许橄榄油或者食用油拌一下。#\n2. 青菜红椒西红柿洗净，红椒切丝，西红柿开水中濯一下去皮后切片；鸡蛋打入碗中放少许盐搅拌均匀，锅中放油把蛋液炒成块盛出备用。#\n3. 锅中放油烧热，放葱姜蒜爆香，放入西红柿，炒到西红柿稍烂放入意面一起翻炒2-3分钟，然后再放入青菜红椒再一起翻炒至青菜快熟时，撒入食盐#\n4. 最后放入炒好的鸡蛋一起翻炒几下即可出锅#'),(460,'白灼生菜','素菜','生菜#\n蚝油#\n生抽#\n香油#','2颗#\n适量#\n适量#\n适量#','1. 将生菜洗净，同时用不锈钢锅烧开水。#\n2. 等水开时，将蚝油、生抽、香油适量备于小碗。（蚝油较咸，可不放盐）#\n3. 水大开后，放少许油，再放入生菜，浸入开水中30秒，马上出锅。（动作要快哦！一定记得倒去菜碗中多余汤水。）#\n4. 用少许烫生菜的水加入调料碗，调匀，淋在烫好的生菜上即成。（趁热吃！）#'),(461,'鸡腿菇烧鸡腿','荤菜','八角#\n桂皮#\n酱油#\n盐#\n糖#\n鸡精#\n水晶粉丝#','两个#\n两小枝#\n#\n#\n#\n少许#\n1包#','1. 鸡腿先洗净斩件；鸡腿菇洗净切片、八角两个、桂皮两小枝洗净备用。#\n2. 锅中座油，下糖炒出糖色，倒入剁好的鸡腿翻炒片刻。#\n3. 加入八角和桂皮翻动几下，倒入酱油调色再翻动片刻。#\n4. 等汁烧开后，加入适量凉水（水要保证够多）继续烧至水开。撇去汤上浮沫。#\n5. 倒入切成片的鸡腿菇同炖，整个过程开大火。#\n6. 中间阶段下水晶粉丝，盖上锅盖继续焖鸡肉和粉丝，直到粉丝软身熟食。此时若水不够要加点开水，不然会很干。#\n7. 水收到差不多时，加入鸡精和盐调下味即可。#'),(462,'豉油鸡','荤菜','鸡#\n酒#\n豉油#\n白糖#\n沙姜或生姜#','1只约1.5-2斤#\n1碗#\n1碗#\n半碗#\n少许#','1. 锅里加一碗酒 一碗豉油和半碗糖姜块烧开。我一般用料酒，有时候用高度数白酒，有时候用啤酒。味道来讲白酒最香。您随意。烧开后放入全鸡。盖上锅盖换小火，但要保证豉油不断沸腾。每五分钟把鸡换一面，用汤勺把豉油淋在表面五次左右。#\n2. 今天是一斤半的鸡 煮约20分钟。用筷子在鸡腿最厚的位置戳下去，如果流出来的是油水就OK了，如果是血水还要继续煮。#\n3. 翻过来再鸡胸脯最厚的位置戳下去，同样流出油水就OK了，流出血水还要继续。#\n4. 煮好就可以上碟了。锅里的豉油倒小碗里斩开吃时当舔料。#'),(463,'辣炒鱿鱼圈','荤菜','鲜鱿鱼#\n嫩姜#\n青红辣椒#\n杏鲍菇#\n蚝油#\n盐#\n大蒜头#','300克#\n1块#\n各3个#\n适量#\n适量#\n适量#\n1颗#','1. 鱿鱼切好后用开水汆烫一下捞出备用。#\n2. 嫩姜切片。#\n3. 辣椒小葱头切碎备用。#\n4. 杏鲍菇切丁。#\n5. 锅中放油，先下嫩姜炒一会，放一点点生抽，再下杏鲍菇，稍炒一会盛出。#\n6. 锅中放油，下辣椒、葱头、蒜头、盐、刚才炒好的杏鲍菇。#\n7. 放入鱿鱼圈、水淀粉、蚝油，炒匀即可。#'),(464,'凉拌黑木耳','素菜','黑木耳#\n洋葱#\n大葱#\n香菜#\n烤熟花生#\n小红辣椒#\n盐#\n生抽#\n陈醋#\n白糖#\n油辣子#','泡发后两把#\n四分之一个#\n一段#\n三颗#\n一小把#\n三个#\n三分之一勺#\n一勺#\n一勺#\n半勺#\n一勺#','1. 木耳泡发后，在开水锅里焯一会，捞出过两遍凉水，沥干备用#\n2. 备主料，洋葱切丝，大葱切片，香菜切段，辣椒切段#\n3. 所有主料放入盆里#\n4. 一勺陈醋#\n5. 一勺生抽#\n6. 一勺油辣子#\n7. 半勺白糖#\n8. 三分之一勺盐，拌匀#\n9. 成品#'),(466,'麻辣猪蹄炖竹笋','荤菜','猪蹄#\n竹笋#\n干辣椒#\n大蒜#\n红油豆瓣酱#\n香叶#\n料酒#\n酱油#','1k?g#\n400g#\n6个#\n3颗#\n1勺#\n3片#\n6勺#\n0.3勺#','1. 竹笋提前一小时泡软#\n2. 猪蹄切小块备用#\n3. 猪蹄用水煮下。出沫 出血水#\n4. 准备材料#\n5. 锅里放油  热锅凉油 放入 麻椒 花椒  炒焦 捞出。这时放入猪蹄炒  炒变色 加入蒜 干辣椒 红油豆瓣酱 一起炒#\n6. 加入开水 莫过猪蹄就可以  少加一点盐。豆瓣酱很咸。放入蒜 香叶 小火炖 过20分钟加入竹笋  继续小火炖40分钟 最后大火收汁 出锅#'),(467,'双椒杏鲍菇','素菜','杏鲍菇#\n青椒#\n红椒#\n盐#\n植物油#\n辣椒酱#\n姜#\n蒜#','适量#\n适量#\n适量#\n适量#\n适量#\n根据口味放#\n适量#\n适量#','1. ①杏鲍菇洗净切片，姜蒜切片，辣椒切块#\n2. ②将油倒入锅中烧八成热放入杏鲍菇翻炒#\n3. ③翻炒两分钟后放盐，再翻炒两分钟放入切好的辣椒块和姜蒜片继续炒三分钟。#\n4. ④最后倒一点酱油着色出锅。#'),(468,'不苦的美味苦瓜','素菜','苦瓜1只#\n葱白#\n白砂糖#\n生抽#\n醋#\n香油#\n盐#','250g#\n3cm#\n半匙#\n1匙#\n半匙#\n数滴#\n可加一点可不加#','1. 苦瓜一剖为二，去苦瓜瓤。切片#\n2. 烧一锅开水，苦瓜焯水，水开即捞出#\n3. 苦瓜过凉水。这样苦瓜颜色翠绿口感脆生#\n4. 调料汁：上面的调料混在一起搅拌均匀。把葱白切片片。#\n5. 苦瓜捞出控水装盘，中间放葱白。然后浇调料汁。然后拌一下开吃。#'),(469,'自制把子肉','荤菜','五花肉#\n鸡腿#\n香肠#','500g#\n3只#\n300g#','1. 五花肉切片，焯水后两面煎黄#\n2. 鸡腿焯水煎黄#\n3. 大豆腐卷两面煎黄#\n4. 香肠洗净晾干#\n5. 海带洗净用线捆成卷#\n6. 鸡蛋煮后剥壳#\n7. 各种香料#\n8. 葱姜蒜辣椒#\n9. 锅内倒水，水开后调入老抽生抽陈醋耗油，放入各种香料，煮五分钟后放入肉类，调小火煮一小时后再放入蔬菜，再放点盐，胡椒粉，再煮20分钟就大功告成#\n10. 成品#'),(471,'清蒸螃蟹','荤菜','梭子蟹#\n姜#','#\n#','1. 螃蟹洗干净，因为是活的没剪皮筋，被夹怕了！#\n2. 锅里水开后，放入海蟹！腹部朝上，避免汤汁流出。#\n3. 大火蒸二十分钟即可#\n4. 装盘#\n5. 姜切末，倒入醋调汁#\n6. 好肥美！开吃吧！#'),(472,'炝炒圆白菜','素菜','圆白菜#\n大蒜#\n花椒#\n干辣椒#\n油#\n盐#','500g#\n4颗#\n10几颗#\n3个#\n适量#\n适量#','1. 白菜切菱块状洗净，也可以手撕。我是每次都是为了快所以切的#\n2. 蒜切末 干辣椒切段#\n3. 锅七八分热时放入油，在放入花椒和辣椒爆香 放入蒜末爆香#\n4. 倒入白菜翻炒几下，放盐起锅就好啦！#\n5. 来张成品照   上桌几分钟就光了，我儿子特爱吃这道菜#'),(473,'垮炖罗非鱼','荤菜','葱段#\n姜片#\n黄酒#\n老抽#\n生抽#\n盐#\n糖#\n醋#\n食用油#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 罗非鱼洗净，鱼身两侧切花刀。#\n2. 然后在鱼身表面薄薄撒一层盐、倒入适量黄酒去腥，加入葱段、姜片、少许生抽腌制20分钟左右。#\n3. 炒锅加热，倒入适量食用油，用厨房用纸擦干鱼身表面水份。#\n4. 待油温七八成热时，放入罗非鱼两面过油煎一下。#\n5. 然后放入腌制鱼的葱姜调料，倒入适量醋，快速盖上锅盖烹一下给鱼去腥。#\n6. 然后倒入适量热水没过鱼身，加入老抽上色糖提味，大火烧开。#\n7. 烧开后转小火，盖上锅盖炖2小时左右。#\n8. 出锅前20分钟放入适量盐即可。#'),(474,'蒜薹辣椒炒米豆腐','素菜','蒜薹#\n米豆腐#\n自做蒜茸辣椒#\n盐#\n鸡精#\n酱油#','6根#\n一块#\n一勺#\n适量#\n适量#\n适量#','1. 米豆腐一块#\n2. 蒜薹切粒#\n3. 米豆腐切成方块，油煎#\n4. 煎黄后加入蒜粒和一勺辣椒酱，加盐，鸡精，酱油炒均#\n5. 做好了！吼吼：上饭#'),(476,'大话私房炒菜~秋葵炒蛋','荤菜','秋葵#\n鸡蛋#\n耗油#\n盐#\n胡椒粉#','适量#\n两个#\n适量#\n适量#\n适量#','1. 准备好原料，秋葵，鸡蛋#\n2. 秋葵焯水，建议焖锅两分钟，因为稍大的壳会生，就会影响口感#\n3. 捞出后，凉水冲过，去头尾切小段#\n4. 秋葵切段后撒胡椒粉拌匀#\n5. 鸡蛋小炒#\n6. 倒入撒好胡椒粉的秋葵翻炒，加入耗油，和适量的盐，加少许水继续煸炒（ps:水一定要少）#\n7. 出锅……#'),(477,'中式泡菜','素菜','黄瓜#\n胡萝卜#\n青椒#\n雪花梨#\n苹果#\n蒜蓉辣酱#\n白醋#\n盐#\n糖#','1条#\n1个#\n1个#\n1个#\n1个#\n适量#\n适量#\n适量#\n适量#','1. 准备食材，各种材料洗净切长条块，放入容器待用。容器最好不要用不锈钢制品#\n2. 撒入适量的盐，静置15分钟，杀出盐水，倒掉#\n3. 放入蒜蓉辣酱，白醋，糖，拌匀用量嘛，辣酱略多一点点，糖醋依个人口味就好#\n4. 静置，12小时～#\n5. 大功告成！#'),(478,'西红柿白菜煮年糕','素菜','年糕#\n西红柿#\n白菜#','半只#\n一个#\n适量#','1. 热锅加油，把洋葱和切好的泡发香菇倒入锅煸炒，然后倒入西红柿，再加点酒，白糖（可以不加），继续炒，然后加水，倒入年糕盖上锅盖等水稍微开了再加菜叶，再加盐，炒一会儿盖上锅盖，等水开滚就差不多熟了，然后加味精和葱花。营养又健康#'),(481,'蒜香排骨～蒸','荤菜','盐#\n生姜#\n酱油#','适量#\n少量#\n适量#','1. 切很多蒜蓉，一点生姜末，喜欢辣加一点辣椒。放上酱油，盐。一点料酒拌均。喜欢爽滑口感的加生粉。喜欢咬肉丝的就以上调料足够#\n2. 保鲜膜盖起来放冰箱冷藏一会入味。天气不够冷的话容易变质，所以冷藏安全点。我是吃完中饭就腌制上了，晚饭时间非常入味了。#\n3. 摆盘上锅中大火蒸30分钟。如果排骨肉少，时间可以短点，如果买的排骨连的肉很厚就适当增加点时间。肉多的一面朝下放，为了让汤汁浸泡#\n4. 蒜蓉汁拌饭，老公喜欢#'),(482,'酱油水鱿鱼#青春食堂#','荤菜','冷鲜鱿鱼#\n姜片#\n蒜#\n葱白#\n红美人椒#\n海鲜酱油#\n胡椒粉、料酒、蚝油#\n油#','两条#\n3片#\n3瓣#\n半根#\n1只#\n适量#\n适量#\n适量#','1. 将鱿鱼去骨清理干净。#\n2. 配料。#\n3. 鱿鱼身用刀划出均匀的小口，不要划断。#\n4. 热锅冷油，放入姜、蒜、葱、辣椒爆香。#\n5. 加入料酒、海鲜酱油、清水熬制两分钟。#\n6. 将用胡椒粉、料酒腌制过的鱿鱼放入锅里煮几分钟，直至鱿鱼变白，最后加一勺蚝油即可。#\n7. 鱿鱼装盘，放一些葱叶装饰一下。#'),(483,'香甜娃娃菜','素菜','娃娃菜#\n香菇#\n虾米#\n油#\n盐#\n鸡精#','500克#\n4个#\n20克#\n适量#\n适量#\n1勺#','1. 准备好一个娃娃菜；#\n2. 娃娃菜，一片一片摘下；#\n3. 切成长长的小片，洗干净；#\n4. 捞出，洌干水；#\n5. 准备好四个香菇；#\n6. 香菇切成碎末；#\n7. 准备好的虾米，洗干净；#\n8. 热锅，放油，爆炒虾米和香菇末；#\n9. 加入娃娃菜；#\n10. 加一点鸡精、盐，翻炒；#\n11. 香甜的娃娃菜出锅了。#'),(485,'火爆猪肝','荤菜','猪肝#\n青红椒#\n盐#\n料酒#\n胡椒粉#\n生抽#\n自制的泡朝天椒、红白萝卜#\n生粉#\n生姜大蒜#','300g#\n各一个#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 猪肝洗净切薄片，用少许生粉、料酒、胡椒粉腌制以此去些腥味儿。#\n2. 生姜大蒜切丝，青红椒切小菱形块，泡过的朝天椒萝卜切好备用。#\n3. 热锅油到六七成热时，下姜蒜朝天椒炝锅，放腌制好的猪肝快速翻炒，依次加入青红椒，泡萝卜继续翻炒，这期间再加盐料酒胡椒粉生抽调味儿，待猪肝完全变色就快出锅了！#\n4. 美味已出炉，怎么样？看着就有食欲吧！#'),(486,'火腿粉丝包菜','素菜','火腿肠#\n粉丝#\n圆白菜#','2根#\n2团#\n1小颗#','1. 1、先将粉丝泡在水里10分钟。2、圆白菜切细条。3、火腿切块。4、粉底稍微泡软后扯断。5、起火，锅内放油，油热后放入葱，辣椒炝锅，放入火腿翻炒下，再放圆白菜翻炒，再放粉丝翻炒，放酱油，盐翻炒，熟后出锅前放入鸡精。#'),(487,'【葱香油爆虾】','荤菜','新鲜明虾#\n香葱#\n料酒#\n盐#\n糖#','#\n#\n#\n#\n#','1. 鲜虾择掉两须，洗净沥水备用（买来的活虾养不到半天就会缺氧死了~不过我其实不忍杀活蹦乱跳的= =这样反而好办）#\n2. 宽锅热油~下鲜虾旺火爆至颜色变红后捞出控油#\n3. 锅内留少许底油~加葱花儿爆出香味#\n4. 放入过了油的虾后立即烹入料酒#\n5. 加盐调味~不停翻炒~再加一小撮儿糖提鲜#\n6. 旺火迅速让料酒蒸干~起锅#\n7. 成品~#'),(489,'凉拌豆角','素菜','鲜豆角#\n大蒜#\n芝麻酱#\n芝麻油#\n盐#\n醋#\n生抽#','#\n#\n#\n#\n#\n#\n#','1. 豆角去头尾洗净，蒜去皮洗好。#\n2. 锅中放水，水开放入豆角焯水断生捞出，放入凉水盆中。#\n3. 蒜擦末(我用擦子擦的)，放适量盐，生抽，醋，芝麻油调成汁。芝麻酱加少许盐，饮用水调好。#\n4. 豆角控水切成段(长短随个人喜欢)，分别淋入蒜汁，芝麻酱即可。#'),(490,'豆腐','素菜','豆腐#\n土豆#\n花椒#\n油菜#\n葱#\n蒜#\n生抽#\n鸡粉#','#\n#\n#\n#\n#\n#\n#\n#','1. 豆腐切小块过油，金黄色时捞出沥干油（番茄酱及生抽调汁备用）土豆切片过油，微黄时捞出，无需切太薄锅内放油，八成热时放入葱蒜爆出香味儿以后，放入豆腐翻炒两分钟后，倒入番茄汁，再放入油菜，适量加些水（也可以不加，油菜会出水）待油菜将熟之时，放入炸好的土豆片翻炒两分钟（太早放土豆片，略失口感   ）出锅装盘时再放适量盐及鸡粉调味儿即可#'),(493,'黄瓜拌鸡丝','荤菜','鸡胸肉#\n黄瓜#\n胡萝卜#\n蒜#\n姜#\n葱#\n生抽#\n醋#\n白糖#\n干辣椒#\n料酒#\n盐#\n油#','1块#\n50克#\n50克#\n2瓣#\n2片#\n1根#\n1汤匙#\n1汤匙#\n1茶匙#\n4个#\n1汤匙#\n#\n#','1. 备材料#\n2. 鸡胸肉清洗后，添加没过的水，加点葱姜和料酒，大火煮开转中火煮至鸡肉熟透；#\n3. 黄瓜切丝；胡萝卜切丝；#\n4. 鸡肉晾凉后撕条；#\n5. 蒜切末，辣椒切段#\n6. 材料都放大碗里，加盐、糖、生抽和醋拌匀；#\n7. 小锅里加油，小火将蒜蓉和辣椒炒出香味#\n8. 趁热浇在拌好的黄瓜鸡丝上即可。#'),(494,'烤鸡翅','荤菜','鸡翅#\n老抽#\n白糖#\n盐#\n孜然粉#\n黑胡椒#\n椒盐#','1000g#\n3勺#\n2勺#\n4勺#\n5勺#\n2勺#\n1勺#','1. 鸡翅洗净，将所有调料混合后腌制鸡翅3小时以上，然后准备烤盘#\n2. 准备烤盘下面铺上锡纸，上面放鸡翅这样可以烤出来多余的油脂#\n3. 准备入烤箱，用牙签在鸡翅上插一些洞，这样能把多余油脂烤出去滴到下面的烤盘上，这样吃的时间才能口感更好#\n4. 芝麻炒熟备用#\n5. 鸡翅烤熟撒上芝麻即可#'),(495,'我的减肥菜——清炖牛肉','荤菜','牛肉#\n姜#\n蒜#\n花椒大料#\n大葱#\n盐#\n酱油#\n干辣椒#\n炖牛羊肉料#\n鲜橘皮#','500g#\n适量#\n适量#\n适量#\n适量#\n1勺#\n2勺#\n4个#\n1包#\n4条#','1. 牛肉切成你要的样子！！#\n2. 一些配料  干辣椒，姜，大葱，橘皮，炖牛羊肉料#\n3. 烧一锅水，放入葱！姜！花椒，大料！水开后放入切好的牛肉#\n4. 就是这样，烧开后撇去沫#\n5. 再换一个锅或者继续用刚才那个，在来一锅清水，放入葱，姜，蒜，橘皮，炖肉料，干辣椒！酱油，盐     （如果是电饭煲  35分钟就好！！！如果用普通锅，开锅后 小火慢炖 一个小时）#\n6. 搞定！      胖宝宝们#'),(497,'凉拌芹菜花生米','素菜','芹菜#\n花生米#\n盐#\n花椒#\n大料#\n香叶#\n桂皮#\n茴香#\n橄榄油#\n芥末油#\n味精#\n香油#\n醋#','75G#\n100G#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备所有食材。#\n2. 花生米用水泡开；水锅放花椒、大料、香叶、桂皮、茴香、盐等，放入花生米中小火煮熟。#\n3. 凉凉待用。#\n4. 芹菜拍扁斜切小段。#\n5. 用水焯断生即可（水中放一点盐和一两滴麻油）#\n6. 用凉水泡一下，捞出控出水份。#\n7. 把芹菜和花生米放一起，放盐、橄榄油、芥末油、一点点味精、香油等调味品。#\n8. 拌匀就可以了。吃之前可放一点醋。#'),(498,'蚝油蒜蓉西兰花','素菜','耗油#\n生抽#\n盐#\n油#\n蒜末#\n鸡精#','两匙#\n三匙#\n适量#\n适量#\n适量#\n适量#','1. 蒜切末，西兰花摘好。#\n2. 锅中烧水，水尽量多一些。等水烧开后，加入少量油、盐和鸡精，放入西兰花，让水没过西兰花。#\n3. 煮的时间看个人喜好。喜欢硬点儿的煮2到3分钟，我喜欢软点儿，一般煮5到7分钟。捞出。#\n4. 煮西兰花的水倒掉大部分，留大概大半碗水的样子，重新放火上。火开小些，放入耗油、生抽和蒜末，不停的搅动。#\n5. 待锅中的汁开始冒小细泡时，即可倒入装西兰花的盘中。完成！#'),(499,'快手麻辣香锅','荤菜','土豆#\n胡萝卜#\n泡发香菇#\n木耳#\n藕#\n青椒#\n芹菜#\n大虾#','3个#\n2个#\n若干朵#\n一小把#\n1段#\n3个#\n4根#\n8个#','1. 锅里适量油，土豆切片，油热倒入土豆片，然后切胡萝卜片再放入一起煎，随后入几个红辣椒，炒出辣味儿。。。煎这一步不要省，不然不够香，趁这个时间可以切藕片啦#\n2. 四五分钟后放入香菇木耳，大虾，继续翻炒，加入少许五香粉，没有就加花椒也行，少许酱油上色增香，翻炒均匀#\n3. 最后放入藕片，藕片很容易熟，出锅前加入青椒或者芹菜，盐调味儿，就出锅啦！色香味俱全噢！整个过程少于半小时#'),(500,'红烧青鱼','荤菜','青鱼#\n面粉#\n葱#\n姜#\n蒜#\n红辣椒#\n盐#\n白糖#\n酱油#\n醋#\n料酒#\n花椒#\n大料#','三条#\n#\n少许#\n少许#\n少许#\n少许#\n适量#\n适量#\n适量#\n适量#\n适量#\n少许#\n少许#','1. 青鱼买回家把头去掉，内脏清理干净，用盐腌半个小时#\n2. 雨裹上一层面粉#\n3. 热锅放油把鱼炸一下，两面都金黄色#\n4. 大料花椒炸出香味后放葱姜蒜，红辣椒炝一会#\n5. 把炸好的鱼放锅里，放上事先准备好的酱油，醋，料酒，白糖，盐，放热水，于鱼平齐就行，盖上盖子小火慢炖30分钟#\n6. 饿了吗，开吃吧#'),(501,'上海年夜菜-停不了口的肉丸','荤菜','酱油#\n料酒#\n葧荠#\n葱姜#\n淀粉#\n水#\n油#','4勺#\n5勺#\n1000g#\n少许#\n3勺#\n两勺#\n500g#','1. 葱姜切成末#\n2. 将切好的葱姜倒入肉糜中、倒入酱油拌匀#\n3. 将葧荠切成末#\n4. 将葧荠倒入肉糜中拌匀#\n5. 顺时针搅拌成这样#\n6. 把肉在手中弄成球状#\n7. 等油热了以后放入肉丸，炸成金黄色盛出来#'),(502,'家常干烧阿根延大红虾','荤菜','大红虾#\n酱油#\n番茄沙司#\n料酒#\n盐#\n糖#\n葱#\n姜#\n蒜#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 大红虾室温解冻，清洗干净，剪去虾须，挑去虾线。#\n2. 葱，姜，蒜切末。#\n3. 锅中放少许油，五成热时，放入红虾，两面煎，5分钟后放入蒜、姜末，继续煎至九成熟。#\n4. 倒入料酒，酱油，番茄沙司，糖，盐，翻煎两面。#\n5. 5分钟后即可起锅装盘，撒上葱花即可开吃了哈。#'),(503,'柠檬鸡块','荤菜','鸡腿/Thigh 肉去骨切麻将大#\n粘米粉#\n木薯粉/芡粉#\n面粉#\n柠檬汁#\n冰糖 （1 1/2 tbsp）#\n少许芝麻 （烤香）#\n切碎的柠檬皮 （削皮刀削出来的薄片切碎）#\n蛋清#\n料酒#\n盐#\n胡椒粉#\n几滴麻油#','350-400 克#\n1/4 杯#\n1 tsp#\n1 tsp#\n3 tbsp#\n10-12 颗#\n#\n1 小勺#\n2 tsp#\n1 tbsp#\n1/2 tsp#\n1 撮#\n#','1. 把鸡肉块用所有的腌料腌20-30分钟，然后把沾粉拌入，拌勻後入锅中火炸成金黄色。鸡肉腌料：2 tsp 蛋清1 tbsp 料酒1/2 tsp 盐1 撮胡椒粉几滴麻油沾粉：1/4 杯 粘米粉1 tsp 木薯粉/芡粉1 tsp 面粉#\n2. 柠檬削皮切碎，然后挤出柠檬汁备用。#\n3. 锅里下一点点的油，把冰糖（我混了点红糖）下锅，倒入柠檬汁和切碎的柠檬皮一起煮至冰糖溶化.#\n4. 糖浆开始呈泡泡状时，倒入鸡块快速翻匀，起锅前撒上芝麻。#'),(504,'土豆咖喱鸡','荤菜','土豆#\n鸡腿肉#\n胡萝卜#\n百梦多微辣咖喱#\n洋葱#','#\n#\n#\n#\n#','1. 1、把鸡肉、土豆、胡萝卜、洋葱洗净、切块；2、在锅里倒入多一点色拉油，把洋葱煸香；3、洋葱捞出，把鸡肉过一下油；4、鸡肉捞出，把胡萝卜过一下油；5、把鸡肉、洋葱、土豆一起下锅，锅里加水超出菜面即可；6、放入百梦多微辣咖喱，开中火煮到土豆烂，菜菜入味即可起锅。（喜欢咖喱拌饭的可以多放点水，汤汁会多）#'),(505,'蜜汁山楂','甜品','山楂#\n冰糖或蜂蜜#\n盐#','250g#\n100g#\n一小勺#','1. 一勺盐加入水中，山楂浸泡20分钟#\n2. 山楂去两头，中间切开去籽#\n3. 锅中加60毫升水，和山楂一起煮五分钟后，加糖不停搅拌成糊状。#\n4. 放入方形容器，盖一层保鲜膜放入冰箱速冻柜三个小时直至成膏状#\n5. 取出后，切成小正方形摆盘即可，酸酸甜甜好开胃的！#'),(506,'白菜烩豆腐','素菜','大白菜#\n老豆腐#\n母鸡汤味浓汤宝一块#\n姜#\n葱#','4、5瓣#\n3两#\n#\n3、4片#\n#','1. 白菜叶和帮用刀分开，其中帮斜刀片开，叶切大片，豆腐切片#\n2. 热锅凉油爆香葱姜，先下白菜帮翻炒片刻下白菜叶，塌水后放入豆腐和浓汤宝，加适量水，盖盖，大火烧开转小火炖至白菜微软，淋入少许水淀粉，出锅#'),(507,'太极八卦汤','汤','菠菜#\n香菜#\n鸡蛋#\n豆腐#\n虾仁#\n盐#\n淀粉#','3颗#\n3颗#\n3颗#\n1块#\n5个#\n#\n#','1. 把菠菜和香菜洗干净备用，淀粉加水备用（勾芡）把虾仁、豆腐切成小块#\n2. 把三个鸡蛋打匀加入温开水 少许盐。用保鲜膜封好在微波炉里用高火打5分钟#\n3. 把菠菜切成碎末放入榨汁机打成汁，放几块豆腐也榨成汁#\n4. 用煮锅倒入菠菜汁加入少许盐。把切好的香菜放入锅里烧开。最后倒入水淀粉 勾芡。开锅后倒入鸡蛋羹上面#\n5. 把豆腐汁倒入锅中加入虾仁、豆腐、盐、香菇（香菇也可以不加） 烧开后倒入水淀粉。可以装饰了 八卦的造型#\n6. 上面汤也好喝 别忘了下面还有鸡蛋羹#'),(508,'紫甘蓝拌豆腐丝','素菜','紫甘蓝#\n豆腐皮#\n蒜末#\n葱末#\n干辣椒#\n花椒#\n白醋#\n白糖#\n盐#\n油各#','150g#\n50g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 紫甘蓝一叶一叶掰开，放到水里泡半小时。#\n2. 豆腐皮洗净，切成丝。#\n3. 紫甘蓝洗净切细丝，切的越细越好（拌起来容易入味）。#\n4. 豆腐丝和紫甘蓝收到一起。#\n5. 开火，稍有，把花椒炸香捞出。#\n6. 葱末和干辣椒放到油里，炸香。#\n7. 炸好的葱油凉温，泼在豆腐丝上。#\n8. 放蒜末、白醋、白糖和盐搅拌均匀即可。#'),(509,'#百年栗园宝宝蛋试用#番茄鸡蛋羹','荤菜','宝宝蛋#\n温水#\n番茄#\n盐#\n糖#\n橄榄油#','2个#\n7勺#\n2片#\n少许#\n少许#\n少许#','1. 百年栗园宝宝蛋#\n2. 用两只鸡蛋#\n3. 将鸡蛋打散#\n4. 然后加入7勺水，搅拌均匀#\n5. 盖上保鲜膜#\n6. 用牙签在保鲜膜上扎些小孔儿#\n7. 上锅蒸，锅开后蒸15分钟左右即可。#\n8. 将番茄切丁#\n9. 锅中倒入橄榄油，然后放入番茄炒出汤汁加盐和糖，翻炒均匀即可，然后浇到蒸熟的鸡蛋羹上即可#'),(510,'番茄豆角','素菜','香肠#\n长豆#\n番茄#\n蒜片#\n盐#\n鸡精#','#\n#\n#\n#\n#\n#','1. 香肠番茄切片，长豆撕段#\n2. 爆香蒜片，放入香肠，炒出油后，放入长豆爆炒#\n3. 长豆变色后，放入番茄，炒出番茄酱汁，倒入适量水，盖锅盖炖吧，中途放入盐，鸡精调味，炖至长豆软烂入味，就可以收汁出锅咯！配上米饭，根本停不下来…#'),(511,'玉米胡萝卜筒子骨汤','汤','筒子骨#\n胡萝卜#\n玉米#\n食盐#\n葱#','1根#\n1-2根#\n3根#\n若干#\n若干#','1. 备好玉米和胡萝卜#\n2. 葱切成段#\n3. 把筒子骨焯水，一定要加点葱进去，这样去腥效果特别好，嘿嘿#\n4. 这步也很重要，焯好的骨头一定要用冷水冲洗干净，这样热胀冷缩，肉质会很Q弹#\n5. 接着把所有处理好的食材放入锅中，一次性加满水，没过食材，大火煮开后转小火，炖2-3个小时#\n6. 搞定！加点盐开喝了哦！不要太香啊！而且汤头是甜甜的！有个小窍门！怕胖的同学们可以等汤过夜后，把上面冻起来的油撇掉，这样就又好吃又不用怕胖了哈哈！！#'),(512,'番茄炒鸡蛋','荤菜','番茄#\n鸡蛋#\n葱#\n盐#\n糖#','两个#\n两个#\n适量#\n适量#\n适量#','1. 番茄切片，鸡蛋打好放在碗里待用。#\n2. 油烧热，倒入打好的鸡蛋，炒至焦黄出锅，放碗里待用。#\n3. 少许油烧热倒入番茄大火翻炒，加少许水中火焖煮几分钟到收汁（喜欢番茄汤汁泡饭的可以多放点水，到时候盐等调料也适量的多加一些）。#\n4. 倒入炒好的鸡蛋，并加入盐，糖，翻炒30秒后加入香葱，再翻炒几下，美味出啦！#'),(513,'鹑鹑欲动——菁选酱油试用','荤菜','豌豆苗#\n鹌鹑蛋#\n菁选酱油#\n剁椒#\n鸡精#\n白糖#\n大蒜#','250g#\n随意#\n适量#\n两勺#\n少量#\n少许#\n一头#','1. 准备好食材#\n2. 蒜切粒，鹌鹑蛋煮熟去皮#\n3. 豌豆苗洗净，锅里烧水，水开后滴几滴油，加盐，豌豆苗放进去略烫一下，捞出和鹌鹑蛋一起摆盘#\n4. 锅里烧油，油热后倒入蒜粒爆香#\n5. 倒入菁选酱油炒匀#\n6. 倒入剁椒，鸡精，白糖翻炒，加少许水炒匀#\n7. 炒好的酱浇在烫熟的豌豆苗周围#\n8. 吃的时候拌匀即可……#'),(514,'蒜蓉粉丝蒸虾','荤菜','海虾  大蒜、绿豆粉、葱花儿！m#','#','1. 把虾洗干净，#\n2. 然后用剪刀把虾的脚和须剪掉、再从背部把虾剪开把中间的虾线取出、再这之前可以把粉用凉水或开水泡一下20分钟！捞出剪两端盛盘！虾一个个放在上面！#\n3. 摆好后放在一边、开始把大蒜切碎，锅到用热一下到进去炒15秒、然后放入盐，料酒、白糖、白胡椒粉、一滴酱油，加点高汤炒一下关火#\n4. 把炒好的蒜蓉放在虾上、锅烧开水后、把虾放进去蒸4分钟！取出洒葱、烧点油淋上去、就好了！#'),(515,'虎皮青椒（辣椒或菜椒）','素菜','青椒#\n生抽或者老抽#\n食用油#\n醋#\n盐#\n糖#','300g#\n少量#\n少量#\n少量#\n少量#\n适量#','1. 青椒洗净切块，蒜剥开用刀拍扁。#\n2. 热锅，把锅热高温，再调小火#\n3. 把青椒倒入热锅中，不加任何调味和油，开始煸炒。（这一步是变成虎皮和去掉青椒部分水份的）#\n4. 当青椒煸炒后微微起皮 关火盛盘 放置一边#\n5. 锅内加少许油加蒜煸香#\n6. 倒入青椒 加入糖和酱油翻炒出锅装盘（依照个人口味加醋调味）#'),(516,'香辣炸鱼','荤菜','粘米粉#\n油#\n盐#\n酱油#\n辣椒粉#','100克#\n1勺#\n1勺#\n1勺#\n30克#','1. 炸粉；#\n2. 粘米粉，#\n3. 皖鱼切块，放盐、油、酱油、搅拌均匀，撒上；辣椒粉，腌制15分钟；#\n4. 加入炸粉、粘米粉，加水搅拌，放入鱼块一起搅拌均匀#\n5. 热锅，倒油，（多些油，掩盖炸的鱼块）#\n6. 放入锅中炸，微黄，翻另外一边，继续炸到微黄，#\n7. 夹起，即可吃了。#'),(517,'酸辣豆角（酸辣长豇豆）','素菜','蒜#\n盐#\n辣椒#\n肉末#','#\n#\n#\n#','1. 先将长豇豆洗净凉干。#\n2. 将凉干的长豇豆切碎。将蒜头切碎。#\n3. 将切好的长豇豆和蒜末装进玻璃瓶（我用的是豆腐乳的瓶），加盐拌匀即可。盐量只需放平时做菜的用量就行。#\n4. 将盖子盖好，倒放在盛水的器皿里（以防空气进入）。一般情况下两天后看到长豇豆颜色变黄即可食用，喜欢吃酸些的可多放一、二天。#\n5. 将辣椒切成小圈，肉切成沫，入油锅煮。再放入长豇豆炒一会，便可以食用。#'),(518,'糖醋里脊～酸甜味蕾','荤菜','猪瘦肉#\n食用油#\n番茄酱#\n生抽#\n盐#\n糖#\n醋#\n淀粉#','#\n#\n#\n#\n#\n#\n#\n#','1. 猪瘦肉切条，用少许生抽，少许淀粉抓匀，腌制十分钟。#\n2. 用三勺醋，四勺糖，少许生抽，适量的盐，少许温水，少许淀粉，调成稀汤汁。#\n3. 把瘦肉条裹上面糊，把瘦肉条一条一条放入油锅中炸，可分两次放入，注意放进去之后不要翻动，否则面糊容易掉。#\n4. 一遍炸完之后，全部复炸一遍。为的是表皮更酥脆。#\n5. 锅中留少许油，加入五勺番茄酱，翻炒至均匀散开，然后加入之前调好的料汁。翻炒至冒泡，随即，关火。#\n6. 把炸好的里脊放入翻炒，至全部均匀粘上料汁。即可#'),(519,'泡鸡爪','荤菜','新鲜鸡爪#\n盐#\n醋#\n生抽#\n蒜瓣#','#\n#\n#\n#\n#','1. 鸡爪2斤 去指甲 对半斩 锅内放水烧开倒入鸡爪后调小火煮十分钟 捞起放纯净水或者过滤水下不断冲洗至干爽无油 再冷水泡三五分钟后沥干水分#\n2. 准备调料有 生抽 白醋 纯净水各一碗 比例1：1：1 （用家里吃饭的碗测量）少许盐 冰糖 蒜#\n3. 如果要辣味 可2棵小辣椒切碎加入#\n4. 全部配料倒入后摇匀 密封盒腌制10小时 OK啦#'),(520,'香椿炒鸡蛋','荤菜','嫩香椿芽#\n鸡蛋#\n盐#','#\n#\n#','1. 香椿洗净，过开水焯烫30秒-1分钟时间，看香椿芽由红变绿即可。#\n2. 捞出过凉水浸泡，滤干水份。切碎。#\n3. 鸡蛋打散。锅里放油，油热后倒入鸡蛋液，迅速翻动，至蛋液凝固后盛出备用。#\n4. 锅里放少许油，放切碎的香椿，后放入炒好的鸡蛋，放盐，翻炒均匀即可。#'),(521,'三鲜日本豆腐','荤菜','日本豆腐（禽蛋豆腐）#\n虾仁#\n干贝#\n扇贝肉#\n杏鲍菇#\n番茄酱#\n海鲜酱#\n糖#\n盐#\n玉米淀粉#','5个#\n适量#\n适量#\n适量#\n1~2个#\n3大勺#\n1大勺#\n一小勺#\n适量#\n适量#','1. 虾仁洗净去食线，干贝清水泡发，扇贝洗净。#\n2. 日本豆腐从中间切开，分成两段，再切成6块。#\n3. 日本豆腐裹一层玉米淀粉，下油锅炸，炸到外皮有点脆就可以了，这样炸过的日本豆腐在炒的时候比较不容易碎。#\n4. 杏鲍菇切成格子纹，吃的时候口感会比较好，#\n5. 再切成小块#\n6. 锅里放油煸炒虾仁，放入番茄酱和海鲜酱，再放一点糖。#\n7. 放杏鲍菇，扇贝和日本豆腐， 放点水闷一下。#\n8. 出锅前撒一点盐，翻炒均匀，出锅。#\n9. 开饭喽#\n10. 一起交流学习吧，v信：gaojing9431#'),(522,'青椒番茄焖土豆','素菜','土豆两个#\n青椒两个#\n番茄一个#','#\n#\n#','1. 这个椒有点辣，处理的时候最好快一点。#\n2. 这次的番茄我切成大块的了，放了白糖水进去。#\n3. 蒜米两颗#\n4. 泡水一下，不会黑也不容易粘锅。#\n5. 把番茄和椒炒了先，备用。#\n6. 洗一下锅后炒土豆然后放水焖几分钟，放盐和酱油，水收得差不多就倒下番茄和椒，翻炒一分钟后倒入蚝油然后出锅。铛铛~_~#'),(523,'香其酱炖茄子','素菜','茄子#\n尖青椒#\n香菜#\n香其酱#','2个#\n2个#\n根据自己喜好#\n1包#','1. 所有材料，香菜有点蔫了，凑合用点#\n2. 茄子洗净，用手掰成块，放到锅里开锅后蒸5分钟，这样一会炒的时候不吃油，而且容易烂#\n3. 将尖青椒切成丝，待会备用。#\n4. 香菜洗好，切好，备用，由于香菜蔫了就用了这些，其实多放点更好吃#\n5. 等油热了之后依次将姜蒜爆香后将蒸好的茄子放入锅中爆炒，接着放尖青椒，差不多就可以把我们的主角香其酱放进去了，根据自己的口味适量放，我个人一般放80克，接着爆炒，火候差不多时倒入纯净水炖一下，等汁收的差不多了把香菜倒入，微微炒一下就可以出锅了#'),(524,'盐水鸭','荤菜','鸭腿#\n花椒，#\n葱，姜#\n料酒#\n大料#\n盐#','3个#\n1小撮#\n#\n1勺#\n1个#\n2勺#','1. 锅烧热改小火，放2勺盐炒到微黄再放花椒粒和大料炒出香味关火。#\n2. 趁热把盐抹在处理干净的鸭腿上，按摩均匀放保鲜盒里，密封好放冰箱冷藏12小时左右。#\n3. 锅里加好清水，放葱姜，料酒和少许盐，把腌制好的鸭腿冲洗一下，放入锅里用大火烧开撇去浮末改小火煮30分钟关火，焖1小时左右。#\n4. 煮好的鸭腿凉透。#\n5. 切块装盘，直接吃或者蘸料吃味道都很棒。#'),(525,'拔丝地瓜','甜品','地瓜#\n白糖#','#\n#','1. 把地瓜切块，用油炸成金黄色。注意，要炸两遍，第一遍炸熟，第二遍待油温高时迅速把炸好的地瓜放到油锅里，迅速翻动，捞出，就会有硬壳。#\n2. 锅里放少许油，放入白糖，翻炒#\n3. 按一个方向不停的搅动#\n4. 糖变成深咖啡色时，把炸好的地瓜倒入锅中，翻动，使其挂糖均匀，关火，出锅#\n5. 装盘就可大吃一顿了#'),(526,'萝卜羊肉汤','汤','羊排肉#\n萝卜#\n葱#\n姜#\n料酒#\n花椒#\n盐#\n味精#','#\n#\n#\n#\n#\n#\n#\n#','1. 羊排肉洗净，沥干血水切块。葱姜洗净分别切段、片备用。羊排肉内放入料酒、姜片抓匀，淹渍半小时。白萝卜洗净，去根须，切成块。#\n2. 锅内倒油烧至六成热，放入葱段煸香，放入腌渍好的羊排肉，大火翻炒过油。#\n3. 汤锅内倒适量清水，大火烧开后放入羊肉，开锅后撇去浮沫，放十几颗花椒去腥，用小火焖煮2小时。#\n4. 放入萝卜继续焖煮1小时，加盐、味精，撒点葱花即可。#'),(528,'清爽豆腐丝','素菜','豆腐丝#\n香菜#\n花椒#\n姜#\n盐#','#\n#\n#\n#\n#','1. 豆腐皮先煮一下，主要是为了干净，不煮也可以。#\n2. 豆腐皮放入香菜，姜丝放在最上。#\n3. 热锅凉油，等油冒烟了下花椒炸一下关火。把花椒扔出去，油倒在姜丝上。#\n4. 可以吃啦，记得拌一下。☆-(?ε?｀#'),(529,'蒸菊花茄子','素菜','茄子#\n生抽、陈醋混合汁（自选）#\n蒜、葱（自选）#\n香油、橄榄油、辣椒油（自选）#','适量#\n适量#\n适量#\n适量#','1. 切5～6厘米的段，截面横竖交叉（5毫米左右）、切到底约1厘米处（不要切断）！入锅蒸15分钟左右至熟。#\n2. 层层叠叠放下！里层插外层空隙，好看些。#\n3. 浇入喜欢的料汁儿、配料！我用生抽、陈醋、香油混合汁儿！麻酱汁也好吃。#'),(530,'【美食厨房】蕨菜炒腊肉','荤菜','蕨菜#\n金字腊肉#\n红辣椒#\n生姜#\n糖#','200g#\n130g#\n1个#\n1小块#\n1勺#','1. 1、蕨菜洗净切段，腊肉切片，红椒切片;#\n2. 2、生姜爆香后倒入腊肉煸炒;#\n3. 3、腊肉煸炒致肥肉半透明时候倒入蕨菜煸炒，并放入适量糖;#\n4. 4、放入红椒一同煸炒3分钟后起锅即可。#'),(531,'砂锅酸菜白肉','荤菜','酸菜#\n五花肉#\n粉丝#\n干辣椒#\n八角#','半颗#\n1块儿#\n1小把#\n两根#\n1个#','1. 酸菜洗净，控干水分切成细丝。#\n2. 葱切细丝，姜切片，蒜切丁，两根干辣椒和一个八角。#\n3. 五花肉凉水下锅，撇去浮沫，水开后下入姜和八角，倒一勺料酒，水沸腾后转小火熬制肉汤，半小时后关火，捞出肉块切薄片，肉汤留用。#\n4. 炒锅倒入油，放入干辣椒、葱、蒜炒出香味，放入酸菜丝，这时候开大火，倒入刚才的肉汤，待汤色变白后转入砂锅继续炖煮。#\n5. 放入肉片铺在最上层，十分钟后放入粉丝略煮，放入些许白胡椒粉即可关火。#'),(532,'【懒人菜谱】腐乳空心菜','素菜','空心菜#\n红腐乳#\n生姜#','#\n#\n#','1. 空心菜洗净切段，切一小撮姜末，待用；#\n2. 三四勺腐乳汁，半块腐乳捣烂，混合在一个小碗里；#\n3. 炒锅热少许油，空心菜和姜末一起入锅翻炒1分钟（可以先放菜茎再放叶子），随后倒入调好的腐乳汁继续翻炒至空心菜略软入味（把盛放乳腐汁的碗加一点水涮下也倒入炒锅），大火收汁，出锅。#'),(533,'糖醋排骨','荤菜','排骨#\n色拉油#\n番茄酱#\n糖#\n料酒#\n盐#\n白胡椒粉#','#\n#\n#\n#\n#\n#\n#','1. 烧热水燥排骨，直到排骨成奶白色。#\n2. 捞出排骨用水清洗干净后，用 白胡椒粉，盐腌制排骨。#\n3. 锅子加热后会有微微冒烟，加入油，煎至排骨成琥珀色，如果时间允许建议逐个煎排骨#\n4. 加入料酒入味后，加入水，番茄酱，糖，改小火，直到排骨入味#'),(534,'鸡蛋炒蒜苗','荤菜','盐#','#','1. 有机蒜苗 割下#\n2. 洗好切段#\n3. 鸡蛋打好#\n4. 放油，遢鸡蛋#\n5. 鸡蛋拿出来，放入蒜苗#\n6. 鸡蛋放入翻炒 加入盐#\n7. 成品可以吃啦#'),(536,'春笋枸杞瘦肉汤','汤','春笋#\n里脊肉#\n青椒#\n枸杞#\n生姜#\n盐#\n油#','半个#\n100克#\n1/3个#\n少许#\n2片#\n#\n#','1. 主要材料。#\n2. 春笋洗净切小片； 青椒切小片； 姜切丝；#\n3. 瘦肉切薄片后加盐、油适量腌10分钟； 枸杞稍浸泡；#\n4. 锅中烧开水，倒入笋片煮半分钟捞出沥干；#\n5. 炒锅中热油，炒香姜丝，然后倒入瘦肉炒至变色；#\n6. 加入青椒炒匀；#\n7. 加水两大碗， 倒入笋片和枸杞；#\n8. 煮开后可撇去浮沫，转中火煮20分钟即可。 喝时加盐调味~~#'),(538,'蒜蓉冬瓜','素菜','冬瓜#\n姜蒜#','一小块#\n适量#','1. 首先把冬瓜切成片#\n2. 锅里烧油，下姜蒜炒香#\n3. 倒冬瓜进去，继续翻炒#\n4. 掺入点水进去#\n5. 放点盐巴#\n6. 然后盖上盖子煮5-6分钟吧，#\n7. 揭开锅盖，用筷子戳下，感觉软了就起锅了，撒点葱花，好看！这是成品图。#'),(539,'清炒生菜','素菜','生菜#\n油#\n盐适量#','两颗#\n适量#\n#','1. 1.菜洗好沥水姜切碎#\n2. 2.热锅冷油，姜下锅爆香#\n3. 3.下盐，放菜翻炒变色出锅#'),(540,'腊肉炒大蒜','荤菜','腊肉#\n大蒜#\n料酒#\n鸡精#','适量#\n适量#\n一小勺#\n适量#','1. 这次用的是广式腊肉，腊肉切片，大蒜切段，头和叶分开哦，(喜欢吃辣椒的可以切点干辣椒)#\n2. 锅烧微热，下腊肉翻炒至出油(油会很多，多出的油可以倒到小碗留着炒别的)#\n3. 出油后倒入大蒜头接着翻炒一会#\n4. 在倒入蒜叶炒至叶微软就可以加点料酒，鸡精，炒均匀就可出锅。爱生活，爱美食，偶微861883299#'),(541,'蚝油炒口蘑','素菜','口蘑#\n葱#\n蚝油#\n油#\n白糖#\n盐#','500g#\n20g#\n15ml#\n15ml#\n10g#\n3g#','1. 准备一斤口蘑，洗干净后切片#\n2. 切葱花#\n3. 焯水口蘑、冲洗干净后放油爆炒，加点盐和白糖，炒一下放点蚝油#\n4. 最后放葱花，翻炒起锅装盘#'),(542,'茄子咸食','主食','茄子#\n面粉#\n食用油#','两个#\n适量#\n适量#','1. 茄子削皮#\n2. 切厚片，切段。不用冲洗，加盐等十分钟等它出水。#\n3. 挤掉水份，加入鸡精跟南德调味。#\n4. 拌入面粉，加水拌成糊糊状，个人喜欢面粉多点裹这茄子的口感，也可以面糊少点。因人而异#\n5. 裹上面粉就可以开炸了。几根裹上面粉就一块了#\n6. 变色了翻面继续炸至焦黄。捞出熟的循环下锅。这样也好控制油温。#\n7. 成品。其实配上生蒜头吃起来别有一番滋味。#\n8. 宝宝喜欢沾番茄酱吃，可以做点蒜水沾这吃。#'),(544,'木耳青椒炒肉','荤菜','木耳#\n青椒#\n五花肉#\n花椒#\n酱油#\n大蒜#\n干辣椒#','适量#\n2～4个#\n适量#\n适量#\n少许#\n适量#\n适量#','1. 青椒切成丝，五花肉切的薄些，木耳泡开并撕开。准备好大蒜与生姜沫#\n2. 锅中放入油，接着放入大蒜、生姜、花椒炒出香味。然后将肉放入，多炒一会儿以免肉肥腻#\n3. 肉炒到适当时将木耳与青椒丝倒入，并放入少量酱油，要多翻炒。木耳会蹦要小心点。加入盐、味精出锅就好了#\n4. 出锅的成品，我放的油比较多，因为木耳油少不好吃#'),(545,'糯米肉圆子','主食','五花肉#\n糯米#\n葱末#\n姜末#\n生抽#\n盐#','500g#\n200g#\n小半根#\n适量#\n适量#\n适量#','1. 准备工作：糯米提前泡三个小时，上锅蒸熟晾凉。#\n2. 将肉末，蒸好的糯米，葱姜末搅拌均匀 并依照个人口味添加调味料。#\n3. 将肉末用手团成鸡蛋大的团子。#\n4. 锅中热油，待油温七成热时一个个的将团子下锅炸制。#\n5. 大火将团子炸至定形后，改中火炸至金黄即可捞出。#\n6. 一定要趁热吃～～～外焦里嫩#'),(546,'东北呼咸菜','素菜','牛肉#\n豇豆#\n芹菜#\n土豆#\n辣椒#','#\n#\n#\n#\n#','1. 把蔬菜洗干净，土豆切块，辣椒手撕开，豇豆和芹菜切成长段，牛肉切成一厘米的粒#\n2. 锅里放油，葱姜爆香，牛肉粒下锅炒五分钟，倒入水#\n3. 牛肉煮至八成熟连汤带牛肉倒入碗中备用#\n4. 锅里再次放油，把芹菜豇豆炒软，把牛肉连汤倒入，依次放入酱油半碗，料酒两汤匙，白糖三汤匙，小火呼十五分钟#\n5. 放入辣椒和土豆，等土豆熟即可，放入鸡精，盛出#\n6. 酱油要多放，不用放盐#'),(547,'莲菜肉盒','主食','五花肉末#\n莲菜#\n五香粉#\n盐#\n胡椒粉#\n鸡蛋#\n面粉#\n苏打粉#\n淀粉#\n葱花#\n香油#','一小碗#\n一根#\n一勺#\n一小勺#\n一大勺#\n一个#\n一碗#\n一小勺#\n半碗#\n少许#\n两勺#','1. 莲菜切片 泡凉水#\n2. 肉馅加入盐 五香粉 胡椒粉 和鸡蛋 香油搅拌。最后放葱花 拌好#\n3. 调面糊 面粉一碗 淀粉拌碗 一勺小苏打。凉水调成挂糊 里边加点盐  图片忘拍了#\n4. 莲菜里边加肉馅 再盖一片莲菜。挂糊 下锅炸。#\n5. 成品。胡调少了 最后几个没什么了#'),(549,'美容丝瓜','素菜','','','1. 丝瓜两根，买的时候要把尾巴掰断，尝一下，看是否苦。#\n2. 把皮削掉#\n3. 丝瓜，蒜，姜，盐，油#\n4. 冷油，热锅，然后放蒜，煸出香味#\n5. 放丝瓜迅速翻炒#\n6. 炒出粘稠度#\n7. 再放蒜，它就入味，然后出锅放盐。#\n8. 成品出来了，再配上一点小番茄。#\n9. 非常美味#'),(551,'芬达话梅鸡翅根','荤菜','翅根#\n芬达#\n话梅#\n葱姜#\n老抽少许调色#','8#\n一瓶，淹没翅根#\n10颗#\n适量#\n#','1. 鸡翅划几刀，葱姜老抽和少许油盐腌制，半小时#\n2. 热锅凉油，油热后翻炒鸡翅，直至变色即可#\n3. 加入准备好的芬达和话梅，大火烧开后改小火，盖盖子炖40分钟#\n4. 大火收汁，装盘即可#'),(552,'凉拌黄瓜拉皮','素菜','拉皮#\n黄瓜#\n肉未#\n葱蒜#\n盐，糖，生抽，#\n陈醋#','2片#\n1根#\n少量#\n#\n#\n#','1. 拉皮切片或条，一般在菜场卖豆制品的地方有卖。#\n2. 黄瓜切丝，蒜切未，放在小盆里，加盐，糖，生抽，陈醋，搅拌后放二十分钟入味。#\n3. 锅加油，放入花椒，变黑后捞出，下肉未加葱蒜未翻炒，少量生抽上色，炒到有微焦，#\n4. 倒人凉皮内，拌匀！#\n5. 香^_^#'),(553,'酸菜粉丝','素菜','粉丝#\n莴笋头#\n彩椒#\n芹菜#\n大蒜#\n酸菜#','1捆#\n1小段#\n1个#\n2根#\n5瓣#\n1小抓#','1. 拿粉丝用热水泡发。#\n2. 配料洗净切条。#\n3. 炒酸菜。#\n4. 放油炒大蒜及其他配料，放生抽、老抽#\n5. 放粉丝、放盐，在放少许水，焖2分钟。#\n6. 就完成了#'),(554,'木耳冬瓜瘦肉汤','汤','瘦肉#\n木耳#\n冬瓜#\n姜#\n蒜头#\n盐#\n白糖#','适量#\n适量#\n适量#\n2片#\n1粒#\n适量#\n适量#','1. 大合照，所以材料切丝#\n2. 姜片蒜头爆香#\n3. 瘦肉先用盐油糖生粉腌制好再炒#\n4. 所以材料翻炒均#\n5. 加水煮10分钟#\n6. 成品！清甜可口#'),(555,'白菜肉沫炒粉丝','荤菜','五花肉#\n白菜#\n粉丝#','#\n#\n#','1. 本来没想过炒出来会这么好吃，所以中间根本没想到要照照片。先把五花肉洗净剁碎，白菜切丝，粉丝用开水泡软。#\n2. 倒入油，炒粉丝还是需要多一点油，虽然油多不健康，但是不多不好吃。倒入肉沫和白菜丝翻炒，炒一会儿就把粉丝捞出水放进锅里，倒入一点料酒、鸡汁酱油、美味鲜酱油，继续翻炒。#\n3. 一直翻炒到粉丝变软，加入适量洋葱酥，继续翻炒一会儿就可以出锅啦！要是中间觉得太干可以适当加入一点料酒。#\n4. 装盘出锅#'),(556,'美味干锅土豆片','素菜','土豆#\n葱花#\n调味料#','1个#\n少量#\n少量#','1. 土豆去皮 ，洗干净，切成薄薄的片#\n2. 锅里放花生油，烧热，放土豆片#\n3. 煎到发黄，放点葱花，增加葱香味#\n4. 放调味料，根据个人口味，最简单的是放方便面调味料#\n5. 装盘开吃 ，喜欢的话就尝试一下吧#'),(557,'青蒜牛肉丝','荤菜','牛里脊#\n青蒜#\n紫洋葱#\n盐#\n生抽#\n蛋清#\n淀粉#','250g#\n100g#\n1颗#\n适量#\n3勺#\n半个#\n适量#','1. 牛里脊逆纹路切成丝，青蒜去根洗净切段，洋葱切条状#\n2. 把牛肉丝放入碗中，入蛋清，生抽适量，淀粉适量，抓匀，多抓一会儿，然后静置15分钟#\n3. 锅里入油，待油温升高后将牛肉入锅划开，快速炒匀，牛肉变色后捞出#\n4. 将锅里入少许底油，洋葱和青蒜入锅炒匀后将牛肉一同翻炒，放入适量盐，适量生抽#\n5. 所有食材均熟透后出锅#'),(558,'美味花蛤蜊海鲜','荤菜','花蛤蜊#\n小米椒#\n大蒜#\n姜#\n葱#\n小青椒#','适量#\n适量#\n4个#\n适量#\n适量#\n适量#','1. 蛤蜊先过水煮，时间不要煮久了，不然蛤蜊肉吃起来会觉得老。准备油烧辣以后放入葱姜蒜辣椒炒至香味出来，放少许的白糖和做海鲜的味极鲜然后把蛤蜊放入锅中一起翻炒，最后放点鸡精和味精即可。#'),(559,'鲜锅兔（跳水兔）','荤菜','兔肉#\n莴笋#\n泡椒泡姜#\n青椒#\n小米辣#\n甜椒#\n仔姜#\n豆瓣#\n大葱小葱#','500g#\n250g#\n150g#\n100g#\n20g#\n一个#\n100g#\n一勺#\n适量#','1. 兔肉买回来暂块洗净，沥干水分，加入适量芡粉料酒盐，拌匀，备用#\n2. 所有材料切好，备用#\n3. 放入适量菜油，七成热放入腌制好的兔肉，炒变色捞起#\n4. 锅里剩下的油不倒，放入切好的泡辣椒泡姜，大葱，豆瓣，炒香#\n5. 炒好的调料加入适量水，烧开后中火熬五分钟，放入焯好的兔肉和莴笋条，大火烧三四分钟#\n6. 三四分钟后，放入准备好的甜椒丝，仔姜丝，青椒段，大火30秒，加入适量盐，鸡精、葱花即可起锅#'),(560,'肉沫豆角','荤菜','豆角#\n肉馅#\n盐#\n酱油#\n耗油#','半斤左右#\n适量#\n适量#\n适量#\n适量#','1. 豆角洗净，切成小块，焯熟备用#\n2. 锅里放油，放葱炒香，放肉沫炒熟。#\n3. 放酱油，继续翻炒#\n4. 放入豆角，加一点水，继续翻炒，#\n5. 放耗油，盐，翻炒均匀，调味出锅即可。#\n6. 装盘#'),(561,'京酱肉丝','荤菜','精瘦肉#\n甜面酱#\n大葱#\n蚝油#\n老抽#\n鸡精#\n白糖#\n淀粉#','#\n#\n#\n#\n#\n#\n#\n#','1. 大葱切丝，偶刀工是硬伤！亲们可以切更细点儿。瘦肉切丝，加少许老抽，鸡精，淀粉码味。酱加，甜面酱，蚝油，老抽少许，白糖混合均匀。#\n2. 起油锅，肉丝滑散，变色。加酱熬开。混合均匀，成功。时间在五分钟左右。#'),(563,'青椒胡萝卜炒子排','荤菜','子排#\n青椒#\n胡萝卜#\n生姜#','一根#\n一个#\n一个#\n三片#','1. 准备食材，青椒生姜活萝卜，子排清洗赶紧加料酒，酱油，盐，白胡椒先腌制十五分钟至半小时即可。#\n2. 胡萝卜青椒生姜切片备用#\n3. 1热油，子排和生姜一起下锅翻炒至变色2将胡萝卜青椒下锅一起炒，加盐，鸡精调味#\n4. 子排还可以这样吃哦！#'),(564,'辣白菜豆腐汤','汤','辣白菜#\n五花肉#\n土豆#\n豆腐#\n食盐#\n白糖#\n五香粉#','250g#\n200g#\n2个#\n1块#\n适量#\n适量#\n少许#','1. 备料#\n2. 土豆切片，备用#\n3. 五花肉，切片，用盐，五香粉抓匀，备用#\n4. 辣白菜跟汤汁分开，备用#\n5. 豆腐切块，备用#\n6. 热锅，倒油，五花肉煸香，#\n7. 放辣白菜，煸炒。#\n8. 放土豆片，翻炒，#\n9. 倒入汤汁#\n10. 加水，#\n11. 放适量白糖#\n12. 适量食盐#\n13. 放豆腐，注意不要使劲翻动，#\n14. 盖盖炖开#\n15. 出锅啦，香香嗒#'),(567,'狼牙土豆','素菜','土豆#\n火腿#\n椒盐#\n孜然粉#\n食用油#','1个#\n一根#\n适量#\n少许#\n少许#','1. 土豆火腿用擦丝切好，#\n2. 美美哒～#\n3. 平底锅内放少许油，#\n4. 油热以后放入土豆火腿，中火煎3分钟，#\n5. 放入椒盐，继续煎3分钟，注意火候，不要煎糊了呦～#\n6. 我喜欢麻辣口的，所以辣椒油里放了一些麻椒，放入辣椒油翻炒，#\n7. 放小半勺孜然粉，继续翻炒均匀，#\n8. 出锅装盘，好吃又好看～#'),(568,'椒盐皮皮虾','荤菜','皮皮虾#\n椒盐#\n红椒#\n葱姜蒜#\n料酒#','500g#\n1勺#\n半个#\n适量#\n2勺#','1. 菜场买了一斤皮皮虾#\n2. 锅烧热，倒稍微多一点油，把皮皮虾倒进去炸一下，炸至皮变色，盛起来。#\n3. 锅里剩的油，加入葱姜蒜爆香#\n4. 把皮皮虾倒进去翻炒，皮皮虾煮的时候本身就会出水，不用另外加水，加两勺料酒去腥。#\n5. 快出锅时，加适量椒盐翻炒均匀即可。#\n6. 出锅装盘#\n7. 好吃。#\n8. 香喷喷#'),(569,'红烧肉（可乐版）','荤菜','五花肉#\n可乐#','500g#\n600ml#','1. 选一条鲜五花肉为原料。#\n2. 用刀切小长方块（注意 别切大，不然味道不浓）。#\n3. 电饼铛烧热，放入肉块，让本身的油榨出来，四面微有些焦黄即可。#\n4. 微微有点焦黄即可盛出来备用。#\n5. 大桶可乐已备好，使用600ml-700ml就好。#\n6.     锅内放入五花肉，倒入可乐没过肉块就行，开火烧开，转小火慢烧，不时查看汤汁状况，当汤汁低于肉块一半以下时要时刻观察  然后大火收汁，几乎汤汁耗尽要不停翻炒  知道发出啪啪响立刻关火 就可以出锅了    此图就是成品。（这道菜不再放其余调味）#'),(570,'吮指的美味【香煎螃蟹】','荤菜','螃蟹#\n盐巴#\n面粉#\n油#','#\n#\n#\n#','1. 瞧这嵌子，估计就是这只夹痛我手的。挑的个个都是母蟹，挺肥的#\n2. 用刷子清洗杂质#\n3. 稍微拍下螃蟹，不然手一不小心就给夹到了，解去绳子，对半切开#\n4. 好多膏黄哈#\n5. 沾少许调好的淀粉#\n6. 锅中倒入少许油，中火煎至两面金黄即可#'),(572,'香干芹菜','素菜','香干#\n芹菜#\n葱姜#\n盐#\n鸡精#\n蚝油#','适量#\n适量#\n适量#\n#\n适量#\n适量#','1. 准备材料#\n2. 锅热放油烧热放葱姜爆香#\n3. 放入芹菜略炒 放入香干 倒适量蚝油 盐鸡精 翻炒均匀#\n4. 出锅 完成～#'),(574,'爆炒海兔头','荤菜','海兔头#\n圆葱#\n辣椒#\n干辣椒段#\n蒜#\n香菜#','#\n#\n#\n#\n#\n#','1. 海兔头清洗干净，去眼睛和喙，用开水焯一下#\n2. 将辣椒切三角块，蒜切片，圆葱切丝，香菜切末#\n3. 锅里放油，油开后放入切好的辣椒段，红辣椒，圆葱和大蒜，炒出香味后加入海兔#\n4. 大火炒，放蚝油，白糖，盐，料酒，胡椒面，酱油，炒到入味后加香菜，关火出锅#'),(576,'奶香番茄浓汤','汤','番茄#\n马铃薯#\n洋葱#\n大蒜#\n乳酪意面酱/番茄酱#\n牛奶#\n淡奶油#\n砂糖#\n海盐#\n黑胡椒粉#\n牛至叶碎（可选）#\n百里香碎（可选）#\n罗勒碎（可选）#\n橄榄油#\n清水#','2个#\n1个#\n1/2个#\n1瓣#\n3大勺#\n100g#\n20g#\n1小勺#\n适量#\n少许#\n少许#\n少许#\n少许#\n适量#\n适量#','1. 番茄底部割十字，沸水烫一会儿，撕皮，切成小块，洋葱，大蒜，马铃薯切小块。#\n2. 橄榄油将洋葱炒香变色，下大蒜，炒出香味。#\n3. 下马铃薯，番茄翻炒。#\n4. 再倒入乳酪意面酱，加水至刚好没过食材，小火炖煮，直到马铃薯能轻易压烂。关火。#\n5. 倒入料理机，搅打半分钟，倒回锅中。#\n6. 加牛奶和淡奶油，开小火。#\n7. 适量加入糖，海盐，黑胡椒粉，牛至叶，百里香，罗勒碎，煮开即可。#'),(577,'什锦火腿 懒人菜','荤菜','冷冻蔬菜粒#\n双汇火腿肠#','#\n#','1. 把蔬菜粒和切成丁的火腿放入油锅翻炒，加入少许盐后，即可出锅#'),(578,'酸辣蛇皮黄瓜','素菜','醋，盐，糖、花椒粉（粒）#','#','1. 新鲜的黄瓜2-3根，洗净（不去皮）。#\n2. 将黄瓜顺序切成薄片，注意不能切断哦（初学者可以在黄瓜两侧放两根筷子）。#\n3. 切完一面反转180度，切反面。同样注意不要切断哦。#\n4. 切完的样子。#\n5. 装盘，在黄瓜的缝隙间撒满盐，腌制10-15分钟。#\n6. 洗去盐粒，攥干水分，并在上面撒上蒜末。#\n7. 用生抽、醋、盐、糖调汁，淋在上面。#\n8. 在锅里加热少许油，炸焦花椒粒和红尖椒，淋在蒜末上。#\n9. 一道酸辣甜香的蛇皮黄瓜出锅了！#'),(579,'日式凉拌豆腐“冷奴”','素菜','内酯豆腐#\n葱花#\n姜泥#\n木鱼花#\n日式酱油#','1块#\n适量#\n适量#\n适量#\n适量#','1. 材料就这些。#\n2. 姜削不削皮都可以，磨成姜泥。#\n3. 葱切葱花，和姜放一起备用。#\n4. 豆腐摆到盘中。#\n5. 先撒上适量木鱼花。#\n6. 然后放上姜泥。#\n7. 最后撒上葱花。#\n8. 浇上适量酱油就可以了。#\n9. 非常简单，当下酒菜也不错。#'),(580,'肉丸萝卜汤——简单好吃','汤','五花肉糜#\n白萝卜#\n葱花#','#\n#\n#','1. 准备食材：五花肉加葱姜末料酒水淀粉顺一个方向搅打上劲，萝卜切斜刀块备用#\n2. 锅放适量水小火将做好的肉丸下入 全部丸子下锅后开中火继续煮至丸子浮起，放入备好的萝卜煮至萝卜绵软，调味撒上葱花#\n3. 成品#'),(582,'醋泡辣萝卜丝','素菜','白萝卜#\n盐#\n麻油#\n白糖#\n生抽#\n辣椒面#\n白醋#','#\n#\n#\n#\n#\n#\n#','1. 白萝卜去皮切丝。（我偷懒，用刨丝器刨滴丝）白萝卜丝里加盐腌制30分钟左右，挤干水份备用。#\n2. 用熟辣椒面加白醋调成醋辣汁，加少许生抽，白糖，麻油拌匀。#\n3. 把步骤2里的料汁倒入挤过水的萝卜丝里拌匀，盖上盖，冷藏4个小时左右即可。#'),(583,'香辣下饭之 - 牙签肉。','荤菜','瘦肉#\n淀粉#\n白芝麻#\n黑椒粉#\n孜然粉#\n辣椒粉#\n姜蒜#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 瘦肉切成薄点的小肉片，加上盐、姜蒜末、胡椒粉、孜然粉、辣椒粉、淀粉拌匀腌制半小时。#\n2. 将腌好的肉用牙签穿上，锅中油烧至七成热，下肉油炸。炸至变色后捞出备用（大概是炸四五分钟）#\n3. 锅中留底油，下姜蒜和干辣椒爆香，加入炸好的牙签肉同一起炒，然后再加入熟白芝麻炒一下就可以出锅啦。#'),(584,'油条炒鸡肉片:（妖妖家的厨房）','荤菜','鸡胸肉#\n油条#\n红椒#\n蒜#\n老姜#\n黄酒，盐，糖，锭粉，老抽，鸡精！#','一块#\n半根#\n三个#\n两根#\n一块#\n各适量#','1. 油条切成小段，红椒切斜刀段，姜切片，蒜切段备用！#\n2. 鸡胸肉切成薄片，用少许料酒，少许老抽，锭粉一起捏制备用！（其实用鸡腿肉更好吃，鸡腿肉更富有弹性，鲜嫩，因为我买了鸡胸肉用了一半煮粥，剩下一半就拿来用炒菜了）#\n3. 热锅上油将红椒段，青蒜，姜片一起下锅爆香！#\n4. 下油条一起颠锅爆香！#\n5. 鸡肉片下锅倒入料酒快速滑开，颠锅加入盐，鸡精快速颠锅均匀入味就可以装盘了！#\n6. 油条的酥脆加上红椒的微辣，鸡肉的鲜嫩融合在一起，真是不错的味道！绝对的下饭菜！#'),(585,'独家白灼油麦菜','素菜','油麦菜#\n生抽#\n米醋#\n砂糖#\n色拉油#\n香油#\n蒜末#\n葱花#\n辣椒油#\n盐#','200g#\n2勺#\n1勺#\n少许#\n适量#\n3滴#\n适量#\n适量#\n少许#\n适量#','1. 油麦菜切成3段待用#\n2. 热水里放点盐和少许色拉油，煮开后放入油麦菜烫一下，约1分钟捞出晾凉沥干水份（必须沥干，否则影响口感）#\n3. 把葱花、蒜末、生抽、米醋、糖、香油、辣椒油调汁，倒入锅内爆个香，马上关火#\n4. 码盘，把汁浇在沥干晾凉的油麦菜上，怎么样，还不错吃吧，很美味，夏天来了，拌起来喽#'),(586,'清蒸毛豆米','素菜','毛豆米#\n蒜瓣#\n葱#\n红椒#\n盐#\n油#','#\n两粒#\n一小段#\n一片#\n#\n#','1. 毛豆角自己动手拨出毛豆米！我特意自己剥的，菜市场也有现成剥好的，#\n2. 洗净毛豆米，装在盘内#\n3. 准备好要用的葱，蒜，红椒#\n4. 放入一点油，盐在洗干净的毛豆米里拌匀#\n5. 红椒切小粒，蒜切碎末，葱切小圆片#\n6. 切好的葱，蒜，红椒粒放在拌匀油盐的毛豆米上#\n7. 入蒸锅蒸20分钟#\n8. 蒸好了！清爽美味的清蒸毛豆米，开吃吧！非常简单的快手菜！#'),(587,'新型保健菜【蒜香秋葵】#夏日时光#','素菜','秋葵#\n蒜头#\n红尖椒#\n盐巴#\n酱油#','500克#\n#\n#\n#\n#','1. 秋葵洗净去蒂#\n2. 锅里烧水，等水沸腾后放入秋葵焯3分钟。沥干水分装入盘中#\n3. 红尖椒和蒜头剁碎备用#\n4. 热锅，倒入少许油，放入红尖椒和蒜头爆香#\n5. 加入少许盐巴和酱油，最后把汁淋在秋葵上即可#'),(588,'香煎五花肉','荤菜','五花肉#\n生菜#\n大蒜#\n辣椒酱#','1条#\n1颗#\n几粒#\n少许#','1. 五花肉切片，放韩国烤肉锅里煎出油，两面金黄时肉就差不多煎好了。#\n2. 生菜洗净、蒜切片，再加上辣椒酱包起来就放开肚皮吃吧！#'),(589,'拔丝地瓜','甜品','地瓜#\n糖#','一个#\n60g#','1. 地瓜削皮，切成菱形块。#\n2. 锅里多放点油，油温热就把地瓜炸至金黄色，表皮硬了就捞出来。把油倒出来，锅里留1/3，改小火，把糖倒锅里，慢慢融化#\n3. 糖融化变深色以后，关火。下地瓜翻炒几下，均匀裹上糖。#\n4. 有拉丝的看见没！备碗凉水，知道啥情况不，吃的时候就知道了！哈哈#\n5. 嘟嘟，卖萌可耻#'),(590,'可乐鸡翅','荤菜','鸡翅#\n可乐#\n料酒#\n生姜  花椒籽#\n老抽 生抽#\n十三香#','#\n#\n#\n#\n#\n#','1. 鸡翅洗干净了用刀划两刀。用料酒、生抽（适量）、生姜、花椒籽、十三香（适量）腌制半小时#\n2. 油加热#\n3. 油煎鸡翅背面，煎至金黄反面煎#\n4.#\n5. 金黄了就可以加可乐（要是觉得油多了可以倒出来再加可乐）#\n6. 中火煮熟（之间要记得吧油泡沫给打去了）#\n7. 看着快熟透就可以加点老抽提色#\n8. 开小火轻轻翻炒一下#\n9. 大火收汁，听到有“滋滋”声就是收汁差不多了，关火吧！#\n10. 完成出锅上盘。看着还是美味哒！吃着还是享受哒！#'),(592,'红烧大虾','荤菜','大虾#\n老抽#\n白砂糖#\n盐#\n番茄沙司#','8只#\n1勺#\n2勺#\n1勺#\n3勺#','1. 大虾洗净备用#\n2. 锅里放底油将大虾小火慢慢炒，翻动要轻，不然虾头掉了不好看，炒至两面金黄后倒出底油只留一点油即可，然后倒入搅拌均匀的料汁，料汁混合后要兑一点水不然太干，开中火继续炒，汤汁快干时候开大火收汁即可#'),(593,'蒜蓉粉丝蒸娃娃菜','素菜','娃娃菜#\n蒜蓉#\n粉丝#\n耗油，豉油，鲜贝露#','一个#\n#\n#\n#','1. 准备食材 ，娃娃菜切6等份，蒜切末，青椒切末，鲜贝露1勺，耗油1勺，豉油两勺，香油少许，粉丝泡开#\n2. 热锅放入葱末，蒜末，炒香#\n3. 倒入调好的酱汁，放入少许盐，糖#\n4. 粉丝放在娃娃菜上，码放整齐，酱汁出锅，加入少许香油#\n5. 将炒好的酱放在粉丝上，入蒸锅，蒸约5~10分钟#\n6. 出锅前撒少许青椒末，即可#'),(594,'柠香煎秋刀鱼～一人食','荤菜','秋刀鱼#\n柠檬#\n生抽#\n盐#\n油#','一条#\n#\n一勺#\n适量#\n适量#','1. 秋刀鱼加料酒，盐腌制十分钟。#\n2. 热锅凉油，煎三分钟左右金黄，翻面。#\n3. 出锅刷生抽，挤上柠汁。#\n4. 好吃～#'),(595,'虾丸汤年糕','荤菜','基围虾#\n年糕#\n生姜#\n红辣椒#\n大蒜苗#\n小青菜#\n鸡蛋#','200g#\n200g#\n2块#\n1个#\n1颗#\n3颗#\n1个#','1. 虾去壳#\n2. 虾剁成泥加入红薯粉加点水搅拌后加入蛋清#\n3. 放点盐搅拌均匀#\n4. 放水烧开并放入生姜和大蒜苗根部，倒入适量油。#\n5. 用勺子把虾泥放入锅中。#\n6. 可以放红辣椒啦！再加点酱油调色。#\n7. 放入年糕煮熟，如只想喝汤的可省略此步骤。#\n8. 放入青菜和大蒜叶。加适量盐。青菜熟后可以起锅啦！#\n9. 成品#'),(596,'黄焖兔子肉','荤菜','新鲜兔子肉#\n八角#\n十三香#\n青椒#\n黄酒#\n酱油#\n孜然粉#\n大蒜#\n姜丝#\n红椒#\n或者米酒#','半只#\n一个#\n一小少#\n各一些#\n一小碗#\n少许#\n一勺#\n三瓣#\n少许#\n#\n#','1. 把兔子肉洗好，剁成块状，就像我图片那么大，比较好入口#\n2. 剁好的兔肉放点盐巴腌制十分钟，在这期间锅里准备烧水#\n3. 水开后把兔子肉放进烧好水的锅里，烫一下过血水后马上捞起#\n4. 放油把大蒜拍碎放进锅里煸会在放入兔肉，姜丝，八角，十三香粉，盐巴，鸡精进去翻炒，<肉有腌制过所以盐巴的量要控制好了>看肉快干了，就倒点少许酱油和先准备好料酒倒进去盖上锅盖隔几分钟翻炒一下，直到汤汁干掉#\n5. 汤汁干了后放入切好的青椒和辣椒翻炒一下，就可以起锅了#'),(598,'家常菜—酸辣土豆丝','素菜','土豆#\n青椒#\n生姜#\n干红辣椒#\n蒜#\n醋#','一个#\n两个#\n一片#\n两个#\n两个#\n一勺#','1. 这是所有食材～#\n2. 土豆对半切开，然后如图切片。#\n3. 再放倒切丝～#\n4. 青椒拍扁也切丝～#\n5. 锅中兑水烧开，然后放一勺醋。 把切好的土豆丝倒入锅中煮开。#\n6. 撇净浮沫捞出～#\n7. 锅中倒油，入姜蒜辣椒爆香～#\n8. 中火下青椒翻炒出香味～#\n9. 放入焯水过的土豆丝翻炒至断生，放入盐～#\n10. 盛盘即可～搞定#'),(600,'咸鸭蛋黄土豆片','素菜','咸鸭蛋黄#\n土豆#\n葱#\n盐、味精#\n西兰花#','3-4个#\n2个#\n2颗#\n适量#\n2小朵#','1. 将咸鸭蛋黃蒸熟（我是买的净蛋黄）。#\n2. 蒸熟的咸鸭蛋黄和切好的土豆片。#\n3. 锅内放入油（多放点淹没土豆片），稍热后倒入土豆片，煎至土豆表面稍黄盛出。#\n4. 锅内放少许油，倒入蒸熟压碎的咸鸭黄翻炒几下后，把土豆片放入锅内翻炒、拌匀即可。#\n5. 盛出装盘。#\n6. 撒上葱花，摆上煮熟的西兰花。美美哒！很好吃哦！#'),(601,'红罗卜佛手瓜雪耳百合无花果汤(最适合秋冬饮用)','汤','雪耳#\n百合#\n无花果#\n密枣#\n猪肉或猪骨#\n陳皮#','随意#\n随意#\n随意#\n随意#\n随意#\n随意#','1. 猪肉氽水，雪耳浸透去脚，合掌瓜红萝卜去皮切块。陈皮浸软去白色部分。#\n2. 所有材料加水，中漫火煲1.5小时至2小时。可以加鹽调味，或不加都很鲜甜。#'),(602,'红烧带鱼','荤菜','带鱼3条#\n淀粉#\n葱姜蒜醋香油料酒#','#\n#\n#','1. 1，将带鱼洗干净，切段2，将带鱼用料酒，盐，生抽，干姜面腌制5分钟3.腌制好的带鱼中放少量淀粉，用量把握在刚好把调料水吸附在带鱼上为佳4.锅中放油，油热后放入带鱼，至两面金黄捞出5.锅中起油，放入蒜，姜煸香，炸好的带鱼放入锅中，放入醋，香油，加入少量水，大火烧开，转小火慢炖大概20分钟，大火收汁，完成。#\n2. 开吃#'),(603,'胡萝卜素不流失的小秘招：胡萝卜炒鸡蛋','素菜','胡萝卜#\n鸡蛋#\n葱#\n淀粉#\n盐#','#\n#\n少量#\n少量#\n少量#','1. 胡萝卜刨丝、葱切葱花。#\n2. 鸡蛋打散之后加少许盐，特别是要加少许水淀粉（这样炒出来不会水水的！！可以最大限度的保住胡萝卜素！）#\n3. 锅里放油（多一点），胡萝卜下锅炒，变成胡萝卜油。#\n4. 沥油，油待用。#\n5. 锅中加一半胡萝卜油，爆香葱花。#\n6. 放入鸡蛋。#\n7. 倒入胡萝卜拌炒，鸡蛋嫩嫩的就可以了。#\n8. 出锅后，淋上剩下的一半胡萝卜油（这个油里可全是胡萝卜素呢~~）。#'),(604,'糖醋藕片','素菜','当季嫩藕一节#\n糖#\n醋#','#\n少许#\n一勺#','1. 切片，浸泡，除淀粉，不粘锅#\n2. 糖，醋，盐，老抽#\n3. 少许油，翻炒#\n4. 把调好的糖醋汁浇入#\n5. 成品#'),(606,'香煎鸡翅','荤菜','鸡翅、#\n生姜#\n大蒜#\n辣椒粉#\n料酒#\n盐#','6个#\n10克#\n两瓣#\n20g#\n#\n#','1. 用盐适量，料酒少许，蒜蓉（两瓣），生姜10克（去腥），辣椒粉20克（个人口味）腌制20分钟#\n2. 加一小勺油（鸡翅本来有油不需要太多）用小火煎7-8分钟（记得翻面），起锅加点孜然粉（胡椒粉、芝麻）#'),(608,'麻辣鲜香香辣虾','荤菜','明虾#\n自制鲜辣粉#\n自制香料粉#\n盐#\n油#\n香麻油#\n白芝麻#\n干辣椒#\n连枝爆花椒#\n香芹#\n姜蒜#\n味素#','500g#\n2g#\n2g#\n4g#\n7g#\n2ml#\n少许#\n少许#\n少许#\n少许#\n少许#\n2g#','1. 鲜活明虾入清水中养1小时待用#\n2. 明虾洗净，去虾须，开背抽泥肠待用#\n3. 姜蒜切片，连枝爆、干辣椒洗净，香芹洗净切段待用#\n4. 坐锅起大油，下明虾过油至头壳半透明，虾身蜷成U字形，捞出沥油待用#\n5. 锅内下5克油，六成热下干辣椒、连枝爆、姜蒜爆香#\n6. 下明虾及香芹，大火翻炒2分钟#\n7. 下鲜辣粉、香料粉、味素、盐，翻炒均匀，炒至手感粘滞，将剩余2克油沿锅沿淋下，继续翻炒2分钟#\n8. 撒白芝麻，翻炒出香，淋香麻油，翻炒均匀，出锅即可#'),(609,'辽宁大连年夜饭必备-海鲜全家福','荤菜','海参#\n鲍鱼#\n鲜虾仁#\n大蒜#','5根#\n若干头#\n若干#\n2瓣#','1. 备料：即食海参切两半，虾仁去掉腥线背后切深刀，鲍鱼肉扣出来切块。#\n2. 首先将虾仁过油，虾仁变色后迅速捞出。#\n3. 调好酱汁：一品鲜酱油4勺、香醋一勺、半勺白糖、适量香油#\n4. 锅内油烧热把葱姜蒜爆香，然后加入水淀粉、调好的酱汁加热到沸腾。然后慢慢收汁的过程中依次加入海参、虾球、鲍鱼。#\n5. 最后收汁后盛出，注意整个过程宜控制到十分钟。如果汁水太多，短时间内收不完汁，就先把海鲜捞出来，总之海鲜烹饪时长务必注意。#'),(611,'利仁电饼铛试用之烤薯角','主食','土豆#\n盐#\n黑胡椒粉#\n色拉油#','3个#\n1茶匙#\n1茶匙#\n1茶匙#','1. 土豆洗净去皮，切菱角块儿；#\n2. 切好的土豆，撒入盐，黑胡椒，色拉油拌均匀；#\n3. 然后放入电饼铛中，上下盘均加热，约烤30分钟，烤至表面焦黄即可。#'),(612,'翡翠白玉汤','汤','豆腐#\n胡萝卜#\n肉丝#\n调料：盐，麻油#','一块#\n一小段#\n100g#\n一勺#','1. 豆腐切小条状，焯水备用。豆腐选了嫩豆腐，很多地方叫法不同，有内脂豆腐，白玉豆腐，嫩豆腐等说法，总之就是很水当当的，闻起来没有柴火味儿的那种。#\n2. 胡萝卜切细丝，梅条肉切丝#\n3. 少油，煸炒肉丝至变色，可以加一丢丢料酒去肉腥，然后加入胡萝卜丝略略炒一下，加入开水煮开#\n4. 水开后，放入豆腐，加少许盐#\n5. 等再次煮沸后，见到翻滚的豆腐君就可以出锅啦，淋点香油会让你味蕾跳舞#'),(614,'肉沫茄子','荤菜','茄子#\n猪肉沫#\n盐#\n白糖#\n郫县豆瓣酱#\n胡椒粉#\n小葱#\n蒜沫#\n干红辣椒#\n生姜丝#\n鸡精#\n酱油#\n料酒#','4条#\n100g#\n1勺#\n2勺#\n1勺#\n1勺#\n适量#\n适量#\n4只#\n适量#\n1勺#\n2勺#\n2勺#','1. 肉沫先用少量老抽、黑胡椒、料酒腌制。#\n2. 茄子切成滚刀块，撒盐腌制出水，然后把水捏干，放盘子备用。#\n3. 以上材料切好备用，分别是生姜、小葱、干辣椒、蒜沫。#\n4. 秘密武器来了，郫县豆瓣酱来一勺！#\n5. 忘记拍煸肉沫的照片了！热锅冷油下肉沫煸炒变色，加一勺料酒先出锅。接着热锅加入适量色拉油，姜丝、干辣椒、蒜沫、郫县豆瓣酱一勺煸出香味，加入挤干水分的茄子翻炒片刻加入适量酱油（我用的草菇老抽）、一勺白糖。茄子变软后肉沫倒进去，再加入小葱、胡椒粉、鸡精。#\n6. 装盘，下饭菜来了！#'),(615,'红烧带鱼','荤菜','带鱼#\n鸡蛋#','一条#\n2个#','1. 带鱼去头，用刷子去掉表面的白鳞，清洗干净后切断#\n2. 然后加入料酒（用花雕酒去腥更好），花椒，葱段，姜片腌制10至15分钟#\n3. 打两个鸡蛋搅散，锅中做油，六成热时裹上蛋液入锅煎至两面金黄#\n4. 带鱼段煎至金黄待用#\n5. 然后调制碗汁：碗中加大葱段，姜片，蒜瓣，花椒，料酒，盐，酱油，冰糖，米醋，白糖少许，调匀。锅中倒少许底油，倒入调好的碗汁#\n6. 倒入带鱼，大火烧两分钟，加入开水#\n7. 水与带鱼齐平，盖上盖子，中小火炖15至20分钟，汤汁收浓即可。#\n8. 成品不太好看，味道还不错！#'),(616,'孜然羊肉炒葱头','荤菜','羊肉卷#\n洋葱#\n孜然#\n干辣椒#\n葱姜#','适量#\n1#\n适量#\n1个#\n若干#','1. 超市买的羊肉卷。25一斤。买了40多块钱的只用了一小半。剩下的放冰箱过几天用。#\n2. 洋葱。#\n3. 切乱刀块儿。切的时候最好戴上面具。不然你就会哭泣。#\n4. 放葱姜辣椒爆香。#\n5. 放入羊肉片。翻炒。炒到肉全部变色。#\n6. 放入洋葱块。接着放入孜然。爱吃孜然的就多放点。然后就翻炒到洋葱断生。#\n7. 不过洋葱很容易炒软炒蔫了。如果爱吃硬脆的洋葱的就少炒一会儿。#'),(617,'油闷茄子','荤菜','茄子#\n葱#\n蒜#','250g#\n1g#\n2g#','1. 茄子洗净，切滚刀块#\n2. 下锅煸炒一会儿，加入酱油，豆豉#\n3. 加入适量水，冰糖，盐，蒜#\n4. 出锅前加入少许油，葱，亮相#'),(618,'炸奥尔良烤翅','荤菜','鸡中翅#\n白砂糖#\n盐#\n辣椒粉#\n味精#\n洋葱粉#','500g#\n1勺#\n适量#\n1勺#\n适量#\n适量#','1. 适量在翅膀里面放入糖、盐、辣椒粉、味精、洋葱粉、腌制2个小时左右#\n2. 锅中烧油#\n3. 放入腌制好的鸡翅膀，记住一定要不停翻面，关小火以免糊了、哈哈 ！ 一次炸几个根据你锅的大小而定，我是一次4个，每次时间也就10分钟左右就熟了！#\n4. 最后摆盘，我在上面放了葱花，觉得要有点绿色好看一些，#\n5. 外酥里嫩的奥尔良烤翅就完工了！美味哒！#'),(619,'卷粉','主食','卷粉皮#\n瘦肉#\n虾米#\n红萝卜#\n大头菜(我们这里叫冲菜)#','2斤#\n适量#\n适量#\n一小根#\n适量#','1. 把所有材料切碎，炒熟，待用。#\n2. 把炒好的馅洒满卷粉皮上，卷起来，就可以了。#\n3. 成品，吃的时候蒸一下，再放点油、酱油(这两种后放才好吃)，就可以吃了。#'),(620,'凉拌萝卜','素菜','白萝卜#\n红辣椒#\n盐#\n糖#\n醋#\n味精#','#\n#\n#\n#\n#\n#','1. 准备好食材#\n2. 白萝卜切片#\n3. 辣椒切圈#\n4. 先用盐腌20分钟，然后滤干水分。 再用糖腌30分钟，再滤干水。最后放醋和糖、味精，根据个人口味放。#\n5. 最后放入小辣椒圈，拌好，放入冰箱，晚饭的时候就可以吃了哦！酸甜可口哦！#'),(621,'麻辣土豆丝','素菜','土豆#\n花椒面#\n花生油#\n海椒面#\n孜然#\n小葱#\n盐#','1颗#\n半茶匙#\n适量#\n1瓷汤勺#\n1茶匙#\n2-3根#\n适量#','1. 土豆切丝，锅放油加热倒入土豆丝炒至透明，关小火加入调料拌匀，见油红了，开大火加入葱花拌匀，关火～起锅 简单又好吃^_^#'),(623,'辣椒炒鸡蛋','素菜','辣椒#\n鸡蛋#\n食用油#\n盐#\n葱#\n蒜#\n生抽#','300克#\n3个#\n#\n#\n#\n#\n#','1. 原料。#\n2.  尖椒洗净，去籽。#\n3. 切丝。#\n4.  炒锅倒油，放入蛋液炒成絮状后盛出。#\n5.  用余下的油炒香葱，蒜。#\n6.  放入尖椒丝，盐，生抽，煸炒。#\n7.  炒至尖椒软塌。 放入鸡蛋，少许白糖翻炒。#\n8.  翻炒均匀即可出锅。#'),(626,'大葱烧豆腐','荤菜','大葱 豆腐#\n盐适量。 酱油1勺#','2条。1块#\n#','1. 入锅。放油 下蒜蓉#\n2. 放入葱切成小段#\n3. 切片 放入豆腐#\n4. 不停翻炒放入白开水#\n5. 完成#'),(627,'大骨海带汤（加千张）','汤','大骨头#\n海带扣#\n千张#\n嫩姜#','500g#\n400g左右#\n250g左右#\n100g左右#','1. 嫩姜洗净切片#\n2. 大骨焯水备用#\n3. 海带扣洗净、千张切片备用#\n4. 姜片和排骨一起放入高压锅、加水适量、加料酒、适量盐、大火烧15分钟左右关火，水冲凉高压锅，再加入海带扣、千张片、大火烧开后转小火慢炖15分钟左右，加食盐调味即可。#\n5. 出锅撒葱花。#'),(628,'冬笋炒胡萝卜','素菜','冬笋#\n胡萝卜#\n食用油#\n生抽#\n盐#\n香油#\n葱#','#\n#\n#\n#\n#\n#\n#','1. 冬笋和胡萝卜切片；#\n2. 热锅冷油先下胡萝卜翻炒2分钟左右；#\n3. 下冬笋片继续翻炒1分钟左右；#\n4. 加一点生抽，再点水翻炒；#\n5. 加盐，勾芡，撒点葱，淋香油即可。#'),(630,'糖醋小排','荤菜','猪小排#\n油#\n盐#\n老抽#\n生抽#\n料酒#\n淀粉#\n醋#\n白糖#\n葱姜蒜#\n白芝麻#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 猪肋排洗净切小块。#\n2. 冷水入锅，锅内加葱姜蒜、料酒，水开后撇去浮沫，转小火煮10分钟，关火焖20分钟。#\n3.  取出小排沥干水分，入油锅大火（要保证外酥里嫩一定要用大火，避免油外溅，可盖上锅盖炸，中途改小火，开盖将小排翻面）炸至表面金黄捞出备用。#\n4.  取小碗，按老抽：生抽：醋：糖是0.5:1.5:2:4的比例调料汁。#\n5.  锅内留少许油，放入炸好的小排，倒入调好的料汁，中火快速炒制料汁完全吸附在小排上。#\n6.  加入少许湿淀粉，快速翻炒，随即淋入少许明油，起锅撒上白芝麻即可。#'),(631,'海带炖黄豆','素菜','黄豆芽#\n海带#\n瘦肉#\n植物油#\n盐#\n胡椒粉#\n糖#','250g#\n250g#\n30g#\n少量#\n适量#\n适量#\n适量#','1. 海带 豆芽洗好 瘦肉切细条#\n2. 热锅凉油 放肉 炒变色后 放入黄豆 炒两分钟 再放人海带 炒两分钟#\n3. 加水 水是菜量的2/3  加糖提鲜 炖到菜熟加盐  在炖一分钟 出锅  加入胡椒粉适量 拌匀#'),(632,'十分钟搞定麻辣土豆片，辣翻你。','素菜','红辣椒#\n盐#\n麻辣粉#\n鸡精#\n食用油#\n孜然#','2个#\n适量#\n3小勺#\n适量#\n2勺#\n1小勺#','1. 将土豆洗净。#\n2. 然后将土豆切片，再用清水淘两遍。#\n3. 将锅内的水烧开，然后把土豆片放入锅内，一分钟捞出。#\n4. 然后将食用油烧开，将干辣椒角放到锅内过滤一下。这时把盐，辣椒粉，适量孜然，鸡精放到土豆片上。用烧开的油泼到上边。完成。#\n5. 然后搅拌均匀，一盘麻辣土豆片就完成了。#'),(633,'白炖鲢鱼汤','汤','鲢鱼#\n盐葱蒜姜#\n料酒(最好是啤酒)#','一条#\n适量#\n适量(啤酒四分之一瓶)#','1. 鱼洗净，切成几段#\n2. 热锅，加少许色拉油#\n3. 放入葱姜蒜，煎几秒，放入鱼，稍微煎一下，加入适量的热开水，然后开始炖#\n4. 炖的时候，将出现的黄色的沫勺掉#\n5. 当鱼汤炖到差不多乳白色时，加入适量盐，根据个人爱好加入适量鸡精，然后出锅#\n6. 完成#'),(634,'泰酱脆皮虾','荤菜','虾#\n菠萝#\n青椒#\n红椒#\n泰式甜辣椒酱#\n蒜#\n姜#\n淀粉#\n砂糖#\n醋#\n水淀粉#\n盐#\n油#','250克#\n1/3个#\n1/3个#\n1/3个#\n4汤匙#\n1瓣#\n1片#\n5汤匙#\n少许#\n2汤匙#\n1汤匙#\n#\n#','1. 虾剪去虾枪虾须，从背上第二节挑去虾肠；#\n2. 沥去水分后加淀粉拌匀待用；#\n3. 菠萝去皮取肉切小块，可用盐水浸泡一下；青、红椒切小片；#\n4. 蒜、姜切末；#\n5. 把虾下油锅中炸至外皮酥脆；一只一只放进去以免粘一起~#\n6. 捞出控油；#\n7. 盐、糖、醋加2汤匙清水和1汤匙水淀粉调均匀；#\n8. 锅中加油烧热，放入蒜姜末爆出香味；#\n9. 加入泰式甜辣酱，倒入调好的糖醋汁烧开；#\n10. 加入虾、菠萝和青红椒炒匀就可以了~#'),(635,'浓香椰汁鸡','荤菜','鸡#\n椰浆#\n油#\n淀粉#\n盐#\n玉米#\n胡萝卜#\n熟木瓜#\n红枣#\n枸杞#\n白胡椒#\n八角#\n桂圆干#\n盐#','一只#\n100克#\n1小勺#\n1小勺#\n1/2小勺#\n一个#\n适量#\n一小个#\n6个#\n少许#\n少许#\n3朵#\n适量#\n适量#','1. 准备好一些蔬菜，木瓜是绝配、玉米带来香甜、胡萝卜带来营养，你还可以放点冬菇；鸡洗干净，清除内脏。#\n2. 切小块；用油、淀粉、盐腌制半小时左右。#\n3. 锅里放8碗水，把剩下的配料除了盐以外都加进去，沸腾了以后改为中火，慢慢煮至蔬菜都变软和出味；把鸡肉加进去，中火慢煮，鸡肉才会比较嫩，当鸡肉都熟透了，就加盐调味，即可关火。#\n4. 汤汁非常的香甜；鸡肉有浓香的椰浆味道，也非常的嫩滑；配菜非常的香~肚子开始咕噜噜的响了...#'),(636,'西红柿炒花菜','素菜','花菜#\n西红柿#\n木耳#\n青椒#\n红椒#','1个#\n3个#\n1把#\n1个#\n1个#','1. 花菜掰小朵，开水加一勺盐炖一分钟，捞起凉水过一遍，备用#\n2. 西红柿上划十字开水一分钟，去皮。#\n3. 切块备用#\n4. 热油，放入西红柿块，翻炒，加盐。至番茄微烂#\n5. 倒入花菜，青椒，红椒（可以不用辣椒）木耳，翻炒。淀粉冷水活开，倒入锅中，翻炒均匀。#\n6. 加鸡精，出锅#'),(637,'可乐鸡翅','荤菜','翅中#\n料酒#\n姜片#\n老抽#\n盐#\n可口可乐#','8个#\n1勺#\n适量#\n1勺#\n适量#\n一小瓶（500毫升）#','1. 把翅中洗净用刀在翅中的正面划2道，然后倒入料酒放入姜片腌制半小时。#\n2. 锅倒入油放火上，等油温微热时放入翅中，小火煎至两面金黄。#\n3. 倒入可乐，可乐要没过鸡翅。我是把一小瓶的可乐都倒里了。#\n4. 因为可乐较甜而且又不易上色，所以我又加了一些生抽和盐。#\n5. 大火烧开后调制小火慢慢熬制，直到汤汁变得粘稠了就大火收汁。#\n6. 装盘后就可以开动了。#'),(638,'双椒回锅肉','荤菜','五花肉#\n红彩椒#\n绿尖椒#\n豆瓣酱#\n生抽#\n白糖#\n姜#\n白酒#','200g#\n1个#\n3个#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 主要原料五花肉、青、红椒#\n2. 五花肉洗净冷水入锅，放入几片姜，倒入1匙白酒或料酒煮八分熟捞出晾凉#\n3. 利用煮肉时间将青红椒切小块备用#\n4. 肉切片（我这个好细一条肉，所以切厚了点）#\n5. 将肉码入锅，小火煸出油#\n6. 两面煸出油，煎出焦黄色（切得薄、肥肉少的省略煸油这一步，锅入少许油直接炒。）#\n7. 放入适量生抽翻炒均匀，再放入一勺郫县豆瓣酱翻炒，然后加入少许白糖翻炒提味，最后倒入青红椒炒制断生即可#\n8. 多诱人啊#\n9. 自然光下如此有诱惑力，我忍不住夹了#'),(639,'木耳荷兰豆','素菜','荷兰豆#\n木耳#\n蒜蓉#\n盐#\n鸡精#','500g#\n200g#\n适量#\n适量#\n少许#','1. 先把木耳泡发，荷兰豆摘好洗净、烧好开水把荷兰豆和木耳一起放入焯一会儿，荷兰豆变色后捞入冷水中浸泡、另起锅倒油烧热，放入蒜蓉炒香，倒入木耳荷兰豆，煸炒的同时放盐和鸡精调味后即可盛出享用啦#'),(641,'火爆猪肝','荤菜','猪肝#\n洋葱#\n辣椒#\n花椒#\n生姜#\n大蒜#\n淀粉#','200#\n1个#\n1个#\n10颗#\n1块#\n4瓣#\n适量#','1. 把洋葱和辣椒切好。#\n2. 猪肝加入盐、一点花椒粉辣椒粉、一点鸡精。加入淀粉、#\n3. 锅烧热、倒入油、然后放入切好的生姜大蒜、颗粒的花椒。爆炒至变色捞起。#\n4. 最后把切好的辣椒、洋葱炒、最后加入猪肝即可。#'),(642,'西红柿鸡蛋汤','汤','西红柿#\n鸡蛋#\n小葱#','1个#\n1个#\n少许#','1. 西红柿洗干净切小块，鸡蛋打匀#\n2. 少少油烧到热，锅擦干！#\n3. 西红柿下锅煸炒出汁，闻到焦糖味，加两碗水烧开。#\n4. 汤烧开，把鸡蛋轮进去，凝固后马上关火#\n5. 出锅加适量盐，撒一点小葱花#\n6. 没有小葱花香菜末也可以#'),(643,'好吃到哭的泡椒凤爪','荤菜','凤爪#\n泡椒#\n盐#\n糖#\n生抽#\n鸡精#','10个#\n50g#\n3勺#\n1小搓#\n一小勺#\n1勺#','1. 凤爪洗净，剪去指甲，对半切开，然后用冷水泡半个小时#\n2. 准备一锅脚爪放进去，水没过脚爪即可，然后倒入料酒，多放几块生姜，然后煮10分钟，放入冰水冷一下，然后再放入水龙头底下冲水，再次放入冰水中泡一下#\n3. 然后把凤爪捞出，放在一旁准备卤水，凉开水加入盐，鸡精，糖，生抽，泡椒调味，然后尝一下咸淡，把凤爪放进去，水要淹没凤爪，那样才入味#'),(644,'鲜鲍鱼鸡汤','汤','鲜鲍鱼仔#\n土鸡#\n姜#\n盐#','1000克#\n1只#\n几片#\n适量#','1. 新鲜鲍鱼仔用清水稍为清洗。#\n2. 用小刀从鲍鱼壳边缘插进去。#\n3. 把鲍鱼肉和壳分离出来。#\n4. 分离出来的鲍鱼肉。#\n5. 鲍鱼壳上留下的鲍鱼肠，把肠扔掉，将壳上的泥清洗干净。#\n6. 鲍鱼肉加少许盐揉抓，再用清水清洗干净沥干水。#\n7. 土鸡洗净。#\n8. 将鸡切成小块。#\n9. 锅内放适量的水，将鲍鱼仔、壳和鸡块和姜片一起放锅内，加适量的水。#\n10. 大火烧开（煮了一大锅，所以在院子里架了灶来烧，够农家味了吧？）#\n11. 转中小火煮60-90分钟，加盐调味即可。#'),(645,'紅燒脆皮豆腐','素菜','老豆腐#\n白糖#\n醬油#\n番茄醬#\n耗油#','2块#\n2勺#\n2勺#\n2勺#\n1勺#','1. 老豆腐切成塊，用紙吸除多餘水分#\n2. 所有調味品加在一起攪拌均勻做好調味汁#\n3. 豆腐下鍋煎成兩面金黃#\n4. 加入調味汁一起翻炒，註意別太用力，豆腐容易壞掉，湯汁收到差不多即可出鍋咯#\n5. 美美的紅燒糖醋豆腐來啦(☆_☆)#'),(646,'昂刺鱼汤','汤','昂刺鱼#\n香菜#\n葱#\n姜#','2条#\n#\n#\n#','1. 昂刺鱼洗净，姜葱香菜切片和段#\n2. 锅内准备清水，入一勺盐，烧开，将昂刺鱼在沸水中焯一下#\n3. 将焯好的昂刺鱼放入清水中洗净黄黑色的外皮，沥干水#\n4. 另起锅入少量油，放入葱姜爆香，将昂刺鱼倒入锅中正反面煸一下#\n5. 淋些料酒再继续煸一下#\n6. 锅内倒入足够量的热水，水量要漫过鱼身，大火煲20分钟#\n7. 汤变浓变白的时候，调入适量盐和胡椒粉，最后撒上些香菜就可以出锅了。#'),(647,'千页豆腐干锅鸡','荤菜','鸡肉#\n千页豆腐#\n青椒#\n洋葱#\n葱#\n姜#\n胡萝卜#\n黄豆芽#','半只#\n半包#\n适量#\n50g#\n适量#\n适量#\n适量#\n适量#','1. 鸡肉宰小块后用料酒盐和姜片腌制半小时。#\n2. 把配料切好，千页豆腐切小三角形片、姜蒜、洋葱切碎、青椒和胡萝卜切丝、葱切段备用#\n3. 先把腌制好的鸡块下油锅爆炒，把水分炒干盛出。#\n4. 千页豆腐用少许花生油煎炒黄。#\n5. 另放少许油，把姜蒜洋葱碎爆香，舀两勺豆瓣酱，再放青椒丝进行翻炒，把鸡肉块倒进去翻炒，小火焖煮十分钟后放入千页豆腐和胡萝卜丝再炒5分钟后撒入葱段即可起锅。#\n6. 另拿小锅，豆芽铺垫倒入炒好的鸡肉，撒上葱段装饰上桌，可小火加热先吃干锅菜，吃到后面还可以加汤煮蔬菜。#'),(648,'做法简单口味高端---美味鱿鱼丝','荤菜','鱿鱼#\n甜面酱#\n孜然粉#\n洋葱#\n料酒#','250g#\n适量#\n适量#\n250g#\n少许#','1. 鱿鱼切丝 洋葱切丝#\n2. 水烧开加少许料酒 鱿鱼丝抄水#\n3. 炒锅放油烧热 下入洋葱翻炒片刻 下鱿鱼丝#\n4. 加甜面酱和孜然粉翻炒均匀出锅#'),(649,'红烧肉末冬瓜|养老公不重样','荤菜','冬瓜#\n肥瘦猪肉#\n香菇#','#\n#\n#','1. 先炒肉末：香菇6个切丁，猪绞肉1斤#\n2. 热油加入猪肉和香菇，翻炒。调味：加盐1勺，黄酒3勺，酱油1勺。#\n3. 全部翻炒到熟透。#\n4. 另起一锅，热油炒冬瓜。#\n5. 炒到冬瓜半透明，再加半碗水，1勺酱油#\n6. 适量加入刚刚炒好的肉末。我加了4大勺。炖煮5分钟，收汁。#\n7. 入味的红烧冬瓜，肉末很下饭，好吃又健康。#'),(650,'香芹鸡肉','荤菜','鸡肉#\n香芹#\n红椒#\n青椒#\n姜片#','300g#\n50g#\n1条#\n1条#\n适量#','1. 鸡肉洗净#\n2. 把配料切好#\n3. 热油锅暴香姜蒜#\n4. 放鸡肉翻炒，小火慢煎#\n5. 煎至熟透加入生抽、料酒、配料翻炒一分钟即可#\n6. 成品#'),(651,'秘制酱牛肉','荤菜','牛腱子#\n大蒜#\n生姜#\n花椒#\n五香#\n干辣椒#\n葱段#\n冰糖#\n料酒#\n食盐#\n老抽#\n生抽#\n卤料包#','1000g#\n30g#\n40g#\n20g#\n5g#\n20g#\n30g#\n50g#\n250g#\n50g#\n10g#\n10g#\n1袋#','1. 牛肉先用冷水泡两小时，不断把血水清洗干净，再烧开水去浮沫#\n2. 备好材料#\n3. 另起一个锅放入冰糖煮化#\n4. 冰糖化后放入准备材料翻炒#\n5. 另起一个锅放入2000g清水，放入生姜煮开#\n6. 生姜水烧开后倒入翻炒好的材料#\n7. 放入牛肉#\n8. 放入料酒#\n9. 放入酱油#\n10. 放入食盐#\n11. 放入孜然粉#\n12. 放入白胡椒#\n13. 600度水炖90分钟#\n14. end#\n15. 秘制酱拼盘??#'),(653,'耗油炒菜心','素菜','瘦肉#\n菜心#\n大蒜#','随意#\n随意#\n两颗#','1. 瘦肉切片，加盐油腌制几分钟待用，蒜轻拍#\n2. 锅烧热下两勺油，下蒜瓣爆香放入肉片炒到有一点焦#\n3. 放进菜心炒到变色加一勺盐加一勺耗油#\n4. 翻炒均匀后装盘，ok，开吃。我做的不多所以盐跟蚝油放得少，想吃咸的也可以多放点蚝油#'),(654,'蜜汁叉烧','荤菜','里脊肉#\n叉烧酱#\n蜂蜜#','500g#\n适量#\n适量#','1. 用叉烧酱腌制一个晚上#\n2. 入烤箱，烤20分钟，取出翻面，刷蜂蜜，再烤15分钟#\n3. 成品#'),(655,'凉拌藕片','素菜','藕片#\n辣椒油#\n味精#\n蒜末#\n酱油#\n盐#\n糖醋#\n青红椒#','200克#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备洗好的藕片，买的是现成切好的。#\n2. 在开水中焯一下。#\n3. 放入青红椒，蒜末和盐，盐2分钟，容易入味。#\n4. 再放入酱油，糖醋。#\n5. 最后放入辣椒油，搅拌均匀即可。#\n6. 可以吃了。#'),(656,'可乐排骨','荤菜','可乐，排骨#\n生抽，料酒，葱姜蒜#','#\n#','1. 把排骨洗净，焯水#\n2. 煮沸#\n3. 洗净#\n4. 准备好辅料#\n5. 把排骨下锅煎至金黄#\n6. 加辅料炒一下#\n7. 加生抽，盐，可乐#\n8. 收汁#\n9. 出锅装盘，撒葱段，立马变得高大上，有木有#'),(657,'肉酿豆腐泡','荤菜','肉馅#\n豆腐泡#\n盐#\n蚝油#','#\n#\n#\n#','1. 首先根据自己的喜欢，和好肉馅！#\n2. 把豆腐泡中间扎眼，肉馅塞里面！#\n3. 平底锅倒少许油加热后把塞肉馅的一面朝下煎！煎至金黄换剩下的几面！捞出！#\n4. 蚝油生抽盐淀粉加水，倒入锅中炒成汁，加入煎好的豆腐泡！翻炒均匀即可出锅！#'),(658,'避风塘炒虾','荤菜','虾#','#','1. 姜葱切碎，加入盐，料酒，胡椒粉，腌制10分钟#\n2. 虾铺上淀粉入锅炸变色捞出#\n3. 再入锅炸，捞出，蒜爆香，加入面包糠，切忌油一定要少。不然面包糠会吸收#\n4. 出锅啦#'),(659,'豆腐海带烩#青春食堂#','素菜','豆腐#\n海带#\n青、红椒#\n橄榄油#\n酱油#\n淀粉#\n水或高汤#\n大蒜#\n盐#','约150g#\n1小张#\n各1个#\n适量#\n约20ml#\n约5g#\n125ml#\n3瓣#\n适量#','1. 泡发的海带先切成条，再如图切成三角形。放适量盐揉搓30秒，用清水洗净。这个方法洗的海带非常干净，煮或凉拌都不会有沫。#\n2. 辣椒去籽切片，大蒜切片。#\n3. 豆腐切成三角形。#\n4. 豆腐用油煎一下，两面金黄即可。#\n5. 热油锅，放蒜片煸香，再依次放青红椒，海带，翻炒1—2分钟再放入豆腐。#\n6. 放酱油翻炒均匀，再放水淀粉勾芡，少许盐，起锅。美味上桌。#'),(660,'咖喱蘑菇','素菜','红椒#\n咖喱酱#','#\n#','1. 红椒切块、大蒜切片，蘑菇洗净，做锅清水，水开后将蘑菇下锅，略微焯一下，也就是略煮1钟捞出控干待用。#\n2. 锅内放入少许橄榄油，放入红椒和蒜片煸炒出香味。#\n3. 放入咖喱酱，炒出香味和黄金色。#\n4. 放入蘑菇，继续翻翻炒炒。#\n5. 直至每个蘑菇包裹上咖喱，放上一小碗水大火烧开咖喱酱搅拌开，转小火，盖盖慢慢炖，直至蘑菇入味。#\n6. 炖的时候也可以放入小砂锅炖，吃的时候烧个小蜡烛烘烤着，更好，咖喱是越熬越浓，日子是越过越平静，岁月静好就在一钵一饭中。#'),(663,'海鲜面','主食','方便面#\n小乌贼#\n海裙子#\n小卷心菜#\n油#\n葱姜#','一包#\n七八只#\n一把#\n半个#\n少许#\n几片#','1. 先起锅把面煮一下，七八分熟即可。#\n2. 同时另起锅热油，葱姜爆香，放入小乌贼炒一下（乌贼我通常会先处理好，焯水后分袋放入冰箱冷冻，吃时提前拿出解冻即可），放入海裙子和切好的卷心菜继续翻炒，放入调料包拌匀。#\n3. 放入捞起的面继续炒匀即可。#'),(664,'橙香煎五花肉','荤菜','盐#\n生抽#\n橄榄油#\n植物油#\n蚝油#\n白糖#','半勺#\n1勺#\n1勺#\n适量#\n1勺#\n1勺#','1. 五花肉切薄片。#\n2. 橙子剥皮、切丝。（尽量不要剥到白色部分）#\n3. 把切好的五花肉放入一个容器中，挤橙子汁。#\n4. 再放入盐、白糖、生抽、蚝油、橄榄油搅拌均匀，腌制一小时以上。#\n5. 平底不粘锅中放适量植物油，放入腌制好的五花肉煎，中小火煎至两面金黄，肉变成透明状即可。#'),(666,'妈妈教的腌萝卜干','素菜','糖#\n香油#\n八角#','适量#\n适量#\n适量#','1. 把萝卜切成条用盐腌制一天，腌制过的盐水不要倒了#\n2. 腌制好的萝卜条放在竹扁上晒到有点收水#\n3. 再用原来的盐水腌制一天#\n4. 再晒到看起来像焉了那样不要太干留点水份#\n5. 然后用个大容器放适当点糖味精和香油八角拌一下拌好用容器装起来过三五天就可以吃了，时间越久越好吃#\n6. 刚刚拌好的萝卜干，有些图片忘了拍了，将就下看看#'),(667,'娘惹咖喱鸡','荤菜','鸡腿#\n洋葱#\n土豆#\n胡萝卜#\n姜#\n姜#\n柠檬汁#\n马来娘惹咖喱酱#\n椰浆#\n冰糖#\n高汤#\n盐#','2只#\n1个#\n2个#\n1个#\n5克#\n15克#\n15ML#\n30ML#\n200ML#\n10克#\n适量#\n适量#','1. 准备材料：鸡腿2只，洋葱切碎，土豆和胡萝卜削皮，切滚刀块，姜蓉剁碎成姜蓉末。#\n2. 鸡腿斩件，放入柠檬汁腌制一下。#\n3. 热锅放入橄榄油，爆香姜蒜末和洋葱粒。#\n4. 加入鸡腿块翻炒。#\n5. 加入马来娘惹咖喱酱炒香。#\n6. 加入胡萝卜和土豆块，翻炒均匀，倒入高汤，盖上盖子焖15分钟。#\n7. 最后加入椰浆和冰糖，煮至冰糖融化，根据口味下盐调味。#\n8. 盛碟上桌#\n9. 配上米饭。#'),(668,'自制虾滑','荤菜','鲜虾#\n竹笋#\n葱头#\n姜#\n料酒#\n盐#\n胡椒粉#\n肉末#','15个#\n一块#\n半根#\n1小块#\n1勺#\n半勺#\n适量#\n1小份#','1. 鲜虾去虾壳 虾头 虾线#\n2. 姜和笋尖切末#\n3. 肉末 虾末 姜末 葱末 笋末 盐 料酒 胡椒粉拌匀#\n4. 拌匀 摔打N次  具体多少次也没特意记  目的就是使虾肉更嫩#\n5. 锅里水烧开  撒入盐  用勺子挖虾肉入锅  煮熟即可#'),(670,'蒸鸡蛋','荤菜','土鸡蛋#\n腌鸭蛋#\n宣威火腿#\n香菇#\n葱#\n蒸鱼豉油的#','4个#\n1个#\n30g#\n4朵#\n20g#\n10ml#','1. 鸡蛋打散，放150ml 水和少量盐，静置20分钟，待泡沫消失，鸭蛋、火腿、葱、香菇切碎#\n2. 将鸭蛋碎粒调进鸡蛋液里，上笼蒸15分钟，水开关至中火蒸，鸡蛋表面不会起泡#\n3. 撒火腿粒#\n4. 撒入香菇丝#\n5. 再蒸5分钟取出，浇上豉油#\n6. 撒上葱花，出锅#'),(671,'炒焖子','素菜','焖子#\n麻酱#\n香菜#\n蒜#\n葱#\n盐#\n醋#','5元的#\n2勺#\n1根#\n3瓣#\n1根#\n少许#\n个人口味#','1. 蒜末#\n2. 葱末#\n3. 焖子切成小块，#\n4. 倒油，热油下过焖子，#\n5. 要放均匀，#\n6. 炒到金黄色，放葱和 蒜，看好火候出锅。#\n7. 搅拌麻酱，和出锅的焖子搅拌，#\n8. 成品，摆盘#'),(672,'凉拌萝卜皮——爽口开胃小凉菜','素菜','心里美#\n大蒜#\n干辣椒#\n花椒#\n醋#\n生抽#','1个#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 取一个心里美萝卜，洗净削成厚薄均匀的片，沥干水备用#\n2. 锅内放少许油，加几粒花椒、蒜末、干辣椒爆香#\n3. 最后加些醋、生抽，搅拌一下，就好了#'),(673,'狂补五脏的健康料理','不属于任何一类','牛蒡#\n胡萝卜#\n莲藕#\n白芝麻（熟）#\n酱油#\n砂糖#\n麻油#','1根#\n2根#\n500g#\n5g#\n60g#\n30g#\n3大勺#','1. 牛蒡与胡萝卜，大约切成3寸长，3分宽度，莲藕对切一半，切成3分厚度，牛蒡与莲藕浸泡水中洗一下（这2种食物容易颜色变黑）#\n2. 锅中放入芝麻油3大勺，干辣椒去籽剪成丝与胡萝卜牛蒡莲藕一起入锅中翻炒，#\n3. 牛蒡颜色有点透明度了，关火，把锅子放在冷毛巾上降温，并且放入酱油糖，翻拌。#\n4. 等全部上色拌匀了，开大火翻炒收干，#\n5. 放在盆中摊开冷却并撒上白芝麻即可#\n6. 一则健康料理就是这么形成的#'),(675,'葱姜炒螃蟹','荤菜','螃蟹#\n香葱#\n姜#\n尖椒#','4只#\n#\n#\n#','1. 螃蟹洗净，隔水蒸约三分钟#\n2. 香葱、姜、尖椒切好备用。螃蟹去壳、去腮后中间切开。#\n3. 油锅内放入配料爆香#\n4. 放入螃蟹翻炒片刻加入生抽炒匀#\n5. 出锅#'),(676,'黄豆炖双肘','荤菜','新鲜猪肘#\n咸猪肘#\n黄豆#\n八角#\n料酒#\n盐#\n白糖#\n蚝油#','500g#\n250g#\n200g#\n1颗#\n少许#\n少许#\n少许#\n少许#','1. 猪肘洗净冷水下锅#\n2. 水快煮干时关火捞去漂浮脏物#\n3. 温水洗净猪肘后加冷水入锅，（水宜没过食材稍多些）放入切好的咸猪肉和八角大火煮沸后转中火.#\n4. 中途加入料酒、盐（只需一点点就行，因为咸猪肉的咸味道会渗入黄豆和猪肘中）白糖，大约煮25分钟左右放入浸泡好的黄豆再中小火继续慢炖.#\n5. 大约1小时后等到汤汁浓稠变乳黄色，黄豆和肉肉已经酥软时加入蚝油稍煮一会即可起锅，装盘即可享用啦！美味呈现，真的好香啊！#'),(677,'自制清蒸罗非鱼','荤菜','罗非鱼#\n葱，姜，蒜，干辣椒，香菜，酱油，花生油，盐#','#\n#','1. 葱姜切丝，切短，备3份，蒜末一份#\n2. 把鱼收拾干净，用刀背均匀拍打鱼肉后花刀切开，并用一份葱姜丝放入料酒后，用盐涂抹到鱼身上后把葱姜蒜丝放入开刀口处腌制1小时以上（我中午腌制的晚上才做的）#\n3. 腌好后把葱姜丝去掉，用水冲洗干净，在放葱姜蒜丝滴上酱油（鱼鼓油）上锅蒸20分钟左右，关火去掉葱姜丝，继续放新的葱姜丝和蒜末（蒜末放鱼表面第一层，在放葱姜丝）放辣椒，盖锅盖闷会儿搞定#'),(678,'醋肉','荤菜','五花肉#\n白醋#\n白糖#\n盐#\n料酒#\n生抽#\n五香粉#\n生姜、蒜头#\n地瓜粉#\n生粉#\n鸡蛋#\n食用油#','500g#\n70g#\n30g#\n6g#\n适量#\n适量#\n适量#\n适量#\n180g#\n20g#\n1个#\n适量#','1. 准备一块五花瘦肉洗净切片#\n2. 生姜蒜头剁成蓉备用#\n3. 准备好腌制的材料，白醋、白砂糖、料酒、生抽、五香粉、生姜蒜头蓉。#\n4. 调好味的肉，盖上保鲜膜放冰箱腌制一至两小时，让肉入味。#\n5. 腌制好的肉取出加入一个蛋清搅拌均匀，再加入地瓜粉、生粉搅拌均匀，冷锅热油，待油温升高，筷子放进油里会冒泡就可以开始炸了。先开始大火炸会再调小火。#\n6. 直至醋肉表面呈金黄色即可关火，捞出沥干油装盘#'),(679,'时蔬沙拉（新手不简单版）生菜、鸡蛋、元葱','素菜','生菜#\n鸡蛋#\n甘蓝#\n紫元葱#\n胡萝卜#\n木耳#\n爱吃的菜#\n千岛酱或沙拉酱#\n黑胡椒酱#','一棵#\n两个#\n切点丝即可#\n一少半#\n一段#\n几个#\n若干#\n适量#\n适量#','1. 蛋煮熟，放冰箱一阵，黄不容易切散。#\n2. 各种菜放入，撒入千岛酱，黑胡椒酱。ok开吃。#'),(680,'萝卜菌菇煲 | 九阳知食','素菜','白萝卜#\n蟹味菇#\n火腿#\n枸杞#\n生姜#\n食盐#','120g#\n80g#\n50g#\n8-10粒#\n几片#\n适量#','1. 准备食材：蟹味菇、火腿、白萝卜、生姜、枸杞#\n2. 火腿切薄片#\n3. 白萝卜切丝#\n4. 所有食材加入电炖锅炖盅，注入清水，选择炖汤功能#\n5. 等待烹饪完成，让这碗汤温暖你的冬天吧#\n6. 扫描二维码，还有更多高颜值原创食谱等你哦~#'),(681,'蒜汁烧土豆块','素菜','小土豆#\n青椒#\n酱油#\n蜂蜜#\n料酒#\n蒜蓉#\n黑胡椒碎#\n香油#\n熟白芝麻#','5个#\n1个#\n4勺#\n1勺#\n1勺#\n1勺#\n适量#\n1/2勺#\n适量#','1. 土豆去皮洗净，切小块。青椒切块。#\n2. 锅里倒入酱油、料酒、蒜蓉烧开#\n3. 加入土豆块。轻轻晃动土豆。不粘锅就行了。#\n4. 土豆块都裹上酱汁#\n5. 加入1/2杯水。大火。#\n6. 土豆块变软的时候，放入蜂蜜、青椒。#\n7. 煮开后转小火，收汤汁快干的时候，加入黑胡椒碎、香油、白芝麻即可。#'),(682,'红烧排骨','荤菜','肋骨#\n八角#\n桂皮#\n姜#\n蒜#','500g#\n1个#\n3g#\n10g#\n10g#','1. 肋骨切条，过去血水#\n2. 锅里放少许油，把排骨炸至表面金黄，捞起待用#\n3. 重新起锅，少许油爆香姜蒜，然后倒入排骨，放一茶勺半的老抽上颜色，翻炒裹上色后，倒入一碗半的水，加入一勺半盐两勺红糖和八角桂皮和一茶勺料酒，盖上锅盖换中火熬煮。#\n4. 熬五分钟后可关火起锅，如果喜欢软一点的排骨就熬8分钟。#'),(683,'开胃凉拌菜','素菜','海带#\n炒花生#\n莲藕#\n芝麻#\n陈醋#\n辣椒#\n辣椒油#\n蒜#\n葱#\n橄榄油#\n白糖#\n盐#\n香菜#\n青瓜#','150g#\n3勺#\n1个#\n3勺#\n#\n1个#\n#\n5颗#\n3条#\n#\n1勺#\n#\n#\n1个#','1. 葱切粒，香菜切段，辣椒按个人口味爱下几个下几个。#\n2. 蒜头切碎#\n3. 莲藕切片煮四五分钟，过凉白开。海带丝同上。#\n4. 青瓜切小段#\n5. 热锅，略微炒一下芝麻，要小火。花生懒得炒，买现成的。#\n6. 香油一勺，辣椒油（自己喜欢），橄榄油两勺，陈醋两勺，白醋几滴，糖一勺，盐少许，酱油少许。#\n7. 全部都到碗里来，搅拌均匀，开吃。忍得住的就放冰箱冰个十几分钟。一次可以做多点，放两三天都没问题。问题是，更好吃，更入味。#'),(685,'毛豆烧鸡块','荤菜','毛豆米#\n鸡块#\n姜#\n蒜瓣#\n八角#\n红辣椒#\n酱油#\n料酒#\n盐#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 毛豆鸡块都洗干净。锅点火倒油，烧到七成热时放入姜片和拍好的蒜瓣、八角，干红辣椒爆一下，放入鸡肉煸炒。#\n2. 加入酱油，料酒，翻炒一下。#\n3. 加水没过鸡块，烧开后用小火炖10分钟这样。#\n4. 然后放入毛豆米，加些盐，大火烧开转小火。#\n5. 汤汁收的差不多的时候加点鸡精就可以出锅了。毛豆米最好多煮一会，不熟的话会有豆腥味。#'),(686,'三杯鸡','荤菜','童子鸡#\n生抽#\n老抽#\n葱姜蒜#\n干辣椒#\n九层塔#\n米酒或红酒或花雕#','#\n#\n#\n#\n#\n#\n#','1. 葱姜蒜，干辣椒，冰糖，大蒜要整颗不要切，姜片也切厚一些#\n2. 选用的是童子鸡，因为比较嫩，用生抽腌一下#\n3. 九层塔进口超市一般都有，照理米酒，没有的话就可以用红酒，花雕，啤酒可以哦#\n4. 葱姜蒜爆香#\n5. 把鸡找煸炒一下，喜欢吃干一些的可以先开水抄一下再煸炒#\n6. 红酒，生抽老抽，冰糖调成汁（甜咸根据自己口味调），倒进去，红酒偏甜冰糖可以少放一些，生抽老抽多放一些。#\n7. 等快收汁时候放入九层塔翻炒出锅即可#'),(687,'东北凉菜','素菜','蒜#\n辣椒油#\n盐#\n味精#\n糖#\n醋#\n香菜#','4瓣#\n#\n少许#\n少许#\n适量#\n适量#\n少许#','1. 将黄瓜香菜洗净之后 黄瓜切丝 香菜切段#\n2. 干豆腐切丝 和之前的香菜 黄瓜 放在一起#\n3. 将蒜拍成泥 连同其他材料一起放进刚才准备的黄瓜里 拌匀 就OK了 糖和醋可以不放 按照个人口味添加哦#\n4. 做好啦#'),(688,'花生猪蹄汤','汤','猪蹄#\n花生#\n干香菇#\n醋#\n盐#\n生姜#','一只#\n一小碗#\n三个#\n一小匙#\n适量#\n一小块#','1. 花生一碗洗净，香菇洗净。泡上一夜，泡发的水不要倒掉，用来煲汤。#\n2. 猪蹄一只，让店家砍小块，洗净。#\n3. 锅里加水，放入脚蹄，煮开后把脚蹄泡到冷水里，洗干净#\n4. 把所有材料放到锅里，加点醋。大火烧开后转小火煲到猪蹄软糯就可，放入盐调味。#\n5. 可以吃了#'),(689,'青菜丸子汤','汤','鸡胗丸、鱼丸（小小个的）#\n清菜苗#\n胡萝卜丝#\n姜#\n盐#\n鸡精#\n葱#','200g#\n5棵#\n适量#\n适量#\n适量#\n适量#\n1根#','1. 备料：鸡胗丸、鱼丸（小小个的）、菜苗、胡萝卜、葱、姜。#\n2. 葱白切块，姜切丝、胡萝卜切丝。#\n3. 适量的水烧开倒入葱白和丸子，再倒入少许橄榄油，盖上锅盖烧四五分钟。#\n4. 煮四五分钟的丸子熟后，接着放入青菜苗、胡萝卜丝、适量的盐，盖上锅盖把菜焖熟，加入鸡精调味即可！#'),(690,'凉拌海带丝','素菜','海带丝#\n姜#\n蒜瓣#\n辣椒#\n米醋#\n芝麻油#','200g#\n1个#\n2个#\n3个#\n20ml#\n5ml#','1. 海带丝切小断，放冷水里煮沸#\n2. 姜，蒜，辣椒切碎#\n3. 海带出锅，倒掉多余水份，趁热放盐，糖，味精#\n4. 最后倒入姜，蒜，辣椒，5ml左右芝麻油，几勺米醋，拌匀即可#'),(691,'啤酒鸡肉','荤菜','鸡肉#\n八角，姜，蒜，像树皮的那个，呵呵#\n料酒，葱，少量糖，盐，#\n啤酒#','#\n#\n#\n#','1. 主要的调料#\n2. 蒜啦#\n3. 料酒，葱腌制，最后把肥的分开，炒的时候先炒一会。#\n4. 先倒入适量的食用菜籽油，烧熟，把料爆香，先炒肥的，然后把瘦的倒进去，翻炒差不多熟的时候，放点糖，（喜欢吃甜的可以多放一点）倒入勇闯的啤酒（个人喜欢这个酒，比别的香甜一些）放入盐，慢慢炖，等到汁收的差不多就好啦。#'),(693,'独家葱爆羊肉','荤菜','冷鲜羊肉#\n香葱#\n姜#\n花椒#','300g#\n切段#\n切粒#\n适量#','1. 葱切段#\n2. 冷鲜羊肉切片加生粉少许盐拌均匀腌制5分钟#\n3. 姜粒、花椒烹出香味拨出扔掉#\n4. 放入羊肉调小火滑炒几下转大火爆炒#\n5. 放入葱段煸炒几下既可#'),(694,'红烧排骨土豆','荤菜','纤排#\n大料#\n葱#\n姜#\n蒜#\n白糖#\n土豆#','800g#\n10g#\n5g#\n10g#\n10g#\n20g#\n400g#','1. 先在水中加入生姜片煮排骨，除去腥味和血水，煮熟即可#\n2. 在锅里放油，加入白糖，翻炒至白糖变成红糖，加入煮好的排骨，翻炒至排骨金黄色。#\n3. 把排骨移动到锅的周围，加入姜，蒜，大料，翻炒至香味四溢。#\n4. 然后加入老抽调色，加入土豆开始翻炒。#\n5. 翻炒五分钟就加入水到锅中，慢慢煮。加入盐味精酱油调味！#\n6. 待锅里的汤汁粘稠起来，便可以起锅了，撒上葱花香菜即可！#'),(695,'伤心凉粉','主食','水淀粉#\n水#\n香菜#\n蒜泥#\n香油#\n花椒油#\n盐#\n鸡精#\n盐#\n醋#\n味极鲜#','50g#\n500g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n7适量#\n适量#\n适量#','1. 1将50克水淀粉放入100克水中，搅拌均匀，2再将400克水倒入锅中，水快开的时候，将刚才搅拌均匀的淀粉水倒入锅中，一直搅拌，直到锅中开始出现大气泡时，倒入已经准备好的器皿中。3放凉，放入冰箱，第二天拿出来切快，放入作料就可以吃了#'),(698,'可乐鸡翅','荤菜','鸡翅#\n可乐#\n葱姜#\n生抽#\n料酒#\n食盐#','#\n#\n#\n#\n#\n#','1. 热水里放葱姜，下鸡翅，大火五分钟，捞出#\n2. 改刀，更入味，用料酒，生抽腌制两小时#\n3. 油锅炸至金黄#\n4. 依次倒入可乐，生抽，食盐，也可以加点干辣椒#\n5. 小火炖十五分钟，大火收汁#'),(699,'鱼菲的快乐农场','不属于任何一类','鸡蛋#\n鹌鹑蛋#\n火腿肠#\n西兰花#\n青豆#\n胡萝卜#\n粟米#\n秀珍菇#\n早餐面包#\n海苔#\n土豆#\n银杏#\n章鱼须#\n盐#\n糖#\n酸奶#','2个#\n3个#\n1根#\n1棵#\n#\n#\n#\n少许#\n#\n少许#\n2个#\n2颗#\n1个#\n适量#\n适量#\n适量#','1. 1个鸡蛋打散，摊成蛋皮#\n2. 火腿肠对切，再从中间划开8条触角，小心不要切断#\n3. 除面包外，其他食材焯水烫熟，银杏微波炉中火加热外壳裂开即可#\n4. 土豆碾成泥，加入盐、糖拌匀，铺再盘子底部#\n5. 其他食材用小剪刀建成需要的造型，拼切起来即可，西兰花直接插在土豆泥中，为其他食材固定位置。#'),(700,'辣螃蟹','荤菜','缅甸蟹#\n青笋#\n魔芋#\n大葱#\n姜#\n大蒜#\n小米辣#\n泡椒#\n糟辣子#\n傣族香菜#\n花生油#\n花椒粉#\n鸡精#\n蚝油#\n十三香#\n海鲜酱油#\n老陈醋#','3只#\n1根#\n1块#\n1颗#\n1大块#\n若干#\n若干#\n3个#\n5勺#\n1把#\n100ml#\n1勺#\n1勺#\n2勺#\n1勺#\n2勺#\n1勺#','1. 螃蟹清洗干净并剪开，蟹钳用刀背拍下，以便入味。加入料酒和姜片腌制15分钟，去腥。#\n2. 准备佐料及配料，根据个人口味多少任意调整。#\n3. 开火，倒油，油热后放入腌制好的螃蟹，炒至变色后起锅，锅内留油。#\n4. 油锅内加入大葱、姜蒜、泡椒、糟辣子爆炒，出香味后加酱油、蚝油、老陈醋、十三香、花椒粉、魔芋翻炒。#\n5. 倒入螃蟹后加适量水翻炒几分钟。#\n6. 加青笋翻炒2分钟。#\n7. 加傣族香菜、鸡精，准备出锅。#\n8. 盛盘，香辣可口的辣螃蟹大功告成。#'),(701,'啤酒鸭','荤菜','无辜的鸭子#\n土豆#\n啤酒#\n青辣椒#\n葱姜蒜#\n花椒、朝天椒#\n和面#','半只#\n一个#\n两罐#\n各一个#\n若干#\n各一把#\n一团#','1. 热锅放油，把花椒炸透。我家爱吃麻辣的，就放了一小把。#\n2. 倒入鸭块，葱姜蒜，朝天椒。翻炒几分钟，倒酱油和啤酒，啤酒一定要够，           否则没有汤汁，皮带面就不好吃了#\n3. 加砂糖，盐，料酒，开始焖15分钟。因鸭子的老嫩程度，时间自由掌握。#\n4. 倒入土豆，继续小火煮到土豆熟为止。　　#\n5.  倒入青辣。起上色作用，辣味主要靠朝天椒。#\n6. 略微翻炒后，可以出锅了！装盘吧！#\n7.  把面煮好用凉水过一下，再用菜里的汤浇一下, 皮带面要越宽越薄越好吃。#'),(702,'含丰富维生素之---蒸咸鱼','荤菜','咸鱼#\n葱段#\n姜片#\n花雕酒#','一块#\n2寸断#\n6片#\n2汤匙#','1. 准备食材#\n2. 咸鱼放入温水中泡5-6小时（可根据咸淡程度，调整时间的长短），期间多次换水#\n3. 之后，在咸鱼中间，放入葱，姜#\n4. 及花雕酒#\n5. 花雕酒，尽量抹匀鱼身#\n6. 继续腌制20分钟，之后，开火#\n7. 继续蒸25分钟#\n8. 不烫手时，取出葱，姜#\n9. 成品图。#'),(703,'湘菜经典之辣椒炒肉','荤菜','前腿肉或有肥肉的里脊肉#\n青辣椒#\n生抽#\n老抽#','250g#\n200g#\n5g#\n2g#','1. 准备好所需要的食材#\n2. 肥肉切薄片待用，瘦肉切薄片加少许生抽腌制5分钟#\n3. 辣椒用刀背压瘪以后切成菱形#\n4. 把肥肉放入锅中，开小火煎出猪油#\n5. 猪油煎出后，将辣椒放入锅中翻炒，直到将辣椒炒软#\n6. 辣椒炒软，表面会有些起皮，这时将腌制好的瘦肉放入锅中翻炒，直到瘦肉炒熟，颜色变浅#\n7. 将瘦肉与辣椒进行不断翻炒，使其入味，如果粘锅可以放少许水闷制，使辣椒与肉的味道更进一步融合#\n8. 入味后加入老抽上色，加入适量盐味精调味，出锅。#'),(704,'韭菜炒土豆','素菜','土豆#\n韭菜#\n干辣椒#','1个#\n一小把#\n3个#','1. 韭菜切成1cm的段，干辣椒切成段#\n2. 土豆切成片，不要太厚，也不要太薄，适中就好#\n3. 油温烧至6~8成熟，下辣椒，下土豆，翻炒1分钟左右，(土豆炒至金黄色口味更好)加盐，翻炒均匀#\n4. 最后倒入韭菜，翻炒半分钟左右即可出锅#'),(705,'玉米排骨汤','汤','排骨#\n玉米#\n白萝卜#\n生姜#\n食醋#','#\n#\n#\n#\n#','1. 玉米洗净切段备用，生姜洗净拍松。#\n2. 白萝卜去皮洗净，然后切块。#\n3. 将排骨洗净砍成块，锅中放入适量的凉水倒入排骨加几片姜片。大火烧开后撇除浮沫，然后转小火烧20分钟这样。#\n4. 然后再倒入待用的萝卜和玉米块加入少许食醋，大火烧开后转小火烧30分钟。（在炖骨头汤时，加少许食醋，骨头汤中的钙质更容易溢出，有利于人体对钙的吸收和利用。）#\n5. 最后加适量的盐即可，一碗清香美味的玉米排骨汤就做好了，绝对适合食欲不振的你，在这样的天气去品尝！#'),(707,'土豆烧牛肉','荤菜','土豆#\n牛肉#','#\n#','1. 土豆削皮切块，放在锅里煮至九层熟捞出待用#\n2. 牛肉切条飞水后捞出切块，高压锅另起水放入大料八角，锅开后20分钟捞出待用#\n3. 锅油热下入姜蒜片炒香下入豆瓣炒10秒左右下入牛肉翻炒一会倒入开水或高汤烧开，尝尝牛肉是否熟了，这时倒入己煮至九层熟的土豆下锅一起盖盖焖至七八分钟，如锅中汤汁多的开大火收汁，不需要太干，起锅前尝尝土豆牛肉味道是否合适，加几滴香油，葱花起锅即可，土豆牛肉既要软糯而又不会烂掉，这样口感才更好#'),(709,'飘香卤鸡','荤菜','土鸡#\n冰糖#\n盐#\n料酒#\n生姜#\n红辣椒干#\n葱段#\n花椒#\n小茴香#\n草果#\n肉蔻#\n香叶#\n生抽#\n老抽#','1只#\n2两#\n#\n#\n1两#\n2个#\n3段#\n1撮#\n1撮#\n1个#\n1个#\n3片#\n#\n#','1. 整理宰好的鸡，把两只鸡爪盘到肚子里，鸡头压在翅膀后边，这样体积小便于在锅里翻动。用线绳稍加固定。#\n2. 把鸡放入锅里加凉水烧开，捞出漂洗干净#\n3. 炒糖色，冰糖放入锅里，加少许的油和水小火炒糖，当咖啡色的泡沫减少时关火并加适量的开水。#\n4. 把佐料用纱布包好。#\n5. 将锅里加入开水、糖色、料包、料酒、生抽、老抽、盐放入锅里调好味道，放入鸡小火炖到软烂，飘香卤鸡就做好了。#\n6. 开始享用吧！#'),(710,'巧煎培根-5分钟煎出完美外形','荤菜','生培根#\n水#','5条#\n没过培根表面即可#','1. 将培根摆在锅中加点水没过表面即可，然后开大火等它煮开后调到中火继续煎。#\n2. 两分钟过去了，可以看到经过水煮过的培根有规律的呈波浪形。#\n3. 继续煎下翻面，翻面的频率半分钟一次，只要达到双面微微金黄色即可。#\n4. 煎到最后的时候表面会有泡泡出现，这就是肥油煎出来以后产生的泡泡。#\n5. 此时可以关火了，将培根放入厨房纸巾中吸去多余的油份即可。#\n6. 随便搭配早餐都很好吃的。#'),(711,'西葫芦炒虾米皮','素菜','西葫芦#\n虾米皮#\n盐#\n白糖#\n食用油#','一个#\n适量#\n#\n#\n#','1. 西葫芦切片#\n2. 虾米皮泡水洗干净#\n3. 热油~七分热#\n4. 放葱花，蒜末，少量花椒爆香#\n5. 放入虾米皮炒十秒#\n6. 放入西葫芦~和虾米皮炒匀~#\n7. 加少量盐~糖~炒匀~出锅~我加了一点辣椒爆香~不喜欢辣的也可以忽略~#'),(713,'酸辣土豆丝','素菜','土豆#\n葱姜蒜#\n干红辣椒#\n醋#\n花生油#','一个#\n适量#\n一个#\n少许#\n少许#','1. 土豆切丝#\n2. 准备好葱姜蒜 干红辣椒一个 花椒适量#\n3. 炒锅放油，加花椒 葱姜蒜 辣椒炒香#\n4. 加土豆丝翻炒片刻 加醋适量翻炒，加盐ok#\n5. 出锅#'),(714,'黄瓜炒鸡蛋','素菜','黄瓜#\n鸡蛋#\n花生油#\n盐#','1个#\n5个#\n1勺#\n1勺#','1. 黄瓜切成片，鸡蛋打入黄瓜内，放入盐搅拌；#\n2. 锅内油烧热，放入黄瓜翻炒，鸡蛋熟了即可盛出。#'),(715,'油焖大虾','荤菜','阿根廷红虾#\n醋#\n白糖#\n料酒#\n生抽#\n葱#\n姜#','12只#\n2勺#\n1.5勺#\n1勺#\n2勺#\n适量#\n适量#','1. 红虾解冻要用冷水慢慢化开#\n2. 挑虾线从头与身子的接缝处用剪刀剪至尾巴，就很容易把虾线去除了#\n3. 去好虾线剪短虾须后用少许料酒腌30分钟左右#\n4. 将腌制的红虾沥干水份，锅内倒油煎炸红虾#\n5. 将红虾煎制焦黄为佳，盛盘备用#\n6. 油锅内放入姜片和葱段，然后放入大红虾翻炒一下加入提前调好的醋，生抽，白糖，料酒混合汁，并加入可以没过红虾的热水。再加入适量的盐，调制炖煮中火炖。#\n7. 炖至汤汁剩余1/3时，将红虾一个一个摆好在盘中，再调制高火把汤汁收浓稠浇在盛好的虾上即可#'),(716,'简易版蜜汁叉烧肉','荤菜','五花肉（较瘦）#\n葱姜蒜#\n蜂蜜#\n生抽#\n耗油#\n盐#\n白糖#\n老抽#','250g#\n适量#\n一茶匙#\n一茶匙#\n少许#\n少许#\n适量#\n很少一丢丢#','1. 把除了肉和蜂蜜之外的所有材料混合（腌料）。把肉放进去腌一个晚上。第二天放到烤架上烤一面15分钟，取出，刷上蜂蜜。反面再烤15分钟，取出在刷蜂蜜。晾十分钟切片装盘（肉块大的话适当多耍几次蜂蜜，延长时间）。#'),(717,'瘦肉炒三丝','荤菜','瘦肉#\n胡萝卜#\n大个土豆#\n黄瓜#\n淀粉#\n料酒#\n盐#\n生抽#\n味精#\n植物油#','适量#\n半根#\n半个#\n半根#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 胡萝卜去皮切丝，黄瓜切丝，土豆去皮切丝过两遍水，瘦肉切丝加料酒、盐、生抽和淀粉拌匀，腌10分钟。#\n2. 锅中油烧热放入肉丝，炒至变色加入胡萝卜丝翻炒至六成熟。#\n3. 再加入土豆丝翻炒2分钟。#\n4. 锅里放适量水，倒入黄瓜丝至水快干时加入盐和味精炒匀即可。#\n5. 成品。#'),(720,'素茄子','素菜','茄子#\n蒜头#\n食盐#\n蚝油#\n沙糖#','2条#\n5瓣#\n半匙#\n1匙#\n少许#','1. 茄子洗净切成5毫米左右的长条#\n2. 锅里多放点油烧热倒入茄条把茄条炸至绵软就出锅凉放一会去掉多余的油#\n3. 炸完茄子的锅留一点油爆香蒜头#\n4. 倒入炸好得茄条翻炒几下#\n5. 加入盐和糖多翻炒几下再放入蚝油至翻炒均匀#\n6. 均匀上色后就可出锅了#'),(721,'鱼香香菇','素菜','香菇#\n胡萝卜#\n柿子椒#\n葱姜蒜#\n生抽#\n耗油#','8个#\n半个#\n1个#\n少许#\n少许#\n少许#','1. 洗净食材 切丝#\n2. 倒入少许油 热锅 后倒入葱姜蒜#\n3. 炒出香味后 倒入胡萝卜#\n4. 翻炒到胡萝卜变色后倒入香菇和柿子椒丝#\n5. 翻炒几次后倒入生抽、放入少许盐#\n6. 点几滴耗油翻炒出锅#'),(722,'麻婆豆腐    好吃下饭','素菜','南豆腐#\n瘦肉#\n郫县豆瓣#\n生抽#\n老抽#\n辣椒油#\n水淀粉#\n花椒油或花椒粉#\n姜蒜#\n葱花#','1斤左右#\n1小块100克左右#\n1大匙#\n1汤匙#\n半汤匙#\n1大匙#\n半碗#\n适量#\n适量#\n适量#','1. 豆腐切大小合适的方块用网筛或网兜装起放开水中泡几分钟去豆腥味#\n2. 猪肉剁成肉泥，加适量生抽料酒和淀粉和少量盐抓匀腌一会（腌过的肉吃起来会比较嫩滑。）#\n3. 热锅凉油放入姜蒜爆香。#\n4. 加入肉糜炒至变色肉粒分开。#\n5. 加入郫县豆瓣和辣椒油炒出红油#\n6. 加入豆腐颠匀，分别调酱油和老抽。然后加入水淀粉煮开至粘稠。（水淀粉用小半碗水加入一汤匙淀粉调成）#\n7. 出锅前再撒入葱花。装盘淋上花椒油或撒上花椒面即可#'),(723,'凉拌鸡丝','荤菜','鸡丝#\n真菌菇#\n胡萝卜#\n黄瓜#\n调料：味极鲜、陈醋、糖、麻油、蒜末、剁椒#','半小碗#\n1把#\n1条#\n半根#\n适量#','1. 胡萝卜、黄瓜、真菌菇洗净切头备用。#\n2. 将胡萝卜、黄瓜切丝，老母鸡块撕成丝。#\n3. 将真菌菇、胡萝卜下水煮熟。#\n4. 将氽熟的真菌菇、胡萝卜捞出，和黄瓜、鸡丝拌在一起。#\n5. 制作调料：碗里放味极鲜、陈醋、蒜末、剁椒、白糖、麻油，搅拌下，淡就加点盐，放微波炉加热1分钟。#\n6. 调料倒在菜上，吃的时候拌开。#\n7. 剩下的一点黄瓜用上摆个盘，饭前图片，饭后光盘。#'),(724,'蛋黄娃娃菜','素菜','娃娃菜#\n鸭蛋黄#\n色拉油#\n大葱#\n盐#\n味极鲜#','一颗#\n2个#\n适量#\n适量#\n少许#\n少许#','1. 将娃娃菜拨去外面的叶子，洗净，一切四瓣备用。#\n2. 切好葱花备用。将煮熟的鸭蛋黄压碎备用，也不用很碎，炒的时候也会自动散开。#\n3. 冷水加入娃娃菜煮至水沸腾，捞出备用。#\n4. 锅中倒入色拉油，加入葱花炒香，倒入蛋黄，炒至蛋黄起泡炒散，放入娃娃菜，加入盐，味极鲜及少量的水，翻炒至入味盛出…#'),(725,'鱼香肉丝','荤菜','瘦肉#\n葱#\n辣椒#\n胡萝卜#\n冬笋#','250g#\n适量#\n1个#\n1颗#\n#','1. 将冬笋，胡萝卜，辣椒切丝，备用#\n2. 开水把蔬菜抄一下#\n3. 瘦肉切条#\n4. 放入料酒，淀粉腌制#\n5. 调鱼香汁，料酒：酱油：醋～1:3:2，再加入糖，盐，麻油，搅拌#\n6. 热锅，放油，葱花煸香，放入瘦肉，变白后，放入蔬菜，加入酱汁。#\n7. 加入郫县豆瓣酱，根据口味#\n8. 出锅#'),(726,'红枣枸杞竹丝鸡汤','汤','竹丝鸡#\n红枣#\n枸杞#\n姜#\n盐#','半只#\n15颗#\n半两#\n4片#\n半勺#','1. 抱歉~忘了拍照~只有成品图~#\n2. 1.用清水把竹丝鸡清洗一遍，然后用热水过一遍；2.把姜片和竹丝鸡一起放锅里煮；3.这个时候，可以清洗红枣枸杞，待水煮沸腾后（应该把锅里的竹丝鸡分泌出来的油去掉）放入锅里；4.可以调时间为半个小时…5.酌情放盐，有味道即可，个人可根据自身口味再加盐。#'),(727,'香菇盅','素菜','夹心肉糜#\n新鲜香菇#\n胡萝卜#\n食用油#\n榨菜丝#\n葱#\n盐#\n料酒#\n黑胡椒粉#','适量#\n9个#\n少量#\n适量#\n少量#\n少量#\n适量#\n适量#\n适量#','1. 香菇洗净，挖去中间蒂。#\n2. 剁肉糜，加入胡萝卜末榨菜末和葱花。加入料酒，盐，少量糖和油，黑胡椒粉，用筷子搅匀。#\n3. 把调好的肉糜放到香菇碗里。上锅蒸15分钟。#\n4. 出锅，开吃。鲜啊??#'),(728,'超麻口水鸡','荤菜','鸡#\n葱姜蒜#\n麻椒#\n干辣椒#\n辣椒油#\n花生#\n黑芝麻#','一只#\n#\n#\n#\n#\n#\n#','1. 鸡斩件，水烧开加姜煮15分钟#\n2. 冷水加冰块泡#\n3. 涳干水斩块大碗里摆好#\n4. 葱姜蒜跺碎，花生炒香捣碎，熟黑芝麻，干辣椒切小块，麻椒少许#\n5. 锅里辣椒油开火烧热#\n6. 用汤勺盛出少许热的辣椒油淋在葱姜蒜末上，加酱油+少许糖+少许精盐活均#\n7. 调好的酱汁均匀淋在鸡上面#\n8. 烧开的辣椒油关火后放入麻椒 ，爆香后捞出麻椒#\n9. 再开小火放入花生碎，黑芝麻，干辣椒，辣椒变色关火#\n10. 油淋在鸡块上就可以了，超级辣#'),(729,'木耳炒蛋','素菜','黑木耳#\n鸡蛋#\n葱#\n盐#','250g#\n4只#\n少许#\n少许#','1. 黑木耳事先泡发好，然后剪成小块，吃起来方便！#\n2. 鸡蛋打散打匀，加点盐#\n3. 锅加热倒油，放入木耳煸炒#\n4. 加入鸡蛋液，等鸡蛋结块了，然后翻炒#\n5. 鸡蛋成型后，加点盐和葱花，再翻炒几下出锅！#'),(730,'虾扯蛋','荤菜','虾#\n鹌鹑蛋#\n料酒#\n生抽#\n胡椒粉#\n红酒#\n油#\n盐#','12只#\n12个#\n2勺#\n1勺#\n适量#\n1勺#\n少许#\n少许#','1. 将虾剥皮留尾去黑线，加入料酒，生抽，胡椒粉，红酒，油，盐抓均匀腌制15-20分钟左右#\n2. 将模具中刷上油，放火上#\n3. 模具热后将虾放上，煎制变色#\n4. 然后磕上鹌鹑蛋，凝固后翻面煎一下即可#\n5. 煎好的虾扯蛋占番茄沙司或者其他喜欢的酱料均可#'),(731,'炒茭白','素菜','五花肉#\n茭白#\n白糖#\n盐#\n酱油#\n料酒#\n葱花#','一点点#\n五根#\n一点点#\n一点点#\n一点点#\n一点点#\n一点点#','1. 茭白当中对半开，然后斜切成片#\n2. 切肉#\n3. 全切好了。很甜~~#\n4. 肉放油锅里煸熟出油，肥肉稍微焦焦的。#\n5. 看！这样炒，肉会很香#\n6. 炒匀，放点酱油，然后白糖，盐，炒匀#\n7. 倒水进去，倒料酒进去。我的水放太多了，可以少放一点。#\n8. 熟了，放点葱花就行了。#\n9. 完成！#'),(733,'【乳香烤鸡翅】','荤菜','鸡中翅#\n南乳#\n南乳汁#\n蜂蜜#\n卤水汁（蚝油）#\n料酒#\n老抽#\n生姜片#\n蒜蓉#\n凉开水#','300g#\n适量#\n适量#\n适量#\n适量#\n适量#\n小量#\n适量#\n适量#\n小量#','1. 把鸡翅洗净滤干水份，鸡翅正面可画两刀，易入味！#\n2. 将南乳，练乳，料酒，卤水汁（蚝油），老抽，姜丝，蒜蓉混合在一起，试下酱汁，味道融合！偏咸一点点，乳香的味道很浓！各调味品的比例在小贴士里有写。#\n3. 这步没拍照。将鸡翅与腌料搅匀装入密封袋放入冰箱一天一夜。#\n4. 次日取出放在烤架上，取一点汁加入蜂蜜、凉开水调匀一会用，用180度上下火烤20分钟取出刷以上的汁水，翻面再进烤箱烤10分钟即可。#\n5. 成品图#\n6. 成品图#'),(735,'芹菜炒鸡块（凤凰于飞）','荤菜','素鸡#\n大葱#\n姜#\n白糖#\n食盐#\n干辣椒#\n酱油#\n芹菜#','一只#\n适量#\n适量#\n适量#\n适量#\n因口味定夺#\n适量#\n若干#','1. 鸡肉切块洗净，芹菜洗净切段，姜、葱切片，干辣椒剁开，备用#\n2. 热锅放入食用油，八成热放入鸡块翻炒，放入适量白糖，炒至鸡肉发干无水#\n3. 放入切好的葱姜辣椒，八角、花椒、酱油适量，翻炒3分钟左右，煸出香味#\n4. 加水漫沒鸡块为宜，放入食盐适量，盖上盖子炖十分钟左右#\n5. 待水炖干后（十分钟左右水份基本就没有了，锅底还会有油，如你不想炒芹菜，可以放入别的食材，比如青椒....）放入切好的芹菜翻炒，约莫3～5分钟即可出锅#\n6. 成品，色泽光鲜，食欲倍增#\n7. 顷刻光盘～额滴神啊～～#'),(737,'Sindy的私人厨房【香炸椒盐小黄鱼】','荤菜','黄鱼#\n盐#\n料酒#\n葱末#\n姜片#\n面粉#\n鸡蛋#\n椒盐#','若干个#\n适量#\n适量#\n适量#\n5片#\n适量#\n2只#\n少许#','1. 小黄鱼洗净，用盐，料酒，葱姜腌制半个小时以上入味去腥#\n2. 将鸡蛋打入碗中，搅拌均匀；将面粉倒入碗中备用#\n3. 将腌制好的小黄鱼，先裹上蛋液，再裹上面粉，入油锅炸至金黄色#\n4. 出锅#'),(738,'清炒苦瓜','素菜','苦瓜#\n生抽#\n陈醋#\n大葱#\n盐#','2个#\n#\n#\n#\n#','1. 苦瓜两个，洗干净。从中间破开一分为二，去掉瓤，斜切成片备用。#\n2. 葱斜切成段，备用#\n3. 热锅倒油，开始冒烟的时候下葱煸出香味下苦瓜翻炒，（如果喜欢口号软一点可以适当加一点锅边水）出锅前加盐即可。#'),(739,'香辣炸鸡块','荤菜','鸡腿肉#\n鸡蛋#\n面粉#\n生粉#\n黑胡椒#\n盐#\n辣椒粉#\n料酒#\n蒜泥#\n酱油#\n米酒/味淋#','2只#\n3只#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 鸡腿去骨，切成块（顺着骨头用小刀剔）#\n2. 两个鸡蛋加调料和鸡块拌匀，可少放一点糖调味，腌制一晚上#\n3. 面粉生粉3：1，少放些粟粉拌匀，炸的会更脆#\n4. 打一个鸡蛋，放少许辣椒粉，将腌好的几块挂上蛋液，再裹上拌好的面粉，入油锅炸#\n5. 炸好啦，第一次做，味道还不错，少裹点面粉应该更脆，喜欢香辣的朋友在腌制的时候可以多放辣椒和其他调料，盐适量即可，淡了可以蘸酱嘛(? ??_??)?#'),(740,'番茄烩金针菇','素菜','番茄(西红柿)#\n金针菇#\n盐#\n油#','两个#\n150g一200g#\n适量#\n#','1. 备齐食材，番茄两个，金针菇150g一200g#\n2. 番茄清水洗净，开水烫后，去皮#\n3. 切一厘米的小片#\n4. 金针菇切去头，先整的冲洗，拨散后再洗好后，拨散沥干水份#\n5. 热锅凉油，用中火煸炒片刻，加入少许盐再煸炒片刻#\n6. 加少许水焖煮10分钟番茄充分焖煮软烂  出汁#\n7. 再加适量水煮五分钟#\n8. 倒入金针菇，继续煮6分钟，再加适量盐调口味，收汁出锅即可  (喜欢甜口的可加少许糖，喜欢汤汁浓稠的可以多煮一会)汤汁拌米饭，拌面都多吃哦)，#'),(741,'红烧猪蹄','荤菜','猪蹄#\n姜#\n大蒜#\n八角#\n桂皮#\n香叶#\n花椒#\n冰糖#\n老抽#\n生抽#','500克#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 猪脚剁碎后洗净，放入高压锅，放姜片，八角，桂皮，香叶 ，定时15分钟#\n2. 从高压锅中捞出猪脚凉水冲洗后，锅中放油，加冰糖炒至冒泡。加猪脚翻炒，直至上色#\n3. 加老抽，生抽，料酒，姜片，醋，干辣椒壳子，香菇 ，适量盐，加入完全淹没猪脚#\n4. 中火慢炖，煮至水快干的时候，开盖，大火，调味，收汁。#'),(742,'泰式冬阴功','荤菜','冬阴功酱（家乐牌#\n虾，白贝，鱿鱼#\n蘑菇#\n盐#\n香茅，良姜，柠檬叶#','一小盒#\n1斤左右#\n适量#\n少许#\n适量（建议到淘宝上买整套的）#','1. 这是我这次用到的材料，其实除了配料外其他可以自己搭配。#\n2. 这是从淘宝搜到的，大概的底料。#\n3. 准备好材料，放适量的水，煮沸，放入香茅等干料煮2分钟，再放入酱料，盐，味道调到合适后煮3-5分钟。再依次入蘑菇、白贝、虾煮熟。#\n4. 上碟后少量香菜。#'),(744,'番茄烩豆腐','素菜','北豆腐#\n番茄#\n西芹少许#\n洋葱#','1块#\n1个#\n#\n半个#','1. 豆腐切粒用油煎至微黄，油温不可太低会巴锅。#\n2. 番茄去皮切丁，西芹洋葱切丁备用。#\n3. 油烧热煸香葱白与姜丝，入洋一葱西芹炒香后下一半番茄丁，放少许番茄沙司，入煎好的豆腐，下少许开水，与些许糖，盐，鸡粉调味，烧至稠时入另一半番茄丁，大火收汁。#\n4. 准备开吃。#'),(745,'超简单蔬菜浓汤','汤','土豆#\n西红柿#\n玉米粒#\n盐#','一颗拳头大小#\n一颗适中#\n根据喜好，不要太多#\n一调味勺#','1. 将土豆，西红柿切丁，备用#\n2. 将土豆丁，西红柿丁，玉米粒，盐一起加入豆浆机中，选择蔬菜浓汤模式，按启动键，然后就可以去玩耍了#\n3. 等机器提示完成后，倒出来就ok了，如果有芝士的话，味道会更棒的#'),(746,'清淡菜~黑木耳肉丸汤','汤','猪肉，水发黑木耳#\n葱，姜，盐，料酒#','适量#\n适量#','1. 肉切片（肥精分开）用绞肉机绞成肉酱，先绞肥肉，等肥肉绞碎，再放入瘦肉，加黄酒，生姜末，葱丁，盐一起搅拌。#\n2. 汤锅放水烧开后，用汤勺挖一团肉酱，用手搓圆后放入开水中。。。#\n3. 放好肉圆，加点料酒，葱段，姜片，盐。#\n4. 加入黑木耳。加盖中火煮出香味。#\n5. 上桌。（也可上桌前撒把大蒜叶）#'),(747,'卧鸡蛋','素菜','花椒粉#\n盐#\n豆油#','#\n#\n#','1. 将花椒粉，酱油，食用油，盐，放入盘中搅拌均匀#\n2. 将鸡蛋打入，上面铺上一层薄薄的盐，葱花，放入蒸锅中蒸15分钟即可。#'),(748,'青椒溜鱼片（教授鲜嫩滑溜鱼片秘诀）','荤菜','淀粉#\n黄酒#\n糖盐味精#\n葱#','适量#\n少许#\n适量#\n适量#','1. 青椒洗净、去籽、掰成大小均匀的片状#\n2. 鱼切片、洗净；加少量黄酒、盐、约两勺淀粉拌均匀，腌制片刻#\n3. 约一小碗油量（炸完鱼片后可乘出多余油），先大火热油再调小火（尽可能小），放鱼片翻炒几下，鱼肉一泛白就捞出（保持肉质鲜美）。#\n4. 热油，中火，煸炒青椒片刻。加一碗水，调味：加1勺盐，小半勺糖，适量味精（此基础上根据自己口味调整）。#\n5. 青椒、鱼片翻炒片刻后。勾薄芡，使汤汁粘稠。#\n6. 收汁，装盘，撒上葱花，即可。#'),(749,'土豆丝～春饼配菜','素菜','土豆#\n青椒#','#\n#','1. 土豆插成丝，过几遍清水，洗去淀粉。#\n2. 青椒切丝，备好蒜末。#\n3. 稍多油，入土豆丝炒炒，再加盐，青椒，蒜末。#\n4. 出锅前淋点白醋。#'),(750,'虾仁蒸蛋','荤菜','鸡蛋#\n小葱#\n青虾#\n凉白开#\n香油#\n生抽#\n盐#','2个#\n1根#\n6个#\n和鸡蛋差不多多#\n少量#\n少量#\n少量#','1. 所有材料，生抽忘记拍了#\n2. 鸡蛋加凉白开和少量盐，鸡蛋和水比例，一比一打散，过滤#\n3. 过滤好的蛋液#\n4. 青虾，去头去壳挑虾线，用盐料酒稍微腌制一会。#\n5. 取两个虾仁放进做好的蛋液里上开水锅蒸三分钟，小火#\n6. 三分钟后将剩下的虾仁放入去，继续蒸六到六分钟。即可出锅。#\n7. 放上小葱花，滴上几滴香油，少量生抽。就好啦！#\n8. 蒸出来木有一点点蜂窝，很滑嫩，好好吃！#'),(751,'白菜猪肉炖粉条','荤菜','大白菜#\n肉糜#\n粉条#\n葱姜蒜#\n生抽#\n红辣椒#','5大片#\n适量#\n一把#\n适量#\n2勺#\n5个#','1. 粉条用温水泡软；大白菜改刀。菜梗与菜叶分开改刀，分开翻炒，因为菜梗不容易煮烂。#\n2. 锅中加油，将葱姜蒜、红辣椒入锅炒香后，倒入肉糜煸炒，再放入菜梗翻炒。#\n3. 调入适量生抽继续炒至菜梗变软，加入少许开水炖煮，倒入泡软的粉条，加适量的盐，转中火炖制5分钟。新鲜白菜本身受热后会出水，所以水不要加太多。#\n4. 将剩余的菜叶放入锅中继续炖煮，炖至汤汁浓稠即可。出锅洒葱花香菜叶，ok啦#'),(753,'酱焖鸡中翅','荤菜','鸡中翅#\n西芹#\n红辣椒#\n生抽、耗油、海鲜酱#','10个#\n两瓣#\n两个#\n适量#','1. 鸡翅解冻洗净沥干水#\n2. 放适量的白酒（可以当料酒本人不习惯料酒的味道）生抽生姜腌制（不用放太多后面还要加）#\n3. 把配菜切好待用！#\n4. 把腌制好的鸡翅放锅中煎#\n5. 两面煎黄！#\n6. 倒入配菜翻炒几下！#\n7. 海鲜酱耗油各一匙羹兑半碗水倒到锅中，焖煮！#\n8. 感觉熟了收汁#\n9. 出锅！开吃！！！！！#'),(754,'无辣不欢《香辣煎牛仔骨》','荤菜','牛仔骨#\n干辣椒#\n蒜头#\n葱#\n盐#\n糖#\n黑胡椒粉#\n美极鲜酱油#','#\n#\n#\n#\n#\n#\n#\n#','1. 牛仔骨切块，撒盐和黑胡椒粉腌制。#\n2. 干辣椒，葱，蒜头切粒。#\n3. 锅里加少许油，将腌制好的牛仔骨煎到七分熟备用。#\n4. 锅里留少许油，倒入蒜头和葱花，干辣椒煸炒一下，倒入牛仔骨。#\n5. 加入一点的美极鲜酱油和少许糖调味，装盘。#'),(755,'鲫鱼炖茄子','荤菜','鲫鱼#\n茄子#\n青椒#\n葱姜蒜#','2条#\n2个#\n3个#\n少量#','1. 茄子切筒块，鲫鱼洗净，备好葱姜蒜#\n2. 煎茄子#\n3. 煎鱼#\n4. 煸香葱姜蒜，豆瓣酱～#\n5. 放鱼，料酒，酱油，醋，大火煮开，放茄子～大火煮开，小火煮十分钟#\n6. 撒上青椒，香菜之类的就可以出锅了#'),(756,'红烧鸡翅～超级下饭菜','荤菜','鸡翅中#\n葱姜#\n生抽#\n老抽#\n料酒#\n冰糖#','500g#\n#\n#\n#\n#\n#','1. 鸡翅先用凉水浸泡下去血水，最好是放冰箱保鲜里泡上半天～然后在鸡翅两面都划上两刀，方便入味。#\n2. 锅热后下底油，放姜片葱爆香。#\n3. 下去鸡翅煎，让鸡皮多的那面朝下，煎四五分钟翻个面再煎煎。#\n4. 烹入料酒，放生抽老抽，放几块冰糖，加小勺子盐，加入没过鸡翅的水，盖锅盖卤制。#\n5. 汁收干后盛出～～#'),(758,'黑白菜','素菜','白菜#\n黑木耳#\n葱白#\n猪五花#\n姜丝#\n海天酱油#\n食用油#\n白醋#\n鸡精#\n盐#','适量#\n适量#\n适量#\n适量#\n少许#\n少许#\n少许#\n一点#\n少许#\n少许#','1. 白菜洗净片刀切好备用，木耳热水泡发，葱 姜 切好备用#\n2. 油倒入锅内 待开 放肉 煸炒一会 倒入白醋 陆续放入葱姜 倒入酱油#\n3. 白菜 木耳 下锅 炒出香味放入鸡精即可 出锅#'),(759,'金玉满堂#沃康山茶油#','素菜','糯米圆子#\n青豆#\n玉米粒#\n沃康山茶油#\n糖#\n水淀粉#\n枸杞#','50克#\n30克#\n30克#\n1汤匙#\n20克#\n2汤匙#\n少许#','1. 原料。#\n2. 煮锅水开后放入糯米小圆子，轻轻搅拌，防止粘锅。#\n3. 煮至圆子浮起即可关火。#\n4. 糯米圆子捞入冷水。#\n5. 锅里放入青豆煮熟，捞出备用。#\n6. 炒锅倒少许沃康山茶油。#\n7. 放入青豆、玉米粒煸炒。#\n8. 加水、糖、糯米圆子。#\n9. 汤汁煮沸后淋入少许水淀粉。#\n10. 煮至汤汁浓稠后关火。#\n11. 放入枸杞，搅拌均匀。#\n12. 盛入盘中。#\n13. 成品。#\n14. 成品。#\n15. 成品。#'),(760,'虫草花蒸排骨','荤菜','排骨#\n虫草花#\n盐#\n酱油#\n食用油#\n鸡粉#\n生粉#','300克#\n80克#\n适量#\n1汤匙#\n少许#\n少许#\n少许#','1. 食材：排骨、干虫草花。#\n2. 排骨浸泡洗净，捞起沥干水。虫草花浸泡片刻、洗净沥干水。#\n3. 用一个较大的盆子盛起排骨，加上盐、鸡粉、生粉。（注：生粉即淀粉）#\n4. 倒进酱油、加上少许食用油，搅拌均匀。#\n5. 加上洗净的虫草花。#\n6. 用筷子搅拌均匀、腌制片刻。#\n7. 准备一个蒸碟，把拌匀的排骨装起。#\n8. 电饭锅煮饭时、用隔层放在电饭锅内蒸熟，饭煲好后排骨也熟了。（也可以用蒸锅隔水大火蒸20分钟）#\n9. 取出排骨，用汤匙拌匀汤汁即可。#\n10. 汤汁鲜甜，排骨鲜嫩。#'),(762,'干锅肥肠','荤菜','猪大肠（肥肠）#\n葱、姜蒜#\n青椒#\n干香菇#\n豆腐皮#\n洋葱#\n花椒#\n八角、桂皮#\n香菜#\n老干妈#\n味极鲜#\n橄榄油#\n火腿肠#','500g#\n#\n1个#\n8个#\n20g#\n1个#\n5g#\n#\n#\n2勺#\n2勺#\n1勺#\n2个#','1. 把肥肠焯水凉干#\n2. 洋葱切条，豆腐皮切丝，香菇切小块#\n3. 葱姜蒜切好，青椒切丝#\n4. 热油放花椒八角桂皮小茴香爆香，放葱姜蒜#\n5. 放香菇煸炒，放味极鲜调味，加少许水#\n6. 带香菇八成熟放肥肠大火炖，洋葱垫底，豆腐皮撒上带出锅#\n7. 出锅放点橄榄油#\n8. 撒青椒、火腿、香菜即可#'),(763,'美极杏鮑菇','素菜','杏鮑菇#\n美极鲜味汁#\n黑胡椒碎#\n蒜末#\n香葱末#\n盐#\n白糖#','#\n#\n#\n#\n#\n#\n#','1. 杏鮑菇洗净，切成长条。准备好蒜末与葱花。#\n2. 锅中烧热油，爆香蒜末葱花。#\n3. 放入杏鮑菇翻炒两分钟。#\n4. 加入美极鲜味汁，白糖，盐和黑胡椒碎继续翻炒一会儿即可出锅。#\n5. 完成。#'),(765,'毛豆炒肉','荤菜','毛豆#\n猪肉#\n青椒#','400克#\n200克#\n3个#','1. 毛豆、肉、青椒洗净切好，肉要用淀粉、酱油、料酒、盐腌一下，皮肉熬成油。#\n2. 锅里皮肉熬成了油，放瘦肉先炒，要吃辣椒的放辣椒油，然后放豆、青椒、盐、鸡精、味精就可以了#'),(766,'有机菜花炒肉','荤菜','五花肉#\n有机菜花#','200g#\n250g#','1. 锅热，加肉。炒#\n2. 肉炒熟。加有机菜花。翻炒#\n3. 加入提味味#\n4. 加入米醋少数。提高口感食欲。个人喜欢#\n5. 继续翻炒。浑匀调味料#\n6. 成品出锅了。#'),(767,'鱼香肉丝','荤菜','瘦猪肉#\n胡萝卜#\n莴苣#\n黑木耳#\n姜#\n大蒜#\n郫县豆瓣#\n酱油#\n醋#\n白糖#\n生粉#\n鸡蛋#\n剁椒#','300g#\n1块#\n1块#\n100g#\n1块#\n1个#\n2勺#\n1勺#\n2勺#\n1勺#\n2勺#\n1个#\n1勺#','1. 准备材料#\n2. 切丝#\n3. 码味：放入料酒、鸡蛋清、生粉、酱油，拌匀.#\n4. 热锅凉油，放入郫县豆瓣煸香#\n5. 放入生姜大蒜#\n6. 倒入肉丝炒制发白#\n7. 倒入配菜#\n8. 放入剁椒#\n9. 加入酱汁（1汤匙酱油+1汤匙白糖+2汤匙醋+1汤匙生粉）#\n10. 调味#\n11. 装盘撒上葱末#\n12. 飘香四溢！#'),(768,'五香酱牛肉','荤菜','牛腱子#\n花椒#\n大料#\n肉蔻#\n良姜#\n草果#\n桂皮#\n姜#\n大蒜#\n白芷#\n丁香#\n盐#\n黄豆酱#\n老抽#\n香叶#\n老冰糖#\n山楂干#','二斤左右#\n十粒#\n两个#\n一个#\n一个#\n一个#\n一块#\n五片#\n五瓣#\n两片#\n五粒#\n五盐勺#\n两勺#\n两勺#\n三片#\n一块#\n十片#','1. 香料家族准备。#\n2. 姜蒜准备，蒜用整瓣。#\n3. 腱子冷水下锅焯，水不要大开，撇去血沫，捞出牛肉，焯肉的水不要倒。#\n4. 炒锅烧一点热油，放入香料，姜蒜，出香味后放其他配料，把肉放进去，翻炒上色，倒入焯肉的水，小火炖一个小时四十分钟。#\n5. 关火，让肉在汤里泡几个小时后凉透捞出，切片摆盘。#'),(769,'油焖大虾','荤菜','对虾#\n番茄酱#\n白糖#\n盐#\n蒜未   姜未   葱花#','12只#\n适量#\n#\n少许#\n适量#','1. 把虾线和虾头的脏东西去掉 ，剪掉虾枪和须备用#\n2. 炒锅放适量的油   待油热把姜末蒜末放下去煸出香味后把虾放下去煎至两面变色  变硬#\n3. 再下番茄酱炒匀后下白糖和盐少许提味  最后撒上葱花即可#\n4. 美味的大虾就出炉了#'),(771,'芦笋炒蘑菇','素菜','芦笋#\n蘑菇#\n油#\n盐#\n红辣椒#\n鸡精#','250g#\n250g#\n适量#\n适量#\n1个#\n少许#','1. 芦笋洗干净，切去老根，我切去了三厘米左右，刨去皮。#\n2. 芦笋切成段，蘑菇切成片。蘑菇放在锅里才想起来照片忘拍了。#\n3. 油锅烧热，下芦笋大火翻炒下。#\n4. 放洗干净切好片的蘑菇继续翻炒。#\n5. 放红辣椒，加盐与鸡精快速翻炒几下出锅。#\n6. 装盘。#'),(772,'茄汁年糕','素菜','年糕#\n盐#\n油#\n番茄酱#\n水#','250克#\n少许#\n少许#\n适量#\n少许#','1. 年糕洗净#\n2. 起油锅加热,放入年糕煸炒#\n3. 放少许水煮开#\n4. 放少许盐煸炒#\n5. 倒入番茄酱#\n6. 拌炒均匀即可#'),(773,'芹菜炒牛肉','荤菜','牛肉#\n芹菜#\n胡萝卜#\n盐#\n味精#\n鸡精#\n淀粉#\n葱#\n姜#\n大蒜#\n植物油#','300g#\n200g#\n1根#\n1勺#\n1勺#\n1勺#\n10克#\n1根#\n1块#\n3瓣#\n50g#','1. 牛肉切片，芹菜切菱形段，胡萝卜切菱形片，将炒锅倒入植物油加热后葱姜蒜爆锅，放入牛肉煸炒，牛肉炒到发白时加入芹菜，胡萝卜继续炒，加入盐，味精，鸡精然后勾芡#'),(775,'黄瓜皮蛋','素菜','黄瓜#\n皮蛋#\n蒜#\n糖#\n老干妈油辣椒#\n酱油#\n醋#\n盐#\n小葱#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 黄瓜切块用盐腌上   皮蛋切丁   蒜拍碎剁蓉  葱切小段#\n2. 碗中倒入酱油、老干妈油辣椒、糖、醋再倒入蒜蓉搅匀#\n3. 将黄瓜皮蛋拌一块  淋上调好的酱汁  撒上葱花即可#'),(776,'美味鸽子炖汤','汤','鸽子#\n瘦肉#\n生姜片#\n淮山#\n太子参#\n麦冬#\n枸杞#\n红枣#\n蜜枣#\n茨实#\n盐#','1个#\n1小块#\n3片#\n3片#\n7-8条#\n8-9条#\n适量#\n1个#\n2个#\n适量#\n少许#','1. 鸽子和猪肉洗净。#\n2. 准备各种汤料后洗净#\n3. 生姜片，鸽子和猪肉，各种汤料一起放入炖盅倒满水。#\n4. 给汤煲自动定时炖汤功能。炖好后放点盐#'),(777,'家常菜之素炒三丝','素菜','干黄花菜#\n红萝卜#\n青椒#\n油#\n盐#','1小把#\n1根#\n2个#\n适量#\n4g#','1. 准备好所有的食材#\n2. 黄花菜提前用温水泡15分钟左右，泡发好的黄花菜沥干水份切段#\n3. 红萝卜、青椒清洗干净并切丝#\n4. 锅中加适量油，倒入红萝卜丝翻炒几下#\n5. 然后加入青椒丝、黄花菜、盐，中火快速翻炒30秒左右，等盐入味后即可出锅#'),(778,'凉拌西兰花黑木耳','素菜','西兰花#\n干黑木耳#\n大蒜#','1棵#\n少许#\n3瓣#','1. 西兰花切小朵用盐水泡一下，干黑木耳放水泡开，#\n2. 锅里放少许水烧开放西兰花煮至断生捞起用凉水冲一下，装盘，黑木耳也放下煮一下捞起冲水，放在西兰花上面，#\n3. 调汁，用一小碗装半碗水，蒜剁成蒜蓉，放在碗里，放少许酱油，蚝油，鸡粉，醋，淀粉，好，锅烧热放少许花生油烧热，倒汁烧开，浇在黑木耳西兰花上，淋上香油，OK，开吃，#\n4. 成品，#'),(779,'蜜汁鸡翅','荤菜','鸡翅#\n奥尔良烤翅料#\n蜂蜜#\n水#','250g#\n35g#\n适量#\n35g#','1. 把奥尔良烤翅料和水混合#\n2. 放入鸡翅涂抹均匀，放入冰箱冷藏8—10个小时#\n3. 放入烤箱中，上下火180度，烤15分钟#\n4. 将剩下的料汁加入适量蜂蜜，涂抹在鸡翅上，再烤20分钟，香喷喷的烤翅就出锅了，老少咸宜，健康卫生～#'),(781,'橄露Gallo经典特级初榨橄榄油试用之【培根干锅花菜】','荤菜','有机花菜#\n荷美尔炒菜培根#\n红椒#\n橄露Gallo经典特级初榨橄榄油#','半个#\n200克#\n半个#\n适量#','1. 准备好原料，花菜用盐水浸泡后撕小朵。#\n2. 锅里烧开水，放适量的盐和橄露橄榄油。#\n3. 放花菜焯水2分钟后沥出。#\n4. 培根切片。#\n5. 红椒切小块，准备大蒜切片，葱切断，花椒粒备用。#\n6. 锅里放适量橄榄油。#\n7. 放入培根。#\n8. 煎至两面黄。#\n9. 把培根挪至一边，放红椒和大蒜煸香。#\n10. 放入花菜。#\n11. 调盐、生抽翻炒，翻炒至花菜水分减少，调鸡精，撒葱段起锅。#\n12. 可以享用啦！#'),(783,'快手菜—家常呛黄瓜','素菜','黄瓜#\n蒜#\n辣椒#','一根#\n两瓣#\n适量#','1. 拍黄瓜，斜着切条条。放点儿盐，提前入味儿。#\n2. 加入蒜末。起油锅，加入麻椒或者花椒和干辣椒圈，熬出香味儿淋在蒜末黄瓜上。加点鸡精，香油，醋。拌匀即可。#\n3. 可以吃啦！#'),(784,'五花肉炒菜花','荤菜','葱#\n大蒜#\n料酒#\n黑胡椒粉#','适量#\n适量#\n适量#\n适量#','1. 五花肉切片，加入料酒和黑胡椒粉拌匀腌制待用。#\n2. 菜花掰开，大小自定，开水锅里走一下，变翠绿色后，捞出，待用。#\n3. 葱花、大蒜切片，待用。#\n4. 热锅倒油，加入葱花大蒜，稍出香味加入五花肉翻炒，加入适量酱油给肉调色，再加入菜花，翻炒片刻，出锅。#'),(785,'茄汁煎豆腐','素菜','番茄#\n豆腐#\n豆油#\n孜然#\n胡椒#\n糖#\n淀粉#\n盐#','中等大小一只#\n三块#\n#\n根据个人口味#\n少量#\n15g#\n5g#\n2g#','1. 豆腐切成0.5厘米厚的薄片。#\n2. 番茄，开水烫后去皮，放入锅中捣烂，加入黑胡椒，糖，盐，淀粉。熬成粘稠的酱。#\n3. 锅中放油，待油沸腾后，将豆腐片，依次放入锅中炸至金黄。#\n4. 将炸好的豆腐片，在盘子中叠放好，浸上制好的酱。可以撒一些葱花。#'),(786,'家庭版干锅香辣虾（超过很多酒店的味道）','荤菜','葱白#\n鲜姜#\n蒜片#\n干辣椒段#\n花椒#\n郫县豆瓣酱#\n酱油#\n油#\n鲜虾#\n芹菜，黄瓜，莲菜#','一根#\n少许#\n少许#\n适量#\n少许#\n一大勺#\n少量#\n300g#\n600g#\n各适量#','1. 切好葱姜蒜。辣椒段。花椒。#\n2. 去除虾线，控干水份。（小提示:着急做的话，可以用吹风机吹吹）#\n3. 油炸虾。分两次:第一次，油温五成时放虾，炸至金黄卷曲出锅；第二次，在油温加热到八九成时再将虾倒入锅煎炸20秒左右出锅。这样虾皮比较脆，并且虾肉很鲜嫩。#\n4. 莲菜，黄瓜入锅油炸一分钟。出锅。#\n5. 烧油，爆香葱姜蒜，豆瓣酱。加入虾后再加少许酱油，最后放入芹菜翻炒。可以出锅。（我的照片直接在锅里照的，光线暗，不是很美观#'),(787,'小熊家鸭血汤','汤','鸭血#\n蛋#\n葱#','250g#\n2个#\n5g#','1. 鸭血一盒，葱，蛋#\n2. 放点油，放葱，加入水，煮开，放入血块。#\n3. 蛋液在小锅里煎出蛋皮#\n4. 蛋皮切丝#\n5. 放入滚了的汤里，放些盐。#\n6. 没错！就好了！#'),(789,'家常干锅花菜','素菜','花菜#\n五花肉#\n葱花#\n姜丝#\n酱油#\n盐#\n辣酱#\n八角#','400g#\n100g#\n少许#\n少许#\n5勺#\n适量#\n1勺#\n少许#','1. 花菜手撕成小块冲洗干净，五花肉切薄片#\n2. 锅中热油放入两瓣八角煸炒出香味儿#\n3. 放入肉片翻炒至颜色变白#\n4. 肉片变白时倒入葱花姜丝翻炒#\n5. 加入3勺酱油，1勺辣酱#\n6. 加入花菜翻炒片刻，再加入2勺酱油让花菜也入入味儿，加少许热水，盖上锅盖中火焖2分钟，加入少许盐调味儿，翻炒1分钟即可出锅#\n7. 开动吧~#'),(791,'小妹家常菜之十六：凉拌牛肉','荤菜','熟卤牛肉#\n盐#\n新鲜指天椒#\n陈醋#\n酱油，白糖#\n芫茜#\n凉开水#','250g#\n适量#\n5根#\n适量#\n适量#\n适量#\n适量#','1. 先将牛肉切片#\n2. 将所有配料调到合自己的口味后淋在熟牛肉上，拌均，搞定。这次忘下香油了#'),(792,'西红柿疙瘩汤','汤','西红柿#\n鸡蛋#\n面粉#\n番茄酱#\n葱姜#\n盐#\n糖#\n小葱#\n香菜#','3个#\n2个#\n200克#\n35克#\n少许（切末）#\n少许#\n2大勺#\n适量#\n适量#','1. 面粉中缓慢加入50克温开水，用筷子搅拌，形成小面片#\n2. 锅内放底油加热，放入葱姜末炝锅，后放入西红柿、番茄酱翻炒#\n3. 加入盐和糖继续翻炒至汤汁红亮，下入水开的另一汤锅中#\n4. 接着下入面疙瘩，同时中小火不停的用汤勺搅动，防止面疙瘩结成大块，如形成了大块，用汤勺捻开#\n5. 盖盖焖煮3－5分钟，煮到粘稠适中开盖加盐少许，转圈倒入搅拌好的鸡蛋，搅动一下，关火，淋上几滴香油#\n6. 吃时撒上一些香菜和小葱#'),(793,'微波松仁玉米#食尚争霸 格兰仕微波炉试用#','素菜','什锦蔬菜#\n去皮松子#','250g#\n1把#','1. 食材准备，什锦蔬菜洗净控干，如果是买的速冻品就要化冻后清洗干净再用；去皮松子一把，橄榄油，盐，糖和黑胡椒粉准备好。香葱忽略掉，本来想放的，后来觉得葱味太浓不想吃，只好弃之。#\n2. 松子盖上保鲜膜，扎几个洞放进微波炉。#\n3. 变频微波叮个一分钟，叮到一半才想起拍照。#\n4. 1分钟后取出松子，去掉保鲜膜晾置一边。#\n5. 玉米撒盐和糖，倒1勺橄榄油，撒适量黑胡椒粉，用勺子拌匀，盖上保鲜膜放进微波炉，保鲜膜上要扎几个洞哦。#\n6. 高火变频3分钟。#\n7. 熟啦！超级easy！#'),(794,'川味干煸鸡丁','荤菜','鸡腿肉#','适量#','1. 1、买回来的大鸡腿切块，比宫保鸡丁的那个鸡丁大些；2、用平常简单的佐料把鸡丁腌制一会，顺便就可以准备配料，3、炒锅烧热，放适量的油，因为鸡肉本身也会有油和水分，适当的放些油就行，把大蒜,生姜，辣椒段，花椒，全部放入爆香，倒入鸡丁，一直翻炒，直到鸡丁外表看起来有点焦的感觉就好，不用鸡肉会老，#'),(795,'红椒炒毛豆肉丝','荤菜','红椒#\n青椒#\n毛豆#\n肉丝#\n油#\n盐#\n生姜#','一个#\n一个#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 这道菜首先需要用酱油酱一下肉，这样才会吃起来嫩，大概五分钟顶多，待油锅热后，炸生姜，出香味后，炒肉丝，熟后盛出，放毛豆，毛豆需要多炒会才不会有豆腥气，再放肉丝，红椒，待红椒稍微有点瘫就可以盛了#'),(796,'鱼香肉丝','荤菜','笋子#\n干木耳#\n盐#\n淀粉#\n酱油#\n砂糖#\n醋#\n水#\n蒜#\n姜#\n葱#\n料酒#\n油#\n郫县豆瓣酱#','1根#\n4朵#\n1勺#\n1勺#\n3勺#\n4勺#\n4勺#\n5勺#\n大半个#\n1块#\n两根#\n适量#\n适量#\n2勺#','1. 猪里脊肉切丝，用冷水浸泡直至泡出血水，同时黑木耳温水泡发。#\n2. 肉丝加入料酒、淀粉、盐、少量植物油腌制半小时。#\n3. 胡萝卜、笋子、黑木耳切丝待用。#\n4. 调配鱼香汁：姜葱蒜切末，加入1勺盐、1勺淀粉、3勺酱油、4勺砂糖、4勺醋、5勺水调匀。#\n5. 热锅热油倒入肉丝大火炒至肉丝变白。#\n6. 转中火加入郫县豆瓣酱炒出红油。#\n7. 倒入胡萝卜、笋子、黑木耳丝大火翻炒至熟。#\n8. 倒入调配好的鱼香汁，约一分钟翻炒均匀即可出锅。#\n9. 成品图#\n10. 成品图#\n11. 成品图#'),(797,'董小姐香菇鹌鹑蛋','荤菜','新鲜香菇#\n鹌鹑蛋#\n盐#\n蚝油#\n葱花#\n麻油#\n虾仁#\n料酒#','7枚#\n7个#\n少量#\n少量#\n少量#\n少量#\n4枚#\n少量#','1. 香菇要尽量挑选伞帽圆整的，凹面大的；洗净后盐水浸泡半小时左右，用以增加香菇的咸度。#\n2. 去掉伞柄，不要戳破。#\n3. 虾仁洗净切丁，一点点料酒填入伞帽里。#\n4. 依次打入鹌鹑蛋，加点蚝油，隔水蒸20分钟即可。#'),(798,'红烧龙头鱼','荤菜','大葱#\n姜#\n大蒜#','#\n#\n#','1. 把龙头鱼清理干净，剪断#\n2. 葱姜蒜，切好备用#\n3. 锅里放油#\n4. 先放姜再放蒜葱#\n5. 等有香味了，再放入鱼#\n6. 放入料酒，酱油，干辣椒和适量水，大火烧开，放入盐转小火#\n7. 水差不多了，可放点醋（醋早了会没味道），转大火收汁，放葱叶和味精，就好了#\n8. 装盘，谢谢大家支持#'),(799,'香辣油爆明虾','荤菜','明虾#\n盐#\n面粉#\n鲜酱油#\n料酒#\n泡椒#\n姜蒜末#','800g#\n3勺#\n两大勺#\n一勺#\n一勺#\n50g#\n50g#','1. 把洗好的明虾剪去虾嘴，剪开虾背，把筋挑掉，加盐和料酒腌制。#\n2. 虾稍微腌制15分钟，放到面粉里裹一下，让双面都均匀沾上面粉。#\n3. 下油锅炸，炸虾要香脆就需要油多一些，用中小火避免炸焦，等虾两面金黄看着很酥脆，就可以捞起来。#\n4. 炸好的虾！#\n5. 最后一步完全看各家口味，主要是下调料回锅爆炒，可以做椒盐、香辣、蚝油闷等等，都非常好吃。基本料就是蒜姜末、洋葱末，然后看口味再加椒盐、辣椒或者其他调料。炒完出锅，非常香脆，外脆里嫩！哈哈～#'),(800,'可乐小鸡腿','荤菜','小鸡腿#\n可乐#\n盐#\n白糖#\n酱油#\n姜片 葱片#','500g#\n适量#\n少许#\n少许#\n少许#\n少许#','1. 小鸡腿已经用水煮沸 捞出沥干  待用#\n2. 锅烧干   倒少许油   油开后   将葱丝姜片放入锅中炒香后捞出    留下带有葱姜香味的油待用#\n3. 先将火关掉   再往锅中倒两匙糖  待糖融化病变成金黄色   开小火   倒入小鸡腿翻炒   同时调成中火#\n4. 待鸡腿炒至金黄色   倒入可乐至刚好淹没鸡翅#\n5. 放入适量盐   鸡精    酱油（可调菜色）    待汤汁浓缩即可出锅#'),(801,'豆腐双菇羹','素菜','嫩豆腐#\n蘑菇#\n平菇#\n鸡蛋#\n蒜片#\n姜末#\n葱末#\n白胡椒粉#\n盐#\n猪油#\n鸡精#\n豌豆淀粉水#','150g#\n150g#\n150g#\n1个#\n一瓣切片#\n少许#\n适量#\n少许#\n适量#\n适量#\n适量#\n适量#','1. 嫩豆腐切碎粒#\n2. 菇菇一样切碎粒#\n3. 葱姜切末#\n4. 锅里加清水、姜末、猪油、胡椒粉、盐，等待煮沸#\n5. 啦啦啦～#\n6. 嫩豆腐和菇菇一起下锅#\n7. 把准备好的蛋液慢慢的倒入锅中#\n8. 一定要一只手慢慢倒入蛋液另一只手顺时针搅拌哦！#\n9. 然后把准备好的豌豆淀粉倒入锅中（一样也需要搅拌哦）#\n10. 加入淀粉后汤汁变稠加入适量鸡精，#\n11. 出锅后加入葱末..??有没有很清爽的感觉呢！#'),(802,'彩椒炒白玉菇','素菜','油#\n盐#\n蚝油#','20ml#\n4g#\n10ml#','1. 清洗干净白玉菇#\n2. 洗干净彩椒，切青，红，黄彩椒成小片#\n3. 下油炒一下彩椒，加点盐调味后装盘#\n4. 下油炒白玉菇，加点盐调味#\n5. 然后下彩椒，加一些蚝油翻炒均匀后装盘。#'),(803,'爆炒豆干','素菜','豆干#\n大葱#\n红椒#','#\n#\n#','1. 把豆干切条，不能太厚，也不能太薄，锅油热下入花掓，干辣椒段，蒜片，炒出香味下入大葱段，红椒丝翻炒10秒左右倒入豆干，大火快炒，放几滴香油，酱油，白糖，五香粉，盐，放入少许蒜苗，再淋半勺油翻炒均匀快速起锅，香气四溢，炒太久会干，所以火候一定得掌握好#'),(804,'猪大肠炒酸菜','荤菜','猪大肠#\n酸菜#\n盐#\n料酒#\n葱、紅萝卜#\n姜、蒜#\n油、醬油#\n白糖、糊椒粉#\n生粉#','500g#\n100g#\n1勺#\n2勺#\n1颗.5#\n4#\n2勺#\n1勺#\n1勺#','1. 生粉，盐搓洗#\n2. 洗净后加姜、葱、料酒煮1小时#\n3. 煮后捞起洗干净切好。#\n4. 炒香姜、蒜、干葱头、能吃辣放干辣椒一起炒香#\n5. 放大肠加料酒小火炒1分鐘#\n6. 放酸菜、紅萝卜炒下。#\n7. 將醬料勾成芡汁翻炒几下大火收汁。#\n8. 成品上碟啦#'),(806,'荷兰豆炒芹菜','素菜','荷兰豆#\n芹菜#\n辣椒#\n蒜#\n盐#\n油#','300g#\n300g#\n少量#\n少量#\n少量#\n少量#','1. 准备芹菜300g#\n2. 准备荷兰豆300g#\n3. 准备少量蒜，辣椒，切碎当配料#\n4. 切好芹菜，在锅里热（炸）好油，放配料下去热，热好把芹菜和荷兰豆一起放下小炒#\n5. 炒十分钟左右放上盐、酱油，小炒一会可以出菜了。(素食者或减肥可以试下这道小清新)#'),(807,'秘制家常烧茄子','素菜','香菜#\n葱#\n蒜#\n盐#\n糖#\n生抽#\n鸡精#','1小把#\n半根#\n4瓣#\n1大勺#\n1大勺#\n约20ml#\n1小勺#','1. 茄子切斜片#\n2. 茄子切好备用#\n3. 葱、蒜切末备用#\n4. 香菜切末备用#\n5. 开炒！倒油。不要太多#\n6. 放入茄子大火翻炒，随后放入1/2的盐，转中小火继续翻炒至茄子软烂。#\n7. 放入葱蒜末翻炒，大火爆香#\n8. 加入西红柿大火翻炒，同时放入盐、糖、鸡精、生抽。#\n9. 最后临出锅前放入香菜末翻炒几下#\n10. 出锅啦！配米饭盖了帽了！#'),(809,'2016，早点遇见本真味#古法红糖麦粿煎','主食','自家小麦粉#\n橄榄油#\n古法红糖粉#\n鸡蛋#','250g#\n1勺#\n200g#\n1颗#','1. 小麦粉下盆，水慢慢倒入，注意黏稠度适中；再加入红糖粉搅拌均匀，红糖的甜度比较淡，口感也比较好，够上健康早餐。#\n2. 最后敲个鸡蛋下去拌匀 ，口感更酥爽#\n3. 黏稠度说明，可匀称下滴带点儿稠度#\n4. 平底煎锅一勺油摇匀，用饭勺盛一大勺倒入后轻轻晃动让麦液均匀铺开，改小火稍微煎会，金黄后翻面。#\n5. 喜欢酥脆点就让它多煎会，变得焦黄#\n6. 搭配五谷豆浆或者牛奶，非常相搭非常爽口的快手早餐就完成了！#'),(811,'红烧茄子','素菜','茄子#\n西红柿#\n青椒#\n大葱#\n姜#\n大蒜#','一个#\n半个#\n半个#\n少许#\n少许#\n少许#','1. 茄子，西红柿，青椒备用#\n2. 葱姜蒜切末备用#\n3. 青椒，西红柿切块备用#\n4. 茄子切厚片，在各片上切一字花刀#\n5. 然后切成菱形块备用#\n6. 起火，烧油#\n7. 用干淀粉将茄子包裹匀#\n8. 油温8成热，将茄子下锅#\n9. 炸至金黄色捞出#\n10. 留底油，葱姜炝锅#\n11. 炒香后，放入茄子，青椒，西红柿#\n12. 放盐，糖，味精，酱油调味，加少许汤烧3-5分钟#\n13. 大火收汁，加入蒜末，香油炒匀#\n14. 出锅装盘！#'),(812,'酱烧梭鱼','荤菜','梭鱼#\n黄豆酱#\n甜面酱#\n郫县豆瓣酱#\n生姜#\n料酒#\n盐#','#\n#\n#\n#\n#\n#\n#','1. 梭鱼收拾干净，斩去头尾，肚子里的黑膜和油脂一定要去掉；切成段，用料酒，盐和生姜腌制，至少半小时。#\n2. 煎鱼段，四面都要煎，可以煎久一些，一定要煎透，鱼肉煎成金黄色，盛出待用。#\n3. 另起锅，油量要比炒菜多一些，下入腌鱼的姜片煸炒，姜片变色后盛出不要，下入郫县豆瓣酱小火炒出红油，再加入黄豆酱与甜面酱，翻炒均匀后，加水，也可以加用梭鱼头尾熬的鱼汤，大火烧开，放入煎好的鱼块，烧制大概15分钟，期间要轻轻翻动下鱼块，使其均匀入味。最后大火收汁，撒葱花装盘！#'),(813,'懒人菜·熥肉','荤菜','五花肉#\n葱#\n姜#\n糖#\n料酒#\n生抽#\n花椒#\n大料#\n剁椒酱#','300g#\n2段#\n一片#\n适量#\n一小勺#\n3-4勺#\n适量#\n1个#\n少量（可不加）#','1. 肉切片，3mm左右厚，临时想起来做没有五花就用这种代替了。葱分两种，一半切段另一半切小片，姜切丝。#\n2. 肉片码在碗里，葱姜花椒大料埋在中间，加料酒酱油糖，剁椒酱是我自己加的不加也可以。进锅蒸，水沸腾后保持中大火继续蒸15分钟左右，具体看肉的多少。#\n3. 炸花椒油。不喜欢花椒的这一步可以忽略。#\n4. 肉连碗端出来加葱花，做了花椒油的泼上去就可以啦～#'),(814,'小炒肉','荤菜','肉#\n青椒#','#\n#','1. 青椒切丝#\n2. 不放油在锅内干煸、起皱盛出#\n3. 肉切丝加湿淀粉、味精、不要放盐下油锅炒#\n4. 加盐、酱油、青椒略炒,起锅#'),(816,'小炒香肠','荤菜','香肠#\n大蒜苗#\n青椒红椒#\n豆豉#\n大蒜#\n小米椒#','2条#\n2根#\n各1只#\n1小把#\n#\n2、3只#','1. 大蒜苗斜刀切段#\n2. 香肠切片，这是自己家做的#\n3. 青椒红椒切成条，小米椒切小段，大蒜切粒#\n4. 豆豉用温水泡一小会儿，把水倒了#\n5. 锅里下油，不用太多，因为香肠会出油，先放蒜粒爆香，再下香肠，中小火，煸炒出油来#\n6. 待香肠出油，先放蒜苗，再放蒜苗叶子，炒一会，放入青红椒和豆豉一起翻炒，加酱油和盐，少加盐，香肠本身有咸味#\n7. 用装豆豉的碗加入小半碗凉白开，倒入国内，稍微煮一会，加入鸡粉和白砂糖，关火，出锅#'),(817,'紫薯红薯桂圆汤','汤','紫薯，红薯#\n桂圆，大枣，枸杞#','100g#\n适量#','1. 紫薯，红薯选各一根#\n2. 削皮，待用。#\n3. 把它们切成块，待用。#\n4. 大枣，桂圆，枸杞，待用#\n5. 放水，放大枣桂圆先煮，让它出来枣和桂圆的味道。#\n6. 然后放入紫薯和红薯，它的颜色是紫薯的颜色很漂亮。#\n7. 煮到粘稠了就可以必火，大概也就二十分钟，薯类很好熟。#\n8. 要出锅时，撒上枸杞，一盘减肥的美味汤出锅了。#'),(818,'【素斋】蜜汁排骨','素菜','豆腐衣#\n山药#\n干淀粉#\n海天叉烧酱#\n老抽#\n白糖#\n味精#\n白芝麻#','4张#\n1条#\n适量#\n一大勺#\n1小勺#\n一小勺#\n适量#\n一小戳#','1. 山药去皮切成8cm 的长条#\n2. 豆衣冷水冲一下切成宽6厘米的长条#\n3. 豆衣包卷在山药条上，热油五成，做好的排骨裹上干淀粉下锅炸成金黄色起锅#\n4. 锅中留底油放入叉烧酱、老抽、白糖烧开，倒入炸好的排骨，水淀粉勾芡收汁#'),(819,'6宝儿之五彩缤纷（宝宝下饭杀手）','不属于任何一类','腊肠或肉丁#\n玉米#\n胡萝卜#\n青豆#\n葱花#\n姜沫#\n蒜沫#\n盐#\n鸡精#','一根#\n一根#\n一根#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 首先准备好胡萝卜丁、玉米粒、腊肠丁或者肉丁、青青豆粒……#\n2. 接着把葱、姜、蒜剁成沫或者切成片……#\n3. 然后热锅入油、把腊肠和佐料放入煸炒、煸炒出香味盛起……#\n4. 然后倒入胡萝卜、玉米、青豆进行煸炒、盖上锅盖焖一会儿……焖软后加入盐和鸡精……#\n5. 最后加入已经炒好的腊肠进行翻炒……准备出锅……#\n6. 出锅了、来个简单的摆盘……6宝儿开心坏了……亲们也试试吧……(≧?≦)#'),(820,'红烧鸡根','荤菜','鸡根#\n料酒#\n椒盐粉#\n鲜酱油#\n冰糖#\n草菇老抽#\n姜#\n葱#\n水#','10个#\n1勺#\n少量#\n1勺#\n15g#\n20ml#\n3片#\n3段#\n250ml#','1. 先出水，用冷水冲洗干净，沥干。#\n2. 每个鸡根上切几刀，（为了更好入味）加葱姜，加料酒，椒盐粉，鲜酱油，白糖一丁点儿，搅匀腌制。#\n3. 腌制三四小时，基本入味。#\n4. 为了健康，不起油锅，直接高压锅。加老抽，加冰糖，高压锅上气后十分钟左右。#\n5. 闷一会儿，出锅。放几根葱装饰。#\n6. 儿子爱吃素，今天破天荒吃了五个鸡根惊呆我了。#'),(821,'青菜豆腐汤','汤','青菜#\n嫩豆腐#\n葱#\n盐#','#\n#\n适量#\n适量#','1. 将豆腐切成小块。#\n2. 锅内放水加一勺盐放入切好的豆腐煮沸。#\n3. 将煮好的豆腐捞出放入盘中。#\n4. 锅内放油后加入葱花爆香。#\n5. 将豆腐放入锅内加水。#\n6. 然后把洗净的青菜放入。#\n7. 煮至青菜变熟加少许食盐调味即可。#'),(822,'杏鲍菇炒玉米','素菜','杏鲍菇#\n玉米粒#\n胡萝卜#\n尖椒#\n大蒜#\n老抽#\n生抽#','1个#\n一碗#\n1个#\n1个#\n3瓣#\n1勺#\n1勺#','1. 都切成丁#\n2. 1、炒锅里放入适量的油，下蒜瓣爆香。闻到蒜香后下胡萝卜丁，翻炒均匀。2、下剥好的玉米粒，翻炒半分钟。3、放入杏鲍菇丁，加一勺v盐翻炒至杏鲍菇变软。4、下尖椒丁，继续翻炒至尖椒断生。5、调入1勺生抽，半勺老抽调味，大火翻炒均匀即可出锅。#'),(823,'鸡柳','荤菜','鸡胸#','500g#','1. 鸡胸肉洗净，顺肉纹切成条状，滤干水分待用#\n2. 加入腌料腌制半小时以上，（我个人买的奥尔良风味的）#\n3. 鸡蛋打匀加入面粉（淀粉），充分包裹鸡肉#\n4. 裹上面包糠放置三分钟，起油锅开炸#\n5. 炸至金黄出锅#\n6. 大功告成#'),(824,'清爽小菜','素菜','胡萝卜#\n黄豆芽#\n香芹#\n木耳#\n香葱末#\n醋#\n盐#','#\n#\n#\n#\n适量#\n适量#\n适量#','1. 胡萝卜、香芹、木耳切丝，豆芽择去根部。#\n2. 锅内放少许油，煸香香葱。#\n3. 将所有原料下锅翻炒。#\n4. 盖好盖稍微焖一会。#\n5. 放入盐、醋调味即可。#'),(825,'清爽拌菜','素菜','米醋#\n盐#\n糖#','#\n#\n#','1. 准备所需菜料。#\n2. 准备所需辅料。#\n3. 白糖、盐、米醋搅拌，待盐、白糖完全融化后，酸甜的糖醋汁就调好了。#\n4. 把糖醋汁浇到先切好的白菜、紫甘蓝、彩椒丝上拌匀即可！#\n5. 成品！#'),(826,'清炒空心菜','素菜','空心菜#\n油#\n葱段#\n蒜末#\n精盐#\n香油#\n味精#','#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 空心菜洗干净，然后摘段，其实就是用手撕撕，就行了，根有老的就不要。#\n2. 锅内放油，油热，放葱段，蒜末炒10秒种. 倒入摘好的空心菜，大火翻炒一分钟，让空心菜瘪下去。#\n3. 加少许精盐用大火急炒，菜软时加点香油、精盐和味精，出锅即可。#'),(827,'自创菜-凉拌仙人掌（清热解毒）','素菜','仙人掌#\n小红辣椒#\n醋#\n糖#\n生抽#','2片#\n2个#\n5ml#\n3g#\n15ml#','1. 仙人掌去除刺，我从超市买回来的是已经处理好的了。#\n2. 把仙人掌切成长条，放清水里泡，多洗几次把黏液去除。#\n3. 烧开水，放点油和盐，将仙人掌煮到变黄色，这时涩味基本去除。放入清水再冲洗一次，黏液在医学上称之为玉芙蓉可以食用。#\n4. 将生抽、陈醋、少许白糖做成蘸汁#\n5. 小红辣椒切圈，放一点在蘸汁里，余下做装饰。#\n6. 酸爽可口的凉拌仙人掌就做好了#'),(828,'阿基師家常菜_腐乳空心菜 2011.06.01','素菜','空心菜#\n辣味豆腐乳#\n辣椒絲#\n蒜末#\n豬油#\n醬油#\n香油#','600g#\n4小塊#\n2大匙#\n1大匙#\n1大匙#\n1小匙#\n2小匙#','1. 取一水晶碗，下豆腐乳、1大匙熱水拌勻ps:豆腐乳包入保鮮膜中壓泥(這樣比較好拌)#\n2. 再下醬油拌勻備用。#\n3. 空心菜洗淨後，用手摘取嫩葉，備用。#\n4. 起一炒鍋，下豬油#\n5. 下蒜末、辣椒絲爆香#\n6. 依序下調勻的豆腐乳(做法2)、空心菜、水炒勻至熟盛盤。#\n7. 最後再淋上剩餘的豆腐乳(做法2)醬汁、香油即可。#'),(830,'香菇木耳炒鸡蛋','素菜','香菇#\n木耳#\n鸡蛋#\n葱 蒜#\n耗油#\n水淀粉#\n盐#\n蘑菇精#','300g#\n100g#\n2个#\n适量#\n1大勺#\n适量#\n适量#\n适量#','1. 香菇去梗洗后切片，木耳泡发#\n2. 鸡蛋加水、加盐打散#\n3. 葱蒜切碎#\n4. 热油炒鸡蛋#\n5. 鸡蛋炒熟切丝#\n6. 热油葱蒜爆香#\n7. 香菇下锅加盐翻炒变软加入耗油#\n8. 木耳下锅翻炒均匀加少许水大火炖两分钟#\n9. 加入鸡蛋炒匀，烹入水淀粉加蘑菇精#\n10. 装盘结束#'),(833,'西红柿鸡蛋汤','汤','西红柿#\n鸡蛋#\n姜#\n大葱#\n料酒#\n盐#\n味精#','一个#\n一个#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 西红柿洗净，鸡蛋一个备用。#\n2. 姜切片大葱切段。#\n3. 西红柿切块，备用#\n4. 鸡蛋加入料酒，盐，备用#\n5. 锅中放油，放入姜片，葱断，倒入西红柿煸炒，放入少许料酒#\n6. 加入开水烧熟#\n7. 锅中水开后，打入鸡蛋，出锅前放入味精，盐调味即可#\n8. 盛出即可享用#'),(834,'酸甜里脊肉','荤菜','里脊肉#\n生粉#\n番茄酱#\n白糖#','一小块#\n少许#\n少许#\n少许#','1. 把里脊肉切碎#\n2. 用菜刀剁碎。#\n3. 拿少许生粉，加入少许酱油。#\n4. 一起拌匀，让它俩粘在一起，加入点鸡精就可以。#\n5. 锅烧热，加入少许油准备煎。#\n6. 把肉泥用小勺子一个一个放到油锅里煎。#\n7. 煎成两面金黄色即可。#\n8. 用吸油纸把表面的油吸干。#\n9. 锅里放入少许番茄酱，用小火，再加入少许白糖一起搅匀。#\n10. 把里脊肉放到锅里和番茄酱一起融合。好诱人的颜色。#\n11. 装盘，可以用牙签戳着，也可随便摆造型。当零食也可以哦！酸酸甜甜好食欲。#'),(835,'土豆烧排骨','荤菜','排骨#\n姜蒜#\n郫县豆瓣#\n大葱#\n八角香叶#\n花椒#\n料酒#\n老抽#\n葱花#','两根#\n适量#\n#\n#\n#\n#\n#\n#\n#','1. 排骨掉水#\n2. 准备豆瓣和香料，忘拍八角了#\n3. 油烧开掉入香料炒香#\n4. 下入排骨炒5分钟#\n5. 加水、淹过排骨就行了#\n6. 烧开后加入土豆和大葱，大火烧5分钟后、转小火30分钟后大火5分钟、#\n7. 关火，上盘，撒葱花，个人建议，不用收汁、有汁美味一点#'),(836,'五香鹌鹑蛋','荤菜','鹌鹑蛋#\n桂皮#\n香叶#\n花椒#\n八角（大料）#\n冰糖#\n海鲜酱油#\n老抽#\n盐#','400g#\n2小块#\n2片#\n6粒#\n2粒#\n5粒#\n少许#\n一点#\n2勺#','1. 鹌鹑蛋洗净。#\n2. 水烧开下入鹌鹑蛋，煮5分钟。#\n3. 捞出过凉水，用勺子轻轻敲碎蛋壳。#\n4. 重新烧一锅开水。这时准备材料：桂皮、香叶、八角、花椒、冰糖、海鲜酱油、老抽、盐。将所有材料放入锅中。#\n5. 待水开把鹌鹑蛋重新下锅中火煮15分钟，关火，晾凉。放阴凉处浸泡一夜，入味。#'),(837,'销魂土豆泥','素菜','土豆#\n火腿肠#\n青椒#\n胡萝卜#\n盐#\n沙拉#\n玉米粒#\n牛奶少许#','一个#\n2根#\n适量#\n适量#\n少许#\n适量#\n少许#\n#','1. 【销魂土豆泥】做法：1、一个中号偏大的土豆切块儿加半碗水放微波炉高火转10分钟；2、取出后尽情的用木槌儿捣成泥状，加入牛奶、3大勺沙拉酱、盐、火腿粒，最好再配一些用盐煮好的青菜和玉米粒~~倍儿好吃！#'),(838,'虾仁黄瓜','荤菜','虾仁#\n黄瓜#','180g#\n1根#','1. 虾仁剃虾线，黄瓜切丁。#\n2. 加淀粉，盐，料酒腌制。如果是新鲜虾就不用加料酒，速冻虾仁腥味太大，加料酒去腥。#\n3. 油6、7分热，下虾仁翻炒，然后下黄瓜丁翻炒，加盐，鸡精，味精。#\n4. 起锅啦，炒鸡简单，又好次营养！天天麻辣换换口味也不错哦～#'),(839,'双拼大虾（奶酪焗+蒜蓉黄油烤）','荤菜','蒜茸#\n黄油#\n橄榄油#\n盐#\n胡椒粉#\n牛至碎#\n胡萝卜粒#\n葱花#\n料酒#\n马苏里拉奶酪#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 大虾洗净，去头、虾须、脚、留尾部。背部划开成至虾肉的2/3处，去虾肠及虾线。用刀背拍几下剖成两半的虾。#\n2. 虾先用料酒和盐腌10分钟。1、蒜蓉黄油烤虾：蒜蓉、黄油、橄榄油、少许盐调和，均匀抹于虾肉上，再撒上一些胡萝卜粒。2、奶酪焗：撒上黑胡椒、牛至碎，均匀涂抹蒜蓉酱（蒜蓉、橄榄油、盐），面上撒一层马苏里拉奶酪。#\n3. 烤箱烤盘均预热，两种虾一起入烤箱，200度烤六分钟，取出撒葱花，继续烤两分钟。时间一到，取出虾装盘，一道华丽丽的双味大虾就做好了！#'),(841,'清炒老南瓜','素菜','老南瓜#\n红辣椒#\n葱蒜末#\n油，盐，鸡精，白糖#','一斤#\n3个#\n适量#\n适量#','1. 老南瓜去仔切片#\n2. 红辣椒切小圈，葱蒜切末#\n3. 起锅热油，依次放入葱蒜末和辣椒爆香#\n4. 待到辣椒稍微变熟，下入南瓜片翻炒#\n5. 大火煸炒几分钟，南瓜稍微有点熟就加入适量白糖#\n6. 最后翻炒至南瓜基本软熟变色，调入适量盐和鸡精，即可出锅#'),(842,'妈妈的味道--榨菜肉丝','荤菜','猪肉#\n榨菜#\n红青椒#\n绿青椒#\n姜#\n蒜#\n淀粉#','150g#\n50g#\n50g#\n50g#\n2片#\n2瓣#\n适量#','1. 猪肉切丝，越薄越好，容易入味。#\n2. 加入淀粉和料酒腌制，想偷懒的话可以在这一步直接倒入生抽和少许盐，这样炒制的时候就不需要调味。不过对味道的掌控不高的话还是晚点再加。#\n3. 姜蒜切小块。#\n4. 锅中热油。#\n5. 油热后先倒入姜蒜煎出香味，然后倒入榨菜丝和青椒丝，稍微翻炒一下盛出备用。#\n6. 另起一锅，再热油，这次的油要烧的很旺，火候大炒出来的肉才好吃。#\n7. 倒入肉丝，翻炒变色后加入之前炒过的榨菜丝和青椒丝。#\n8. 加入少许盐和生抽调味即可。#'),(843,'香椿炒蛋','素菜','香椿#\n鸡蛋#','1把#\n4个#','1. 香椿洗净后焯水，剁碎。#\n2. 鸡蛋打散，加盐，香椿碎，拌匀。#\n3. 油锅烧热，倒入混合后的蛋液。蛋液凝固后翻炒几下，保证蛋液全部凝固熟透即可。#'),(844,'香口金沙豆腐','素菜','嫩豆腐#\n生的咸鸭蛋黄#\n葱花、蒜蓉#\n生抽#','3小块#\n2个#\n适量#\n1勺#','1. 材料图#\n2. 豆腐切成小块，蛋黄用勺子压碎；#\n3. 锅中加油，烧热后下豆腐块儿中火慢慢煎;#\n4. 两面金黄后，捞出备用；#\n5. 用锅中余油，下蒜蓉及咸蛋黄小火炒，边炒边用铲子压碎蛋黄粒，直到如图冒泡泡，闻到蛋黄的香味儿;#\n6. 倒入煎好的豆腐块儿;#\n7. 拌匀，加入生抽调味儿，再略翻炒一下下，让每块豆腐都裹上沙沙的金黄的咸蛋黄，出锅前撒上葱花就可以啦！#\n8. 成品，漂亮吧！#\n9. 盘子底的，浇到米饭上，拌着吃，实在太香太好吃了，真正的做到光盘了呢！嘻嘻！#'),(845,'火爆大头菜','素菜','大头菜（有的地方叫包菜，莲花白）#\n花椒粒#\n干红辣椒#\n盐#\n鸡精#','一个#\n少许#\n少许#\n适量#\n适量#','1. 把大头菜用手撕开，去掉中间的茎，只要叶子。#\n2. 如图#\n3. 热锅热油，下花椒粒，干辣椒，5秒后，下大头菜，迅速翻炒，出锅时放盐，鸡精。#\n4. 出锅，如图，完成！#'),(846,'糖醋莲花白','素菜','莲花白#\n姜#\n蒜#\n干辣椒#','一个#\n#\n#\n#','1. 洗好，切好莲花白#\n2. 准备材料#\n3. 锅中倒油烧热，倒入莲花白翻炒#\n4. 先翻炒，后放入红辣椒，再放酱油，醋，糖翻炒几分钟，自己把握#\n5. 根据口味放入盐#\n6. 出锅#'),(847,'花旗参炖瘦肉汤','汤','瘦肉#\n花旗参#\n枸杞#\n纯净水#','200g#\n20g#\n5g#\n3碗#','1. 瘦肉剁碎，盛入炖盅。#\n2. 加洗净的花旗参，加纯净水3碗。#\n3. 盖好炖盅，放入炖锅，加水至炖盅7分之5处。#\n4. 我用的是依立慢炖紫砂锅，晚上10点准备好，预今早7点喝，故预5小时后开炖，隔水炖要3小时40分。#'),(848,'开屏鲈鱼','荤菜','鲈鱼#\n姜片#\n火腿肉片#\n红绿辣椒#\n料酒，鲜酱油#','一条1斤左右#\n若干#\n若干#\n若干#\n若干#','1. 鲈鱼切好，撒一点点细盐#\n2. 姜片肉片#\n3. 很简单的摆放，姜片放下面，火腿放下面，红绿辣椒摆放好#\n4. 放入料酒，鲜酱油，色拉油，开水蒸15分钟，出炉即可#'),(849,'杏鲍菇炒牛肉','荤菜','牛肉#\n杏鲍菇#\n青椒#\n红椒#\n腌制牛肉：#\n细盐#\n白糖#\n生粉#\n料酒#\n玉米油#\n黑胡椒粉#\n菜品调味料：#\n李锦记蚝油#\n细盐#\n酱油#','200克#\n100克#\n半个#\n半个#\n#\n1小匙#\n1小匙#\n1小匙#\n1大匙#\n1大匙#\n1小匙#\n#\n2大匙#\n1/2匙#\n1小匙#','1. 牛肉切成小方块，加入一小匙盐、糖。#\n2. 加入黑胡椒粉、料酒、生粉。#\n3. 加入玉米油后拌匀，腌制20分钟。#\n4. 将杏鲍菇洗净。#\n5. 切成和牛肉一般大的小块。#\n6. 将红、青椒也切成小块。#\n7. 热锅内倒入油，将腌制好的牛肉倒入锅内。#\n8. 牛肉炒至6成熟时，捞起。#\n9. 锅内留少许油，将杏鲍菇倒进锅内翻炒2分钟。#\n10. 将牛肉倒回锅内，放1/2小匙盐。#\n11. 再倒入蚝油翻均。#\n12. 最后把青、红椒块倒进去，翻拌均匀，继续炒1分钟即可出锅。#'),(850,'猪皮冻（小马哥版）','荤菜','猪皮#\n大葱#\n姜#\n香叶#','500g#\n#\n#\n#','1. 猪皮先用开水烫一下变色即可#\n2. 捞出后有刀将猪皮上的肥油剃掉，再切成细丝备用#\n3. 锅加水加入葱，姜，香叶，猪皮大火烧开，转小火盖盖闷30~40分钟#\n4. 将煮好皮冻到入合适的容器中放凉冷却#\n5. 定型后切成块即可#'),(852,'牛里脊西红柿下饭酱汤','汤','牛里脊#\n土豆#\n洋葱#\n西红柿#','一条#\n一个#\n半个#\n两个#','1. 牛肉用水泡20分钟去血水 西红柿烫过去皮后切块可以不用切太小 土豆切片  姜片备用#\n2. 洋葱切细丝#\n3. 底油 姜片煸香 下牛肉翻炒1分钟#\n4. 放洋葱丝继续煸炒1分钟#\n5. 放西红柿 土豆片翻炒2分钟 加水没过牛肉 大火炖开转小火半小时 加调味料 盐糖鸡精 出锅 可以撒些香菜#\n6. 汤给宝宝下了面 味道还是不错的#\n7. 出锅啦 配米饭好吃#'),(853,'火爆鸡尖','荤菜','鸡尖#\n红海椒#\n青椒#\n鸡精#\n豆瓣酱#\n八角#\n盐#\n食用油#\n白糖#\n酱油#\n姜蒜#\n干花椒#','适量#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 青椒切成筒，红椒切成菱形状！#\n2. 鸡尖洗干净。晾干水分！#\n3. 姜蒜切成片，准备八角干花椒，放入碗里备用！#\n4. 锅内放入菜油，烧辣！#\n5. 放入准备好的，八角姜蒜花椒，炒香！#\n6. 倒入鸡尖，炒至鸡尖蕉黄！加入豆瓣酱，白糖，少许酱油！#\n7. 放入切好的辣椒！#\n8. 翻炒两分钟。加入鸡精和盐！#\n9. 装盘！#'),(854,'芹菜炒虾仁','荤菜','西芹#\n虾仁#\n蚝油#\n葱#\n姜#','#\n#\n#\n#\n#','1. 准备好所需的材料#\n2. 西芹焯水#\n3. 先下葱姜炒香，再倒入虾仁，虾仁至七分熟可以倒入西芹，放蚝油，炒两分钟，即可装盘盛出～#'),(855,'酸辣笋条','素菜','冬笋#\n鲜酱油#\n辣椒油#\n香醋#\n白糖#\n盐#','750g#\n4汤匙#\n适量#\n1汤匙#\n5g#\n2g#','1. 冬笋洗净后去老根和壳#\n2. 切成条状#\n3. 锅内水开后加入2克盐下入冬笋条煮熟后捞起#\n4. 把调料调成酸辣汁#\n5. 煮熟的冬笋捞起后倒入调料等半小时再食用#\n6. 上桌#\n7. 成品图#'),(856,'酸黄瓜炒肉丝','荤菜','酸黄瓜  （自制的或罐头式的都行）#\n胡萝卜#\n肉#\n蒜#\n盐#\n酱油#\n十三香#','#\n1小块#\n1小块#\n2瓣#\n#\n#\n#','1. 这里我用的是现成的酸黄瓜罐头。酸黄瓜、肉丝、胡萝卜（没有也可以不放）切丝，蒜切片。#\n2. 先将肉炒变色，加入一点十三香，在放入一些酱油调色。#\n3. 放胡萝卜丝 和 酸黄瓜丝 翻炒，酸黄瓜炒软后，加入少许盐。（如果黄瓜不够酸，可以加入少许米醋，少许白糖调味儿）#\n4. 出锅前 放入蒜片爆香。#\n5. 出锅喽！#'),(857,'鱼香茄子','素菜','长茄子#\n油#\n盐#\n酱油#\n水淀粉#\n生姜#\n大蒜瓣#\n小葱#\n豆瓣酱#\n泡椒#','一个#\n适量#\n适量#\n适量#\n适量#\n一块#\n三瓣#\n两颗#\n适量#\n三个#','1. 准备好原材料#\n2. 茄子去皮切成细长条#\n3. 生姜、大蒜瓣切成末，小葱切碎#\n4. 泡椒剁成末，豆瓣酱剁细#\n5. 锅里加入适量油，放入茄子小火煸炒，加入适量盐，慢慢煸炒出水分，炒软出锅待用#\n6. 锅里再加入少许油，加入泡椒末、豆瓣酱、小葱葱头部分，煸炒出香味#\n7. 加入少许水，烧开#\n8. 加入茄子，焖煮两分钟#\n9. 加入适量酱油、水淀粉，翻炒均匀，撒上葱花#\n10. 出锅了#'),(858,'藤椒鸡#寻找最聪明的蒸菜达人#','荤菜','鸡#\n红米椒#\n青米椒#\n黄酒、海盐、香叶、八角、小茴香、花椒、胡椒粒、葱束、姜片#\n藤椒油#\n白芝麻#','一只#\n5只#\n5只#\n少许#\n40ml#\n少许#','1. 将鸡去头去尾洗净#\n2. 斩成小块后加入黄酒、海盐、香叶、八角、小茴香、花椒、胡椒粒、葱束、姜片腌制15分钟后，取出装盘。另起蒸锅，上汽后放斩好的鸡蒸熟（约10分钟焖5分钟#\n3. 起锅放鸡汤烧开后放切好的红米椒和青米椒，加少许的盐，芝麻，糖，姜末，鸡粉调味，起锅前加一大勺藤椒油#\n4. 然后浇到蒸熟的鸡上就可以啦#\n5. 上桌，享用，很香滴~（天热的时候，还可以放冰箱冷藏后吃）#'),(859,'港式生炒骨','荤菜','排骨#\n青红椒各#\n罐装菠萝#\nＡ：生抽#\n胡椒粉#\n糖#\n香油#\n淀粉　#\nＢ：番茄酱#\n糖#\n白醋#\n水淀粉#\n盐#\nＣ：淀粉#\n泡打粉#\n水#','一斤#\n一个#\n两片#\n15ＭＬ#\n5克#\n2克#\n5ＭＬ#\n3克 　　#\n80克#\n30克#\n15ＭＬ#\n20克#\n3克 　　　#\n80克#\n4克#\n少许#','1. 将排骨洗净后，与Ａ料拌匀，腌制30分钟。青红椒、菠萝切块。#\n2. Ｂ里所有调料混合均匀，Ｃ里粉类过筛后与少量水调成面糊备用。#\n3. 起锅热油，到八成热时，将腌制好的排骨，放入Ｃ的面糊里裹上浆，放油锅炸熟。#\n4. 所有排骨都炸熟后，捞出，再将油锅烧至十成热，将排骨复炸一次，10秒钟后捞出，放厨房纸上吸干多余油份。#\n5. 炒锅内倒少量油，将青红椒、菠萝块爆炒后捞出。再将Ｂ料倒入，烧开后，放入炸好的排骨与炒过的青红椒、菠萝块，均匀的裹上酱汁即可出锅。#'),(860,'蒸茄子','素菜','生抽#\n蚝油#\n大蒜#\n香油#','#\n#\n#\n#','1. 茄子切条上锅蒸熟。#\n2. 调汁：香醋一勺，生抽一勺，蚝油一勺，少许鸡精，一点红糖，大蒜切蓉，加点香油，混合搅拌。喜欢辣的加点红尖椒蓉。#\n3. 茄子蒸熟后将调汁浇在茄子上。#'),(861,'咕噜排骨','荤菜','排骨#\n菠萝#\n彩椒#\n胡萝卜#\n番茄酱#\n盐#\n生粉#\n鸡蛋#\n胡椒粉#\n水#','1条#\n半个#\n1个#\n半个#\n适量#\n#\n#\n#\n#\n#','1. 准备材料，切好备用#\n2. 排骨用盐 生粉 胡椒粉腌一下，裹上蛋液后再沾生粉，放在锅里煎吃金黄色#\n3. 一边煎排骨一边调汁，番茄酱 水 白醋 糖，煮沸#\n4. 然后倒入排骨 菠萝 彩椒 胡萝卜一起煮，熟后大火收汁#\n5. 成品#'),(862,'白菜酱肉包子','主食','肉#\n大酱#\n油#\n香油#\n味精#\n葱姜#','#\n#\n#\n#\n#\n#','1. 肉（七分瘦，三分肥）切丁，大酱（不用放盐，咸味够了）油，一勺香油，味精，切些葱姜末一起拌匀#\n2. 把切成丁的白菜用几勺油拌匀，油把菜包住，就不会出太多水#\n3. 发好的面团切剂子，擀皮，把馅料拌匀，包馅，收口（切记，包子包好后不要停留太长时间，因为白菜太容易出水了，以防塌底）#\n4. 包好的包子，冷水下锅蒸熟（谁都不许笑话我，俺的包子就包成这样了，难看也没办法啊）#'),(864,'鸡米花','荤菜','鸡脯肉#\n面包糠#\n鸡蛋#\n椒盐、食盐、辣椒面、黑胡椒粉#','500g#\n适量#\n1个#\n适量#','1. 把鸡肉切块，把所有调料和鸡蛋均匀搅拌在一起，尝下咸淡。然后腌制30分钟#\n2. 提前一天把面包片晒干，剁碎，把腌好的鸡肉倒在面包糠里均匀裹好。放进烤箱，180度25-30分钟就好啦。#\n3. 放在烤箱里180度25-30分钟#\n4. 趁热吃哦。#'),(865,'减肥水果沙拉','素菜','芒果#\n草莓#\n酸奶#','1个#\n6个#\n1瓶#','1. 草莓洗净切块备用芒果削皮切块#\n2. 倒入酸奶即可享用#'),(868,'香菇炒杂菜','素菜','干香菇50克，杂菜400克，蒜片少许，盐5克，几粒少许，生抽5克。#','#','1. 干香菇发好切条#\n2. 锅里放油煸炒香菇，使香菇金黄炒出香味。#\n3. 倒入杂菜翻炒，生抽，加盐，鸡精#\n4. 出锅喽#'),(869,'独家夏、秋季银耳香菇枸杞绿豆汤【3-4人】','汤','瘦肉【切片】#\n银耳【浸泡20分钟撕碎】#\n干香菇【浸泡，切丝】#\n绿豆#\n枸杞#\n红枣【去核】#\n菊花#','250g#\n适量#\n2个#\n1把#\n十几粒#\n2个#\n10g#','1. 所有食材处理好入汤锅加足水煲2小时即可，喝时候下盐#'),(870,'酸菜鱼','荤菜','草鱼#\n酸菜#\n姜蒜葱#\n花椒辣椒干#','一条#\n一包#\n适量#\n稍微多点#','1. 草鱼洗干净，切片刀法一定要好，切薄一点。用盐搓一下鱼片，再洗干净，加入盐，生粉淀粉红薯粉都可以，料酒（我放的是自己酿的米酒），蛋清（使鱼片润滑嫩）腌制一会，另一边开始熬汤！#\n2. 放油把姜蒜辣椒花椒炸香，放入开水，酸菜。调味，根据个人口味调，（不用放酱油、料酒）调味好之后盖上锅，熬10分钟，把酸菜的味道熬出来，#\n3. 放入鱼片，最好是快速的一片一片放。把锅盖上，看到沸腾了就开锅捞起来！#\n4. 最后，多放点油，烧开，把花椒放去炸香，浇上捞起来的鱼上面，一股香味就出来了，开吃！#'),(871,'红烧素鸡','素菜','素鸡#','一条#','1. 买来素鸡一条，用水冲洗干净，餐巾纸擦干水份。#\n2. 切成5毫米厚度均勻的薄片。#\n3. 锅里放油，油微热后放入素鸡油煎。#\n4. 翻面，继续油煎。#\n5. 准备一盆冷水，将煎好的素鸡趁热放在冷水中浸泡。#\n6. 直至一条素鸡全部煎完，全部浸入水中。大约浸泡15-20分钟，期间用筷子上下翻翻，使素鸡都能吸满水份。#\n7. 将吸满水份的素鸡放入锅中，加酱油，盐，糖以及部分浸泡素鸡的水，大火烧开转小火煮5-10分钟。#\n8. 好了，吸满汤汁的素鸡出锅。最好早上烧，中午吃或者中午烧晚上吃，这样更入味。#'),(874,'下酒菜之啤酒鸭','荤菜','蒜苗#\n干辣椒#\n八角#\n桂皮#\n啤酒#\n盐#\n酱油#\n料酒#\n油#','4棵#\n适量#\n4个#\n少许#\n一罐#\n一勺#\n两勺#\n三勺#\n少量#','1. 第一时间，先把鸭肉洗干净，用一勺盐，两勺酱油，三勺料酒腌15分钟。#\n2. 姜切片，蒜切段。#\n3. 锅里少许油，先爆香姜片，八角桂皮干辣椒。#\n4. 加入鸭肉炒出鸭油来，把肉拨到一边，利用那些油炒大蒜，最后把鸭肉盛到瓦锅，底下的油不要。#\n5. 加入一罐啤酒，大火烧开，中火烧到收汁。#\n6. 开动。#'),(875,'木瓜排骨汤','汤','排骨#\n生木瓜#\n盐#\n水#','600g#\n300g（约半只）#\n2g（按个人口味放吧）#\n1200ml#','1. 木瓜削好皮，把木瓜籽拿出来，切成大块。放一边待用！#\n2. 把排骨切块，排骨切好后，现在用汤煲煮沸水，水开后放入排骨，大火将排骨煮沸后转回小火，煲30分钟#\n3. 30分钟过后开大火，然后倒入切好的木瓜，大火煮沸后转回小火再继续煲30分钟，提前5分钟放盐#\n4. 时间到啦！好喝的木瓜排骨汤可以喝啦！#'),(876,'菠菜豆腐','素菜','北豆腐#\n菠菜#\n金华火腿#\n生抽#','#\n#\n#\n#','1. 金华火腿切丁 豆腐切块#\n2. 葱花金华火腿下锅煸香#\n3. 豆腐下锅煸炒 加生抽 加水 炖煮#\n4. 炖煮几分钟后加入洗好的菠菜#'),(877,'西芹百合炒腰果','素菜','西芹#\n百合#\n腰果#\n盐#\n水淀粉#','200g#\n25g#\n1把#\n2g#\n少许#','1. 芹菜斜刀切片 百合掰成小片#\n2. 锅烧热放油 油热后放葱花姜丝爆香 先下入西芹翻炒片刻 再放百合 继续煸炒#\n3. 临出锅时放入腰果 少许水淀粉勾玻璃芡 出锅#'),(878,'香煎鸡翅','荤菜','鸡翅#\n蒜蓉#\n生姜#\n辣椒#','#\n#\n#\n#','1. 鸡翅洗净  在鸡翅上划几刀  用盐  酱油 姜米  老酒腌五分钟#\n2. 将蒜蓉  姜丝  辣椒准备好#\n3. 腌过的鸡翅洗干净沥干水  热锅下油  辣椒和姜丝放下锅  和鸡翅一起煎  可以再放一点盐  煎到一面变颜色换一面#\n4. 中火慢慢煎  煎到划开鸡翅里面没有血水  吃嫩一点就可以出锅   个人喜欢脆点的再煎会  最后放蒜蓉 葱花煎香  起锅#\n5. 全程不需要放水  多的油可以用来炒青菜#\n6. 装盘  开吃#'),(880,'蒜苔腊肠','荤菜','蒜苔#\n腊肠#','适量#\n一小根#','1. 腊肠洗净上锅蒸熟后取出，放凉切片备用。#\n2. 蒜苔洗净切段，大蒜拍碎切几下备用。#\n3. 热锅倒油，油热后放蒜放腊肠炒，炒十下左右放入蒜苔，我没放水所以用小火，慢慢炒熟的，差不多熟了放盐和味精，翻炒几下出锅。盐不能放太多不然腊肠很咸，成功！#'),(881,'麻辣尖椒豆皮','素菜','辣椒#\n豆皮#\n香菜#\n小葱#\n蒜瓣#\n油#\n醋#\n家酱#\n盐#\n辣椒面#','2个#\n2个#\n适量#\n适量#\n3个#\n适量#\n少许#\n2小勺#\n适量#\n少许#','1. 豆皮切成丝#\n2. 辣椒切成丝#\n3. 香菜切成小段 留到最后盛出菜后放入提味#\n4. 葱 姜 蒜 依次切好#\n5. 油锅热好了之后 将葱姜蒜一起倒入翻炒 再将辣椒 豆皮 倒入翻炒 炒的过程中 加入酱和醋 最后加入盐#\n6. 炒好菜 盛出菜之后 放入香菜  这样就完成了#'),(883,'油煎大虾','荤菜','大虾#\n盐#','7只#\n少许#','1. 大虾洗净，去须，去虾线，背部剪开，放少许盐（入味）#\n2. 把虾放入平底锅，倒入少许油，用中火两面煎。#\n3. 大约煎7到8分钟，等虾完全变红，就可以装盘了。#'),(884,'蒸鲈鱼','荤菜','鲈鱼#\n姜#\n蒜#\n葱#\n蒸鱼豉油#\n鸡粉#\n鸡汁#\n小米椒#\n酱油#\n料酒#','一条一斤多的#\n一颗#\n三头#\n些许#\n些许#\n些许#\n些许#\n五颗#\n些许#\n些许#','1. 鲈鱼剖好洗净#\n2. 姜切片、蒜切片、小米椒切成末，备用。#\n3. 用料酒、水淀粉、姜片、蒜片、葱段码制鲈鱼，最少码20分钟。#\n4. 锅里坐水，水开了再把鲈鱼放锅里蒸，我蒸了20分钟，起锅时趁着有热气把剩下葱段放在鱼身上，再淋上用:蒸鱼豉油、酱油、香油、鸡粉、鸡汁、花椒油兑成的料汁。上桌。#'),(885,'鳕鱼蒸蛋','荤菜','土鸡蛋#\n去皮鳕鱼#\n盐#\n无味植物油(玉米油)#\n高汤#','2个#\n一小块#\n少许#\n少许#\n一小碗#','1. 土鸡蛋打散，加入少许盐和玉米油调味，加入等量的高汤，过筛后倒入碗中，加入切成小丁的鳕鱼块，覆盖保鲜膜，用牙签戳几个小孔，水开后放入蒸笼，蒸8分钟左右～#\n2. 没有高汤不要紧，用浓缩鸡汁加水煮沸即可，超市都有卖～#\n3. 吃的时候，是滑进肚子里的好吗？鲜美到哭o(≧v≦)o~~再挑食的孩子也能轻松应付～#'),(886,'洋葱炒土豆片','素菜','洋葱#\n土豆#\n香菜末#\n花椒粉#\n盐#\n鸡精#\n植物油#','250克#\n100克#\n少许#\n少许#\n适量#\n少许#\n适量#','1. 将洋葱剥去老皮洗净，切成丝；土豆去皮，洗净，切成片。#\n2. 锅内倒入植物油烧至七成热，撒入花椒粉炒出香味，倒入土豆片翻炒均匀，加适量水烧沸。#\n3. 放入洋葱丝，翻炒熟后用盐和鸡精调味，撒上香菜末即可。也可不放香菜末#'),(888,'花旗参炖鸽药膳滋补汤','汤','乳鸽#\n花旗参#\n橙皮#\n百合#\n生姜#\n海盐#','#\n#\n#\n#\n#\n#','1. 准备好食材#\n2. 撕开绵绵精致包装，各个食材分类放置，将鸽子全身冲洗一遍#\n3. 花旗参、百合等食材用清水清洗净备用#\n4. 将食材一同倒入盛有1250毫升清水的汤锅中，煮沸后采用小火慢炖的形式，预计3小时左右，出锅前随个人口味放入调料，味道更鲜美#'),(890,'青椒回锅肉','荤菜','五花肉#\n花椒粉#\n生姜#\n大蒜#\n豆瓣酱#\n酱油#\n青椒#\n芹菜#','500#\n1g#\n10g#\n10g#\n30g#\n15ml#\n7个#\n50g#','1. 将五花肉洗干净放入锅里煮熟。煮的同时可以放一些萝卜土豆，待会可以直接当一个菜。#\n2. 肉不要煮太熟，内部带点血，就可以出锅了，然后切成如图薄片。加生姜蒜片一起煎。如果肉偏瘦，煎之前加油在锅里，如果偏肥就可以不用加油。#\n3. 青椒芹菜切段。待肉两面微焦时，倒入锅内，大火炒一炒。#\n4. 加入豆瓣酱，酱油，花椒面。一点点白糖。在炒一分钟即可出锅#\n5. 最后起锅时加一点味精。OK。完美#'),(891,'酱炒卤豆干','素菜','卤豆干#\n辣椒#\n辣椒酱#','适量#\n适量#\n一勺#','1. 准备豆干，绿辣椒#\n2. 豆干切片，辣椒切丝#\n3. 多放点油，辣椒下锅炒一下#\n4. 放入辣椒酱，超市都有，麻辣味的#\n5. 辣椒酱放进去炒一会就放豆干炒到豆干看着软了点，大概两分钟左右，火中火（我的加了点上一顿吃剩的火腿，童鞋们可以忽略）#\n6. 出锅#'),(893,'白灼芥兰','素菜','芥兰#\n大葱#\n蚝油#\n海鲜酱油#','#\n一小段#\n一勺#\n适量#','1. 芥兰洗净，把老皮去掉控水备用#\n2. 烧开水加入适量食用油，放入芥兰，焯1分钟左右关火焖一小会，待芥兰熟透捞出放入备好的凉水里#\n3. 葱段切成细丝，待芥兰放凉后捞出摆盘，葱丝洒在芥兰上面#\n4. 开油锅加入适量食用油，关小火，加入一勺蚝油以及适量海鲜酱油，拌匀，看到蚝油融开并微微冒泡关火，把调料直接倒入装好盘的芥兰上面#\n5. 成品#'),(894,'红烧鸡翅','荤菜','鸡翅#\n八角#\n糖，生抽#\n生姜#\n小葱#','12只#\n一个#\n适量#\n几片#\n一颗#','1. 鸡翅买回来用冷水淖一下（冷水烧热过程开始切生姜葱）沥干捞出，放在干净的盘子里。#\n2. 锅里放两勺油，爆葱姜。倒入鸡翅，翻炒几下，让鸡翅和油完全亲密接触。#\n3. 倒入两勺生抽，一勺白糖，加水，水盖过鸡翅即可。大火煮沸腾后切换为小火，尝咸淡，如果淡了适量加一点生抽。#\n4. 小火煮40分钟左右（在这个过程中水将慢慢变少，但切记观察水，不可烧干，否则鸡肉会变老）水耗为卤子的量即可关火，出锅。#'),(896,'油炒基围虾','荤菜','基围虾#\n葱、生姜、蒜瓣、干辣椒皮#\n盐（醋可放可不放）#','一斤#\n适量#\n少许#','1. 一斤基围虾，清水冲洗两到三遍#\n2. 准备适量葱、蒜、姜、干辣椒皮。姜切片，蒜切碎，辣椒皮切片#\n3. 放油，葱蒜姜辣椒皮炒香#\n4. 放虾，炒红#\n5. 放少许水，少许盐，醋可放可以不放，煮几分钟入味#\n6. 出锅#'),(898,'蓑衣凉拌黄瓜','素菜','黄瓜#\n盐　　　#\n香油#\n醋#\n白糖#','#\n#\n#\n#\n#','1. 黄瓜清洗干净后在黄瓜两边放两根筷子；90度直角把黄瓜切成薄片，因为有筷子所以可以防止把黄瓜切断；#\n2. 切完一面后把黄瓜翻身；刀的角度改为45度左右，也切成薄片就好了；#\n3. 把切好的黄瓜放入碗里，加少许盐，均匀撒在黄瓜表面，腌制20分钟；把腌制后的水倒掉；#\n4. 加一勺白糖；加两勺生抽；加两勺米醋（白色，黄色均可）；最后再加半勺香油即可。#'),(899,'蒸红鱼','荤菜','红鱼#\n葱姜#\n蒸鱼豉油 糖 生抽#\n油#','1条#\n适量#\n适量#\n适量#','1. 红鱼处理干净 用盐 黄酒 姜腌10分钟 上锅蒸10分钟#\n2. 去掉汁水 撒葱 用热油浇#\n3. 浇蒸鱼豉油 生抽 糖的混合液#'),(900,'花花土豆泥','素菜','土豆#\n胡萝卜#\n小葱#\n芝麻#\n蚝油#\n盐#\n醋#','1个#\n1个#\n1颗#\n1勺#\n半勺#\n适量#\n一点点#','1. 土豆切块上锅蒸熟#\n2. 凉凉后装袋子压成泥状#\n3. 压成泥状后倒入碗里#\n4. 加入蚝油芝麻盐醋拌匀#\n5. 加入葱末在拌匀#\n6. 装盘#'),(901,'乌贼炒韭菜','荤菜','乌贼#\n韭菜#\n青椒#\n盐#\n蒜#\n酱油#','300g#\n1小把#\n1颗#\n少许#\n2小瓣#\n2小茶匙#','1. 洗净备用#\n2. 切块，在背部开花#\n3. 韭菜洗干净，甩掉水，切段#\n4. 青椒切丝#\n5. 滚水后导入乌贼，30秒后捞起（去腥味，避免等一下下锅时油温突然下降）#\n6. 爆香蒜泥，倒入乌贼，大火炒一下，加入酱油（上色）#\n7. 加入韭菜#\n8. 加入青椒，炒一下，调味即可#\n9. 上菜#'),(902,'腌鹅蛋','荤菜','盐#','#','1. 把鹅蛋洗净晾干，然后把鹅蛋在高度酒里浸泡30至40秒。#\n2. 捞出鸡蛋滚上一层盐。#\n3. 用保鲜膜包好#\n4. 放在平盘里#\n5. 最后再用保鲜膜包好，放在太阳底下暴晒一下午，之后放在阴凉处一个月，就可以吃了。#'),(903,'干锅土豆片','素菜','土豆#\n杭椒#\n洋葱#\n蒜苗#\n香菜#\n周君记香水鱼调料#\n红99火锅底料#\n大蒜子#\n鸡精#\n味精#\n孜然粉#\n东古酱油#','500g#\n50g#\n50g#\n50g#\n少许#\n15g#\n15g#\n2个#\n少许#\n少许#\n1勺#\n15g#','1. 土豆切厚片，洋葱切块，杭椒、蒜苗、香菜切段，大蒜子切片。#\n2. 土豆中油温下锅炸成金黄色就可以。#\n3. 锅烧热放少许油，加入红99、香水鱼，在加入切好的蒜片、洋葱、杭椒、蒜苗，中火炒香，再加入炸好的土豆片炒30秒左右，再加入鸡精、味精、东古酱油、孜然粉，在加入少许水，炒至均匀装盘，洒上香菜即可。#'),(904,'可乐鸡翅','荤菜','鸡中翅#\n可乐#\n大葱#\n姜片#','10个#\n1罐#\n1根#\n1g#','1. 鸡中翅洗净滤干水分#\n2. 生姜切片备用，大葱切成小段#\n3. 起油锅，加入姜片，干辣椒煸香#\n4. 鸡翅加入煸炒至变色#\n5. 加入两勺生抽，翻炒两分钟#\n6. 倒入可乐把鸡翅全部淹没，盖上锅盖焖煮至汤汁收干#\n7. 大火收干汤汁后，倒入葱段#\n8. 好啦，装盘开吃#'),(905,'干煸芸豆','素菜','肉少许（可不放）#\n芸豆#\n花椒少许#\n葱姜蒜少许#','#\n500g#\n#\n#','1. 准备好所有材料#\n2. 芸豆下油锅过油，炸到外皮少皱#\n3. 先下少需肉煸炒出香，下芸豆继续大火翻炒几下，转中火防止糊锅#\n4. 出锅装盘就ok#'),(906,'香烤芦笋','素菜','芦笋#\n盐#\n黑胡椒碎#\n油#','150g#\n1小勺#\n1小勺#\n1大勺#','1. 芦笋洗净，去掉根部的老皮。大蒜切碎铺在中间。#\n2. 刷上油，放入烤箱，160度，中上层，先烤5分钟。#\n3. 5分钟之后撒上盐和黑胡椒碎。继续烤10分钟。#\n4. 待蒜末微微焦黄之后即可食用。#'),(907,'炝菜花','素菜','菜花#\n大葱#\n干辣椒#\n花椒#\n黄瓜#','#\n#\n#\n#\n#','1. 菜花切好，洗净备用。掰菜花的时候可以炉子上烧水，节省时间#\n2. 将掰好的菜花放入烧开的水中，淖熟，再用凉水过几遍 。#\n3. 放入切好的黄瓜，盐，醋，味精，葱花备用#\n4. 烧热油锅，放入花椒，干辣椒爆香#\n5. 趁热倒入配好的菜上。调班均匀即可。当当当当~清新爽口的炝菜花出炉了#'),(908,'花菜回锅肉','荤菜','辣椒#\n姜#\n蒜#\n辣椒酱#\n花椒#\n蒜子#','#\n#\n#\n#\n#\n#','1. 先将花菜切成小块放入盐水浸泡#\n2. 将五花肉和各种配料切好放在一旁备用#\n3. 油入锅中烧热、小火放入五花肉炸至微卷、放入豆辨翻炒出香再放入蒜、姜、花椒#\n4. 最后加入花菜翻炒再加入盐味精适量！记得盐稍微一点点就可以了哦！#\n5. 现在一盘美味下饭的菜肴出锅啦！#'),(909,'酥肉','荤菜','五花肉和眉条肉#\n盐#\n胡椒粉#\n生粉#\n小麦面粉#\n鸡蛋#\n花椒#','各一长小条#\n不超过3小勺#\n一点#\n一勺左右#\n3勺左右#\n4个#\n大把#','1. 把花椒碾成粉状，把生粉面粉和花椒粉胡椒粉还有盐鸡蛋都加入搅拌，等候20分钟！#\n2. 放入油锅炸7-8分钟左右，捞起后复炸3分钟左右至金黄色即可#\n3. 待冷却后可放入冰箱冷冻起来，随吃随取！#'),(910,'冬瓜烧肉','荤菜','五花肉#\n冬瓜#\n红辣椒#\n葱姜蒜#','200g#\n200g#\n100g#\n各5g#','1. 将各种主料配料切好准备好#\n2. 把五花肉中的肥肉先下锅，炸到出油，然后放进瘦肉个姜蒜#\n3. 放酱油烧至肉七分熟#\n4. 将冬瓜和辣椒放进入一起翻炒#\n5. 炒至冬瓜透明，辣椒熟#\n6. ok#'),(911,'清蒸武昌鱼','荤菜','武昌鱼#\n蒸鱼豉油#\n葱丝，姜丝#','#\n3勺#\n二份备用#','1. 鱼洗净用刀划花，倒入料酒，鱼的表面抹盐，腌制15分钟！#\n2. 葱姜丝码好，放入蒸锅，大火蒸十分钟，关火闷5分，起锅，倒出盘中的水份，取出蒸鱼时的葱姜#\n3. 用准备好的另一份葱姜完美码盘，放入豉油，锅烧热（放花椒）热油淋到鱼上即可#'),(912,'韩式土豆排骨汤','汤','汤骨#\n土豆#\n大蒜#\n青椒#\n老豆腐#','1000g#\n4只#\n一个#\n1只#\n1盒#','1. 大块排骨焯水后用温水冲洗干净，放入滚水中火炖1.5小时，放入去皮的土豆块。#\n2. 大蒜瓣切细末，韩国大酱2份和，辣椒酱1份，辣椒粉一份，加一勺汤，少许生抽，糖调匀，倒入汤中再炖1个小时，盐调味汤就好了。#\n3. 吃的时候，放吃的量到石锅中，加上豆腐，辣椒圈略煮就能吃啦，配饭香香暖暖的。#'),(913,'空气炸锅试用之三：酥炸排条#九阳烘焙剧场#','荤菜','里脊肉#\n料酒#\n豆果菁选酱油#\n胡椒粉#\n香辣酱#\n盐#\n鸡蛋#\n淀粉#','200g#\n10ml#\n10ml#\n3g#\n5g#\n5g#\n1个#\n30g#','1. 里脊肉切成手指粗细长短的条状。#\n2. 加入除淀粉外所有调料，抓匀，腌制半小时以上。#\n3. 加入淀粉抓匀。#\n4. 空气炸锅180度预热5分钟。将排条一根根夹入炸锅内，180度炸5分钟。#\n5. 取出炸蓝，翻匀排条，再炸8分钟即可。#\n6. 开吃！#'),(914,'椒盐平菇','素菜','平菇#\n鸡蛋#\n淀粉或面粉#\n椒盐#','#\n1个#\n少许#\n少许#','1. 面粉和鸡蛋 准备好#\n2. 蛋打进去 搅匀#\n3. 平菇用热水炒好 挤出水分待用#\n4. 把这俩混合 我这次面粉加少了 所以比较稀#\n5. 热锅 加油 小火 油热了就可以把平菇一点点放进去油炸 不要一下子全放进去#\n6. 全部炸好后 撒椒盐#'),(916,'春笋炒五花肉','荤菜','盐#\n油#\n大喜大牛肉粉#\n料酒#','适量#\n适量#\n1勺#\n适量#','1. 准备一个春笋，我们这边菜市场不会卖半个的，所以买了一个，中间部分用来炒五花肉，尖尖部分用来焖排骨，头部分切丁当炒酸菜；#\n2. 去壳，取中间部分切片，水烧开，放一点盐开水焯一下苦味；#\n3. 捞出洌干水；#\n4. 五花肉切片，加入大喜大牛肉粉，油、盐、酱油一起腌制十分钟；#\n5. 如果爆炒，五花肉；#\n6. 加入洌干水的春笋片；#\n7. 加入盐、酱油，适量开水，中火焖三分钟；#\n8. 收汁即可，出锅；#'),(918,'清炒小白菜','素菜','鸡精#\n葱#\n大蒜#\n盐#','少量#\n一节#\n两粒#\n一勺#','1. 先把葱蒜切好，少量#\n2. 放油，烧热后加入白菜#\n3. 翻炒两分钟以后，加入盐一勺，放入事先准备的葱蒜，翻炒两遍，加入鸡精，准备出锅#'),(919,'黄瓜炒虾仁','荤菜','黄瓜#\n虾#\n大蒜#\n耗油，料酒，鸡精，盐，生抽#\n红菜椒#','一根#\n适量#\n一瓣#\n少许#\n半个#','1. 黄瓜洗净，切块，红菜椒切块#\n2. 虾去头和壳，虾线，剥好备用，大蒜切丝备用#\n3. 起锅热油，放入蒜丝爆香，加入虾仁翻炒，加入少许料酒，耗油，继续翻炒#\n4. 加入黄瓜，红菜椒，滴几滴生抽上色，翻炒一下，加入盐，鸡精，即可出锅装盘#'),(920,'酸菜鱼片汤','荤菜','鱼片#\n酸菜#\n粉丝#\n姜片#\n蒜片#\n泡红椒#\n葱花#','100g#\n200g#\n50g#\n适量#\n适量#\n适量#\n适量#','1. 鱼片切好码味，加上盐，胡椒粉，香油，淀粉拌匀。粉丝泡软。其他作料备好。#\n2. 锅内少许油，七成热后下姜片，蒜片爆香，再加入酸菜和泡红椒炒出香味加水盖盖煮至水沸。#\n3. 水沸后放入鱼片及粉丝煮约10分钟，加入适量盐即可，出锅并撒上葱花。#'),(921,'【家常小炒】青椒炒肉','荤菜','里脊肉#\n青椒#\n姜#\n盐、鸡精、十三香、生抽、淀粉、料酒和酱油#','适量#\n3个#\n适量#\n适量#','1. 青椒洗净切丝备用。#\n2. 里脊肉洗净切丝备用。（粗细因个人喜好而定）#\n3. 姜削皮洗净切碎备用。#\n4. 将姜、里脊肉、料酒、生抽、淀粉和清水进行搅拌腌制10分钟备用。#\n5. 起锅放油烧热备用。#\n6. 加入青椒和腌制好的肉丝一起翻炒至肉变白。#\n7. 再陆续加入鸡精、十三香、盐和酱油进行翻炒。#\n8. 最后翻炒均匀，出锅装盘即可。#'),(922,'蚝油水豆腐---家常豆腐做法','荤菜','水豆腐#\n蚝油#\n茶树菇老抽#\n火麻油#\n盐#','一块#\n30ml#\n五滴#\n半汤勺#\n半勺#','1. 准备水豆腐一块，也叫嫩豆腐，一块。#\n2. 将豆腐切成六片，然后每片切成四块。#\n3. 倒入半汤勺的亦舒堂火麻油，调至中火，然后将豆腐放下去，中小火慢慢煎豆腐。#\n4. 倒入蚝油30ml、盐半勺和放一点老抽来调色，注意掌握火候，煎至豆腐两面金黄即可。#\n5. 出锅~拍照~开动~#'),(923,'香干榨菜毛豆炒肉丝','荤菜','红椒#\n葱，油，盐，生抽，鸡精#','1个#\n适量#','1. 瘦肉切丝，香干切条，榨菜切丝用清水泡一下，红椒切丝，毛豆米洗净，葱切花。#\n2. 炒锅烧热倒油放入肉丝炒散后倒点生抽，加点糖，胡椒粉翻炒二分钟后盛出肉丝备用。#\n3. 锅里再倒油热后放入葱花爆香放入毛豆米煸炒二分钟，下入红椒丝，香干，榨菜丝翻炒二三分钟后放入炒好的肉丝一起翻炒，加点盐，鸡精再炒几下就可以装盘啦！#'),(924,'喵妈秘制烤鸡','荤菜','全鸡#\n土豆#\n西兰花#\n洋葱#\n大蒜#\n海盐#\n黑胡椒#\n百里香#\n蜂蜜#\n橄榄油#','一只#\n两个#\n一个#\n一个#\n一头#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 1. 全鸡抹海盐 百里香 黑胡椒搁置一会柠檬多扎几个洞塞进鸡肚子里#\n2. 2. 土豆 洋葱 西兰花切块大蒜最好用新蒜 不用剥皮 浇橄榄油或者色拉油和海盐黑胡椒拌匀垫在鸡下面烤盘先用锡箔纸包好哦#\n3. 3. 入烤箱150度一个小时期间要是不是去看看鸡表皮涂蜂蜜 记得翻面下面的蔬菜要记得翻一下#\n4. 4. 等到熟了以后就可以撕块吃了个人觉得烤鸡一定要用撕的·这样才不会断掉鸡肉的纤维破坏口感吃的时候可以将肚子里的柠檬拿出来挤出汁水淋在鸡肉块上#\n5. 完美合照！！！#'),(925,'土豆炒咸蛋','荤菜','土豆#\n咸蛋#\n红辣椒#\n植物油#','2个#\n2个#\n1个#\n50ml左右#','1. 两土豆去皮，洗干净#\n2. 对半切开，入蒸锅蒸20~30分钟，筷子可以插入便可#\n3. 蒸好的土豆切成小丁#\n4. 咸蛋也切成小丁#\n5. 红辣椒切丝，我准备了一个，这里只用了半个，看个人喜欢哈，这个辣椒不辣哟#\n6. 锅内放油，烧至7.8成熟#\n7. 放入辣椒翻炒#\n8. 放入土豆一起翻炒#\n9. 接着放入咸蛋，炒2～3分钟，闻到咸蛋香味即可出锅，不需放盐哦#\n10. 装盘～一道简单好吃的下饭菜ok了#'),(927,'牛奶炖蛋','甜品','鸡蛋#\n牛奶#','1只#\n1碗#','1. 1?：1只鸡蛋，1碗牛奶，加入少量白糖，一起打散，打起有泡泡，用匙去掉泡泡先可以蒸出图片中这么滑。2?：用保鲜膜或东西盖住才可以放进锅里蒸。       3?：把水先烧滚再放进去大火蒸10分钟，关火不要打开锅盖，5分钟后才打开。超简单…#'),(928,'超级简单香辣鸡胗','荤菜','鸡胗#\n美人椒#\n干辣椒#\n花椒#\n剁椒#\n食用油#\n大葱#\n生抽#\n老抽#\n冰糖#','500g#\n3个#\n3个#\n十几粒#\n适量#\n适量#\n一段#\n适量#\n适量#\n3颗#','1. 材料准备好，鸡胗泡半个小时左右放血，然后沥干，热锅烧油，放入鸡胗，干辣椒，美人椒，花椒，剁椒，翻炒一会儿，再倒生抽老抽，加冰糖和葱花#\n2. 加水，翻炒15分钟左右，大火收汁盛出～可以吃啦#'),(929,'四季豆末炒叉烧肉丁','荤菜','四季豆#\n叉烧肉#\n李锦记蚝油#\n李锦记生抽#\n糖#\n葱末#\n色拉油#','250g#\n10片#\n1大勺#\n1小勺#\n少许#\n适量#\n适量#','1. 热锅起油，油热后将葱放入锅内，翻炒至出香味。#\n2. 再加入切成丁的叉烧肉继续翻炒出肉香味。#\n3. 然后再加入切成末的四季豆继续翻炒。#\n4. 四季豆炒半熟时加入适量的李锦记蚝油调味。#\n5. 炒匀后再加入适量的李锦记生抽调色。#\n6. 再加入一小碗水继续煮熟。#\n7. 收干汁水后就可以装盘了。#'),(930,'泡菜汤','汤','五花肉#\n小葱#\n洋葱#\n泡菜#\n豆腐#\n豆芽#\n白萝卜#\n韩式辣酱#','一些#\n适量#\n#\n#\n#\n#\n#\n一汤匙#','1. 准备食材#\n2. 炒五花肉至熟。#\n3. 加洋葱继续炒。#\n4. 加泡菜炒。#\n5. 加水。大火煮开。#\n6. 放土豆，豆芽，豆腐，加辣酱。再次煮开，之后转小火煮20分钟左右。#'),(931,'豆酱藕丁','素菜','莲藕#\n豆酱#\n葱花#','适量#\n适量#\n适量#','1. 一小节莲藕#\n2. 切丁#\n3. 热油后放入两小勺豆瓣酱#\n4. 放入藕丁#\n5. 藕丁熟后关火，撒入葱花（用余温热葱花）#\n6. 完成#\n7. 上菜#'),(932,'【简单又好吃】糖醋油条（简易版）','素菜','白糖#\n陈醋#\n蒜#\n剩油条#\n酱油#','适量（比陈醋多点）#\n适量#\n适量#\n1根（两条粘在一起的）#\n比陈醋多#','1. 将油条撕开，再撕成小块。#\n2. 酱料：将糖、陈醋、酱油以及切碎的蒜都倒在一个碗中，搅拌至糖融化即可。#\n3. 开小火，不用等锅热就直接把调好的酱料倒倒锅中，冒小泡了就把油条放进去，翻炒会，出锅即可！#\n4. 香喷喷！超好吃！酱油一定要比醋多，不然陈醋的味道很浓。#'),(933,'家常土豆泥','素菜','中型土豆#\n淡奶油#\n盐#\n黄油#\n黑胡椒#','4个#\n300g#\n少许#\n30g#\n少许#','1. 土豆去皮后洗干净#\n2. 土豆切块后入冷水煮（随意怎么切，只要切的相对均匀），加入一小勺盐。水沸后关中小火煮20分钟左右。#\n3. 这是煮好的土豆，把水倒出（太热，拍不清楚照片）#\n4. 接着再把它放入煮土豆的锅，置于小火上捣碎（保持热度），煮好的土豆非常容易捣成泥。#\n5. 加入淡奶，开中火调匀（淡奶可以多加一些）一开始有点稀，熬一会儿就好了。#\n6. 加入黄油，少许黑胡椒熬匀就可以关火了#\n7. 这是完成的土豆泥#\n8. 准备吃啦#\n9. 浇上面的是我前一天晚上做的牛肉汤，勾了芡淋上的#'),(934,'酸汤肥牛（简易）','荤菜','小米椒#\n尖椒#\n酱油#\n酸醋#\n盐#','#\n#\n#\n#\n#','1. 1、金针菇过一下水。捞起备用。2、牛肉最好也过一次。（我就是因为没有把牛肉过水所以一倒下去汤汁就很浑浊，大家可以尝试过一下水）3、姜蒜辣椒下油锅炒香后倒入高汤（我没高汤所以我是倒开水）水煮滚后放入酱油酸醋调汁。最后倒入牛肉金针菇一起焖煮即可。#'),(935,'蚝油香菇肉片','荤菜','香菇#\n猪肉#\n葱花#\n蚝油#','500g#\n50g#\n适量#\n适量#','1. 香菇切片，焯水后淋干备用。#\n2. 猪肉，切片备用。可用淀粉抓下。#\n3. 热锅，倒油，放入肉片炒变色，依次放葱花，香菇，翻炒。倒适量蚝油，继续翻炒，出锅！~~#'),(936,'香葱油爆茄子','素菜','茄子#\n大葱#\n大蒜籽#\n生抽#\n醋#\n盐#\n辣椒#\n油#','2根#\n少许#\n2瓣#\n少许#\n少许#\n适量#\n适量#\n大量#','1. 准备原材料：·茄子切成块状或者滚刀状·大蒜籽切成米粒状·大葱切细#\n2. 茄子过油·切记茄子不可先泡水·点火热锅，倒入大量植物油加热至翻滚·倒入备用的茄子#\n3. 沥油·轻微翻炒待茄子变软·将锅内茄子捞出，挤压出油#\n4. 爆香·将备用的大蒜籽和大葱放入沸油锅内·根据口味加入适量的生抽，醋，辣椒等。（喜欢粘稠酱汁的还可加入少许芡粉）·翻炒#\n5. 出锅·爆出香味后，再将滚过油的茄子倒入锅内一起翻炒。·根据咸淡加入适量食用盐·出锅，盛盘#'),(937,'香辣孜然烤鸡翅','荤菜','鸡翅#\n孜然粉#\n孜然#\n料酒#\n老抽#\n香辣粉#\n姜丝#\n橄榄油#\n干辣椒圈#','8只#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 解冻到室温的鸡翅洗净后划几道放入孜然粉、香辣粉、老抽、料酒、姜丝、干辣椒圈拌匀，盖保鲜膜放入冰箱过夜（比例按照喜好就行，吃口重的可以再适当加些盐）。#\n2. 烤盘铺锡纸，平放鸡翅，洒上孜然，喷点橄榄油。#\n3. 自家烤箱脾气急，预热180度，放中层正反面各6分钟就可以了。（翻身时再喷些橄榄油撒些孜然）。烤的时候香极了，凑近了还能听见热闹的滋滋声^_^#\n4. 香嫩美味～#'),(939,'葱爆银鱼干','荤菜','料酒#\n生抽#\n盐#\n辣椒粉#','少许#\n少许#\n#\n少许#','1. 银鱼干泡温水十五分钟捞出沥干水分。葱切丝备用。#\n2. 锅烧干，入油至5分热。倒入葱丝，辣椒粉，料酒煸中火炒出香味，加入银鱼，少许生抽喝盐，大火煸炒至银鱼透明焦香，起锅装盘。完成#'),(940,'葱油萝卜丝','素菜','白萝卜#\n葱#\n盐#\n白糖#\n鸡精#','半根#\n适量#\n适量#\n适量#\n适量#','1. 将萝卜洗净去皮切成细丝，也可以用刨丝器刨成丝。#\n2. 将萝卜丝用盐拌匀腌制2小时，滗去腌出的水分。#\n3. 锅里放入植物油，烧至5成热关火，放入葱花爆香#\n4. 将萝卜丝下葱油中拌匀，加入少许白糖、鸡精调味即可。#'),(941,'草鱼煮香菜','荤菜','草鱼#\n香菜#\n酱油，盐，酒#\n小红辣椒(最好腌制的)#\n姜，蒜#','一条#\n适量#\n少量#\n根据口味适量#\n数片，数粒#','1. 鱼切块，放酱油，盐，酒适量腌制半个小时左右#\n2. 洗干净适量香菜做备用(直接放碗底，鱼煮好后直接倒上面)#\n3. 四个左右小红辣椒，切碎。一块姜，切碎。三粒蒜左右，切碎。#\n4. 加水烧开(能盖过鱼即可)，烧开后把鱼放进去，加入姜和辣椒，至煮熟#\n5. 煮熟后，加适量菜籽油最好(如果没有，用其他油代替)，煮五分钟左右，加盐加蒜，再煮五分钟出锅#\n6. 出锅直接浇在香菜上，完成#'),(942,'茶香带鱼','荤菜','带鱼#\n红茶#\n生粉#\n生抽#\n白糖#\n盐#\n鸡精#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 带鱼事先切片，在红茶汤浸泡至少10分钟，捞出沥干水分，拍上一层生粉#\n2. 锅里油烧热，下入带鱼片油炸酥脆捞出#\n3. 另备一口锅，爆香葱姜蒜末，倒入茶汤，加入生抽，白糖，少量料酒煮开，加入煎好的带鱼烧制入味，最后出锅前加入点香菜碎和香葱末即可#'),(945,'盐焗大虾','荤菜','海虾#\n粗盐#\n盐#\n黄酒#\n葱#\n姜#','8只#\n800g两包#\n少许#\n少许#\n少许#\n少许#','1. 开背去除虾线，放入葱姜黄酒腌制一会儿#\n2. 倒入粗盐和花椒翻炒十分钟左右，放入虾，盖上盖子等个一两分钟然后翻面，然后就出锅。#\n3. 嫩点的好吃！#'),(947,'利仁电饼铛试用之--外焦里嫩烤鸡翅（10分钟菜谱）','荤菜','鸡中翅#\n椒盐#\n生抽#\n食用油#','12个#\n2小勺#\n2小勺#\n适量#','1. 电饼铛#\n2. 功能蛮强大的！#\n3. 鸡中翅正反面划上两刀、加入小量油、椒盐粉、生抽腌制3小时以上（放冰箱保鲜）#\n4. 电饼铛预热，预热完后刷上小量油、摆上鸡翅刷上一层油。选择烤鸡翅功能。盖上上盖。#\n5. 大概7分钟便熟啦！表皮焦脆！#\n6. 不用10分钟就完成啦！超方便！而且外焦里嫩！#\n7. 这是外壳照片！#'),(949,'茄子“开屏”--清蒸','素菜','茄子#\n辣椒#\n胡萝卜#\n调料酱#','#\n#\n#\n#','1. 把茄子 胡萝卜切斜片 均匀的擦少许盐 摆盘#\n2. 放蒸锅，冷水上锅 大火烧开#\n3. 烧开后 ，揭盖淋入蚝油和生抽拌成的酱汁（注意不要太咸）#\n4. 蒸锅转中小火继续蒸，另起锅炒香姜蒜 花椒#\n5. 后加入红绿剁椒#\n6. 将炒好的调料淋入茄子上，同时放少许枸杞点缀（注意别被蒸汽烫着）#\n7. 关火前淋一点蒸豆鼓油 香油 葱苗，最后关火闷3分钟后，出锅！ 开始享用吧！#'),(950,'猪肝排骨粥','主食','猪肝#\n肋排#\n泰国香米#\n油#\n椒味盐#','70g#\n400g#\n60g#\n适量#\n适量#','1. 食材：猪肝、肋排和泰国香米。#\n2. 将肋排浸泡去血水。#\n3. 将猪肝浸泡2小时左右，期间不间断更换清水。#\n4. 将肋排煮汤一下。#\n5. 泰国香米洗净，放入砂锅中，一次性加足适量的清水。#\n6. 放入肋排。#\n7. 盖锅盖，大火烧开。#\n8. 用筷子隔放锅盖，以防溢出。#\n9. 煮至米粒粘稠，放入猪肝，继续煮10分钟。#\n10. 倒入适量的菜籽油。#\n11. 撒入适量的味椒盐，拌匀。#\n12. 即可关火。#'),(951,'千叶豆腐','素菜','千叶豆腐#\n豆瓣酱#\n洋葱#\n蒜苗#\n青椒#\n椒盐#\n白糖#','一盒呗#\n一勺呗 牛肉酱也可以呗#\n想要多少加多少呗#\n随便呗#\n一个呗#\n一点点呗#\n一小把呗#','1. 就是豆腐煎咯 煎煎黄 没图 大热天我才不拍#\n2. 然后豆腐拿出来咯 剩下的油么 你放勺酱 牛肉酱 豆瓣酱随便咯 要辣的放辣的不要辣放豆瓣咯 炒一炒不就炒开了嘛#\n3. 乱七八糟配料一起下去炒咯 然后豆腐加进去炒咯#\n4. 好了么加点开水 一点点咯 记住一点点！ 再加白糖呀#\n5. 然后么好了呀 撒点椒盐翻翻么出锅了#'),(952,'懒人版麻辣香锅','荤菜','土豆#\n彩椒#\n大葱#\n豆瓣酱#\n火锅料底#','2个#\n#\n#\n#\n#','1. 将鱼丸煮熟 葱切段 土豆和甘蓝切好 （甘蓝我是手撕滴）#\n2. 锅里到油量比平时炒菜多点，等油热一点就把豆瓣酱和火锅料底放里#\n3. 把葱段和彩椒放锅里爆锅#\n4. 我怕土豆片切厚不爱熟先放里的 抄的差不多把其余的材料统统放里就Ok拉#'),(953,'反沙番薯','素菜','番薯#\n白砂糖#\n植物油#','#\n#\n#','1. 番薯去皮，切长条#\n2. 入油锅，炸至熟透，装盘。将油盛起，下次做菜的时候还可以用。#\n3. 加入白糖和水，水能湿润白糖即可，开始炒糖浆啦，小火慢炒，炒至出现浓密泡泡粘稠状就ok啦，需要耐心哦#\n4. 差不多这样子糖浆就炒好了！倒入炸熟的番薯，翻炒一会儿就反沙啦！#\n5. 装盘啦哈哈，好好吃，自己做的又卫生又好吃～#'),(954,'葱油白萝卜丝','素菜','白萝卜#\n葱#\n食用油#\n盐#\n鸡精#','#\n#\n#\n#\n#','1. 白萝卜洗净去皮，切成细丝，在开水中焯一下，放凉备用。#\n2. 葱切成碎未，放在白萝卜丝上。#\n3. 小勺内放一勺食用油在火上加热，然后将热油浇在葱碎和白萝卜上将葱烫熟，加入盐，鸡精拌匀即可。#'),(956,'地三鲜（非油炸）','素菜','茄子#\n灯笼椒#\n土豆#','2条#\n1个#\n1个#','1. 茄子切滚刀块后泡水里灯笼椒去核切块土豆去皮切片锅放油（油稍为的多一点），热后放入沥干水的土豆、茄子，炒一会，直接盖上盖子，焖一分钟再翻一下，再焖一下，过程保持中火，直至土豆茄子熟（因为茄子泡过水，加上油，这烧的过程我是完全没有放水的，如果你们觉得太干可以酒上一点水）然后放入青椒，开大火炒一分钟后倒入调料水（盐，白糖，蚝油，酱油，水，生粉）放入葱段翻炒几下，出锅！#'),(958,'包包菜炒粉丝。','素菜','粉丝#\n盐#\n老抽#\n蒜#\n葱#\n辣椒#','适量#\n#\n#\n#\n#\n#','1. 提前将粉丝在开水里泡10-20分钟。（我用的是藕粉，几分钟就可以了，）#\n2. 包包菜切粗条。肉切丁既可。蒜切碎。葱切厂段。辣椒不要切的太碎#\n3. 锅内放油。烧热。放蒜。等有香味放肉入锅。等到肉差不多要熟了，放包包菜，炒一下下，放粉丝。在小火炒，放点点水（粉丝很容易粘锅），在放老抽上色，#\n4. 等到水快没了，就放盐，鸡精。起锅前放葱段。#'),(960,'橄榄菜拌莴笋','素菜','莴笋#\n青豆#\n甜玉米粒#\n油#\n盐#\n橄榄菜#\n葱#\n鸡精#','一根#\n30克#\n50克#\n适量#\n适量#\n80克#\n少许#\n少许#','1. 准备一根莴笋洗净，买的时候让店家去皮；#\n2. 切成丝，不要太细；#\n3. 准备齐全的所有材料；#\n4. 莴笋入开水锅中焯水，#\n5. 捞出入大碗里；#\n6. 青豆焯水；#\n7. 炒锅入油，放入葱花炒出香味，放入焯水后的青豆和甜玉米粒翻炒；#\n8. 青豆、玉米粒都是熟的，稍微翻炒即可，放入橄榄菜翻炒均匀，#\n9. 放少许的盐、鸡精炒匀；#\n10. 把炒匀的蔬菜放到莴笋丝上面，像意面一样；#\n11.#'),(961,'清炒蒜香蚕豆','素菜','蚕豆， 新鲜#\n蒜苗粒#\n油盐糖#','400g#\n2-3根#\n适量#','1. 剥掉大衣的蚕豆， 多新鲜啊！#\n2. 起油锅烧热油， 倒入蚕豆翻炒， 加水焖烧8-10分钟左右， 放盐少许糖， 撒入蒜苗粒， 清香的蚕豆出锅装盘了！#'),(963,'锅焖土豆回锅肉','荤菜','蒜蓉#\n葱花#\n八角#\n生抽#\n咖喱粉#\n老抽#','三瓣#\n少许#\n少许#\n适量#\n少许#\n适量#','1. 先把五花肉洗净下锅内煮熟捞起切片备用  土豆削皮切块备用  锅里放入油锅热后下入蒜蓉  八角  煸炒出香味在下入肉片煸出多余的油，，待油出得差不多时放入土豆  咖喱粉一起翻炒至土豆色泽晶亮#\n2. 乘出放入砂锅内用大火煮开后转小火慢炖加入生抽  老抽一起中间翻2  3次以免粘锅底。等土豆可以又筷子一戳就烂的时候便可以撒上葱花开吃咯#'),(966,'酸辣土豆丝','素菜','土豆#\n青椒红椒#\n干红椒#\n花椒#\n大葱#\n大蒜#\n盐#\n耗油#\n生抽#\n鸡精#\n白醋#','2个#\n各一个#\n少许#\n少许#\n少许#\n4瓣#\n#\n#\n#\n#\n#','1. 全部食材清洗干净#\n2. 土豆切丝，辣椒切丝，干红椒掰断，大葱切片，蒜切片#\n3. 油热后下入葱蒜干红椒花椒，爆香后下入青椒红椒#\n4. 下入土豆丝翻炒片刻，加入盐继续翻炒#\n5. 加入耗油，生抽，鸡精翻炒，起锅前加入两汤匙白醋#\n6. 出锅啦，酸酸辣辣的超级下饭菜#'),(967,'三鲜蛋卷','主食','鸡蛋#\n烤肠#\n黄瓜#\n红萝卜#\n豆瓣酱#','2个#\n1个#\n1块#\n1块#\n少许#','1. 准备食材！#\n2. 红萝卜、黄瓜、烤肠切丝，鸡蛋打散，我只用了两个鸡蛋，想吃嫩鸡蛋的话可稍微加点水。#\n3. 热锅放油，倒入鸡蛋，不要翻炒，成饼后，我在上面撒了点黑芝麻，没有的话可忽略。大家尽量用平底锅吧！#\n4. 完整的蛋皮#\n5. 先摸豆瓣酱，放上切好的三丝，卷起来即可。#\n6. 卷好后#\n7. 做好了！喜欢酸酸甜甜的话可放点番茄酱沙拉酱！#'),(968,'豆芽干豆腐丝炒韭菜','素菜','韭菜#','适量#','1. 绿豆芽一盘#\n2. 干豆腐丝三分之一盘#\n3. 韭菜#\n4. 韭菜切段备用#\n5. 葱花，蒜沫#\n6. 锅内放油烧热(也可放入些肉丝风味更好)放入葱花蒜沫爆香，再放入豆芽和干豆腐丝大火爆炒大约一分钟，再放入韭菜。放入调料:盐，十三香，继续大火爆炒，出锅前放入鸡粉或味精即可。#'),(969,'醪糟（米酒）卧蛋','甜品','醪糟(米酒）#\n鸡蛋#\n红糖#\n水#\n桂花#\n枸杞#','20g#\n1个#\n20g#\n1大碗#\n3g#\n3g#','1. 喝多少水就加多少水，水煮开后打入鸡蛋不要打散，鸡蛋快煮熟时加入醪糟、桂花、枸杞、红糖，煮开3到5分钟即可。#\n2. 成品#'),(971,'辣椒炒肉','荤菜','大辣椒#\n猪肉#\n蒜粒#\n海鲜酱油#\n盐#','#\n#\n#\n#\n#','1. 这个在东北我们叫大辣椒 是一种不辣的辣椒 跟那种红黄色的彩椒差不多 是绿色的 把籽拿出来 用手掰成块#\n2. 猪肉切片 蒜切粒#\n3. 锅内放油 油热后用蒜爆香 放入肉 少加一点海鲜酱油#\n4. 肉翻炒变色后 放入辣椒 孕妇说想吃软一点的 就多炒了一会 快熟是加盐#\n5. 出锅前放点蒜粒 炒的时间长 所以颜色有点深 不过味道很好#'),(972,'卤牛腱子肉','荤菜','牛腱子肉#\n调味料：料酒，生姜，八角，花椒，豆蔻，桂皮，香叶，山奈#','1000#\n适量#','1. 牛腱子肉，洗净#\n2. 卤水制作：把调味料放入清水中，加盐，糖，老抽。大火烧开。#\n3. 卤水烧开加入牛腱子肉加料酒大火烧10分钟，转小火煮1小时，至肉烂捞出#\n4. 切片装盘。#'),(973,'白果猪肚汤','汤','白果#\n猪肚#\n黑胡椒#\n鸡粉#\n清水#','150g#\n380g#\n适量#\n适量#\n适量#','1. 食材：处理好的猪肚和白果。#\n2. 将猪肚和白果放入煮锅中，倒入适量的清水。#\n3. 倒入适量的黑胡椒粉。#\n4. 盖锅盖，大火煮滚，再煮5分钟，关火。#\n5. 整锅倒入电炖锅中。#\n6. 盖锅盖，通电。#\n7. 炖1小时左右，揭盖。#\n8. 加入适量的鸡粉，拌匀。#\n9. 即可断电。#'),(974,'秋葵炒蛋','荤菜','秋葵#\n鸡蛋#\n盐#\n黄酒#','4-5个#\n3个#\n适量#\n适量#','1. 秋葵洗干净切片#\n2. 鸡蛋加黄酒、盐进行搅拌均匀#\n3. 将切片秋葵放在鸡蛋汤里，油锅热了下锅翻炒，蛋花开始凝结时加少许盐，味精#\n4. 装盘，开吃。#'),(975,'炒年糕','素菜','蟹肉棒#\n圆白菜#\n芝士年糕#\n韩式辣酱#','#\n#\n#\n#','1. 蟹肉棒圆白菜备用#\n2. 刚从冷冻柜里拿出来的先焯软#\n3. 倒油把圆白菜先炒熟在倒入年糕翻炒#\n4. 加辣酱在倒入半碗水开始慢慢煮#\n5. 差不多汤汁稠稠的时候放入蟹肉棒 太早放会全碎掉 感觉差不多就可以起锅啦#\n6. 铛铛铛铛 一切凭感觉#'),(976,'奥尔良鸡翅(烤箱)','荤菜','鸡翅#\n奥尔良调料#\n盐#\n食用油#','#\n#\n#\n#','1. 把鸡翅切花刀。放一点盐和奥尔良调料腌制一天。#\n2. 腌制时放入冰箱。(套上保鲜膜)#\n3. 鸡翅抹上油，烤箱调成上档，230度，10分钟之后反面再考10分钟。#'),(977,'奶油蘑菇汤（不用炒）','汤','牛奶#\n口蘑#\n黄油#\n芝士片#\n鸡汁#\n黑胡椒#\n迷迭香#\n香蒜碎（可不加）#','500ml#\n10个#\n20g#\n2片#\n适量#\n适量#\n适量#\n适量#','1. 牛奶和口蘑一起倒入锅中，小火炖（千万不要煮开）#\n2. 看到牛奶稍微冒泡时加入黄油，此时可把火开大一点，但是整个制作过程都不要让牛奶沸腾#\n3. 用筷子稍作搅拌，融化黄油，把芝士片撕成小块，放入牛奶中融化#\n4. 黄油芝士都融化后加入鸡汁，黑胡椒，香蒜碎，如果想要浓稠一点就加入少许淀粉#\n5. 最后倒一点迷迭香#\n6. 完成！#'),(978,'蒜苔炒香肠','荤菜','蒜苔#\n香肠#\n盐#\n白胡椒#\n鸡精#','300g#\n一根#\n适量#\n适量#\n适量#','1. 把香肠洗干净放在锅里蒸个两三分钟～这样炒出来的香肠不硬，在蒸的同时把蒜苔洗干净控水！#\n2. 把锅烧热～倒入油～把油烧热倒入蒜苔翻炒～加入盐和白胡椒继续翻炒！#\n3. 蒜苔不容易进味道，要炒的久一点，香肠蒸好以后切成片，倒入香肠翻炒，（如果想吃的更软点加点水即可）加入鸡精出锅！！！#\n4. 儿子在偷吃！！#'),(979,'肚包鸡','荤菜','猪肚#\n仔鸡#\n白胡椒粒#\n水发黄豆#\n八角#\n小茴香#\n绍酒#\n盐#\n葱#\n姜#\n蒜#\n绍酒#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 把猪肚和仔鸡清洗干净后，猪肚用凉水下锅开火焯水去异味。#\n2. 仔鸡也凉水下锅开火，焯水捞出待用。#\n3. 鸡脚切断在鸡内放入葱段、姜片、八角、小茴香和水发黄豆，猪肚肉搓上少些盐，放些白胡椒粒，把仔鸡装入猪肚里面，最后用针线封口。#\n4. 沙锅中放白胡椒粒，猪肚包鸡下锅，水开后下葱、姜、蒜、绍酒，文火煲两个小时左右。最后放入些许红椒块提色，加盐调味中间需翻动猪肚包鸡（一受热均匀，二防粘沙锅底）。约1.5小时煲好。#'),(980,'开洋煮千张','荤菜','香菇#\n虾#\n花生油#\n面粉#\n姜末#\n料酒#\n胡椒粉#','#\n#\n#\n#\n#\n#\n#','1. 千张切丝，下锅用开水焯一下，可以去掉豆腥味#\n2. 香菇切丝，焯水，虾干略微用水泡泡#\n3. 炒锅置火上，放入一勺花生油和一小勺面粉，用小火慢炒，待油和面泛起大泡，再度变成均匀的小泡时，迅速冲入高汤用旺火烧沸，待汤成乳白色时，下入千张丝，香菇丝，虾干，姜末，料酒，煮到所有原料的味道都融入汤内。最后爱吃辣的可以撒些胡椒粉#'),(981,'金枪鱼蔬菜卷','荤菜','豆腐皮#\n金枪鱼罐头#\n胡萝卜#\n香菜#\n鸡蛋#\n盐#\n沙拉酱#','1张#\n适量#\n适量#\n适量#\n1个#\n少许#\n少许#','1. 原料图#\n2. 香菜洗净，胡萝卜洗净切细丝，鸡蛋加少许盐摊成鸡蛋饼然后再切成细条待用。#\n3. 在豆腐皮的一端依次码上鸡蛋皮，胡萝卜丝，香菜和金枪鱼肉，卷起来后在另外一端涂少许沙拉酱粘合，然后切小段即可。#\n4. 摆盘，是不是很简单捏～#'),(982,'蒜苗炒绿豆芽','素菜','蒜苗#\n豆芽#\n肉#\n油#\n盐#\n生抽#\n陈醋#\n十三香#\n鸡精#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 油热后放入葱花，然后放肉，炒变色后，放入豆芽，炒的快要去生了，放入蒜苗，然后加入其他调料，醋最后放，少放一点很好吃。不要太多～～出锅#'),(983,'香芋地瓜丸','甜品','红薯#\n面粉#\n糯米粉#\n油#\n糖#','两个#\n50g#\n50g#\n适量#\n两勺#','1. 先把红薯切开成片（快熟）蒸熟#\n2. 把红薯碾压成泥，加入糖，糯米粉，面粉搅拌均匀，和成面团#\n3. 开火油热至八成熟，把和好的面团滚成小圆球放入锅中炸#\n4. 炸至金黄即可捞出#\n5. 甜甜哒地瓜丸就完成了#'),(984,'奥尔良鸡翅','荤菜','鸡翅#\n奥尔良烤鸡翅粉#\n蜂蜜#','10个#\n1包#\n1勺#','1. 鸡翅洗干净以后划两刀，放冷水锅里去腥，水开后捞出用热水洗净！这包料用冰水或者冷水泡开（千万不能多放水，不然没有味道了）把洗好的鸡翅腌进去拿保鲜膜盖住！放入冰箱一晚上#\n2. 把鸡翅放入烤架，烧烤或220度烤制15分钟，反面15分钟！然后摸一层蜂蜜上色，还是原来的温度，正反5分钟！早摸蜂蜜容易焦。#\n3. 或者也可以选择空气炸锅200度一样的操作！个人感觉空气炸锅火力更旺。要时刻关注。#\n4. 空气炸锅成品#\n5. 烤箱成品#\n6. 后来烤过一次鸡翅根。感觉不如鸡翅入味。#'),(985,'【私房凉拌秋木耳】','素菜','秋木耳#\n洋葱#\n香芹菜#\n香菜#\n香辣香菇肉沫酱（辣椒酱#\n香辣香菇肉沫酱是我自制的#\n白糖#\n陈醋#\n生抽#\n鸡粉#\n木姜子油（或麻油或不放#','15g#\n半个#\n3瓣#\n2棵#\n2大勺#\n有谱#\n3-4味勺#\n15g#\n5g#\n2g#\n10g#','1. 木耳提前洗净后浸泡，最好隔夜泡，次日吃。将木耳去蒂掰成小块，洋葱切成三角小块，香芹菜、香菜切5cm小段待用#\n2. 木耳焯水，煮开即捞出滤干水#\n3. 将4种材料放入大碗中，加入各种调味品拌匀#\n4. 拌匀后试味稍等5分钟装盘，洋葱会没辣么生辣，吃用生洋葱好处很多喔！#\n5. 成品图#\n6. 成品近照#\n7. 尝一口，香辣酸爽.....#'),(986,'酸菜鱼','荤菜','草鱼#\n南方酸菜#','一条#\n一袋#','1. 我做的很简单,鱼剔骨,肉切片0.5厚,鱼肉腌制15分钟#\n2. B红干椒,姜,蒜蓉,葱花,爆香,备用（小料）。C接着把酸菜切丝煸炒,然后盛出备用。D鱼骨放小料,炒出香味加料酒,酱油,加水烧开。E另起锅水烧开,把腌制的鱼滑熟,放入酸菜汤内#\n3. 鱼骨酸菜汤#'),(987,'麻辣牛肉','荤菜','牛肉#\n芝麻#\n姜片#\n香叶#\n八角#\n淀粉#\n辣椒面#\n花椒面#\n料酒#\n胡椒粉#\n调和油#\n红糖#\n盐#\n葱#\n干辣椒#','500g#\n30g#\n5片#\n5片#\n4颗#\n30g#\n3勺#\n2勺#\n20ml#\n5g#\n200ml#\n30g#\n少许#\n2条#\n5个#','1. 将牛肉切成条状，放入清水浸泡十分钟，去血#\n2. 将八角、干辣椒、姜片、料酒、葱花放入水中，待水烧开加入牛肉煮十分钟#\n3. 二十分钟后捞出牛肉沥干，加入少许料酒，胡椒粉，少许盐，淀粉码味#\n4. 将码味二十分钟后的牛肉条放入油锅中炸至金黄#\n5. 将牛肉捞出沥干，留50毫升油在锅中，加入红糖不停搅拌至起泡，放入牛肉拌匀，加入辣椒面、花椒面、芝麻、拌匀#\n6. 麻辣咸淡根据自己的口味调整，咸了加糖，颜色暗淡加辣椒面，调到自己喜欢的口味就可以起锅啦#'),(988,'鲫鱼汤','汤','鲫鱼#\n葱#\n姜#\n枸杞#\n白胡椒粉#\n盐#\n白萝卜#','两条#\n适量#\n适量#\n#\n#\n#\n#','1. 一.  鲫鱼洗净   去腮  去内脏  去里膜   备用二.  热锅放油，将鱼煎至两面微黄三.  萝卜切片备用   注意不要切太薄四.  葱切小段   姜切片  蒜苗切丝备用五.  鱼煎至两面微黄后加入冷水  葱 姜至水沸腾  加入萝卜片   调至微火慢熬30min    六.  慢熬过程中加入白胡椒面  盐  枸杞  七.  盛出   撒上蒜苗丝  完成#'),(989,'酱牛肉','荤菜','牛腱子#\n李锦记卤水汁#\n甜面酱#\n老抽#\n生抽#\n香叶#\n大料#\n冰糖#','2斤#\n200ml#\n50g#\n30ml#\n100ml#\n4片#\n1个#\n20g#','1. 开水抄牛腱，重新烧水加料酒小火炖制1小时#\n2. 单起一只锅，放入牛腱，加入炖牛腱的汤（没过牛肉的三分之二）和所有调料，中火酱半个小时#\n3. 晾凉后将牛腱连酱汤一起装盒，放在冰箱酱两天待其入味#'),(990,'西兰花炒虾仁','荤菜','橄榄油#\n料酒#\n胡椒粉#\n盐#\n鸡精#\n蚝油#','#\n#\n#\n#\n#\n#','1. 西兰花焯水，点两滴油，丁点盐，保持菜品翠绿#\n2. 虾焯水放两滴料酒去腥#\n3. 油开后放西兰花稍炒，依次放胡椒粉，蚝油，盐，鸡精，再放虾仁，蒜片，翻炒片刻出锅！#'),(991,'小米山药粥','主食','鲜山药#\n小米#\n白糖#','45克#\n50克#\n适量#','1. 在水中滴入几滴醋，把山药洗净，顺便把手浸泡一下（手在稀释的醋中浸泡一下，切山药时就不会手痒了）。将山药洗净削皮，切成小块。小米用水洗净（淘米水洗脸可以美容哦）。#\n2. 锅中加1000ml水烧开。放入小米煮5分钟（小米比山药难煮一些，应早下锅一会）。#\n3. 放入山药一起煮，大火煮5分钟，小火煮15分钟。 放入适量白糖调匀即可食用。#'),(992,'剁椒香干爆秋葵','素菜','秋葵#\n香干#\n剁椒#\n盐#\n蒜瓣#','300克#\n4块#\n1勺#\n适量#\n4颗#','1. 准备食材#\n2. 秋葵去蒂#\n3. 香干切小四方块，秋葵切小块#\n4. 剁椒和蒜瓣入油锅爆香#\n5. 下入香干和秋葵，加盐拌匀，秋葵断生即可出锅，大约7分钟#'),(993,'乱炖排骨','荤菜','排骨#\n茄子#\n土豆#\n西红柿#\n豆角#\n豆油#\n葱姜蒜#\n豆瓣酱#\n辣椒酱#\n酱油#\n十三香#\n花椒#\n大料#\n冰糖#\n料酒#\n味精#\n鸡精#\n食盐#','500g#\n200g#\n200g#\n200g#\n200g#\n少许#\n少许#\n适量#\n适量#\n少许#\n少许#\n少许#\n少许#\n10个#\n少许#\n少许#\n少许#\n适量#','1. 排骨洗净沥干，土豆去皮切块，茄子洗净切块，西红柿洗净切块，豆角摘净洗净切段，葱姜蒜切沫。#\n2. 豆油热过后小火煸炒葱姜蒜，随后加入豆瓣酱，辣椒酱和冰糖继续熬制几分钟。#\n3. 转大火加入排骨翻炒，再依次加入土豆，西红柿，茄子和豆角，最后加水没过食材，水开后转小火炖30分钟以上。#'),(994,'极鲜版炒蚬子','荤菜','蚬子#\n葱段#\n姜片#\n干辣椒#','#\n#\n#\n#','1. 蚬子洗净，水中放盐吐沙子#\n2. 切葱段，姜片，辣椒#\n3. 放入少量油，把葱段姜片辣椒炒香#\n4. 放入蚬子，放一点点一品鲜酱油，最后开口就可以出锅了#'),(995,'蔓越莓XO酱焗鳕鱼','荤菜','美国蔓越莓#\n鳕鱼#\n奶白菜#\n带枝番茄#\n紫色食用花#\n纯净水#\n盐#\n白胡椒粉#\nXO酱#\n桑巴酱#\n腰果仁#\n白葡萄酒#','50g#\n150g#\n100g#\n90g#\n3朵#\n200ml#\n10g#\n2g#\n90g#\n90g#\n20g#\n20g#','1. 鳕鱼用白葡萄酒，盐，白胡椒粉，鲜柠檬汁腌制，表皮裹上玉米面粉煎制金黄色待用。蔓越莓干用纯净水泡软，按比例加入自制的XO酱，烤过的腰果仁，一起打碎至酱状，放在煎制好的鳕鱼上，进入烤箱185度烤制8分钟即可。美国蔓越莓占整道菜的百分之40。#'),(996,'红烧肉干豆角','荤菜','猪五花肉#\n干豆角#\n冰糖#\n老抽#\n生抽#\n蚝油#\n盐#\n鸡精#\n大料#\n花椒#\n葱花#\n姜片#\n料酒#\n淘米水#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 猪五花肉改刀切2厘米宽的小块，冷水下锅，放姜片和料酒，锅开后煮25分钟去末捞出备用#\n2. 锅里放油，五分热时将冰糖放入翻炒至全部融化成浆色，放入五花肉翻炒，再放入老抽，生抽，蚝油，葱花，大料，花椒，盐，翻炒出香味，添没过五花肉的淘米水，（这里说一下，淘米水营养丰富，而且它可以更好的保留肉质鲜嫩）#\n3. 水开后放入干豆角，放入鸡精，盖上锅盖小火炖四十分钟，最后大火收汁即可#\n4. 大功告成！#'),(997,'炒年年糕 賀2015','素菜','豬肉#\n韓國年糕#\n韓國辣椒醬#\n泡茶#\n牛油#','適量#\n適量#\n半匙#\n適量#\n1勺#','1. 所用材料就這些#\n2. 先把年糕出水#\n3. 撈出 浸涼水 口感會彈牙啦#\n4. 豬肉用刀背拍打 切小塊#\n5. 放入牛油 再放肉塊 炒到豬肉變色#\n6. 放入一半份量泡菜#\n7. 再放入年糕 加水或高湯#\n8. 放半匙辣椒醬 煮一會 出鍋前再放入另一半泡菜#\n9. 完成#'),(998,'西芹百合','素菜','西芹#\n百合#\n盐#\n鸡精#\n花生油#','适量#\n适量#\n少许#\n少许#\n适量#','1. 干百合用清水泡两个小时、在沸水中焯一下去除苦味。#\n2. 炒锅放入适量花生油烧至六成热，将西芹、百合略炒，加少许盐和鸡精调味即可，口感清香、略苦。#'),(999,'葱油蛏子','荤菜','油#\n美味鲜#\n黄酒#','适量#\n适量#\n适量#','1. 蛏子洗净 ，用刀割断后面一根筋 ，否则煮的时候会开口 。#\n2. 备用葱 ……#\n3. 油热放葱炒半熟 。#\n4. 下蛏子放黄酒 , 美味鲜酱油，加上少量水大火开煮 。#\n5. 煮熟出锅……#'),(1000,'凉拌紫甘蓝','素菜','紫甘蓝#\n蒜苗#\n盐#\n生抽#\n醋#\n香油#','150g#\n3颗#\n2g#\n2勺#\n1勺#\n1勺#','1. 紫甘蓝和蒜苗洗净，紫甘蓝切成丝，蒜苗切碎#\n2. 将切好的紫甘蓝倒入一个大碗中，加入盐、生抽、醋、香油拌匀#\n3. 装入盘中撒上蒜苗碎就好了，也可以用蒜末#'),(1002,'家里宝贝们最爱红烧肉','荤菜','五花肉#\n冰糖#\n八角#\n姜#\n蒜#\n葱#\n生抽，料酒，蚝油#\n盐#','500g#\n适量#\n1颗#\n2片#\n2瓣#\n适量#\n适量#\n4g#','1. 五花肉切成麻将大小的块，温水下锅烧出血沫和表面脏东西#\n2. 煮好后冷水冲洗干净。#\n3. 锅烧热，肉块下锅煎至金黄出油。#\n4. 请原谅如此粗糙的工艺，我这是砸的冰糖。。。冰糖小火熬化起小泡泡加入八角和姜片爆香，随后放入葱段蒜片，肉下锅炒上糖色，随后依次加生抽，料酒，蚝油，翻炒均匀倒半瓶啤酒代替水。#\n5. 烧开倒入电压力锅，烧开，加盐。盖上盖子，调肉类蹄筋档位40分钟。#\n6. 起炒锅收汁即可。喜欢肉汤泡饭可以多留一些汤汁。#'),(1003,'剁辣蒜丝','素菜','蒜苗#\n剁辣椒#\n盐#','适量#\n适量#\n适量#','1. 把蒜苗洗干净、凉干水份#\n2. 再把切成小断#\n3. 切成小断后的蒜苗改切成丝、用盐腌制十五分钟左右#\n4. 盐好的蒜苗拌上剁辣椒#\n5. 拌好的蒜入容器内放入冰箱3一5天便可以吃了#'),(1004,'豉汁蒸排骨','荤菜','肋排#\n料酒#\n姜丝#\n李锦记风味豆豉酱#\n蚝油#\n淀粉#','300g#\n一小勺#\n一小把#\n一勺#\n一小勺#\n一小勺#','1. 肋排洗净切小块沥干水份，用一小勺料酒和一点姜丝拌匀腌制5分钟。#\n2. 放一勺李锦记的风味豆豉酱，充分拌匀。#\n3. 放入一勺蚝油（比豆豉酱稍少的量），充分拌匀。#\n4. 放一小勺干淀粉，拌匀，让淀粉在排骨表面薄薄的裹上一层即可#\n5. 全部调料和排骨拌匀后，装入盘或者碗中。在最上面放上一勺剁椒。#\n6. 入锅，大火，水开后蒸15分钟左右即可。#'),(1005,'啤酒鸭','荤菜','半边鸭#\n酱油#\n糖#\n啤酒#\n盐#','2个#\n15毫升#\n5毫升#\n1罐#\n半勺#','1. 鸭洗净，斩块。#\n2. 将鸭肉焯水。#\n3. 将鸭肉放入热锅中煸炒。#\n4. 加入葱姜蒜继续炒。#\n5. 鸭肉变色后加入酱油，盐，糖，翻炒均匀。#\n6. 倒入一罐啤酒，稍稍没过鸭肉，目测1厘米左右。#\n7. 盖上盖子中小火焖25到30分钟。#\n8. 大火收汁，装盘出锅。#'),(1006,'红烧猪蹄','荤菜','猪前蹄#\n桂皮#\n香叶#\n八角#\n姜#\n大蒜#\n老抽#\n糖#\n耗油#\n盐#','2个#\n#\n#\n#\n#\n#\n#\n一勺#\n两勺#\n少许#','1. 猪蹄一个切成4块，洗净，焯水#\n2. 把所有的调料放入锅中(我用的是电饭煲，可以用砂锅，砂锅比较慢要4个小时，或者高压锅)烧一壶开水倒入锅中，水能没过猪蹄的量，将焯好的猪蹄放入锅中，按蒸煮键，一般煮一小时就差不多#\n3. 最后把煮好的猪蹄和汤倒入炒锅收汁，这时放入鸡精，等到汤包裹在猪蹄上就可以出锅了#'),(1009,'简单易学凉拌苦瓜','素菜','苦瓜#\n胡萝卜#\n花生油#\n花椒#\n葱、姜、蒜末#\n生抽#\n醋#\n辣椒面#\n鸡精#\n盐#\n芝麻#\n糖#','1个#\n1段#\n少量#\n5个#\n少量#\n少量#\n少量#\n少量#\n少量#\n少量#\n少量#\n少量#','1. 苦瓜去籽切片，撒盐沥水祛苦。#\n2. 胡萝卜取段切片备用#\n3. 葱姜蒜切末#\n4. 生抽、醋、糖、鸡精、辣椒面调汁#\n5. 坐锅点火，苦瓜胡萝卜开水下锅，再次开锅捞出，放入冷水中，口感更好#\n6. 爆香花椒后挑出，然后葱姜蒜末爆香#\n7. 倒入之前调好的汁，加入芝麻#\n8. 关火，然后把苦瓜胡萝卜倒入拌匀#\n9. 装盘即可#'),(1010,'青椒炒干豆腐','素菜','干豆腐#\n青椒#\n葱#\n姜#\n蒜#\n生抽#\n蚝油#\n现磨麻椒粉（可用花椒粉代替）#\n水淀粉#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 干豆腐切成菱形块。#\n2. 青椒去蒂去籽切滚刀块。#\n3. 取适量葱姜蒜切末。#\n4. 水淀粉、蚝油、生抽和麻椒粉调成碗汁。#\n5. 锅内放油。#\n6. 放入葱姜蒜末。#\n7. 放入干豆腐，翻炒均匀。#\n8. 淋入调好的碗汁，再放入小半碗清水。#\n9. 转中火炖至汤汁收浓。#\n10. 放入青椒块。#\n11. 翻四海升平2分钟，加盐调味即可。#'),(1011,'清炒茄子','素菜','白茄子#\n葱#','四根#\n适量#','1. 将买来的茄子洗净 斜切薄片 泡清水中 葱洗净切段#\n2. 热锅 下三小勺油 （茄子吃油噢）待油热后 爆香蒜头 下盐#\n3. 将茄子从水中捞出 倒入锅中 盖上锅盖 沿锅边倒入适量清水 没过茄子 让其焖煮#\n4. 坐等茄子收汁 起锅前 倒入葱段 翻匀起锅即可#'),(1012,'可乐鸡翅','荤菜','油盐#\n可乐#\n酱油#','少许#\n少许#\n少许#','1. 水煮鸡翅，把水倒掉，鸡翅捞起来切纹路。#\n2. 热锅加入姜蒜，放入鸡翅，加入酱油和可乐，煮10至15分钟左右便可出锅。装盘后用香菜装饰下，一道色香味俱全的可乐鸡翅出炉囖！?(??? )?#'),(1014,'爆炒小河虾','荤菜','小河虾#\n蒜苔#\n青辣椒#\n生姜蒜#\n盐#\n花椒粉#\n味精#','半斤#\n150克#\n三个#\n适量#\n#\n#\n#','1. 小河虾冲洗干净沥干水分。#\n2. 蒜苔辣椒切段，生姜蒜切丝。#\n3. 炒锅烧热放油放入小河虾炒干水汽铲出来备用。#\n4. 锅内放少许油烧热，放入生姜蒜炒香。#\n5. 加入蒜苔辣椒放盐，花椒粉炒至断生。#\n6. 最后放入小河虾一起炒均匀放味精出锅。#'),(1016,'咖喱土豆鸡块','荤菜','鸡腿#\n土豆#\n胡萝卜#\n葱（最好是洋葱）#\n好梦多咖喱#\n胡椒粉#\n食用油#\n酱油#\n盐#','2个#\n1个#\n1个#\n少量#\n3块#\n少许#\n少许#\n少许#\n少许#','1. 鸡腿去皮 切成约1厘米小块. 在加入适量的胡椒粉 盐 酱油 食用油 搅拌均匀 放一旁腌制一下#\n2. 土豆 胡萝卜去皮洗净 在切成小块 土豆用水泡一下.#\n3. 锅里热油 放入葱爆香. （有洋葱最好用洋葱爆香）#\n4. 将土豆胡萝卜鸡肉全部放入大火炒1-2分钟.#\n5. 放入清水 大火煮10分钟 煮烂即可.#\n6. 放入3块咖喱块 煮至咖喱融化.#\n7. 配上一碗热乎乎的米饭 哈哈 美味!#'),(1017,'尖椒炒鱿鱼','荤菜','鱿鱼#\n尖椒#\n干红辣椒#\n姜#','两条#\n两个#\n五个#\n4片#','1. 将买回来的鱿鱼处理干净#\n2. 将鱿鱼切丝备用#\n3. 烧开水把鱿鱼放进去，不要在水里煮 放下去40秒捞上来就好！#\n4. 尖椒切丝备用#\n5. 干红辣椒切段备用#\n6. 烧油将干红辣椒、、尖椒炒10秒#\n7. 然后倒入鱿鱼和调味料翻炒3-5分钟即可出锅！#\n8. 然后就可以开吃啦！#'),(1018,'东北土豆炖茄子','素菜','土豆#\n茄子#\n十三香#\n盐#\n老抽#\n洋葱#\n大蒜#\n姜片#\n酱油#','3个#\n2个#\n3勺#\n2勺#\n3勺#\n3分之1个#\n1头#\n3片#\n2勺#','1. 洋葱 大蒜 青椒切碎 土豆切块 茄子手撕块#\n2. 热锅下油 油热放入一部分葱姜蒜爆锅 炒香放入土豆块翻炒 接着放入茄子翻炒 加入盐和酱油继续炒 炒至茄子变软加入一碗温水 放十三香 老抽调色#\n3. 中火炖煮 开锅后放入一部分葱蒜沫 炖至锅内汤水变浓稠 加入剩下的葱蒜沫 拌入切碎的青椒和味精即可出锅#'),(1019,'蛋黄糯米肉丸','荤菜','前肘肉#\n鸭蛋黄#\n糯米#\n盐#\n味极鲜酱油#','300g#\n10个#\n三茶碗#\n适量#\n少量#','1. 糯米提前六小时用冷水浸泡。#\n2. 将蛋黄放到烤箱烤到冒油。#\n3. 将肉剁成肉馅，越细越好。#\n4. 肉馅加入分次加水搅拌。再加适量盐和味极鲜搅拌均匀。#\n5. 将肉馅平铺在手掌包入一个蛋黄，搓圆，放到沥干的糯米里滚一圈。#\n6. 蒸笼可放胡萝卜片垫底再放肉丸，按以上步骤包完以后，切胡萝卜粒放到丸子顶部做装饰。#\n7. 开锅再蒸大概40分钟就可以了。#'),(1020,'糖醋排骨','荤菜','排骨#\n姜片#\n蒜#\n料酒#\n酱油#\n糖#\n醋#\n香葱#\n芝麻#','适量#\n5片#\n2颗#\n1汤匙#\n2汤匙#\n3汤匙#\n4汤匙#\n适量#\n适量#','1. 1、排骨洗净放入锅中，加水，没过排骨。2、放入姜片蒜片加入糖醋汤（1汤匙料酒，2汤匙酱油3汤匙白糖4汤匙醋）3、大火烧开加盖转中小火焖煮30分钟。4、当锅中汁水快干时，开大火快速翻炒收汁。5、装盘撒上芝麻和香葱！#'),(1021,'蒜薹炒鸡蛋#沃康山茶油#','素菜','蒜薹#\n沃康山茶油#\n生抽少许#\n鸡蛋#\n盐#\n大蒜#','300克#\n40克#\n#\n2个#\n少许#\n三瓣#','1. 蒜薹洗净，切5厘米的小段，鸡蛋加少许盐少许水打散#\n2. 锅烧热，倒入20克沃康山茶油#\n3. 倒入打散的鸡蛋#\n4. 鸡蛋炒熟后盛出备用#\n5. 锅里再次倒入20克沃康山茶油#\n6. 倒入蒜片煸出香味#\n7. 倒入蒜薹翻炒#\n8. 加入少许生抽和盐翻炒#\n9. 临出锅前倒入炒好的鸡蛋#\n10. 来碗米饭，香香哒#'),(1022,'XO酱斋肠粉#青春食堂#','主食','粘米粉#\nXO酱#\n油#\n酱油#\n葱#\n清水#','100克#\n1茶匙#\n少许#\n少许#\n1根#\n400克#','1. 备好食材：粘米粉、XO酱、葱；#\n2. 粘米粉倒入大碗里，加上清水调匀米浆；#\n3. 葱洗净切碎，加入米浆中；#\n4. 调入1茶匙XO酱；#\n5. 用筷子搅拌均匀；#\n6. 蒸盆内涂抹一点食用油，倒入调匀的米浆；#\n7. 放入蒸锅中，大火蒸10分钟；#\n8. 蒸熟的肠粉取出，用刮刀或木铲轻轻刮起；#\n9. 切小段摆盆，淋上喜欢的酱汁即可食用；#\n10. 成品图#\n11. 成品图#\n12. 成品图#'),(1023,'蟹肉棒炒鸡蛋','荤菜','蟹肉棒#\n鸡蛋#\n盐#\n白糖#\n酒#\n鸡精#','8根#\n2个#\n适量#\n适量#\n适量#\n适量#','1. 超市买的蟹肉棒，每根都按其纹理撕开，成条状。如图。（需要点时间，撕得越细炒出的量越多，为省事也可直接将蟹肉棒切成小段炒蛋，做法一样。）#\n2. 热锅入油，蛋直接打在锅里，转小火，用铲子迅速翻炒打散，等蛋稍炒干时开大火，下蟹肉棒，加盐，糖，少许水，酒，快速翻炒片刻。装盘即可。#\n3. 成品，如图。鲜，香，回味无穷。#'),(1024,'腊肉','荤菜','五花肉#\n海盐#\n花椒#\n白酒#\n糖#\n五香粉#\n辣椒粉#','1000g#\n80g#\n4g#\n3ml#\n15g#\n5g#\n适量#','1. 盐和花椒小火干炒，加入糖，白酒，五香粉，辣椒粉，温热时撒在五花肉上。肉上再撒些白酒，两天翻一次，倒掉水分。#\n2. 七天后，洗净，挂在通风处三天。熏制。#\n3. 锅中放锡纸，放上面粉，米，橙皮，茶叶，肉架空小火熏1小时以上。#\n4. 风干腊肉，炒饭，炒素菜放一点。#'),(1025,'爆炒猪肚','荤菜','猪肚#\n大葱#\n姜#\n大蒜#','两个#\n三根#\n六片#\n两瓣#','1. 先用水把猪肚煮熟，然后捞出来切条备用#\n2. 把大葱，姜，蒜切好备用#\n3. 锅内放入适量的油，待油热以后放入葱姜蒜爆炒，炒出香味后放入肚条，翻炒之后加入盐和鸡精，炒匀以后装盘出锅#\n4. 这是成品图，看起来很好吃的样子#'),(1026,'红烧地瓜','素菜','地瓜#\n调料：油，糖，料酒，酱油#\n芝麻#','适量#\n适量#\n适量#','1. 清洗地瓜。#\n2. 切丝准备。#\n3. 倒入油锅翻炒到颜色变金黄。#\n4. 加入糖，料酒，酱油翻炒入味后装盘。#\n5. 成品上洒上芝麻完成！#'),(1027,'香煎黑椒杏鲍菇','素菜','杏鲍菇#\n盐#\n黑椒汁#','230克#\n适量#\n30ML#','1. 准备材料#\n2. 杏鲍菇洗净，切薄片。#\n3. 将黑椒汁加进杏鲍菇片。#\n4. 将杏鲍菇和黑椒汁拌匀。#\n5. 平底锅放少许橄榄油，倒入杏鲍菇片，煎熟，即可上桌。#\n6. 简单做出好味道#\n7.#'),(1028,'清蒸鱼','荤菜','各种可以蒸的鱼#\n生姜丝#\n蕃茄#\n香菇#\n泡青菜#\n蒜头油#\n香菜#','#\n适量#\n一小个#\n一朵#\n适量#\n适量#\n一小棵#','1. 洗净鱼儿，甩干水放入盘子里，泡菜洗净后切丝铺在鱼身上，然后放香菇丝，姜丝，蕃茄切块铺在上面，淋少许生抽，最后在上面淋上两大匙蒜头油即可。（那个香菜的根洗干净后可放在上面蒸，增加香气还不浪费）#\n2. 蒸锅大火至水开后放入鱼，蒸15分钟。（一定保证全程大火）#\n3. 出锅趁热撒上香菜段，趁热吃喔！#'),(1029,'豆腐脑','主食','黄豆#\n清水#\n熟石膏粉#\n玉米淀粉#\n凉白开#','150g（约豆浆机中自带量杯的一杯半）#\n1000ml#\n1小匙（tsp）#\n2小匙#\n3大匙（tbsp）#','1. 将黄豆浸泡过夜后沥出，#\n2. 放入豆浆机中，加入清水1000ml，启动豆浆机。#\n3.#\n4. 在豆浆机制浆的同时，用1小匙熟石膏粉、2小匙玉米淀粉加3大匙凉白开调匀，#\n5. 倒入一个大口深盆中。#\n6. 豆浆机完成制浆后，过滤豆渣，留下豆浆。#\n7. 在豆浆温度稍稍降为摄氏85度左右（约华氏185度左右）时，将装豆浆的容器稍微提起至高处，往装有均匀石膏粉浆的深盆里冲。#\n8. 豆浆都冲到深盆里后，静置15-20分钟即完成豆腐脑的制作。#'),(1030,'汤菜：韭菜海米咕嘟豆腐','汤','韭菜#\n豆腐#\n海米#\n盐#\n鸡精#\n油#\n香油#','100g#\n1块#\n一小把#\n适量#\n少许#\n少许#\n少许#','1. 韭菜洗净切段，海米洗净。#\n2. 锅中倒入少许油加热，放入海米翻炒几下，豆腐放入锅中，用铲子切成小块，加盐调味。#\n3. 加水没过豆腐，（喜欢喝汤的可以多加一些水）。盖锅盖，小火炖煮约15分钟，至豆腐出现小孔。#\n4. 下入韭菜煮至成熟，放入鸡精调味后关火。淋入少许香油即可。#'),(1031,'泡椒鸡胗（杂）','荤菜','鸡胗#\n泡椒，红尖椒，生姜，大蒜，生抽，料酒#','适量#\n#','1. 材料备好，鸡胗切小片用少量料酒和生抽腌制10分钟。#\n2. 锅烧热放油，鸡胗爆炒至变色。#\n3. 然后先放入切好的生姜，大蒜，再放入红尖椒，泡椒。继续翻炒#\n4. 加少量料酒，生抽适量，翻炒至红尖椒变软。放盐，味精。#'),(1033,'土豆烧牛腩','荤菜','牛腩#\n土豆#\n姜#\n老抽#\n生抽#\n白糖#\n香葱#\n草果#\n桂皮#\n丁香#\n八角#','350g#\n2个#\n3片#\n1汤匙#\n1汤匙#\n1汤匙#\n1根#\n1个#\n1个#\n少许#\n2个#','1. 牛腩切小块，放热水里焯下，盛出沥水。土豆也切差不多大小的滚刀块。炒锅里放水，把八角、丁香、桂皮、草果、姜片放入，如果想简单省事可以直接放包炖肉料包。一汤匙老抽、一汤匙生抽、一汤匙料酒、一汤匙白糖，开锅把焯过的牛腩放入。盖盖，小小火一个半小时。#\n2. 土豆泡凉水里，五分钟就行。#\n3. 一个半小时后放入土豆，如果锅里汤汁少了再倒点热水，直到土豆微烂放入切好的香葱末就行。#\n4. 收汁，如果味道不够稍微加点盐就行。#'),(1034,'萝卜素丸子','素菜','红萝卜#\n胡萝卜#\n中筋面粉#\n盐#\n味精#\n古月面#\n姜末#\n葱末#','一个#\n两根#\n五百克#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 第一步:萝卜擦成细丝，加入盐，放置半小时，然后将萝卜丝用手攥干，沥去水分，但不宜过干！#\n2. 第二步:加入味精、古月面和面粉搅拌均匀，使面粉和萝卜丝调和在一起，可捏合成丸子形状即可！#\n3. 第三步:锅内倒入食用油，至七成热，下入捏好的丸子，炸至金黄色泛红即可#'),(1035,'干锅鸡','荤菜','藕#\n胡萝卜#\n洋葱#\n青椒#\n黄瓜#\n郫县豆瓣酱#\n六月鲜豆瓣酱#\n特级鲜酱油#','一节#\n一根#\n一个#\n2-3个#\n一根#\n若干#\n少量#\n适量#','1. 配菜切块，鸡肉选的鸡腿肉，放入料酒生姜腌制半小时#\n2. 将配菜放入足够的油中炸熟！捞出再炸鸡腿肉，炸至鸡腿肉水分完全收干，然后放入豆瓣酱酱油等炒至均匀上色倒入配菜再一起炒一会盛出放入香菜点缀！#\n3. 一盆麻辣香锅出炉啦#'),(1036,'干煸麻辣鸡丝','荤菜','鸡腿#\n尖椒#\n麻辣花生#\n葱花#\n白芝麻#\n四川辣酱#\n生抽#\n白糖#\n盐#\n料酒#','1块#\n1根#\n2汤勺#\n适量#\n适量#\n1茶匙#\n1汤勺#\n1茶匙#\n1茶匙#\n2汤勺#','1. 鸡腿肉去骨，用清水煮15分钟至熟，尽在凉水中片刻取出切成细丝。也可以用吃剩的扒鸡或者烤鸡来做。#\n2. 锅中倒入油，放入葱花爆香，加入四川辣酱炒香。#\n3. 放入尖椒丝翻炒。#\n4. 再放入切成丝的鸡肉翻炒，加入生抽、盐、白糖调味炒匀后关火#\n5. 麻辣花生切碎撒入锅中，翻拌均匀。#\n6. 最后加入白芝麻即可装盘。#'),(1037,'炒土豆','素菜','土豆#\n辣椒#','1个#\n1个#','1. 首先削皮#\n2. 然后切成薄薄的丝#\n3. 在炒之前先阜水，阜水后用冷水浸一下。之后再放油，接着放辣椒炒一下再放土豆炒两三分钟。#\n4. 成品#'),(1038,'鱼片','荤菜','花鲢鱼#\n葱姜蒜#\n黄酒#\n盐#','1条#\n若干#\n一些#\n少许#','1. 买回来洗干净 鱼头做了剁椒鱼头 鱼身切片#\n2. 放黄酒 少许淀粉 鸡蛋 盐 葱姜腌半小时以上 我是放冰箱的#\n3. 锅中倒油开始滑鱼片#\n4. 好了出锅#\n5. 准备素菜 有啥加啥#\n6. 开始炒素菜#\n7. 切点蒜和葱末#\n8. 加鱼片一起煮一会加少许水#\n9. 盖锅盖焖烧 差不多了加点水淀粉勾芡#\n10. 好了 出锅装盘#\n11. 还可以烧木耳鱼片#\n12. 鱼头做的剁椒鱼头#'),(1039,'香菇酿肉','荤菜','香菇#\n猪肉馅#\n胡萝卜#\n料酒#\n盐#\n耗油#\n淀粉#\n葱#\n姜#','12个#\n200g#\n1个#\n适量#\n#\n#\n#\n#\n#','1. 鲜香菇洗净，将香菇蒂用剪刀剪下#\n2. 将胡萝卜切成末，香菇蒂切成末，葱姜切成末，与猪肉馅及辅料按照自己的口味添加后拌匀#\n3. 将做好的肉馅酿在香菇中#\n4. 预热空气炸锅5分钟后，把食材放入其中，180度18分钟即可#\n5. 成品#'),(1040,'鱼香杏鲍菇','素菜','杏鲍菇#\n大蒜#\n豆瓣酱#\n生抽#\n老抽#\n蚝油#\n醋#\n糖#\n淀粉#\n清水#','3~4个#\n3粒#\n2勺#\n1勺#\n半勺#\n1勺#\n半勺#\n1勺#\n半勺#\n少许#','1. 杏鲍菇洗净撕丝，干锅里焙干水分，盛出待用(耐心等热透了才出水)#\n2. 除了蒜和豆瓣酱以外的所有调料混合成调料汁#\n3. 少许油的油锅里爆香蒜瓣，放入豆瓣酱炒出红油#\n4. 加金针菇翻炒均匀#\n5. 倒入调料汁翻炒收汁即可(一般不用放盐，不放心可以在收汁后尝一根再考虑要不要加盐)#'),(1041,'破壁料理机食谱：排骨汤','汤','排骨#\n玉米#\n胡萝卜#\n姜#\n盐#\n料酒#','200g#\n1条#\n半条#\n3片#\n4g#\n1／2瓶盖#','1. 玉米掰粒，胡萝卜可省事不切。排骨用料酒，2g盐，2片姜腌好。#\n2. 把全部食材放入杯中，加水到最高位线下，再放2片姜。#\n3. 工作接近尾声。骨头不见了，玉米胡萝卜也不见了。#\n4. 工作结束，开盖加2g盐，按下点动键挖拌几秒。离电倒出。#\n5. 绵滑细腻的骨头汤。#'),(1045,'香煎千页豆腐','素菜','千页豆腐#\n肉末#\n香菇#\n葱#\n白糖#\n酱油#\n辣酱#','半份#\n少许#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 千页豆腐切块备用。#\n2. 香菇切碎，和肉末，葱，酱油，辣酱拌匀。#\n3. 千页豆腐煎二面金黄。#\n4. 拌好的肉末香菇辣酱放锅炒香，用适量盐和白糖，淀粉，水勾芡汁淋入稍煮，收汁即可。#\n5. 煎好的千页豆腐摆盘，淋上炒好的肉末酱汁即可大块剁耶。#'),(1046,'辣炒铁杆山药','素菜','铁杆山药#\n辣椒#\n葱姜蒜#','适量#\n适量#\n适量#','1. 山药洗净放蒸锅蒸熟，熟后切断备用，辣椒切丝，葱姜蒜切好备用，香菜备用     锅里放油少量，油8成热放葱姜，出香味后放山药，炒匀后放酱油2滴，加少量的水小火炖开，大火收汁，放青椒翻炒，放醋，鸡精，盐，蒜，撒香菜成盘。#'),(1048,'【雪菜豆豉蒸鳊鱼】：年年有余的吉祥菜','荤菜','鳊鱼#\n姜#\n蒜#\n雪菜#\n即食豆豉#\n盐#\n食用油#','1条（约600g）#\n4片#\n1瓣#\n2汤匙#\n1汤匙#\n少许#\n少许#','1. 姜、蒜去皮切碎，雪菜、豆豉备用；#\n2. 鳊鱼处理干净擦干水份，鱼背上划斜刀，并内外涂抹少许盐腌制30分钟；#\n3. 腌鱼的过程中，取一炒锅烧热，下少许油，先下姜、蒜爆香；#\n4. 姜、蒜爆香后，下雪菜、豆豉煸炒；#\n5. 煸炒出香后，盛出待用；#\n6. 鳊鱼腌好后，将炒好的雪菜、豆豉铺放在鱼身上；#\n7. 锅中烧水，水开后将鱼碟放入锅中；#\n8. 盖上锅盖，隔水大火蒸10-12分钟；#\n9. 蒸好后关火，抬出鱼碟即可。#'),(1049,'阳台美食--蒜蓉地瓜叶','素菜','地瓜叶#\n蒜#\n盐#','100克#\n3瓣#\n一点点#','1. 疯长的地瓜君~#\n2. 被剪掉头发以后看起来利索多了#\n3. 把叶子一片一片摘下来备用#\n4. 地瓜叶洗净 蒜瓣去皮切成碎末#\n5. 锅中放底油 下入蒜末爆香 然后下入地瓜叶翻炒#\n6. 出锅~#'),(1051,'李孃孃爱厨房之一一蒜苔炒肉丝','荤菜','猪肉(瘦)#\n蒜苔#\n姜米#\n泡辣椒#\n郫县豆瓣#\n盐#\n菜仔油#','75g#\n400g#\n少许#\n少许#\n少许#\n少许#\n适量#','1. 先上成品图哦！#\n2. 制作蒜苔肉丝的材料    蒜苔、猪肉(瘦)、泡辣椒、姜米、盐、郫县豆瓣。   肉丝里加入一点水淀粉和少许的盐码味待用  热锅，倒油，油辣后把码好味的肉丝倒入锅里划散后，加入姜米、泡辣椒、蒜苔炒两下后加入少许的水烘一下就可以起锅装盘了。#\n3. 最后上两张美图哦！#\n4. 哈哈哈哈#'),(1053,'油焖大虾','荤菜','海虾#\n葱姜蒜#\n酱油#\n糖#\n料酒#','1盒#\n适量#\n2勺#\n1勺#\n1勺#','1. 大虾洗净剪去虾须，从虾背切开一个缝#\n2. 放入少量料酒、酱油、糖腌一下#\n3. 锅里放油，五成热时放葱姜#\n4. 葱姜出香味后把虾摆入锅中煎一下#\n5. 倒入酱油料酒白糖翻炒均匀后，盖上锅盖，焖一会儿，带汤汁收干即可#\n6. 装盘#'),(1054,'家常菜—红烧金鲳鱼','荤菜','金鲳鱼#\n料酒#\n生抽#\n生姜蒜头#\n青葱红椒#','一条#\n两勺#\n两勺#\n适量#\n各一个#','1. 将材料清洗干净#\n2. 热油锅，放油，把鱼用小火两面煎黄#\n3. 下姜蒜，加入料酒，酱油，清水，用中火焖三分钟再将鱼翻面，再焖三分钟#\n4. 大火收汁，加入葱末，红椒末，起锅#'),(1055,'糖醋排骨','荤菜','排骨#\n料酒#\n生抽#\n老抽#\n香醋#\n白糖#\n盐#\n鸡精#\n芝麻#\n葱花#','500g#\n一汤匙#\n一汤匙#\n半汤匙#\n三汤匙#\n三汤匙#\n半茶匙#\n少许#\n适量#\n适量#','1. 小排500克焯水后，煮三十分钟，肉汤可以煮面条，别倒掉了。#\n2. 捞出焯好的排骨腌渍，用一汤匙料酒，一汤匙生抽，半汤匙老抽，二汤匙香醋（不是白醋）腌渍20分钟。#\n3. 炸制，油别放多，可以省油，炸到金黄色那就好了，只要翻身的勤就不会糊锅。#\n4. 加入三汤勺白糖（大胆的放糖吧，三汤匙，别怕多）。半碗焯排骨水大火烧开，调入半茶匙1盐提味。#\n5. 小火焖十分钟大火收汁，收汁的时候最后加一汤匙香醋，那个酸甜口就出来了。#\n6. 临出锅撒葱花芝麻，少许味精。#'),(1056,'西红柿地瓜炖牛肉[牛腩和红薯炖出罗宋汤的味道]','荤菜','牛腩#\n西红柿#\n地瓜#\n青椒#\n葱姜蒜#\n番茄酱#','250g#\n3个#\n2个#\n2个#\n少许#\n2勺#','1. 葱姜蒜爆锅后，加入牛腩翻炒一会，全部变色后加水。#\n2. 加水，盖盖子，翻水后，小火炖半小时!#\n3. 加入，西红柿，地瓜，辣椒段等所有，继续炖半小时，勤快的可以把西红柿拿开水烫一下，扒皮。#\n4. 半小时后，打开锅盖收汁，这时加入番茄酱，和两小勺盐，让汤汁和味道更有卖相。#\n5. 放过番茄酱颜色立马不一样了，我还加了一些奶酪，西餐味更浓一些，家没有奶酪的，放一小盒酸奶也可以。#'),(1057,'虾干烧豆腐','荤菜','北豆腐#\n虾干#','一块#\n适量#','1. 豆腐下锅煎到表面金黄#\n2. 虾干提前用水泡发#\n3. 热锅凉油下入虾干，倒入料酒#\n4. 加入葱姜末后倒入煎好的豆腐，加适量酱油和盐，翻炒均匀加上开水，#\n5. 适量淀粉加入凉水和香油#\n6. 豆腐闷制5到10分钟后，倒入淀粉水，大火烧开出锅#'),(1058,'木耳鱼丸','荤菜','鱼丸#\n肉丸#\n干木耳#\n油#\n姜沫#\n鸡精#\n葱花#','#\n#\n#\n适量#\n适量#\n适量#\n适量#','1. 这道菜其实很简单，都是买现成材料，谁都会做的。丸子就不用洗了，都是干净的。木耳用水泡发，然后去蒂切一刀。#\n2. 锅中一些底油，油热放点姜沫，倒入木耳炒1分钟。然后倒入鱼丸子，和肉丸子。#\n3. 不要翻炒，加大半碗水，加些盐盖锅盖，烧开。#\n4. 大概烧个3分钟，稍微留一点汤，不要全烧干了哦！#\n5. 少加点鸡精，加点葱花就可以起锅了。#\n6. 我觉得清清爽爽，色彩搭配的也不错，口感也不错！#'),(1060,'鱼香茄子','素菜','茄子#\n大蒜#\n生姜#\n四川豆瓣#\n花椒#','3根#\n少许#\n少许#\n少许#\n少许#','1. 茄子切段,切花刀。大蒜,生姜切丁备用。#\n2. 切好的茄子放置微波炉加热3分钟,这样做出来的茄子不会油。#\n3. 冷锅倒油放入少许四川豆瓣酱,花椒,大蒜丁,生姜丁翻炒直至炒出香味。(热锅炒出的四川豆瓣酱易糊,易生锅,更不易炒出四川豆瓣酱的香味)。#\n4. 倒入加热过的茄子,少许酱油,以及清水一小碗,烧制水分全干方可出锅。#'),(1061,'香酥龙利鱼','荤菜','龙利鱼#\n面粉#\n油#\n盐#\n酱油#\n料酒#\n咖喱#\n番茄酱#','#\n#\n#\n#\n#\n#\n#\n#','1. 鱼切块状#\n2. 下调味料腌制半小时左右#\n3. 油锅起小泡泡#\n4. 鱼块果上面粉#\n5. 下油锅炸注意轻轻翻动#\n6. 炸至金黄色即可等凉了香酥可口#\n7. 可调制一些咖喱和番茄酱沾着吃更美味#'),(1062,'清蒸南瓜','素菜','南瓜#','一块#','1. 把南瓜洗干净，切成小块#\n2. 摆在盘子里，可以摆自己喜欢的样子！然后放蒸锅里#\n3. 盖上盖子，大火蒸大概20分钟的样子，就可以关火了#\n4. 成品图，味道甜甜美美！#'),(1063,'油焖大虾（甜口味的）','荤菜','大虾#\n番茄酱#\n白糖#\n盐#\n葱姜蒜沫#\n食用油#','6只#\n适量#\n4勺#\n适量#\n适量#\n适量#','1. 准备材料，食用油，盐适量#\n2. 大虾剪去须子，锅热放入食用油，炸制金黄色捞出备用……#\n3. 滴入少许食用油，放入番茄酱，白糖，盐调味均匀炒至浓稠，把大虾挨个放入锅中，蘸满酱汁…#\n4. 哈哈，油焖大虾出锅喽，开吃#'),(1064,'豆瓣油淋茄子','素菜','紫茄子#\n香葱#\n豆瓣#\n生粉#\n红椒#','2根#\n适量#\n适量#\n适量#\n适量#','1. 将长条茄子切成小细条， 准备好郫县豆瓣， 两头大蒜， 小葱；#\n2. 将平锅烧热后，加入花生油50克、将茄片排锅内、煎至两面金黄即出锅#\n3. 将锅烧热，放少量的油， 下入郫县豆瓣翻炒；将炒锅放中火上、加油15克、热后投入葱丝、蒜末、姜末、肉末、精盐、白糖、米醋；#\n4.  炒勾后即下入煎茄片、轻轻拌炒，炒勾即可出锅#'),(1065,'红烧狮子头','荤菜','瘦肉#\n鸡蛋#\n老豆腐#\n淀粉#\n香菇#\n小葱#\n蚝油#\n盐#\n食用油#\n大葱#','200g#\n1个#\n200g#\n5g#\n3颗#\n1根#\n少量#\n少量#\n300ml#\n半截#','1. 把材料切碎备好#\n2. 切碎搅匀#\n3. 手搓成圆形肉团#\n4. 热油锅后然后调中火，把肉丸下锅炸#\n5. 变金黄色调小火用筷子翻反面炸#\n6. 怕烧焦火调小，到这个色后关火起锅#\n7. 切好大葱#\n8. 热油锅，下大葱煎香#\n9. 小火两面煎黄煎香后，调入蚝油，酱油，盐，白胡椒粉，料酒#\n10. 淀粉勾芡#\n11. 淀粉倒入锅，加半碗水，熬2分钟#\n12. 肉丸下锅煮5分钟#\n13. 红烧狮子头#'),(1066,'凉拌土豆丝','素菜','米醋#\n大蒜#\n花椒油#\n香油#\n盐#\n味精#','#\n#\n#\n#\n#\n#','1. 部分材料展示#\n2. 土豆削皮，先横刀切片，再切细丝，快速淘洗之后滤干备用。#\n3. 甜红椒切丝。大蒜用磨泥器磨成细茸，也可用擂钵捣成茸，还可用刀剁细。磨好的蒜蓉调入花椒油、香油、很少量的白醋、盐、味精，制成蒜蓉调味汁。#\n4. 锅内烧水，水开后倒入土豆丝，焯熟。#\n5. 用漏勺捞出土豆丝，放凉开水里漂一下，滤干。#\n6. 拌入红椒丝，蒜蓉调味汁。#\n7. 让它们充分融合一会儿，就可以享用啦。#'),(1067,'五花肉烩扁豆土豆','荤菜','土豆#\n盐#\n糖#\n老抽#\n葱姜蒜#','#\n#\n#\n#\n#','1. 五花肉切片，扁豆洗净掰小段，土豆切条，葱姜蒜切碎备用。#\n2. 先将五花肉煸一下。#\n3. 放入葱姜蒜炝锅。#\n4. 放入土豆炒呀炒。#\n5. 再放入扁豆炒呀炒。#\n6. 加入料酒。#\n7. 再来点老抽翻炒上色。#\n8. 最后加入盐和适量的清水，小咕嘟一会。#\n9. 待食材全部软烂，汤汁也收尽就可以出锅了。#'),(1068,'酸菜豆腐鱼','荤菜','鲫鱼#\n酸菜#\n豆腐#\n生姜#\n葱#\n红椒#\n植物油#\n盐#\n绍酒#\n胡椒粉#\n麻油#','一条#\n100g#\n200g#\n10g#\n10g#\n一只#\n20g#\n5g#\n3g#\n少许#\n2g#','1. 1，将鲫鱼杀洗干净#\n2. 2 豆腐切成小块，生姜，红椒切粒，葱切花（小粒）（豆腐含嘌呤较多，嘌呤代谢失常的痛风病人和血尿酸浓度增高的患者应慎食豆腐。）#\n3. 3 锅内烧油，下入鲫鱼，姜粒，绍酒，用小火煎香后，注入适量清汤。全程已中火为好。#\n4. 4 再加入酸菜，豆腐，红椒粒，调入盐，胡椒粉，用中火煮透。#\n5. 5 淋入麻油，撒上葱花既可食用。#'),(1069,'苦瓜酿肉','荤菜','五花肉#\n苦瓜#\n鸡蛋#\n红椒#\n盐#\n淀粉#\n白糖#\n醋#','200g#\n1个#\n1个#\n2—3个#\n2勺#\n少许#\n1勺#\n2勺#','1. 苦瓜切3厘米左右块，去掉里面的瓤和籽，过热水焯（里面可以适当放点盐和油，这样颜色比较好看，不会黄）。焯完之后立刻放入冷水备用。#\n2. 五花肉加入鸡蛋和少许淀粉、葱、姜、盐等调味。将肉塞进苦瓜，隔水蒸15—20分钟。#\n3. 将蒸好的苦瓜原汁倒入锅中加入少量水，白糖，醋，辣椒，盐煮沸，最后加水淀粉收汁。淋到蒸品上，这道菜充分体现了酸甜苦辣哦～～#'),(1070,'凉拌洋葱','素菜','洋葱#\n辣椒面#\n豆豉「按喜好加」#\n盐#\n花椒#\n生抽#\n醋#','1个#\n少量#\n少许#\n少许#\n4颗#\n2勺#\n少许#','1. 1.先把洋葱对半切开，然后放置水中除去味道，以便好切#\n2. 2.在水里静置5分钟后拿出切丝，等用。#\n3. 3.在锅中烧热油，然后放入花椒和辣椒面，然后用热油浇在花椒和辣椒面上。最后放入所有调料，拌匀即可。#'),(1071,'自制腊肉炒蒜苔','荤菜','自制腊肉#\n蒜苔#\n花生油#\n葱#','1根#\n250g#\n适量#\n适量#','1. 腊肉切片，备用#\n2. 蒜苔切段备用#\n3. 锅中热油，油热后，放入腊肠煸炒至肠变色，之后放入葱段，蒜苔煸炒至香味，倒入适量冷水，至蒜苔变软，即可出锅#\n4. 成品图~~~~~~#'),(1072,'香煎武昌鱼','荤菜','大葱#\n姜#\n盐#\n料酒#\n胡椒粉#\n小葱#','一根#\n一块#\n适量#\n适量#\n适量#\n两根#','1. 大葱切段，姜拍了切片，用盐和花椒一起抹处理干净的新鲜武昌鱼身子，鱼身上划几刀，以便入味，当然要加一些料酒去腥，鱼腌半小时到1小时左右#\n2. 锅烧热热的，热锅凉油下武昌鱼开始煎，保持小小的火，一面煎黄了，轻轻反翻过来煎另外一面，直到把鱼煎熟，#\n3. 鱼快煎好的时候，放少许小葱和姜片和鱼一起煎，煎香，撒少量胡椒粉，起锅装鱼盘里，可以吃了，外皮焦香，鱼肉鲜嫩，香煎武昌鱼很好吃呢！#'),(1073,'酒酿鱼～功夫菜','荤菜','辣椒#\n大蒜#\n生姜#\n料酒#\n老抽#','1只#\n10粒#\n1小块#\n1勺#\n1小勺#','1. 菜市场没有青鱼干，只好买了黄鱼干。#\n2. 切小块#\n3. 放水里浸泡50分钟左右，因为鱼是盐腌制过的。浸泡太久鱼肉松散也不好吃。#\n4. 上锅淋料酒蒸熟，放凉。#\n5. 蒜，姜，辣椒切碎粒。#\n6. 锅底放油比平时炒菜要多2倍，加热至边缘有青烟关火。#\n7. 先放蒜姜出香味再放辣椒，开小火，#\n8. 接下来放酒酿，开中火煮开。#\n9. 加入鱼块，继续转中小火煮。要注意不断翻铲以免沾锅，大概20分钟左右。#\n10. 直到水份收干，淋老抽调色用。#\n11. 出锅#\n12. 成品诱人啊。#'),(1074,'美国蔓越莓乳扇卷大山神排','荤菜','美国蔓越莓干#\n美国冷冻蔓越莓#\n美国蔓越莓酱#\n乳扇#\n红酒#\n牛肋骨#\n小唐菜#\n牛骨汤#\n辣椒干#\n桂皮#\n香叶#\n花椒#\n黑胡椒#\n橄榄油#','50g#\n20g#\n30g#\n30g#\n#\n250g#\n10g#\n500g#\n5g#\n5g#\n3g#\n2g#\n1g#\n少许#','1. 1-先把牛肋骨250克加黑胡椒和少许盐加橄榄油生煎两面2-辣椒干5克，桂皮5克，香叶3克，花椒2克炒香加入牛骨汤500克封上锡纸烤1个半小时。3-把乳扇下70度热油锅炸卷成冰淇淋筒。过后把美国蔓越莓干50克泡红酒加少许糖熬成泥塞乳炸好的乳扇卷和配上鲜玫瑰即可。4-在把小锅加热下橄榄油牛骨汤和美国蔓越莓酱 30克烧成四分之一后调入盐，糖和美国鲜蔓越莓20克为酱料。5-最后把烤好的牛排捞出放入煎锅煎成香味入装盘放上做好的乳扇，小唐菜和淋上调好的美国鲜蔓越莓酱即可。#'),(1075,'番茄红烩蛋包牛肉丸','荤菜','番茄#\n牛肉丸#\n鸡蛋#\n面粉#','两个#\n一包#\n三个#\n少许#','1. 牛筋丸水煮至浮起来备用#\n2. 三个鸡蛋加面粉加盐打散#\n3. 番茄切小块备用#\n4. 锅里烧热油 牛肉丸放进蛋液丸滚一圈下锅煎 火不要太大 所有牛肉丸入锅后把剩余蛋液倒入锅中翻面 加少许胡椒粉 蛋液凝固后将牛肉丸盛出锅。#\n5. 锅里重新添油烧热，切小块番茄下锅大锅翻炒至糊状。加盐。蛋包牛肉丸入锅拌匀烩热。#\n6. 装盘出锅#'),(1076,'蚂蚁上树','荤菜','肉末#\n粉丝#\n酸豆角#\n蒜末#\n酱油#\n鸡精#\n盐#\n郫县豆瓣#','100g#\n150g#\n50g#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 将酸豆角切小段 准备蒜末#\n2. 粉丝用热水泡软 肉末中加入姜末 盐#\n3. 热锅凉油 待油温5成热时加入蒜末#\n4. 加入肉末炒出香味#\n5. 加入酸豆角继续翻炒  放入郫县豆瓣 酱油 盐#\n6. 加一小碗水后放入粉丝焖一会#\n7. 待水分收得差不多就可以翻炒几下  就可以出锅了#\n8. 出锅装盘#'),(1077,'木耳西兰花','素菜','西兰花#\n木耳#\n红辣椒#\n葱#\n蒜#','一颗#\n250g#\n一根#\n一根#\n两瓣#','1. 准备！开始#\n2. 将煮沸的清水放入少量的盐，放入西兰花，一分钟左右捞出，放到冷水中#\n3. 木耳也需要煮1分钟左右，放入冷水中#\n4. 小葱切末，蒜切片，辣椒切段#\n5. 小火油热后，放入葱蒜#\n6. 炒出香味后放入红辣椒，翻炒10秒左右#\n7. 放入西兰花，木耳进行翻炒，并且加入盐，少量料酒，少量糖（少量！一丢丢），就可以出锅#\n8. 完成#'),(1078,'豌豆尖豆腐汤','汤','盐#','#','1. 洗净豌豆尖#\n2. 准备好一块豆腐#\n3. 水热后，先把豆腐放下，然后放豌豆尖，再根据个人口味，放一点盐巴。即可。#'),(1079,'美味鲜嫩的蒸蛋','荤菜','盐#\n香葱#\n香油#\n蒸鱼豉油#','少许#\n适量#\n少许#\n少许#','1. 鸡蛋打碎，加温水、盐、香油，继续搅拌，好了以后把浮在蛋液上的泡沫撇掉，碗口加封保鲜膜，并在保鲜膜上用牙签戳几个洞！上锅蒸10分钟左右！#\n2. 出锅洒上葱花，加入蒸鱼豉油更加鲜美！#'),(1081,'农家小炒肉#豆果美食汇#','荤菜','带皮五花肉#\n青蒜段#\n杭椒、指天椒#\n配制成品调味料#','200g#\n80g#\n65g#\n60g#','1. 材料图~冰袋给的很足~#\n2. 再拍一下拆了包装之后的~很新鲜像刚洗完了现切的一样~#\n3. 然后热锅煸炒五花肉~直接空锅下的肉~把五花肉本身的油煸出来就好了这样成品没那么油~#\n4. 煸香五花肉如图~这样子就差不多了~#\n5. 下青蒜翻炒~#\n6. 然后加入酱料包~如果自己做的话~调个家常带辣的酱油口就挺好吃的~酱油耗油再来点豆豉和一丢丢糖啥的~#\n7. 然后翻炒均匀~#\n8. 给不太能吃辣的人炒得~所以最后放的辣椒条~翻炒两下直接出锅不会特别辣但是还有香味~#'),(1082,'葱爆椒盐虾球','荤菜','虾球#\n小葱#\n生姜#\n椒盐#\n料酒#\n生抽#\n白糖#','500g#\n1把#\n1块#\n适量#\n适量#\n少许#\n少许#','1. 材料备齐。买来的虾球虽然已经掐去头部，但还有残余的腮部和脚。所以自己清理的时候要去掉这个部分。然后抽出虾肠，用刷子刷洗干净。#\n2. 锅中入油，下葱姜煸香，油的分量要下多一些；#\n3. 油温较高时，下虾球煎炒，油多一些是为了能够将虾球略微的煎炸一下；#\n4. 大火煎炒的时间要久一点；#\n5. 接着放入料酒、一大勺白糖，和生抽大火继续炒至冒烟；#\n6. 最后下入分量较多的椒盐翻炒后装盘即可。#'),(1083,'香煎沙丁鱼','荤菜','沙丁鱼#\n盐、料酒、葱、姜、蒜、花椒面#','6条#\n适量#','1. 将冰鲜沙丁鱼清理好后，放一点盐及料酒腌制十分钟。#\n2. 热锅放姜丝、蒜粒炒香，然后将鱼放入锅里小火慢煎。#\n3. 待两面煎黄，洒少许花椒面，起锅。#\n4. 装盘放上葱花，趁热吃最好。#'),(1084,'腊肉炒碗豆角','荤菜','五花肉或腊肉#\n大蒜#\n盐，鸡精，姜，蒜，葱#','适量#\n适量#\n适量#','1. 用手掐去豆角的头尾，有条筋要撕掉，不然会影响口感#\n2. 腊肉切均匀的片，如果是新鲜五花肉，最好用蠔油，盐，酱油等腌一下#\n3. 切一两条红辣椒，增加菜色，切好葱蒜姜#\n4. 锅热放少许油，然后放肉去煎变色（腊肉的肥肉部分透亮，用水煮过，肥而不腻），（煎新鲜肉时可放少许老抽上色，又香又漂亮）#\n5. 先放姜蒜再放辣椒豆角翻炒至豆角变色，放盐，鸡精出锅#\n6. 出锅了，色香味俱全#'),(1086,'珐琅铸铁锅-红烧各种丸子','荤菜','香芋丸子#\n香菜丸子#\n胡萝卜玉米丸子#\n马蹄·荸荠#\n生姜#\n蒜瓣#\n紫苏#\n青辣椒#\n红小辣椒#\n小葱#\n盐#\n白糖#\n生抽#\n老抽#\n油#\n米酒#\n番茄酱#\n凤球麦鲍鱼汁或者蚝油#\n水#','10个#\n6个#\n6个#\n10个#\n2片#\n3个#\n小撮#\n1条#\n1个#\n适量#\n1茶匙#\n盐的三倍#\n1汤匙#\n2滴#\n一点点#\n1汤匙#\n1.5汤匙#\n半汤匙#\n100ml#','1. 材料切大段即可，准备铁锅一口。马蹄切半。#\n2. 将丸子（购买自熟食摊点哦不是生的）和各种调料配料丢进去。大火烧滚后盖锅盖改1000度中火8分钟焖之。#\n3. 八分钟焖后开锅盖搅拌翻炒两分钟适当收汁即可。#\n4. 同样配方还可以焖假篓夹肉或者各种熟食铺的丸子啊蛋饺啊。#\n5. 好吃。连续吃两天了。#'),(1087,'芝士地瓜蓉','甜品','地瓜#\n花生碎#\n马苏里拉芝士#\n蛋清#','1个#\n50g#\n50g#\n2个#','1. 地瓜（我选了一个大个的#\n2. 将地瓜泥装入烤碗，八分满，倒入蛋清，最后洒满芝士碎。#\n3. 烤箱210度预热五分钟，放入烤碗，15分钟。#\n4. 美味地瓜蓉出炉。#'),(1088,'唐阿姨椒盐虾（少油少盐）','荤菜','台湾虾#\n蒜瓣#\n尖椒#\n油#\n黄酒#\n酱油#\n胡椒粉#\n盐#\n小葱#','500g#\n5个#\n1个#\n2勺#\n100ml#\n1勺#\n少许#\n少许#\n3根#','1. 台湾虾一斤，清水洗净，虾须剪掉，水沥干#\n2. 用剪刀将每只虾背部剪开，便于煎熟入味#\n3. 蒜头切碎，尖椒切小条#\n4. 平底锅里加入两勺油（一般中号不锈钢汤勺），放入虾，煎到两面金黄#\n5. 虾煎到金黄后，放入蒜末尖椒先煸一下#\n6. 蒜末尖椒煸香后和虾一起翻炒均匀#\n7. 加入黄酒二两左右，加入少量酱油，尝一下味道，嫌淡的话可以加少许盐#\n8. 汤汁基本收干，撒上葱花和胡椒粉，稍微拌一下，出锅#'),(1089,'独家韭菜炒豆腐干','素菜','豆腐干#\n韭菜#\n猪肉#\n豆瓣#\n泡椒#\n花椒，盐，味精，老姜#','3块#\n100g#\n35g#\n适量#\n3个#\n适量#','1. 韭菜切节，豆腐干切切细条（丝）备用。泡椒切粹，猪肉切丝备用。如图所示。#\n2. 架锅放油30ml 烧至7成热，放豆瓣，花椒，泡椒，老姜下去炒15秒，然后放肉丝、盐炒20秒，再放豆腐干下去继续炒20秒。这时放50ml 水到锅内大火炒20秒(加水是为了高温消毒灭菌)后减小火力放韭菜到锅内再炒25秒。#\n3. 韭菜（韭黄）最后放是为了保持韭菜避免炒老，放韭菜前需要确定锅内菜的咸淡，适合口味后再放韭菜。起锅前放点味精或鸡精即可。此菜做法比较简单，几乎是一学即会。#'),(1090,'素炒菠菜胡萝卜','素菜','胡萝卜#\n菠菜#\n植物油#\n盐#\n老抽#','一个#\n4颗#\n适量#\n适量#\n少量#','1. 将菠菜和胡萝卜洗净 然后菠菜分段 胡萝卜切块 备用#\n2. 在锅内加适量植物油#\n3. 待油热 倒入胡萝卜翻炒#\n4. 然后向锅内倒入少许老抽 继续翻炒#\n5. 待胡萝卜炒至七成熟时将备好的菠菜倒入锅中一起翻炒 加适量盐 并再次倒入少许老抽#\n6. 随即便可出锅#'),(1091,'豉油鸡简易版','荤菜','童子鸡一只#\n食用油#\n生抽#\n麻油#\n冰糖#\n生姜葱#','700g#\n一碗#\n一碗#\n一勺#\n35g#\n少许#','1. 鸡洗干净 泡五分钟 去除血水 放入锅中放入葱姜  倒入食用油一碗 吃饭的碗 大小#\n2. 倒入生抽一碗 如果生抽偏咸 适量减少用量#\n3. 麻油一勺 这里贪方便了 直接用碗了#\n4. 放入冰糖 冰糖我是选用黄冰糖#\n5. 开火 大火烧开转小火 20分钟 中间翻次身 20分钟后 用筷子插下 能轻松插入 就是熟啦 关火 取出放入盘子 晾凉 切块#'),(1092,'素炒油麦菜','素菜','油麦菜#\n配菜【蒜末】#','2棵#\n适量#','1. 油热好，放蒜末爆香！#\n2. 把有卖菜切段倒入锅中翻炒，后放盐和鸡精！#\n3. 好看又美味的油麦菜就可以起锅啦！#'),(1093,'椒盐虾','荤菜','海虾#\n椒盐#\n大蒜#\n橄榄油#\n萝卜丝#','200g#\n20g#\n2颗#\n稍多#\n10g#','1. 先将虾去头，去背上的腥线，洗净备用。#\n2. 将锅烧热放比平时炒菜多些的橄榄油（个人喜好，可以换），感觉快冒烟时放入虾，煎至虾尾弯曲，表面金黄，撒上椒盐出锅装盘。#'),(1095,'凉拌腰花片','荤菜','猪腰#','2只#','1. 将腰花片成薄片，滚水烫到变色定型就沥出备用。#\n2. 调凉拌汁，葱姜蒜末，辣椒油，生抽，糖，醋，芝麻油，盐，味精，花椒油，拌均匀，淋在腰花片上，拌匀装盘。#'),(1096,'秋葵炒蛋','荤菜','秋葵#\n鸡蛋#\n油#\n葱#\n盐#','250g#\n2个#\n适量#\n适量#\n适量#','1. 秋葵横着切小段备用#\n2. 鸡蛋打散备用#\n3. 锅内放油炒鸡蛋，炒好后盛出，以免炒太老#\n4. 锅内加入适量油，放入葱花炒香后倒入秋葵翻炒均匀后倒入炒好的鸡蛋，调入盐翻炒均匀，再翻炒片刻即可#\n5. 出锅装盘！#'),(1098,'凉拌樱桃萝卜','素菜','樱桃萝卜#\n盐#\n糖#\n醋#\n味精#\n蒜末#','一把#\n适量#\n适量#\n适量#\n少许#\n2瓣#','1. 把萝卜缨子摘下来，洗净，放入盆中加盐腌一会儿#\n2. 把樱桃萝卜去头尾，切片（没照照片），切完后萝卜缨子也都腌倒了，可以把水倒掉#\n3. 放入萝卜片，蒜末，盐，糖，醋，味精，搅拌均匀。#\n4. 装盘，是不是很漂亮呢？#'),(1099,'白菜炒蚕蛹（家常）','荤菜','蚕蛹，白菜，葱，姜，蒜，食用油，盐，酱油，花椒面，味精#','#','1. 蚕蛹焯熟，备用！#\n2. 白菜切片，备用！#\n3. 葱姜蒜切好，备用！#\n4. 锅内加食用油，加葱，姜！#\n5. 加蚕蛹，翻炒，加盐，继续翻炒！#\n6. 加白菜，翻炒！#\n7. 加花椒面，酱油，继续翻炒！#\n8. 翻炒至食物都熟了，加蒜，味精，翻炒出锅！#\n9. 出锅啦！#'),(1103,'蘑菇炒肉片','荤菜','蘑菇#\n猪肉#\n料酒#\n盐#\n生粉#\n食用油#','#\n#\n#\n#\n#\n#','1. 准备好所需要的材料#\n2. 将猪肉切成薄片，加少许盐，料酒，生粉搅拌均匀，腌制十分钟左右，这样可以肉嫩一点。#\n3. 将蘑菇切成薄片。#\n4. 锅中倒少许油#\n5. 待油烧热后加入腌制好的肉片翻炒。#\n6. 待肉变色后倒入蘑菇翻炒。#\n7. 等蘑菇炒出水份后加盖煮个两分钟左右即可。#\n8. 装盘即可。#'),(1104,'最简单的红烧肉','荤菜','五花肉#\n生姜#\n朝天椒#','500g#\n10g#\n5个#','1. 五花肉切成这样的方块就好了，刀一定要磨快一点哦#\n2. 凉水下锅#\n3. 煮成这样，捞起来#\n4. 放油，加白糖，炒至微微焦黄，这个步骤很重要，个人不是很爱吃甜的，所以糖放的比较少，你们随意~(一定要小火！！)#\n5. 下锅把糖均匀的裹在五花肉的表面#\n6. 加入生姜片和朝天椒#\n7. 放入少量的料酒，生抽，一点点的醋#\n8. 肉炒到表面泛黄就加水小火闷大概20分钟#\n9. 最后大火收汁，摆盘放葱花和柠檬片就大功告成了(炒的过程中放一点点柠檬汁和蜂蜜味道更好哦~)#'),(1106,'蒜仔烧茭白','素菜','大蒜#\n葱#','#\n#','1. 鲜茭白4棵，蒜仔若干#\n2. 茭白切成滚刀段#\n3. 由于是烧制菜肴，所以锅中倒足量油，中火烧热#\n4. 放入葱和蒜仔炒香#\n5. 倒入茭白煸炒，大火，用铲子不停翻炒至所有材料都裹上油#\n6. 炒至蒜仔和茭白都呈金黄色，改中火。#\n7. 倒入适量鲜酱油上色，加少量耗油和鸡精提香，加盐调味。翻炒至色泽金红即可，关火出锅。#\n8. 装盘，美味出炉！鲜甜可口，解酒必备哦！#'),(1107,'炒绿豆芽','素菜','新鲜绿豆芽500克#\n花椒#\n植物油#\n白醋#\n食盐#\n味精#','500克#\n少许几粒#\n适量#\n少许#\n少许#\n适量#','1. 豆芽洗净水淋干，油锅烧热，花椒入锅，烹出香味，#\n2. 将豆芽下锅 爆炒几下，倒入白醋继续翻炒数分钟，起锅时放入食盐、味精，装盘即可。#'),(1108,'酥炸花椒芽','素菜','花椒芽#\n鸡蛋#\n面粉#\n盐#\n糖#','200g#\n1个#\n70g#\n2g#\n2g#','1. 花椒芽洗净控水，面粉、鸡蛋盐调一个面糊；#\n2. 将花椒芽跟面糊混合，静置五分钟；#\n3. 锅上火，坐油烧至五成热；将挂好糊的花椒芽入锅，炸至酥脆捞出控油即可上桌。#'),(1109,'无添加剂无硫磺~自制笋干','素菜','竹笋#\n盐#','10斤#\n适量#','1. 竹笋选又矮又胖，且色白的，这种的笋比较嫩。这次没选好，先剥去壳。#\n2. 先一切二#\n3. 再切丝，切得越细，晒干越快。#\n4. 切好的笋丝#\n5. 煮锅水，加了4勺盐，#\n6. 倒入笋，煮开后，煮上几分钟。#\n7. 沥干水分。#\n8. 在太阳底下暴晒上三五天，即可，天气好的情况下，两天就可以了。#\n9. 完成了，再也不用担心买到硫磺熏过的笋干了。#'),(1110,'茄汁草菇鸡蛋','荤菜','草鸡蛋（小）#\n草菇#\n番茄沙司#\n糖#\n盐#\n葱末#','6只#\n400g#\n适量#\n适量#\n少许#\n少许#','1. 准备好蛋液。#\n2. 草菇有点大，切成小瓣，入开水汆一下，去草酸。热锅冷油（油稍多点），等油热，倒入蛋液，至蛋成形，放入草菇一同翻炒，时间不要太久，鸡蛋老了就不好吃了。#\n3. 先放沙司和糖，等鸡蛋吸收了酸甜味，最后放盐，一盘酸酸甜甜、滑滑嫩嫩的茄汁草菇鸡蛋做好了。#'),(1111,'麻香糖醋藕','素菜','莲藕#\n大葱#\n大蒜#\n花生油#\n酱油#\n醋#\n白糖#\n辣椒#','两节约4两#\n一根#\n2小颗#\n适量#\n半茶匙#\n1茶匙#\n1茶匙#\n2根#','1. 莲藕切均匀的薄片，这样熟得快。葱白跟葱花切开分开放。蒜也切片。辣椒切小圈圈，美观。（姜是乱入的，我另一道菜-_-#）#\n2. 锅烧干，放油。油热之后放蒜下去爆香，等蒜变成金黄色（闻到香味）就放入藕片。炒至藕片都变色。#\n3. 放入酱油和醋，入色均匀后放入白糖炒。#\n4. 放入葱花跟辣椒，翻炒一分钟，出锅。#'),(1113,'清炒藕片','素菜','藕#\n干木耳#\n胡萝卜#\n芹菜#\n蒜#\n盐#\n油#\n葱#','1节#\n少许#\n1/2根#\n1小段#\n1/2头#\n#\n#\n#','1. 提前2个小时将干木耳泡水。藕去皮切片，胡萝卜切片，芹菜切成小段。葱，蒜切成碎片。#\n2. 将切好的藕片，胡萝卜片，芹菜段，以及泡好的木耳一起下锅焯水。然后用凉水过一遍，捞出沥干。#\n3. 锅中倒油，下葱花蒜爆香，倒入焯好的藕，胡萝卜，芹菜，迅速煸炒，加盐调味。出锅前撒一点鸡精即可。#'),(1114,'番茄肉沫豆腐','荤菜','番茄#\n豆腐#\n肉沫#\n葱#','一个#\n一块#\n250g#\n#','1. 一   少许油煎豆腐，不用锅铲，直接翻锅，煎至金黄色。出锅。二   起锅，加入大蒜，热了加肉沫翻炒，肉沫是加入酱油腌制五分钟。三   待肉七分熟加入番茄，中火翻炒。加入糖，和盐。翻炒一会。四    加入豆腐和葱。翻锅，加点点水。待收汁出锅。#'),(1115,'蒜薹炒肉','荤菜','蒜苔#\n熟肉#','#\n#','1. 蒜苔切好装盘#\n2. 家人喜欢熟肉，用的熟肉，可以用生肉代替哈。这个随意#\n3. 蒜切好#\n4. 油锅烧热，下蒜。#\n5. 下入蒜苔，生抽两勺，酱油三勺（铲勺）盐三勺，味精两勺（小勺）因为后面要加水，所以放的多一些。否则淡的不要不要的。#\n6. 加水，大火煮。然后转小火。蒜苔不好熟。#\n7. 最后加入熟肉，因为本身就是熟的，只是为了增加香味。用生肉的要先放入肉炒哦。#\n8. 炒片刻，就可以吃啦！#'),(1117,'酱爆三丁','荤菜','黄瓜#\n胡萝卜#\n鸡肉#\n淀粉#\n姜#\n葱#\n白胡椒粉#\n料酒#\n盐#\n辣黄豆酱#','80G#\n90G#\n250G#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备所有食材#\n2. 把鸡肉、胡萝卜、黄瓜均切丁。葱姜切碎。#\n3. 鸡丁加盐、料酒、白胡椒粉、葱姜水、淀粉腌制。#\n4. 油热放胡萝卜丁、黄瓜丁炸好出锅。#\n5. 鸡丁炸至变为白色出锅。#\n6. 放底油把酱炒香（可适当加一点点水）#\n7. 放炸好的胡萝卜丁、黄瓜丁、鸡丁翻炒。#\n8. 好了，盛盘吧。#'),(1119,'蒜末空心菜','素菜','空心菜#\n大蒜#\n盐#\n鸡精#','300g#\n4瓣#\n适量#\n适量#','1. 把空心菜择好洗干净沥干水！注意菜杆不要扔掉！空心菜杆最好吃#\n2. 把大蒜切成碎末#\n3. 起锅放油，等油烧到8成热，把空心菜放进去翻炒，炒一下把蒜末放进去，火候一定要大，快炒熟的时候，把盐放进去，要一定盐最后放，放早了青菜容易出水！就不好吃了#\n4. 成品！是不是翠翠绿绿的！很有食欲#'),(1120,'洋葱炒鸡蛋','荤菜','洋葱#\n鸡蛋#\n调料#','一个#\n2只#\n#','1. 将洋葱剥皮 洗净 切成片#\n2. 将鸡蛋打散备用#\n3. 加入适量油 将蛋液倒入其中 形成蛋饼状盛出#\n4. 倒入洋葱翻炒至变色#\n5. 再加入蛋饼翻炒两分钟左右 加入盐 鸡精 胡椒粉 翻炒均匀 盛出#\n6. 简简单单的洋葱炒鸡蛋就完成啦#'),(1121,'五彩杏鲍菇','素菜','杏鲍菇#\n青椒#\n红椒#\n黑胡椒、盐、姜#','3个#\n1个#\n1个#\n少许#','1. 将食材洗净并切片以备用#\n2. 用沸水把杏鲍菇煮熟，捞出以备用；少许油倒入锅中，放入青椒、红椒、杏鲍菇、胡椒、盐，炒至青椒红椒去生即可。#'),(1123,'酸菜排骨','荤菜','八角#\n盐#\n花椒#\n葱#\n姜#','#\n#\n#\n#\n#','1. 排骨焯水洗去肉末待用。#\n2. 锅内放油放入花椒八角爆香，加入排骨煸炒，变色后放入高压锅内，加水，压二十分钟左右。#\n3. 酸白菜洗净,挤去水份切丝。#\n4. 炒锅内放油加入葱姜炒香，放入酸白菜炒到出水后，加入排骨一起炖。#\n5. 依个人口味适量加入盐,熟后出锅。#'),(1124,'糖醋肉','荤菜','红椒#\n黄椒#\n洋葱#\n蒜#\n姜#\n醋#\n生抽#\n淀粉#','一个#\n一个#\n一个#\n#\n#\n#\n#\n#','1. 里脊肉切成1cm见方长条，加入盐，料酒，生抽，淀粉腌制半小时#\n2. 将洋葱，红黄彩椒切成片待用#\n3. 姜蒜切片待用#\n4. 调制面糊。两个蛋清加入少许淀粉和5勺面粉，加适量清水调至糊状待用#\n5. 取一小碗，加入盐，生抽，食醋，糖，番茄酱，少量淀粉调成汁一旁待用#\n6. 起油锅，将里脊肉裹上面糊入油锅#\n7. 两面金黄后出锅#\n8. 全部好后再入锅复炸，逼出油#\n9. 另起锅，煸香姜蒜片后加入配料翻炒，加入里脊肉和调好的酱汁，待大火收干即可盛出#\n10. 完成#'),(1125,'喵氏清炒土豆丝','素菜','土豆#\n青椒#\n大蒜#','2个#\n5个#\n2瓣#','1. 土豆刮皮，辣椒洗净，大蒜去皮。#\n2. 沿辣椒生长方向将其划破，将里面的辣椒籽去除，展平，切丝；大蒜瓣切丝。#\n3. 土豆切丝，并放入冷水中浸泡，可撒少量食盐，这样既可以保持土豆丝色泽鲜艳，又可以减少粘锅。#\n4. 将锅烧干，放入适量食用油，待油滚烫时放入切好的辣椒，翻炒，熟透后装盘。#\n5. 将土豆丝沥干。锅洗净，烧干，放入适量油，待油温80度左右，调至中火，放入土豆丝，翻炒。待土豆8分熟后放入炒好的辣椒，放入适量食盐，拌匀，起锅，装盘。#'),(1126,'茄汁沙丁鱼','荤菜','沙丁鱼#\n番茄酱#\n韩式辣酱#\n黄酒#\n豆豉#\n葱姜蒜#\n八角#\n小茴香#\n糖#\n盐#\n清水#\n老抽#','1000克#\n400克#\n150克#\n1勺#\n1勺#\n1小盘#\n1个#\n几粒#\n1勺#\n1小勺#\n半杯#\n1勺#','1. 准备材料。#\n2. 所有的固体原料装锅。#\n3. 把液体原料淋在上面。#\n4. 高压锅，选择豆类那一档。大约1小时。#'),(1128,'炸酱面','主食','五花肉、干黄酱、面条、黄瓜、食用油、老抽、 花椒、五香粉、蛋清一个、姜末#','#','1. 五花肉用适量五香粉、老抽、姜末，蛋清一个拌匀，腌制片刻。#\n2. 开水泡香菇#\n3. 去根，洗净。#\n4. 切碎#\n5. 炒锅内放适量食用油，放少量花椒。花椒变色后，放入五花肉炒。#\n6. 加入干黄酱、适量开水转小火#\n7. 熟后盛出。#\n8. 黄瓜洗净后切丝。#\n9. 烧水煮面。#\n10. 盛面，浇酱。#\n11. 开吃，香喷喷。#'),(1130,'潮汕焖鱼常见搭配之——【菜脯焖淡甲鱼】','荤菜','淡甲鱼#\n菜脯#\n蒜#\n葱#\n盐#\n食用油#','中型大小2条#\n少许#\n少许#\n少许#\n少许#\n适量#','1. 淡甲去鱼鳞、内脏，洗净切段，用少许盐腌30分钟；#\n2. 菜脯洗净，切薄片；#\n3. 蒜去皮洗净切成蒜末；葱去头洗净切段；#\n4. 烧热炒锅，下适量油，爆香蒜末；#\n5. 蒜香味爆出来后，下菜脯煸炒出香味；#\n6. 下鱼块；#\n7. 稍许翻动鱼块；#\n8. 加入开水，并调入少许盐；#\n9. 盖上锅盖，中小火焖煮；#\n10. 焖至水变少变浓稠，开盖加入葱段，关火继续盖上盖子焖2分钟；#\n11. 2分钟后，开盖装盘即可。#'),(1131,'回味无穷——卤水翅爪','荤菜','鸡全翅#\n凤爪#','5只#\n5只#','1. 先来个大合照#\n2. 买回来鸡全翅一分为三，鸡翅凤爪汆烫下，目的为了去掉血腥味，油锅煎下鸡翅到微黄！#\n3. 加入凤爪，倒入味极鲜酱油,老抽，翻炒上色。#\n4. 加入八角，小茴，香叶，注入水淹没到食材即可！大火烧开，转中火，烧至汤汁快收干！#\n5. 装盘，洒上点白芝麻更香！#\n6. 这一盘卤水翅爪没有加到一丁点盐，酱油的咸味已足够！#'),(1132,'豆腐脑','素菜','豆子#\n葡萄糖内脂#\n木耳#\n瘦肉#','#\n#\n#\n#','1. 豆子清洗干净，泡６个小时，木耳泡开。#\n2. 用豆浆机打碎#\n3. 把用凉水融好的一小勺内脂倒入８０度左右的豆浆中，静止半小时，豆腐脑终于做成功了！#\n4. 切点肉丝木耳做卤#\n5. 用勺子舀了一碗豆腐脑，浇上做好的肉卤#'),(1133,'螃蟹炒年糕','荤菜','梭子蟹#\n年糕#\n小青菜#','2只#\n3条#\n若干#','1. 螃蟹去壳、去腮，洗净切小块；年糕切薄片；小青菜洗净。#\n2. 热锅倒油，待油热下螃蟹块，加少许水，快速翻炒。#\n3. 螃蟹变色基本炒熟，下年糕翻炒，加耗油（或盐、少许酱油）。#\n4. 年糕稍软加小青菜，翻炒至熟，装盘。#'),(1134,'辣椒炒豆腐干豆芽','素菜','大蒜#\n豆腐干#\n辣椒#\n五花肉#\n盐#\n味精#\n十三香#\n老抽#\n淀粉#','#\n#\n#\n#\n少量#\n#\n#\n#\n#','1. 五花肉.葱花.大蒜.切好备用.#\n2. 豆干.豆芽.清洗好备用.#\n3. 辣椒切好备用#\n4. 锅中放入油.烧熟后.小火晾晾#\n5. 放入五花肉小火煸炒至五花肉表面焦黄.#\n6. 小火放入葱花.大蒜煸炒出香味.后放入十三香.酱油.少量老抽上色后#\n7. 放入豆芽煸炒到豆芽变软.#\n8. 后依次放入豆干.辣椒.盐.煸炒一会#\n9. 水淀粉调好后.大火淋入菜中后添加味精.#\n10. 美味的豆芽豆干炒辣椒就做好了#'),(1135,'双椒蛏子','荤菜','蛏子#\n剁椒， 红和黄#\n香葱花#\n海鲜生抽#\n油#','500g#\n各2大匙#\n3-4大匙#\n1-2大匙#\n2-3大匙#','1. 鲜活蛏子吐泥沙... 用可以上笼蒸的盘子把洗刷好的蛏子摆两排， 一排上铺黄剁椒， 另一排红剁椒。水烧开，上笼蒸10-15；俩种剁椒中间铺香葱花， 淋上生抽。 同时， 另一小锅烧烈热油， 浇上去！ 做好了！#'),(1137,'黄鳝烧茄子','荤菜','黄鳝#\n茄子#\n调味料：生姜，葱，料酒，盐，糖，老抽，生抽#','500g#\n3只#\n适量#','1. 黄鳝宰杀清洗干净，切成段备用。#\n2. 茄子改刀切成滚刀块备用。#\n3. 炒锅倒油适量，大火烧热，放入生姜煸出香味，倒入黄鳝翻炒，倒入料酒去腥味。#\n4. 黄鳝煸炒后，加入老抽上色，加盐，糖调底味，加水没过黄鳝，大火烧开后，加盖中火焖烧15分钟左右。#\n5. 黄鳝焖烧后，倒入茄子，大火翻动，加盖转中火继续焖烧5分钟左右，至茄子烧塌即可。#\n6. 大火收汁，加盐，糖，生抽调好口味即可，注意留汤汁略宽些。#\n7. 成品菜装盆，此菜品黄鳝肉骨分离，酥软可口，茄子软糯，茄香浓郁，营养丰富。#'),(1139,'世界上最简单却最美味的汤——清汤甩穗','汤','鸡蛋#\n香菜#\n葱#\n味极鲜一品鲜酱油#\n盐#\n香油#','#\n#\n#\n#\n#\n#','1. 水中入虾皮葱丝烧开；#\n2. 碗中放入酱油和盐；（自己掌握量）#\n3. 放入紫菜和香菜；#\n4. 水烧开后倒入打散的鸡蛋立即关火；#\n5. 将锅里的全部倒入放了紫菜香菜的盆碗中即可，最后滴入香油。#'),(1141,'少油的肉末茄子','荤菜','瘦肉#\n茄子#\n大蒜#\n杭椒#\n郫县豆瓣#','100g#\n3个#\n2个#\n1个#\n2小勺#','1. 我选的是白茄子，去皮，切成网络型。#\n2. 切好的茄子隔水上锅蒸。#\n3. 蒜和辣椒切成碎粒。#\n4. 瘦肉切成肉末，锅烧热放油，炒熟。#\n5. 豆瓣酱#\n6. 肉末炒好加豆瓣酱煸香，放入切好的蒜泥和辣椒碎，加少许盐，俩滴酱油提色，2小勺生抽，一勺黄酒。#\n7. 这时候茄子也蒸熟了，到入豆瓣酱锅里，翻炒俩下，彻底入味、放点鸡精出锅。#\n8. 成品，装盘洒点葱末、白茄子味微甜，细腻，入口即化。加上肉末豆瓣酱蒜泥的香味，加上一碗米饭美极了。#'),(1142,'家常版大丰收','素菜','金瓜#\n土豆#\n豆角#\n黏玉米#','一个#\n两个#\n一把#\n一根#','1. 金瓜和土豆切块，豆角掰成小段#\n2. 黏玉米切成小段#\n3. 锅中热油，放入金瓜和土豆翻炒后加豆角段炒匀#\n4. 最后放黏玉米段#\n5. 添少许汤小火炖一会儿，直到所有原料都熟了，汤汁收浓#\n6. 调味，出锅前撒点葱花和蒜末就ok了！#'),(1143,'尖椒炒鸡丁','荤菜','鸡胸肉#\n尖椒#\n盐#\n糖#\n鸡精#\n酱油#\n生粉#','一块#\n1个#\n#\n#\n#\n#\n#','1. 鸡丁里加适量糖盐鸡精酱油生粉腌制一会儿#\n2. 油热蒜末爆香#\n3. 加鸡丁翻炒到边缘变色#\n4. 加尖椒继续翻炒#\n5. 加少量清水酱油跟盐 均匀出锅#'),(1145,'海香菇爆炒鸡杂','荤菜','鸡杂#\n海鲜菇#\n辣椒#\n豆瓣酱#\n生姜#\n蒜头#\n酱油#\n蚝油#\n糖#\n五香粉#\n鲍鱼汁#\n海鲜酱#\n辣椒粉#\n料酒#\n盐焗粉#\n生粉#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 食材洗好备用#\n2. 把鸡杂切好用料酒、盐焗粉、海鲜酱、蚝油、酱油、辣椒粉、生姜腌制备用#\n3. 锅热好后下入姜蒜爆香后放入适量豆瓣酱炒香#\n4. 炒香豆瓣酱后下入鸡杂#\n5. 鸡杂炒到六七分熟下入海鲜菇#\n6. 在炒制的过程中用鲍鱼汁、蚝油、辣椒粉、糖、五香粉、酱油调制在一起#\n7. 海鲜菇炒的差不多熟了就下入辣椒#\n8. 辣椒下入后把调制好的酱汁一起入锅炒均匀#\n9. 最后用生粉勾芡下汤汁#'),(1146,'＃自己做更健康＃之老菜创新菜宫保三样','荤菜','主料：鸡小胸#\n鲜虾，花生。#\n青红椒，黄瓜。#\n祘，葱#\n调料：料酒，白胡椒，盐，糖，辣椒酱，红油豆瓣酱，生抽，香油。#\n辅料：魔玉花，#','3条#\n适量#\n适量#\n适量#\n少许#\n适量#','1. 鲜虾去头去沙线，鸡小胸洗净切块与鲜虾加盐，胡椒，料酒，水淀粉调底味备用。#\n2. 青红椒洗净切块，黄瓜洗净切斜小块（半条）祘四辨切片备用。#\n3. 花生用油炸熟备用。#\n4. 锅底放油煸炒鸡肉鲜虾魔玉变色下葱祘爆出香味加料酒，辣椒酱，红油豆辨（各一勺）煸炒放糖，盐，生抽，香油，加少许高汤后放青椒黄瓜花生淋少许水淀粉即可。#\n5. 宫保三样#'),(1147,'西红柿土豆咸笋汤','汤','西红柿#\n土豆#\n咸笋#\n盐#\n油#\n姜丝#','一个#\n半个#\n10根#\n少量#\n少量#\n少许#','1. 西红柿和土豆洗净，切成丁。#\n2. 咸笋先需要在清水中浸泡，洗到附在上面的盐，再浸泡10分钟。再将咸笋切成细丝。#\n3. 油锅烧热，倒入土豆丁，翻炒出香味，倒入西红柿丁，再翻炒出汤汁。此时加入咸笋丝，翻炒1分钟。#\n4. 再加入清水淹没过主料，倒入盐调味。调成小火，慢炖。待土豆变软，即可出锅。#'),(1148,'【家乐浓汤宝】油泡豆芽青菜汤—做在冬至','汤','豆芽菜#\n青菜#\n浓汤宝#\n油#\n水#\n香菜#','100g#\n6颗#\n1个#\n少许#\n1000ml#\n少许#','1. 先将油泡用剪刀从中间剪开，（方便塞肉）过一下热水，快速拿出来，如果过水太久，油泡就没有嚼劲啦。待油泡冷却后，就可以将事先整理好的肉末塞入油泡中，直接包好，不需要特别封口。#\n2. 将事先准备好的豆芽菜在锅中翻炒一下，加入大概1000ml水，放入浓汤宝一个，再放入包好的肉末油泡，煮开后饭入青菜，少许香菜即可。#\n3. 美味的汤出炉咯。#\n4. 非常好喝，肉也是鲜嫩多汁。#'),(1149,'清蒸茄子','素菜','茄子#\n青椒#\n小米辣#\n蒜#\n葱油，香油，味精，鸡精#','四个#\n五个#\n五个#\n四五个#\n适量#','1. 将小米辣剁碎，放入碗中，依次加入葱油，盐，鸡精，味精#\n2. 再将青椒也剁碎#\n3. 还有蒜#\n4. 然后把他们都放进装小米辣的碗里#\n5. 把茄子洗干净放入锅中蒸熟#\n6. 在茄子蒸好后，把先做好的调料中加入开水调好，将茄子放入盘中，再将调料水淋上去，最后再放入锅中蒸十分钟就可以吃了#'),(1150,'尖椒平菇快炒素鸡','素菜','小尖椒#\n素鸡#\n平菇#\n生抽 醋 耗油 姜丝 盐#','6个#\n4-5片#\n3-4个#\n适量#','1. 尖椒切丝素鸡切条 平菇切片#\n2. 平菇下锅煎至金黄后。依次加入尖椒 素鸡 生抽 醋翻炒   加耗油及少量水。收汁出锅～#'),(1151,'土豆泥沙拉球','素菜','土豆#\n玉米粒#\n豌豆#\n胡萝卜#\n盐#\n香油#','2个#\n少量#\n少量#\n少量#\n少量#\n少量#','1. 土豆去皮，切厚片。下冷水锅里煮。锅里放少量盐。一点点就可以了。#\n2. 利用煮土豆的时间，把胡萝卜切小丁。玉米粒、豌豆粒洗净待用。#\n3. 土豆用筷子戳一下，很轻易就能穿透的时候土豆就好了。取出放在一边。#\n4. 把玉米粒、胡萝卜丁、豌豆下开水了焯一下。焯五分钟。取出控干水分。#\n5. 用勺子把土豆压成泥。加入少量盐，几滴香油。把玉米粒胡萝卜丁豌豆倒入土豆泥中搅拌。带上一次性手套。用手团成圆子。然后摆在盘子里。淋上沙拉就完成了。#\n6. OK#'),(1153,'水煮黄鸭叫','荤菜','黄鸭叫#\n青辣椒#\n姜#\n蒜#\n生菜#\n盐#\n鸡精#','四只#\n一个#\n一粒#\n一颗#\n几片#\n少许#\n少许#','1. 1. 黄鸭叫去内脏，去鳃，用盐料酒腌制半小时#\n2. 2. 把姜，大蒜，红辣椒，紫苏切碎。取一个新鲜的青辣椒切碎，不嗜辣的朋友可以把青椒换成葱花哦#\n3. 3. 生菜折小断#\n4. 4. 锅烧热，放油炸黄鸭叫，炸黄出锅#\n5. 5.  剩下的油倒入姜，红辣椒，大蒜爆炒后倒入黄鸭叫翻几下，倒水直至水煮直奶才色后，加盐和鸡精，再加入紫苏和青辣椒。#\n6. 6. 放生菜翻滚一下即可。#\n7. 7.  装盘，大功告成。#'),(1154,'跳跳鱼','荤菜','洋葱#\n葱花#\n姜沫#\n紫苏#\n香菜#\n蒜头#\n朝天辣椒#\n小米泡椒#\n生抽#\n盐#\n料酒#','1个#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n少许#','1. 准备好所有食材#\n2. 一锅水加2勺盐煮开后下鱼，滴少许料酒，煮断生#\n3. 煮到刚熟盛出，不能煮过就不鲜嫩了#\n4. 锅内加多点油，然后下蒜、姜、洋葱、朝天辣椒、小米泡椒、鸡腿菇翻炒片刻，加入适量生抽#\n5. 加入葱花、香菜沫、紫苏继续翻炒#\n6. 加入适量盐调味#\n7. 盛入淋在刚才的鱼上#\n8. 点火，煮一会入味#\n9. 开吃！#'),(1155,'可乐鸡翅','荤菜','鸡翅8个#\n可乐一瓶#\n生姜片、葱适量#\n老抽2勺#','#\n#\n#\n#','1. 鸡翅洗净用油生姜葱煸炒一下后直接倒入可乐即可#\n2. 大火烧15分钟后加入老抽在烧10分钟即可#'),(1156,'培根金针菇卷','荤菜','培根#\n金针菇#','8-10片#\n300g#','1. 取培根中间切开#\n2. 依次排好#\n3. 金针菇洗干净沥干水分#\n4. 金针菇取适量对折，卷入培根卷好，穿入牙签固定#\n5. 平底锅热油后放入卷好的金针菇，两面煎熟，出锅～#'),(1157,'桂花山药泥','甜品','山药棍#\n糖桂花#','1根#\n适量#','1. 洗净山药棍#\n2. 放入蒸锅蒸10-15分钟#\n3. 用勺将蒸好的山药棍捣成泥#\n4. 根据个人口味加入糖桂花，搅拌均匀#\n5. 用模子将山药泥做成自己喜欢的样子，就大功告成啦Y(^_^)Y#'),(1158,'杂蔬天妇罗 深夜食堂改良版','素菜','鸡蛋#\n面粉#\n淀粉#\n盐#\n香菇#\n秋葵#\n藕片#\n土豆片#\n辣椒#\n茄子#\n虾#','1只#\n100g#\n30g#\n10g#\n5只#\n3只#\n50g#\n50g#\n2只#\n1条#\n9只#','1. 调浆汁，加一块冰到浆汁里更好#\n2. 虾去壳，并挑去虾线#\n3. 蔬菜，切条或者片#\n4. 蔬菜：藕片，土豆片#\n5. 挂汁后入油锅炸#\n6. 沥油#'),(1159,'小炒鸡','荤菜','鸡腿#\n芹菜#\n葱头#\n泡椒#\n葱#\n姜#\n蒜#\n盐#\n料酒#\n生抽#\n淀粉#','200克#\n50克#\n20克#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 原料图片#\n2. 仔鸡腿去骨，切成条，用盐、料酒、淀粉上浆#\n3. 芹菜择洗干净，切段；葱头切条#\n4. 泡椒切段，葱、姜、蒜切碎#\n5. 热锅凉油下入鸡肉炒断生#\n6. 放入泡椒、葱、姜、蒜炒出香味#\n7. 再放入芹菜、葱头及调料#\n8. 翻炒均匀#\n9. 装盘#'),(1160,'橄榄菜四季豆炒肉丁','荤菜','猪肉#\n四季豆#\n橄榄菜#\n洋葱#\n红椒#\n蒜头#\n盐#\n油#\n生抽#\n鸡精#','#\n#\n#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 四季豆摘掉两端，并拉出丝，洗干净切成丁，红椒切丁，洋葱切丁，蒜头切丁，备用#\n2. 猪肉洗干净剁成肉丁，用一点点生抽腌制5分钟#\n3. 下少许油热锅，加入肉丁迅速翻炒至变色，盛出备用#\n4. 继续下油热锅，下四季豆翻炒至变色并软熟，盛出备用#\n5. 把锅用清水洗一下，热锅后加少许的油，把蒜丁爆香，加入洋葱丁，红椒丁，炒出香味后，倒入四季豆，肉丁，翻炒一下，加入一勺橄榄菜，炒匀，最后加盐和鸡精调味即可#'),(1161,'青豆炒虾仁','荤菜','海麻虾#\n新鲜带荚青豆#\n油#\n绍酒#\n青葱#\n蒜#\n糖#\n盐#\n火腿茸#','600 克#\n350 克#\n2 汤匙 1 茶匙#\n2 茶匙#\n2 棵#\n1 瓣，拍扁#\n1 茶匙#\n适量#\n1 汤匙（ 随意）#','1. 置中式易洁锅在中大火上，下油2汤匙，加入葱粒爆炒至软，挑散虾仁，放下锅内，不停铲动至虾仁变色分散，洒酒，然后铲出。#\n2. 放锅回火上，加少许油，爆香蒜瓣，夹出弃去， 下青豆炒至翠绿，并洒下水2汤匙，加盐、糖调味。#\n3. 虾仁回锅，拌入火腿茸炒匀，试味，上碟趁热供食。#'),(1164,'滑蛋虾仁','荤菜','虾仁#\n鸡蛋#\n西兰花#','15只#\n3只#\n1个#','1. 西兰花灼熟#\n2. 腌虾仁的盐分成两次放，中间隔十分钟，这样虾仁质感会Q弹#\n3. 鸡蛋加少量盐打匀，#\n4. 虾仁放油锅炒半分钟，推至锅边，再放入蛋液快速炒十秒，把虾仁放到蛋里一起炒十秒，完成啦#'),(1165,'冬季大补菜—红炖羊肉','荤菜','羊肉#\n胡萝卜#\n葱姜蒜#\n花椒大料香叶八角#\n干红辣椒#\n啤酒#\n老抽 生抽 酱油 白糖#','500g#\n2根#\n若干#\n若干#\n3个#\n1瓶#\n若干#','1. 所有食材洗干净 羊肉 胡萝卜切块待用 固体佐料待用#\n2. 热锅放油 加入葱姜蒜花椒大料香叶 炸香#\n3. 待佐料炒出香味之后放羊肉翻炒 加入生抽 老抽 白糖 盐直至羊肉变色#\n4. 加入一瓶啤酒，此时要开始把火调小，盖上锅盖炖二十分钟#\n5. 加入洗净切好的胡萝卜继续小火慢炖二十分钟，此时羊肉的香味已经可以闻到啦～二十分钟之后就可以出锅啦～#'),(1166,'葱爆羊肉','荤菜','大葱#','#','1. 羊肉，胡萝卜，大葱切片准备好，姜切丝待用。喜欢麻辣的的可以适量放入花椒，干辣椒。#\n2. 油烧热放入姜丝爆香，倒入切好的羊肉（用的是去骨羊排，喜欢肥瘦夹杂的感觉，怕油的可以用羊腿肉。羊肉多少煮熟处理好的。），煸炒出香味儿#\n3. 放入胡萝卜和大葱一起翻炒。调入适量盐和胡椒就可以出锅装盘啦#'),(1167,'清蒸鱼','荤菜','鲳鱼#\n大葱#\n姜丝#\n蒸鱼豉油#\n色拉油#','一条#\n半棵#\n少许#\n一汤匙#\n一汤匙#','1. 将鱼洗净，剖条纹，加入姜丝和葱在鱼肚子里，上锅蒸8—10分钟，去掉汁水，淋上蒸鱼豉油，放切好的葱丝，淋上烧热的色拉油，一道美味营养的清蒸鱼就做好了，老少皆宜。#'),(1168,'韩国?????直译就是土豆排骨汤','汤','金针菇#\n青椒#\n葱#\n其他青菜#\n韩国大酱#\n辣椒粉#','一把#\n一个#\n若干#\n若干#\n适量#\n一小勺#','1. 葱青椒土豆金针菇这些东西切好洗好备用#\n2. 排骨先炖一个小时#\n3. 炖排骨的间歇卖个萌，哈哈~~~#\n4. 排骨炖差不多之后放入土豆，7颗大蒜，葱，大酱酱油少许盐辣椒粉炖#\n5. 土豆差不多熟后放金针菇青椒圈炖5分钟#\n6. 咕嘟咕嘟暖暖的土豆排骨汤就好啦~~~~#'),(1169,'爆脆鸡胗','荤菜','鸡胗#\n青尖椒段（辣）#\n姜末#\n蒜片#\n料酒（腌渍用）#\n酱油#\n盐#\n糖#','10个#\n1-2个辣椒#\n#\n#\n2勺#\n1勺#\n#\n1小勺#','1. 鸡胗只取鼓鼓的那两块肉，外面的白色筋膜和内面的那一层皱皱巴巴的皮尽可能剔除干净，然后切细条。用盐，料酒，姜末入底味和去腥。下锅前，拌点淀粉进来。#\n2. 油加热到6，7成热，把鸡胗倒入，翻炒。#\n3. 鸡胗变色后，下青椒段和蒜片，中高火继续翻炒。#\n4. 加糖，酱油，盐，炒匀，用水淀粉沿着锅边快速勾芡出锅。#'),(1170,'香蕉西葫芦炒羊肺#鲜动生活甘草羊#','荤菜','香蕉西葫芦#\n羊肺#\n青蒜#\n植物油#\n生抽#\n蚝油#\n盐#\n葱花#','3根#\n240克#\n数根#\n20克#\n15克#\n15克#\n适量#\n少许#','1. 香蕉西葫芦三根，清洗干净#\n2. 羊肺是买的煮熟的，又重新清洗干净了#\n3. 青蒜清洗干净#\n4. 香蕉西葫芦切成一厘米见方的丁#\n5. 羊肺切成一厘米见方的丁#\n6. 青蒜切末#\n7. 锅中倒油，葱花煸炒出香味#\n8. 小火，入羊肺丁，翻炒变色，水份略有蒸发#\n9. 根据口味调入适量盐、生抽、蚝油，翻炒均匀#\n10. 入香蕉西葫芦丁，翻炒一分钟#\n11. 将青蒜末投入，翻炒均匀即可出锅#\n12. 嫩嫩的明黄，搭配红褐色，碰撞出新的美味#\n13. 香蕉西葫芦脆嫩，羊肺绵软#\n14. 有滋有味#'),(1171,'拔丝红薯','甜品','红薯#\n油#\n糖#','2根#\n适量#\n适量#','1. 红薯洗干净，去皮，#\n2. 然后把红薯切成菱形壮就可以了，然后再洗一遍…#\n3. 然后锅里放油，，#\n4. 油热以后放入切好的红薯，大概炸至8～10分钟左右，炸至金黄色就可以，可以用筷子扎一下看还有没炸透的…#\n5. 然后用笊篱捞出来，放置盘子里#\n6. 盘子上可以刷一点油，这样就不会现在盘子上了#\n7. 锅里可以留点底油，放入白砂糖，转至小火，要不停的去搅动糖，待糖变成焦黄色，这是就可以放入炸好的红薯，然后用铲子翻动就可以出锅了…#'),(1173,'南瓜青椒肉丝','荤菜','青嫩南瓜#\n肉丝#\n青椒#\n大蒜#\n料酒#\n生抽#\n淀粉#\n油盐#','1个#\n50克#\n1个#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 准备好原材料；#\n2. 肉丝中加入盐、淀粉、料酒、生抽和少许油；#\n3. 搅拌均匀后腌制一、二分钟；#\n4.  烧热锅， 放少许油， 下入大蒜碎；#\n5. 大蒜爆香后下入肉丝；#\n6.  翻炒肉丝， 直到肉丝微微变色；#\n7. 下入南瓜丝和青椒丝翻炒；#\n8.  翻炒到微微发软后加入盐等调味；#\n9. 出锅装盘。#'),(1174,'＃新年一起下厨＃酿丸子','荤菜','前腿肉#\n玉米#\n香菇#','#\n#\n#','1. 切肉成小块#\n2. 香菇也要切小块#\n3. 进去绞肉环节，我直接把盐和淀粉料酒放一起绞#\n4. 加入煮过水的甜玉米#\n5. 塞到油豆腐里，上蒸锅，#\n6. 好咯，看着还不错吧，只是老公说不够咸，我倒觉得还行啦#'),(1175,'脆炸面条鱼','荤菜','鸡蛋#\n椒盐#','#\n#','1. 面条鱼洗净沥干，加入少许盐拌匀，备用#\n2. 放入面粉，一个鸡蛋(脆一点可以直接将鱼占面粉炸）#\n3. 热一锅油，将面条鱼一条一条沾上面粉再放入油锅炸至金黄色#\n4. 食用时根据自己口味可以撒上椒盐等！#'),(1176,'黑椒碎香煎金枪鱼','荤菜','新鲜金枪鱼肉#\n黑胡椒碎#\n小葱#\n香菜#\n李锦记生抽#\n橄榄油#','半斤#\n大量#\n适量#\n少许#\n适量#\n适量#','1. 右下角是我今天买的新鲜金枪鱼。#\n2. 1、金枪鱼肉切方形块。我一共切了三方块，一块后面能切三片的量。按个人喜好切啦，喜欢方型、三角形都随意。2、橄榄油热锅，锅八成热小火放上金枪鱼，四面略微煎熟变色便可出锅。3、熟的表层均匀铺满黑胡椒碎。4、切片约5mm厚度一片。5、香菜小葱切碎跟生抽拌匀铺在盘子上。#\n3. 最后将金枪鱼片摆在小葱香菜碎上，金枪鱼表层刷上橄榄油就OK啦！#\n4. 鲜美好吃的黑椒碎香煎金枪鱼可以上桌了。夏日的下酒好菜哦。（≧?≦）#'),(1177,'海苔肉卷','荤菜','鸡胸肉#\n海苔#\n胡萝卜#\n尖椒#\n小葱#\n盐#\n胡椒粉#\n鸡精#\n淀粉#\n酱油#','1片#\n1片#\n1小块#\n1块#\n1根#\n1勺#\n半勺#\n1勺#\n1勺#\n1勺#','1. 鸡胸肉先切小丁，再剁，剁成鸡肉馅#\n2. 一小块胡萝卜和尖椒就够了，切丁；小葱切成葱花；加一勺盐、鸡精、酱油、淀粉、半勺胡椒，把所有放入一起搅匀。#\n3. 铺一个海苔，把刚才的馅像做寿司一样平铺在海苔上，记住要在收尾处空出一条不放馅，卷起。#\n4. 小火慢煎，大概10分钟。（看馅多少而定）#\n5. 馅熟透后切片#'),(1178,'老鸽丝瓜芋艿汤','汤','老鸽子#\n葱姜#\n丝瓜#\n盐#\n芋艿#','2只#\n#\n#\n#\n#','1. 老鸽子洗净后切块#\n2. 锅内加水，将老鸽子和姜片葱结一起炖煮.#\n3. 炖酥后的鸽汤放入去皮煮熟的芋艿和丝瓜煮沸，稍加薄盐调味即可.#'),(1179,'蒜蓉枸杞蒸丝瓜','素菜','丝瓜#\n大蒜#\n油#\n枸杞#\n盐#\n生抽#\n鸡精#','2根去头尾#\n适量#\n炒蒜蓉#\n适量#\n适量#\n适量#\n少许#','1. 丝瓜去皮切成高矮一样的段摆在深一些的盘子上。大蒜去皮拍蒜蓉，大勺多放些油炒热，加入大蒜沫炒香，再加入盐、生抽、鸡精调味，好了后盛出干蒜蓉，均匀摆在丝瓜上，锅内汁留用。枸杞用水泡软摆在蒜蓉上。#\n2. 蒸锅放水加屉，把整盘丝瓜放进去，浇上刚才大勺里留用的部分汁，蒸8分钟。#\n3. 成了。（这个东西，怎么评价呢？好看，味道一般般，偶尔做一次还行！）#'),(1180,'豉汁蒸排骨','荤菜','排骨#\n豆豉#\n姜片#\n蒜蓉#\n辣椒末#\n葱末#\n料酒#\n白糖#\n酱油#\n玉米淀粉#\n胡椒粉#','500g#\n适量#\n3块#\n适量#\n适量#\n适量#\n2勺#\n少许#\n1大勺#\n适量#\n适量#','1. 辣椒碎、葱、姜#\n2. 排骨洗净吸干水分装入碟子，把蒜末和豆豉放入油锅爆香后放入排骨搅拌均匀#\n3. 然后加入姜、辣椒、酱油、糖、料酒、胡椒粉搅拌均匀腌制一个小时后加玉米淀粉再搅拌均匀放入煮开水的锅中蒸40分钟#\n4. 起锅前撒上葱末#\n5. 成品图，浓香的豉汁和辣椒的香气胃口大开#'),(1181,'千丝万缕','不属于任何一类','青椒#\n金针菇#\n香肠#\n香葱#\n香菜#\n蒜#\n花生油#\n盐#\n酱油#','一个#\n1小把#\n1根#\n2根#\n1根#\n1瓣#\n适量#\n适量#\n适量#','1. 把材料洗净准备好#\n2. 青椒、香肠切丝，香葱、香菜切段，蒜切碎，金针菇撕散开。#\n3. 锅里放油烧热，放入蒜碎爆香。#\n4. 放入青椒、金针菇，酱油翻炒均匀。#\n5. 放入香葱、香肠继续翻炒均匀。#\n6. 最后放入香菜、盐翻炒均匀出锅即可。#\n7. 味道好极了！#'),(1183,'家乡菜“拔海蛋”','荤菜','鸭蛋#\n马蹄#\n黑木耳#\n盐#\n生姜#\n肥猪肉#','8个#\n6只#\n适量#\n适量#\n适量#\n适量#','1. 木耳、马蹄切成丝，把肥肉切成丁备用。#\n2. 把肥肉入锅内炼成油，再把木耳丝和马蹄丝倒入锅内炒熟，调味。#\n3. 鸭蛋去壳倒入碗里搅拌打散，再把炒好的猪油木耳马蹄丝与打散的鸭蛋一起搅拌均匀，放入锅里隔水蒸约十到十五分钟。#\n4. 蒸熟后，切成菱形装入碟即可食用。#'),(1184,'凉拌菠菜粉丝','素菜','盐#\n油#\n葱#\n蒜#\n凉拌酱油#\n醋#\n鸡精#\n熟花生米#\n花椒#\n干辣椒#\n香油#','1勺#\n2勺#\n少许#\n少许#\n2勺#\n1.5勺#\n少许#\n20g#\n10颗#\n3颗#\n少许#','1. 把粉丝和菠菜洗净，分别在锅里用开水煮烫至软即可，捞出用凉水冰一下！一会把菠菜和粉丝捞出控干水备用！#\n2. 将蒜切末，葱切丝，干辣椒切断！#\n3. 把花生米撵碎（曾看过一篇文章，讲到这花生米的红衣服最好不要食用，我便给他们“脱”了红衣服）#\n4. 把切好的葱丝、辣椒段及蒜末放入菜中，油烧热将花椒放入炸出香味即可，摘去花椒将热油倒在葱丝、蒜末及干辣椒上，这时会散发出很浓的香味！#\n5. 将撵碎的花生米撒入，再依次加入盐、醋、酱油、鸡精等调味料！#\n6. 滴上一滴香油，搅拌均匀即可！#'),(1185,'鸡蛋羹','荤菜','鸡蛋#\n纯牛奶#\n白糖#\n葡萄干#','2只#\n250ml#\n1勺#\n随意#','1. 拿个容器大点搅鸡蛋~加白糖、纯牛奶搅~倒入碗时要过滤蛋泡~再用保鲜膜密封碗口~上锅蒸15分钟即是纯正营养价值高的甜品~#'),(1186,'九阳烘焙剧场——香烤土豆','素菜','大土豆#\n食盐#\n辣椒粉#\n孜然粉#\n椒盐#\n葱#\n蒜#\n青红小辣椒#\n玉米油#','一个#\n适量#\n两勺#\n一勺#\n一勺#\n少许#\n少许#\n各一根#\n适量#','1. 大土豆去皮，切成均匀三角块，用清水冲洗去淀粉，再浸泡在淡盐水中一刻钟，沥干水分，擦干。#\n2. 九阳空气炸锅200摄氏度预热5分钟，将土豆块放入炸篮中，尽量平铺。土豆刷一层玉米油，定时20分钟。中途可以拿出来翻一翻。#\n3. 热锅烧油，放入蒜蓉、切好的青红辣椒圈煸香，加入葱花，炒匀关火。#\n4. 趁热放入辣椒粉、孜然粉、椒盐，炸好的土豆块，翻炒均匀，再加入适量食盐，少许白砂糖和少许鸡精，炒好装盘。#\n5. 香炸土豆就做好啦，微辣、咸香，土豆外焦里糯，非常可口。#'),(1188,'清炒眉豆','素菜','眉豆#\n姜#\n盐#\n生抽#','400g#\n适量#\n适量#\n适量#','1. 姜切小片备用#\n2. 油锅下姜煸香#\n3. 下眉豆翻炒，放入生抽，盐，加一点水#\n4. 翻炒大概一分半即可#'),(1189,'翻滚吧饭团子','不属于任何一类','剩米饭#\n玉米粒#\n香肠粒#\n鸡蛋#\n千岛酱#','一碗#\n少许#\n少许#\n一个#\n少许#','1. ①先把剩米饭充分搅拌好，备用②玉米粒可以事先过下热水备好，香肠切一小粒片，鸡蛋搅拌成蛋液备用③带上手套把剩米饭与食材一起搓起来④而要盛放的盘子可以放点生粉，以防盘子与饭团相互粘住。#\n2. ⑤这时备好的饭团就要放进蛋液里翻滚，使得蛋液裹紧饭团。⑥锅里放点油，火候不必太大，以防焦了。把裹好蛋液的饭团放进油锅里进行肆无忌惮的翻滚吧。⑦只要蛋液颜色稍微改变就ok好啦。⑧最好装盘时可以放些千岛酱做装饰。#'),(1190,'香辣鲜榨菜拌海带丝','素菜','鲜榨菜#\n海带丝#\n芝麻辣#\n味极鲜酱油#\n醋#\n鸡精#\n香油#','#\n#\n#\n#\n#\n#\n#','1. 干海带丝泡水八小时以上，最好用开水泡，换两次水。 　　#\n2. 把泡软的海带丝放入锅中煮熟，煮时加点醋更易烂。 　　#\n3. 把榨菜去皮切成粗丝，加一点盐腌一会儿，榨菜吃盐比较多，用清水冲洗掉浮盐，然后挤干。#\n4. 煮熟的海带丝和腌好的榨菜丝放在一起，加少许味极鲜酱油、醋、香油、芝麻辣等拌匀即可。#'),(1191,'蒸蒜蓉粉丝娃娃菜','素菜','粉丝#\n娃娃菜#\n大蒜#\n木耳#\n酱油#\n白糖，醋#\n盐，香油#','100g#\n200g#\n2—3瓣#\n少许#\n少量#\n少量#\n少量#','1. 娃娃菜或大白菜，今天没买到娃娃菜。大白菜切丝。#\n2. 粉丝，一般商店都能买到，用水泡发。如果嫌太长了，发开后切两段。#\n3. 调好的汁，这个是决定菜菜品的味道。酱油，白糖，醋，姜丝，蒜泥，蒸鱼豉油这个很重要，盐，香油。#\n4. 上锅蒸，用盘子底层放白菜上面放粉丝#\n5. 开始浇，调好的汁。#\n6. 蒸熟后出锅。蒜香已经扑鼻而来，放几片发好的木耳或香菜味道更佳，我朋友不爱吃香菜没放，各位客官请慢慢品尝。#'),(1192,'啤酒蒸大闸蟹','荤菜','啤酒#\n姜#\n红糖#\n镇江香醋#','3瓶#\n一小块#\n少许#\n#','1. 首先把大闸蟹洗干净捆扎好，然后把啤酒全部倒上，让它们泡泡澡，大概泡个十分钟就可以了#\n2. 把蟹从啤酒捞出后，让蟹的肚子朝上，这样蒸的时候能更好的保留蟹的营养，啤酒不要倒掉，用泡蟹的啤酒不用加水，直接开大火蒸，上气后蒸15至20分钟，关火后再焖10分钟即可#\n3. 趁蒸蟹的时间可以准备蘸料，把姜切末加少许红糖和香醋调匀，最后就可以吃蟹啦～#'),(1193,'蒜香椒盐皮皮虾','荤菜','皮皮虾#\n蒜苗#\n芹菜#\n红椒#\n姜 蒜 花椒 红尖椒#\n油 盐 椒盐粉#','250g#\n1根#\n1根#\n半个#\n适量#\n适量#','1. 将皮皮虾放在清水里浸泡半个小时，然后冲洗干净盛盘。#\n2. 准备好配菜和调料#\n3. 将控干水的虾放在油锅中炸直至虾皮变焦红，然后起锅。#\n4. 将备好的调料炸香，放入焦红的皮皮虾翻炒，依次加入椒盐、鸡精炒匀，起锅盛盘。#\n5. Bingo 可以上桌解馋了#'),(1194,'酸菜猪肉水饺','主食','东北酸菜#\n猪肉泥#\n面粉#\n葱油#\n盐#\n花椒粉#\n生抽#\n香油#\n水#\n醋#\n蒜泥#\n香油#\n辣椒油#','#\n（五花颈背3：7）#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 酸菜冲洗一遍挤干水份，剁碎，与肉泥继续一起剁匀，放入容器中，加入葱油，盐，花椒粉，生抽，香油，顺着一个方向搅拌上劲备用。#\n2. 水和面粉和成软硬适中的面团，饧一会。分小块#\n3. 切剂子，擀皮。#\n4. 包好。下锅煮熟，蘸料汁。#'),(1195,'鸡蛋炒西红柿','荤菜','鸡蛋#\n盐#\n小葱#\n玉米油#\n白糖#\n生抽#\n葱#\n姜#','三个#\n2g#\n5g#\n20g#\n10g#\n10g#\n5g#\n2g#','1. 将西红柿底部插个叉子，用煤气灶的最小火烧一下外皮，看到爆裂了就转动方向#\n2. 然后拿到水龙头下面冲一下，皮很容易就撕下来了#\n3. 3个西红柿都撕掉外皮#\n4. 鸡蛋磕入碗中打散，西红柿切块，葱、姜切片#\n5. 油热了先将鸡蛋摊好划散盛出来#\n6. 原锅加油爆香葱、姜#\n7. 下入西红柿翻炒几下#\n8. 加适量盐#\n9. 加1勺白糖#\n10. 再加少许生抽提味#\n11. 将炒好的鸡蛋倒进去#\n12. 加入小葱碎翻炒一下就可以了#\n13. 来碗大米饭开吃吧！#'),(1196,'甜酸斎','无法明确分类','面筋#\n番茄酱#\n白糖#\n盐#\n白醋#\n淀粉#\n水#','一袋#\n3勺#\n2勺#\n三分之一勺#\n1勺#\n1勺#\n大半碗#','1. 准备好油面筋，可以用水冲冲#\n2. 锅内放冷水，多一些#\n3. 倒入油面筋，记得在每个油面筋上用手戳一个洞#\n4. 开火煮，煮到水开，油面筋全部烫熟了#\n5. 过滤出油面筋，沥干水分#\n6. 将辅料配好放在碗里#\n7. 锅内倒少许油#\n8. 开小火，倒入辅料#\n9. 等有点粘稠了就把油面筋倒进去，让油面筋全部裹上酱汁就行了#'),(1197,'蒜香龙虾','荤菜','大蒜头#\n盐#\n白砂糖#\n豆豉酱#\n龙虾#','4颗（大颗）#\n适量#\n适量#\n两大勺#\n两斤#','1. 因为匆忙，忘记拍食材全家福了～把蒜头拍碎，切细，下油锅爆香。#\n2. 放入剪好洗净的龙虾翻炒至龙虾变红。#\n3. 我喜欢有一点辣味，但是放辣椒显得单调，所以就放我喜欢的豆豉酱，又能提香，这个根据个人口味添加。#\n4. 放入豆豉酱，盐，白砂糖各适量，最后加入水，大火烧20分钟左右，即可出锅。#\n5. 美味的蒜香龙虾就完成啦！！！！#'),(1198,'脆米鸡','荤菜','鸡胸肉#\n杏鲍菇#\n甜椒#\n二荆条#\n大葱#\n姜#\n蒜#\n豆瓣#\n白胡椒粉#\n料酒#\n盐#\n小葱#','一块#\n1个#\n1个#\n4个#\n适量#\n适量#\n1个#\n适量#\n少许#\n少许#\n少许#\n少许#','1. 鸡肉洗净后切细丁，用少许料酒和盐码匀，其他所有的食材均切细丁，杏鲍菇焯水#\n2. 热锅冷油放大葱，姜，蒜炒香后，放入鸡丁，豆瓣煸炒，然后放杏鲍菇，甜椒和二荆条，起锅时放小葱#\n3. 颜色有红有绿，看着就开胃#'),(1199,'培根炒芦笋','荤菜','培根#\n芦笋#\n独蒜#\n老姜#\n黑胡椒粉#\n盐#\n鸡精#','#\n#\n#\n#\n#\n#\n#','1. 芦笋剥去老茎干部分，切滚刀，培根切条备用#\n2. 芦笋下过焯水一分钟捞起#\n3. 姜蒜切末，油锅下花椒数颗（只需少量色拉油即可，培根会出一点油），下姜蒜末，爆香以后下培根翻炒#\n4. 在加入芦笋继续翻炒，加黑胡椒粉，盐及鸡精调味即可。是一道比较清淡爽口的菜……#'),(1200,'西葫芦炒香菇','素菜','西葫芦#\n香菇#\n胡萝卜#\n盐#\n生抽#\n醋#\n蒜末#','半个#\n四只#\n半根#\n#\n#\n#\n#','1. 主料分别切片，西葫芦别太薄，以免熟后塌软。#\n2. 锅内少许油，烹香蒜末后，先放香菇和胡萝卜，放生抽和少许清水。翻炒至熟后放入西葫芦，再放入醋和盐，翻炒至西葫芦七八成熟即可。#'),(1201,'蛋皮芝麻羊肉卷','荤菜','速冻羊肉卷#\n胡萝卜丝#\n辣椒丝#\n杏鲍菇#\n鸡蛋#\n胡椒粉、盐、孜然粉#\n芝麻#\n食用油#','半盒#\n适量#\n适量#\n1个#\n4个#\n适量#\n适量#\n炸东西的量#','1. 杏鲍菇切丝、羊肉卷切条、胡萝卜丝、辣椒丝加入孜然粉、胡椒粉、盐调味#\n2. 鸡蛋打碎、用筷子或打蛋器打匀备用#\n3. 平底锅刷油烧热、倒入适量蛋液、通过晃动平底锅将蛋液均匀摊开，#\n4. 待蛋液成型用锅铲轻轻铲起蛋饼边缘即可取出完整蛋饼，以此将蛋液全部摊成蛋饼#\n5. 将拌好的馅料卷入蛋饼、切段刷上容器上剩余蛋液撒上芝麻#\n6. 锅内倒入植物油、烧热、将裹好芝麻的羊肉卷入锅炸制颜色金黄即可#\n7. 出锅、装盘#'),(1202,'腊肉豆干小米辣','荤菜','腊肉#\n豆干#\n小米辣#\n大蒜#\n姜#\n生抽#\n盐#','100g#\n300g#\n30g#\n适量#\n适量#\n适量#\n适量#','1. 豆干切条备用#\n2. 蒜，姜，小米辣切好备用#\n3. 腊肉切片备用#\n4. 姜放入油锅，蒜和小米辣放一部分#\n5. 煸香后放入腊肉翻炒一分钟#\n6. 放豆干，加点水，翻炒#\n7. 放盐，生抽翻炒#\n8. 翻炒两分钟即可出锅#'),(1203,'红烧牛肉','荤菜','番茄#\n姜#\n蒜#\n干辣椒#\n豆瓣酱#\n白糖#\n冰糖#','一个#\n#\n#\n#\n#\n#\n#','1. 姜蒜切片，一大把干辣椒切段，一小把花椒，备用。#\n2. 牛肉焯水，打去血沫。捞出滤干切块。#\n3. 热油爆干辣椒至变色，下姜蒜爆出香味，豆瓣酱至出油。下牛肉翻炒几下，加适量白糖至融化，老抽生抽料酒各一勺，翻炒至牛肉完全上色#\n4. 加水至完全没过牛肉，待水烧开，大胆加盐至汤味略咸（可以蘸少许尝尝）放入一两颗冰糖。转小火闷炖90分钟。#\n5. 胡萝卜切滚刀片，倒入。加少许鸡精。火稍调大继续闷炖四十分钟。切一个西红柿埋入汤锅中。转大火收汁。#'),(1204,'芋艿排骨汤','汤','葱#\n姜#\n料酒#\n盐#','#\n#\n#\n#','1. 排骨清洗好，斩成小断儿，#\n2. 锅里加水放入排骨，葱，姜，料酒，烧开，撇去浮沫，在重新加水，放入炖锅内#\n3. 芋艿去皮洗好，切成小块#\n4. 排骨炖四十分钟左右，在加入芋艿块在炖半个小时，加盐就可以拿碗儿喝咯!#'),(1205,'鲜菌菇滑蛋','荤菜','鸡蛋#\n各种新鲜的菌菇#\n胡萝卜#\n葱花#','3个#\n150g#\n半根#\n一小把#','1. 准备材料。#\n2. 几种鲜菌菇洗净，胡萝卜去皮，切成丝。#\n3. 将几种蘑菇和胡萝卜丝放入开水锅焯2分钟后捞出沥干水分，菌菇撕开成小朵。鸡蛋打散。#\n4. 把撕好的菌菇和胡萝卜丝倒入蛋液中，调入盐和打匀（可以撒一点点白胡椒粉）。#\n5. 锅烧热后倒入油，将混合蛋液倒入锅中，撒一半葱花。#\n6. 不停翻炒至蛋液凝固，撒入剩下的葱花即可。#'),(1206,'台式糖醋溜鱼片','荤菜','木耳#\n葱#\n大蒜#\n生姜#\n酱油#\n米醋#\n番茄酱#\n白糖#\n生粉#\n地瓜粉#','#\n1根#\n#\n#\n#\n#\n#\n#\n#\n#','1. 原料：鱼片#\n2. 木耳用水发好，约十分钟#\n3. 配料：番茄酱，青椒，葱姜蒜#\n4. 将鱼肉切片，配上少量蛋液，精盐，料酒和生粉腌制约10分钟#\n5. 将鱼肉均匀挂上地瓜粉#\n6. 锅中放油，待油温五成热，放入鱼块，带鱼块膨胀，迅速取出#\n7. 炒锅放油，放入葱姜蒜，炒香后放入番茄酱，炒制粘稠后，放入洋葱，青椒，木耳。#\n8. 水淀粉勾芡，放入鱼片，迅速盛出。糖醋鱼片就完成了#\n9. 鱼肉爽滑，表面粘附酸辣酱汁，是下饭佳肴。#'),(1207,'红烧小黄鱼','荤菜','食盐#\n醋#\n生姜#\n葱#\n料酒#\n生抽#\n植物油#\n白糖#\n蒜#\n八角#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 小黄鱼宰杀制净，拍一层淀粉。葱姜蒜切碎#\n2. 小黄鱼下温油中炸黄，捞出备用#\n3. 葱姜蒜炒出香味，下入小黄鱼及调料，小火烧至入味#'),(1208,'凉拌莴笋丝#橄露贝贝橄榄油#','素菜','莴笋1根#\n生抽#\n陈醋#\n蒜头#\n白芝麻#\n橄榄油#\n香菜#\n自制辣椒酱#','160g#\n50g#\n5g#\n1瓣#\n5g#\n10g#\n一棵#\n一小勺#','1. 莴笋一根#\n2. 莴笋去皮后，借用擦丝器，擦成丝。#\n3. 蒜头一个拍碎切成末，加入生抽陈醋。#\n4. 加入少许白芝麻。#\n5. 加入橄榄油#\n6. 香菜一棵剪碎加入，再加入自制的辣椒酱#\n7. 拌匀即可。#'),(1209,'香辣肉丝','荤菜','里脊肉#\n香菜#\n干辣椒或者尖椒#','#\n#\n#','1. 里脊肉切丝#\n2. 香菜切段，还有干辣椒#\n3. 锅里热油，#\n4. 炒肉丝，炒发白#\n5. 干辣椒放入，放些酱油和少许盐#\n6. 放入香菜段，放盐，酱油翻炒，#\n7. 出锅～#'),(1210,'自制风干鱼','荤菜','花椒，盐，辣椒#','适量#','1. 开膛破肚，清洗干净。#\n2. 炒熟的盐和花椒加辣椒加工成粉。#\n3. 均匀涂抹后，悬挂通风处(我家楼道，风不大，但不断...)#\n4. 一星期的成品，挂个2星期肉体干硬了，就可以食用。#'),(1211,'豆沙粽子','主食','粽叶#\n糯米#\n豆沙#\n鸡蛋#','#\n#\n#\n#','1. 粽叶和糯米提前用水泡两个小时；#\n2. 将两三片粽叶重叠，折成漏斗状，先放入一勺米，再盛上一勺豆沙，再放一勺半填满、压紧；#\n3. 包好收口，用绳缠紧；#\n4. 将包好的粽子放入锅中，可以再压上几个鸡蛋，煮一个半小时即可。#'),(1212,'猪脚炖花生汤','汤','生姜#\n大蒜#\n桂皮#','#\n#\n#','1. 先去猪脚里面的血水（先把猪脚放入冷水中，等水开，大概5分钟）#\n2. 再把配料加花生一起放入砂锅中，大概40分钟的样子就可以了#\n3. 加盐加味精就行了#'),(1215,'盐煎鸡翅','荤菜','鸡翅#\n盐#\n花生油#\n黑胡椒粉或孜然粉或辣椒粉（非必要）#','7只#\n10g#\n少量#\n适量#','1. 1.鸡中翅洗干净，挤干水分，加盐拌匀，放冰箱内腌制6小时以上。从冰箱取出鸡翅，用水冲洗干净，并挤干水分#\n2. 2.平底锅放少许油，搪匀后逐只放入鸡翅，用慢火煎#\n3. 3.煎到一面开始变金黄时，加盖焖上2分钟#\n4. 4.另一面反过来，如法炮制。加盖的目的是为了让鸡翅加快变熟，同时防止水分被煎干，口感变柴#\n5. 5.上碟时可根据喜好撒上黑椒粉或孜然粉或辣椒粉等调味，也可什么都不加，原汁原味#'),(1216,'灰灰的拍黄瓜','素菜','基本调味#','#','1. 拍黄瓜，用刀面将黄瓜拍碎后切小段#\n2. 加入蒜末#\n3. 依次放入醋，糖，少许盐及香油#'),(1218,'冬补圣品--香酥羊腿','荤菜','羊腿肉#\n花椒#\n麻椒#\n八角#\n陈皮#\n五香粉#\n盐#\n酱油#\n蚝油#\n鸡蛋#\n玉米淀粉#\n香菜#','1000g#\n1小勺#\n1小勺#\n1颗#\n1块#\n1小勺#\n2小勺#\n1 小勺#\n少许#\n3只#\n约100克#\n1根#','1. 将羊腿肉切割成小块#\n2. 将花椒，麻椒，八角，酱油，蚝油，料酒，酱油，五香粉，盐，糖等调味料放到切好的羊腿肉中#\n3. 将调味料和肉搅拌均匀#\n4. 封好保鲜膜，放入冰箱冷藏4小时以上，腌制入味#\n5. 把腌制好的羊肉放到高压锅里，隔水蒸20分钟#\n6. 蒸熟的羊肉出锅后沥干水分#\n7. 用玉米淀粉和鸡蛋调糊，给每块羊肉都裹上糊#\n8. 起锅，放油，油烧至八成热，把挂好糊的羊肉块放到油锅中，炸至两面金黄色#\n9. 炸好了，撒些香菜点缀。。。#\n10. 成品！！！#'),(1221,'简单美味蒜蒸开边九节虾','荤菜','蒜头／辣椒#\n葱珠#\n蚝油#\n盐／味精#','适量#\n适量#\n半匙#\n各1小匙#','1. 九节虾买回来洗干净对边切开。#\n2. 把蒜蓉辣椒爆香加入盐味精蚝油搅匀淋上。#\n3. 大火蒸8分钟后酒上葱珠即可上桌。#'),(1222,'土豆炖鸡','荤菜','鸡翅#\n土豆#\n糖#\n酱油#\n盐#','六个#\n四个#\n若干#\n若干#\n若干#','1. 先把鸡翅用滚水过一下，去血和杂质。#\n2. 把白砂糖倒入温油中炒化，喜欢甜就多放，不喜欢就少放，火不要大，不然会糊#\n3. 把鸡翅倒入油锅中，翻炒至鸡翅金黄，然后倒入适量老抽，翻炒到鸡翅上色，然后倒入土豆块，继续翻炒，待全部染色均匀，放入水，没过鸡翅土豆，并加入少许盐#\n4. 中火炖，待锅中起泡泡，汤汁变粘稠后，大火收汁，收汁时要来回翻炒，防止沾锅。然后装盘#'),(1224,'芹香千张手卷','素菜','香芹#\n肉泥#\n千张#\n韭菜#\n盐#\n味精#\n蚝油#\n自制烤肉粉#\n油#','200g#\n200g#\n200g#\n少许#\n5g#\n2g#\n5ml#\n5g#\n5g#','1. 香芹洗净去老根去叶切米，姜蒜切米，小米辣切圈待用#\n2. 坐锅起油，下姜蒜爆香，下肉泥划散#\n3. 下味精、蚝油、盐，翻炒2分钟#\n4. 下小米辣、香芹，翻炒2分钟，撒烤肉粉，翻炒均匀出香，起锅待用#\n5. 坐锅烧水，加少许盐，下千张烫熟#\n6. 下韭菜，烫15秒，捞起浸泡在冰水中#\n7. 千张切7X10cm方块#\n8. 将肉泥铺在千张上，卷起，用韭菜缠紧即可#'),(1226,'胡罗卜炒鸡蛋','荤菜','胡萝卜#\n鸡蛋#\n大葱#\n花生油#\n盐#\n十三香#','500g#\n2个#\n适量#\n适量#\n适量#\n少许#','1. 胡罗卜改刀，切凌行片#\n2. 鸡蛋2个打散#\n3. 大葱切碎#\n4. 起火，锅里放油，油热把打好的鸡蛋液下锅#\n5. 鸡蛋炒熟出锅放入盘里，备用。#\n6. 炒勺里油热放入胡罗卜片，翻炒至八分熟，加适量的盐，翻炒出锅，备用#\n7. 锅里油热，下入葱花十三香，爆香#\n8. 放入胡罗卜和炒好的鸡蛋，加入适量的酱油。掂勺出锅。#\n9. 成品#'),(1227,'家常菜—鸭翅毛豆米','荤菜','鸭翅#\n带壳毛豆#\n玉米油#\n盐#\n葱#\n生姜#\n八角#\n桂皮#\n生抽#\n老抽#\n白砂糖#\n料酒#','17个#\n700克#\n1大勺#\n适量#\n2棵#\n适量#\n数个#\n适量#\n2勺#\n2勺#\n适量#\n1勺#','1. 鸭翅清洗干净放入冷水中焯水，去除鸭翅中的血污及异味。毛豆去壳洗净待用。#\n2. 焯水后的鸭翅再放入水中清洗，拨去残留的杂毛，洗净控干。#\n3. 锅内加1勺玉米油烧热，放入鸭翅、毛豆米及葱、生姜、八角、桂皮煸炒，再加入适量料酒、生抽、老抽、盐，加水漫过鸭翅盖上锅盖焖煮。#\n4. 大约中小火四十分钟后，捞出葱等调料，加入少量糖开大火收干汤汁，即装盘食用。#\n5. 配上一碗白米饭，绝对是好吃的下饭菜。#'),(1228,'凉拌笋丝','素菜','竹笋#\n香菜#\n大蒜#\n生抽#\n醋#\n麻油#\n香油#','250g#\n#\n一瓣#\n少许#\n少许#\n一滴#\n少许#','1. 先把笋切丝，锅内放水烧开，将笋丝放入锅内烫三分钟，然后捞起来放篮子备用；葱、香菜、蒜切末，起锅放少许油，油烧热后倒出小碗，将葱、香菜、蒜末倒入小碗，油凉些许时间在碗里加入适量生抽、醋、麻油、辣椒油、鸡精，拌匀即可食用#'),(1229,'泡菜猪蹄','荤菜','猪蹄#\n冰糖#\n白糖#\n泡菜#\n老抽#\n蚝油#\n姜#\n料酒#\n盐#\n白醋#\n西红柿#\n泡椒#','2个#\n一大块#\n适量#\n一碗#\n2勺#\n1勺#\n几片#\n适量#\n适量#\n适量#\n2个#\n适量#','1. 准备好所需食材#\n2. 将猪蹄洗净去猪毛，切块儿#\n3. 姜切丝儿#\n4. 西红柿洗净切块儿，去皮不去皮都可以#\n5. 锅中倒油，油热后煸炒西红柿至软盛出备用#\n6. 锅中倒油，油热后放姜丝煸炒后放些白醋，翻炒后，放辣白菜继续翻炒出香味#\n7. 然后放西红柿加一些泡椒一起翻炒#\n8. 然后放猪蹄翻炒均匀后盛出#\n9. 然后全部倒入电压力锅中，大概半个小时即可#\n10. 做好啦#\n11. 拍摄花絮#\n12. 拍摄花絮#\n13. 拍摄花絮#'),(1231,'电饼铛考椒盐杏鲍菇','素菜','豆油#\n椒盐#','适量#\n适量#','1. 杏鲍菇切成厚度3毫米差不多的厚度。电饼铛烧热放油，待油烧热，将杏鲍菇如图放在饼铛里烤，挨个翻面，水分下来后再次翻面，烤到微微发黄，再翻过，待两面都烤好后就可以装盘了#\n2. 撒上椒盐，可以吃喽！很简单又下饭的菜#'),(1232,'香辣虾','荤菜','姜、蒜切片#\n葱切丝#\n泡辣椒#\n泡姜#','适量#\n适量#\n几个#\n一块（切片）#','1. 锅内倒入油，记得要多一些，比平日炒同样份量的荤菜油多一倍吧　大火烧油至辣，倒入虾#\n2. 炒一会，放入干辣椒和花椒，翻炒，让热油把辣味和麻味都“压榨”出来#\n3. 出辣味和麻味后，放入姜蒜片，泡椒，泡姜(葱先不要放）#\n4. 姜蒜香味炒出后，加入酱油适量，白砂糖适量，料酒少许　快要起锅时，放入葱丝，翻炒　加适量盐。#'),(1233,'小炒五花肉','荤菜','五花肉#\n白豆腐干#\n尖椒#\n红椒#\n酸豆角#\n小葱#\n蒜#\n洋葱#\n海鲜酱油#\n剁椒#','1块#\n4块#\n1/2根#\n1/2根#\n3根#\n1根#\n3瓣#\n1/4个#\n1大勺#\n1大勺#','1. 锅烧热，放入少许油，加热后放入蒜片爆香；#\n2. 放入五花肉，小火翻炒；#\n3. 炒至五花肉变色，放入洋葱块；#\n4. 再放入豆腐干；#\n5. 炒匀后加入酸豆角；#\n6. 加一大勺酱油；#\n7. 再加入剁椒；#\n8. 炒匀后放入青红椒、葱，大火炒1分钟即可。#'),(1234,'红烧黄骨鱼','荤菜','黄骨鱼#\n姜片#\n蒜头#\n葱，香菜#\n干辣椒#\n花椒#','一条#\n适量#\n两片#\n各一棵#\n1个#\n15粒#','1. 洗干净黄骨鱼，抹点盐，姜和料酒，腌制20分钟#\n2. 葱，香菜洗干净，切段。姜切片，蒜切片#\n3. 起油锅，待锅略有烟出时，下鱼调小火慢慢煎，先不急着翻，有点脱皮膨胀，翻面煎，待成金黄色后，留油乘起鱼。#\n4. 开大火，下蒜片，姜片，干辣椒，花椒，葱白段，一起爆香#\n5. 香味出来后下鱼。 在鱼上撒一勺酱油，加凉开水，能淹没过鱼身就好。大火边烧边加点盐，根据自己口味调节。如果怕腥再加点料酒。#\n6. 待水烧的差不多略干的时候，把葱叶段和香菜段放入。 几秒钟后可以乘起出锅！#'),(1235,'黄金炸猪排','荤菜','排骨#\n鸡蛋#\n淀粉#\n面包糠#\n黄酒#','500g#\n2个#\n适量#\n适量#\n少许#','1. 大排骨用刀背敲一下。放黄酒和少许盐腌制30分钟。#\n2. 大排沾上淀粉，再浸入蛋液，再裹上面包糠。#\n3. 轻轻压一下就可以，弄的太薄会柴。#\n4. 下油锅炸#\n5. 用吸油纸吸下油，ok了。#'),(1236,'一口香排骨','荤菜','肋排#\n料酒#\n姜#\n卷心菜#','#\n#\n#\n#','1. 排骨切小块#\n2. 洗净，加姜入锅焯水#\n3. 水煮开后加料酒再次煮开#\n4. 倒出洗去浮沫，沥干水#\n5. 二大勺排骨酱、一大勺甜辣酱、料酒、少许鲜酱油#\n6. 均匀抹在排骨上，放冰箱腌制至少4小时，期间翻转排骨几次#\n7. 排骨放碗中，入微波炉高火3分钟#\n8. 微波炉开时，把卷心菜洗净，用盐水泡一会，切成细丝，放在盆底。把排骨翻面，高火3分钟#\n9. 卷心菜上码好排骨#'),(1237,'豆腐蒸蛋','荤菜','内酯豆腐#\n鸡蛋#\n蒜末#\n调味酱油#','一块#\n一枚#\n少许#\n少许#','1. 第一步：把一块嫩豆腐中间挖个坑，打个鸡蛋进去；#\n2. 第二步：上锅蒸，我用的是煮蛋器，#\n3. 第四步，蒸好撒点葱花回蒜花，淋点麻油和凉拌酱油。#'),(1238,'酸豆角炒腊里脊','荤菜','酸豆角#\n腊里脊肉#\n大蒜#\n姜#\n泡酸红辣椒#\n生抽#\n米醋#\n料酒#','110g#\n100g#\n2瓣#\n1片#\n3个#\n1/4勺#\n1大勺#\n1/2勺#','1. 材料。#\n2. 腊里脊肉用水冲洗后放入锅中煮，煮开5分钟取出。#\n3. 晾凉后先切片，然后切碎备用。酸豆角冲洗后和蒜、姜和酸红辣椒都切碎备用。#\n4. 炒锅中放入少量油，烧热后下入腊里脊翻炒1分钟，盛出。#\n5. 炒锅中再放入少量油，油热后，下入蒜和姜，炒出香味，然后放入红椒，翻炒匀。#\n6. 放入切碎的酸豆角翻炒，调入生抽、米醋，翻炒匀，炒出醋香味。#\n7. 然后倒入腊里脊肉翻炒，最后调入料酒，翻炒匀即可。#'),(1239,'红烧鲍鱼排骨','荤菜','油#\n盐#\n酱油#\n蚝油#\n葱#\n姜#','#\n#\n#\n#\n#\n#','1. 排骨用沸水淖一下去血水，鲍鱼去内脏，切花刀备用#\n2. 锅内放少许油，将葱，姜煸出香味，放入排骨，倒酱油，蚝油，糖翻炒片刻，加水，开大火十五分钟～#\n3. 大火15分钟后，放入鲍鱼，继续大火收汁～#\n4. 装盘，撒点香葱～#'),(1240,'花生酱炆排骨','荤菜','排骨#\n蚝油#\n酱油#\n白糖#\n盐#\n花生酱#\n葱#\n水#\n姜#\n蒜#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n1条#\n适量#\n3片#\n1小个#','1. 大合照，煮开水放葱和排骨飞水备用#\n2. 用花生油爆香姜蒜煎煎排骨#\n3. 煎到排骨金黄加水蚝油#\n4. 加酱油和白糖#\n5. 炆10分钟后加花生酱和少许盐#\n6. 噹噹噹！美味的花生酱排骨#'),(1241,'粉蒸萝卜丝','素菜','胡萝卜#\n澄面#','250g#\n适量#','1. 将萝卜切丝，将干净毛巾去一下水，撒入澄面拌匀，摊薄点上锅蒸3，4分钟，出锅放凉加葱花，盐，鸡精，香油拌匀即可。#'),(1242,'照烧鸡腿','荤菜','鸡腿#\n柠檬#\n调料A:料酒#\n黒胡椒粉#\n老抽#\n生抽#\n调料B:生抽#\n老抽#\n盐#\n蜂蜜#\n水淀粉#','2只#\n半个#\n2勺#\n1勺#\n1勺#\n2勺#\n3勺#\n1勺#\n适量#\n1勺#\n适量#','1. 鸡腿去骨，提前一天晚上用调料A腌上#\n2. 将调料B的所有调料混合调匀，勺子的大小就是家里的普通汤勺就行#\n3. 锅内放少量油，七成热时将鸡腿带皮的一面放进去煎（可以事先将整块肉划几刀，可以更入味，也防止肉成熟时收缩）#\n4. 一面煎好后，翻另一面煎至五成熟#\n5. 加入适量水，大火煮开后，改小火煮熟（可以用筷子扎一下，能够轻松穿透就可以了）#\n6. 将煮好的鸡肉捞出切开摆盘，锅里的汤汁用水淀粉勾成浓芡淋在上面，最后可以适当滴几滴柠檬汁增添香味，好了，大功告成，开吃吧，美美哒#'),(1243,'西红柿炒鸡蛋','荤菜','鸡蛋#\n西红柿#','1个#\n半个#','1. 鸡蛋放到碗里，打鸡蛋。#\n2. 西红柿洗净切开#\n3. 西红柿洗净，切块#\n4. 热油，因为我加的是无烟炒菜锅，所以你们看不见烟#\n5. 开始炒鸡蛋#\n6. 吵成这个样子#\n7. 关火，放西红柿，可以利用余热来翻炒一会儿#\n8. 炒成这样就好啦#\n9. 装...盘...颜色不好看菜也太少了不过0失败#\n10. 呵呵呵...#'),(1244,'土豆炖豆角','荤菜','生抽#\n盐#\n葱#\n蒜#\n大料#','#\n#\n#\n#\n#','1. 把豆角择一下洗干净，切成寸段，土豆洗净去皮，切成一寸长，一厘米宽的条。#\n2. 热锅放底油，放一个大料小火炸透，用葱花和蒜片炝锅，放进豆角，翻炒至豆角都变色，放入生抽翻炒，倒入开水，让水没过豆角，大火炖煮10分钟。#\n3. 把土豆条下锅一起炖，改中火慢慢炖，随时翻一下，以免糊锅底。#\n4. 汤收的快没了的时候，放入适量盐。用筷子扎一下土豆，没有硬芯就可以了。最后放一把蒜沫，拌匀即可关火出锅。称上一碗米饭，一起吃，真的很香哦！#'),(1245,'紫苏炒黄瓜','素菜','紫苏#\n黄瓜#\n干辣椒，小米辣#\n酱油，鸡精#','少许#\n适量#\n适量#\n适量#','1. 紫苏切细#\n2. 黄瓜切片#\n3. 小米辣切碎#\n4. 干辣椒#\n5. 先爆香干辣椒，小米辣，紫苏。再放黄瓜#\n6. 炒至软身后，加入鸡精，生抽。出锅#'),(1246,'蒜苗炒鸡蛋木耳','荤菜','蒜苗#\n木耳#\n鸡蛋#\n油#\n盐#','450#\n适量#\n1只#\n少许#\n少许#','1. 蒜苗弄干净切去根部，然后切段，洗干净。#\n2. 木耳用清水泡开后，用开水焯1分钟，沥去水。#\n3. 打一只蛋，下锅炒蛋。#\n4. 锅里加少许油，放入蒜苗炒，然后加入木耳和炒蛋，加少许酱油和适量盐，简单快手菜就好了(￣▽￣)ノ#'),(1247,'吮指茶香酥虾','荤菜','乌龙茶#\n新鲜大虾#\n盐#\n淀粉#','2小袋#\n300克#\n1匙#\n10克#','1. 将大红袍滚水泡开备用。#\n2. 泡好的大红袍茶滤去茶汤，将茶叶倒入容器中，倒入淀粉。#\n3. 茶叶和淀粉充分搅拌均匀。#\n4. 平底锅中倒入适量的油，烧热。#\n5. 倒入茶叶，中火炸至茶叶变脆。#\n6. 捞出炸好的茶叶，滤干油备用。#\n7. 大虾洗净，挑去虾肠线，沥干水份。#\n8. 平底锅中油再次烧热，倒入处理好的大虾。#\n9. 中火将大虾炸至虾皮呈红色。捞出大虾，滤去油。#\n10. 平底锅留少量的油，倒入炸好的茶叶和大虾，调入盐。#\n11. 大火翻炒数下，关火即可。#'),(1248,'炒豆腐','素菜','豆腐#\n大葱#\n食用油#\n盐#\n十三香#','一块#\n一颗#\n适量#\n适量#\n适量#','1. 准备食材#\n2. 切成小块#\n3. 锅里烧开水里面放盐，把豆腐倒进去绰几分钟，#\n4. 把豆腐从锅里捞出来过凉水，，#\n5. 葱花切丝。锅里放油，油热了倒入葱花。#\n6. 油里葱花出香倒入豆腐，翻炒几下然后放盐，十三香，#\n7. 出锅#'),(1249,'家常水煮鱼','荤菜','鲤鱼，别的鱼也可以#\n油菜白菜豆芽都可以#','一条人多也可以多#\n适量就可以#','1. 把鱼洗好，去皮去鱼线#\n2. 把鱼肉剃下去#\n3. 把鱼骨鱼头鱼皮适量切好就可#\n4. 把鱼肉切片用玉米淀粉腌制十分钟左右就可，肉要是干可以放少许水#\n5. 葱姜蒜，麻椒红辣椒，油菜白菜，皮辣酱#\n6. 油烧开，放入皮辣酱炒熟放入葱姜蒜在炒放入水烧开放入鱼骨鱼头小火二十分钟在放入鱼肉十分钟，白菜油菜开水过熟放入器具，鱼出锅倒入放白菜油菜的器具里，葱姜蒜麻椒辣椒放入顶头，空锅把油烧开倒入鱼上既可食用#'),(1250,'小白菜大骨头汤','汤','大料#\n盐#\n花椒粉#\n味精#','一颗#\n自定#\n一点调味就可以了#\n适量#','1. 把大骨头洗干净，放入高压锅，加入水，水可多放些，加入盐、花椒粉、大料，再放一小片姜！大约要压30分钟，骨头的肉就会松软，骨头的营养也就都在汤里面了。#\n2. 把小白菜洗好，放在一旁备用#\n3. 30分钟结束后，打开高压锅，放入小白菜，把小白菜翻入汤中，微微盖上锅盖，等小白菜变蔫就可以停火了，加入适量味精（加入小白菜不要煮的时间太久，软了就可以了）#\n4. 配上一碗米饭，清淡营养，美味扑鼻而来，你还能招架的住吗！！#'),(1251,'五香酱牛肉','荤菜','牛键子#\n干黄酱#\n花椒粒#\n桂皮#\n八角#\n丁香#\n老抽#\n冰糖#\n小茴香#\n生姜#','600g#\n1小勺#\n#\n#\n#\n#\n#\n#\n#\n#','1. 酱牛肉应该用牛建子肉做,,,我买的这个肉我也不知道是什么部位的,,,价牌上写的是\"精瘦肉\"\"\"\"。算了。。凑合了#'),(1252,'粽子鸡翅','荤菜','鸡翅#\n熟粽子#\n鲜粽叶#\n老抽#\n糖#\n黄酒#\n姜片#\n葱段#','8只#\n两只#\n两张#\n两汤翅#\n1汤翅#\n1 汤翅#\n#\n#','1. 熟粽子切成大块备用。#\n2. 鸡翅洗净擦干水份。锅内油热后，放入鸡翅，一面煎黄后，翻面再煎黄。#\n3. 加入黄酒、老抽、糖、姜片、葱段、翻均匀。加入热水至没过所有食材。#\n4. 将粽叶略剪成大片，放入锅中同煮15分钟。#\n5. 待锅内汤汁收至略浓后，取出粽叶，加入适量盐调味，倒入粽子块翻炒一分钟左右，待粽子块表面均匀裹上汤汁即可关火。#'),(1253,'榨菜拌豆腐','素菜','包装榨菜#\n内脂豆腐#\n香菜#\n香油#\n砂糖#\n蚝油#\n生抽#\n大蒜#','20克#\n1盒#\n少许#\n#\n少许#\n#\n#\n2瓣#','1. 将榨菜用冷水浸泡10分钟备用（包装榨菜很咸，要用清水浸泡并换两次水，并加少许糖。才不至于太咸，）。#\n2. 榨菜切碎，大蒜剁成蓉。#\n3. 在一碗中加入生抽，蚝油，砂糖，香油搅拌均匀。#\n4. 准备一个长盘，刮胡刀片一片，内脂豆腐一盒。用刀片小心的在豆腐盒四周切开，掀起盒盖。将豆腐倒扣在长盘上，再在豆腐盒的一角横切一刀。豆腐盒一见空气，就会自动掉出在盘上了。#\n5. 在豆腐上铺上调好的料及汤汁点缀些香菜即可。#'),(1255,'肉末炒毛豆','荤菜','毛豆#\n肉末#\n橄榄油#\n高汤#\n淀粉#\n盐#\n红椒#','#\n#\n#\n#\n#\n#\n#','1. 红辣椒切丁，肉末用料酒，淀粉腌制五分钟。剥好的毛豆用水焯一下，煮至熟透，捞出沥干水份。#\n2. 锅里放油烧热，下腌制后的肉末炒散，放入焯过水的毛豆，翻炒均匀，倒入红辣椒丁，淋一些高汤，根据各自口味适量放入盐调味后起锅。#\n3. 颜色鲜艳，口感清淡，营养丰富#'),(1257,'三杯鸡','荤菜','鸡翅或鸡腿#\n九层塔、盐、生抽、老抽、糖、黄酒、花椒大料、葱姜蒜#','#\n#','1. 三杯鸡，顾名思义，一杯油、一杯酱油、一杯黄酒组成，将鸡肉处理成小块，坐油，花椒大料辣椒葱姜蒜一起爆香，放入鸡块爆炒，外皮成微黄色时加入盐、生抽、老抽、糖继续翻炒。上色均匀后加入黄酒没过鸡块，如觉得酒味太浓可一半酒一半水，大火烧开后小火收汁，出锅前两分钟再下入九层塔稍微收汁后即可。注意：下的早会减淡九层塔的香味#\n2. 比啤酒和可乐鸡翅更浓香#'),(1259,'鲜花入菜，清淡香甜【鸡蛋炒黄花菜】','素菜','黄花菜#\n鸡蛋#\n盐巴#','#\n#\n#','1. 把新鲜黄花的花蕊全部摘掉，就可以去掉大部分的秋水仙碱， 再把去掉花蕊的黄花放在淡盐水中浸泡30分钟。#\n2. 黄花菜清洗后用开水绰烫一会#\n3. 鸡蛋打入碗里，加点盐，搅拌均匀，锅中底油，油热倒入鸡蛋液摊开，最好开小火，时间不要长，15秒这样就行了。#\n4. 倒入黄花菜翻炒几下，然后稍微加点水，倒入少许盐巴调味即可#'),(1260,'素炒平菇','素菜','平菇#\n青椒#\n葱蒜#\n十三香#\n盐#\n鸡精#\n香油#\n辣椒面#','500g#\n2个#\n#\n#\n#\n#\n#\n#','1. 如图所示，平菇撕开，青椒切丝，葱切沫，蒜切片#\n2. 热锅冷油，油到八分热时放葱蒜炝锅，放少许辣椒面。#\n3. 爆出葱香后放平菇翻炒（喜欢汤汁多的可以多炒一会），放适量十三香，盐。翻炒均匀。#\n4. 约一两分钟后放青椒丝炒匀，放适量鸡精，关火淋上香油即可出锅。#\n5. 今天炒的汤汁多了点，因为婆婆爱吃汤泡饭，就炒成这样了#'),(1261,'米粉蒸肉','荤菜','精瘦肉#\n粘米粉#\n腌肉料#','330g#\n适量#\n25g#','1. 肉切片腌制半个小时，可以放一些料酒#\n2. 把腌肉汁液倒出，不要使肉很湿#\n3. 把粘米粉（也就得大米粉）倒入肉片中拌匀上锅蒸，出锅造型#'),(1262,'红烧土豆鸡翅','荤菜','鸡翅中#\n大土豆#\n姜#\n料酒#\n老抽#\n盐#\n糖#\n鸡精#\n葱或青蒜#','8#\n1#\n#\n#\n#\n#\n#\n#\n#','1. 鸡翅中洗净，两面用刀各划一下，放入容器中，加入少许料酒和老抽腌一会儿（我腌了大概十分钟）；#\n2. 土豆去皮切成块；#\n3. 炒锅中加油和姜片（油不要多放，因为鸡翅会出油），等油锅热了，放入鸡翅（腌的汁不要在此时倒入锅中）翻炒片刻；然后放入土豆块一起翻炒，倒入刚才的腌汁，觉得颜色不够的话，可再加些老抽；加水，盖上锅盖，大火煮五六分钟，转小火煮七八分钟；#\n4. 开盖，在小火状态下调味，加盐、糖、鸡精，出锅，撒上葱末或青蒜末。#'),(1263,'猪肉闷豆芽','荤菜','肥瘦猪肉#\n黄豆芽#\n葱姜蒜#','500g#\n500g#\n适量#','1. 肉带点肥肉（可以炸点油，这样炒出来更香点）切好肉，豆芽洗干净，沥水备用！#\n2. 葱姜蒜（我今天买了点香菜，可以放点，没有也可以不放的）#\n3. 少放点油，因为那点肥肉可以炸出来油的，炒饭肉有些变色时加入姜蒜，翻炒一份钟，加入豆芽！#\n4. 豆芽放进去不要加水，把锅盖盖上把豆芽的那种味道闷掉，最后闷的豆芽水分没有多少的时候加点水，放盐等，再翻炒两分钟就可以了！#\n5. 出锅前放葱花，翻两下（我放了点香菜）#'),(1264,'清炒芥兰','素菜','芥兰#\n盐#\n蒜末#\n鸡精#','300g#\n1勺#\n2颗#\n1勺#','1. 锅烧热倒油 放蒜末出香味 倒芥兰 炒软后放盐 鸡精就行了#\n2. 炒好了 装盘#'),(1265,'油焖大虾','荤菜','虾#\n酱油#\n蚝油#\n花生油#\n盐#\n糖#\n玉米淀粉#','一斤#\n#\n#\n半碗#\n半勺#\n半勺#\n半勺#','1. 虾用水龙头冲洗干净，剪去虾须虾枪。#\n2. 热锅下油，（油要多一点）大火下虾把虾焖煎到虾壳微焦，翻面，同样焖煎到虾壳微焦。#\n3. 转中火倒入所有调味料翻炒（盐，糖，淀粉，酱油，蚝油预先用100ml水调匀），收汁，出锅。#'),(1266,'凉拌莴苣丝----倍儿爽（新手零失败）','素菜','盐#\n蒜碎#\n白醋#','一小勺#\n若干#\n20毫升左右#','1. 莴苣去皮切丝（我抄了一下，开水放进接着捞起来）#\n2. 将盐、白醋、蒜碎拌匀即可。醋味要浓一些，主要吃的就是酸香味，可以尝尝，不够可再加点。#'),(1267,'培根卷金针菇','荤菜','培根#\n金针菇#\n腌料#','16片#\n1包#\n（个人口味）#','1. 准备上图物品，这个怎么卷，洗，我就不废话了（最后用半根牙签固定）#\n2. 我用的是这个，你可以按自己口味啊#\n3. 腌制10～15分，两面哦#\n4. 下锅炸，到金针菇变黄（中火）#\n5. 炸好后，就是这样啦#\n6. 摆个盘#'),(1268,'爆炒河虾','荤菜','河虾#\n料酒、姜、香菜、芹菜杆#\n盐、鸡精、白糖#','一斤多#\n少许#\n少许#','1. 河虾处理干净，清洗沥水备用。#\n2. 芹菜杆少许、姜切粒、香菜少许。#\n3. 锅烧热，加入适量食用油，小火把姜炒香。大火把河蟹放入爆炒，一勺盐，鸡精，小半勺白糖，一直翻炒。放适量料酒炒至成熟。#\n4. 加少许芹菜杆提香，喜欢吃辣的可以放些干辣椒一起炒。#\n5. 爆炒河虾，味道极其鲜美！#'),(1271,'鸭肉炒茭白','荤菜','鸭肉切片#\n茭白#\n蒜#','适量#\n3根#\n2只#','1. 茭白三根，切片备用！#\n2. 鸭肉煸炒，成深色即可！同时把蒜蓉一起放入煸炒，很香哦！#\n3. 煸炒茭白，再把鸭肉一起煸炒，放入调味料，生抽适量，糖适量，盐适量，我另外又放了一点耗油！#\n4. 成品图——鸭肉片炒茭白！#'),(1272,'#菁选酱油试用之水煮杏鲍菇','素菜','杏鲍菇#\n菁选酱油#\n食用油#\n豆瓣酱#\n水淀粉#\n白糖#\n盐#\n花椒#\n芝麻#\n辣椒#\n香菜#\n花椒粉#','300克#\n1茶匙#\n3汤匙#\n1汤匙#\n1汤匙#\n1茶匙#\n适量#\n几粒#\n少许#\n1段#\n少许#\n少许#','1. 杏鲍菇洗净，用削皮刀削成薄片。#\n2. 炒锅倒油，放入豆瓣酱炒香。#\n3. 豆瓣酱炒出红油后加适量水，加盐，白糖，煮开。#\n4. 放入杏鲍菇。#\n5. 加菁选酱油。#\n6. 淋入少许水淀粉，再次煮开后关火，倒入容器中。#\n7. 加少许花椒粉。#\n8. 撒熟芝麻。#\n9. 放入辣椒段。#\n10. 炒锅倒油，放入花椒炸香。#\n11. 趁热将花椒油烹入。#\n12. 放入少许香菜即可。#\n13. 水煮杏鲍菇，米饭杀手哦！#'),(1273,'满园春色','不属于任何一类','牛里脊#\n洋葱#\n大辣椒#\n西红柿#\n小青柠#\n孜然粉#\n盐#\n生粉#\n生抽#\n干贝素#\n油#','500g#\n小1个#\n1个#\n1个#\n1个#\n2勺#\n适量#\n1勺#\n1勺#\n1勺#\n适量#','1. 首先肉切长条，除油和孜然粉外，全部腌制30分钟备用，其次将洋葱切丝，大辣椒掰块，西红柿从中间切开铺在锡纸上将腌制好的肉用牙签串好放在菜上面，涂一层油，放入190度的烤箱10分钟拿出来再刷一层油撒上孜然粉再烤3分钟，满园春色就出炉了#\n2. 偶的满园春色，一盘不行，又重复做了一次，才算满足了偶家的两个活宝，哈哈#'),(1274,'长帝行业首款3.5版电烤箱CKTF-32GS——鹌鹑蛋烤磨菇','荤菜','磨菇#\n芦笋#\n培根#\n鹌鹑蛋#\n盐 现磨黑胡椒#\n黄油#','9个#\n一把#\n2片#\n9个#\n适量#\n适量#','1. 准备好全部食材后，磨菇洗净后去根蒂，培根切小丁#\n2. 洗净的芦笋在放了盐和油的沸水中氽烫#\n3. 捞出，沥干水份摆放在刷了黄油的烤盘里#\n4. 磨菇窝里放上培根丁#\n5. 放入鹌鹑蛋，摆放到烤盘里#\n6. 全部做好后撒上盐和现磨的黑胡椒#\n7. 放入长帝行业首款3.5版电烤箱CKTF-32GS烤箱，设置立体热风循环180度20分种#\n8. 随着一声叮声，美味的鹌鹑蛋烤磨菇就做好了~#\n9. 是不是很诱人呀~开吃~#'),(1275,'快手菜--胡萝卜炒豆腐丝','素菜','胡萝卜#\n豆腐丝（买成品）#\n盐#\n油#\n酱油#\n蒜#\n花椒#','一个#\n适量（根据个人喜好）#\n少许#\n适量#\n少许#\n两瓣#\n7颗#','1. 把胡萝卜擦丝，豆腐丝切段（长度在10厘米左右)搁置旁边备用#\n2. 开火起锅，锅内放油小火，把切好的蒜粒和花椒炸香#\n3. 然后把胡萝卜丝放入锅内翻炒，接着把豆腐丝放入一起翻炒数下，(此时火力为中火)#\n4. 好了，出锅喽！看着红白相间的颜色很有食欲吧~~~#'),(1276,'菁选酱油之咸鱼茄子煲（沙锅茄子）','荤菜','茄子#\n咸鱼#\n葱#\n蒜末#\n红辣椒#\n肉糜#\n洋葱#','两个#\n少许#\n两根#\n少许#\n少许#\n少许#\n少许#','1. 茄子切条状，放入三四小勺淀粉，拌匀。#\n2. 沙锅底下垫上洋葱片。#\n3. 茄子入油锅炸至表面微黄#\n4. 沥干油放入铺了洋葱的沙锅上面。#\n5. 撒入少许盐。#\n6. 菁选酱油少许。#\n7. 另起油锅，依次放入葱蒜末，肉糜，切成丁的咸鱼，红辣椒，煸出香味。#\n8. 放入刚刚炸好的茄子上面，放入半碗水。#\n9. 盖上盖，大火煮开后转小火煮10分钟。#\n10. 煮好后搅拌均匀，放入鸡精，撒上香葱即可。热气腾腾的茄子煲就可以上桌了。#\n11. 我的试用：豆果酱油。#'),(1277,'孜然羊肉','荤菜','羊肉片#\n西葫芦#\n洋葱#\n孜然#','250g#\n50g#\n50g#\n#','1. 准备食材，西葫芦切片，羊肉切片，洋葱切丝，泡花椒水#\n2. 花椒水放凉后，搅拌入羊肉，加少许淀粉，料酒拌均匀，热锅凉油炒熟#\n3. 葱蒜呛锅，放入西葫芦断生放入洋葱，羊肉，料酒，盐，生抽少许，孜然翻炒#\n4. 出锅后再撒孜然，辣椒，淋少许热油#'),(1279,'西红柿焖鸡','荤菜','鸡块（鸡腿肉，鸡翅均可）#\n西红柿#\n姜，蒜头，香菜#','半只#\n一个#\n适量#','1. 鸡切小块，放料酒，盐腌制15分钟。西红柿洗干净，切块#\n2. 姜，蒜，切片备用#\n3. 起油锅，待油七成热，放两片姜，倒入鸡块，快速翻炒，至鸡块略现微黄，铲起备用#\n4. 再下适量油，待油热，放入剩下的姜片，和蒜片，爆香后，倒入鸡块翻炒片刻，倒入酱油，适量料酒，辣椒酱适量，炒均匀后，加入水，能淹没鸡块即可。#\n5. 盖上锅盖，小火焖15-20分钟后，开盖，加入西红柿，开大火收汁。  待西红柿软后，加入香菜，出锅！#'),(1280,'螃蟹年糕','荤菜','螃蟹#\n年糕#\n鲍鱼#\n鸡蛋#\n青菜#\n胡萝卜#\n酱肉#\n大蒜#\n葱#\n番茄#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 先将材料切片 切块#\n2. 锅中放入黄油，然后放入所有东西除了蛋跟青菜，加水，煮15分钟左右#\n3. 最后加入鸡蛋跟青菜，加盐搅拌。…因为酱肉有味道所以盐不用太多#'),(1281,'葱花跑蛋','荤菜','鸡蛋（我用的是土鸡蛋）#\n葱#\n盐#','2个#\n#\n#','1. 拿一个碟子，把蛋敲在碟子里，葱切成葱花，放入装蛋的碟子中，加入盐，一起搅拌均匀#\n2. 锅烧热，放油，等油烧至8成热，将搅拌好的蛋花，倒入锅中，等蛋花旁边已经慢慢凝固，把锅抬起，按一个圆形，扭动锅，把中间未凝固的蛋花，往旁边流去，变成一个圆形的，然后翻一面，另外一面因为有葱花，稍微煎一会儿，就可以起锅，避免葱花焦掉。#'),(1282,'粉蒸羊排','荤菜','羊排#\n土豆#\n红薯#\n粉丝#\n生抽#\n老抽#\n料酒#\n豆瓣酱#\n胡椒粉#\n姜#\n蒜#\n芫须#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 首先肉肉加料酒、生抽、老抽、胡椒粉、豆瓣酱码味道两小时。#\n2. 土豆红薯切坨坨，混点盐和油；粉丝泡软，沥干，加盐混匀。肉肉里面加点高汤，加米粉，混匀。土豆红薯铺最下面，然后是粉丝，最后铺肉。#\n3. 上锅大火蒸一小时左右，撒盐蓿、葱，浇姜蒜水#'),(1283,'莴笋火腿丁','荤菜','莴笋#\n火腿肠#\n干辣椒（小）#\n小葱叶#','500g#\n100g#\n些许#\n些许#','1. 1.将准备好的莴笋与火腿肠切丁，备用。2.待油烧开，倒入莴笋丁翻炒。（火腿肠容易炒烂）。3.炒至七、八分熟，倒入火腿肠。4、翻炒片刻，菜略熟，即可起锅。5、起锅后，撒入葱花，一道美味的莴笋火腿丁就完成了。#'),(1284,'粉丝沙拉（中華春雨サラダ）','素菜','粉丝#\n黄瓜#\n火腿切片#\n绿豆芽#\n木耳#\n★调料汁#\n寿司醋#\n生抽#\n香油#\n鸡精#\n白芝麻（熟）#\n大蒜粉#\n黑胡椒#','1团#\n1根#\n3片#\n30g#\n15g#\nドレッシング#\n2.5大勺#\n1.5大勺#\n2大勺#\n1茶勺#\n2茶勺#\n少许#\n少许#','1. 粉丝开水炒熟，冰镇后，剪短。豆芽和木耳也要用水抄熟。黄瓜去皮切丝，火腿切片切丝。#\n2. 制作调料汁，将★的材料放入一个碗里搅拌均匀。#\n3. 拿个大盆，把所有材料和调料汁搅拌均匀，摆盘。#\n4. 完成！爽口开胃营养十足的粉丝沙拉就做好了！#'),(1285,'酿豆腐猪婆菜#比暖男更暖的是#','荤菜','陈皮#\n糯米#\n香菇干#\n蜡肉#\n蜡肠#\n香菜#\n葱#\n盐#\n油#','10克#\n2斤#\n2两#\n2两#\n半斤#\n1两#\n1两#\n适量#\n适量#','1. 白豆腐大约35块，将糯米加水煮熟（有点手忙脚乱，所以忘拍图片了，请凉解）#\n2. 锅里烧油，放入白豆腐炸至金黄色即可（如果觉得麻烦也可以直接买已经炸好的豆腐）#\n3. 蜡肉，蜡肠，香菇切碎#\n4. 切碎的香菜和葱#\n5. 把泡过水的陈皮干也切碎#\n6. 把糯米和所有菜馅一起搅拌好#\n7. 用手指把豆腐里挖松动，不要太用力因为容易挖破，然后把糯米馅酿进豆腐里#\n8. 已经泡过澡的猪婆菜，酿好后的收口朝下放#\n9. 这是都酿好的，然后放入锅里加水油盐开始煮45分钟，直到煮熟#\n10. 成品#'),(1286,'黄瓜小炒','素菜','黄瓜#\n木耳#\n腐竹#\n干辣椒#\n味极鲜#\n盐#','1根#\n适量#\n适量#\n2个#\n适量#\n少许#','1. 本来准备两根黄瓜的，但是发现一根就好了，干辣椒切段！#\n2. 木耳，腐竹泡好，撕小块，切小段！#\n3. 油锅一热放入干辣椒，闻到香味，放入黄瓜翻炒，断生即可！#\n4. 依次加入木耳，腐竹翻炒，加入味极鲜，盐，翻炒片刻即可！#\n5. 一顿简单的午饭出来啦！一边烤面包一边做，做好了菜，面包也烤出来啦！#'),(1287,'蒜蓉粉丝娃娃菜','素菜','娃娃菜#\n蒜泥#\n剁椒#\n盐#\n糖#','#\n#\n#\n#\n#','1. 一个娃娃菜切四份摆盘，粉丝开水烫过每个娃娃菜上放少许，用油炝过的蒜泥放在粉丝上，炝蒜泥里面放盐适量，糖少许，剁椒放盐适量，油炝过，放与蒜泥上，剁椒根据个人口味适量#'),(1289,'千丝万缕黄金虾','荤菜','上好虾仁#\n鸡蛋#\n面条#\n盐#\n花椒粉#\n食用油#\n柠檬#\n蛋黄酱（沙拉酱）#\n喜欢的水果粒#','300g#\n一个#\n50g#\n适当#\n适当#\n适量#\n一个#\n少许#\n想放多少就放多少#','1. 将虾仁从背部抛开，去虾线，用花椒粉，盐，柠檬汁加以研制#\n2. 将面条煮好注意煮到7成熟！面条放入凉水中，捞出滴一点油，以免粘在一起！#\n3. 用面条将虾包好，裹少许生粉（淀粉），放入油锅中炸制，注油温不要太高！4成热就好！炸至金黄！#\n4. 炸好后，等待油温再次升高！放入炸好了的虾进行复炸！使在虾中的油逼出去！并使其表面更脆#\n5. 放入沙拉酱！水果粒，拌匀！OK#'),(1290,'凉调藕片','素菜','藕#\n蒜#\n姜#\n盐#\n粗#','一节#\n一瓣#\n两片#\n适量#\n适量#','1. 莲藕刮皮后切成片备用，蒜和姜切成末#\n2. 开火煮水，水沸腾后将藕片放入锅中焯熟#\n3. 焯藕片的过程中准备一盆凉水#\n4. 焯个六七分钟后就将藕片从热水中捞进事先准备的凉水中镇凉。#\n5. 将藕片控干水份后加入姜蒜末和盐、醋调好即可。#'),(1291,'洋葱炒木耳','素菜','调料#\n木耳#\n胡萝卜#\n洋葱#\n蒜#\n酱油#','#\n#\n#\n#\n#\n#','1. 糖尿病菜谱其中之一——#\n2. 把干木耳泡发2小时，成（图）现状。#\n3. 放水里燥一下，捞出沥干。#\n4. 洋葱切成块状。#\n5. 先炒洋葱和萝卜，炒一会儿放入调料，倒入木耳。#\n6. 成品。。顺便把察剩下胡萝卜察成丝丝调成凉菜。#\n7. 美味可以享用了。#'),(1292,'啤酒鸭','荤菜','鸭#\n八角#\n桂皮#\n蒜头#\n姜#\n黄酒#\n醋#\n啤酒#\n大葱#','1只#\n2个#\n1个#\n5瓣#\n3片#\n少许#\n少许#\n1听#\n1个#','1. 准备原材料，鸭子剁块，姜切片，葱切断，八角，桂皮洗净待用#\n2. 先将鸭子和两片姜放入锅中灼水，去除腥味捞出，用清水冲洗两下！#\n3. 锅洗净放少许油，将蒜头，姜片，八角，桂皮放入锅中（吃辣的放入红辣椒），中火爆香，火大了蒜头辣椒容易糊。爆香后放入准备好的鸭块，翻炒炸出油来，至鸭块成变色，有点像烤鸭的颜色！#\n4. 放入黄酒，醋少许翻炒出香味！倒入啤酒，大火烧开，小火闷烧至汤汁变少#\n5. 放盐翻炒，也可以放鸡精，加葱段翻炒几下装盘！#'),(1293,'胡萝卜土豆丝饼','主食','土豆#\n胡萝卜#\n香菜#\n面粉#\n盐#','1个#\n半个#\n2棵#\n1汤匙#\n1汤匙#','1. 土豆去皮（忘拍胡萝卜啦）；#\n2. 土豆和胡萝卜洗干净后，分别切丝；#\n3. 把土豆丝和胡萝卜丝放进大碗里，加入1汤匙的盐进去，用手反复抓压几次，挤出土豆丝的水分，土豆丝变软就可以啦；#\n4. 把土豆、胡萝卜丝洗一下，沥干水分后放进碗里，加入香菜碎；#\n5. 加进1汤匙的面粉，把所有材料用筷子搅拌均匀；#\n6. 烧热平底锅，把材料分成三份，慢火煎至金黄；#\n7. 翻面后，继续慢火煎着金黄，为土豆饼多翻几次身，就不怕煎糊了；#\n8. 好了，可以上桌开吃咯，香香脆脆的。#\n9. 看看特写：#'),(1294,'香煎带皮土豆块','素菜','土豆#\n盐#\n五香粉#','随意#\n适量#\n适量#','1. 土豆洗净切块#\n2. 铁锅烧油到七八成热，均匀撒上盐在锅里#\n3. 转中小火将土豆每个年都煎黄#\n4. 起锅撒上五香粉和香葱末，完成#'),(1295,'好心情小炒','不属于任何一类','韭菜#\n毛豆米#\n香干#\n肉丝#','250g#\n100g#\n2块#\n150g#','1. 1.韭菜洗净切断。肉丝先腌制并炒好。2.锅内油热，放下毛豆米，香干，再放入韭菜，肉丝，翻炒即可，加，盐，糖，鸡精，生抽。#'),(1296,'素炒米粉','主食','豆芽#\n油麦菜#\n盐#\n酱油#\n五香粉#\n咖喱粉#','适量#\n适量#\n适量#\n适量#\n少许#\n少量#','1. 干米粉温水浸泡3分钟左右备用。#\n2. 鸡蛋打散成蛋液炒熟备用。#\n3. 锅坐底油下葱蒜炝锅，分别下米粉，配菜，调料适量大火快炒出锅即可。#'),(1297,'菁选酱油试用之四喜丸子','荤菜','肉馅#\n鸡蛋#\n葱#\n姜#\n蒜#\n酱油#\n冰糖#\n盐#\n八角#\n香叶#\n花椒#\n面包糠#','300g#\n一个#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n1粒#\n1片#\n适量#\n适量#','1. 肉馅加入鸡蛋，葱姜末朝一个方向搅拌，肉馅上劲儿#\n2. 加入面包糠继续搅拌（如果没有面包糠，也可以用馒头渣儿）#\n3. 团成丸子去油锅煎至金黄#\n4. 丸子捞出，锅中剩些底油，#\n5. 放入准备好的调料，先不放冰糖和香叶#\n6. 加热水，丸子，酱油，冰糖，香叶，中小火炖至汁液粘稠#\n7. 出锅，可撒些配菜#'),(1298,'美味炒黄瓜','素菜','黄瓜#\n火腿肠#\n鸡蛋#','300g#\n一根#\n一个#','1. 准备好材料。#\n2. 先煎鸡蛋#\n3. 再加入切好的火腿肠,翻炒一下后盛起来放一旁备用。#\n4. 放油，黄瓜入锅，炒至断生即可#\n5. 加入之前炒好的鸡蛋火腿，放适量盐，鸡精，香葱。#\n6. 美味彩色黄瓜出锅，开吃！喜欢请+我v信：zengshan311#'),(1299,'红烧豆腐虾仁','荤菜','豆腐#\n虾仁#\n盐#\n料酒#\n酱油#\n淀粉#\n姜#','#\n#\n#\n#\n#\n#\n#','1. 超市买的冷冻虾仁，虾仁洗干净后，用盐，料酒，少许酱油，淀粉腌渍10分钟这样。#\n2. 豆腐切小块，锅中底油，放点姜末爆香一下，然后倒入豆腐稍微煎一下。#\n3. 锅中加些水，倒入虾仁，加点酱油，轻轻地搅炒一下。#\n4. 大火烧开，加些盐，转成小火烧四，五分钟这样。#\n5. 汤收的差不多的时候，用淀粉勾个芡就可以了。#'),(1300,'炒牛肉','荤菜','牛肉#\n洋葱#\n盐#\n淀粉#\n小苏打#\n芝麻#\n孜然#\n味精#\n油#\n十三香#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 牛肉切薄片，放少许料酒（辅料忘记料酒啦），淀粉和小苏打，抓一抓，腌上20分钟左右，准备洋葱。油热后葱蒜爆锅，下入牛肉，炒变色，再炒几分钟就熟了，下去洋葱，芝麻孜然辣椒面，炒一炒，放其他调料，就出锅吧。洋葱我炒的时间短，还有点生味。一定要放淀粉和小苏打抓，炒出来的牛肉就会很软，一点都不硬。#'),(1301,'白灼虾','荤菜','基围虾#\n姜#\n大葱#\n料酒#','250g#\n2片#\n2条#\n一汤匙#','1. 锅内放适量水、姜、葱结、并煮沸，把洗淨的虾放入锅中、同时倒入料酒，盖锅盖煮1分钟后捞起。#\n2. 冲凉水后、装滤篮滤干水，装盘即可。#\n3. 蘸料：1姜蓉、葱白碎、生抽、热油。2蒜蓉、芫茜碎、辣椒碎、生抽、热油。#'),(1302,'葱油金针菇','素菜','金针菇#\n海天蒸鱼豉油#\n海天特级金标生抽#\n香葱#\n油#','400g#\n1汤匙#\n1汤匙#\n2棵#\n适量#','1. 将金针菇择去蒂部并洗净沥水，摆盘备用。#\n2. 金针菇上浇上海天蒸鱼豉油，上锅蒸几分钟后关火取出，淋上海天特级金标生抽。#\n3. 香葱切成葱花，放在金针菇上，最后淋上一层刚烧热的油即可。#\n4. 完成了。#'),(1303,'懒人鸡翅','荤菜','鸡中翅#\n盐 胡椒 啤酒 酱油#','5块#\n适量#','1. 玉米片，我是用啤酒瓶杆碎的，有的潮了杆不碎可以用微波炉转一分钟。#\n2. 鸡翅洗干净，在正反面划两刀，放盐祘片 姜片 胡椒 啤酒#\n3. 倒啤酒和鸡翅平就可以，然后腌制15分钟，啤酒可以缩短腌制时间。#\n4. 裹上玉米片碎。#\n5. 我的玉米片碎弄得少了有点不够，哈哈。裹好后放微波炉中高火转3分钟，然后反面再转3分钟，一共12分钟，就可以，不过大家要注意自己家微波炉有的中火就可以了，有的要高火才行#\n6. 成品，玉米碎有点少，美观不太好#'),(1304,'盐水煮虾','荤菜','姜#\n葱#\n大料#\n盐#','#\n#\n#\n#','1. 把虾洗干净放进锅里煮，把盐，葱，姜，蒜，大料也放进去一起煮，十分钟就好了#'),(1305,'春香入味。。。椿意盎然~：）','不属于任何一类','香椿#\n虾#\n橄榄油#\n盐#\n花椒#','#\n#\n#\n#\n#','1. 简单原料：香椿、虾、盐、花椒、橄榄油~#\n2. 水中加盐、花椒烧开放入虾汆水~~：）#\n3. 香椿也一样过水待用~#\n4. 香椿控干水分~放入盐及橄榄油~：）#\n5. 将香椿用粉碎机搅打成汁~#\n6. 将搅打好的香椿汁淋在虾上~~搞定开动~~：P#'),(1307,'宁式溜肝尖','荤菜','鲜猪肝#\n柿子椒#\n洋葱#\n葱#\n姜#\n蒜#','半斤#\n一个#\n少许#\n#\n#\n#','1. 先将猪肝切片后，加入盐和淀粉拌匀:P#\n2. 然后将柿子椒切成如图得块，洋葱亦是如此，放盘备用#\n3. 锅内放油，葱姜蒜爆香后放入肝，当猪肝变色后迅速倒入柿子椒、洋葱，翻炒！放料酒，生抽，盐少许，鸡汁！翻炒均匀后收火，淋入芝麻油！（≧≦）大功告成！简单到爆哦！亲们可以在出锅得时候在放些蒜片来提味哦！#\n4. 叮～一盘家常溜肝尖OK啦！#'),(1308,'老鸭煲','汤','鸭子#\n罗汉笋#\n干香菇#\n姜片#\n料酒#\n盐#\n葱花#','小半个#\n#\n#\n#\n#\n#\n#','1. 干香菇事先泡发，然后去蒂切片。罗汉笋我买的是4块钱一袋，也可以买其它笋子代替的。笋子买回来多洗几遍，然后中间切一刀就行了，喜欢吃小点的，可以多切一刀。#\n2. 鸭子洗干净，倒入烧开的水，撇出血水和浮沫，煮几分种后捞出。#\n3. 换砂锅，水开倒入去过浮沫的鸭子，加姜片和一些料酒。#\n4. 水开倒入切好的香菇和笋子，大火烧开后转小火。一定要最小火，余下的时候你就可以去看电视了。#\n5. 小火最起码1个半小时才可以上桌，那样鸭子才好吃，起锅前加适当的盐，撒上些葱花即可。#'),(1309,'麻排','荤菜','净排#\n酱油#\n糖#\n耗油#\n料酒#\n辣椒面#\n麻油#\n五香粉#\n花椒粒#\n盐#','约500g#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 排骨泡半个小时，去除血水，洗净。用厨房纸吸干水分。#\n2. 调制料汁#\n3. 排骨放进去腌几个小时，随意，至少两个小时#\n4. 用锡纸把排骨包好就可以放进烤箱评烤了，上下火200°中层烤30分钟。根据各家烤箱不同，时间自己掌握哦！#\n5. 排骨烤熟后把出的汤汁倒掉，锡纸铺平排骨排好继续烤五六分钟，看表层微焦即可，翻面同样烤至微焦#\n6. 烤好装盘了！还可以撒上一些芝麻孜然#\n7. 外焦里嫩、麻辣甜香。好喜欢嘴唇麻酥酥的感觉，甜甜的，好吃极了！#'),(1310,'鸡片炒杏鲍菇','荤菜','鸡胸肉#\n杏鲍菇#\n葱姜末#\n淀粉，料酒，盐，味精#','3条#\n3个#\n适量#\n适量#','1. 鸡胸肉，杏鲍菇切片#\n2. 鸡胸肉用少量淀粉，料酒腌制#\n3. 杏鲍菇焯水#\n4. 鸡胸肉过油#\n5. 葱姜炝锅，倒入鸡胸肉，杏鲍菇翻炒#\n6. 加入适量盐，味精调味，出锅#'),(1311,'酱焖豆角','素菜','豆角#\n海天黄豆酱#\n蒜末#\n水#\n大料#\n葱#\n糖#','1斤#\n20g#\n1头#\n适量#\n1个#\n两片#\n5g#','1. 豆角洗净，蒜切末，葱切片#\n2. 热锅凉油，大料葱片炝锅炒出香味捞出葱片，倒入豆角，加入两小勺黄豆酱炒均匀，倒入凉水，盖盖。汁收到一半的时候放入 一小勺糖，翻炒两下，盖盖。等汤汁收好了放入蒜末翻炒两下就可以出锅了！#'),(1312,'土豆条辣椒酱','素菜','土豆#\n干红辣椒#\n大酱#\n生抽#\n鸡精#\n十三香#\n葱花#','#\n#\n#\n#\n#\n#\n#','1. 土豆去皮洗净切成条状。锅里下油烧热，放入干红辣椒段（油不用太热 以免辣椒糊锅） 7秒以后放入土豆条翻炒#\n2. 不断翻炒使均匀 土豆条炒成金黄色#\n3. 放入一圈生抽 翻炒#\n4. 再淋一圈大酱继续翻炒 使均匀  买的大酱不同味道也不同 撒入鸡精和十三香#\n5. 加水 和土豆平齐 太多汤大 太少糊锅#\n6. 加盖开炖 准备葱花#\n7. 汤少土豆有点黏糊的时候小火#\n8. 马上将葱花加入 翻炒均匀 熄火 香喷喷的土豆辣椒酱就好了#'),(1313,'蒜台炒肉','荤菜','盐#\n十三香#\n油#\n味素#\n酱油#','#\n#\n#\n#\n#','1. 蒜台洗净，切段。#\n2. 肉切丝。#\n3. 锅里放油，六七层热，下肉丝翻炒。肉丝变色，放入十三香，酱油炒出香味。#\n4. 放入蒜台，爆炒，表皮开始有变化，放入盐，几粒味素。翻炒出锅。#'),(1314,'尖椒肥肠','荤菜','耗油#\n郫县豆瓣酱#\n盐#\n糖#\n老抽#\n水淀粉#\n葱姜蒜#','1汤勺#\n2汤勺#\n少许#\n少许#\n少许#\n少许#\n少许#','1. 熟肥肠清理干净，切段。尖椒（担心太辣可以换部分青椒）切菱形。#\n2. 锅底加少许油，八成热加葱姜蒜，出味后加肥肠，郫县豆瓣酱，耗油，糖，老抽，上色后出锅。#\n3. 锅底加油少许，油热后加尖椒，点少许水。八成熟加入肥肠翻炒，约半分钟后加少许盐，水淀粉适量，出锅即可。#'),(1315,'夏日必备之凉菜--爽脆烧辣椒','素菜','生抽#\n白醋#\n纯芝麻油#','适量#\n适量#\n适量#','1. 准备好适量青辣椒或红椒（图片是四个青辣椒一个人滴份量）用煤炉火或者煤气烧焦表层。#\n2. 然后用清水洗净表层烧焦滴皮，用凉开水过一下充分洗净。#\n3. 最后，把洗净滴辣椒去蒂手撕成一条一条放在容器中，倒入生抽、白醋、纯香芝麻油调味即可。嗜辣的还可以加少许辣椒粉！#'),(1316,'爽口黄瓜','素菜','黄瓜#\n辣椒油#\n陈醋#\n盐#\n香油#\n蒜末#','1根#\n适量#\n适量#\n少许#\n少许#\n适量#','1. 黄瓜去皮，用刀面拍打后切块，放入蒜末、盐、辣椒油、香油、陈醋，搅拌均匀后腌制5分钟即可！#'),(1317,'小清新白菜卷','素菜','白菜叶#\n菠菜#\n鸡蛋#\n盐#\n玉米油#\n蚝油#\n生抽#\n生粉汁#','6片#\n适量#\n1个#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 新鲜的蔬菜浸泡清理干净。#\n2. 蔬菜加点盐在热水里淖熟，鸡蛋液摊成蛋饼，切碎备用。#\n3. 白菜叶平铺，上面铺放一些菠菜和蛋皮，然后将白菜叶卷起，包裏好。#\n4. 热锅放一点玉米油，然后放一勺蚝油、一小勺生抽炒制，最后将生粉汁加入，搅拌均匀淋在白菜卷上即可。#'),(1318,'三色滑虾仁','荤菜','虾仁#\n胡萝卜#\n黄瓜#\n红辣椒#\n白辣椒#\n盐#\n淀粉#\n料酒#\n蚝油#','半斤#\n一根#\n一根#\n半个#\n半个#\n#\n#\n#\n#','1. 虾仁洗净去线后加入料酒，花椒粉，淀粉后，拌均，腌制15分钟。#\n2. 材料切丁（大小依据个人爱好），蒜#\n3. 虾仁在油锅里煸炒7成熟时拿起备用，另起油，倒入胡萝卜翻炒，再加入红椒等～这时倒入蚝油翻炒均匀，倒入过油的虾仁，一分钟后加入黄瓜翻炒，所有材料在一起翻炒半分钟后，起锅～^_^#'),(1319,'蒸白蒿','素菜','白蒿#\n面粉#\n蒜#\n盐#\n糖#\n酱油#\n醋#\n香油#','200g#\n20g#\n1头#\n2g#\n2g#\n2ml#\n5ml#\n少许#','1. 白蒿择洗干净，攥干水分！#\n2. 裹适量干面粉，上锅蒸八分钟；#\n3. 蒜捣碎，配适量醋、盐、糖、酱油、香油调成蘸料，上桌即可享用。（这份料汁是另一个菜的，因为没有拍照，所以借用）#'),(1320,'之:豆豉蒸鱼干#菁选酱油试用#','荤菜','蒜#\n姜#\n白糖#\n米酒#\n菁选酱油#\n豆豉#\n盐#\n油#','#\n#\n#\n#\n#\n#\n#\n#','1. 将鱼干用水泡软#\n2. 姜、蒜、豆鼓切碎。#\n3. 锅内放油烧热，下姜蒜炒，再放豆豉炒出香味。#\n4. 鱼干沥水，平铺在盘上。#\n5. 将炒香的姜蒜豆豉铺在鱼干上。#\n6. 淋些酱油#\n7. 加点白糖。#\n8. 淋些芝麻油。#\n9. 淋些米酒，撒点盐。#\n10. 放高压锅随饭一起蒸。#'),(1321,'陕北麻食','主食','盐  花椒面  味精【调料种类尽量少些，陕北吃法，讲究好厨子一把盐】#\n白葱，干辣椒#','最好放一个西红柿，颜色会非常漂亮，但我妈妈不喜欢西红柿所以我没放！#\n白葱切花   干辣椒切碎#','1. 面和好以后要发半个小时左右。#\n2. 发好之后把面团切成小方块，用大拇指再【陕北叫法是蒸鱉】上面捻一下。会变成这样的花纹。也可以直接在案板上弄。但是没有这种花纹的有筋道。#\n3. 豆腐，胡萝卜，土豆都切丁。锅里倒油至八成热的时候放干辣椒白葱花大火爆香，放土豆，胡萝卜丁，放盐，花椒。炒至金黄倒入开水改小火至胡萝卜变软。。#\n4. 放入捻好的麻食，大火烧开，改中火顿熟，放味精出锅。#\n5. 成品，看起来也很漂亮。#\n6. 放点油泼辣子，很过瘾！#'),(1323,'香菇肉片','荤菜','黄瓜~胡萝卜#\n葱~姜~蒜#','#\n#','1. 把香菇祛根~抹刀片成片~猪肉切片~黄瓜和胡萝卜切陵型片~葱切马蹄片~姜切丝~蒜切片~香菇用沸水汆烫以下~#\n2. 锅中加底油~用葱姜蒜爆锅~加猪肉炒香~加料酒~蚝油~少许酱油~糖少许~在把其他配料下入~用盐~鸡粉~白胡椒粉调味~大火翻炒几下~淋红油~撒上蒜片出锅！#'),(1324,'洋葱牛肉','荤菜','青椒#\n料酒#\n盐#\n生抽#\n姜汁#\n淀粉#\n胡椒粉#\n孜然粉#\n葱姜蒜#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 牛肉清水泡一会儿，中途多换几遍水，把血水泡出来。#\n2. 牛肉切片，放入料酒、盐、姜汁、胡椒粉，少许淀粉，抓匀腌制一会儿。#\n3. 洋葱、青椒切丝备用。#\n4. 锅中放入油，油热放入牛肉片，离火滑散，牛肉变色后放入葱姜蒜末，翻炒片刻。#\n5. 牛肉炒好后，盛出，用锅内油把洋葱青椒炒熟。#\n6. 加入炒好的牛肉片，放入少许生抽、孜然粉，炒匀。#\n7. 出锅前放入盐调味即可。#'),(1326,'红绿灯','不属于任何一类','红椒#\n蒜#','适量#\n适量#','1. 加油，放蒜，放青椒红椒翻炒，再放入玉米，最后加适量盐巴。很简单的一道菜#'),(1327,'麻汁蒜泥豆角','素菜','豆角#\n芝麻酱#\n醋#\n精盐#\n鸡精#\n香油#','400克#\n50克#\n50克#\n#\n#\n#','1. 豆角摘净，清洗干净#\n2.  锅中放适量清水，烧开后放入豆角，以淹没豆角为好，待豆角变色后捞出，放入凉水中浸泡，反复两次，待豆角完全变凉后捞出#\n3. 将豆角切段，一寸左右，放盘#\n4. 将麻酱加少许盐、醋、蒜泥、香油调匀#\n5. 根据自己口味将调好的麻酱汁淋在豆角上即可#'),(1328,'蒜苗炒肉片','荤菜','生抽#\n料酒#\n老抽#\n盐#\n油#','适量#\n适量#\n适量#\n适量#\n适量#','1. 先把肉切片倒入生抽料酒腌十五分钟。#\n2. 蒜苖洗净切段。起油锅爆炒肉片片刻。#\n3. 倒入蒜苗爆炒加老抽加少量水盖上锅盖。#\n4. 烧七分钟就起锅装盘。#'),(1329,'水煮肉片','荤菜','猪里脊#\n莴笋#\n好人家水煮肉片料包#\n大蒜#','300g#\n500g#\n1袋#\n两辦#','1. 猪里脊肉，切成薄片用好人家料包里面的腌肉料，放生抽，一点点盐腌制20分钟。#\n2. 莴笋去皮#\n3. 切成片#\n4. 所有食材#\n5. 锅里放少许油，炒莴笋，放点点盐。#\n6. 炒好后放入容器备用。#\n7. 锅里加水，放入料包#\n8. 煮沸后，放入腌制好的猪里脊肉，拿筷子搅拌均匀，一分钟后倒入容器。#\n9. 放入辣椒粉，麻椒粉，蒜末。#\n10. 锅里放油加热，冒烟后，到在辣椒粉上即可。#\n11. 成品#'),(1330,'番茄炒包菜','素菜','番茄#\n包菜#','3小个#\n0.5小个#','1. 番茄包菜切条型  蒜末#\n2. 热锅凉油  1.3大勺 （这个菜不费油）   蒜爆香  番茄下锅   炒一会  包菜下锅  加盐2小勺   糖3.5小勺   炒软#'),(1331,'红烧牛肉','荤菜','牛腩#\n土豆#\n牛肉口味浓汤宝#\n水#\n八角#\n料酒#\n姜片#','300克#\n200克#\n1块#\n两碗#\n1粒#\n少许#\n少许#','1. 牛肉切块并沸水，祛除血沫。土豆去皮切块#\n2. 锅中入油，加入姜片略煸，放入两碗水，水沸后加入浓汤宝#\n3. 待略煮滚后放入牛肉、料酒、八角、酱油和糖，煮滚后捞出#\n4. 将捞出的牛肉和汤料放入高压锅焖20分钟，最后加入土豆#\n5. 待收汁后即可出锅#'),(1332,'蒸蛋','荤菜','鸡蛋#\n盐适量，油适量，十三香适量，水一小碗。#','两个#\n#','1. 1.找一个合适的碗，打两个蛋，放适量盐，十三香调味，打散。#\n2. 2.加一小碗水，边加，边调，水用温水，最后加适量油#\n3. 锅里烧水，调好的蛋盖上一层保鲜膜，水涨后，把蛋放进去蒸十分钟左右。#\n4. 可以吃了。#'),(1333,'酱豆腐','素菜','大豆腐#\n东北大酱#\n葱花#\n熟豆油#\n味精#','半块#\n两勺#\n适量#\n少许#\n半勺#','1. 准备好酱加入少量水调匀。#\n2. 将豆腐切块备用。#\n3. 锅中加入适量油，油热后加入酱快速翻炒两下，加入适量水，加入豆腐。#\n4. 炖三五分钟，汤快收干时加蒜末味精出锅，撒上葱花。#'),(1334,'韩式煮年糕','主食','年糕#\n辣酱#\n生菜#\n火腿肉#','200g#\n1包#\n4片#\n1块#','1. 清水煮年糕十分钟 最后放辣酱 放生菜 放煮熟的火腿肉一大块 收汁即可#\n2. 就给你们看一看哈哈哈#\n3. 这汤汁 讲真再喝两大碗我也是妥妥的#'),(1335,'灰灰的粉丝扇贝','荤菜','蒜#\n小米辣#\n基本调味#','#\n#\n#','1. 扇贝洗净，干贝的部分抹一点蚝油#\n2. 粉丝洗净加盐调味泡发，铺在扇贝上#\n3. 热油爆香蒜末个米辣，可以加少许辣椒#\n4. 炒好的调料加在扇贝上，隔水蒸上10分钟，开吃#'),(1336,'鱼头豆腐汤','汤','胖头鱼头#\n豆腐#\n姜#\n小葱#\n盐#\n胡椒粉#','一个#\n一块#\n一小块#\n几根#\n#\n#','1. 胖头鱼头一个，豆腐一块，小葱几根，姜一小块，将胖头鱼头收拾干净，从中间切开，豆腐切块#\n2. 锅内放油，烧热，放入胖头鱼头两面煎黄；余油爆香葱段、姜片#\n3. 砂锅加水，把鱼头放入砂锅内，大火将鱼头汤煮成白色，将豆腐下锅，小火慢炖十分钟，然后加盐胡椒粉调味#'),(1337,'木耳炒鸡蛋','素菜','鸡蛋#\n木耳#\n西红柿#','三个#\n少许#\n#','1. 将鸡蛋打散，放入少许盐，加入点醋提鲜。木耳提前用水泡发变软。西红柿切小块。#\n2. 将鸡蛋炒出备用。#\n3. 油热，放入洋葱炒出香味，放入西红柿和木耳，加入盐翻炒。#\n4. 木耳炒熟时，放入炒好的鸡蛋翻炒。#\n5. 木耳炒鸡蛋出锅。#'),(1338,'杜龙黄豆汤：味甜清鲜的滋补汤','汤','猪骨#\n盐#','250g#\n适量#','1. 选鲜活的杜龙，请师傅帮忙处理好，用盐揉搓表面，冲洗干净。#\n2. 新鲜的黄豆洗净。#\n3. 猪骨洗净。#\n4. 猪骨冷水下锅，大火煮开。#\n5. 洗去浮沫，待用。#\n6. 锅中煮开水，下排骨，大火煮开，转小火煮1小时。#\n7. 转大火，下杜龙，再次煮开，转小火煮半个小时。#\n8. 再次转大火，下黄豆，再煮开，转小火煮半个小时左右。#\n9. 加盐调味，熄火即可饮用。#'),(1339,'西红柿炖牛肋排肉','荤菜','牛肉#\n西红柿#\n料酒#\n炖肉料包#\n葱姜蒜#\n生抽#\n盐和糖#\n番茄酱#','#\n#\n#\n#\n#\n#\n#\n#','1. 牛肉切大粒，放入开水煮，撇去浮沫，撇干净为止，然后捞出#\n2. 放入高压锅（如果没有，电饭煲也可以，我就是，炖了俩小时）加清水，料包，姜片，大火十分钟以后，转中火20分钟，捞出#\n3. 准备#\n4. 放入开水中，皮爆开，捞出#\n5. 切丁，然后锅内放少许油，葱姜蒜下锅爆香，倒入西红柿，翻炒，加入少量生抽，一包番茄酱，适量糖，炖好的牛肉粒，倒入炖肉剩下的肉汤【适量】然后放盐，鸡精，炖到汤浓浓的#\n6. 出锅！【可以选一个漂亮的碗】味道非常#'),(1340,'日式茶碗蒸','荤菜','鸡蛋#\n蟹肉棒#\n香菜#\n香菇#','#\n#\n#\n#','1. 香菇 蟹肉棒 香菜#\n2. 鸡蛋打散加调味料 放入容器开始蒸 半熟时加入蟹肉棒 香菇 这样材料才不会沉入碗底#\n3. 点缀上香菜#\n4. 很好吃哟#'),(1341,'清炖鸡腿','荤菜','鸡翅根 鸡腿#\n葱段 姜片 八角#','#\n适量#','1. 首先把鸡腿和翅根用凉水洗干净 然后用清水煮开后三分钟捞出再用清水洗一洗。煮鸡腿和翅根的同时把葱段和姜片八角备好。然后倒上热水把鸡腿和翅根放进去一块把备好的料放进去一块煮大火煮开后转小火煮一个小时左右。#'),(1342,'蓝莓土豆','甜品','土豆#\n蓝莓酱#\n雀巢炼乳#\n安慕希酸奶#','1个#\n20g#\n适量#\n适量#','1. 将土豆洗干净，放锅里蒸熟，千万不要切开或削皮，会影响味道的。#\n2. 土豆熟后，剥皮，放在一个保鲜袋里面，用擀面杖轧成土豆泥。#\n3. 土豆泥放入安慕希酸奶，（平时爱喝这个牌子的）和炼乳一起搅拌，根据自己的口味，调整酸奶和炼乳的比例。#\n4. 将蓝莓放入一点儿纯净水调稀，浇在土豆泥上，最后放上一片香菜叶点缀，大功告成。#'),(1346,'灰灰的红油鸡丝拌黄瓜','荤菜','基本调味#\n红油辣椒#\n葱姜#','#\n#\n#','1. 开水中煮熟鸡胸肉，葱姜去腥#\n2. 黄瓜去皮刨丝#\n3. 鸡胸肉撕成丝，放凉#\n4. 醋，味极鲜，糖，盐拌成调料，最后加入辣椒油#'),(1347,'宫保鸡丁','荤菜','鸡胸肉（鸡腿肉）#\n黄瓜#\n大葱#\n麻辣花生米#\n水淀粉#\n米醋#\n白糖#\n干红辣椒#\n姜#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 黄瓜大葱鸡肉洗净切丁，鸡肉放少许料酒、六月鲜酱油、淀粉、几片姜抓匀，腌制十分钟#\n2. 准备一些水淀粉，根据口味调入米醋、白糖#\n3. 锅内放油，烧至冒烟将鸡丁放入油中炸制变色，捞出备用#\n4. 锅内留下两汤匙左右热油，放入干红辣椒炒香，然后依次放入大葱、黄瓜丁翻炒#\n5. 下入鸡丁，翻炒匀后放入黄飞鸿麻辣花生米#\n6. 放入2中准备好的水淀粉，炒至粘稠，调入盐炒匀即可出锅。#'),(1348,'剁椒冬瓜','素菜','五花肉#\n冬瓜#\n生抽#\n盐#\n味精#\n姜#\n蒜瓣#\n杭椒#\n料酒#\n十三香#\n香菜#','100g#\n300g#\n5g#\n适量#\n少许#\n1小块#\n1颗#\n2根#\n150g#\n1g#\n5g#','1. 杭椒洗净横切小段，加盐、料酒盐半小时。#\n2. 冬瓜洗净，去皮、去子切成小长方体装盘备用。#\n3. 五花肉切片，油烧开，加入五花肉翻炒，并加入姜、蒜，十三香，（红椒是平时晾干的杭椒，基本都没有不用放的，但有的话，炸干了很香）待油脂基本干了，加入冬瓜翻炒。#\n4. 冬瓜翻炒3～5分钟，加入少许生抽，翻炒并迅速倒入料酒、盐，大火烧开小火炖干，（只有少许水时放入冰糖，也可最开始时炒糖色，在我做的排骨中有炒糖色步骤，可以参考）加入杭椒、味精或鸡精少许，翻炒1分钟。盖上盖闷一分钟，加入香菜翻炒一下装盘。#'),(1349,'青椒回锅肉','荤菜','五花肉#\n青椒#\n郫县豆瓣#\n姜#\n蒜#','#\n#\n#\n#\n#','1. 首先要将五花肉 用水煮成8成熟 水里可少放些姜片#\n2. 将煮好的的肉切片 用小火煸炒一下 将肉里的油脂煸炒出来  倒出备用#\n3. 锅内留底油用姜蒜 爆香 先将青椒放入锅中 稍炒一下后将肉放入 放入适量的郫县豆瓣 翻炒即可了#'),(1350,'清炖鲅鱼','荤菜','鲅鱼#\n茼蒿#\n大葱#\n姜#\n盐#\n肥猪肉#','一条#\n500g#\n50g#\n五片#\n适量#\n50g#','1. 鲅鱼清洗去鳃，切成三到五段，备用。茼蒿清洗改刀5公分长备用。#\n2. 锅里倒入少量花生油，放入肥猪肉煸炒，待肥油靠出来后放葱姜煸香，放入鲅鱼段稍微煎一下，倒入清水没过雨鱼身，大火烧开，改小火慢炖，大约20分钟。#\n3. 看到鱼汤发白，加入茼蒿，加少许盐调味，5分钟出锅。#\n4. 装盘，清炖鲅鱼完成了！鲜美无比，开始享用吧！#'),(1351,'炝炒小白菜','素菜','小白菜#\n植物油#\n盐#\n干辣椒#','250g#\n少量#\n#\n3只#','1. 小白菜洗净掰成一片一片的 干辣椒切小#\n2. 辣椒炒香#\n3. 辣椒炒香后加小白菜炝炒#\n4. 加少量水 加半勺盐#\n5. 起锅#'),(1352,'凉拌菠菜粉条','素菜','鸡蛋#\n老干妈#\n豉油#\n麻油#\n醋#','一颗#\n#\n#\n#\n#','1. 先烫蛋皮。我家是铁锅，所以锅底油涂的稍微多一点。蛋液尽量打散，锅7分热倒入蛋液，滚成圆圆，小火烘成蛋皮，当边边微圈的时候就慢慢揭下来。切条备用。#\n2. 菠菜，粉条分别过水烫熟。投入准备好的冷水过一下。粉条控干水。菠菜用手挤干水。和蛋皮一起拌入调料就好。#'),(1354,'京酱肉丝—东北版','荤菜','猪里脊肉#\n淀粉#\n甜面酱#\n干黄酱#\n葱#\n黄瓜#\n干豆腐#\n洋葱#','200g#\n1勺#\n1袋#\n2勺#\n1个#\n1个#\n2张#\n1个#','1. 里脊肉切丝加一勺料酒，一勺淀粉腌制一会，洋葱黄瓜切丝待用#\n2. 锅放油烧热，放入肉丝迅速炒散，然后盛出#\n3. 锅底留油，放入甜面酱和干黄酱略炒，用油爆炸过酱#\n4. 再放入肉丝炒匀即可装盘#\n5. 干豆腐切成宽点长条，放青菜丝，卷成卷#\n6. 中间位置斜着切一刀#\n7. 摆在肉酱边上，旁边再摆些葱丝，黄瓜条～完成#'),(1355,'豉香地三鲜','素菜','茄子#\n土豆#\n青红杭椒#\n豆豉#\n油#\n味精#\n销魂味椒盐#\n蒸鱼豉油#','300g#\n200g#\n少许#\n少许#\n5g#\n2g#\n5g#\n5ml#','1. 豆豉泡发，杭椒切菱形块，姜蒜切米#\n2. 茄子土豆切滚刀块，泡在清水中#\n3. 坐锅起大油，下土豆块炸至金黄#\n4. 下茄子炸至稍绵软#\n5. 坐锅起油，下姜蒜豆豉炒香#\n6. 下杭椒块，炒2分钟#\n7. 下茄子土豆，加味精、味椒盐，翻炒2分钟#\n8. 淋蒸鱼豉油，翻炒出香，起锅即可#'),(1356,'凉瓜炒蛋','素菜','凉瓜#\n鸡蛋#','一根#\n三个#','1. 凉瓜切片#\n2. 鸡蛋打散，加入盐，油，鸡粉，适量#\n3. 倒入油，把鸡蛋煎好，不要煎老了，老了不好吃#\n4. 倒入油，盐，把凉瓜炒至七分熟#\n5. 把前面煎好的鸡蛋倒入，翻炒一分钟即可。#\n6. 大功告成。#'),(1357,'酱烧茄条','素菜','茄子#\n姜末#\n盐#\n葱末#\n白砂糖#\n蒜末#\n鸡精#\n甜面酱#\n水淀粉#\n老抽#','适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 茄子用淡盐水浸泡洗净后，切成长条，泡在清水里，至少15分钟。#\n2. 泡茄子的水倒掉，把茄子一根根用干净的布吸干表面水份。#\n3. 锅里放油烧热（跟平时烧菜差不多量的油就可以了）。吸干水份的茄条分次排入锅中，煎至茄条变软。#\n4. 煎好的茄条都放盘子里备用#\n5. 用锅里剩下的一点油，爆香葱姜蒜末和甜面酱一大勺#\n6. 加点水烧开.#\n7. 放入煎好的茄条，加半汤匙老抽，再加点白砂糖，煮沸后转小火盖上盖子煮两分钟，加一点点盐和鸡精调好味。#\n8. 倒入少许调好的水淀粉，勾芡后出锅撒上葱花。#'),(1359,'高升排骨','荤菜','猪小排#','一斤半#','1. 主料：猪小排一斤半；#\n2. 热锅温油，入排骨，煸炒2~3分钟；#\n3. 肉有些泛金黄色就可以了；#\n4. 加1大勺黄酒、2大勺米醋、3大勺白糖、4大勺生抽、5大勺水，佐料刚刚及齐排骨就可以；旺火烧滚，转文火焖30分钟左右；#\n5. 看汤汁收到挂住排骨就可以了，酥烂嫩滑，一吃就知道它这名儿真不是盖的#'),(1360,'肉片家常菜','荤菜','肉片#\n青椒#\n黑木耳#\n盐#\n鸡精#\n十三香#','1个#\n2个#\n#\n#\n#\n#','1. 把葱姜蒜准备好#\n2. 青椒切好#\n3. 黑木耳准备好，要洗干净哦#\n4. 肉片切成片#\n5. 锅热把葱姜蒜倒入炸出香味，倒入青椒，黑木耳翻炒，然后把肉片倒入倒炒几下就可以#'),(1361,'咖喱鸡','荤菜','三黄鸡#\n土豆#\n胡萝卜#\n椰浆#\n味好美咖喱鸡调料#\n食盐#','半个#\n1个#\n1个#\n100ML#\n1包#\n1/4小匙#','1.  将鸡洗净切块。#\n2.  加入1/4小匙食盐稍为腌制几分钟。#\n3.  将土豆和胡萝卜切块。#\n4. 将味好美咖喱鸡调料倒入碗中，加清水400ML搅匀备用。#\n5. 热炒锅，倒入1大勺植物油，倒入鸡块煎炒2分钟。#\n6.  再倒入土豆块和胡萝卜块，继续煎炒2分钟。#\n7. 倒入拌匀的味好美咖喱鸡调味汁。#\n8. 大火烧开后转小火煮25分钟左右。#\n9. 25分钟后转大火，加入100ML椰浆，再煮至汤汁变稠即可。#'),(1363,'韭黄炒滑蛋','素菜','鸡蛋#\n红椒#\n韭黄#\n盐#\n淀粉水#\n酱油#\n料酒#','3只#\n半只#\n1把#\n#\n2-3勺#\n#\n几滴#','1. 将鸡蛋打散，添加淀粉水2-3勺，料酒几滴，搅匀备用；锅烧热后滑道油，再次注油烧热，下蛋液后用筷子快速搅拌成小蛋块（如果喜欢蛋块大一点，蛋液入锅后让其静置凝固后再搅动），鸡蛋炒至七成熟起锅；#\n2. 将韭黄、红椒洗净沥水。韭黄切段，红椒切丝备用。锅烧热后注油，大火将红椒丝煸香，下韭黄翻炒，调入适量精盐炒匀；#\n3. 下七成熟鸡蛋块入锅同炒，加入少许酱油调味，颠锅翻炒几下起锅装盘。#'),(1364,'蚝油萝卜','素菜','萝卜#\n蚝油#\n葱姜蒜#\n食用油#','#\n#\n#\n#','1. 萝卜切块#\n2. 锅热放少量食用油，油热放葱姜蒜炒出香味后放入萝卜块#\n3. 翻炒后放入较多量蚝油，并加入水，水稍微多一些#\n4. 开大火煮至沸腾后转小火慢炖收汁#\n5. 成品#'),(1365,'木子减肥珍藏：凉拌紫甘蓝','素菜','紫甘蓝#\n胡萝卜#\n盐，香醋，麻油，白芝麻#','200g#\n100g#\n适量#','1. 切细丝，很盐腌。#\n2. 腌10分钟，把汁水滤出倒掉。#\n3. 倒入香醋，麻油，撒上白芝麻（炒好的）。装盘。#'),(1366,'木耳豆腐','素菜','蚝油#\n糖#\n高汤#\n盐#','#\n#\n#\n#','1. 木耳泡发，撕成小朵备用。豆腐切片。锅中放植物油，烧热，放入豆腐片。#\n2. 豆腐片两面煎成金黄色，加入高汤，微微炖一会儿。放入木耳，加入蚝油和糖，翻炒均匀，即可。#'),(1367,'干煸豆角（重口味素食）','素菜','四季豆（或豇豆角）#\n干红辣椒#\n花椒#\n麻椒#\n姜#','#\n#\n#\n#\n#','1. 四季豆洗干净，去硬筋（用豇豆角也可以，就不用去筋了），切成4-5cm的段#\n2. 干红辣椒掰小段，姜切丝#\n3. 炒锅多放些油，烧热后把豆角放进去炸到表皮起皱，把豆角捞出来控油#\n4. 锅里的油倒出去，剩一点底油，花椒麻椒、辣椒、姜丝（花椒辣椒的用量是平时炒菜的2-3倍）一起下锅煸出香味#\n5. 刚才炸好的豆角入锅，加盐，中火翻炒至干瘪#'),(1368,'芹菜炒肉丝','荤菜','青椒#\n盐#\n料酒#\n花椒粉#\n大蒜#\n郫县豆瓣#\n油#','2-3个#\n适量#\n适量#\n适量#\n1-2辨#\n适量#\n适量#','1. 先把瘦肉丝加料酒、盐、淀粉、花椒粉腌制10-20分钟。#\n2. 把芹菜去叶洗好切成段。#\n3. 把青椒切丝，蒜拍好。#\n4. 热锅冷油，放入大蒜、豆瓣酱炒香。#\n5. 加肉丝、青椒、芹菜，大火翻炒。加盐起锅。#\n6. 装盘。完成。#'),(1369,'凉拌茄子','素菜','茄子#\n蒜#\n小红尖椒#\n盐，糖，酱油，醋，香油#\n芝麻#\n葱花/香菜#','半斤#\n半头#\n2个#\n适量#\n少许#\n少许#','1. 茄子洗干净，切段。#\n2. 上锅大火蒸半个小时，蒸熟。蒸出来的水滗掉。#\n3. 蒜和辣椒一起用研磨器磨碎，加入调料和芝麻和茄子拌均匀，放冰箱冷藏几个小时更好吃~#\n4. 吃时可以放葱花/香菜装饰下~#'),(1370,'香辣肉丝','荤菜','肥瘦猪肉#\n香菜#\n干辣椒#\n盐#\n酱油#\n糖#\n味素#\n大蒜#','500g#\n150g#\n15个#\n若干#\n少许#\n少许#\n少许#\n3瓣#','1. 肉切丝，蒜切片，香菜切段，辣椒切丝#\n2. 油热后小火煸炒蒜片，随后转大火加入肉丝炒至肉出水，加入香菜继续大火并加少许水，将酱油，糖，味素和盐依次放入，翻炒至汤汁快干时盛盘。#\n3. 小火热油后加入辣椒丝，翻炒至辣椒水份蒸发完，开始变色时，将油和辣椒丝浇入之前盛盘的肉丝上，辣椒丝一定不要变黑，否则会发苦，必要时可离火一段时间。吃的时候要夹一口香菜肉丝，沾着盘底辣椒油，搭配一条辣椒丝，东北特色的吃法。#'),(1372,'糖醋排骨','荤菜','排骨#\n姜#\n花椒#','一份#\n少量#\n少量#','1. 精排骨一份#\n2. 花椒、姜少许#\n3. 用开水过一下排骨，备用#\n4. 1：锅里到上油，下排骨，炒至微黄放酱油2：加一碗水淹过排骨3：水开以后放糖、放盐4：水分快干的时候放醋收汁5：起锅#\n5. 啦啦，做好啦#\n6. 很香，很入味#\n7. 糖醋排骨#\n8. 要吃芝麻的可以加上芝麻哦#'),(1373,'鲜蘑土豆片','素菜','鲜蘑#\n土豆#\n植物油#\n生抽#\n耗油#\n盐#\n葱花切段#\n蒜切片#','一大把#\n一大个#\n10ml#\n10ml#\n3ml#\n5g#\n适量#\n适量#','1. 土豆洗净切薄片，清水泡出淀粉；鲜蘑洗净撕成小扇#\n2. 鲜蘑用水焯八分熟，捞出备用#\n3. 热锅下油，爆香葱蒜，下十三香，生抽#\n4. 入土豆片翻炒，不要让土豆片粘锅，炒到八分熟下鲜蘑，放少量清水#\n5. 翻炒两分钟，下盐，可以出锅了，撒上点葱花点缀，收工#'),(1374,'乡村鲫鱼','荤菜','水库鲫鱼#\n花椒#\n酸菜#\n泡老姜#\n泡辣椒#\n小葱#\n美人椒#\n大蒜#\n老姜#\n豆瓣#\n胡椒面#\n泡辣椒酱#','10个#\n适量#\n适量#\n适量#\n适量#\n200g#\n200g#\n#\n#\n#\n#\n#','1. 把鲫鱼杀死刮干净鱼鳞抠去内脏洗净麻上盐、葱头、老姜、料酒腌制10分钟入味，酸菜、泡老姜、泡椒切好。#\n2. 锅内放菜油等菜油泡沫化了后放入一漂猪油，猪油化了后，放入一小把花椒，有花椒香味飘出后放入切好的泡菜、泡老姜、泡椒翻炒一会再放入豆瓣一汤匙，翻炒一会至豆瓣炒熟，加入新鲜的大蒜、老姜，和自制辣椒酱，翻炒一分钟左右加入水。#\n3. 自制泡辣椒酱：泡辣椒用料理机打烂加捣烂的大蒜用菜油炒一下就好了，很香#\n4. 水涨后放入鱼，加入酱油，少许胡椒面煮8分钟左右鱼就好了最后把小葱放进去就可以起锅了。#'),(1375,'速冻饺子版锅贴','主食','速冻饺子#\n葱花#\n食用油#\n面粉#','少许#\n少许#\n少许#\n少许#','1. 准备好饺子#\n2. 将1汤匙面粉调成略稠的面粉水，注意不是浓稠的面粉浆；#\n3. 取平底不沾锅，倒少许食用油，约1汤匙，温热，码入饺子#\n4. 将面粉水均匀倒入不沾锅中，并左右转动，使其均匀包在饺子上，面粉水约漫过饺子三分之一即可；#\n5. 约6、7分钟后，可开盖看看，若饺子皮呈透明并鼓起状，表示熟透；若饺子熟透而水未干，就起大火收干水，同时撒入葱花，稍待片刻即可；#\n6. 起锅开吃，底酥而不焦，葱花香气扑鼻，狠好吃也。(有白芝麻的话撒点更香更好吃了)#'),(1376,'节瓜鱼丸汤','汤','大节瓜#\n鱼肉#\n红枣、生姜#\n盐、油、白糖、蚝油、生抽、淀粉#','1个#\n1斤#\n适量#\n适量#','1. 节瓜削皮，切成大块状一边备用。。#\n2. 鱼肉冼净用搅拌机，打成鱼肉泥，加油、盐、白糖、蚝油、生抽、淀粉搅拌均匀，用筷子顺时针搅拌10分钟，这样出来的鱼肉会有弹性、不粘手，接受用手搓成丸子状，放一边备用。。#\n3. 油锅下姜片，把节瓜倒下去翻炒一下。。备半锅开水#\n4. 把节瓜放到开水锅里，放红枣下去，先大火煮沸腾，小火煮半小时，再放鱼丸下去煮15分钟，试一下节瓜的软硬程度，再试一下汤水的味道，不够咸再加盐。。#\n5. 上一张节瓜鱼丸汤的图片#'),(1377,'懒人必备----咖喱土豆','素菜','土豆#\n胡萝卜#\n咖喱粉#','一个#\n一个小的#\n适量#','1. 将土豆胡萝卜都削皮切成小粒粒#\n2. 油热，放入花椒，炒香后捞起，放入姜末蒜末和土豆胡萝卜，一起炒，再放入老抽和咖喱粉适量。略炒，加入一点水，有汤更好。烧到土豆和胡萝卜都软了即可。水刚开始不要加太多，保持最后起锅不要有太多余的水。最后记得放盐和味精。#'),(1378,'香辣肥牛金针菇','荤菜','肥牛#\n金针菇#\n郫县豆瓣酱#\n剁椒#\n蒜末#\n花椒#\n盐#','300g#\n300g#\n1勺#\n1勺#\n1勺#\n1小把#\n少许#','1. 材料#\n2. 放油#\n3. 放蒜花椒#\n4. 加辣酱#\n5. 加金针菇，然后加水等开#\n6. 水开加肥牛#\n7. 变色即熟#'),(1379,'煎大明虾','荤菜','大明虾#\n黄油#\n盐#\n黑胡椒#','数量根据自己定#\n40g#\n适量#\n适量#','1. 大明虾洗净，背部划开，取出砂筋#\n2. 平底锅烧热后，放入黄油，待黄油融化起泡就放入大明虾#\n3. 放的时候注意，不是一下子倒入，要一个个放，平铺… 煎至虾的两面都变红，就差不多了… 大概需要10-12分钟，煎的时候，一面变红了，要用筷子一个个翻过来煎另外一面#\n4. 两面都变色后，撒入盐和黑胡椒#\n5. 最后装盘，可根据自己口味，吃之前撒一点研磨的黑胡椒和海盐～ ^?_?^#'),(1380,'#夏日素食#简单三部曲腌黄瓜','素菜','黄瓜#\n苹果醋#\n枸杞#','自定#\n适量#\n装饰#','1. 黄瓜洗干净 切段 放密封盒里 苹果醋备用#\n2. 苹果醋倒进去 没过黄瓜就可以 盖上盖子腌制一个晚上#\n3. 第二天 可以吃啦 简单吧 很美味哦 醋也可以喝 味道不错 没吃完 记得冷藏哦！#'),(1381,'酸菜肉丝','荤菜','肉丝#\n酸菜#\n黄豆#\n大蒜#\n生粉#\n生抽#','一小碗#\n一小碗#\n两把#\n几瓣#\n一勺#\n少量#','1. 肉丝中加入生粉，盐，生抽拌匀#\n2. 腌制的酸菜加入泡好的黄豆稍微炒一下，加入水闷熟，因为家里做的腌菜比较干，所以煮的时间比较才。将水煮干后入盘备用。#\n3. 油锅中放入大蒜豆豉炸香，倒入肉丝炒熟，不宜太久，再将酸菜和黄豆倒入锅中，微炒，可再加水闷一小会儿，看自己喜好。#'),(1382,'西红柿炒蛋','素菜','西红柿#\n鸡蛋#\n葱#\n油#\n盐#\n白糖#','3个#\n2个#\n1根#\n6勺#\n1/2勺#\n2勺#','1. 西红柿洗干净去蒂，切成小块备用。#\n2. 葱的葱白和葱叶分开切。#\n3. 鸡蛋打散成蛋液，放入葱花。加一小点水，这样子炒出来的鸡蛋比较嫩。#\n4. 锅中放入一半的油，烧至六成熟后，将蛋液缓缓倒入，在锅中快速搅打炒成蓬松的炒鸡蛋，盛出备用。#\n5. 锅中放入剩下的一半油，烧至五成熟，放入葱白爆香。#\n6. 放入西红柿块，大火翻炒，炒至西红柿稍软烂，放入盐、白糖调味。#\n7. 最后放入鸡蛋，炒均匀，盛出，西红柿炒鸡蛋就完成啦！#'),(1383,'白灼海螺','荤菜','海螺#\n葱#\n姜#\n青红椒#\n白胡椒粉#\n料酒#\n生抽#\n香油#\n醋#','10个#\n#\n#\n#\n#\n#\n#\n#\n#','1. 半锅水加姜片、葱段、料酒烧开，放进海螺烫煮４－５分钟，捞起后马上泡进冰水五分钟#\n2. 用小叉剔出肉，去除中段的黄、绿色肠肚#\n3. 肉切片摆盘，尾部回锅再烫３－４分钟后捞起摆盘#\n4. 撒上葱丝、嫩姜丝、青红椒丝，淋上生抽一大匙，白胡椒粉少许，泼上两大匙滚油即可火侯掌握恰当，螺肉柔软爽脆，味道清甜滋美！#'),(1385,'白胡椒虾','荤菜','对虾#\n生姜#\n料酒#\n盐#\n白胡椒粉#\n葱#','#\n#\n#\n#\n#\n#','1. 把虾处理一下，剪去虾枪虾须和虾头；#\n2. 在虾背上用剪刀剪开，#\n3. 拉出虾肠；#\n4. 热锅冷油，加入生姜丝#\n5. 炒出香味；#\n6. 加入虾翻炒；#\n7. 放入少许料酒；#\n8. 加入盐和白胡椒粉翻炒入味；#\n9. 加入葱翻炒即可出锅；#\n10. 洗干净生菜，放在盘底，虾放上面即可#'),(1386,'葱爆羊肉','荤菜','羊肉#\n大葱#\n辣椒#','300g#\n两根#\n几根#','1. 全部原料，羊肉可以用料酒生抽腌制一下。#\n2. 羊肉下锅炒至变色。#\n3. 羊肉盛出来，特别香嫩。#\n4. 留底油炒大葱辣椒，再把刚才的羊肉放进去。#\n5. 好啦#\n6. 香滑～#'),(1387,'香椿恋黄豆','素菜','香椿#\n黄豆#\n盐#\n鸡精粉#\n香油#','适量#\n100g#\n适量#\n适量#\n少许#','1. 黄豆提前泡几小时以后  把泡好的黄豆用开水煮熟备用#\n2. 把洗净的香椿用开水汆烫几秒钟捞出。#\n3. 把烫好的香椿切末和煮熟的黄豆混合，里面撒少许盐，在香椿恋黄豆里再放入少许鸡粉滴几滴香油拌匀，然后装盘便可食用。#'),(1388,'老醋花生米','素菜','花生米#\n盐#\n白糖#\n醋#\n香菜#','#\n#\n#\n#\n#','1. 花生米用水冲洗干净，用厨纸把表面水份擦干。锅里放油，冷油时就倒入花生米快速翻炒，以保证花生米能够均匀受热。待花生米颜色微变，这时香味也出来了，立即将花生米捞出控油。#\n2. 醋，白糖，和少许盐调成味汁，香菜切末。#\n3. 调好的汁倒入放冷的花生米里拌匀，撒香菜末即可。#'),(1389,'微波龙利鱼','荤菜','龙利鱼鱼肉#\n生抽#\nTabasco#','一块#\n少许#\n少许#','1. 太懒了不想出门，家里只有龙利鱼了。龙利鱼微波炉高火加热15分钟，倒掉盘里的汁水，淋点生抽再微波5分钟，然后再滴些Tabasco就可以吃了。^_^简单也是一种美味。#'),(1390,'花菜炒肉片','荤菜','盐#\n食用油#\n生抽#\n醋#\n姜#\n鸡精#\n红尖椒#','适量#\n适量#\n适量#\n适量#\n适量#\n#\n#','1. 花菜放盐水里先泡半小时 怕里面有小虫子#\n2. 切成小块用开水过一遍 盛起来冲下凉水备用#\n3. 锅里食用油烧开 放入姜丝红椒和肉片翻炒一下#\n4. 接着放入花菜一起炒 然后放盐生抽和醋 加入一点点水焖一小会#\n5. 最后要盛盘的时候加入鸡精 大功告成啦 我和老公吃了就剩盘子了#'),(1391,'爆炒猪肚','荤菜','猪肚#\n青红椒#\n生菜<可不加>#\n生抽老抽蚝油#\n鸡精<可不加>#\n姜蒜#','适量#\n各半个#\n几片#\n适量#\n适量#\n一些#','1. 准备材料，切姜蒜，青红椒#\n2. 猪肚洗干净，尽量煮烂，捞出来切段<一定要薄>#\n3. 热锅烧油，加姜蒜，加猪肚，生抽老抽蚝油翻炒#\n4. 加青红椒翻炒<建议猪肚能嚼的动以后再加>#\n5. 加水煮，收汁，再加水，一直到嚼的动为止<我加了五次水因为猪肚切的太厚了>#\n6. 猪肚煮烂之后加生菜翻炒，收汁盛出，超级下饭<但是青椒好像炒没了>#'),(1392,'鱼香肉丝','荤菜','牛肉#\n土豆#\n胡萝卜#\n黑木耳#\n醋#\n生抽#\n酱油#\n白糖#\n葱姜蒜#\n黑胡椒#\n盐#\n花生油#\n淀粉#\n青椒#','100g#\n1个#\n1个#\n1把#\n2汤匙#\n1汤匙#\n1汤匙#\n1汤匙#\n适量#\n少许#\n少许#\n适量#\n适量#\n半个#','1. 土豆切丝，泡水里洗净淀粉，胡萝卜切丝，木耳切丝#\n2. 葱姜蒜切末#\n3. 青椒切丝#\n4. 牛肉切丝，放碗里，加少许盐，黑胡椒，淀粉，姜末，花生油抓匀腌制十分钟#\n5. 腌制的过程中可以调鱼香汁，白糖，醋，生抽，酱油，水淀粉，调匀即可#\n6. 热锅温油，下入牛肉丝，迅速划散，炒到发白盛出备用，锅内留底油，爆香葱姜蒜，下入胡萝卜土豆木耳丝加盐，翻炒均匀，倒入鱼香汁，大火翻炒收汁，出锅前放入青椒丝即可#'),(1393,'洋葱爱鸡蛋','素菜','洋葱#\n鸡蛋#\n食用盐#\n酱油#\n醋#\n干辣椒#\n青椒#\n葱#\n孜然粉(有最好，没有也不碍)#','#\n#\n#\n#\n#\n#\n#\n#\n#','1. 洋葱洗净，切入盘。#\n2. 葱姜，干辣椒，青椒切好备用。#\n3. 鸡蛋打入碗中，搅拌均匀。(此时不用添加食用盐)#\n4. 先煎鸡蛋，煎好后先盛入打鸡蛋碗中。#\n5. 倒油，油热后放葱姜，干辣椒，青椒炝锅。#\n6. 倒入洋葱翻炒。翻炒过程中加酱油，醋少许。#\n7. 加入鸡蛋一同翻炒，此时加适量盐，再加青椒一同翻炒。最后装盘。#'),(1394,'豆豉蒜香排骨','荤菜','肋排#\n卷心菜#\n豆豉#\n蒜头#\n姜#\n料酒#\n生抽#\n白糖#\n淀粉#\n六月鲜或蒸鱼露#','400g#\n几页#\n少许#\n半个#\n两片#\n一勺#\n一勺#\n一小勺#\n少许#\n少许#','1. 肋排洗净，加生抽、黄酒、姜 、白糖腌制30分钟以上#\n2. 倒掉多余的水份，放淀粉拌匀。#\n3. 切好卷心菜，蒜末，豆豉也略切两刀，备用。#\n4. 同上#\n5. 起油锅，把放好淀粉的排骨，炒成金黄色。#\n6. 卷心菜垫底，再铺上排骨，蒜末，豆豉，蒸锅上气后蒸30分钟。#\n7. 蒸好的排骨，可以加些蒸鱼路或六月鲜调味，大功告成啦。#'),(1395,'番茄炒甘蓝','素菜','甘蓝#\n番茄#','一半#\n大的一个#','1. 甘蓝拔好#\n2. 洗净切丝#\n3. 番茄切块#\n4. 蒜切片#\n5. 蒜爆香#\n6. 炒番茄#\n7. 放入甘蓝，撒入生抽#\n8. 盖盖焖5分钟#\n9. 出盘#'),(1396,'韩式凉拌墨鱼仔','荤菜','墨鱼仔#\n韩式辣酱#\n白糖#\n酱油#\n辣椒粉#\n醋#\n姜#\n蒜#\n白芝麻#\n冰柠檬水#\n料酒#\n姜#','500克#\n4汤匙#\n2汤匙#\n2汤匙#\n2汤匙#\n1汤匙#\n20克#\n20克#\n2汤匙#\n适量#\n1汤匙#\n2片#','1. 墨鱼仔剥去外皮，去除背部小硬壳（海螵蛸），掏清内脏，切掉眼睛，冲洗干净备用。把芝麻炒香备用。　　#\n2. 锅里下水烧开，放入姜片、料酒和墨鱼仔煮滚后，关火焖3分钟。#\n3. 捞起墨鱼仔，立刻放入冰柠檬水里浸泡5分钟。蒜、姜切成碎粒，然后将韩式辣酱、辣椒粉、酱油、白糖、醋、蒜、姜、熟芝麻调配好。#\n4. 墨鱼仔沥干水份放入碗中，将调好的调料倒入碗中，搅拌均匀。盖上盖子放入冰箱冷藏1-2小时后即可开吃，时间越长风味更佳。#'),(1397,'翡翠肉末卷','荤菜','白菜#\n肉末#\n调料#','#\n#\n#','1. 白菜叶放锅中，加点盐 油 煮到软，捞出 沥水。#\n2. 肉末拌入盐 生抽 老抽 糖 料酒 ，腌一会#\n3. 肉末卷入白菜叶中#\n4. 香菜叶烫软 包住包菜叶 ，上蒸锅，冒气后继续5分钟，拿出后把汁叶倒出#\n5. 爆香葱姜#\n6. 炒香红辣椒 胡萝卜丁，加入蚝油 水淀粉 调汁。#\n7. 淋在翡翠包上，高大上吧，嘻嘻。#'),(1398,'泡椒凤爪','荤菜','白醋#\n少量凉白开#','#\n#','1. 凤爪洗净煎去指甲尖分切成小块，放入加了姜片和少许醋的沸水锅里煮至用筷子能一下扎透的程度．#\n2. 煮好后捞出迅速用清水反复冲洗干净后，再泡在冰水里．　　（这一步我反复往水里加了两次冰块到水里，我总觉得冰镇得越久鸡爪越白越Ｑ）#\n3. 取一个能密封的干净容器，放入凉透的鸡爪，倒入泡椒，和泡椒水盖好盖，隔冰箱里冷藏过夜就可以吃了．（泡的时候，你可以先尝尝泡椒的咸味，如果不是太咸，最好直接用它的水量没过鸡爪～我这次买的泡椒特别咸，所以加了些凉白开和醋．）#'),(1399,'山西过油肉','荤菜','里脊肉#\n鸡蛋#\n木耳#\n红椒#\n洋葱#\n盐#\n老抽#\n老陈醋#','350g#\n1个#\n5个#\n1个#\n半个#\n适量#\n适量#\n1ml#','1. 黑木耳泡发，五个小时以上最好，舒展饱满。洗净撕小朵，红椒去蒂洗净撕小朵。#\n2. 里脊肉切片，加一个鸡蛋，两大勺淀粉，少许盐，搅拌均匀。炒锅放稍多的油，八成热时放肉片，稍炸成金黄色盛出沥油。#\n3. 炒锅倒稍少油，八成热时放洋葱，翻炒两分钟放木耳和红椒，继续翻炒三分钟放肉片，加适量盐、胡椒粉、老抽、适量温水，翻炒五分钟临起锅时，倒老陈醋。0k#'),(1400,'香辣藕丁','素菜','藕#\n青菜#\n红辣椒#\n葱#\n姜#\n蒜#\n花椒#\n食用油#\n盐#\n味极鲜#','一节#\n四五棵#\n2个#\n少许#\n少许#\n少许#\n四五粒#\n少许#\n#\n#','1. 热锅，食用油加热到八成#\n2. 放入花椒，炸后捞出，继续放入葱姜蒜爆香#\n3. 倒入藕丁，翻炒，同时加入盐，味极鲜#\n4. 放入青菜，翻炒二三分钟即可#'),(1402,'凉拌海带丝','素菜','海带丝#\n大蒜#\n姜丝#\n红辣椒#\n香菜#\n盐#\n醋#\n花椒油#\n芝麻油#\n白砂糖#\n酱油#','200g#\n4块#\n25g#\n4个#\n1颗#\n适量，按自己口味加#\n#\n#\n#\n#\n#','1. 超市买的海带丝开水煮3分钟左右，捞出来放入凉水中泡着，\'\'（凉水中放入一勺盐）待用#\n2. 把辣椒，大蒜，姜切沫。#\n3. 把所有配料倒入已经凉透的海带中拌匀（加入白砂糖，海带丝比较脆）#\n4. 加入香菜，（不喜欢吃的不加）搅拌均匀，装盘即可。#\n5. 放入冰箱隔天更好吃#'),(1403,'土豆烧豆角','素菜','中等土豆#\n豆角#\n老抽#\n生抽#\n葱姜蒜末#\n冰糖#\n盐#','2个#\n1把#\n#\n#\n#\n#\n#','1.  为了少油，土豆切条后加了适量盐抓拌，入微波炉高火3分钟打熟。#\n2. 先将冰糖、生抽、老抽、耗油和少量水制成汁，提前兑好免得冰糖不能化。#\n3. 豆角洗净掰成寸段，锅烧热，放油中火将豆角煎熟，并放一点点盐#\n4. 豆角熟了再将打好的土豆条入锅，最后倒入调好的汁，大火翻炒收汁出锅。#'),(1404,'肉丝拌菜','荤菜','肉丝#\n苦菊紫甘篮生菜红柿子椒#\n盐糖香油麻油芥末油葱祘#','200g#\n适量#\n少许#','1. 肉切丝备用上浆调味十白胡椒盐料酒备用。#\n2. 锅放煸炒肉丝下祘葱爆香放生抽面酱糖香油即可#\n3. 所有菜切丝#\n4. 调味麻油芥末油香油糖与肉丝调合即可。#\n5. 肉丝拌菜#'),(1405,'香辣水煮鱼','荤菜','鱼柳#\n豆豉酱#\n花椒粒#\n干碎辣椒#\n豆芽#','#\n#\n#\n#\n#','1. 买回来的鱼柳用水泡半小时（期间要换几次水）#\n2. 豆芽去掉牙尾。#\n3. 清洗干净的鱼柳用厨纸吸干水份。然后斜刀切片。#\n4. 切好的鱼柳用：盐，酒，生粉，鸡精腌制。#\n5. 炒锅放油烧热，放豆豉酱，花椒粒，干碎辣椒爆香，之后放水烧开。#\n6. 放处理好的豆芽烫熟，捞起来放入碗里。#\n7. 将腌好的鱼片放入香辣汤里煮熟。之后捞起放入有豆芽的大碗里。#\n8. 最后锅里放两勺油烧热，淋上做好的水煮鱼上即可。#'),(1406,'四季豆烧土豆','素菜','四季豆#\n土豆#\n西红柿#\n大葱#\n大蒜#\n青椒#','250g#\n1个#\n1个#\n适量#\n适量#\n2个#','1. 1、油烧热，放入葱花、蒜末，洗净、去头、去尾、去筋手掐好的四季豆的条，和去皮切成条的土豆。2、放入糖、盐、酱油炒。3、烧香后小半碗水加盖焖煮约15分钟！4、看到四季豆和土豆熟了，加入西红柿收汁，快干时放入切好的青椒！装盘好了！#'),(1407,'大盘鸡拌面','主食','鸡腿块（或鸡块）#\n土豆#\n洋葱#\n绿辣子#\n葱#\n姜#\n蒜#\n红辣角#\n花椒#\n八角#\n盐#\n酱油#\n糖#','四个鸡腿#\n一个小的#\n一个小的#\n2个#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 将鸡块在热水中绰掉血水，沥干捞出#\n2. 热锅凉油放入花椒，来回搅拌花椒，入味，待油热冒烟时，关火，捞出花椒。#\n3. 油热后倒入鸡块，翻炒，随后放入红辣角，葱姜继续翻炒。#\n4. 加入热水，莫过鸡块就可以了，放入八角，酱油，糖#\n5. 鸡块小火炖25分钟，依次放入土豆，洋葱，绿辣子（土豆块熟的时候再放入洋葱和绿辣子）#\n6. 放入盐调味#\n7. 面煮好捞出#\n8. 把做好的鸡块浇在面条上，这样香喷喷的大盘鸡拌面就#'),(1408,'凉拌双色木耳','素菜','枸杞#\n生抽#\n姜汁#\n糖#\n醋#\n香油#','几粒#\n#\n#\n#\n#\n#','1. 黑白木耳泡发 摘洗干净 用开水焯一下 沥水#\n2. 放入容器内 倒入一勺生抽、两勺糖、三勺醋、少许盐、一点姜汁、几滴香油拌匀，最后洒上枸杞即可#'),(1409,'芋艿蒸小排','荤菜','芋艿#\n肋排#\n彩椒#\n香葱#\n盐#\n有机豉油#\n豆豉#','#\n#\n#\n#\n适量#\n适量#\n适量#','1. 芋艿用水煮熟，剥去外皮，放入碗内。#\n2. 排骨事先用盐和豉油，豆豉腌20分钟。摆在芋艿上。入锅蒸20分钟。#\n3. 出锅洒葱花和彩椒即可#'),(1410,'尖椒炒鸡蛋','素菜','木耳#\n葱#\n盐#\n味精#','适量#\n少许#\n两勺#\n适量#','1. 打好3个鸡蛋。#\n2. 打散。#\n3. 尖椒切成丁。#\n4. 尖椒倒入搅好的鸡蛋中，撒一勺盐，搅匀。#\n5. 锅中入油，烧热倒入蛋液。注意转小火哦。#\n6. 放入木耳，翻炒片刻。撒一勺盐，适量的味精。翻炒均匀。#\n7. 最后装盘出锅。#'),(1411,'蒸鸡蛋甜味','甜品','鸡蛋#\n炼乳#\n白糖#','2个#\n1勺#\n2勺#','1. 一个碗打蛋液，用另一个碗加糖加炼乳用热水兑开。待热水晾成温水，就可以倒入鸡蛋液中一起打。我没有筛子，所以省略了过筛这步，蒸出来也没有蜂窝 。重要的是用汤匙把打好的鸡蛋水上面的泡沫舀掉，这样蒸后鸡蛋表面很平滑#\n2. 锅里把水烧开，鸡蛋盖上保鲜膜上锅中火蒸15分钟，熄火后再焖几分钟#\n3. 喜欢更甜的，还可以浇上炼乳或蜂蜜。趁热吃或入冷藏后食用都不错#'),(1413,'啤酒鸡蛋','荤菜','啤酒#\n糖#\n盐#\n酱油#\n老抽#','330ml(一瓶)#\n25克#\n10克#\n5克#\n10克#','1. 首先把鸡蛋煮熟，再剥壳。#\n2. 剥壳后用刀子划几道口子，再把啤酒，糖，盐，酱油，老抽一起倒入煮干即可。#\n3. 做法简单，比乡巴佬好吃。哈哈#\n4. 比乡巴佬好吃，新鲜干净。#\n5. 啦啦啦～#'),(1414,'咸鸡蒸鲫鱼#寻找最聪明的蒸菜达人#','荤菜','鲫鱼#\n咸草鸡#\n色拉油#\n盐#\n料酒#\n葱花#\n姜片适量#\n薄盐生抽#\n红辣椒#','1条#\n1/4只#\n1勺#\n1小勺#\n1勺#\n适量#\n4片#\n1勺#\n1个#','1. 买回的鲫鱼#\n2. 刮了鱼鳞后，直接切断，背脊不要切断，把内脏挖出洗净#\n3. 加点盐#\n4. 加料酒腌制一会#\n5. 把鱼取出放到盘上，底下垫点姜片#\n6. 把蒸过的草鸡放在中间#\n7. 上蒸笼蒸8分钟#\n8. 加点葱花、红辣椒和薄盐生抽#\n9. 烧热适量色拉油#\n10. 把油淋到葱花上即可#'),(1415,'凉拌金针菇','素菜','金针菇，黄瓜，洋葱，青椒#\n盐，香油，醋，酱油#','#\n#','1. 金针菇摘好后浸泡#\n2. 将黄瓜，洋葱，青椒切丝（吼吼，切的有些粗了，见笑见笑）#\n3. 将金针菇下锅过水，开锅后一两分钟在出锅#\n4. 准备好凉水，将金针放入凉水中#\n5. 将金针去水，放入盆中，放入盐，香油，醋，生抽（也可以放点蚝油）#\n6. 盛盘～开吃咯～～#'),(1416,'五彩煎肉饼--格兰仕“百变金刚”立式电烤箱试用菜谱','荤菜','肉滑#\n鸡蛋#\n彩椒#\n车达奶酪#\n红薯淀粉#\n综合香料#\n黑胡椒粉#\n盐#\n油#','325克#\n1个#\n少许#\n20克#\n1汤匙#\n1茶匙#\n1茶匙#\n#\n#','1. 先准备好材料；#\n2. 不知是因为台风灾的原因还是别的，肉末早卖完了，只好买了玉米胡萝卜的肉滑；#\n3. 彩椒切碎；#\n4. 肉滑中打入鸡蛋，加入奶酪、淀粉、彩椒末、香料、黑椒粉和盐；#\n5.  顺一个方向搅拌上劲；#\n6. 烤盘里刷一层油，用格兰仕立式烤箱的顶部BBQ，预热烤箱210度，放入做成的肉饼；#\n7.  煎至两面金黄即可，约20分钟。#'),(1417,'猪肝青菜汤`','汤','猪肝#\n小青菜#\n淀粉#\n鸡精#\n料酒#\n姜粒#\n盐#\n猪油#\n葱段#','适量#\n适量#\n#\n#\n#\n#\n#\n#\n#','1. 小青菜，猪肝洗干净。切点葱段，姜粒！#\n2. 猪肝切成片，放入小碗中！#\n3. 少量料酒去腥，一小勺淀粉搅拌均匀。让猪肝嫩一些，淀粉一定不要太多了！#\n4. 锅中烧点热水，把猪肝放入稍微烫一下。烫一下就要盛出。不然会老#\n5. 锅中换水。大半汤碗水！水烧开，一勺半盐，一勺鸡精。把猪肝放入！#\n6. 猪肝稍微煮一会。把青菜放入烫熟。汤中的泡泡用汤勺去除！#\n7. 汤碗中一勺猪油，少许葱段！把烧好的猪肝汤盛入。汤勺搅拌下即可！#\n8. 猪肝汤配菠菜感觉更好吃！小青菜也鲜……#'),(1418,'麻辣豆腐','素菜','肥瘦猪肉#\n豆腐#\n老干妈#\n盐#\n葱花#','1块#\n一块#\n一勺#\n2g#\n适量#','1. 切片#\n2. 切块#\n3. 豆腐煮一下 炒的时候不容易碎#\n4. 热油锅炒肉片.#\n5. 放辣椒...因为我能吃太辣.所以放的少#\n6. 放豆腐...葱花...盐#'),(1419,'茭白炒肉','荤菜','茭白#\n青椒#\n肉丝#\n盐#\n酱油#\n糖#\n姜#\n蒜#\n辣椒#','2根#\n2个#\n1两#\n大半勺#\n1勺#\n半勺#\n#\n#\n#','1. 原料备好，肉提前加酱油稍腌制5分钟。#\n2. 锅中倒少量油，七成熟加肉煸香。#\n3. 倒入菜炒熟来张掂勺的。#\n4. 出锅前加糖、盐、酱油。#'),(1420,'野山椒煸兔丁','荤菜','兔肉#\n泡野山椒#\n青线椒#\n盐#\n干花椒#\n干辣椒#\n姜片#\n大葱白#\n鸡粉#\n料酒#\n蛋清#\n淀粉#\n酱油#\n泡椒水#\n香油#','250克#\n100克#\n8根#\n3克#\n10克#\n50克#\n5片#\n1根#\n3克#\n15克#\n1/2个#\n10克#\n5克#\n20克#\n15克#','1. 准备材料。干辣椒切成小段，去籽。 青线椒切成2cm的段，大葱切1.5cm长的段。#\n2. 兔肉用清水漂洗至没有血水，剁成2cm大小的块，用盐、料酒、酱油、鸡蛋清、淀粉拌匀腌制20分钟入味。#\n3. 炒锅里加入比平时炒菜多1倍的油，中火烧至五成热，将兔肉入锅里滑炒至散，控去多余的油。#\n4. 倒入泡野山椒，中小火煸炒至香味四溢#\n5. 放入姜片、大葱段、干辣椒段、花椒继续煸炒。#\n6. 调入盐、鸡粉、料酒、泡椒水、香油。稍微收汁后，放入线椒段炒熟即可。#'),(1421,'京酱肉丝','荤菜','猪瘦肉#\n葱白#\n蛋清#\n甜面酱#\n盐#\n味精#\n料酒#\n白糖#\n葱末#\n湿淀粉#\n花生油#','250克#\n200克#\n一个#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 将猪瘦肉洗净，切成均匀细丝。#\n2. 加入料酒、盐、湿淀粉、蛋清抓匀上浆。#\n3. 将葱白切成丝，码放盘子中。#\n4. 炒锅注油烧至五成热，下肉丝炒至变色，盛出待用。#\n5. 炒锅注少许油，下葱末爆香，放入甜面酱略炒，加入少许清水、料酒、白糖、味精不停炒动，待变色出香味，倒入肉丝翻炒均匀。#\n6. 出锅盛在葱丝上面，食时拌匀即成。#'),(1422,'可乐鸡翅','荤菜','鸡翅#\n可乐#\n五香粉#\n盐.味精.生抽.料酒（没有料酒米酒也行）.油，蜂蜜#\n葱头#','250g#\n盖过鸡翅即可#\n少许#\n少许#\n少量#','1. 首先先将鸡翅洗好，用刀切几刀，这样好入味#\n2. 接着将洗好的鸡翅，用盐，味精，料酒，淀粉，油，蜂蜜腌10分钟#\n3. 将腌好的鸡翅，用小火煎至两面金黄（注意翻动，要不就糊了）#\n4. 煎好后，倒入可乐，大火煮10～15分钟，小火勾汁，出锅#'),(1423,'剁椒土豆片','素菜','葱#\n姜#','#\n#','1. 土豆切片、葱姜切丝#\n2. 油锅放葱姜和剁椒炒香#\n3. 再放土豆片炒熟#\n4. 出锅装盘#'),(1425,'鱼香肉丝','荤菜','里脊肉#\n笋#\n木耳#\n胡萝卜#','1条#\n半只#\n若干#\n若干#','1. 笋丝，胡萝卜丝，木耳丝略炒一下盛出备用，顺纹理将里脊肉切成细肉丝，淀粉用水调开后放入肉丝加少许盐略腌，生抽，醋，糖，少许老抽，料酒调成汁。热锅冷油放肉丝炒到断生后放一勺搅碎的郫县豆瓣酱泥炒出红油，倒入调好的酱汁炒均匀，放入素三丝略炒，放盐味精，炒匀。#'),(1426,'萝卜排骨汤','汤','猪排骨（小排或筒骨）#\n白萝卜#\n生姜#\n小葱#\n盐#\n料酒#','500g#\n一根#\n2片#\n2根#\n少量#\n少量#','1. 排骨切好 放入冷水煮开 待煮片刻后取出洗去血沫#\n2. 白萝卜刨皮滚刀块～#\n3. 一锅冷水放入姜片 葱段 倒入2瓶盖的料酒#\n4. 煮开后下入排骨萝卜～#\n5. 煮一个小时关火焖半个小时再开火煮10分钟即可～#\n6. 冬天的萝卜赛人参呢～是大补哦～冷冷的冬天来一碗热乎乎的汤～#'),(1427,'#梅太厨房#越南汤河粉','荤菜','河粉#\n绿豆芽#\n罗勒叶#\n薄荷叶#\n牛里脊片#\n小米辣#\n鱼露#\n洋葱#\n香菜根#\n丁香#\n香叶#\n草果#\n八角#\n柠檬汁#\n柠檬叶#\n大蒜#\n南姜#\n香茅#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 干锅培香桂皮、八角、草果、丁香、香叶、南姜后与新鲜柠檬叶、香菜根一起装入布袋扎紧#\n2. 牛尾骨冷水浸泡半小时再飞水，与香料包、整颗洋葱、带皮大蒜整颗、香茅、香菜根一起冷水下锅，熬制8小时，汤底制做完毕。#\n3. 沸水快速烫熟河粉、绿豆芽，铺上薄片生牛肉浇入滚烫牛骨清汤，加鱼露、撒上新鲜罗勒、薄荷叶、花生蒜碎，即可。#\n4. 佐餐辣椒：小米辣剁碎挤半个柠檬汁加柠檬片加鱼露浸泡半天即可。#'),(1428,'油酥烧饼','主食','面粉#\n酵母#\n糖粉#\n小苏打#\n盐#\n味精#\n鸡精#\n十三香#','250g#\n2.5g#\n7.5g#\n1g#\n2.5g#\n2.5g#\n2.5g#\n0.5g#','1. 250g面粉加150g水、2.5g酵母和7.5g的糖粉，搅拌均匀，附上一层保鲜膜静待面自行发起来。#\n2. 另取一干净容器，面粉加油、盐2.5g，鸡精2.5g，味精2.5g，十三香0.5g，做油酥，放一边待用。#\n3. 发面和油酥分别做成大小面团，发面团包裹油酥面团，卷起，折叠，做成长条形状放一边醒10分钟。#\n4. 醒好后，做成圆形。烤箱200度预热。#\n5. 烤盘铺油纸，烧饼放入烤盘，烧饼上刷一层油和芝麻，烤箱200度20分钟左右即可。#\n6. 新鲜的油酥烧饼出炉#'),(1429,'香糟春笋','素菜','春笋#\n糟卤#\n糖#','600g#\n300g#\n10g#','1. 春笋和香糟卤。#\n2. 春笋剥去笋壳切掉老根洗净。#\n3. 将笋切段，长度随意，我切的是6厘米左右。#\n4. 锅里水烧开放入春笋段，煮沸3分钟出锅。#\n5. 煮好的笋段出锅过凉水捞出沥干水分放入容器。#\n6. 糟卤很咸我喜欢调淡些带点甜味，300克糟卤加150克凉白开和糖搅拌匀到糖全部融化，倒入装笋的容器盖上盖浸泡30分钟就可以捞出吃了。泡时间越长笋会更咸，可以根据口味加减水量。可以放冰箱放，清凉爽口。剩下的糟卤汤煮开晾凉可以泡毛豆花生也是不错。#\n7. 糟卤笋装盘食用，简单爽口的小菜。#'),(1430,'黑鱼西红柿炖冻豆腐','荤菜','黑鱼#\n西红柿#\n大葱#\n蒜#\n姜#\n黑胡椒粉#\n薄荷#','一条#\n350g#\n一根#\n8颗#\n一块#\n少许#\n一颗#','1. 黑鱼去鳞去腮洗净切块 葱洗净切断 蒜去皮洗净备用 姜切片备用 冻豆腐切块 西红柿洗净热水烫一下，去掉皮后切块备用。#\n2. 热锅凉油，爆香葱姜蒜后放入西红柿炒出汁后把鱼倒入锅中，待鱼肉变白后，倒开水，放入切好的冻豆腐，大火烧开后，小火炖一个小时即可，出锅前撒适量盐，轻轻的搅拌均匀即可，盛到碗里后，在上面撒少许胡椒粉，最后放一颗薄荷点缀一下，夏天来点薄荷，让身体顿时凉爽一些。#'),(1431,'青椒炒牛肉','荤菜','蒜蓉#\n姜#','#\n#','1. 青椒切丝备用#\n2. 牛肉先用油拌一下放一分钟，这样牛肉比较滑，再放调味料，盐，蚝油，酱油，糖，粉，鸡精可放可不放，用油爆香蒜，姜再发牛肉爆炒，记得放一点点酒，肉更香哦！#\n3. 再加青椒爆炒一下，（我喜欢加糖，觉得食物加了糖才能把本身的味道煮出来），味道好极了，加少许水继续炒，这样就有汁了，青椒无需煮太久，太软就不好吃了哦，再加其他调味料盐，蚝油，酱油调味，完成上碟可以吃饭了咯#'),(1433,'干煸肥肠','荤菜','肥肠#\n洋葱#\n青椒#\n土豆#\n蒜#\n姜#\n干辣椒#','250g#\n1个#\n3个#\n1个#\n少许#\n少许#\n少许#','1. 准备好材料，肥肠一定要洗干净哦！#\n2. 先将肥肠爆炒，煸到比较干#\n3. 再放入青椒和洋葱，然后是土豆#\n4. 做好啦！最后只放一点盐即可！#'),(1434,'菇片鸡腿粥','荤菜','白粥#\n鸡腿#\n香菇#\n姜#\n葱#\n盐#','一锅#\n300克#\n150克#\n适量#\n适量#\n适量#','1. 煮一锅白粥#\n2. 斩好的鸡腿飞水：把鸡腿块跟姜和冷水一起煮开，再用冷水冲干净#\n3. 把鸡腿加入煮好的白粥，中火煮15分钟#\n4. 香菇加保鲜膜放微波炉大火转2分钟#\n5. 香菇切片放入粥中，煮沸后改小火15分钟#\n6. 加入细细的嫩姜丝跟葱碎、适量的盐调味就可以了#'),(1435,'香菇青菜','素菜','青菜#\n香菇#\n盐，胡椒粉，鸡精，蚝油#\n蒜#\n葱#\n干辣椒#','吃多少买多少#\n8朵#\n#\n2瓣#\n2根#\n3个#','1. 把香菇去蒂切片，青菜折成一片一片。锅里放水放一点盐滴一滴油水烧开，把青菜香菇在锅里过一下，这样青菜不会有苦味而且青菜颜色也很好看。捞出控水。#\n2. 蒜切片把葱白切段，干辣椒用剪刀剪段，葱叶切成葱花备用。#\n3. 在锅里放少许底油把蒜片葱白段，干辣椒一起放锅里炸香，（儿子喜欢吃姜我也切了些姜丝，可以不放姜丝）先放入香菇片翻炒，在放入青菜翻炒两下加盐，胡椒粉，蚝油少许一小勺吧，用少许凉水把蚝油拌开慢慢加入锅里翻炒，看菜熟了撒一点点鸡精翻炒撒葱花出锅。#'),(1436,'无油版菠菜鸡蛋汤','汤','菠菜#\n鸡蛋#\n盐、味精、水#','#\n#\n#','1. 材料很简单#\n2. 菠菜用水焯一下#\n3. 在水开后倒入打散的鸡蛋，用筷子搅合一下#\n4. 鸡蛋熟了就可以出锅了，不要煮老了，出锅前加盐和味精调味#'),(1437,'糖醋小排骨','荤菜','排骨#\n花椒#\n葱#\n姜#\n盐#\n香油#\n水淀粉#\n油#\n料酒#\n冰糖#\n老抽#','750克#\n适量#\n少许#\n少许#\n少许#\n少许#\n适量#\n适量#\n适量#\n少许#\n少许#','1. 将排骨剁成小段洗净，在电压力锅（普通压力锅也行）中加入水、葱姜、料酒、盐和排骨，将排骨煮熟捞起待用。#\n2. 将水、水淀粉、老抽、香油、醋调成碗汁。#\n3. 另起油锅，放入少量油，加入冰糖小火融化，倒入碗汁烧开，把煮熟的排骨倒入裹匀，再煮片刻即可。#'),(1438,'西红柿鸡蛋','素菜','西红柿#\n鸡蛋#\n大葱#','1个#\n两个#\n少许#','1. 西红柿1个洗干净切大小均匀的块，鸡蛋2个打散，打鸡蛋的时候可以加入少量的淸水，这样煎出的鸡蛋比较松软。热锅放油，油温五分热时倒入鸡蛋炒散，倒入切好的西红柿，放盐喜欢甜的朋友可以放少许的糖，最后放几片切好的葱片，ok出锅红黄绿很漂亮哦！（本人没有放鸡精，因为这道菜本身就很鲜，再一个给宝贝吃）#'),(1439,'葱爆大虾','荤菜','花椒#\n蒜#\n姜#\n干辣椒#','适量#\n适量#\n适量#\n3个#','1. 去超市买来新鲜的大虾#\n2. 把虾洗净，从背后切一刀，将虾线挑出来，放入一点点盐稍微腌一下#\n3. 准备大葱、姜、蒜适量，可根据自己的口味放#\n4. 将葱切成大段，姜蒜切末#\n5. 把虾用淀粉稍微裹一下，这样烧出了的虾很入味#\n6. 放油，将虾翻炒成金黄色，然后放入干辣椒、花椒若干颗、一半蒜末、姜和大葱，可根据喜好加一点点李锦记的蚝油，放入盐、酱油少量翻炒，适量加一点点水#\n7. 完成美味的葱爆大虾！( ▽｀)#'),(1440,'黄油烤鸡','荤菜','鸡#','一只#','1. 鸡洗净沥干后从腹部切开，记得不是背部哦，是肚子处，切开后将鸡压平，这种方法可以让鸡在一个小时以内烤熟。室温软化黄油，把手指轻轻插入鸡皮下，用手指轻轻的将黄油抹在鸡皮下（鸡皮和鸡肉直接，不要把皮捅破），尽量都抹到，抹均匀。#\n2. 鸡表面和翻面洒上一层薄盐，腌1个小时，然后两面抹上一层薄油，洒上新磨的黑胡椒，放入烤盘入烤箱，皮向上，350华氏度烤45分钟，因为烤箱火力不同，可以略长，但一小时内应该就熟了。#\n3. 配上一些配菜，就是一份晚餐啦。#'),(1441,'一锅端','不属于任何一类','面筋塞肉#\n亲亲肠#\n蟹肉棒#\n鲜虾脆#\n藕#\n莴苣#\n百页结#\n红黄小番茄#\n鲜香菇#\n胡椒粉#\n香油#','#\n#\n#\n#\n#\n#\n#\n#\n#\n少量#\n适量#','1. 把莴苣刨皮、藕刨皮洗净切段。百页结热水浸泡下捞起，香菇洗净弄些花纹。#\n2. 可以根据自家口味调节，比如，花菜、山药、芋艿、胡萝卜、白萝卜等，挑喜欢的菜放在一起乱烧，“炖”是要烧很久才叫炖。#\n3. 烧法：锅中放大半锅水，面筋放入，盖锅，滚后放百页结、藕段烧滚，放亲亲肠，鲜虾脆、香菇烧滚放盐、莴苣，关火，放蟹肉棒、红黄番茄加胡椒粉，香油。正好家里还有肉片，所以放在油锅中煸炒下也放进去烧了。#\n4. 烧这一锅端有先后顺序，不然有的太烂不好吃，蟹肉棒是不可烧，放入马上盛岀吃。鸡精可根据自家口味放。#'),(1442,'可乐鸡翅','荤菜','鸡翅（翅根，中翅都行）#\n250mL可乐#\n料酒（我家没料酒用白酒代替 ）#\n生姜#','#\n一瓶#\n#\n#','1. 鸡翅先用小刀横划几刀，再少许盐腌一小时，生姜切丝备用#\n2. 锅烧热放少量油，放入生姜、鸡翅和料酒，翻炒至鸡翅变色，油一定不能放多，如果油多了，在倒入可乐之前可以把油给倒出来。#\n3. 鸡翅炒变色后倒入一瓶可乐，盖上锅盖用中火炖#\n4. 可乐变少后，要一直不停地翻炒，直至全部汁都挂在鸡翅上#\n5. 最后宝宝最爱的香香甜甜的可乐就可以上桌了#'),(1443,'脑花豆腐','荤菜','水豆腐#\n脑花#\n大葱#\n生姜#\n豆瓣海椒#\n花椒#','两块#\n两幅#\n一根#\n5片#\n一勺#\n一把#','1. 豆腐切成块状。#\n2. 到下锅煮2-3分钟，收水#\n3. 材料备好#\n4. 多倒一些油，然后加一小勺盐来煎#\n5. 把大葱、花椒、豆瓣海椒加进去煎，煎好后捞出来丢掉，只剩油#\n6. 丢入豆腐和脑花煮6-8分钟，脑花煮好即可#\n7. 最后撒一层花椒面就好了～超好吃#'),(1444,'奶香香草土豆泥','甜品','土豆#\n牛奶#\n盐#\n香草#\n黑胡椒粉#','200g#\n半瓶#\n少许#\n少许#\n少许#','1. 小土豆洗净  电压锅放少量水#\n2. 电压锅按豆子按钮#\n3. 好  土豆都爆皮了  用棍子轻轻能穿过#\n4. 放凉了  土豆剥皮  用打蛋器压烂土豆成泥#\n5. 土豆泥加入牛奶#\n6. 好  土豆泥打到没颗粒  感觉香浓滑滑的#\n7. 加入少许#\n8. 加少许黑椒粉  最后加入香草叶  搅拌均匀#\n9. 好咯  香浓土豆泥有淡淡奶味 清新香草味#\n10. 香滑可口#'),(1445,'黑胡椒杏鲍菇','素菜','杏鲍菇#\n盐，黑胡椒，姜片。#','够吃#\n少许#','1. 杏鲍菇加黑胡椒，切好吧。方形，圆形长方形，你随意。#\n2. 煸姜片，出味道。#\n3. 加杏鲍菇煸干就行。#\n4. 好了，撒点黑胡椒，盐，起锅吧。简单吧零厨艺的事情#'),(1446,'香炒龙虾','荤菜','龙虾#\n葱，#\n大料#\n油#\n丁香#\n桂皮#\n辣椒#\n盐#\n糖#\n生抽#\n老抽#\n料酒#\n姜#\n蒜#','若干#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 处理好龙虾，用小刷子一一洗净，备用！#\n2. 准备好葱姜蒜，大料，桂皮，丁香，辣椒#\n3. 热油后，加入姜蒜，煸香后加入大料，丁香，桂皮，辣椒翻炒！#\n4. 加入龙虾翻炒若干下后，加入葱，生抽，少许老抽，翻炒，再加入料酒，少许糖去腥提鲜，加少许水！#\n5. 加盖，两三分钟后出锅，美味的龙虾来了！#'),(1448,'家常小菜--通菜梗煸肉','荤菜','五花肉丁#\n通心菜梗#','一大勺#\n一把#','1. 通心菜梗洗净，横切碎，五花肉切成筷头大小的肉碎。#\n2. 热油爆炒肉碎，煸出油，放一点老抽，炒匀，喜欢辣的，可以放把辣椒碎，倒入通心菜碎，不断翻炒至熟，调入盐味精。#'),(1449,'傻瓜！红烧土豆（识字就会，美味）','素菜','土豆#\n盐#\n糖#\n生抽#','中等个头四个#\n少许#\n两勺#\n少许#','1. 土豆洗净切小块#\n2. 锅底铺满油，中火油热后加入土豆煎至金黄，加盐（平时做菜的量）加糖（比例大约1:2）试味后入水，加酱油微调色，收汁即可。#\n3. 油可以多放一些，味道给足之后加水没过土豆多煮会儿入味，香极了！#'),(1450,'鲫鱼豆腐汤','汤','鲫鱼#\n豆腐#','一条#\n一块#','1. 菜市场买活鲫鱼一条，现场宰杀收拾好回家简单冲洗下就可以了#\n2. 选用不粘平底锅加比平时炒菜多点的油，大概七八成热的时候放入鲫鱼，中大火煎鱼。其间不可用铲子铲来铲去，否则鱼皮就都掉了。煎五分钟左右，轻轻摆动锅子鱼可以轻松滑动就证明煎好了，把鱼翻个面继续煎。#\n3. 另起砂锅加水，姜片，葱段，豆腐大火烧开。放入煎好的鲫鱼，大火煮沸后转小火。#\n4. 一般二十分钟后汤水即可呈奶白色，一个小时后汤水最为香浓，依各人口味加入盐和白胡椒~#'),(1451,'孜香西葫芦炒蛋','素菜','西葫芦，#\n泡发的木耳#\n鸡蛋#\n培根#\n红椒#\n盐#\n香葱#\n孜然粒#\n生抽#','一根#\n50克#\n2个#\n100克#\n一个#\n1.5茶匙#\n一根#\n2茶匙#\n2汤匙#','1. 西葫芦切片，红椒切块，培根切断儿，小香葱切碎断儿。#\n2. 锅上火，放入培根片煎至透明盛出备用。#\n3. 鸡蛋打散，放少许盐搅拌均匀。#\n4. 锅内放油，油热后加入蛋液，炒至熟时盛出备用。#\n5. 锅内放油，热后加蒜、葱花爆香，加入西葫芦片，大火翻炒1—2分钟，加入培根、木耳、红椒翻炒两分钟后加入生抽调味，然后加入鸡蛋炒匀，最后加入孜然粒和盐大火炒半分钟即可。#'),(1452,'重庆麻辣小龙虾','荤菜','田园小龙虾#\n辣椒#\n花椒#\n老姜#\n大蒜#\n盐#\n糖#','#\n1两#\n10克#\n5克#\n10克#\n3克#\n3克#','1. 龙虾去头，去脏腑，洗净沥干#\n2. 龙虾码盐10分钟，待用#\n3. 辣椒，姜，蒜，切碎，备用#\n4. 热油爆炒龙虾5分钟，沥出龙虾#\n5. 锅里的油加温去水分，倒入姜，葱，蒜，爆炒30秒，加入龙虾拌炒，加入味精，糖#\n6. 起锅，装盘即可#'),(1453,'请客上台盘的菜———开背虾蒸粉丝','荤菜','葱#\n姜#\n蒜#','#\n#\n#','1. 食材：基围虾，己泡发好的粉丝，葱姜蒜。#\n2. 葱姜蒜切末。#\n3. 在虾头处挤去脏泥，再虾背切开。#\n4. 粉丝放入盆中(最好大一些的盆)#\n5. 虾码在粉丝上。#\n6. 准备好调料。#\n7. 热锅热油关火倒入葱姜蒜。#\n8. 倒入蒸鱼豉油，开火烧开。#\n9. 浇在码好的虾上，放蒸锅大火蒸十分钟即可开吃。#'),(211658,'清凉系列:草莓布丁','甜品','七式草莓布丁粉#\n细砂糖#','100g#\n30g#','1. 准备材料#\n2. 称100g粉，30g糖，600g水烧开。搅拌均匀#\n3. 放入容器，冰箱#\n4. 20分钟就可以吃了#\n5. 糖可以少一点#'),(246176,'三菇烩豆腐','素菜','金针菇#\n北豆腐#\n鲍鱼汁#\n蚝油#','100g#\n1块（或油豆腐）#\n2汤匙#\n2汤匙#','1. 香菇、金针菇、蘑菇洗净，豆腐切成片待用。#\n2. 锅中油烧至七成热，放入豆腐用中火煎。#\n3. 煎成两面呈金黄色；如果用油豆腐这道步骤就省去了。#\n4. 倒出多余的油，放入三种蘑菇翻炒。#\n5. 炒至蘑菇变软。#\n6. 加入鲍鱼汁、蚝油和少量的水，用中火焖10分钟即可出锅。#'),(246185,'芋圆红豆汤','甜品','紫薯#\n芋头#\n牛奶#\n红豆#\n白砂糖#','2个#\n适量#\n一盒#\n适量#\n适量#','1. 将南瓜紫薯芋头切片蒸熟 筷子能捣开即可#\n2. 分别捣成泥 最好放进保鲜袋中手捏(>_<)#\n3. 加入山芋粉 牛奶 糖（多放点好吃）#\n4. 揉成不黏手的面团即可#\n5. 红豆汤单独煮 将芋圆大火煮开 然后小火多煮一会#\n6. 揉成条状 切丁 开始搓橡皮泥啦！#\n7. 加入红豆汤就好啦！#'),(246316,'家常版潮汕砂锅粥','主食','姜末#\n胡椒粉#\n盐#','少许#\n少许#\n少许#','1. 大米淘洗后泡半小时#\n2. 虾子背部切开，取走虾线，可剪掉虾须，备用#\n3. 砂锅一次性加够水，开锅后下米，拿掉盖子，不时搅拌#\n4. 米爆开后煮一会儿，最后十分钟放虾子，姜末，也可放海米，我不喜欢就没放，大约十分钟关火，盖盖子闷一会儿#\n5. 加少许盐和胡椒粉，出锅。。。鲜得翻过去#'),(246335,'超简单的花生牛轧糖（棉花糖版）','甜品','原味棉花糖（白色）#\n奶粉#\n花生#\n黄油#','240g#\n200g#\n250g#\n45g#','1. 不粘锅放入黄油 小火化开#\n2. 黄油全化开后 加入棉花糖 小火搅拌棉花糖软化#\n3. 棉花糖软化后 关火加入奶粉快速搅拌 加入花生碎搅拌#\n4. 放入磨具 用擀面杖压平 凉后用刀切长条 再切块#\n5. 切小块 包上包装纸即可#\n6. 完成#'),(248241,'爆炒牛肉丝','荤菜','牛肉#\n青椒#\n小米辣#\n仔姜#\n大蒜#\n老姜#\n葱段#\n胡椒粉#\n淀粉#','300g#\n#\n#\n#\n#\n#\n#\n#\n#','1. 牛肉切丝，加入料酒，淀粉，盐，胡椒粉，腌制半小时左右#\n2. 辣椒，仔姜，切丝备用#\n3. 蒜，老姜，葱段，切好备用。放少许油，加热，放入姜蒜，爆香。#\n4. 将倒牛肉丝，加少许豆瓣炒至肉丝变色。依次加入，仔姜丝，红辣椒，青辣椒。最后调味出锅#'),(248306,'蜜汁烤翅根','荤菜','鸡翅根#\n蜜汁烤鸡翅料#\n橄榄油#\n水#\n蜂蜜#','16个#\n60克#\n45毫升#\n70克#\n60毫升#','1. 鸡翅根洗净，沥干水分。用刀在翅根的两侧，各划两刀，以便腌制时更入味。烤鸡料倒入碗中，调入水，搅拌均匀。#\n2. 将翅根放入容器中，倒入调好的料汁，充分搅拌均匀。再加入橄榄油，继续搅拌均匀，盖上保鲜膜，放入冰箱冷藏腌制24小时或48小时。#\n3. 烤盘上铺上锡纸，烤箱预热至220度。将腌好的鸡翅根放在烤网上，刷上薄薄一层蜂蜜。#\n4. 烤盘放在烤箱的最底层，烤网放烤箱中层，烤15分钟后取出，翻面，再刷上一层薄薄的蜂蜜，将烤网移至烤箱最上层，再烤15分钟即可。#'),(249381,'豌豆黄','甜品','豌豆#\n白糖#\n碱#\n琼脂#\n清水#','500克#\n300克#\n1克#\n10克#\n1250克#','1. 琼脂洗净泡透，加入250克清水，蒸化过罗备用。#\n2. 豌豆加碱、水煮透，磨成渣，去皮。将其放入锅中加入白糖拌匀，上火烧沸，不停地铲动，使其勿粘锅底。#\n3. 炒至水分蒸发时，将琼脂倒入锅中，再炒片刻即成豆泥。#\n4. 将炒好的豌豆泥倒入长方形盘内冷却（上面盖一张油纸以免表面结皮裂口）。放在通风出处，凉透后放入冰箱冷藏。上桌时切块即可。#'),(249468,'养生春笋','素菜','春笋片#\n猪肉丝#\n青椒丝#\n红椒丝#\n黄菊花#\n枸杞#\n薄荷#\n水淀粉#\n葱油#\n盐#\n鸡精#','500g#\n250g#\n50g#\n50g#\n1支#\n50g#\n20g#\n30ml#\n20ml#\n1勺#\n半勺#','1. 干锅加热，向锅内倒入少量葱油待油烧热后将肉丝倒入锅中摊开翻炒即可#\n2. 待肉丝炒熟后放入青椒丝和红椒丝，稍微翻炒一下即可放入春笋，然后开大火翻炒#\n3. 待春笋炒熟后，放入泡好的枸杞和汤汁#\n4. 放入少许盐和鸡精继续翻炒，最后加入少许水淀粉，稍微翻炒一下即可关火#\n5. 将准备好的黄菊花将花瓣取下，并清洗干净#\n6. 将洗净的黄菊花瓣放入锅中，用锅内余温翻炒两下即可装盘#'),(250275,'韩式泡菜锅','荤菜','培根#\n老豆腐#\n白洋葱#\n蘑菇#\n韩国辣白菜#\n葱白#\n是拉差香甜辣酱#\n柴鱼花#\n芫荽#\n高汤#','#\n#\n#\n#\n#\n#\n#\n#\n#\n#','1. 青口洗净，培根、老豆腐、白洋葱、蘑菇、葱白切成合适大小；#\n2. 韩国辣白菜稍稍切小块；#\n3. 锅里加适量橄榄油烧热，倒入洋葱、培根、葱白煸出香味，倒入韩国辣白菜继续煸炒2分钟左右；#\n4. 加入除海鲜以外其它所有的料，继续焖煮15-20分钟；#\n5. 加入海鲜煮至青口开口，加少许黑胡椒、盐调味；#\n6. 起锅前加入芫荽即可。#'),(251136,'清炒西芹','素菜','西芹#\n油、盐、味精、耗油#','3根#\n适量#','1. 西芹洗净切片，放入热水中焯一下水#\n2. 锅中倒入油，加入蒜头#\n3. 油热后放入西芹翻炒。#\n4. 炒的时候加些水#\n5. 炒差不多后加入耗油、盐继续翻炒一下，加入味精翻炒下。关火装盘。#\n6. 完成#'),(251152,'烤肉酱鸡胸肉','荤菜','鸡胸肉#\n烤肉酱#\n料酒#\n芡粉#','两块#\n适量#\n少许#\n少许#','1. 鸡胸肉解冻洗净后沥干水分#\n2. 鸡胸肉切约一厘米厚的片#\n3. 少许料酒、芡粉，适量烤肉酱与鸡胸肉和匀，包上保鲜膜放冰箱腌制半小时以上#\n4. 平底锅倒少许油，中小火慢煎鸡胸肉直至鸡肉熟透#\n5. 切小块装盘#'),(251197,'土豆烧素丸#酱香鲜#','素菜','土豆#\n菠菜丸、香菇丸#\n花椒，葱花#\n味事达酱香鲜酱油#\n盐#','三个#\n200g#\n适量#\n一勺#\n适量#','1. 土豆去皮洗净，切滚刀块#\n2. 丸子从冰箱中取出，可以切半，容易熟#\n3. 酱油亮相#\n4. 锅内热油，加入葱花，花椒炒香#\n5. 加入土豆，调入适量盐，加入味事达酱油#\n6. 加入丸子，翻炒均匀#\n7. 加入开水，没过土豆#\n8. 大火煮开，转中火，烧制汤汁收干即可#'),(251253,'辅食之南瓜米糊','甜品','南瓜#','#','1. 南瓜切小块蒸熟，压成泥。#\n2. 南瓜泥加入做好的婴儿米粉里即可。#'),(251295,'早餐系列—香蕉吐司卷','主食','吐司片#\n香蕉#\n鸡蛋#\n寿司帘#','2片#\n2根#\n1颗#\n#','1. 吐司切边备用，鸡蛋打散备用，香蕉切成与寿司帘合适的长度备用。#\n2. 将吐司放在寿司帘上，香蕉放在吐司上，方法与卷寿司一样，紧握起来即可。#\n3. 将卷好的吐司卷包裹蛋液。#\n4. 取平底锅入油，油热后放入裹着蛋液的吐司卷，煎一下（小心不要煎过头）。#\n5. 煎好后切成小段即可。#'),(251400,'花生酥','甜品','中筋面粉#\n碎花生仁#\n白砂糖#\n玉米油#\n鸡蛋#\n芝麻#','300g#\n55g#\n50g#\n50g#\n1个#\n适量#','1. 将玉米油，白砂糖，鸡蛋液搅拌均匀即可，顺带留出少量的蛋液备用。#\n2. 将面粉分次加入搅拌好的蛋液中，待揉至不粘手后，加入花生碎，揉进面里。#\n3. 然后揉成长条状，切成同等大小的面团，然后将其搓圆，稍微压扁，在其表面刷上蛋液，撒上芝麻。#\n4. 摆好后，放入事先预热好的烤箱中，180度20分钟（烤箱温度根据实际情况决定）。#'),(251477,'金橘醋','不属于任何一类','新鲜金桔#\n黄冰糖#\n醯官醋纯酿原浆米醋#','300g#\n300g#\n500ml#','1. 1、新鲜金橘洗净外皮后自然风干。#\n2. 2、对半切开后放入密封瓶中，洒入黄冰糖。??#\n3. 3、倒入原浆米醋完全浸泡即可#'),(251500,'卤水猪舌和猪肝','荤菜','猪舌#\n猪肝#\n盐#\n姜#\n葱#\n料酒#\n卤水#','一只#\n#\n适量#\n适量#\n适量#\n少量#\n适量#','1. 先把猪舌和猪干清洗下，再放锅中焯水。#\n2. 捞岀放凉水冲洗，用小刀把猪舌上的一层膜刮掉，用盐捏洗猪舌。猪肝冲洗即可。#\n3. 用叉在猪舌和猪肝扎些小洞。#\n4. 猪舌猪肝重新加水放进锅中烧，放姜，葱，滚后放料酒，中火烧40分。#\n5. 另用一只锅，放卤水再加些水放煤气灶上烧滚(因我家吃的清淡才加水，如你口味偏咸就不用加)#\n6. 把烧好的猪舌和猪肝浸泡在卤水中，等凉了再放冰箱，待明天吃时再切装盘。#'),(251886,'川味辣子鸡','荤菜','鸡肉块#\n干辣椒#\n花椒#\n葱#\n姜#\n蒜#\n盐#\n胡椒粉#\n白芝麻#\n酱油#','200g#\n30g#\n1碗#\n适量#\n适量#\n适量#\n适量#\n少量#\n1勺#\n1勺#','1. 鸡肉块，洗干净，放盐腌制15分钟#\n2. 炸鸡肉块，先小火炸，大概8分钟鸡肉就熟了。再开大火炸，让其上色，就OK了。#\n3. 鸡肉捞出来，控干油。#\n4. 花椒，干辣椒，先用水泡一下，然后切一小段一小段。#\n5. 葱切段，蒜切片，姜切丝#\n6. 热锅热油，放入葱姜蒜小火爆香#\n7. 放入花椒，小火爆香。#\n8. 放入干辣椒，小火哦。#\n9. 放入鸡肉块，迅速翻炒#\n10. 放入酱油，盐，胡椒粉翻炒均匀。#\n11. 放入白芝麻，翻炒均匀就OK了。#\n12. OK啦#\n13.#\n14. 成品！#'),(252179,'油炸肉丸子','荤菜','猪肉#\n山药#\n鸡蛋#\n香葱#\n生姜#\n生抽#\n料酒#\n盐#\n淀粉#\n油#\n糖（也可不加）#\n黑胡椒粉#','500g#\n适量#\n1个#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 猪肉用料理机搅成末（或者用刀剁），加入山药泥，姜末，香葱，盐，生抽，料酒#\n2. 用筷子或者打蛋器搅拌均匀，直到肉馅上劲成糊状#\n3. 加入鸡蛋#\n4. 加人淀粉，搅拌均匀#\n5. 用手抓起肉馅往盆里摔,摔100次左右#\n6. 热锅倒入适量的油，烧到7成热，可挤一肉丸试一下#\n7. 用左手虎口挤出肉丸，勺子挖下，放入油锅#\n8. 调小火炸至肉丸金黄#\n9. 装盘出锅#\n10. 来张切面的#'),(252522,'自制麻辣香锅','荤菜','藕#\n木耳#\n五花肉#\n黄瓜#\n青蒜#\n洋葱#\n烤鱼底料#','半节#\n一小捧#\n二两#\n一根#\n少许#\n少许#\n#','1. 准备好各种食材，您爱吃的#\n2. 木耳，藕片，焯水。其他食材改刀，切好！#\n3. 烤鱼料下锅，加入洋葱，青蒜，炝锅。之后下入五花肉，变色后放入藕，木耳，黄瓜。#\n4. 翻炒片刻，淋入香油，出锅#'),(275861,'桂花桃胶皂角米炖燕窝','甜品','燕窝#\n桃胶#\n皂角米#\n冰糖#\n干桂花#','3-5g#\n5-8粒#\n5-8粒#\n适量#\n2茶匙#','1. 燕窝、皂角米、桃胶放入清水中浸泡一晚。天热的话最好放进冰箱冷藏。#\n2. 将泡发好的皂角米、桃胶、燕窝清洗后放入炖盅，2茶匙干桂花、水，隔水炖40分-1小时（喜欢比较Q弹的口感就少炖一会，软糯的多炖一会），出锅前10分钟放冰糖，待冰糖完全融化后出锅。#\n3. 一碗营养美味的甜品完成！#\n4. 吃上一口，Q弹爽滑，伴着淡淡的桂花香，满足。#'),(275919,'饭后甜品～芒果','甜品','牛奶#\n白糖#','#\n#','1. 将芒果切丁，可如图这样切，备好#\n2. 打两三个鸡蛋，把蛋清和蛋黄分开，往蛋清里放点糖打化了再倒入牛奶，用保鲜膜包好，扎几个洞#\n3. 上锅蒸十分钟左右，再关火焖会#\n4. 拿起去掉保鲜膜放入芒果，最后放入冷藏，等要吃的时候再拿出来#'),(276224,'【超健康减肥圣汤】菌菇肉丸毛菜豆腐汤','汤','各类菌菇#\n猪肉糜#\n鸡毛菜#\n内酯豆腐#\n盐#\n麻油#\n酱油#\n料酒#\n小葱#','500g#\n250g#\n1把#\n半块#\n1小勺#\n1小勺#\n1小勺#\n1小勺#\n1根#','1. 猪肉糜加料酒、葱末、盐、酱油拌匀#\n2. 菌菇洗净 改刀成小块 鸡毛菜洗净 豆腐泡水洗净 改刀成小立方体#\n3. 水加姜片和一根整葱烧开 加适量料酒 入小肉丸 烧开撇去泡沫至汤清#\n4. 炖大约10分钟 去掉葱姜 入菌菇#\n5. 再炖10分钟左右入豆腐#\n6. 再再炖10分钟 入鸡毛菜#\n7. 加盐调味 等到鸡毛菜更绿了 差不多5分钟 就可以加一小勺麻油 开动咯～#'),(276259,'雅客茶拌','不属于任何一类','去脂奶粉#\n植脂末#\n法式香草味植脂末#\n白糖#\n雅客巴经典锡兰茶#\n姜粉#\n肉桂粉#\n丁香粉#\n小豆蔻粉#','1杯#\n1杯#\n1杯#\n1/2杯#\n1/2 杯#\n2 茶匙#\n2茶匙#\n1 茶匙#\n1 茶匙#','1. 在一只大碗内加入奶粉、植脂末、香草植脂末、糖和煮好的雅客巴经典锡兰茶并混合。#\n2. 将混合后的茶倒入搅拌器或料理机，加入姜粉（生姜亦可），肉桂粉，丁香粉和小豆蔻粉，搅拌至液体呈稳定均匀状态，每次搅拌一杯。#\n3. 食用方法：需要食用时，将2堆勺搅拌好的茶拌加入一大杯热水即可。#'),(276911,'自制泡菜','素菜','白萝卜#\n胡萝卜#\n芹菜#\n小米辣#\n小红椒#','#\n#\n#\n#\n#','1. 将白萝卜 胡萝卜 芹菜 切块； 然后和小米辣 小红椒 一起放进密封灌里；搁上白醋和少量水 泡1---2天 即可#'),(278297,'波萝虾羔牛肉饭','荤菜','波萝#\n牛肉#\n虾羔#\n米饭#\n红葱头#\n红辣椒#\n碗豆#\n姜#\n葱#\n糖#\n盐#\n蚝油#\n老抽#\n生粉#\n胡椒粉#','一个#\n一块#\n两小片#\n两碗#\n三个#\n少许#\n少许#\n少许#\n两条#\n适量#\n适量#\n适量#\n适量#\n适量#\n适量#','1. 波萝去皮切成小粒，用盐水泡一会，再沥干水分#\n2. 牛肉粒，用生粉、糖、蚝油、老抽,胡椒粉腌味一小时以上#\n3. 虾羔切片，压碎，红辣椒切粒，姜切成末，红葱头切片，葱切成葱花#\n4. 锅里放油烧热，牛肉过一下油捞出待用#\n5. 锅里再放油，放姜末，红葱头，爆香，跟着碗豆，红辣椒炒一会，拔开在锅边，再放入虾羔在一边爆香，洒入少许料酒炒匀，放米饭，转大火炒匀，放少许糖炒匀，多炒一会，米饭均匀的沾上虾羔的味#\n6. 饭炒差不多后，倒入牛肉，接着放波萝，炒一会，放葱花炒匀即可出锅#');
