--
-- Table structure for table `recipe_records`
--

DROP TABLE IF EXISTS `recipe_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recipe_records` (
  `ID` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `USER_ID` bigint NOT NULL COMMENT '用户ID',
  `RECORD_DATE` date NOT NULL COMMENT '记录日期',
  `MEAL_TYPE` varchar(20) NOT NULL COMMENT '餐次类型：breakfast/lunch/dinner',
  `RECIPE_NAME` varchar(200) NOT NULL COMMENT '菜谱名称',
  `DISH_IDS` text COMMENT '菜品ID列表，JSON格式',
  `IS_MANUAL` tinyint(1) DEFAULT '0' COMMENT '是否手动输入：0-推荐菜谱，1-手动输入',
  `CREATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `UPDATE_TIME` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`ID`),
  KEY `idx_user_date` (`USER_ID`,`RECORD_DATE`),
  KEY `idx_user_meal` (`USER_ID`,`MEAL_TYPE`),
  KEY `idx_date` (`RECORD_DATE`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='菜谱记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

